COLLDATA("nasai","ur",[[5017,"انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اس ذات کی قسم، جس کے ہاتھ میں محمد صلی اللہ علیہ وسلم کی جان ہے! تم میں سے کوئی مومن نہیں ہو سکتا جب تک کہ اپنے بھائی کے لیے وہی بھلائی نہ چاہے جو اپنے لیے چاہتا ہے\"۔","الألباني: صحيح",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’قسم اس ذات کی جس کے ہاتھ میں محمد (صلی اللہ علیہ وسلم)کی جان ہے!تم میں سے کوئی شخص (اس وقت تک)مومن نہیں ہوسکتا جب تک وہ اپنے (ہرمسلمان)بھائی کے لیے اسی طرح خیروبھلائی پسند نہ کرے جس طرح اپنے لیے کرتا ہے۔،،","f2":"خیر وبھلائی سے دنیا وعقبیٰ کی ہر خیر وبھلائی مراد ہے،طاعات سے لے کر جنت تک۔"}],[5018,"علی رضی اللہ عنہ کہتے ہیں کہ نبی امّی صلی اللہ علیہ وسلم نے سے مجھ سے عہد کیا کہ \"تم سے صرف مومن ہی محبت کرے گا، اور تم سے صرف منافق ہی بغض رکھے اور نفرت کرے گا\"۔","الألباني: صحيح",{"u2":"حضرت زر(بن حبیش) سے روایت ہے کہ سیدنا علی رضی اللہ عنہ نےفرمایا:نبی امی صلی اللہ علیہ وسلممجھے ارشاد فرمایا کرتے تھے کہ تجھ سے مومن ہی محبت کرےگا اور تجھ سےمنافق ہی بغض رکھے گا۔","f2":"(1)’’نبی امی،،امی آپ کا وہ عظیم وصف ہے جو پہلی کتابوں میں بھی مرقوم تھا۔ امی نسبت ہے ام القریٰ(مکہ) کی طرف جو آپ کا مولد ومسکن تھا اور جہاں آپ کو نبوت ورسالت کے عہد وجلیلہ پر فائز کیا گیا۔ یایہ نسبت ہے ام (ماں)کیطرف کہ آپ کسی سکول ومکتب سے نہیں پڑھے اور نہ کسی استاد کےسامنے زانوئے تلمذ تہہ کیا بلکہ آپ کا تر بیت کنندہ،فیض رساں اور علم بخشنے والا صرف آپ کا رب جلیل وعظیم ہی ہے اور یہ بہت عظمت والی بات ہے اور عظیم معجزہ بھی آپ نےکسی سے پڑھے بغیر دنیا کو علم سے منور فرمایا۔ اور آپ کے شاگرد جہان کے معلم بنے۔ صلی اللہ علیہ وسلم۔\n(2)’’مومن ہوگا،،بشرطیکہ اس کی محبت کی بنا یہ ہو کہ سیدنا علی رضی اللہ عنہ ابن عم رسول تھے۔آپ پر ابتدائی اسلام لانےوالے تھے۔ساری زندگی آپ کے جاں نثار ہے۔ سب جنگوں میں شرکت کی۔پھر آپ کے اولاد بننے کاشرف حاصل کیا۔ چوتھے خلیفہ بنے۔اگر کوئی شخص کسی ذاتی تعلق کی بناپر ان سے محبت کرتا ہےوہ اس خوش خبر ی کے تحت نہیں آئےگا۔\n(3)’’منافق ہوگا،، بشرطیکہ اس کا سیدنا علی رضی اللہ عنہ سے بغض آپ کی ان خصوصیات کی بنا پر ہی ہو جن کا ذکر اوپر ہوا۔ اگر کسی ذاتی جھگڑے کی بنا پر ناراضی ہوتو وہ اس وعید کے تحت نہیں آئےگا۔"}],[5019,"انس رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"انصار سے محبت ایمان کی نشانی ہے، اور انصار سے نفرت نفاق کی نشانی ہے\"۔","الألباني: صحيح",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے نبی اکرم صلی اللہ علیہ وسلم نےفرمایا:’’انصار سےمحبت ایمان کی نشانی ہے اور انصار سے بغض نفاق کی نشانی ہے۔،،","f2":"’’نشانی ہے،،لیکن یہ تب ہے جب انصار سے محبت یا بغض ان کے انصار (مدد گار نبی)ہونے کی وجہ سے ہو۔اگر کسی تعلق کی وجہ سے محبت ہو یا کسی جھگڑے کی بنا پر ان سے ناراضی ہوتو وہ اس حدیث کے تحت داخل نہیں کیونکہ ان کانام انصار،رسول اکرم صلی اللہ علیہ وسلم کی مدد نصرت کی بنا پر رکھا گیا ورنہ تو وہ اوس اور خزرج تھے۔"}],[5020,"عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس میں چار چیزیں ہوں، وہ منافق ہے، یا ان چار میں سے کوئی ایک خصلت(عادت) ہو تو اس میں نفاق کی ایک خصلت ہے جب تک کہ وہ اسے چھوڑ نہ دے: جب بات کرے تو جھوٹ بولے، وعدہ کرے تو وعدہ خلافی کرے، عہد و پیمان کرے تو توڑ دے، اور جب جھگڑا کرے تو گالی گلوچ کرے\"۔","الألباني: صحيح",{"u2":"سیدنا عبد اللہ بن عمر و رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلمنےفرمایا: ’’چار خصلتیں ایسی ہیں کہ جس شخص میں (سب کی سب)پائی جائیں،وہ (خالص) منافق ہوگا اور جس شخث میں ان چار میں سے کوئی ایک پائی جائے، اس میں نفاق کی ایک خصلت ہوگی حتیٰ کہ وہ اسے چھوڑ دے:٭ جب بات کرے تو جھوٹ بولے۔٭جب وعدہ کرے تو خلاف ورزی کرے۔٭جب عہد کرے تو خلاف ورزی کرے۔٭جب عہد کرے تو بے وفائی کرے۔ ٭جب لڑائی کرے تو گالی بکے۔،،","f2":"(1)حدیث سے ثابت ہوتاہے کہ ایک مسلمان شخص کو اخلاق رزیلہ سے اجتناب کرنا چاہیئے بالخصوص وہ برے اعمال جن کاحدیث میں ذکر ہواہے،چیزیں عملی نفاق کو مستلزم ہیں جو تقاضائے ایمان کے باکل منافی ہیں۔قرآن وحدیث میں کچھ اور علامات نفاق بھی مذکور ہیں،مثلا:نماز میں سستی کرنا، دکھلادے کی عبادت کرنا،دینی معاملات میں تذبذب کاشکار ہوتا نیز ذاتی مفادات ہی کو پیش نظر رکھنا وغیرہ،تاہم اس حدیث مبارکہ میں بطور خاص جن چار چیزوں کا ذکر کیا گیاہے ان کاتعلق لوگوں کےعام باہمی معاملات سے ہے اور عموما انھی معاملات میں اتار چڑھاؤ باہمی اختلاف وفساد کا سبب بنتا ہے،اس لیے شریعت مطہرہ نے ان علامات کو نمایا ں طور پر ذکر کیا ہے۔واللہ اعلم .\n(2)یہاں منافق سے اعتقادی منافق مراد نہیں کہ اسے دائرہ اسلام ہی سے خارج قرار دے دیا جائے کیونکہ اس (اعتقادی منافق)کا علم وحی کے بغیر نہیں ہوسکتا،بلکہ اس سے عملی منافق مراد ہے،یعنی جس کے کام منافقوں جیسے ہوں۔اور یہ کام واقعی منافقوں کے ہیں۔مطلب یہ کہ ایسا شخص عملی منافق ہوتاہے،نیز یہ اس وقت ہےجب یہ خصلتیں اس میں بختہ ہوں اور وہ ان کا عادی بن جائے یعنی جب بھی بات کرے،جھوٹ ہی بولے۔جب بھی وعدہ کرے،خلاف ورزی ہی کرے۔جب بھی عہد کرے،تو ڑدے وغیرہ کیونکہ کبھی کبھار جھوٹ یا وعدہ خلافی یا گالی گلوچ تو ہر ایک سے ہوسکتے ہیں۔ اتنے سے کسی کو منافق نہیں کہا جائے گا۔"}],[5021,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"نفاق کی تین علامتیں (نشانیاں) ہیں: جب بات کرے تو جھوٹ بولے، جب وعدہ کرے تو وعدہ خلافی کرے اور جب امین بنایا جائے تو خیانت کرے\"۔","الألباني: صحيح",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’منافق کی نشانیاں تین ہیں:جب باترکرے،جھوٹ بولے۔جب وعدہ کرے تو خلاف ورزی کرے۔ جب اس کے پاس امانت رکھی جائے توخیانت کرے۔،،"}],[5022,"علی رضی اللہ عنہ کہتے ہیں کہ مجھ سے رسول اللہ صلی اللہ علیہ وسلم نے عہد کیا کہ \"مجھ سے محبت صرف مومن کرے گا، اور مجھ سے بغض و نفرت صرف منافق کرے گا\"۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ سے روایت ہے،انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نےمجھے ارشاد فرمایاتھا کہ تجھ سے مومن ہی محبت کرے گا اور تجھ سےمنافق ہی بغض رکھے گا۔"}],[5023,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ تین باتیں جس شخص میں ہوں، وہ منافق ہے: جب بات چیت کرے تو جھوٹ بولے، جب امین بنایا جائے تو خیانت کرے، جب وعدہ کرے تو وعدہ خلافی کرے، اور جس شخص میں ان میں سے کوئی ایک عادت ہو تو اس میں نفاق کی ایک عادت ہے یہاں تک کہ وہ اسے چھوڑ دے۔","الألباني: صحيح الإسناد موقوف",{"u2":"سیدنا عبداللہ بن مسعود رضی اللہ عنہ سےفرمایا تین عادتیں جس میں پائی جائیں،وہ منافق ہوگا: جب بات کر ے، جھوٹ بولے۔جب اس کے پاس امانت رکھی جائے تو خیانت کرے اور جب وعدہ کرے، خلاف ورزی کرے۔جس شخص میں ان میں سے کوئی ایک عادت پائی جائے۔ اس میں نفاق کی خصلت رہے گی حتی ٰ کہ اسے چھوڑ دے۔"}],[5024,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے ایمان کے ساتھ ثواب کی نیت سے رمضان میں قیام کیا (یعنی تراویح پڑھی) کی تو اس کے تمام گزرے ہوئے گناہ معاف کر دئیے جائیں گے\"۔","الألباني: صحيح",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ سے مروی ہے کہ نبی اکر م صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص ایمان کی حالت میں اور ثواب کی نیت سےرمضان المبارک کی راتوں کا قیام کرے، اس کے سب پہلے گناہ معاف کر دے جاتے ہیں۔،،"}],[5025,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص رمضان کے مہینے میں ایمان کے ساتھ اور ثواب کی نیت سے تراویح پڑھے تو اس کے تمام گزرے ہوئے گناہ معاف کر دئیے جائیں گے\"۔","الألباني: صحيح",{"u2":"حضرت ابو ہریرہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا:’’جوشخص رمصان المبارک کی راتوں میں ایمان کی بنا پر اورثواب کی نیت سے عبادبت کرے،اس کے سب پہلے گناہ معاف کر دیے جاتے ہیں۔،،","f2":"دیکھیے حدیث نمبر2194"}],[5026,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس نے رمضان کے مہینے میں ایمان کے ساتھ ثواب کی نیت سے تراویح پڑھی تو اس کے تمام گزرے ہوئے گناہ معاف کر دئیے جائیں گے\"۔","الألباني: صحيح",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا:’’جوشخص رمصان المبارک کی راتوں میں ایمان کی بنا پر اورثواب کی نیت سے عبادبت کرے،اس کے سب پہلے گناہ معاف کر دیے جاتے ہیں۔،،","f2":"’’اس کے پہلے گناہ معاف کر دیے جاتے ہیں،،اس سے مراد حقوق اللہ ہیں۔گناہوں کی اس معافی میں حقوق العباد قطعا شامل نہیں۔اس بات پراہل علم کا اتفاق ہے۔حقوق العباد،صرف بندوں کے معاف کرنے سے معاف ہوسکتے ہیں۔ اگر دنیا میں صاحب حق سےمعاف نہ کرایا گیا توروز قیامت حق داروں کے گناہ اور حق کو اپنی طرف سے اجر وثواب دے کرے اور اس وجہ سے صاحب حق اپنا معاف کردیے۔"}],[5027,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے رمضان میں ایمان کے ساتھ اور ثواب کی نیت سے نماز تہجد پڑھی تو اس کے گزرے ہوئے تمام گناہ معاف کر دیے جائیں گے۔ اور جس نے ایمان کے ساتھ ثواب کی نیت سے شب قدر میں قیام کیا، اس کے بھی گزرے ہوئے تمام گناہ معاف کر دیے جائیں گے\"۔","الألباني: صحيح",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ کا بیان ہےکہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’جو شخص ایمان کے جذبے اور ثواب کی نیت سے رمضان المبارک کا قیام کرے،اس کے سب پہلے گناہ معاف کردیے جاتے ہیں۔اور جو شخص جذبہ ایمان اور نیت ثواب کے ساتھ لیلۃ القدر میں عبادت کر ے، اس کے بھی سب پہلے گناہ معاف کر دیے جاتے ہیں۔،،","f2":"یہ روایات اور ان کامفہوم کتاب الصیام میں بیان ہو چکا ہے۔یہاں یہ روایات ذکر کر نے سے اما م صاحب رحمہ اللہ کا مقصد یہ ہے کہ یہ اعمال (روزہ اور قیام وغیرہ)ایمان کا حصہ ہیں جیسا کہ محدثین کا مسلک ہے۔"}],[5028,"طلحہ بن عبیداللہ رضی اللہ عنہ سے روایت ہے کہ اہل نجد میں سے ایک شخص رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، جس کے بال بکھرے ہوئے تھے، اس کی گنگناہٹ سنائی دیتی تھی لیکن سمجھ میں نہیں آتا تھا کہ وہ کیا کہہ رہا ہے۔ جب وہ قریب ہوا تو معلوم ہوا کہ وہ اسلام کے بارے میں پوچھ رہا ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے اس سے فرمایا: \"دن رات میں پانچ وقت کی نماز\"، اس نے کہا: اس کے علاوہ کچھ اور بھی ہیں میرے اوپر؟ آپ نے فرمایا: \"نہیں، سوائے اس کے کہ تم نفل (سنت) پڑھنا چاہو\"، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"رمضان کے مہینے کے روزے\"، اس نے کہا: میرے اوپر اس کے علاوہ کچھ اور بھی روزے ہیں؟ آپ نے فرمایا: \"نہیں، سوائے اس کے کہ تم نفل ادا کرو\"، اور پھر رسول اللہ صلی اللہ علیہ وسلم نے اس سے زکاۃ کا ذکر کیا۔ اس نے کہا: میرے اوپر اس کے علاوہ بھی ہے؟ آپ نے فرمایا: \"نہیں سوائے اس کے کہ تم نفل دینا چاہو\"، پھر وہ منہ موڑ کر چلا اور کہہ رہا تھا: نہ اس سے زیادہ کروں گا اور نہ اس سے کم کروں گا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اگر اس نے سچ کہا ہے تو وہ کامیاب ہوا\"۔\n§وضاحت\n۱؎: زکاۃ بھی ایمان کے ارکان اور پہچان میں سے ہے اس لیے مؤلف نے یہ عنوان قائم کیا ہے۔","الألباني: صحيح",{"u2":"حضرت طلحہ بن عبید اللہ نے فرمایا:ایک آدمی نجد کے علاقے سے رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا۔ اس کے سر کے بال بکھرے ہوئے تھے۔ اس کی آواز کی بھنبھناہٹ تو سنائی دیتی تھی مگر اس کی بات سمجھ میں نہیں آتی تھی حتی ٰ کہ وہ قریب آگیا تو پتہ چلا کہ وہ اسلام کے بارے میں پوچھ رہاہے۔رسول اللہ صلی اللہ علیہ وسلم نے اسے فرمایا:’’ہر دن رات میں پانچ نمازیں۔،،اس نے کہا:کیا ان کے علاوہ کوئی اور نماز بھی مجھ پر فرض ہے؟ آپ نے فرمایا:’’نہیں مگر یہ کہ تو خوشی سے پڑھے۔،،رسول اللہ صلی اللہ علیہ وسلم نے اسے فرمایا: اور ماہ رمضان المبارک کے روزے۔،، اس نے کہا:کیا اس کے علاوہ بھی مجھ پر کوئی روزے فرض ہیں؟ آپنے فرمایا:’’نہیں مگر یہ کہ خوشی سے کرے۔،،رسول اللہ صلی اللہ علیہ وسلم نے اس کے سامنے زکاۃ کا بھی ذکر فرمایا۔ اس نے کہا: اس کے علاوہ بھی کوئی مالی چیز(صدقہ)مجھ پرفرض ہے؟آپ نے فرمایا:’’نہیں الا یہ کہ تو نفل صدقہ کرے۔،،وہ آدمی واپس جانے لگا تو کہہ رہا تھا:میں نہ اس سے زیادہ کروں گانہ کم۔رسول اللہ صلی اللہ علیہ وسلم سے فرمایا:’’اگر یہ آدمی اپنی بات پر لگا رہا تو کامیاب ہوگیا۔،،","f2":"(1)’’سنائی دیتی تھی،، گویا وہ اپنے سوالات دور سے ہی بڑا بڑا ہوا آرہا تھا۔\n(2)’’کوئی اور نماز، مثلا تہجد،اشراق وضحیٰ وغیرہ کی نمازیں۔یہاں فرضوں سے آگے پیچھے پڑھی جانے والی سنتیں مراد نہیں (جنھیں رواتب کہتے ہیں) کیونکہ یہ تب ہوتا اگر آپ نمازوں کی رکعات کی تعداد بتارہے ہوتے۔\n(3)’’کوئی مالی صدقہ،،بعض لوگوں نے یہاں سے صدقہ الفطر اور قربانی کےوجوب کی نفی پر استدلال کیا ہے۔لیکن صحیح باب یہ ہے کہ صدقۃ الفطر نہیں بلکہ صدقۃ النفس ہے۔ اسی طرح قربانی بھی مالی صدقہ نہیں ورنہ اس سے خود کھانا اور امر اء کو کھلانا جائز نہ ہوتا بلکہ یہ الگ عبادت ہے،جیسے حج اگرچہ اس میں مال صرف ہوتا ہے۔\n(4)’’زیادہ کروں گا نہ کم،، یعنی نفل نمازیں،روزے اور صدقات کی ادائیگی کا عہد نہیں کرتا اور فرائض میں کمی نہیں کروں گا۔ ان الفاظ سے نوافل کی ادائیگی نہیں ہوتی جیساکہ ظاہر بین شخص سمجھتا ہے۔تفصیلی بحث پیچھے گز چکی ہے۔دیکھیے (حدیث:459)\n(5)امام نسائی رحمہ اللہ کا مقصود شعب ایمان بیان کرنا ہے جن میں زکاو ایک اہم حیثیت رکھتی ہے۔"}],[5029,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"اللہ تعالی نے ایسے شخص کو جو اس کی راہ میں نکلتا ہے (یعنی جہاد کے لیے) اور اس کا یہ نکلنا صرف اللہ پر اپنے ایمان کے تقاضے اور اس کی راہ میں جہاد کے جذبے سے ہے (تو اللہ نے ایسے شخص کی) ضمانت اپنے ذمہ لے لی ہے کہ میں اسے جنت میں داخل کروں گا چاہے وہ قتل ہو کر مرا ہو، یا اپنی طبعی موت پائی ہو، یا میں اسے اس اجر و ثواب اور مال غنیمت کے ساتھ جو اسے ملا ہو اور جو بھی ملا ہو، اس کے اپنے اس گھر پر واپس پہنچا دوں گا جہاں سے وہ جہاد کے لیے نکلا تھا\"۔","الألباني: صحيح",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کر تے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:’’جو شخص اللہ تعالیٰ کے راستے میں (جہاد کے لیے)نکلتاہے،اس کے لیے اللہ تعالیٰ نے ضمانت دے رکھی ہے کہ اگروہ صرف مجھ پر ایمان رکھتے ہوئے او ر خالص میرے راستے میں جہاد کرنے کے لیے نکلتاہے تو میں سے ضرور جنت میں داخل کروں گا، چاہے وہ (میدان جنگ میں) قتل وہ جائے یا اسی راستے میں فوت ہےجائے۔یاپھر وہ (اللہ تعالیٰ) اس کو اس کے کھر واپس لائے گا جس سےوہ نکلا تھا جب کہ اس کو ثواب بھی حاصل ہو گا اور عنیمت بھی جواس کے مقدر میں ہے۔،،"}],[5030,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی نے ضمانت لی ہے اس شخص کی جو اس کے راستے میں نکلا ہو اور اس کا یہ نکلنا جہاد کے مقصد سے، اللہ پر ایمان اور اس کے رسولوں کی تصدیق کی وجہ سے ہو تو وہ ضامن ہے اس کا کہ اسے جنت میں داخل کرے یا اسے اس کے وطن لوٹا دے جہاں سے وہ نکلا تھا اس اجر یا مال غنیمت کے ساتھ جو اسے ملا ہو جو بھی ملا ہو\"۔","الألباني: صحيح",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہےکہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص اللہ تعالیٰ کے راستے میں (جہاد کےلیے) نکلتا ہے جب کہ اس کی نیت صرف اللہ تعالیٰ کے راستے میں جہاد ہی کی ہوا ور مجھ پر ایمان اور میرے رسولوں کی تصدیق ہی اس کو جہاد پر مجبور کر رہے ہوں تو اللہ تعالیٰ نے ضمانت دے رکھی ہےکہ میں اسے ضرور جنت میں داخل کروں گا اسے اس کے گھر میں واپس لاؤں گا جہاں سے وہ جہاد کےلیے نکلا تھا، علاوہ ثواب اورعنیمت کے جو اس کو ملے۔،،","f2":"’’مجھ پرایمان،،یہ اللہ تعالیٰ کے الفاظ کی حکایت ونقل ہے کیونکہ ’’میرے رسولوں کی تصدیق،،والے الفاظ اللہ تعالی ٰ ہی کے ہوسکتے ہیں۔"}],[5031,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس بنی عبدقیس کا وفد آیا، تو ان لوگوں بت کہا: ہم لوگ قبیلہ ربیعہ سے ہیں، ہم آپ تک حرمت والے مہینوں کے علاوہ کبھی نہیں آ سکتے تو آپ ہمیں کچھ باتوں کا حکم دیجئیے جو ہم آپ سے سیکھیں اور جو ہمارے پیچھے رہ گئے ہیں اسے ان تک پہنچا سکیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"میں تمہیں چار باتوں کا حکم دیتا ہوں اور چار باتوں سے روکتا ہوں: اللہ پر ایمان -پھر آپ نے اس کی تشریح کی کہ ایک تو گواہی دینا کہ اللہ کے سوا کوئی معبود برحق نہیں اور میں اللہ کا رسول ہوں - دوسرے نماز قائم کرنا، تیسرے زکاۃ کی ادائیگی، چوتھے یہ کہ مال غنیمت کا پانچواں (خمس) مجھے لا کر دینا، اور میں تمہیں روکتا ہوں: (تمبی) کدو کے بنے پیالے، لاکھی (سبز رنگ) کے برتنوں، لکڑی کے برتنوں اور تار کول ملے ہوئے برتنوں کے استعمال سے\" ۱؎۔\n§وضاحت\n۱؎: حدیث میں وارد الفاظ میں دباء، حنتم، مزفت، نقیر، مختلف برتنوں کے نام ہیں جس میں زمانہ جاہلیت میں شراب بنائی اور رکھی جاتی تھی جب شراب حرام ہوئی تو آپ نے ان برتنوں کے استعمال سے بھی منع فرما دیا تھا تاکہ لوگ شراب سے بالکل دور ہو جائیں اور اس حرام چیز کو اپنی زندگی سے مکمل طور پر خارج کر دیں، یہ حکم سد باب کے طور پر تھا، جب مسلمان اس وبا سے دور ہو گئے تو ان برتنوں کے استعمال کی اجازت ہو گئی، بریدہ اسلمی رضی اللہ عنہ کی روایت میں ہے «كنت نهيتكم عن الأوعية فاشربوا في كل وعاء» اس حدیث کی رو سے اب سابقہ نہی کا حکم منسوخ ہو گیا۔","الألباني: صحيح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سےروایت ہے، انھوں نے فرمایا: قبیلہ عبد القیس کا وفد رسول اللہ صلی اللہ علیہ وسلم کی خدمت اقدس میں حاضر ہوا اور کہا: ہم قبیلہ عبد القیس والے ربیعہ کی نسل سے ہیں۔ہم حرمت والے مہینے کے علاوہ آپ کے پاس نہیں آسکتے۔ہمیں کی اہم چیز کا حکم دیجیے جو ہم آپ سے سیکھیں اور واپس جاکر اپنے علاقے کے لوکوں کو اسکی دعوت دیں۔تب آپ نے فرمایا:’’میں تمھیں چار چیزوں کا حکم دیتا ہوں اور چار چیزوں سے روکتا ہوں:(پہلی چار چیزیں یہ ہیں)اللہ تعالیٰ پر ایمان لانا،پھر آپ نے ان کے لیے ایمان کی تفصیل بیان فرمائی۔اس بات کی گواہی دینا کہ اللہ تعالیٰ کے سوا کوئی معبود نہیں اور میں اللہ تعالیٰ کا رسول ہوں۔ نماز پاپندی سے ادا کرنا، زکاۃ اداکر نا اور اپنی بھیجنا اور میں تمھیں خشک کدو کے برتنوں،سبز مٹکے اور تارکول والے مٹکے سے روکتا ہوں۔","f2":"(1)یہ حدیث مبارکہ شہادتین کے اقرار کے ساتھ ساتھ اقامت نماز،ادائیگی زکاۃ،رمضان المبارک کے روزے رکھنے اور مال عنیمت میں سے خمس ادا کرنے کی اہمیت واضح کرتی ہے،نیز یہ بھی رہنمائی کرتی ہے کہ مال غنمیت سے خمس نکالنا ضروری ہے،خواہ مال تھوڑا ہویا زیادہ۔\n(2)’’ربیعہ کی نسل سے ہیں،،مضر اور ربیعہ دوبھائی تھے۔ قریش مکہ مضر کی اولاد سےتھے اور یمنی لوگ ربیعہ کی۔عبد القیس بھی یمنی تھے۔ ان کو روکتے تھے جس کے بارے میں شبہ ہوتا تھا کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس جارہا ہے۔ویسے بھی مضر قبائل ربیعہ کے قبیلوں کواپنا دشمن خیال کرتے تھے اور ان کے قتل اور لوٹ مار کو جائز سمجھتے تھے، اس لیے وہ حرمت والے مہینے کے علاوہ امن وامان سےنہیں گزر سکتے تھے۔(باقی بحث گزر چکی ہیں۔)"}],[5032,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو کسی مسلمان کے جنازے کے پیچھے جائے ایمان کے ساتھ ثواب کی نیت سے، اس کی نماز جنازہ ادا کرے پھر قبر میں رکھے جانے تک انتظار کرے تو اس کے لیے دو قیراط ثواب ہے، ایک قیراط جبل احد کی طرح ہو گا، اور جس نے اس کی نماز جنازہ پڑھی اور لوٹ آیا تو اسے صرف ایک قیراط ثواب ملے گا\"۔","الألباني: صحيح",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم نے فرمایا:’’جوشخص جذبہ ایمان اور ثواب کی نیت رکھتے ہوئے کسی مسلمان کے جنازے کے ساتھ جائے اور نماز جنازہ پڑھے،پھر انتظار کرے حتی ٰ کہ اسے قبر میں دفن کردیا جائے تو اسے دو قیراط ثواب ملے گا جن میں سے ہر ایک قیراط حد پہاڑ کے برابر ہوگا۔اور جو صرف جنازہ پڑھ کر واپس آجائے،اس کو ایک قیراط ثواب ملے گا۔،،"}],[5033,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کا ایک شخص کے پاس سے گزر ہوا، جو اپنے بھائی کو شرم و حیاء کے بارے میں نصیحت کر رہا تھا، آپ نے فرمایا: \"اس کو چھوڑ دو، (یعنی اس کو یہ نصیحت کرنی چھوڑ دو) شرم و حیاء تو ایمان میں داخل ہے\"۔","الألباني: صحيح",{"u2":"حضرت سالم کے والد محترم (حضرت ابن عمر سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم ایک آدمی کے پاس سےگزرے جو اپنے بھائی کو زیادہ حیا کرنے کی وجہ سے ڈانٹ رہا تھا۔آپ نے فرمایا:’’رہنے دے!حیا ایمان کاحصہ ہے۔،،","f2":"(1)حیا عظیم الشان اور اعلیٰ صفات حمیدہ میں سے ایک عظیم صفت ہے۔ہر مسلمان کو چاہیئے کہ آپ کو ہر وقت زیور حیا سے آراستہ رکھے۔حیا کی بابت بہت احادیث میں تر غیب منقول ہے۔\n(2)’’ڈانٹ رہاتھا،، کہ تواس قدر حیا رکرتا ہے کہ اپنا حق بھی نہیں مانگ سکتا۔\n(3)’’رہنے دے،،کیونکہ حیا نہ رہا تو دین ودنیا دونوں جاتے رہیں گے۔دین تو نام ہی حیا کا ہے۔دنیا میں بھی ذلیل ہوتا ہے۔"}],[5034,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یہ دین آسان ہے اور جو دین میں (عملی طور پر) سختی برتے گا تو دین اس پر غالب آ جائے گا(اور اسے تھکا دے گا) لہٰذا صحیح راستے پر چلو (اگر مکمل طور سے عمل نہ کر سکو تو کم از کم) دین سے قریب رہو، لوگوں کو دین کے معاملے میں خوش رکھو (نفرت نہ پیدا کرو) انہیں آسانی دو اور صبح و شام اور کچھ رات گئے کی مدد سے اللہ کی عبادت کرو ۱؎۔\n§وضاحت\n۱؎: ان اوقات سے مدد طلب کرنے کا مطلب ہے کہ ان میں اللہ تعالی کی عبادت کرو۔","الألباني: صحيح",{"u2":"حضرت ابو ہریرہ سے روایت ہےکہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’دین آسان ہے۔جو شخص دین کو سخت بنائے گا،دین اس پر غالب آجائے گا،لہذا تم اپنے اعمال درست رکھو،میا نہ روی اختیار کرو،خوش رہو۔لوگوں پر آسانی کرو،کچھ سفر پہلے پہر کر لیا کر،کچھ پچھلے پہر اور کچھ آخررات کو۔،،","f2":"(1)’’دین آسان ہے،،یعنی جواحکام اللہ تعالیٰ نے مشروع فرمائے ہیں، وہ انسانی طاقت سےباہر نہیں۔ان پ ریہ آسانی عمل ہو سکتا ہے کیونکہ اللہ تعالی ٰ وسعت سےزیادہ تکلیف نہیں دیتا۔یہ مطلب نہیں کہ جو کام مشکل نظر آئے وہ دین نہیں ہو سکتا کیونکہ بدنیت آدمی کے لیے تو دین کا ہر کام ہی مشکل ہے۔\n(2)’’سخت بنائے گا،، یعنی دین میں طرف اپنی طرف سے سخت احکام وداخل کرے گا یا غلو کرے گا تو ایک وقت آئے گا کہ وہ خود اپنی پیدا کردہ سختی پر پورا نہیں اتر سکے گا۔اور اس کا غلو اس کے گلے کا طوق بن جائے گا۔\n(3)’’میانہ روی،،نوافل کے بارے میں ورنہ فرائض کی ادائیگی تو ہمیشہ ضرور ی ہے۔نوافل اتنے ہی اختیار کرنے چاہییں جن پر آسانی اور ہمیشہ عمل ہو سکے۔\n(4)’’خوش رہو،،یعنی اللہ تعالیٰ کے ثواب ورحمت پر یقین رکھواور پر امید رہو۔\n(5)’’کچھ سفر،،عمل کو سفر سے تشبیہ دی گئی ہے۔سفر مناسب طریق سے کیاجائے تو مسافر اور سواری دونوں سہولت میں رہتے ہیں اور سفر بھی اچھا کٹتا ہے لیکن اگر سفر کو مسلسل جاری رکھا جائے اور سواری کو تھکادیا جائے تو سفر منقطع ہوجاتا ہے۔مسافر بھی بیمار پڑجاتا ہے۔اسی طرح عمل بھی اختیار کیا جائے جس پر سہولت سےعمل ہوسکے،دیگر فرائض بھی ادا ہوسکیں اور جسم بھی کمزور نہ پڑے۔عرب معاشرے میں یہ تین اوقات سفر کےلیے بہترین تھے۔باقی اوقات آرام اور کھانے پینے کے لیے ہوتےتھے۔"}],[5035,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم ان کے پاس آئے، ان کے پاس ایک عورت تھی، آپ نے فرمایا: \"یہ کون ہے؟\" کہا: فلانی ہے، یہ سوتی نہیں، اور وہ اس کی نماز کا تذکرہ کرنے لگیں، آپ نے فرمایا: \"ایسا مت کرو، تم اتنا ہی کرو جتنے کی تم میں سکت اور طاقت ہو، اللہ کی قسم! اللہ (ثواب دینے سے) نہیں تھکتا، لیکن تم (عمل کرتے کرتے) تھک جاؤ گے اسے تو وہ دینی عمل سب سے زیادہ پسند ہے جسے آدمی پابندی سے کرے\"۔","الألباني: صحيح",{"u2":"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم انکے پاس تشریف لائے توان (حضرت عائشہ)پاس ایک عورت بیٹھی تھی۔آپ نےفرمایا:’’یہ کو ن ہے؟،،انھوں نے کہا:فلاں عورت ہے۔یہ(رات کو)بالکل نہیں سوتی اور اس کی (نفل)نماز کاذکر کرنے لگیں۔آپ نے فرمایا:’’بس کرو۔اتنا کام کیا کر و جس کی تم طاقت رکھتے ہو۔اللہ کی قسم!اللہ تعالیٰ (ثواب دینے سے)نہیں اکتا ئے گا حتی کہ تم اکتاجاؤ گے۔دین کے کاموں میں سے اللہ تعالی کو سب سے زیادہ پسند دہ ہے جس عمل کرنے والا ہمیشگی کرسکے۔،،","f2":"(1)’’بس کرو،،یا تو خطاب حضرت عائشہ کوہے کہ زیادہ تعریف نہ کرو،اس لیے کہ اس عورت کا یہ انداز قابل تعریف نہیں۔ یا خطاب اس عورت سے ہے کہ یہ طریقہ عبادت چھوڑ دو،یہ درست نہیں بلکہ اس طریقے سے نفل عبادت کیا کرو جس پر تم کاربند رہ سکو۔\n(2)’’نہیں اکتائے گا،، یعنی اللہ تعالی کے پاس ثواب کی کوئی کمی نہیں کہ ثواب کہ دیتے دیتے ختم ہوجائے بلکہ تم ہی کام کرتے کرتے تھک جاؤ گے اور چھوڑ بیٹھو گے۔ پھر ثواب بھی رک جائےگا۔\n(3)’’ہمیشگی کرے،،ظاہر ہے یہ وہی ہوگا جس میں عبادت کے ساتھ ساتھ جسمانی\nآرام اور سہولت کا بھی لحاظ رکھا جائے گا۔"}],[5036,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"وہ زمانہ قریب ہے جب مسلمان کا بہترین مال بکریاں ہوں گی، جنہیں لے کر وہ پہاڑوں کی چوٹیوں اور بارش ہونے کی جگہوں میں چلا جائے گا، وہ اس طرح فتنوں سے اپنے دین کو بچائے گا\"۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری سے روایت کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’وہ وقت قریب ہے جب مسلمان کا بہترین مال بکریاں ہوں گی جن کو لے کر وہ پہاڑی کی چوٹیوں یا بارشی علاقو ں میں چلا جاآ گا تاکہ اپنے دین کو فتنوں سے بچائے۔","f2":"1۔اپنے دین وایمان کی حفاطت کے لیے فتنوں سے بھاگ جانا بھی شعبہ ہائے ایمان میں سے ایک عظیم شعبہ ہے،اس لیے بوقت ضرورت ایک ایمان دار شخص کو فتنوں کی آماجگاہ اور فتنہ پرور لوگوں سے اپنادین وایمان بچانے کے لیے راہ فرار اختیار کر لینی چاہیئے،شرعا اس میں کوئی حرج نہیں۔\n(2)یہ حدیث مبارکہ بکر یاں پالنے اور چرانے وغیرہ کی فضیلت پر بھی دلالت کرتی ہے،نیز اپنا دین محفوظ کرنے کے لیے الگ تھلگ حتی کہ پہاڑ کی چوٹی کو اپنا مسکن بنالینے کی فضیلت کی طرف اشارہ کرتی ہے۔\n(3)یہ حدیث مبارکہ دلائل نبوت میں سے آپ کی نبوت پر ایک عظیم دلیل ہے کہ جس طرح نبی اکرم صلی اللہ علیہ وسلم نے آخری زمانے میں فتنوں کی خبر دی تھی بعینہٖ اسی طرح فتنے گاہے گاہے سر اٹھاے رہتے ہیں حتی کہ بسااوفات ایک ذہین وفہیم مومن بھی حیران وششدر ہوتا ہے کہ ان حالات میں اسے کیا کرنا چا ہئیے اور اپنا دین ان فتنوں سے کس طرح بچانا چاہیئے۔\n(4)اسلام میں رہبانیت اور گوشہ نشینی نہیں، خواہ وہ عبادت کے لیے ہی ہوبلکہ لوگوں میں رہ کر عبادات بجالانا اسلامی طریقہ ہے تاکہ اپنے ساتھ ساتھ لوگوں کو بھی دین پر قائم کرنے کی کوشش کر سکے۔البتہ جب حالات اتنے سنگین ہو جائیں کہ لوگوں میں رہ کر دین پر قائم رہنا ممکن نہ ہو اور اس کے رہنے سے لوگوں کو بھی کوئی شرعی فائدہ نہ ہوتو پھر گوشہ نشینی جائز ہےجیسا کہ حدیث میں بیان ہے۔\n(5)بارشی علاقے سے مراد وادیاں ہیں جہاں بارش کاپانی جمع ہو تا ہے۔یا وہ جگہیں ہیں جہاں بارشیں زیادہ برستی ہیٔں،پھراس سے مراد بھی پہاڑی علاقے ہی ہوں گے۔"}],[5037,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"منافق کی مثال اس بکری کی طرح ہے جو دو ریوڑوں میں چل رہی ہو، کبھی وہ ادھر جاتی ہے اور کبھی ادھر، وہ نہیں سمجھ پاتی کہ کس ریوڑ کے ساتھ چلے\"۔","الألباني: صحيح",{"u2":"سیدنا ابن عمر ٖ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’منافق کی مثال اس بکری کی طرح ہے جو بکر ے کی طلب میں دور یوڑوں کے درمیان ہتی ہے۔کبھی اس ریوڑ میں جاتی ہے،کبھی اس ریوڑ میں اس کو تسلی نہں ہوتی کہ کس ریوڑ کے ساتھ رہے۔","f2":"منافقین کےلیے اس سے زیادہ مناسب مثال ممکن نہیں اور اس میں ان کی انتہائی تو ہین ہے کہ ان کو مؤنث سے مشابہت دی گئی ہے۔گویا مردانہ صفات سے عاری ہیں اور کمینوں کی طرح مال کی طلب میں کبھی مسلمانوں کی خوشامد کرتے ہیں کبھی کافروں کی،لیکن تسلی پھر بھی نہیں ہوتی، حیران وپریشان ہی رہتے ہیں۔"}],[5038,"ابوموسی اشعری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اس مومن کی مثال جو قرآن پڑھتا ہے سنترے کی سی ہے کہ اس کا مزہ بھی اچھا ہے اور بو بھی اچھی ہے، اور اس مومن کی مثال جو قرآن نہیں پڑھتا کھجور کے مانند ہے کہ اس کا مزہ اچھا ہے لیکن کوئی بو نہیں ہے، اور اس منافق کی مثال جو قرآن پڑھتا ہے ریحانہ (خوشبودار گھاس وغیرہ) کی سی ہے کہ اس کی بو اچھی ہے لیکن مزہ کڑوا ہے، اور اس منافق کی مثال جو قرآن نہیں پڑھتا تھوہڑ (اندرائن) جیسی ہے کہ اس کا مزہ کڑوا ہے اور اس میں کوئی خوشبو بھی نہیں\"۔","الألباني: صحيح",{"u2":"سیدنا ابو موسی ٰ اشعر ی رضی اللہ عنہ نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:اس مومن کی مثال جو قرآن مجید پڑھتا ہے،نارنگی کی طرح ہے جس کا ذائقہ بھی اچھا ہے اور خوشبو بھی عمدہ۔اور مومن قرآن نہیں پڑھتا،اس کی مثال کھجور جیسی ہے جس کا ذائقہ تو عمدہ ہے مگر اس میں ہوشبو نہیں۔جومنافق قرآن پڑھتا ہے،اس کی مثال نازبو کی طرح ہے جس کو خوشبو تو اچھی ہے مگر ذائقہ کڑوا ہے۔اور جو منافق قرآن نہیں پڑھتا،اس کی مثال ایلوے کی طرح ہے۔اس کاذائقہ بھی کڑوا ہے،خوشبو بھی نہیں۔","f2":"ان مثالوں میں ایمان کو اچھے ذائقے سے تشبیہ دی گئی ہے جوایمان کی طرح نظر آنےوالی چیز نہیں اور قراءت قرآن ونماز کو خوشبو کے ساتھ کیو نکہ یہ دونوں ظاہر چیزں ہیں۔ محسوس ہوسکتی ہیں۔ معلوم ہوتا ہے اس روایت کو ذکرکرنے سےمقصود ایمان کی کمی بیشی بیان کرنا ہے کیونکہ سب کھجور وں یا نازنگیوں کی مٹھاس ایک سی نہیں ہوتی بلکہ فرق ہوتاہے۔اسی طرح سب مومن ایمان میں برابر نہیں ہوتے۔ان میں بھی فرق ہوتاہے۔"}],[5039,"انس بن مالک رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کوئی مومن نہیں ہو سکتا جب تک کہ وہ اپنے بھائی کے لیے وہی پسند نہ کرے جو اپنے لیے پسند کرتا ہے\"۔","الألباني: صحيح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا:’’ تم میں سے کوئی شخص کامل مومن نہیں بن سکتا حتیٰ کہ اپنے مسلمان بھائی کے لیے وہی کچھ پسند کر جو اپنے لیے کرتا ہے۔،،\nکتات الایمان اختتام پذیر ہوئی۔\nقاضی ابن کسار کہتے ہیں کہ میں نے عبد الصمد بخاری سے سنا، وہ فرماتے تھے کہ حفص بن عمر جو (حدیث:5000میں) عبد الرحمٰن بن مہدی سے بیان کرتے ہیں میں انھیں نہیں جانتا۔ہاں اگروہ حفص بن عمر و ربالی ہوں جو عموما بصریوں سے روایت کرتے ہیں تو وہ ثقہ راوی ہیں۔ قاضی کہتے ہیں کہ انھیں یہ کہتے ہوئےبھی سنا: میں نہیں جانتا کہ انس بن مالک سے مرفوع روایت ہے (امر ت ان اقاتل ....)(واستقبلوا قبلتنا)..... کے اضافے کے ساتھ سوائے عبد اللہ بن مبارک اور یحی ٰ بن ایوب مصری کےکسی نے حیمد الطویل سے بیان کی ہو۔ اور وہ اسی جز میں باب علی مایقاتل الناس کے تحت گزرچکی ہے۔","f2":"ہ عبارت یہاں بے محل ہے۔ حفض بن عمر کی بحث کا تعلق حدیث:5000 سے ہے اور اس میں بھی راجح یہی ہے کہ یہ حفض بن عمر ہی ہے اور عبدالصمد کا دعوائے تصحیف درست نہیں۔دیکھییے(ذخیرۃ العقبی شرح سنن النسائی:37/249)دوسری بات حدیث:5006سے متعلق ہے۔اس میں دعوی ٰ کیا گیا ہے کہ (واستقبلو ا قبلتنا ......) کا اضافہ حمید الطویل سے صرف عبد اللہ بن مبارک اور یحیٰ بن ایوب مصری بیان کرتے ہیں تو بھی درست نہیں کیونکہ محمد بن عیسیٰ بھی حمید الطویل سے یہ اضافہ نقل کرتے ہیں جیسا کہ باب تحریم الدم، حدیث3971 میں ہے۔تفصیل کے لیے دیکھیے (ذخیرۃ العقبیٰ شرح سنن النسائی:37/392)"}],[5040,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"دس چیزیں فطرت ۲؎ (انبیاء کی سنت) ہیں (جو ہمیشہ سے چلی آ رہی ہیں): مونچھیں کتروانا، ناخن کاٹنا، انگلیوں کے پوروں اور جوڑوں کو دھونا، ڈاڑھی کا چھوڑنا، مسواک کرنا، ناک میں پانی ڈالنا، بغل کے بال اکھیڑنا، ناف کے نیچے کے بال صاف کرنا، استنجاء کرنا\"۔ مصعب بن شبیہ کہتے ہیں: دسویں بات میں بھول گیا، شاید وہ \"کلی کرنا ہو\"۔\n§وضاحت\n۱؎: عنوان کتاب: «کتاب الزینۃ من السنن» ہے، یعنی یہ احادیث سنن کبری سے ماخوذ ہیں، جن کے نمبرات کا حوالہ ہم نے ہر حدیث کے آخر میں دے دیا ہے، اس کے بعد دوسرا عنوان: «کتاب الزینۃ من المجتبی» ہے، یعنی اب یہاں سے منتخب ابواب ہوں گے جو ظاہر ہے کہ سنن کبری سے ماخوذ ہوں گے یا مؤلف کے جدید اضافے ہوں گے، اس تنبیہ کی ضرورت اس واسطے ہوئی کہ مولانا عطاء اللہ حنیف بھوجیانی کے نسخے میں عنوان کتاب صحیح آیا ہے، اور مولانا نے اس پر حاشیہ لکھ کر یہ واضح کر دیا ہے کہ اس کتاب میں یہ ابواب \" سنن کبری \" سے منقول ہیں، لیکن مولانا وحیدالزماں کے مترجم نسخے میں«کتاب الزینۃ: باب من السنن الفطرۃ» مطبوع ہے، اور حدیث کے ترجمہ میں آیا ہے: دس باتیں پیدائشی سنت ہیں :(یعنی ہمیشہ سے چلی آتی ہیں، سب نبیوں نے اس کا حکم کیا ) :(۳/۴۵۵ ) اور اس کا ترجمہ \" کتاب آرائش کے بیان میں \"، پھر نیچے پیدائشی سنتیں لکھا ہے، اور مشہور حسن کے نسخے میں«کتاب الزینۃ من السنن الفطرۃ» مطبوع ہے، جب کہ «من السنن» کا تعلق «کتاب الزینۃ» سے ہے۔ ۲؎: اکثر علماء نے فطرت کی تفسیر سنت سے کی ہے، گویا یہ خصلتیں انبیاء کی سنت ہیں جن کی اقتداء کا حکم اللہ تعالی نے ہمیں اپنے قول: «فبهداهم اقتده» :(سورة الأنعام: 90 ) میں دیا ہے، بعض علماء اس کی تفسیر \" فطرت \" ہی سے کرتے ہیں، یعنی یہ سب کام انسانی فطرت کے ہیں جس پر انسان کی خلقت ہوئی ہے، بعض علماء دونوں باتوں کو ملا کر یوں تفسیر کرتے ہیں کہ یہ سب حقیقی انسانی فطرت کے کام ہیں اسی لیے ان کو انبیاء علیہم السلام نے اپنایا ہے۔","الألباني: حسن",{"u2":"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: دس چیزیں فطرت انسانیہ کا تقاضا ہیں: مونچھیں کاٹنا، ناخن تراشنا، انگلیوں کے جوڑوں اور پوروں کو اچھی طرح دھونا، ڈاڑھی پوری رکھنا، مسواک کرنا، ناک میں پانی چڑھانا (اور ناک کی صفائی کرنا) بغلوں کے بال اکھیڑنا، شرم گاہ کے بال مونڈنا، پانی کے ساتھ استنجا کرنا۔ مصعب بن شیبہ (راوئ حدیث) نے کہا: دسویں چیز میں بھول گیا۔ امید ہے کہ وہ کلی کرنا ہوگا۔","f2":"1۔ اس حدیث سے اس طرف اشارہ ملتا ہے کہ امور فطرت صرف دس چیزیں نہیں بلکہ یہ دس تو کچھ امور فطرت ہیں۔ یہ اس لیے کہ حدیث کے الفاظ ہیں: عشرة من الفطرة، اور لفظ من تبعیض کے لیے ہے یعنی کچھ امور فطرت یہ ہیں نہ کہ سارے امور فطرت کا یہاں احاطہ ہے۔ بعض احادیث میں دس کے بجائے پانچ اشیاء کو امور فطرت کہاگیا ہے،وہاں بھی احاطہ اور حصر مقصود نہیں۔ واللہ اعلم۔2۔ ان دس چیزوں کے فطرت ہونے سے مراد یہ ہے کہ فطرت انسانیہ ان امور کا تقاضا کرتی ہے۔ فطرت کے معنی سنت بھی کیے گئے ہیں کیونکہ دین اسلام بھی تو فطرت انسانیہ کے عین مطابق ہے۔ تمام انبیاء﷩ ان چیزوں پر عمل پیرا رہے۔ ان میں سے اکثر امور کی تفصیل کتاب الطہارۃ میں بیان ہوچکی ہے۔ (دیکھئے، حدیث:3تا15) 3۔ براحم، برجمة کی جمع ہے۔ اس سے مراد وہ تمام جگہیں ہیں جہاں میل کچیل جمع ہوتاہے اور توجہ نہ کی جائے تو پانی وہاں نہیں پہنچتا، مثلاً: انگلیوں کی گرہیں اور پور، جسم کے دیگر جوڑ اور ہتھیلی کی لکیریں وغیرہ۔"}],[5041,"طلق بن حبیب کہتے ہیں کہ دس باتیں فطرت (انبیاء کی سنتیں) ہیں: مسواک کرنا، مونچھ کترنا، ناخن کاٹنا، انگلیوں کے پوروں اور جوڑوں کو دھونا، ناف کے نیچے کے بال صاف کرنا، ناک میں پانی ڈالنا، مجھے شک ہے کہ کلی کرنا بھی کہا۔","الألباني: صحيح الإسناد مقطوع",{"u2":"سلیمان تیمی سے روایت ہے کہ میں نے حضرت طلق بن حبیب کو فرماتے سنا، دس چیزیں فطری ہیں:مسواک کرنا، مونچھیں حضرت کاٹنا، ناخن تراشنا، انگلیوں کے پوروں اور جوڑوں کو اچھی طرح دھونا، زیر ناف بال مونڈنا، ناک کی صفائی کرنا، کلی کے بارے میں مجھے شک ہے۔"}],[5043,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"پانچ چیزیں خصائل فطرت سے ہیں: ختنہ کرانا، ناف کے نیچے کے بال مونڈنا، بغل کے بال اکھیڑنا، ناخن اور مونچھیں کاٹنا\"۔ مالک نے اسے موقوفاً روایت کیا ہے، (ان کی روایت آگے آ رہی ہے)۔\n§وضاحت\n۱؎: پانچ چیزوں کے ذکر سے یہاں حصر مراد نہیں ہے، خود پچھلی حدیث میں \" دس \" کا تذکرہ ہے، مطلب یہ ہے کہ \" یہ پانچ، یا دس چیزیں فطرت کے خصائل میں سے ہیں۔ ان کے علاوہ بھی بعض چیزیں فطرت کے خصائل میں سے ہیں جن کا تذکرہ کئی روایات میں آیا ہے :(نیز دیکھئیے فتح الباری کتاب اللباس باب ۶۳ )۔","الألباني: صحيح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: پانچ چیزیں فطری ہیں: ختنہ کرنا، شرمگاہ کے بال مونڈنا، بغلوں کے بال اکھیڑنا، ناخن تراشنا اور مونچھیں چھوٹی کرنا۔\nامام مالک رحمہ اللہ نے اس (روایت) کو موقوف بیان کیا ہے(جیسا کہ اگلی روایت میں آ رہا ہے)"}],[5044,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ پانچ چیزیں خصائل فطرت سے ہیں: ناخن کترنا، مونچھ کاٹنا، بغل کے بال اکھیڑنا، ناف کے نیچے کے بال مونڈنا اور ختنہ کرنا۔","الألباني: صحيح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نے فرمایا: پانچ چیزیں فطرت اور سنت ہیں: ناخن تراشنا، مونچھیں کاٹنا، بغل کے بال اکھیڑنا، شرمگاہ کے بال مونڈنا اور ختنہ کروانا","f2":"فطرت ہیں۔ جو شخص یہ کام نہیں کرتا وہ انسانی فطرت کا باغی اور انبیاء ﷩ کے طریقے کا مخالف ہے۔"}],[5045,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ میں نے عرض کیا: اللہ کے رسول! کون سا گناہ بڑا ہے؟ آپ نے فرمایا: \"یہ کہ تم کسی کو اللہ کے برابر (ہم پلہ) ٹھہراؤ حالانکہ اس نے تمہیں پیدا کیا ہے\"، میں نے عرض کیا: پھر کون سا؟ آپ نے فرمایا: \"یہ کہ تم اس ڈر سے اپنے بچے کو مار ڈالو کہ وہ تمہارے ساتھ کھائے گا\"۔ میں نے عرض کیا: پھر کون سا؟ آپ نے فرمایا کہ \"تم اپنے پڑوسی کی بیوی سے زنا کرو\"۔\nعبداللہ بن عمر رضی اللہ عنہما روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"مونچھیں کاٹو اور ڈاڑھیاں بڑھاؤ\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: مونچھوں کو ختم کرو اور ڈاڑھی کو بڑھنے دو۔","f2":"اس حدیث کی تشریح کے لیے ملاحظہ فرمائیں، حدیث:15"}],[5046,"زید بن ثابت رضی اللہ عنہ کہتے ہیں کہ جب آیت: «ومن يقتل مؤمنا متعمدا فجزاؤه جهنم خالدا فيها» نازل ہوئی تو ہمیں خوف ہوا۔ پھر سورۃ الفرقان کی یہ آیت: «والذين لا يدعون مع اللہ إلها آخر ولا يقتلون النفس التي حرم اللہ إلا بالحق» نازل ہوئی۔\nعبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ میں نے عرض کیا: اللہ کے رسول! کون سا گناہ سب سے بڑا ہے؟ آپ نے فرمایا: \"یہ کہ تم کسی کو اللہ کے برابر ٹھہراؤ حالانکہ اس نے تم کو پیدا کیا ہے\"۔ میں نے عرض کیا: پھر کون سا؟ آپ نے فرمایا: \"یہ کہ تم اپنے بچے کو اس وجہ سے مار ڈالو کہ وہ تمہارے ساتھ کھائے گا\"۔ میں نے عرض کیا: پھر کون سا؟ آپ نے فرمایا: \"یہ کہ تم اپنے پڑوسی کی بیوی کے ساتھ زنا کرو\"۔\nام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ کیا تمہیں معلوم نہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کسی مسلمان شخص کا خون حلال نہیں سوائے اس شخص کے جس نے شادی کے بعد زنا کیا یا اسلام لانے کے بعد کفر کیا یا جان کے بدلے جان لینا ہو\"۔ اسے زہیر نے موقوفاً روایت کیا ہے (ان کی روایت آگے آ رہی ہے)۔\nعبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ڈاڑھیاں بڑھاؤ اور مونچھیں کترو\"۔","الألباني: منكر",{"u2":"حضرت ابن عمر رضی اللہ عنہما سے روایت ہے کہ نبئ اکرم صلی اللہ علیہ وسلم نے فرمایا: ڈاڑھیاں رکھو اور مونچھیں صاف کرو۔"}],[5047,"زید بن ارقم رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"جس نے مونچھیں نہیں کاٹیں وہ ہم میں سے نہیں ہے\"۔","الألباني: صحيح",{"u2":"سیدنا زید بن ارقم رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: جو شخص اپنی مونچھیں نہ کاٹے، وہ ہم میں سے نہیں۔","f2":"1۔مونچھیں نہ کاٹے یعنی کاٹنے کی ضرورت ہو، مثلاً: وہ منہ میں پڑنے لگیں۔ مشروب سے آلودہ ہوں وغیرہ: ورنہ ہر روز کاٹنا ضروری نہیں اور نہ ساری زندگی میں ایک آدھ دفعہ کاٹ لینا ہی کافی ہے۔2۔ ہم میں سے نہیں۔ یعین ہمارے طریقۂ کار پر عمل پیرا نہیں، یا دیکھنےمیں مسلمان نہیں لگتا، یا تشبیہ مراد ہے کہ وہ غیر مسلموں جیسا ہے۔ واللہ اعلم۔"}],[5048,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے ایک بچے کو دیکھا، اس کے سر کا کچھ حصہ منڈا ہوا تھا اور کچھ نہیں، آپ نے ایسا کرنے سے روکا اور فرمایا: \"یا تو پورا سر مونڈو، یا پھر پورے سر پر بال رکھو\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما سے روایت ہے کہ نبئ اکرم صلی اللہ علیہ وسلم نے ایک بچہ دیکھ جس کا کچھ سر مونڈا ہوا تھا اور کچھ چھوڑ دیا گیا تھا۔ آپ نے اس سے منع فرمایا اور فرمایا: سارا سر منڈاؤ یا سارا رہنے دو","f2":"کافر لوگ سر مونڈتے وقت کچھ بال کسی بت وغیرہ کے نام پر رکھ چھوڑتے تھے جس طرح آج کل بھی بعض جاہل لوگ کسی پیر کے نام کی بودی رکھتے ہیں، حالانکہ غیراللہ کی ایسی تعظیم حرام ہے، لہذا آپ نے منع فرمایا۔ ویسے بھی یہ چیز نامناسب لگتی ہے۔ آدمی بھدا لگتا ہے اور یہ فطرت انسانیہ کے خلاف ہے۔ البتہ اس کا یہ مطلب نہیں کہ سر کے ہر حصے سے ایک جیسے یا ایک جتنے بال کٹوائے جائیں بلکہ اگر کانوں کے قریب سے زیادہ ترشوالیے جائیں تاکہ کانوں میں نہ پڑیں اور سر کے اوپر سے کم کٹوالیے جائیں تو کوئی حرج نہیں بشرطیکہ دیکھنے میں متناسب ہوں۔"}],[5049,"علی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے عورت کو سر منڈانے سے منع فرمایا۔","الألباني: ضعيف",{"u2":"سیدنا علی رضی اللہ عنہ سےر وایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا کہ عورت اپنا سرمنڈوائے۔","f2":"اسلام اور انسانی فطرت کا تقاضاہ ہے کہ مرد اور عورت ظاہری امور میں مشابہت نہ رکھیں بلکہ دور سے ہی امتیاز ہونا چاہیے کہ یہ مرد ہے اور یہ عورت۔ مرد کے لیے شریعت نے سرمونڈنا اور بال کٹوانا جائز قرار دیا ہے، جبکہ عورت کے لیے نہ سر منڈوانا جائز ہے نہ بال کٹوانا ہی تاکہ مرد کے ساتھ مشابہت نہ ہو۔ اس کے علاوہ لمبے بال مرد کے کام کاج میں بھی رکاوٹ بن سکتے ہیں۔ سرڈھانپنے کی وجہ سے عورت کے لیے لمبے بال کوئی مسئلہ نہیں، اس لیے بال کٹوانا یا منڈوانا مردوں کے ساتھ خاص کردیا گیا اور سرکے بال رکھنا عورتوں کے ساتھ۔"}],[5050,"عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"(قیامت کے دن) آدمی آدمی کا ہاتھ پکڑے آئے گا اور کہے گا: اے میرے رب! اس نے مجھے قتل کیا تھا، تو اللہ تعالی اس سے کہے گا: تم نے اسے کیوں قتل کیا تھا؟ وہ کہے گا: میں نے اسے اس لیے قتل کیا تھا تاکہ عزت و غلبہ تجھے حاصل ہو، اللہ تعالی فرمائے گا: وہ یقیناً میرے ہی لیے ہے، ایک اور شخص ایک شخص کا ہاتھ پکڑے آئے گا اور کہے گا: اس نے مجھے قتل کیا تھا، تو اللہ تعالی اس سے پوچھے گا: تم نے اسے کیوں قتل کیا تھا؟ وہ کہے گا: تاکہ عزت و غلبہ فلاں کا ہو، اللہ فرمائے گا: وہ تو اس کے لیے نہیں ہے۔ پھر وہ (قاتل) اس کا (جس کے لیے قتل کیا اس کا) گناہ سمیٹ لے گا\" ۱؎۔\n§وضاحت\n۱؎: یہ حدیث آیت کریمہ «ولا تزر وازرة وزر أخرء» کے منافی اور خلاف نہیں ہے، اس لیے کہ آیت کا مفہوم یہ ہے کہ کسی دوسرے کا گناہ ایسے شخص پر نہیں لادا جا سکتا جس کا اس گناہ سے نہ تو ذاتی تعلق ہے اور نہ ہی اس کے کسی ذاتی فعل کا اثر ہے، اور یہاں جس قتل ناحق کا تذکرہ ہے اس میں اس شخص کا تعلق اور اثر موجود ہے جس کی عزت و تکریم یا حکومت کی خاطر قاتل نے اس قتل کو انجام دیا ہے۔\nعبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"مجھے اللہ تعالی نے «قزع» (سر کے کچھ بال منڈانے اور کچھ رکھ چھوڑنے)سے منع کیا ہے\"۔","الألباني: صحيح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ نبئ اکرم صلی اللہ علیہ وسلم نے فرمایا: اللہ عزوجل نے مجھے قزع سے منع فرمایا ہے۔","f2":"یہ روایت ان الفاظ کے ساتھ منکر ہے۔ محقق کتاب کا اسے بخاری و مسلم کی طرف منسوب کرنا درست نہیں کیونکہ بخاری ومسلم کا سیاق آئندہ روایت کے مطابق ہے۔ دیکھئے: (ذخیرۃ العقبیٰ شرح سنن النسائی:38؍13)"}],[5051,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے «قزع» (سر کے کچھ بال منڈانے اور کچھ رکھ چھوڑنے) سے منع فرمایا ہے۔ ابوعبدالرحمٰن(نسائی) کہتے ہیں: یحیی بن سعید اور محمد بن بشر کی حدیث زیادہ قرین صواب ہے ۱؎۔\n§وضاحت\n۱؎: یحیی بن سعید اور محمد بن بشر کی حدیث باب «ذکر النہی عن أن یحلق بعض شعر الصبي و یترک بعضہ» کے ضمن میں نمبر ۵۲۳۲، ۵۲۳۳ کے تحت ذکر ہے۔ ان دونوں حدیثوں میں عبیداللہ اور نافع کے درمیان عمر بن نافع کا ذکر ہے، جب کہ سفیان کی اس روایت میں ایسا نہیں ہے۔","الألباني: صحيح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے قزع سے منع فرمایا ہے۔\nابوعبدالرحمٰن (امام نسائی رحمہ اللہ) نے کہا کہ یحیٰ بن سعید(القطان) اور محمد بن بشر کی روایت (اس مذکورہ روایت سے) زیادہ درست اور صحیح ہے۔","f2":"قزع سے مراد یہ ہے کہ سر کہیں سے مونڈ دیا جائے کہیں سے چھوڑ دیا جائے۔ منع کی وجہ حدیث نمبر5051 میں دیکھئے۔"}],[5052,"وائل بن حجر رضی اللہ عنہ کہتے ہیں کہ میں نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا اور میرے سر پر (لمبے) بال تھے، آپ نے فرمایا: \"نحوست ہے\"، میں نے سمجھا کہ آپ مجھے کہہ رہے ہیں، چنانچہ میں نے اپنے سر کے بال کٹوا دیے پھر میں آپ کے پاس آیا تو آپ نے فرمایا: \"میں نے تم سے نہیں کہا تھا، لیکن یہ بہتر ہے\"۔\n§وضاحت\n۱؎: اکثر نسخوں میں یہ تبویب ہے، بعض نسخوں میں «الأخذ من الشعر» ہے جو احادیث کے سیاق کے مناسب ہے، کیونکہ ان میں صرف بال کاٹنے کا تذکرہ ہے۔","الألباني: صحيح الإسناد",{"u2":"سیدنا وائل بن حجر رضی اللہ عنہ نے کہا کہ میں نبئ اکرم صلی اللہ علیہ وسلم کے پاس حاضر ہوا تو میرے لمبے لمبے بال تھے۔ آپ نے فرمایا: نحوست ہے (یہ بری چیز ہے۔) میں نے سمجھا، آپ کا اشارہ میری طرف ہے۔ میں نے اپنے بال کاٹ دیے۔ پھر میں آپ کےپاس حاضر ہوا تو آپ نے فرمایا: میرا اشارہ تیری طرف نہیں تھا۔ ویسے یہ تیری زیادہ اچھی حالت ہے۔","f2":"1۔ مذکورہ حدیث اور عنوان کی باہم مطابقت نہیں ہے۔ ہاں! یہ مطابقت اس صورت میں ہو سکتی ہے کہ یہ باب اس طرح ہو’ الأ خذ من الشعر‘ جیسا کہ بعض نسخوں میں انہیں الفاظ سے عنوان قائم کیا گیا ہے۔ دیکھیے (ذخیرۃ العقبیٰ شرح سنن النسائی:38؍18)۔2۔ یہ حدیث مبارکہ صحابۂ کرام رضی اللہ عنہم کی عظمت پر بھی صریح دلالت کرتی ہے کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے حکم کی کس طرح تعمیل کرتے تھے کہ سیدنا وائل بن حجر رضی اللہ عنہ نے جب نبی صلی اللہ علیہ وسلم کی زبان مبارک سےلفظ ذباب ’نحوست ہے‘ سنا توفوراً جاکر اپنے لمبے بال کٹوادیے۔ انہوں نے یہ کام اس لیے کیا کہ وہ سمجھتے تھے کہ آپ میرے بالوں کی مذمت کررہے ہیں۔ رسول اللہ صلی اللہ علیہ وسلم نے انہیں اگرچہ بال کٹوانے کاحکم نہیں دیا تھا، تاہم آپ نے سیدنا وائل رضی اللہ عنہ کے فعل کی تحسین فرمائی۔3۔ بہت زیادہ لمبے بال رکھنا مناسب نہیں کہ حداعتدال ہی سے نکل جائیں۔ یہی وجہ ہے کہ نبی صلی اللہ علیہ وسلم نے سیدنا وائل رضی اللہ عنہ کے لمبے بال کٹوادینے کے عمل کو سراہا اور خود رسول اللہ صلی اللہ علیہ وسلم کے اپنے بال مبارک آپ کے مبارک شانوں (کندھوں) سے زیادہ نیچے نہیں جایا کرتے تھے۔ ہر شخص کو بالخصوص ہر مسلمان کو نبی صلی اللہ علیہ وسلم کی اقتدا کرنی چاہیے۔4۔ معلوم ہوا بال کٹوانا اچھی بات ہے۔بہت لمبے بال رکھنا عورتوں سے مشابہت ہے۔"}],[5053,"انس رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کے بال درمیانے قسم کے تھے، نہ بہت گھنگرالے تھے، نہ بہت سیدھے، کانوں اور مونڈھوں کے بیچ تک ہوتے تھے۔","الألباني: صحيح",{"u2":"سیدنا انس رضی اللہ عنہ سےر وایت ہے، انہوں نے فرمایا: نبئ اکرم صلی اللہ علیہ وسلم کے سر کے بال لہردار تھے۔ نہ گھنگھریالے نہ بالکل سیدھے۔ (اور عموماً) کانوں اور کندھے کے درمیان رہتے تھے۔","f2":"1۔’لہردار‘ ممکن ہے پیدائشی طور پر لہر دار ہوں۔ یہ بھی ہوسکتا ہے کہ لمبے ہونے کی وجہ سے ان میں بل پڑ گئے ہوں۔ لمبے بالوں میں عموماً ایسے ہوتا ہے۔2۔ کانوں اور کندھوں کے درمیان‘ معلوم ہوتا ہے کہ آپ کانوں کے نچلے حصے کے برابر بال کاٹ لیتے ہوں گے۔ جب وہ بڑھتے بڑھتے کندھوں کو لگنے لگتے تو پھر کاٹ دیتے۔ یہ بھی کہا جاسکتا ہے کہ آپ سر جھکاتے تو آپ کے بال مبارک کانوں کے برابر محسوس ہوتے اور جب سرمبارک اٹھاتے تو کندھوں کولگتے تھے۔ عام حالات میں کانوں اور کندھوں کےدرمیان رہتے۔ واللہ اعلم۔ 3۔ دونوں صورتوں میں بال کٹوانے پر دلالت ہوتی ہے۔4۔ اس حدیث مبارکہ سے یہ بھی معلوم ہوتا ہے کہ ڈاڑھی اور سرکے بالوں کاحکم الگ الگ ہے۔ سر کے بال کٹوانا او رمنڈوانا دونوں جائز ہیں جبکہ ڈاڑھی کےبال کٹوانا اور منڈوانا دونوں ناجائز اور حرام کام ہیں۔5۔ رسول اللہ صلی اللہ علیہ وسلم حسن تخلیق کا شاہکار تھے، اس لیے نیم گھنگریالے بال ہی حسن و جمال کی علامت ہوں گے جیسا کہ نبی صلی اللہ علیہ وسلم کے بال تھے۔"}],[5054,"حمید بن عبدالرحمٰن حمیری کہتے ہیں کہ میری ملاقات ایک ایسے شخص سے ہوئی، جو نبی اکرم صلی اللہ علیہ وسلم کی صحبت میں ابوہریرہ رضی اللہ عنہ کی طرح چار سال رہا تھا، اس نے کہا: ہمیں رسول اللہ صلی اللہ علیہ وسلم نے روزانہ کنگھی کرنے سے منع فرمایا ہے ۱؎۔\n§وضاحت\n۱؎: یہ حدیث اگلے باب سے متعلق ہے، ناسخین کتاب کی غلطی سے یہاں درج ہو گئی ہے۔","الألباني: صحيح",{"u2":"حضرت حمید بن عبدالرحمن حمیری سے روایت ہے کہ میں ایک بزرگ کو ملا نبئ اکرم صلی اللہ علیہ وسلم کی خدمت اقدس میں اسی طرح رہے تھے جس طرح سیدنا ابوہریرہ رضی اللہ عنہ چار سال آپ کی خدمت اقدس میں رہے۔ انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے ہمیں ہرروز کنگھی کرنے سے منع فرمایا ہے۔","f2":"1۔ جس طرح سیدنا ابوہریرہ رضی اللہ عنہ یہ تشبیہ مدت میں بھی ہوسکتی ہے کہ وہ بھی چار سال آپ صلی اللہ علیہ وسلم کے پاس رہے۔ سیدنا ابوہریر ہ رضی اللہ عنہ 7ہجری کے آغاز میں حاضر ہوئے اور رسول اللہ صلی اللہ علیہ وسلم 11 ہجری کے تیسرے مہینے میں اللہ کو پیارے ہوئے۔ یا یہ تشبیہ کیفیت میں بھی ہوسکتی ہے کہ جس طرح سیدنا ابوہریرہ رضی اللہ عنہ ہر وقت آپ کے ساتھ رہا کرتے تھے، اسی طرح وہ بزرگ بھی تقریباً ہر وقت آ پ کے ساتھ رہا کرتے تھے۔2۔ ہرروز کنگھی، کیونکہ ہر روز کنگھی کرنا دلیل ہے کہ اس شخص کی زیب وزینت کی طرف ضرورت سے زیادہ توجہ ہے اور یہ وصف عورتوں میں پایا جاتا ہے۔ یہ شخص یا عورتوں کی طرح بن سنور کر رہتا ہے۔ اس میں وہ مردوں کے لیے فتنہ بنے گا یا عورتوں کو مائل کرنے کی غرض سے ایسے کرتا ہے تو عورتوں کے لیے فتنہ بنے گا۔ مردوں کی توجہ زیب و زینت کی طرف نہیں ہونی چاہیے ورنہ مفاسد پیدا ہوں گے۔3۔ ہر روز کنگھی نہ کرنے کا لازمی نتیجہ ہے کہ بال کٹواکے رکھے جائیں تاکہ روازانہ کنگھی کرنے کی ضرورت ہی نہ رہے۔ یہی باب سے مناسبت ہے۔"}],[5055,"عبداللہ بن مغفل رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے (بالوں میں) کنگھی کرنے سے منع فرمایا، مگر ایک دن چھوڑ کر۔","الألباني: صحيح",{"u2":"سیدنا عبداللہ بن مغفل رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بلا ناغہ کنگھی کرنےسے منع فرمایا ہے۔"}],[5056,"حسن بصری سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے کنگھی کرنے سے منع فرمایا مگر ایک دن چھوڑ کر۔","الألباني: صحيح لغيره",{"u2":"حضرت حسن بصری سے روایت ہے کہ نبئ اکرم صلی اللہ علیہ وسلم نے بلا ناغہ کنگھی کرنے سے روکا ہے۔"}],[5057,"ابراہیم نخعی اور سعید بن جبیر سے روایت ہے کہ وہ دونوں خالی زمین کو کرائے پر اٹھانے میں کوئی حرج نہیں سمجھتے تھے۔\nحسن بصری اور محمد بن سیرین کہتے ہیں: (بالوں میں) کنگھی ایک ایک دن چھوڑ کر کرنا چاہیئے۔","الألباني: صحيح الإسناد مقطوع",{"u2":"حضرت حسن بصری اور حضرت محمدبن سیرین نے فرمایا: کنگھی ناغے سے ہونی چاہیے۔","f2":"اس فرمان میں ان لوگوں کے لیے نصحیت ہے جو ہر وقت جیب میں کنگھی لیے پھر تے ہیں۔ تفصیلی بحث کے لیے دیکھئے، حدیث:5057۔ صحیح بات یہ ہے کہ مذکورہ بالاتینوں روایات شواہد و متابعات کی وجہ سے صحیح ہیں۔"}],[5058,"عبداللہ بن شقیق کہتے ہیں کہ ایک صحابی رسول جو مصر میں افسر تھے، ان کے پاس ان کے ساتھیوں میں سے ایک شخص آیا جو پراگندہ سر اور بکھرے ہوئے بال والا تھا، تو انہوں نے کہا: کیا وجہ ہے کہ میں آپ کو پراگندہ سرپا رہا ہوں حالانکہ آپ امیر ہیں؟ وہ بولے: نبی اکرم صلی اللہ علیہ وسلم ہمیں «ارفاہ» سے منع فرماتے تھے، ہم نے کہا: «ارفاہ» کیا ہے؟ روزانہ بالوں میں کنگھی کرنا۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن شفیق سے روایت ہے کہ نبئ اکرم صلی اللہ علیہ وسلم کے صحابہ میں سے ایک صحابی مصر کے حاکم تھے۔ ان کا ایک ساتھی ان کے پاس آیا تو دیکھا کہ ان کے بال پراگندہ اور بکھرے ہوئے ہیں۔ وہ کہنے لگا:کیا وجہ ہے کہ آپ کے بال بکھرے ہوئے ہیں، حالانکہ آپ حاکم ہیں؟ انہوں نے فرمایا نبئ اکرم صلی اللہ علیہ وسلم ہمیں زیادہ ٹیپ ٹاپ سے روکا کرتے تھے۔ اس نے کہا: ٹیپ ٹاپ کا کیا مطلب؟ انہوں نے فرمایا: ہر روز کنگھی کرنا۔","f2":"ٹیپ ٹاپ تو وسیع مفہوم رکھتا ہے اور ہر روز کنگھی کرنااس میں داخل ہے نہ کہ یہ اس کے معنی ہیں۔"}],[5059,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم (کاموں کو) دائیں طرف سے شروع کرنا پسند فرماتے تھے (کوئی چیز) لیتے تھے تو دائیں ہاتھ سے، دیتے تھے تو دائیں ہاتھ سے، نیز آپ صلی اللہ علیہ وسلم ہر کام میں داہنی طرف سے ابتداء کرنا پسند فرماتے تھے۔","الألباني: صحيح",{"u2":"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے، انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم دائیں طرف اختیار کرنے کو پسند فرماتے تھے۔ اپنے دائیں ہاتھ سے لیتے، دائیں ہاتھ سے دیتے بلکہ تمام معاملات میں دائیں طرف کو ترجیح دیتے تھے۔","f2":"تمام معاملات، مراد وہ معاملات ہیں جو دائیں سے مناسبت رکھتے ہیں ورنہ استنجا کرنا، ناک جھاڑنا وغیرہ بائیں ہی سے مستحب ہیں، نیز ہ معاملات ایک ہاتھ سے سرانجام دیے جاسکتے ہوں ورنہ جو کام دونوں ہاتھوں سے ہوتے ہیں، وہاں دونوں ہاتھ استعمال ہوں گے۔مثلاً: روٹی پکانا بلکہ بعض چیزوں کو کھانا، جیسے ہڈی سے گوشت نوچنا۔ البتہ ایسے کاموں میں بھی دائیں سے ابتداء کی جائے، نیز یہ صرف مستحب ہے۔ اسے فرض نہیں سمجھ لینا چاہیے۔ ہاں کھانے پینے میں دائیں ہاتھ کا استعمال ضروری ہے، نیز عبادات میں کہ عبادات عادات سے مختلف ہوتی ہیں۔ مزید دیکھئے، حدیث112)"}],[5060,"براء بن عازب رضی اللہ عنہما کہتے ہیں کہ میں نے کسی کو لال جوڑے میں رسول اللہ صلی اللہ علیہ وسلم سے زیادہ خوبصورت نہیں دیکھا، آپ کے بال آپ کے مونڈھوں تک تھے ۱؎۔\n§وضاحت\n۱؎: نبی اکرم صلی اللہ علیہ وسلم کے سر کے بال تین طرح تھے: آدھے کانوں تک، پورے کانوں تک، اور کندھے تک، تینوں صورتیں مختلف احوال میں ہوتی تھیں، ان میں کوئی تضاد نہیں ہے۔","الألباني: صحيح",{"u2":"سیدنا براء رضی اللہ عنہ نے فرمایا: میں نے کسی شخص کو سرخ حلہ پہنے ہوئے رسول اللہ صلی اللہ علیہ وسلم سے زیادہ خوب صورت نہیں دیکھا جب کہ آپ کے سر مبارک کے لمبے لمبے بال کندھوں سے ٹکراتے تھے۔","f2":"مقصود یہ ہے کہ سرخ لباس آپ پر بہت جچتا تھا کیونکہ وہ آپ کے جسمانی رنگ وروپ سے بہت زیادہ مناسبت رکھتا تھا۔ رنگ بھی سرخ وسپید اور حلہ بھی سرخ و سفید۔ 2۔ کندھوں سے، مراد مرد کے لیے بالوں کو کاٹنا ضروری ہے۔ کندھوں کے برابر کاٹے یا کانوں کے یا اس سے اوپر۔ (تفصیل دیکھئے، حدیث:5056)"}],[5061,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے بال کان کے آدھے حصہ تک ہوتے تھے۔","الألباني: صحيح",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے، انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم کے بال مبارک نصف کانوں تک ہوتے تھے۔","f2":"نصف کانوں تک،یہ سابقہ روایات کے خلاف نہیں۔ کاٹتے وقت نصف کانوں کے برابرہوں، پھر بڑھ جاتے ہوں گے"}],[5062,"براء بن عازب رضی اللہ عنہما کہتے ہیں کہ میں نے لال جوڑے میں رسول اللہ صلی اللہ علیہ وسلم سے زیادہ خوبصورت کسی آدمی کو نہیں دیکھا، اور میں نے دیکھا کہ آپ کے بال آپ کے مونڈھوں کے قریب تھے۔","الألباني: صحيح",{"u2":"سیدنا براء رضی اللہ عنہ نے فرمایا: میں نے کسی شخص کو سرخ حلہ پہنے ہوئے رسول اللہ صلی اللہ علیہ وسلم سے بڑھ کر خوب صورت نہیں دیکھا، نیز میں نے دیکھا کہ آپ کی زلفیں کندھوں کے قریب لہرایا کرتی تھیں۔","f2":"عربی میں سر کے لمبے بالوں کے لیے تین الفاظ استعمال کیے جاتے ہیں: وفرہ، وہ بال جو کانوں کے برابر تک ہوں، لمّہ، جو کانوں اور کندھوں کے درمیان ہوں اور جمّہ، وہ بال جو کندھوں سے ٹکراتے ہوں۔ پیارے رسول مکرم صلی اللہ علیہ وسلم کے مبارک بالوں کے بارے میں تینوں الفاظ عام استعمال کیے گئے ہیں۔ توجیہ سابقہ حدیث میں گزر چکی ہے۔"}],[5063,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ تم لوگ مجھے کس کی قرأت کے مطابق پڑھنے کے لیے کہتے ہو؟ میں نے رسول اللہ صلی اللہ علیہ وسلم سے ستر سے زائد سورتیں پڑھیں، اس وقت زید (زید بن ثابت) کی دو چوٹیاں تھیں، وہ بچوں کے ساتھ کھیل رہے تھے ۱؎۔\n§وضاحت\n۱؎: لمبے بال کو «ذوابہ» کہتے ہیں، نہ کہ عورتوں کی طرح بندھی ہوئی چوٹی کو، ابن مسعود رضی اللہ عنہ کے اس اثر نیز اگلی حدیث سے سر کے اتنے بڑے بالوں کا جواز ثابت ہوتا ہے، کیونکہ ان دونوں :(نبی اکرم صلی اللہ علیہ وسلم و ابن مسعود ) نے اس پر اعتراض نہیں کیا، لیکن آپ صلی اللہ علیہ وسلم نے لمبے بالوں کی بجائے انہیں چھوٹے کرنے کو زیادہ پسند کیا، جیسا کہ حدیث نمبر ۵۰۶۹ میں صراحت ہے :(نیز ملاحظہ ہو: فتح الباری: کتاب اللباس، باب الذوائب )۔","الألباني: صحيح لغيره",{"u2":"حضرت ہبیرہ بن مریم سے منقول ہے کہ سیدنا عبداللہ بن مسعود رضی اللہ عنہ نے فرمایا: تم مجھے کس کی قراءت کے مطابق پڑھنے پر مجبور کرتے ہو؟(زید کی؟) جب کہ حقیقت یہ ہے کہ میں رسول اللہ صلی اللہ علیہ وسلم کو ستر سے زائد سورتیں سنا چکا تھا جب کہ زید کے سر پر دو مینڈھیاں ہوتی تھیں۔ وہ بچوں کے ساتھ کھیلا کرتا تھا۔","f2":"سیدنا ابن مسعود رضی اللہ عنہ کا مقصد یہ ہے کہ میں قدیم الاسلام ہوں۔ قرآن کا بڑا قاری ہوں جب کہ حضرت زید بن ثابت توکل کا بچہ ہے۔ یہ مجھ سے بڑا قاری کیسے ہوسکتا ہے؟ اصل بات یہ ہے کہ حضرت ابوبکر، حضرت عمر اور حضرت عثمان رضی اللہ عنہما نے سیدنا زید بن ثابت رضی اللہ عنہ کو قرآن جمع کرنے اور ترتیب دینے پر مامور فرمایا۔ انہوں نے بڑی جانفشانی سے سیدنا ابوبکر رضی اللہ عنہ کے دور میں قرآن مجید جمع کیا اور سیدنا عثمان رضی اللہ عنہ کے دور میں قرآن مجید قریش کے لہجے میں مرتب فرمایا۔ ان کواس اہم کام پر مامور کرنے کی وجہ یہ تھی کہ وہ نوجوان اور تیز فہم تھے۔ قرآن مجید کے کاتب تھے۔ رسول اللہ صلی اللہ علیہ وسلم اور حضرت جبریل علیہ السلام کے درمیان ہوا تھا۔ گویا کہ وہ ناسخ منسوخ، قرآنی لہجہ اور ترتیب سور کے سب سے بڑے عالم اور واقف تھے۔ پھر ان کا حافظہ بھی قوی تھا، بخلاف اس کے سیدنا ابن مسعود رضی اللہ عنہ نے ابتدائی دور میں قرآن مجید پڑھا تھ۔ پھر وہ سیدنا عثمان رضی اللہ عنہ کے دور میں بوڑھے ہو چکے تھے۔ ظاہر ہے کہ بوڑھے آدمی کی یادداشت جوان آدمی کے برابر نہیں ہو سکتی مگر سیدنا ابن مسعود رضی اللہ عنہ اپنی بات پر اڑے رہے اور تمام صحابۂ کرام رضی اللہ عنہم کے متفقہ نسخۂ قرآن کی مخالفت کرتے رہے۔ یہ ان کی فرو گزاشت تھی مگر ان کی جلالت، قدر اوربزرگی کی وجہ سے انہیں معذور قرار دیا گیا اور ان پر سختی نہ کی گئی۔ رضی اللہ عنہ و ارضاہ"}],[5064,"ابووائل شقیق بن سلمہ کہتے ہیں کہ عبداللہ بن مسعود رضی اللہ عنہ نے ہم سے خطاب کرتے ہوئے کہا کہ تم لوگ مجھ سے زید بن ثابت کی قرأت کے مطابق پڑھنے کو کہتے ہو ۱؎، اس کے بعد کہ میں رسول اللہ صلی اللہ علیہ وسلم سے ستر سے زائد کئی سورتیں سن چکا ہوں، اس وقت زید بچوں کے ساتھ تھے، ان کی دو چوٹیاں تھیں؟۔\n§وضاحت\n۱؎: جب ابن مسعود رضی اللہ عنہ سے کہا گیا ہے کہ آپ عثمان رضی اللہ عنہ کے مصحف کے مطابق قرآن پڑھا کریں کیونکہ آپ کے مصحف اور اس میں فرق ہے، تب انہوں نے مصحف عثمانی کے جمع کرنے والے زید بن ثابت رضی اللہ عنہ کے بارے میں یہ بات کہی، آپ کی نظر اس بات پر نہیں گئی کہ عام صحابہ نے مصحف عثمانی ہی پر اجماع کیا، بہرحال بتصریح رسول اللہ صلی اللہ علیہ وسلم قرآن سات قراءتوں پر نازل ہوا، ابن مسعود صحابی رسول تھے، اور ان کو اپنے اوپر اعتماد تھا، لیکن مصحف عثمانی پر اجماع کے بعد اس کے مطابق پڑھنے پر اجماع امت ہے۔","الألباني: صحيح",{"u2":"حضرت ابووائل سے مروی ہے کہ سیدنا ابن مسعود رضی اللہ عنہ نے ہمیں خطاب فرمایا اور کہا: تم مجھے کس طرح مجبور کرتے ہوکہ میں زیدبن ثابت کی قراءت کے مطابق پڑھوں جب کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کی زبان مبارک سے ستر سے زیادہ سورتیں پڑھ لی تھیں اور زید ابھی بچوں کے ساتھ کھیلا کرتا تھا۔ اس کی دو مینڈھیاں ہوتی تھیں۔","f2":"بچوں کے بال قابو رکھنے کے لیے ان کی مینڈھیاں بنادی جاتی تھیں تاکہ کھیل کود میں بال خراب نہ ہوں۔ جب بچہ سمجھ دار ہوجاتا تھا تو مینڈھیوں کی ضرورت نہیں رہتی تھی۔ مقصدیہ ہے کہ وہ بچے تھے۔ حدیث سے مینڈھیوں کا جواز بھی معلوم ہوتا ہے۔"}],[5065,"حصین رضی اللہ عنہ کہتے ہیں کہ جب وہ نبی اکرم صلی اللہ علیہ وسلم کے پاس مدینے میں آئے تو آپ نے ان سے فرمایا: \"میرے قریب آؤ\"، وہ آپ کے قریب ہوئے تو آپ نے اپنا ہاتھ ان کی چوٹی پر رکھا اور اپنا ہاتھ پھرایا پھر اللہ کا نام لے کر انہیں دعا دی۔","الألباني: صحيح الإسناد",{"u2":"زیاد بن حصین اپنے والد محترم (حصین بن اوس رضی اللہ عنہ) سے بیان کرتے ہیں کہ جب وہ نبئ اکرم صلی اللہ علیہ وسلم کے پاس مدینہ منورہ پہنچے تو آپ نے ان ےس فرمایا: آگے آجاؤ۔ جب وہ آپ کے قریب آگئے تو آپ نے اپنا ہاتھ ان کے لمبے لمبے بالوں پر رکھا اور سارے سر پر ہاتھ پھیرا اور ان کو دعا دی اور خوب دعا دی۔","f2":"’ذؤابہ‘ مینڈھی کو بھی کہتے ہیں، یعنی گندھے ہوئے بال۔ اور لٹکتے ہوئےبالوں کو بھی کہہ دیا جاتا ہے جنہیں زلفیں بھی کہا جاتا ہے۔ ویسے زلفیں ان بالوں کو کہا جاتا ہے جو چہرے پر لٹکتے ہوں۔ واللہ اعلم"}],[5066,"وائل بن حجر رضی اللہ عنہ کہتے ہیں کہ میں نبی اکرم صلی اللہ علیہ وسلم کے پاس گیا، میرے سر پر لمبے بال تھے، آپ نے فرمایا: \"نحوست ہے\"، میں سمجھا کہ آپ کی مراد میں ہی ہوں۔ میں گیا اور اپنے بال کتروا دیئے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"میری مراد تم نہیں تھے، ویسے یہ زیادہ اچھا ہے\"۔","الألباني: صحيح",{"u2":"سیدنا وائل بن حجر رضی اللہ عنہ بیان کرتے ہیں کہ میں نبئ اکرم صلی اللہ علیہ وسلم کے پا حاضر ہوا تو میرے لمبے لمبے بال تھے۔ آپ نے فرمایا: (یہ) منحوس چیز ہے۔ میں نے سمجھا کہ آپ مجھے کہہ رہے ہیں۔ میں اٹھا اور اپنے بال کاٹ کر پھر حاضر ہوا تو آپ نے فرمایا: میں نے تجھے نہیں کہا تھا۔ ویسے یہ زیادہ اچھی حالت ہے۔","f2":"زیادہ لمبے بالوں کی حفاظت مشکل ہوتی ہے، نیز اس میں عورتوں سے مشابہت ہے، لہذا کٹوا لینے چاہییں۔"}],[5067,"رویفع بن ثابت رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اے رویفع! شاید میرے بعد تمہاری عمر لمبی ہو، لہٰذا تم لوگوں کو بتا دینا کہ جس نے کر اپنی داڑھی میں گرہ لگائی یا گھوڑے کے گلے میں تانت ڈالی (کہ نظر نہ لگے) یا کسی چوپائے کے گوبر یا ہڈی سے استنجاء کیا تو محمد اس سے بری ہیں\"۔","الألباني: صحيح",{"u2":"سیدنا رویفع بن ثابت رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اے رویفع! شاید تو میرے بعد عرصۂ درازتک زندہ رہے، لہذا لوگوں کو بتا دینا کہ جس شخص نے اپنی ڈاڑھی کو گرہیں دیں یا گلے میں تندی ڈالی یا جانور کے گوبر اور ہڈی سے استنجا کیا تو محمد صلی اللہ علیہ وسلم سے اس کا کوئی تعلق نہیں۔","f2":"1۔ جانور کی ہڈی اور اس کے گوبرسے استنجا کرنا ممنوع ہے جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا ہے۔2۔ ان کاموں سے خاص طور پر دور رہنا چاہیے جن کے ارتکاب پر رسول اللہ صلی اللہ علیہ وسلم نے اظہار براءت فرمایا ہے۔ اس سے بڑھ کر ناکامی اور خسارہ کیا ہوسکتا ہے کہ رسول اللہ صلی اللہ علیہ وسلم یہ فرمادیں کہ فلاں شخص سےمیں بری ہوں۔ اس کے ساتھ میرا کوئی تعلق نہیں۔ اعاذنا اللہ منہ۔ 3۔شاید، یہ دراصل پیش گوئی تھی کہ میرے بعد عرصۂ درازتک زندہ رہے گا۔ اور واقعتاً ایسے ہی ہوا۔ سیدنا رویفع رضی اللہ عنہ 53ھ میں فوت ہوئے اور افریقہ میں فوت ہونے والے آخری صحابی یہی ہیں۔ ’شاید‘ کا لفظ اظہار عبدیت کے لیے ہے، جیسے ان شاء اللہ کہا جاتا ہے۔4۔ ’ڈاڑھی کو گرہیں دیں ‘جیسے عموماً سکھوں میں دیکھا جاتا ہے یا بالوں کو بل دے کر ویسے ہی گرہیں دی جائیں، دونوں صورتیں ہی مذموم ہیں۔ بعض لوگ بالوں کو اس طرح بل دیتے اور لپیٹتےہیں کہ بڑی سے بڑی ڈاڑھی بھی چھوٹی ہوتی ہے اور بآسانی کھل کر لٹکتی بھی نہیں۔ اگرچہ بظاہر ڈاڑھی میں گانٹھ محسوس تونہیں ہوتی لیکن نتیجے میں اس سے کم بھی نہیں ہوتی، اس لیے اس صورت تلفیف سے بھی اجتناب بہتر ہے۔ ڈاڑھی میں سنت طریقہ تسریح ہے، یعنی اسے کھلا چھوڑا جائے۔ ڈاڑھی کو بل دے کر اوپر چڑھا لینا ایک غیر ضروری تکلف سا لگتا ہے، لہذا اس سے احترازبہتر ہے۔ بعض نے اس سے مراد یہ لیا ہے کہ نماز کے دوران میں ڈاڑھی سے کھیلتے نہیں رہنا چاہیے۔ یا نماز شروع کرنے سے پہلے ڈاڑھی کو مٹی سے بچانے کےلیے گرہ نہیں دینی چاہیے، جیسے آپ نے سر کے بال باندھنے اور کپڑے سمیٹنے سے روکا ہے۔ گویا نماز میں اپنے جسم وغیرہ کو مٹی سے بچانے ہی کو فکر نہیں کرتے رہنا چاہیے بلکہ توجہ نماز کی طرف ہی رہنی چاہیے۔5۔ ’تندی ڈال‘ ذبح شدہ جانور کے پٹھے کی رگ کو تندی کہتے ہیں۔ یہ بہت مضبوط ہوتی ہے۔ قوس کے کناروں کو باندھی جاتی ہے تاکہ لچک کی وجہ سے تیر دور پھینکنے میں مدد ملے۔ جاہلیت میں لوگ کاہنوں سے تندی پڑھوا کر اپنے گلے میں ڈالتے تھے تاکہ نظر بد سے محفوظ رہیں۔ چونکہ کاہن شرکیہ الفاظ پڑھتے تھے، لہذا اس سے منع فرمایا۔6۔ ’گوبر اور ہڈی سے استنجا‘ کیونہ ان سے صفائی نہیں ہوتی، اس لیے ان سے استنجاء کرنا منع ہے، نیز یہ جنوں کی خوراک ہیں۔ گوبر ویسے بھی گندگی کی طرح ہے۔"}],[5068,"زہری کہتے ہیں کہ ہمیں یہ بات پہنچی ہے کہ رافع بن خدیج رضی اللہ عنہ اپنے دو چچاؤں سے جو ان کے خیال میں غزوہ بدر میں شریک تھے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے زمین کرائے پر اٹھانے سے منع فرمایا۔ اسے عثمان بن سعید نے بھی شعیب سے روایت کیا ہے اور اس میں ان کے دونوں چچاؤں کا ذکر نہیں کیا ہے۔\nعمرو بن دینار کہتے ہیں کہ میں نے ابن عمر رضی اللہ عنہما کو کہتے سنا: ہم مخابرہ میں کوئی حرج نہیں سمجھتے تھے۔ یہاں تک کہ جب پہلا سال ہوا تو رافع رضی اللہ عنہ نے بتایا کہ نبی اکرم صلی اللہ علیہ وسلم نے اس سے روکا ہے۔ «عارم» محمد بن فضل نے یحیی بن عربی کی مخالفت کی ہے۔ اور اسے بسند «عن حماد عن عمرو عن جابر» روایت کیا ہے۔\nعبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سفید بال اکھاڑنے سے منع فرمایا۔","الألباني: صحيح لغيره",{"u2":"حضرت عمرو بن شعیب کے پردادا محترم (حضرت عبداللہ بن عمرو رضی اللہ عنہما) سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سفید بال اکھیڑنے سے منع فرمایا ہے۔","f2":"1۔یہ حدیث مبارکہ ڈاڑھی اور سر کے سفید بال باقی رکھنے اور ان کو زائل نہ کرنے پر دلالت کرتی ہے، اس لیے کہ مومن کے سفید بالوں کی بابت رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «هو نور مالمؤمن» وہ مومن کا نور ہے۔(سنن ابن ماجہ، ابواب الادب، باب نتف الشیب، حدیث:3721) سنن ابوداؤد کی روایت میں یہ وضاحت بھی موجود ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس مسلمان کے بال حالتِ اسلام میں سفید ہو جائیں قیامت کے دن یہ اس کے لیے نور ہوں گے۔ مزید برآں آپ نے یہ بھی فرمایا ہے کہ اللہ تعالی اس کے ایک ایک بال کے عوض اس کی نیکی لکھتا ہے اوراس کے عوض اس سے ایک گناہ دور کرتا ہے۔(سنن ابی داؤد، الترجل، باب فی تنف الشیب، حدیث:4202)۔2۔ یہاں ایک اشکال وارد ہوتا ہے کہ احادیث میں رسول اللہ صلی اللہ علیہ وسلم نے سفید بال رنگنے کا حکم بھی دیا ہے۔ دونوں قسم کی ان احادیث میں تطبیق یہ ہوسکتی ہے کہ سفید بالوں کو رنگنے کا حکم صرف یہودو نصاریٰ کی مخالفت کرنے کےلیے دیا گیا ہے کیونکہ یہ اپنے سفید بالوں کو نہیں رنگتے۔ یہ بھی ہوسکتا ہے کہ جب بال حالت اسلام میں سفید ہوجائیں تو پھر رنگنے کے باوجود بھی مومن مذکورہ فضیلت کا مستحق قرار پاتا ہے۔ واللہ اعلم"}],[5069,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یہود و نصاری خضاب نہیں لگاتے، لہٰذا تم ان کی مخالفت کرو\"۔\n§وضاحت\n۱؎: یعنی ان کی مخالفت میں خضاب لگاؤ۔","الألباني: صحيح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: یہودی اور عیسائی سفید بالوں کو نہیں رنگتے، لہذا تم ان کی مخالفت کرو۔","f2":"1۔مخالفت کرنے سے مراد بال رنگنا ہے اور اس کی کئی صورتیں ہیں:٭ان کو سیاہ رنگ سے رنگ لیا جائے۔ لیکن حدیث میں اس کی ممانعت ہے۔٭ حنا، یعنی مہندی سے رنگا جائے اور حنا کا رنگ معروف ہے یعنی سرخ۔٭ حنا اور کتم سے رنگا جائے اور یہ رنگ سیاہی مائل سرخ ہوتا ہے۔2۔ ڈاڑھی اور سرکے بالوں کو رنگنا واجب ہے یا مستحب؟اس مسئلے میں اہل علم کا اختلاف ہے، تاہم حق یہ ہے کہ احادیث مبارکہ میں بالوں کو رنگنے ہی کا حکم ہے کیونکہ رسول اللہ صلی اللہ علیہ وسلم کا فرمان ہے:«ان اليهود والنصارى لايصبغون فخالفوهم» یہودی اورعیسائی اپنے بال نہیں رنگتے، تم ان کی مخالفت کرو، یعنی بالوں کو رنگو۔(صحیح البخاری، اللباس، باب الخضاب، حدیث:5899، وصحیح مسلم، اللباس، باب فی مخالفۃ الیہود فی الصبغ، حدیث:2103) اس حدیث میں مطلقاً مخالفت کاحکم ہے۔ مطلب یہ ہے کہ بالوں کو سفید نہ رہنے دو بلکہ ان کو رنگ لو، خواہ کسی رنگ سے ہو، بالوں کو کالا کرنے کے قائل اسی مطلق حکم سے استدلال کرتےہیں لیکن یہ استدلال درست نہیں کیونکہ نبی صلی اللہ علیہ وسلم نے بالکل سیاہ رنگ کے خضاب سے منع فرمایا ہے جیسا کہ صحیح مسلم میں ہے کہ فتح مکہ والے دن سیدنا ابوبکر صدیق رضی اللہ عنہ کے والد سیدنا ابوقحافہ رضی اللہ عنہ کو نبی صلی اللہ علیہ وسلم کی خدمت میں لایا گیا تو ان کےسر اور ڈاڑھی کے بال ثغامہ بوٹی کی طرح سفید تھے۔ نبی صلی اللہ علیہ وسلم نے انہیں دیکھ کر فرمایا:«غيروا هذا بشئ واجتنبوا لسواد» اسے کسی رنگ سے بدل دو لیکن سیاہ رنگ سے بچنا۔ (صحیح مسلم، اللباس، باب استحباب خضاب الشیب.... حدیث:2102) اس حدیث مبارکہ سے واضح ہوگیا کہ سراور ڈاڑھی کے بالوں کو رنگنے کا حکم تو ہے لیکن کالے رنگ کے علاوہ کسی اور رنگ سے انہیں رنگا جائے گا۔ باقی رہا یہ مسئلہ کہ بالوں کو رنگنا فرض ہے یا مستحب؟تو اس کے متعلق علماء کی دونوں رائے ہیں۔ بعض اہل علم و جوب کے قائل ہیں اور بعض اسے مستحب ہی سمجھتے ہیں۔ ہمارے خیال میں استحباب والا موقف اقرب الی الصواب ہے۔\nحافظ عبدالمنان رحمہ اللہ ایک استفتا کا جواب دیتے ہوئے رقم طراز ہیں: احادیث میں رسول اللہ صلی اللہ علیہ وسلم کےبالوں کو رنگنے کا بھی ذکر ہے اور نہ رنگنے کا بھی جس سے پتا چلتا ہے کہ آپ کا رنگنے سےمتعلق امرندب(استحباب) پرمحمول ہے، البتہ کل کے کل بال سفید ہوجائیں کوئی ایک بال بھی سیاہ نہ رہے تو پھر رنگنے کی مزیدتاکید ہے جیسا کہ ابوقحافہ، والد ابی بکر رضی اللہ عنہما والی حدیث سے عیاں ہے۔ دیکھئے (احکام ومسائل:1؍531) مولانا صفی الرحمن مبارک پوری رحمہ اللہ صحیح مسلم کی شرح میں لکھتے ہیں’ خضاب کا حکم استحباب کےلیے ہونا چاہیے نہ کہ وجوب کے لیے، اس کےلیے کہ حضرت علی، ابی بن کعب، سلمہ بن اکوع اور حضرت انس اور صحابہ کی ایک جماعت نے خضاب کے حکم پر عمل نہیں کیا۔ رضی اللہ عنہما۔ مزید برآں یہ کہ ان کے علاوہ دوسرے بہت سے صحابۂ کرام رضی اللہ عنہم کا طرز عمل بھی اس پر شاید ہے۔ گویا انہوں نے اس کی ضرورت محسوس نہیں کی۔ سیدنا ابوبکر رضی اللہ عنہ ان میں ممتاز ہیں۔"}],[5070,"سعد بن ابی وقاص رضی اللہ عنہ کہتے ہیں کہ کھیتوں والے لوگ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں اپنے کھیت کرائیے پر اس اناج کے بدلے دیا کرتے تھے جو کھیتوں کی مینڈھوں پر ہوتا ہے۔ تو وہ لوگ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور اس سلسلے میں کسی چیز کے بارے میں انہوں نے جھگڑا کیا۔ تو آپ نے انہیں اس کے (غلہ کے) بدلے کرائے پر دینے سے منع فرما دیا اور فرمایا: \"سونے چاندی کے بدلے کرائے پر دو\"۔ اس حدیث کو سلیمان بن یسار نے بھی رافع بن خدیج رضی اللہ عنہ سے روایت کیا ہے، لیکن انہوں نے اسے اپنے چچاؤں میں کسی چچا کی حدیث سے روایت کیا ہے۔\nانس بن مالک رضی اللہ عنہ کہتے ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم کا انتقال ہوا تو بعض عرب مرتد ہو گئے، عمر رضی اللہ عنہ نے کہا: ابوبکر! آپ عربوں سے کیسے جنگ کریں گے؟ ابوبکر رضی اللہ عنہ نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے تو فرمایا ہے: \"مجھے حکم دیا گیا ہے کہ میں لوگوں سے اس وقت تک جنگ کروں جب تک کہ وہ گواہی نہ دیں کہ اللہ کے سوا کوئی حقیقی معبود نہیں اور یہ کہ میں اللہ کا رسول ہوں، اور وہ نماز قائم نہ کریں اور زکاۃ نہ دیں، اللہ کی قسم! اگر وہ بکری کا ایک بچہ ۱؎ بھی روکیں گے جو وہ رسول اللہ صلی اللہ علیہ وسلم کو دیا کرتے تھے تو میں اس کے لیے ان سے جنگ کروں گا\"۔ عمر رضی اللہ عنہ کہتے ہیں: جب میں نے ابوبکر رضی اللہ عنہ کی رائے دیکھی کہ انہیں اس پر شرح صدر ہے تو میں نے جان لیا کہ یہی حق ہے ۲؎۔\n§وضاحت\n۱؎: یا تو یہ بطور مبالغہ ہے، یا یہ مراد ہے کہ اگر کسی کو بکریوں کی زکاۃ میں مطلوب عمر کی بکری نہ موجود ہو تو اس کی جگہ بکری کا بچہ بھی دے دینا کافی ہو گا۔۲؎: معلوم ہوا کہ صرف کلمہ شہادت کا اقرار کر لینا کافی نہیں ہو گا جب تک عقائد، اصول اسلام اور احکام اسلام کی کتاب وسنت کی روشنی میں پابندی نہ کرے، گویا کلمہ شہادت ذریعہ ہے شعائر اسلام کے اظہار کا اور شعائر اسلام کی پابندی ہی نجات کا ضامن ہے۔\nابوہریرہ رضی اللہ عنہ کہتے ہیں کہ (ارتداد کا فتنہ ظاہر ہونے پر) ابوبکر رضی اللہ عنہ نے ان مرتدین سے جنگ کرنے کی ٹھان لی، تو عمر رضی اللہ عنہ نے کہا: ابوبکر! آپ لوگوں سے کیوں کر لڑیں گے حالانکہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: \"مجھے حکم دیا گیا ہے کہ میں لوگوں سے لڑوں جب تک کہ وہ لا الٰہ الا اللہ نہ کہیں، جب وہ یہ کہنے لگیں تو ان کے خون، ان کے مال مجھ سے محفوظ ہو گئے مگر (جان و مال کے) حق کے بدلے\"، ابوبکر رضی اللہ عنہ نے کہا: میں ہر اس شخص سے لازماً جنگ کروں گا جو نماز اور زکاۃ کے درمیان تفریق کرے گا۔ اللہ کی قسم! اگر یہ لوگ مجھ سے بکری کا ایک بچہ بھی روکیں گے جسے وہ رسول اللہ صلی اللہ علیہ وسلم کو دیا کرتے تھے تو اسے روکنے پر ان سے جنگ کروں گا\"۔ عمر رضی اللہ عنہ کہتے ہیں: یہ اس کے سوا کچھ نہ تھا کہ میں نے دیکھا کہ اللہ تعالی نے ابوبکر رضی اللہ عنہ کے سینے کو ان مرتدین سے جنگ کرنے کے لیے کھول دیا ہے، تو میں نے جان لیا کہ یہی حق ہے۔\nابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مجھے حکم دیا گیا ہے کہ میں لوگوں سے اس وقت تک جنگ کروں جب تک کہ وہ \"لا الٰہ الا اللہ\" نہ کہیں، پھر جب وہ اسے کہہ لیں تو انہوں نے مجھ سے اپنا خون اور اپنے مال محفوظ کر لیے مگر اس کے (جان و مال کے) حق کے بدلے، اور ان کا حساب اللہ تعالی پر ہے\"۔\nابوایوب انصاری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو اللہ تعالی کی عبادت کرتا ہے، اس کے ساتھ کسی کو شریک نہیں کرتا، نماز قائم کرتا ہے، زکاۃ دیتا ہے اور کبائر سے دور اور بچتا ہے۔ اس کے لیے جنت ہے\"، لوگوں نے آپ سے کبائر کے بارے میں پوچھا تو آپ نے فرمایا: \"اللہ کے ساتھ شریک کرنا، کسی مسلمان جان کو (ناحق) قتل کرنا اور لڑائی کے دن میدان جنگ سے بھاگ جانا\"۔\n§وضاحت\n۱؎: کبیرہ: ہر اس گناہ کو کہتے ہیں جس کے مرتکب کو جہنم کے عذاب اور سخت وعید کی دھمکی دی گئی ہو، ان میں سے بعض کا تذکرہ احادیث میں آیا ہے، اور جن کا تذکرہ لفظ کبیرہ کے ساتھ نہیں آیا ہے مگر مذکورہ سزا کے ساتھ آیا ہے، وہ بھی کبیرہ گناہوں میں سے ہیں۔ کبائر تین طرح کے ہیں: :(۱ ) پہلی قسم اکبر الکبائر کی ہے جیسے اشراک باللہ اور نبی اکرم صلی اللہ علیہ وسلم جو کچھ لائے ہیں اس کی تکذیب کرنا۔ :(۲ ) اور دوسرے درجے کے کبائر حقوق العباد کے تعلق سے ہیں مثلاً کسی کو ناحق قتل کرنا، دوسرے کا مال غصب کرنا اور ہتک عزت کرنا وغیرہ۔ :(۳ ) تیسرے درجے کے کبائر کا تعلق حقوق اللہ سے ہے، مثلاً زنا اور شراب نوشی وغیرہ۔ :(جیسے حدیث رقم ۴۰۱۷ ) میں کبائر کی تعداد سات آئی ہے، لیکن متعدد احادیث میں ان سات کے علاوہ کثیر تعداد میں دیگر گناہوں کو بھی کبیرہ کہا گیا ہے۔ اس لیے وہاں حصر اور استقصاء مقصود نہیں ہے :(دیکھئیے: فتح الباری کتاب الحدود، باب رمی المحصنات )۔\nعبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اس ذات کی قسم جس کے سوا کوئی معبود برحق نہیں! کسی مسلمان کا خون جو گواہی دے کہ اللہ کے سوا کوئی معبود (برحق) نہیں اور میں اللہ کا رسول ہوں حلال نہیں، سوائے تین افراد کے: ایک وہ جو (مسلمانوں کی) جماعت سے الگ ہو کر اسلام کو ترک کر دے، دوسرا شادی شدہ زانی، اور تیسرا جان کے بدلے جان ۱؎۔ اعمش کہتے ہیں: میں نے یہ حدیث ابراہیم نخعی سے بیان کی تو انہوں نے اس جیسی حدیث مجھ سے اسود کے واسطے سے عائشہ سے روایت کرتے ہوئے بیان کی۔\n§وضاحت\n۱؎: یعنی اگر کوئی دین اسلام سے مرتد ہو گیا، یا شادی شدہ ہو کر بھی زنا کر لیا، یا کسی کو ناحق قتل کیا ہے، تو اسے ان جرائم کی بنا پر اس کا خون حلال ہو گیا لیکن اس کے خون لینے کا کام اسلامی حکومت کا ہے نہ کہ سماج کا۔\nاس سند سے بھی ابوہریرہ رضی اللہ عنہ کے واسطے سے رسول اللہ صلی اللہ علیہ وسلم سے اسی جیسی روایت مروی ہے۔","الألباني: حسن",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم سے سابقہ روایت کی مثل حدیث بیان کرتے ہیں۔"}],[5071,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم اللہ تعالی کو پیارے ہو گئے اور ابوبکر رضی اللہ عنہ آپ کے خلیفہ بنے اور عربوں میں سے جن لوگوں کو کافر ہونا تھا کافر ہو گئے تو عمر رضی اللہ عنہ نے ابوبکر رضی اللہ عنہ سے کہا: آپ لوگوں سے کیسے لڑیں گے؟ حالانکہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے:\"مجھے حکم دیا گیا کہ میں لوگوں سے اس وقت تک جنگ کروں جب تک کہ وہ \"لا الٰہ الا اللہ\" نہ کہیں، پس جس نے \"لا الٰہ الا اللہ\" کہا اس نے اپنا مال اور اپنی جان مجھ سے محفوظ کر لی مگر اس کے (یعنی جان و مال کے) حق کے بدلے، اور اس کا حساب اللہ پر ہے\"۔ ابوبکر رضی اللہ عنہ نے کہا: اللہ کی قسم! میں ہر اس شخص سے جنگ کروں گا جو نماز اور زکاۃ میں فرق کرے گا، اس لیے کہ زکاۃ مال کا حق ہے۔ اللہ کی قسم! اگر یہ لوگ رسی کا ایک ٹکڑا ۱؎ بھی جسے رسول اللہ صلی اللہ علیہ وسلم کو دیتے تھے مجھے دینے سے روکیں گے تو میں اس کے نہ دینے پر ان سے جنگ کروں گا\"۔ عمر رضی اللہ عنہ کہتے ہیں: اللہ کی قسم! یہ اس کے سوا کچھ نہ تھا کہ میں نے سمجھا کہ اللہ تعالی نے ابوبکر رضی اللہ عنہ کے سینے کو جنگ کے لیے کھول دیا ہے، اور میں نے یہ جان لیا کہ یہی حق ہے۔\n§وضاحت\n۱؎: یا تو یہ مبالغہ کے طور پر استعمال کیا گیا ہے، کیونکہ بکریوں کی کسی تعداد پر زکاۃ میں رسی واجب نہیں ہے، یا \" عقال \" سے مراد مطلق زکاۃ ہے، اور ایسا شرعی لغت میں مستعمل بھی ہے، اس صورت میں اس عبارت کا معنی ہو گا \" تو اگر کوئی زکاۃ دیا کرتا تھا تو اب اس کے روکنے پر میں اس سے قتال کروں گا \" واللہ اعلم۔\nابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مجھے حکم دیا گیا ہے کہ میں لوگوں سے اس وقت تک جنگ کروں جب تک کہ وہ \"لا الٰہ الا اللہ\" نہ کہیں، جب وہ اسے کہہ لیں تو انہوں نے مجھ سے اپنا خون اور اپنا مال محفوظ کر لیے مگر (جان و مال کے) حق کے بدلے اور اس کا حساب اللہ تعالی پر ہو گا\"۔\nابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یہود و نصاری خضاب نہیں لگاتے، لہٰذا تم ان کی مخالفت کرو اور خضاب لگاؤ\"۔","الألباني: صحيح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: یہودی اور عیسائی بال نہیں رنگتے۔ تم ان کی مخالفت کرو اوربال رنگو۔"}],[5072,"ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"یہود و نصاری خضاب نہیں لگاتے، لہٰذا تم ان کی مخالفت کرو\"۔","الألباني: صحيح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبئ اکرم صلی اللہ علیہ وسلم نے فرمایا: یہودی اور عیسائی بال نہیں رنگتے۔ تم ان کی مخالفت کرو۔"}],[5073,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بڑھاپے کا رنگ بدلو اور یہود کی مشابہت اختیار نہ کرو\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما سےروایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: سفید بالوں کو رنگ سے بدل لیا کرو اور یہودیوں سے مشابہت نہ کرو۔"}],[5074,"زبیر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بڑھاپے کا رنگ بدلو اور یہودیوں کی مشابہت اختیار نہ کرو\"، یہ دونوں روایتیں محفوظ نہیں ہیں ۱؎۔\n§وضاحت\n۱؎: عروہ کبھی اس کو ابن عمر رضی اللہ عنہما کی حدیث سے روایت کرتے ہیں، اور کبھی زبیر رضی اللہ عنہ کی حدیث سے، اور کبھی عائشہ رضی اللہ عنہا کی حدیث سے، اسی وجہ سے مؤلف نے \" غیر محفوظ \" کہا ہے، جب کہ یہ بالکل ممکن ہے کہ عروہ نے تینوں سے یہ روایت کی ہو، نیز اس کے صحیح شواہد موجود ہیں۔","الألباني: صحيح",{"u2":"سیدنا زبیر رضی اللہ عنہ سےروایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: سفید بالوں کو رنگ لیا کرو اور یہودیوں کی مشابہت اختیار نہ کرو۔ یہ دونوں روایتیں غیر محفوظ ہیں۔","f2":"بالوں سے مراد سر، ڈاڑھی اور مونچھوں کے بال ہیں، اس لیے تمام بالوں کی بابت حکم یہی ہے، نیز یہ بھی یادر ہے کہ دیگر احکام کی طرح اس حکم میں بھی عورتیں مردوں کے تابع ہیں، یعنی انہوں نے اپنے سفید بال رنگنےہوں تو وہ بھی انہیں کالے رنگ سے نہ رنگیں بلکہ کسی اور رنگ ہی سے رنگیں۔"}],[5075,"عبداللہ بن عباس رضی اللہ عنہما سے مرفوعاً روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اخیر زمانے میں کچھ لوگ ایسے ہوں گے جو کبوتر کے پوٹوں کی طرح کالا خضاب لگائیں گے، انہیں جنت کی خوشبو نصیب نہ ہو گی\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما سے مرفوعاً روایت ہے کہ آخری زمانے میں ایسے لوگ ہوں گے جو سیاہ رنگ سے اپنے بال رنگیں گے جیسے کبوتروں کے سینے ہوتےہیں۔ وہ جنت کی خوشبو بھی نہیں پائیں گے۔","f2":"1۔ بالوں کو رنگنے کے حوالے سے نوجوان لڑکے اور لڑکیاں فی زمانہ مختلف بے اعتدالیوں کا شکار ہیں، مثلاً: بالوں وغیرہ کو ڈائی کرانا، یعنی جیسا لباس ویسے ہی بالوں کی رنگت اور اسی طرح آنکھوں میں، ڈائی شدہ بالوں اور لباس کی مناسبت سے لینزوغیرہ لگوانا۔ یہ کام نہ صرف ناجائز ہیں بلکہ اس میں کفار کی عورتوں کے ساتھ مشابہت بھی یقینی ہے۔اس کے ساتھ ساتھ یہ تغییر تخلیق اللہ بھی ہے، یعنی اللہ کی تخلیق کو بدلنا اور اس میں تبدیلی کرنا بھی ہے، لہذا اہل اسلام کی یہ شرعی اور اخلاقی ذمہ داری ہے کہ وہ اپنی بہو، بیٹیوں، اور دیگر متعلقہ خواتین کو اس قبیح کام سے روکیں، انہیں اللہ تعالی، اس کے رسول اللہ صلی اللہ علیہ وسلم اور قرآن و حدیث کی صریح مخالفت کرنے سے باز رکھیں اور آخرت کی۔ معاذ اللہ۔ ناکامی ونامرادی کا خوف دلائیں۔ اغیار، یعنی غیر مسلموں، یہودیوں، عیسائیوں اور ہندوؤں وغیرہ کی دیکھا دیکھی، نیز’ روشن خیالی‘ کے نام پر ہم روز بروز دین سے دور سے دور تر ہوتے جارہے ہیں اور اپنی اولاد کو جہنم کا ایندھن بنارہے ہیں اور یہ سب کچھ ٹھنڈے پیٹوں برداشت کررہے ہیں۔اللہ تعالی ہمیں اس دنیوی و اخروی خسارے سے محفوظ فرمائے۔ آمین۔2۔ سیاہ خضاب کا استعمال حرام ہے، جس کی سزا یہ ہے کہ ایسا انسان جنت کی خوشبو بھی نہیں پا ئے گا۔3۔ مرفوعاً یعنی یہ رسو ل اللہ کا فرمان ہے۔ 4۔ ’ جیسے کبوتروں کے سینے‘ کبوتر کا سینہ عموماً سیاہ ہوتاہے۔ اور مثال عموم کے لحاظ سے ہوتی ہے نہ کہ چند افراد کے لحاظ سے۔ 5۔ ’ خوشبو نہیں پائےگا۔‘ یعنی جنت میں داخل ہونے کے باوجود یا اولین طور پر جنت میں نہیں جائیں گے بلکہ انہیں سزا بھگتنا ہوگی۔"}],[5076,"جابر رضی اللہ عنہ کہتے ہیں کہ ابوقحافہ رضی اللہ عنہ کو فتح مکہ کے دن لایا گیا، سفیدی میں ان کا سر اور ڈاڑھی دونوں «ثغامہ» کی طرح سفید تھے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اس کو کسی اور رنگ سے بدل لو، لیکن کالے رنگ سے دور رہنا\"۔\n§وضاحت\n۱؎: «ثغامہ» ایک گھاس ہے جس کے پھل اور پھول سب سفید ہوتے ہیں۔","الألباني: صحيح",{"u2":"سیدنا جابر رضی اللہ عنہ سے روایت ہے، انہوں نے فرمایا کہ سیدنا ابوقحافہ رضی اللہ عنہ کو فتح مکہ کے دن لایا گیا تو ان کے سر اور ڈاڑھی کے بال ثغامہ پودے(کے پھل اور پھول) کی طرح بالکل سفید تھے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ان کو کسی رنگ سے بدل دو مگر سیاہ رنگ سے پرہیز کرنا۔","f2":"1۔ثغامہ ایک پودا ہے جو پہاڑ کی چوٹی پراگتا ہے۔ اس کو سفید پھل اور پھول لگتے ہیں۔ جب وہ خشک ہوجاتا ہے تو اس کی سفیدی بڑھ جاتی ہے۔ اور پھولوں کی کثرت کی بنا پر دور سے درخت بھی سفید ہی نظر آتا ہے۔2۔ ’پرہیز کرنا‘ جب بوڑھے شخص کو جس سے دھوکے کا خطرہ نہیں، سیاہ رنگ منع ہے تو جس شخص میں دھوکے کا امکان ہے، اسے کیسے اس کی اجازت ہوسکتی ہے۔3۔ ’ابوقحافہ‘ حضرت ابوبکر صدیق کے والد گرامی تھے۔"}],[5077,"ابوذر رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"سب سے بہتر چیز جس سے تم بڑھاپے کا رنگ بدلو مہندی اور «کتم» ہے\"۔\n§وضاحت\n۱؎: «کتم» ایک پودا ہے جسے مہندی کے ساتھ ملاتے ہیں، ان دونوں کو ملا کر استعمال سے بالوں کا رنگ سیاہی مائل ہو جاتا ہے۔","الألباني: صحيح",{"u2":"سیدنا ابوذر رضی اللہ عنہ سے روایت ہے کہ نبئ اکرم صلی اللہ علیہ وسلم نے فرمایا: ’بہترین وہ چیز جس کے ساتھ تم سفید بالوں کو رنگو، مہندی اور وسمہ ہے","f2":"1۔اس حدیث مبارکہ سے معلوم ہوتا ہے کہ مہندی اور وسمے کا خضاب بہترین اور افضل ہے، نیز خضاب صرف یہی دو چیزیں (مہندی اور وسمہ) ہی نہیں بلکہ دیگر بھی کئی ایک خضاب ہیں۔ احتیاط صرف کا لے سیاہ خضاب کرنے سے ہے اور یہ ممانعت مرد اور عورت کے لیے یکساں ہے۔2۔ یہ حدیث مبارکہ مخلوط اشیاء سے بنائے گئے خضاب کے استعمال پر بھی دلالت کرتی ہے۔3۔ مہندی اور وسمہ دونوں کو ملانے سے رنگ خالص سیاہ نہیں رہتا بلکہ سر خی مائل ہوجاتا ہے۔"}],[5078,"ابوذر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سب سے بہتر چیز جس سے تم بڑھاپے کا رنگ بدلو مہندی اور «کتم» ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوذر سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نےفرمایا: ’ بہترین وہ چیز جس سے تم سے سفید بالوں کا رنگ بدلو، مہندی اور وسمے کا آمیزہ ہے۔‘"}],[5079,"ابوذر رضی اللہ عنہ کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"سب سے بہتر چیز جس سے تم بڑھاپے کا رنگ بدلو، مہندی اور کتم ہے\"۔","الألباني: صحيح",{"u2":"سیدنا ابوذر رضی اللہ عنہ بیان کرتے ہیں کہ میں نے نبئ اکرم صلی اللہ علیہ وسلم کو فرماتے سنا:’ سب سے اچھی چیز جس کے ساتھ تم سفید بالوں کو رنگ دار کرو، مہندی اور وسمے کا مرکب ہے۔"}],[5080,"ابوذر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سب سے بہتر چیز جس سے تم بڑھاپے کا رنگ بدلو، مہندی اور کتم ہے\"۔ جریری اور کہمس نے ان کی مخالفت کی ہے ۱؎۔\n§وضاحت\n۱؎: یعنی اجلح کی مخالفت کی ہے، اور دونوں کی سندوں میں انقطاع ہے جو واضح ہے :(ان دونوں کی روایتیں آگے آ رہی ہیں )۔","الألباني: صحيح",{"u2":"سیدنا ابوذر رضی اللہ عنہ سےروایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: بہترین وہ جیز جس سے تم سفید بالوں کو رنگین کرو، مہندی اور وسمے کا مجموعہ ہے۔\nجریری اور کہمس نے(اس روایت کے بیان کرنے میں اجلح کی) مخالفت کی ہے۔","f2":"مخالفت کی وجہ یہ ہے کہ اجلح اپنی سند سے اسے متصل بیان کرتے ہیں، جبکہ سعید الجریری اور کہمس بن حسن نے اسے مرسل بیان کیا ہے۔ لیکن اس سے صحت حدیث پر کوئی فرق نہیں پڑتا کیونکہ متصل روایت کی دیگر روایات سے تائید ہوتی ہے، بالخصوص عبدالرحمن بن ابی لیلیٰ کی مذکورہ موصول روایت بھی اس کی مؤید ہے۔ واللہ اعلم"}],[5081,"عبداللہ بن بریدہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سب سے بہتر چیز جس سے تم بڑھاپے کا رنگ بدلو، مہندی اور کتم ہے\"۔","الألباني: صحيح لغيره",{"u2":"حضرت عبداللہ بن بریدہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’ سب سے اچھی جیز جس کے ساتھ تم سفید بالوں کا رنگ بدلو، مہندی اور وسمے کا آمیزہ ہے۔"}],[5082,"عبداللہ بن بریدہ سے روایت ہے کہ انہیں معلوم ہوا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سب سے بہتر چیز جس سے تم بڑھاپے کا رنگ بدلو، مہندی اور کتم ہے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن بریدہ سے روایت ہے کہ مجھے یہ بات پہنچی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’ بہترین وہ چیز جس کے ساتھ تم سفید بالوں کا رنگ تبدیل کرو، مہندی اور وسمے کا مرکب ہے۔"}],[5083,"ابورمثہ رضی اللہ عنہ کہتے ہیں کہ میں اور میرے والد نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے، اس وقت آپ نے اپنی ڈاڑھی میں مہندی لگا رکھی تھی ۱؎۔\n§وضاحت\n۱؎: آگے انس رضی اللہ عنہ کی حدیث :(نمبر: ۵۰۸۹ ) میں ہے کہ \" نبی اکرم صلی اللہ علیہ وسلم کے بالوں میں اتنے سفید بال تھے ہی نہیں کہ آپ خضاب لگاتے۔ \" دونوں حدیثوں میں باہم یوں تطبیق دی جاتی ہے کہ واقعی اتنے زیادہ بال تھے نہیں کہ آپ کو ان کے رنگ تبدیل کرنے کی ضرورت ہوتی :(یعنی بذریعہ خضاب ) مگر آپ نے ان کا رنگ تبدیل کیا تاکہ امت کے لیے نمونہ ہو، اس عمل کو انس رضی اللہ عنہ کو دیکھنے کا اتفاق نہ ہو سکا۔ رہی ابن عمر رضی اللہ عنہما کی اگلی حدیث :(نمبر: ۵۰۸۸ ) کہ آپ صلی اللہ علیہ وسلم پیلے رنگ سے اپنے بال رنگتے تھے تو پیلے رنگ کا استعمال بعد میں منسوخ ہو گیا تھا جس کی خبر ابن عمر رضی اللہ عنہما کو نہیں ہو سکی تھی۔","الألباني: صحيح",{"u2":"حضرت ابورمثہ نے فرمایا: میں اپنےوالد محترم کے ساتھ نبئ اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضرہوا۔ آپ نے اپنی ڈاڑھی کو مہندی لگا رکھی تھی۔","f2":"رسول اللہ صلی اللہ علیہ وسلم عموماً ڈاڑھی کو نہیں رنگتے تھے کیونکہ صرف چند بال سفید تھے جن کو انگلیوں پر گنا جاسکتا تھا، رنگنے کی ضرورت ہی نہیں تھی مگر کبھی کبھار آپ نے مہندی لگائی ہوگی۔"}],[5084,"ابورمثہ رضی اللہ عنہ کہتے ہیں کہ میں نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا، میں نے دیکھا کہ آپ اپنی داڑھی میں پیلے رنگ لگائے ہوئے ہیں۔","الألباني: صحيح",{"u2":"حضر ابورمثہ سے روایت ہے، انہوں نے فرمایا:میں نبئ اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا۔ میں نے دیکھا کہ آپ نے ڈاڑھی زرد کررکھی تھی۔","f2":"ڈاڑھی زرد کرنے سےمراد مہندی لگانا ہی ہے جیسا کہ اوپر گزرا۔ مہندی کا رنگ بھی تقریباً زرد ہی ہوتا ہے۔"}],[5085,"زید بن اسلم کہتے ہیں کہ ابن عمر رضی اللہ عنہما اپنی ڈاڑھی خلوق سے پیلی کرتے تھے، میں نے کہا: ابوعبدالرحمٰن! آپ اپنی ڈاڑھی خلوق سے پیلی کرتے ہیں؟ کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ آپ اس سے اپنی ڈاڑھی پیلی کرتے تھے، اور کوئی بھی رنگ آپ کو اس سے زیادہ پسند نہیں تھا، آپ اس سے اپنے تمام کپڑے یہاں تک کہ اپنی پگڑی بھی رنگتے تھے ۲؎۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: ابوقتیبہ کی حدیث کے مقابلے میں یہ زیادہ قرین صواب ہے ۳؎۔\n§وضاحت\n۱؎: \"خلوق\" ایک قسم کی خوشبو ہے جو کئی چیز سے بنتی ہے، اس میں ورس اور زعفران بھی شامل ہے۔ ۲؎: عبداللہ بن عمر رضی اللہ عنہما کو پیلے رنگ کی اجازت منسوخ ہو جانے کی خبر نہیں مل سکی تھی، پیلا رنگ عورتوں کا رنگ ہونے کے سبب مردوں کے لیے منسوخ کر دیا گیا۔ ۳؎: ابوقتیبہ کی روایت مؤلف کے یہاں آگے آ رہی ہے :(حدیث نمبر ۵۲۴۵ ) اس روایت میں ابن عمر رضی اللہ عنہما سے سوال کرنے والے زید بن اسلم کی جگہ \"عبید\" ہیں، مؤلف یہی بتار ہے ہیں کہ سائل \"زید\" ہیں نہ کہ \"عبید\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت زید بن اسلم سے روایت ہے کہ میں نے حضرت ابن عمر رضی اللہ عنہما کو دیکھا، انہوں نے اپنی ڈاڑھی کو خلوق سے زرد کررکھا تھا۔ میں نے کہا: اے ابوعبدالرحمن! آپ اپنی ڈاڑھی کو خلوق سے رنگتے ہیں؟ انہوں نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو خلوق سے ڈاڑھی رنگتے دیکھا ہے۔ اور آپ کو اس سے بڑھ کر کوئی رنگ پیارا نہیں تھا۔ آپ اس سے اپنے سب کپڑے حتی کہ پگڑی بھی رنگ لیا کرتے تھے۔\nابوعبدالرحمن (امام نسائی رحمہ اللہ) نے کہا: یہ حدیث ابوقتیبہ کی حدیث کی نسبت زیادہ صحیح ہے۔","f2":"1۔ امام نسائی رحمہ اللہ کا مذکورہ قول، سنن نسائی کے مختلف نسخوں میں مختلف انداز میں درج ہے۔ایک نسخے میں الفاظ ہیں: وهذا اولى بالصواب من حديث ابي قبية۔ ہندی نسخے میں الفاظ ہیں: وهذا ولى بالصواب من الذي قبله۔ ایک نسخے میں یہ الفاظ ہیں: وهذا اولى بالصواب من حديث قبية۔ شارح سنن النسائی علامہ محمد بن علی اتیوبی رحمہ اللہ نے آخری الفاظ کو درست قرار دیا ہے۔ تفصیل کے لیے دیکھئے (ذخیرۃ العقبیٰ شرح سنن النسائی:38؍87) واللہ اعلم۔2۔ ’خلوق‘ ایک زنانہ خوشبو ہے جوزعفران وغیرہ کو ملاکر بنائی جاتی ہے۔ رنگ زرد سرخ ہوتا ہے۔ عام طور پر یہ عورتوں کے استعمال میں آتی ہے، اس لیے مردوں کو اس سے روکا بھی گیا ہے۔ شاید بیان جواز کے لیے آپ نے کبھی کبھار ایک آدھ بارا سے استعمال فرمایا ہو۔ مردوں کے لیے اس کا استعمال مناسب نہیں ہے۔ ہاں کوئی اور خوشبو نہ ملے تو مجبوری کی حالت میں کبھی کبھی استعمال ہوجائے تو گنجائش ہے۔ واللہ اعلم"}],[5086,"انس رضی اللہ عنہ کہتے ہیں کہ قبیلہ عرینہ کے کچھ لوگ اسلام لائے تو انہیں مدینے کی آب و ہوا راس نہیں آئی، چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا:\"اگر تم لوگ ہمارے اونٹوں میں جاتے اور ان کا دودھ پیتے (تو اچھا ہوتا)\"، (حمید کہتے ہیں: قتادہ نے انس سے «البانہا» (دودھ کے) بجائے «ابو الہا»(پیشاب) روایت کی ہے۔) انہوں نے ایسا ہی کیا، پھر جب وہ ٹھیک ہو گئے تو اسلام لانے کے بعد کافر و مرتد ہو گئے، رسول اللہ صلی اللہ علیہ وسلم کے مسلمان چرواہے کو قتل کر دیا، اور آپ کے اونٹوں کو ہانک لے گئے اور جنگجو بن کر نکلے، رسول اللہ صلی اللہ علیہ وسلم نے انہیں گرفتار کرنے کے لیے کچھ لوگ بھیجے، چنانچہ وہ سب گرفتار کر لیے گئے۔ آپ صلی اللہ علیہ وسلم نے ان کے ہاتھ پاؤں کاٹ دیے، ان کی آنکھیں گرم سلائی سے پھوڑ دیں، اور انہیں حرہ (مدینے کے پاس پتھریلی زمین)میں چھوڑ دیا یہاں تک کہ وہ سب مر گئے۔\nقتادہ کہتے ہیں کہ انہوں نے انس رضی اللہ عنہ سے پوچھا: کیا رسول اللہ صلی اللہ علیہ وسلم نے خضاب لگایا تھا؟ کہا: آپ کو اس کی حاجت نہ تھی، کیونکہ صرف تھوڑی سی سفیدی کان کے پاس تھی۔","الألباني: صحيح",{"u2":"حضرت قتادہ سے روایت ہے کہ میں نے حضرت انس سے پوچھا: کیا رسول اللہ صلی اللہ علیہ وسلم نے بالوں کو رنگا ہے؟ آپ نے فرمایا: اس کی نوبت ہی نہیں آئی تھی۔ صرف آپ کی کنپٹیوں میں کچھ ہی بال سفید تھے۔","f2":"صحیح بات یہ ہے کہ آپ کے بال مبارک اتنے سفید نہیں ہوئے تھے کہ ان کو رنگنے کی ضرورت پڑتی۔ بعض احادیث میں رنگنے کا جوذکر آیا ہے، وہ کبھی کبھار پر محمول ہوگا۔"}],[5087,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ قبیلہ عکل یا عرینہ کے کچھ لوگ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور بولے: اللہ کے رسول! ہم مویشی والے لوگ ہیں ناکہ کھیت والے۔ انہیں مدینے کی آب و ہوا راس نہ آئی تو رسول اللہ صلی اللہ علیہ وسلم نے ان کے لیے کچھ اونٹوں اور ایک چرواہے کا حکم دیا اور ان سے وہاں جانے کے لیے کہا تاکہ وہ ان کے دودھ اور پیشاب پی کر صحت یاب ہو سکیں، جب وہ ٹھیک ہو گئے (وہ حرہ کے ایک گوشے میں تھے۔) تو اسلام سے پھر کر کافر (و مرتد) ہو گئے اور رسول اللہ صلی اللہ علیہ وسلم کے مسلمان چرواہے کو قتل کر دیا اور اونٹوں کو ہانک لے گئے، آپ نے ان کے پیچھے کچھ لوگوں کو بھیجا، تو وہ گرفتار کر کے لائے گئے، آپ نے ان کی آنکھیں گرم سلائی سے پھوڑ دیں، ان کے ہاتھ پاؤں کاٹ دیے اور پھر انہیں حرہ میں ان کے حال پر چھوڑ دیا یہاں تک کہ وہ سب مر گئے۔\nانس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم خضاب نہیں لگاتے تھے، کیونکہ تھوڑی سی سفیدی آپ کے ہونٹ کے نیچے تھے، تھوڑی سی کان کے پاس ڈاڑھی میں اور تھوڑی سی سر میں۔","الألباني: صحيح",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم اپنے بالوں کو نہیں رنگتے تھے۔ آپ کے سفید بال تھوڑے سے ڈاڑھی بچہ میں تھے، کچھ کنپٹیوں میں تھے اور معمولی سے سرمبارک میں تھے۔","f2":"’ڈاڑھی بچہ‘ نچلے ہونٹ اور ٹھوڑی کی درمیان جگہ کے بالوں کوکہتے ہیں۔ سفیدی عموماً یہیں سےشروع ہوتی ہے یا کنپٹیوں سے۔"}],[5088,"اس سند سے بھی عبدالاعلی سے اسی طرح روایت ہے۔\nعبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم کو دس عادتیں ناپسند تھیں: پیلا رنگ لگانا یعنی خلوق، بڑھاپے کا رنگ بدلنا ۱؎، تہبند(لنگی) ٹخنے سے نیچے لٹکانا، سونے کی انگوٹھی پہننا، چوسر شطرنج کھیلنا، بے موقع و محل عورتوں کا اجنبیوں کے سامنے بن ٹھن کر نکلنا، معوذات کے علاوہ دوسرے منتر پڑھنا، تعویذ لٹکانا، ناجائز جگہ میں منی بہانا، بچے کو صحت مند نہ ہونے دینا، ۲؎ البتہ آپ اسے حرام نہیں کہتے تھے۔\n§وضاحت\n۱؎: \"بڑھاپے کا رنگ بدلنا\" یعنی انہیں اکھیڑنا یا ان میں کالا خضاب لگانا۔ \"بچے کو صحت مند نہ ہونے دینا\" یعنی ایام رضاعت میں بچے کی ماں سے صحبت کرنا۔","الألباني: صحيح",{"u2":"سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ اللہ کے نبی صلی اللہ علیہ وسلم دس کاموں کو ناپسند فرماتے تھے: (مردوں کا) خلوق لگانا،سفید بالوں کو سیاہ کرنا، تہبند(ٹخنوں سے نیچے) لٹکانا، (مردوں کےلیے) سونے کی انگوٹھی پہننا، شطرنج کھیلنا، نامناسب مقام پر عورت کا اظہار زینت کرنا، معوذات وغیرہ کے علاوہ دم کرنا، تمیمے لٹکانا، منی غلط مقام پر ضائع کرنا اور چھوٹے بچے میں خرابی ڈالنا۔ لیکن آپ اس (آخری کام) کو حرام نہیں فرماتے تھے۔","f2":"محقق کتاب کا روایت کی سند کو حسن قرار دینا محل نظر ہے کیونکہ عبدالرحمن بن حرملہ راجح قول کے مطابق ضعیف راوی ہے، اس لیے یہ روایت منکر اور ضعیف ہے، تاہم دیگر دلائل کی رو سے مذکورہ دس کاموں میں سے بعض قطعاً حرام ہیں اور بعض مکروہ۔ تفصیل کےلیےدیکھئے: (تمام المنۃ،ص:75، والموسوعۃ الحدیثیۃ، مسند احمد:6؍92)"}],[5089,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ ایک عورت نے نبی اکرم صلی اللہ علیہ وسلم کو خط دینے کے لیے اپنا ہاتھ بڑھایا تو آپ نے اپنا ہاتھ کھینچ لیا، وہ بولی: اللہ کے رسول! میں نے ایک خط دینے کے لیے آپ کی طرف ہاتھ بڑھایا تو آپ نے اسے نہیں لیا۔ آپ نے فرمایا: \"مجھے نہیں معلوم کہ وہ عورت کا ہاتھ ہے یا مرد کا\"، میں نے عرض کیا: عورت کا ہاتھ ہے۔ آپ نے فرمایا: \"اگر تم عورت ہوتی تو اپنے ناخنوں کو مہندی سے رنگا ہوتا\" ۱؎۔\n§وضاحت\n۱؎: اس حدیث سے اس بات کی تاکید معلوم ہوتی ہے کہ عورتوں کو اپنی نسوانیت کی علامت اختیار کئے رہنا چاہیئے اور مردوں سے مشابہت کی کوئی بات اختیار نہیں کرنی چاہیئے اس کی حکمت دراصل اللہ کی تخلیق کو اپنی جگہ برقرار رکھنے کی بات ہے، اللہ کی خلقت کو بدلنا حرام عمل ہے، اس کی خواہ کوئی صورت ہو، نسوانیت کی علامت کے سلسلے میں بھی خاص خاص مرد اور عورت کے امتیازی علامات کے علاوہ چیزوں میں علاقہ و سماج کے عزت و رواج کا لحاظ کیا جائے گا۔","الألباني: حسن",{"u2":"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ ایک عورت نے اپنے ہاتھ میں ایک تحریر پکڑ کر آپ کی طرف بڑھائی۔ آپ نے اپنا ہاتھ پیچھے کرلیا۔ اس نے کہا: اے اللہ کے رسول! میں نے اپنے ہاتھ میں ایک تحریر پکڑ کر آپ کی طرف بڑھائی تھی لیکن آپ نے نہیں پکڑی۔ آپ نے فرمایا: ’ مجھے معلوم نہیں تھا کہ یہ عورت کا ہاتھ ہے یا مرد کا؟‘میں نے کہا: یہ عورت کا ہاتھ تھا۔آپ نے فرمایا: ’اگر تو عورت ہوتی تو اپنے ناخن مہندی کے ساتھ رنگ لیتی۔"}],[5090,"کریمہ کہتی ہیں کہ میں نے عائشہ رضی اللہ عنہا سے سنا: ان سے کسی عورت نے مہندی لگانے کے بارے میں پوچھا تو وہ بولیں: اس میں کوئی حرج نہیں، لیکن میں اسے اس لیے ناپسند کرتی ہوں کہ میرے محبوب صلی اللہ علیہ وسلم اس کی بو کو ناپسند کرتے تھے یعنی نبی اکرم صلی اللہ علیہ وسلم۔","الألباني: ضعيف",{"u2":"حضرت کریمہ نے کہا کہ میں نے سیدہ عائشہ رضی اللہ عنہا سے ایک عورت کو مہندی لگانے کے بارے میں سوال کرتے ہوئے سنا۔ سیدہ عائشہ رضی اللہ عنہا نے فرمایا: کوئی حرج نہیں لیکن میں اسے ناپسندکرتی ہوں کیونکہ میرے محبوب صلی اللہ علیہ وسلم اس کی بوکوناپسند فرماتے تھے۔"}],[5091,"ابوالحصین ہیثم بن شفی کہتے ہیں کہ میں اور میرا ایک ساتھی جس کی کنیت ابوعامر تھی اور وہ قبیلہ معافر ۱؎ کا تھا دونوں ایلیاء (بیت المقدس) میں نماز پڑھنے کے لیے نکلے، بیت المقدس میں لوگوں کے واعظ صحابہ میں سے قبیلہ ازد کے ابوریحانہ نامی ایک شخص تھے، میرے ساتھی مسجد میں مجھ سے پہلے پہنچے، پھر ان کے پیچھے میں آیا اور آ کر ان کے بغل میں بیٹھ گیا تو انہوں نے مجھ سے پوچھا: آپ نے ابوریحانہ کا کچھ وعظ سنا؟ میں نے کہا: نہیں، وہ بولے: میں نے انہیں کہتے ہوئے سنا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے دس باتوں سے منع فرمایا ہے: \"دانت باریک کرنے سے، گودنا گودنے سے، (سفید) بال اکھیڑنے سے، دو مردوں کے ایک ساتھ ایک کپڑے میں سونے سے، دو عورتوں کے ایک ساتھ ایک ہی کپڑے میں سونے سے، مرد کے اپنے کپڑوں کے نیچے عجمیوں کی طرح ریشمی کپڑا لگانے سے، یا عجمیوں کی طرح اپنے مونڈھوں پر ریشم لگانے سے، دوسروں کے مال لوٹنے سے، درندوں کی کھال پر سوار ہونے سے، اور انگوٹھی پہننے سے سوائے بادشاہ (حاکم) کے\" ۲؎۔\n§وضاحت\n۱؎: \"معافر\" یمن میں ایک جگہ کا نام ہے۔ ۲؎: اکثر سلف نے صرف زیب و زینت کی خاطر انگوٹھی پہننے سے منع کیا ہے، :(کچھ علماء اس ممانعت کو مکروہ تنزیہی قرار دیتے ہیں ) بادشاہ، یا بادشاہ کے نائبین جیسے عامل، گورنر، اسی طرح کسی بھی ادارے یا اس کے سربراہ کے لیے اپنی تحریر پر مہر لگانے کی خاطر انگوٹھی کے جواز کے سب قائل ہیں۔","الألباني: ضعيف",{"u2":"حضرت ابوالحصین، ہثیم بن شفی نے کہا کہ میں اور میرا ایک ساتھی، جو(یمن کے علاقے) معافر سے تھا اور اس کا نام ابوعامر تھا، بیت المقدس میں نماز پڑھنے کےارادے سے چلے۔ وہاں ایک صحابی جن کا نام ابوریحانہ ازدی رضی اللہ عنہ تھا، وعظ فرما رہے تھے۔میرا ساتھی مجھ سے پہلے مسجد میں چلا گیا(اور وعظ سننے لگا)۔ پھر میں بھی اس کے پاس پہنچ گیا اور اس کے پہلو میں بیٹھ گیا۔وہ مجھ سے پوچھنے لگا: کیا تو نے سیدنا ابوریحانہ رضی اللہ عنہ کا وعظ سنا ہے؟ میں نے کہا: نہیں۔وہ کہنے لگا، میں نے ان کو فرماتے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے دس کاموں سے منع فرمایا ہے: دانتوں کورگڑکر بار یک کرنا، جسم کو گدوانا(جسم کھود کر رنگ بھرنا)، بال اکھیڑنا، آدمی کا آدمی کے ساتھ ننگے جسم لیٹنا، عورت کا عورت کے ساتھ ننگے جسم لیٹنا، عجمیوں کی طرح مرد کا اپنے کپڑوں کے نیچے ریشم پہننا، عجمیوں کی طرح کندھوں پر ریشمی کپڑا ڈالنا، ڈاکا ڈالنا، چیتے کی کھال پر سوار ہونا اور انگوٹھی پہننا علاوہ حاکم کے (اور وہ انگوٹھی پہن سکتا ہے)۔","f2":"یہ روایت ضعیف ہے، تاہم سفید بال یا چہرے سے بال اکھیڑنا دیگر صحیح احادیث کی روسے حرام ہے، البتہ چاندی کی انگوٹھی کا جواز ہے، اسی لیے بعض علماء نے اس روایت کو دیگر شواہدکی بنا پر صحیح لغیرہ کہا ہے۔ دیکھئے(الموسوعۃ الحدیثیۃ، مسند احمد:28؍442)"}],[5092,"زہری کہتے ہیں کہ سعید بن مسیب کہتے تھے: سونے اور چاندی کے بدلے زمین کرائے پر اٹھانے میں کوئی مضائقہ اور حرج نہیں اور رافع بن خدیج رضی اللہ عنہ بیان کرتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے اس سے منع فرمایا ہے۔ عبدالکریم بن حارث نے اس کے مرسل ہونے میں ان کی موافقت کی ہے ۱؎۔\n§وضاحت\n۱؎: یعنی شعیب کی موافقت کی ہے اور یہ موافقت اس طرح ہے کہ زھری اور رافع کے درمیان سالم کا ذکر نہیں ہے جب کہ مالک اور عقیل نے سالم کا ذکر کیا ہے۔\nنافع کا بیان ہے کہ رافع بن خدیج رضی اللہ عنہ نے عبداللہ بن عمر رضی اللہ عنہما کو خبر دی کہ ہمارے چچا لوگ رسول اللہ صلی اللہ علیہ وسلم کے پاس گئے، پھر واپس آ کر خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم نے کھیت کرائے پر دینے سے منع فرمایا ہے، تو عبداللہ بن عمر رضی اللہ عنہما نے کہا: ہمیں معلوم ہے کہ وہ (رافع) رسول اللہ صلی اللہ علیہ وسلم کے عہد میں زمین والے تھے، اور اسے کرائے پر اس شرط پر دیتے تھے کہ جو کچھ اس کی کیاریوں کے کناروں پر جہاں سے پانی ہو کر گزرتا ہے پیدا ہو گا اور کچھ گھاس (چارہ) جس کی مقدار انہیں معلوم نہیں ان کی ہو گی۔ اسے ابن عون نے بھی نافع سے روایت کیا ہے لیکن اس میں :(«عمومتہ» کے بجائے)«بعض عمومتہ» کہا ہے۔\nابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مجھے حکم دیا گیا ہے کہ میں لوگوں سے جنگ کروں، یہاں تک کہ وہ لا الٰہ الا اللہ کہیں تو جس نے یہ کہہ دیا، اس نے اپنی جان اور اپنا مال مجھ سے محفوظ کر لیا مگر (جان و مال کے) حق کے بدلے، اور اس کا حساب اللہ پر ہے\"۔ ولید بن مسلم نے عثمان کی مخالفت کی ہے ۱؎۔\n§وضاحت\n۱؎: مخالفت یہ ہے کہ ولید نے مرفوع حدیث کے ساتھ ساتھ پورا واقعہ بھی بیان کیا ہے۔\nمعاویہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فریب کاری (یعنی اپنے بالوں میں دوسرے بال جوڑنے) سے منع فرمایا۔","الألباني: صحيح لغيره",{"u2":"سیدنا معاویہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے جعلی بال لگانے سے منع فرمایا ہے۔","f2":"عورت کے لیے تزئین و آرائش اور بننا سنورنا جائز ہے مگر جس میں غیر ضروری تکلف نہ ہو، مثلاً:وہ نہائے دھوئے، سرمہ ڈالے، تیل وخوشبو لگائے،(خاوند کےلیے) سرخی ومہندی لگائے، زیورات پہنے مگر غیر ضروری تکلف منع ہے جس کی چند صورتیں پچھلی حدیث میں گزری ہیں۔ اسی طرح بالوں کی کثرت اور طوالت ظاہر کرنے کےلیے اصل بالوں کے علاوہ اور بال جوڑنا جب کہ اتنے زیادہ اور اتنے لمبے بالوں کی ضرورت بھی نہیں۔پھر اس میں دھوکا بھی پایا جاتا ہے کیونکہ بال اس طرح جوڑے جاتے ہیں کہ نظر یہی آئے کہ اصل بال ہی اتنے لمبے ہیں۔ البتہ بالوں کو قابو میں رکھنے کےلیے پراندہ لگانا جائز ہے۔ چھوٹا ہو یا بڑا کیونکہ وہ دھاگے وغیرہ سے بنایا جاتا ہے۔ اس میں کوئی جعل سازی یا دھوکا دہی نہیں۔ غیر ضروری تکلف مردوں کو اپنی طرف مائل کرنے کےلیے کیا جاتا ہے جس سے زنا پھیلتا ہے جو قوموں کی تباہی و ہلاکت کا سبب ہے۔"}],[5093,"سعید مقبری کہتے ہیں کہ میں نے معاویہ بن ابی سفیان رضی اللہ عنہما کو منبر پر دیکھا ان کے ساتھ ان کے ہاتھوں میں عورتوں کے بالوں کی ایک چوٹی تھی، انہوں نے کہا: کیا حال ہے مسلمان عورتوں کا جو ایسا کرتی ہیں، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا ہے: \"جس عورت نے اپنے سر میں کوئی ایسا بال شامل کیا جو اس میں کا نہیں ہے تو وہ فریب کرتی ہے\"۔","الألباني: صحيح",{"u2":"حضرت سعید مقبری رحمہ اللہ سےروایت ہے کہ میں نے دیکھا، حضرت معاویہ بن ابوسفیان رضی اللہ عنہما منبر (مدینہ) پر بیٹھے تھے اور ان کےہاتھ میں جعلی بالوں کا ایک گچھا تھا۔ انہوں نے فرمایا: کیا بات ہے کہ مسلمان عورتیں یہ کام کرتی ہیں؟ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: جوعورت اپنے سر کے بالوں میں اور بالوں کا اضافہ کرے تو یہ جعلی سازی ہے جس سے وہ اضافہ کررہی ہے۔","f2":"۔ اس حدیث سے معلوم ہوا کہ اگر کوئی عورت اپنے سرکے قدرتی اور اصلی بالون کے ساتھ نقلی یا کسی دوسری عورت کے بال جڑوائے تاکہ اس کے بال لمبے نظر آئیں جیسا کہ رسول اللہ صلی اللہ علیہ وسلم کے زریں دور میں بھی عورتیں یہ کام کرتی تھیں، تو ایسا کرنا شرعاً حرام اور ناجائز ہے۔2۔اس حدیث مبارکہ سے یہ مسئلہ بھی معلوم ہوتا ہے کہ عورت کے بال جب تک اس کے سرپر موجود ہوں او ران کا پردہ ہے اور غیر محرم لوگوں سے ان کو چھپانا ضروری ہے، تاہم جب وہ الگ ہوجائیں تو وہ انہیں ضائع کرنا اور دفن کرنا ضروری ہے اور نہ غیر محرم مردوں سے چھپانا ضروری ہے جیساکہ سیدنا معاویہ رضی اللہ عنہ نے اپنے ہاتھ میں عورت کے بالوں کا گچھا پکڑا ہوا تھا اور انہوں نے وہ گچھا لوگوں کے سامنے بھی کیا۔3۔ بدعملی اور معصیت کے مرتکب لوگوں کو ہلاکت وتباہی کے گڑھے میں گرنے سے پہلے متنبہ کرنا، نیز انہیں اس کے خطرناک نتائج سے ڈرانا ضروری ہے تاکہ وہ لوگ اللہ تعالی کے عذاب کا شکار ہونے سے بچ جائیں اور صراط مستقیم کے راہی بن جائیں۔ 4۔دوران خطبہ لوگوں کو دکھانے کےلیے کوئی چیز ہاتھ میں پکڑی جاسکتی ہے، نیز بنی اسرائیل یا دیگر اقوام کی ہلاکت اورتباہی و بربادی کے واقعات، عبرت کے لیے بیان کیے جاسکتے ہیں تاکہ لوگوں کو معلوم ہوکہ اللہ اور اس کے رسول صلی اللہ علیہ وسلم کی نافرمانی کا نتیجہ کس قدر خطرناک اور تباہ کن ہوتا ہے۔5۔ یہ سیدنا معاویہ رضی اللہ عنہ کےدور خلافت اور ان کے آخری حج کی بات ہے وہ مدینہ منورہ بھی حاضر ہوئے تھے۔"}],[5094,"اسماء بنت ابی بکر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بال جوڑنے والی اور بال جوڑوانے والی عورت پر لعنت فرمائی ہے۔","الألباني: صحيح",{"u2":"سیدہ اسماء بنت ابی بکر رضی اللہ عنہا سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے جعلی بال لگانے والی اور لگوانے والی پر لعنت فرمائی ہے۔","f2":"1۔ ’لگانے والی‘ خواہ اجرت پرلگائے یا خوشی سے کیونکہ حرام کام میں تعاون بھی حرام ہے۔2۔ ’لعنت فرمائی‘ کسی کا نام لے کراس پر لعنت کرنا جائز نہیں مگر کسی وصف کا ذکر کرکے لعنت کی جاسکتی ہے، جیسے چور پر لعنت۔ تفصیل پیچھے گزر چکی ہے۔"}],[5095,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ بال جوڑنے والی اور جوڑوانے والی، گودنے والی اور گودوانے والی عورت پر رسول اللہ صلی اللہ علیہ وسلم نے لعنت فرمائی ہے۔(ابوعبدالرحمٰن نسائی کہتے ہیں:) ولید بن ہشام نے اسے مرسلاً روایت کیا ہے، (ان کی روایت آگے آ رہی ہے)۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے جعلی بال لگانے والی، لگوانے والی، رنگ بھر نےوالی اور بھروانے والی عورتوں پر لعنت فرمائی ہے۔\nولید بن ابوہشام نے اس روایت کو مرسل بیان کیا ہے۔","f2":"ولیدبن ابوہشام نے عبیداللہ بن عمر کی مخالفت کی ہے کیونکہ اس (عبید اللہ) نے یہ روایت حضرت نافع رحمہ اللہ سے موصول بیان کی ہے او ر وہ اس طرح کہ عبیداللہ نے نافع سے اور انہوں نے عبداللہ بن عمر رضی اللہ عنہما سے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے جعلی بال ملانے والی، ملوانے والی جسم گودنے والی اور گدوانے والی پر لعنت کی ہے۔ یہی مذکورہ حدیث عبیداللہ کی سند والی ہے جبکہ اگلی روایت:5099 جوکہ مرسل بیان کی گئی ہےاس میں ولید بن ابوہشام نے نافع سے بیان کیا ہے اور انہوں نے کہا ہے کہ مجھے یہ بات پہنچی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے...... الخ. اصل بات یہ ہے کہ عبیداللہ، نافع سے بیان کرنے میں دیگر رواۃ سے مقدم ہے۔ چونکہ عبیداللہ نے نافع سے موصول بیان کی ہے، لہذا یہ روایت محفوظ ہے۔ واللہ اعلم"}],[5096,"نافع سے روایت ہے کہ انہیں یہ بات پہنچی کہ رسول اللہ صلی اللہ علیہ وسلم نے بال جوڑنے والی اور جوڑوانے والی، گودنے والی اور گودوانے والی عورت پر لعنت فرمائی ہے۔","الألباني: صحيح لغيره",{"u2":"حضرت نافع سے روایت ہے کہ مجھے یہ بات پہنچی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے جعلی بال ملانے والی،ملوانے والی، گودنے والی(جسم کے مختلف حصوں میں چھید کررنگ بھرنے والی یا جسم پر نقش ونگار بنانے والی) اور گدوانے والی(جسم کے مختلف حصوں کو چھدوا کر ان میں رنگ بھروانے ولی یا جسم کے مختلف حصوں پر چھدوا کر نقش ونگار کرانے والی) عورت پر لعنت فرمائی ہے۔"}],[5097,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بال جوڑنے والی اور جوڑوانے والی عورت پر اللہ تعالی نے لعنت فرمائی ہے\"۔","الألباني: صحيح",{"u2":"سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اللہ تعالی نے جعلی بال لگانے والی اور لگوانے والی عورت پر لعنت فرمائی ہے۔","f2":"گویا ایسا کرنے والی عورتوں پر اللہ تعالی اور اس کے رسول صلی اللہ علیہ وسلم دونوں کی لعنت ہے۔"}],[5098,"مسروق سے روایت ہے کہ ایک عورت نے عبداللہ بن مسعود رضی اللہ عنہ کے پاس آ کر کہا: میرے سر پر بال بہت کم ہیں، کیا میرے لیے صحیح ہو گا کہ میں اپنے بال میں کچھ بال جوڑ لوں؟ انہوں نے کہا: نہیں، اس نے کہا: کیا آپ نے اسے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے یا کتاب اللہ (قرآن) میں ہے؟ کہا: نہیں، بلکہ میں نے اسے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے۔ اور اسے کتاب اللہ (قرآن) میں بھی پاتا ہوں …، اور پھر آگے حدیث بیان کی۔","الألباني: صحيح",{"u2":"حضرت مسروق سے روایت ہے کہ ایک عورت سیدنا عبداللہ بن مسعود رضی اللہ عنہ کے پاس آئی اور کہنے لگی کہ میرے سرکے بال نہ ہونے کے برابر ہیں تو کیا میں جعلی بال لگاسکتی ہوں؟ انہوں نے فرمایا: نہیں۔وہ کہنے لگی: کیا یہ بات آپ نے رسول اللہ صلی اللہ علیہ وسلم سے سنی یا کتاب اللہ میں پائی ہے؟ انہوں نے فرمایا: ہاں، میں نے یہ بات رسول اللہ صلی اللہ علیہ وسلم سے بھی سنی اور میں اسے کتاب اللہ میں بھی پاتا ہوں۔ پھر راوی نے پوری حدیث بیان کی۔","f2":"1۔’کتاب اللہ میں پاتا ہوں‘ یعنی انہوں نے قرآن کی اس عمومی دلیل﴿وَما ءاتىكُمُ الرَّ‌سولُ فَخُذوهُ وَما نَهىكُم عَنهُ فَانتَهوا﴾ کے پیش نظر جعلی بال نہ لگانے کو قرآن کا حکم قرار دیا کیونکہ آپ کی بات کو ماننا قرآن کاحکم ہے۔ لیکن اپنے اجتہاد سے مستنبط کیے گئے مسائل کی نسبت اللہ تعالی کی طرف یارسول اللہ صلی اللہ علیہ وسلم کی طرف کرنا درست نہیں ہے، مثلاً: قیاسی مسائل کی بابت کہنا کہ یہ اللہ تعالی یا اس کے رسول صلی اللہ علیہ وسلم کا فرمان ہے، یہ درست نہیں، اس لیے اس سے محتاط رہنا بہت ضروری ہے۔ واللہ اعلم۔2۔ یہ حدیث مفصلاً صحیح مسلم میں آتی ہے۔ اس سے معلوم ہوتاہے کہ تھوڑے بالوں والی عورت بھی جعلی بال نہیں لگاسکتی کیونکہ اس میں جعل سازی اور دھوکا دہی پائی جاتی ہے، نیز تھوڑے زیادہ کی کوئی حدبندی نہیں۔ اس طرح تو ہر عورت کہہ سکتی ہے کہ میرے بال تھوڑے ہیں۔ جو چیز شریعت نے ناجائز اور حرام قرار دی ہے وہ ناجائزاور حرام ہی ہے اس میں قطعاً دوسری کوئی رائے نہیں۔ واللہ اعلم"}],[5099,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے گودنے والی، گودوانے والی، پیشانی کے بال اکھاڑنے والی، خوبصورتی کے لیے دانتوں کے درمیان کشادگی کروانے والی، اور اللہ تعالی کی بنائی ہوئی چیز کو بدلنے والی عورتوں پر لعنت فرمائی ہے ۱؎۔\n§وضاحت\n۱؎: چونکہ یہ سارے اعمال ممنوع ہیں اس لیے ان کو کرنے والے اور ان کے کرنے میں مدد دینے والے سب پر لعنت کی گئی ہے، دانتوں میں کشادگی کے لیے، دانتوں کی تراش خراش کرنی پڑتی ہے اور یہ عمل قدرتی دانتوں میں تبدیلی ہے جو اللہ کی تخلیق میں دخل دینا ہے اس لیے یہ عمل بھی ممنوع ہے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے رنگ بھرنےوالی، بھروانے والی، بال اکھیڑنے والی اور دانتوں کو رگڑ رگڑ کر باریک کرنے والی عورتوں پر لعنت فرمائی ہے جو حسن کی خاطر(اللہ تعالی کی بنائی ہوئی صورت میں) بگاڑ پیدا کرتی ہیں۔","f2":"1۔اس حدیث مبارکہ سے جسم کو گودنے، گدوانے اور چہرے یا ابرو وغیرہ سے بال اکھیڑنے کی حرمت ثابت ہوتی ہے، نیز خوبصورتی کے لیے دانت رگڑنا اور رگڑوانا بھی حرام ہے اور ان سب کی وحۂ حرمت اللہ تعالی کی تخلیق میں تبدیلی کرنا ہے۔2۔ حسن کی خاطر اس قسم کا بناؤ سنگھار حرام ہے، ہاں اگر یہ کام بغرض علاج یا کسی نقص وعیب کے ازالے کی خاطر کیے جائیں تو پھر کوئی حرج نہیں، مثلاً: اگر عورت کے چہرے پر ڈاڑھی اگ آئے تویہ اس کے لیے عیب ہے، اس لیے اس کاازالہ کرنے میں کوئی قباحت نہیں۔ واللہ اعلم مزید تفصیل کےلیے دیکھئے: (شرح صحیح مسلم للنووی:14؍150۔152) 3۔ ’بال اکھیڑنا‘ اس کی وضاحت حدیث نمبر:5094 میں گزر چکی ہے۔ یادرہے کہ جن بالوں کو شریعت نے ختم کرنے کا حکم دیا ہے، وہ اس سے مستثنیٰ ہیں، مثلاً: بغلوں کے بال، نیز جس طرح عورتوں کے لیے مذکورہ بالوں کے علاوہ بال اکھیڑنے منع ہیں، اسی طرح حسن کی خاطر مرد بھی بال نہیں اکھیڑسکتے، مثلاً: ڈاڑھی یا ابرو کے بال اکھیڑنا مردوں کے لیے بھی ممنوع ہیں۔"}],[5100,"عمرو بن شرحبیل کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"قیامت کے روز لوگوں کے درمیان سب سے پہلے خون کا فیصلہ کیا جائے گا\"۔\nابراہیم نخعی کہتے ہیں کہ عبداللہ بن مسعود نے :(«متفلجات للحسن» کے بجائے) صرف «متفلجات» کہا اور حدیث بیان کی۔","الألباني: صحيح لغيره",{"u2":"حضرت عبداللہ بن مسعود نے فرمایا: دانتوں کو رگڑکر باریک کرنے والی عورتیں، پھر راوی نے پوری حدیث بیان کی۔"}],[5101,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے گودنے، گودوانے، بال جوڑنے، جڑوانے اور بال اکھاڑنے اور اکھڑوانے والی عورتوں کو ایسا کرے کرنے سے منع فرمایا۔","الألباني: ضعيف الإسناد",{"u2":"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے رنگ بھرنے والی، بھروانے والی، بال ملانے والی، بال ملوانے ولی، بال اکھیڑنے والی اور اکھڑوانے والی عورتوں کو ان کاموں سے منع فرمایا ہے۔"}],[5102,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں: \"سود کھانے والا، کھلانے والا، اور اس کا لکھنے والا ۱؎ جب کہ وہ اسے جانتا ہو (کہ یہ حرام ہے) اور خوبصورتی کے لیے گودنے اور گودوانے والی عورتیں، صدقے کو روکنے والا اور ہجرت کے بعد لوٹ کر اعرابی (دیہاتی) ہو جانے والا ۲؎ یہ سب قیامت کے دن رسول اللہ صلی اللہ علیہ وسلم کے فرمان کے مطابق ملعون ہیں۔\n§وضاحت\n۱؎: سود کھانا اور کھلانا تو اصل گناہ ہے، اور حساب کتاب گناہ میں تعاون کی قبیل سے ہے اس لیے وہ بھی حرام ہے اور موجب لعنت ہے۔ اسی طرح وہ کام جو اس حرام کام میں ممدو معاون ہوں موجب لعنت ہیں۔ ۲؎: یہ اس وقت کے تناظر میں تھا جب اللہ کے رسول صلی اللہ علیہ وسلم کے ساتھ رہ کر ان کی مدد کرنی واجب تھی اور مدینہ کے علاوہ مسلمانوں کا کوئی مرکزی بھی نہیں تھا، اگر دنیا میں کہیں اب بھی ایسی صورت حال پیدا ہو جائے تو دنیاوی منفعت کی خاطر مرکز اسلام کو چھوڑ کر دوسری جگہ منتقل ہو جانے کا یہی حکم ہو گا، مگر اب ایسا کہاں ؟۔","الألباني: صحيح",{"u2":"سیدنا عبداللہ بن مسعود رضی اللہ عنہ نے فرمایا: سود لینے والا، دینے والا، سود لکھنے والا بشرطیکہ وہ جانتے بوجھتے ہوں اور حسن کی خاطر رنگ بھرنے والی، بھروانے والی، زکاۃ سے انکار کرنے والا اور مہاجرین جانے کے بعد دوبارہ باد یہ کو لوٹ جانے والا، یہ سب اشخاص حضرت محمد صلی اللہ علیہ وسلم کی زبانی قیامت کےدن ملعون ہوں گے۔","f2":"1۔اس حدیث مبارکہ سے یہ مسئلہ بھی معلوم ہوتاہے کہ سود کھانا اور کھلانا حرام ہے، نیز سود لینے اور دینے والے اور سود لکھنے والے ان سب پرلعنت کی گئی ہے، یعنی یہ سارے یعنی ہیں بشرطیکہ انہیں سود کی حرمت کا علم ہو۔ اس کے ساتھ ساتھ یہ حدیث مبارکہ زکاۃ و صدقات اپنے پاس روک رکھنے اور مستحق لوگوں کو نہ دینے کی حرمت بھی بتاتی ہے جبکہ زکاۃکی ادائیگی فرض اور دین کی اساس وبنیاد ہے۔2۔ ’ سود لینے والا‘ عربی میں سود کھانے والا کہا گیا ہے مگر مراد لینے والا ہے۔ کھائے یا کسی اور استعمال میں لائے کیونکہ سود کا اپنی ذات کے لیے استعمال حرام ہے چاہے کسی بھی صورت میں ہو۔ البتہ اگر کسی کے پاس اس کی رضا مندی کی بغیر سود کا مال آجائے تو وہ اسے فقراء میں تقسیم اور رفاہِ عام کے کاموں میں خرچ کرسکتا ہے کیونکہ مال ضائع کرنا جائز نہیں، البتہ اسے ثواب نہیں ملے گا کیونکہ یہ مال حقیقتاً اس کا نہیں تھا، البتہ اس ےس فقراء کو فائدہ ہوجائے گا۔3۔ ’لکھنے والا‘ کیونکہ یہ شخص بھی کبیرہ گناہ میں معاون بن رہا ہے۔ 4۔ ’جانتے بوجھتے‘ یعنی متعلقہ افراد کو علم ہوکہ یہ سود کا معاملہ ہے۔ جہالت معاف ہے۔5۔ ’باد یہ کو لوٹ جانے والا‘ یہ صرف رسول اللہ صلی اللہ علیہ وسلم کے دور کے ساتھ خاص ہے کہ جس شخص نے ایک بار آپ کے دست مبارک پر ہجرت کی بیعت کرلی ہو،وہ دوبارہ اپنے اصلی علاقے میں اقامت اختیار نہیں کرسکتا ورنہ یہ ارتداد کے برابر گناہ ہوگا، الا یہ کہ خود رسول اللہ صلی اللہ علیہ وسلم اس کو اجازت فرما دیں جس طرح سیدنا سلمہ بن اکوع رضی اللہ عنہ کو اجازت دی تھی۔ آپ کے بعد کوئی ہجرت اس طرح لازم نہیں جس طرح نبی صلی اللہ علیہ وسلم کے زمانے مبارک میں تھی۔البتہ اب بھی اگر کوئی شخص دین کی خاطر ہجرت کرے گا تو وہ بھی اپنے وطن (ہجرت گاہ) واپس نہیں جاسکتا۔ واللہ اعلم. 6۔ ’حضرت محمد صلی اللہ علیہ وسلم کی زبانی‘ یعنی رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے کہ وہ قیامت کے دن لعنت میں ہوگا۔"}],[5103,"علی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سود کھانے والے، کھلانے والے، اس کا حساب لکھنے والے اور صدقہ نہ دینے والے پر لعنت فرمائی ہے، نیز آپ نوحہ (مردے پر چیخ چیخ کر رونے) سے منع فرماتے تھے۔ اسے ابن عون و عطا بن سائب نے مرسلاً روایت کیا ہے۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سود کھانے والے، کھلانے والے، لکھنے والے اور صدقہ (زکاۃ) سے انکار کرنے والے پر لعنت فرمائی ہے، نیز آپ نوحہ کرنے سے منع فرماتے تھے۔\nاس روایت کو ابن عون(نے حارث سے) اور عطاء بن سائب نے(شعبی سے) مرسل بیان کیا ہے۔"}],[5104,"حارث کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سود کھانے اور کھلانے والے، سود پر گواہی دینے والے، سود کا حساب لکھنے والے پر، اور گودنے والی اور گودوانے والی عورت پر لعنت فرمائی ہے، الا یہ کہ وہ کسی مرض کی وجہ سے ہو تو آپ نے فرمایا: \"ہاں\" اور آپ نے حلالہ کرنے اور کروانے والے پر، اور زکاۃ نہ دینے والے پر(لعنت فرمائی) اور آپ نوحہ کرنے سے منع فرماتے تھے (نوحہ کے بارے میں) «لعن» کا لفظ نہیں کہا۔","الألباني: صحيح",{"u2":"حضرت حارث سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سود کھانے والے، کھلانے والے، اس پر گواہ بننےوالے، اس کو لکھنے والے، رنگ بھرنے والی، بھروانے والی الا یہ کہ کسی بیماری کی وجہ سے ہوحلالہ کرنے والے، حلالہ کروانے والے، زکاۃ کی ادائیگی سے انکار کرنے والے لوگوں پر لعنت فرمائی ہے۔ اور آپ نوحہ سے منع فرماتے تھے، البتہ اس میں لعنت کا ذکر نہیں۔","f2":"1۔’حلالہ‘ جس عورت کو تیسری طلاق ہوجائے، وہ ہمیشہ کے لیے طلاق دینے والے خاوند پر حرام ہوجاتی ہے الا یہ کہ کسی اور خاوند سے نکاح کرے اور وہاں بھی نباہ نہ ہوسکے بلکہ طلاق ہوجائے یا یہ خاوند فوت ہوجائے تو پھر عدت گزرنے کے بعد پہلے خاوند کے لیے حلال ہوسکتی ہے۔ مگر دوسرا خاوند پہلے خاوند کے لیے حلال کرنے کے نقطۂ نظر سے اس سے نکاح کرے تو حرام ہے اور یہ شریعت کی حرام کردہ چیزکو حیلے سے حلال کرنا ہے۔ اور حرام کو حلال کرنے کےلیے حیلہ حرام ہے۔ حلالہ کرنے والا دوسرا خاوند ہے اور کروانے والا پہلا خاوند ہے۔2۔ ’ لعنت کا ذکر نہیں‘ یعنی نوحہ حرام تو ہے مگر اس فعل پر لعنت کا لفظ ذکر نہیں کیا گیا۔"}],[5105,"شعبی کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سود کھانے اور کھلانے والے، سود کی گواہی دینے والے، سود کا حساب لکھنے والے پر، اور گودنے والی اور گودوانے والی عورت پر لعنت فرمائی ہے، اور نوحہ سے منع فرمایا، (اس روایت میں حلالہ کرنے والے اور صدقہ کو روکنے والے پر) لعنت کا ذکر نہیں کیا۔","الألباني: صحيح لغيره",{"u2":"حضرت شعبی بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سود کھانے والے، کھلانے والے، سود پر گواہ بننے والے، اس کی کتابت کرنے والے، رنگ بھرنے والی، بھروانے والی پر لعنت فرمائی ہے۔ اور نوحہ سے منع فرمایا ہے۔ اور(راوی نے) یہ نہیں کہا کہ نوحہ کرنے والا ملعون ہے۔","f2":"’رنگ بھرنے والی‘ یہ فعل حرام ہے عورت کرے یا مرد۔ چونکہ عموماً عورتیں یہ کام کرتی تھیں، اس لیے مؤنث کا صیغہ استعمال کیا گیا ہے۔"}],[5106,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ عمر رضی اللہ عنہ کے پاس ایک عورت لائی گئی جو گودنا گودتی تھی تو انہوں نے کہا: میں تم کو اللہ کی قسم دیتا ہوں، اس سلسلے میں تم میں سے کسی نے کچھ رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے؟ ابوہریرہ رضی اللہ عنہ کہتے ہیں: چنانچہ میں نے کھڑے ہو کر کہا: امیر المؤمنین! میں نے سنا ہے۔ انہوں نے کہا: کیا سنا ہے؟ میں نے کہا: میں نے آپ کو فرماتے ہوئے سنا: \"(اے عورتو!) نہ گودو اور نہ گودواؤ\"۔","الألباني: صحيح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نے فرمایا کہ سیدنا عمر رضی اللہ عنہ کے پاس ایک عورت لائی گئی جو رنگ بھرنے کا کاروبار کرتی تھی۔ آپ نے فرمایا: میں اللہ تعالی کی قسم دے کر تم سے پوچھتا ہوں! کیا تم میں سے کسی نے رسول اللہ صلی اللہ علیہ وسلم سے (اس کی بابت) کچھ سنا ہے؟ میں نے کھڑے ہوکر کہا: اے امیرالمؤمنین! میں نے سنا ہے۔ انہوں نے فرمایا: کیا سنا ہے؟ میں نے کہا: میں نے آپ کو فرماتے سنا ہے: ’نہ رنگ بھرو نہ بھرواؤ۔‘","f2":"1۔ اس حدیث مبارکہ سے معلوم ہوا کہ امیرالمؤمنین خلیفۂ ثانی سیدنا عمرفاروق رضی اللہ عنہ اگرچہ خصائص نبوت کے حامل اور خلیفۂ راشدین ہیں لیکن دینی مسائل میں وہ بھی اپنے اجتہاد سے کچھ کہنے کے بجائے پیش آمدہ مسئلے کی بابت نصوص(قرآن وسنت کے دلائل) تلاش کرتے تھے جیسا کہ مذکورہ حدیث سے واضح ہے۔ 2۔ سیدنا ابوہریرہ رضی اللہ عنہ نے اس حدیث میں سیدنا عمر رضی اللہ عنہ کا جو قصہ بیان فرمایا ہے اس کا ایک مقصدیہ بات بتلانا بھی ہے کہ انہیں نصوص، یعنی فرامین رسول ضبط تھے کیونکہ سیدنا عمر رضی اللہ عنہ ایسے موقع پر خاموش نہیں ہو جاتے تھے بلکہ دوسرے صحابۂکرام رضی اللہ عنہما سے بھی تصدیق کرتے اور پوچھتے۔ لیکن سیدنا ابوہریرہ رضی اللہ عنہ سے حدیث ہے۔ اگر سیدنا عمر رضی اللہ عنہ اس کا انکار کرتے تو اس کا یقیناً ذکر ہوتا۔ بلاشبہ سیدنا ابوہریرہ رضی اللہ عنہ حافظ الحدیث اور فقیہ صحابئ رسول ہیں۔3۔ یہ حدیث’ خبر واحد‘ کے حجت ہونے کی بھی دلیل ہے۔"}],[5107,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو چہرے کے بال اکھاڑنے والی، دانتوں کے درمیان کشادگی کرانے والی اور گودانے والی عورتوں پر لعنت فرماتے ہوئے سنا ہے، جو اللہ تعالی کی بنائی ہوئی خلقت کو تبدیل کرتی ہیں۔","الألباني: حسن صحيح",{"u2":"حضرت ابن مسعود نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا کہ آپ بال اکھیڑنے والی، بہ تکلف دانتوں کو کشادہ کرنے والی اور رنگ بھروانے والی عورتوں پر لعنت کرتے تھے جو اللہ عزوجل کی پیدا کردہ صورت میں بگاڑ پیدا کرتی ہیں۔","f2":"حدیث نمبر5094 میں گزرا کہ جاہلیت میں عورتیں اپنے دانتوں کو ریتی سے رگڑ رگڑ کر باریک کرتی تھیں۔ مقصد یہ ہوتا تھا کہ دانت الگ الگ نظر آئیں۔ اسی بات کو اس حدیث میں بہ تکلف دانتوں کو کشادہ کرنا کہا گیا ہے۔ یہ حرام ہے۔ایک تو اس لیے کہ یہ اللہ تعالی کی تخلیق میں تبدیلی کرنا ہے اور دوسری بات یہ بھی ہے کہ خوب صورتی کے لیے اتنا زیادہ تکلف کرنا مفت کی درد سری ہے۔"}],[5108,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو بال اکھاڑنے والی، دانتوں کے درمیان کشادگی کرانے والی اور گودوانے والی عورتوں پر لعنت کرتے سنا، جو اللہ کی خلقت کو تبدیل کرتی ہیں۔","الألباني: حسن صحيح",{"u2":"حضرت عبداللہ سے روایت ہے، انہوں نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے بال اکھیڑنے والی، دانتوں کو بہ تکلف کشادہ کرنے والی اور رنگ بھروانے والی عورتوں پر لعنت کرتے سنا ہے جو اللہ عزوجل کی بنائی ہوئی صورت میں تبدیلی پیدا کرتی ہیں۔"}],[5109,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"اللہ تعالی لعنت فرمائے بال اکھاڑنے والی، گودوانے والی اور دانتوں میں کشادگی کرانے والی عورتوں پر، جو اللہ تعالی کی خلقت کو تبدیل کرتی ہیں\"۔","الألباني: حسن صحيح",{"u2":"حضرت عبداللہ سے روایت ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’ اللہ تعالی نے بال اکھیڑنے والی‘ رنگ بھروانے والی اور دانتوں کو بہ تکلف کھلا کرنے والی عورتوں پر لعنت فرمائی ہے جو اللہ عزوجل کی بنائی ہوئی صورت کی تبدیل کرتی ہیں۔‘","f2":"’تبدیل کرتی ہیں‘ گویا ایسے کام جنہیں عورتیں خوب صورتی کے لیے اختیار کرتی ہیں، حقیقتاً وہ انسانی فطری صورت کو بگاڑنے کے مترادف ہیں۔ اگرچہ مزاج خراب ہونے کی وجہ سے وہ اسے خوب صورتی تصور کرتی ہیں لیکن حقیقت یہی ہے کہ اصل حسن و جمال وہ ہے جو اللہ تعالی نے ہر مرد عورت کو خود عطا فرمایا ہے۔ اصل تخلیق الہی سے اعراض او رعدول بدصورتی تو ہو سکتی ہے، خوبصورتی قطعاً نہیں ہوسکتی۔"}],[5110,"ابوالحصین حمیری کہتے ہیں کہ وہ اور ان کے ایک ساتھی ابوریحانہ رضی اللہ عنہ کے ساتھ رہتے تھے اور خیر و بھلائی کی باتیں سیکھتے تھے، ایک دن میرے ساتھی میرے یہاں آئے اور مجھے بتایا کہ انہوں نے ابوریحانہ رضی اللہ عنہ کو کہتے ہوئے سنا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے دانتوں کو رگڑ کر باریک کرنے، گودنے اور بال اکھاڑنے کو حرام قرار دیا ہے۔","الألباني: ضعيف",{"u2":"حضرت ابوالحصین حمیری سے روایت ہے کہ میں اور میرا ایک ساتھی سیدنا ابوریحانہ رضی اللہ عنہ کے ساتھ ہر وقت رہتے تھے اور ان سے اچھی باتیں سیکھتے (علم حاصل کرتے) تھے۔ ایک دن میرا ساتھی ان کے پاس گیا اور پھر اس نے مجھے بتایا کہ میں نے سیدنا ابوریحانہ رضی اللہ عنہ کو فرماتے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے دانتوں کو باریک کرنا، رنگ بھر نا اور بال اکھیڑنا حرام قرار دیا ہے۔"}],[5111,"تابعی سعید بن المسیب کہتے ہیں کہ کچھ عرب رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور اسلام قبول کیا، پھر وہ بیمار پڑ گئے تو رسول اللہ صلی اللہ علیہ وسلم نے انہیں دودھ والی اونٹنیوں کے پاس بھیجا تاکہ وہ ان کا دودھ پیئں۔ وہ انہیں اونٹنیوں میں رہے، پھر انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے غلام چرواہے پر نیت خراب کی اور اسے قتل کر دیا اور اونٹنیاں ہانک لے گئے، لوگوں نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے یہ دعا کی: «اللہم عطش من عطش آل محمد الليلة» \"اے اللہ! اسے پیاسا رکھ جس نے محمد کے گھر والوں کو اس رات پیاسا رکھا\"، پھر رسول اللہ صلی اللہ علیہ وسلم نے ان کی تلاش میں کچھ لوگ بھیجے۔ جب وہ گرفتار کر لیے گئے تو آپ نے ان کے ہاتھ کاٹ دیے اور ان کی آنکھیں گرم سلائی سے پھوڑ دیں۔ راویوں میں سے بعض دوسرے سے کچھ زیادہ بیان کرتے ہیں، سوائے معاویہ کے، انہوں نے اس حدیث میں کہا ہے کہ وہ ہانک کر مشرکوں کی زمین کی طرف لے گئے۔\nابوریحانہ رضی اللہ عنہ کہتے ہیں کہ ہمیں یہ بات پہنچی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے دانتوں کو رگڑ کر باریک کرنے اور گودنے سے منع فرمایا ہے۔","الألباني: ضعيف الإسناد",{"u2":"سیدنا ابوریحانہ رضی اللہ عنہ نے فرمایا: ہمیں یہ بات پہنچی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے دانتوں کو باریک کرنے اور گودنے(جسم کو چھید کر نقش ونگار بنانے اور رنگ بھرنے) سے منع فرمایا ہے۔"}],[5112,"ابوریحانہ رضی اللہ عنہ کہتے ہیں کہ ہم تک یہ بات پہنچی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے دانتوں کو رگڑ کر باریک کرنے اور گودنے سے منع فرمایا ہے۔","الألباني: صحيح",{"u2":"سیدنا ابوریحانہ رضی اللہ عنہ سے روایت ہے کہ ہمیں یہ بات پہنچی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے دانتوں کو باریک کرنے اور رنگ بھرنے سے منع فرمایا ہے۔"}],[5113,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سب سے بہترین سرمہ اثمد (ایک پتھر) ہوتا ہے، وہ نظر تیز کرتا اور بال اگاتا ہے\"۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: عبداللہ بن عثمان بن خثیم لین الحدیث ہیں ۱؎۔\n§وضاحت\n۱؎: لیکن دیگر بہت سے أئمہ نے ان کی توثیق کی ہے، نیز بقول حافظ ابن حجر: ایک روایت کے مطابق خود امام نسائی نے ان کی توثیق کی ہے، :(دیکھئیے تہذیب التہذیب )","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تمہارے لیے بہترین سرمہ اثمد ہے۔ یہ نظر کو تیز کرتا ہے اور (پلکوں کے) بال بڑھاتا ہے۔\nابوعبدالرحمنٰ (امام نسائی رحمہ اللہ) نے فرمایا: عبداللہ بن عثمان بن خثیم لین الحدیث ہے۔ (مطلب یہ کہ اس کی حدیث ضعیف ہے۔)","f2":"1۔ اثمدسرمہ لگانا مستحب ہے۔ اور یہ استحباب مردوں اور عورتوں دونوں کے لیے ہے کیونکہ احادیث مبارکہ کے الفاظ عام ہیں۔ نبی صلی اللہ علیہ وسلم نے فرمایا: (اکتحلوا بالاثمد...) ’تم اثمد سرمہ لگایا کرو۔ اس سے نظر روشن اور تیز ہوتی ہے اور (پلکوں کے) بال اگتے ہیں۔‘ 2۔ سرمہ جہاں نظرتیز کرنے کےلیے لگانا جائز ہے وہاں زینت کےلیے بھی اس کا استعمال جائز ہے۔ عورتوں کےلیے تو کوئی اختلاف نہیں، البتہ مردوں کےلیے بعض فقہاء نے بطور زینت منع فرمایا ہے کیونکہ یہ رنگ والی زنگ زینت ہے اور رنگ والی زینت مردوں کے لیے قطعاً منع ہے۔ لیکن یہ صریح نص کےمقابلے میں رائے ہے، اس لیے قبول نہیں، پھر رسول اللہ صلی اللہ علیہ وسلم نے تو خود مردوں کو سرمہ لگانے کی ترغیب بھی دی ہے۔ واللہ اعلم"}],[5114,"سماک کہتے ہیں کہ میں نے جابر بن سمرہ رضی اللہ عنہ سے سنا، ان سے رسول اللہ صلی اللہ علیہ وسلم کے بالوں کی سفیدی کے بارے میں پوچھا گیا، تو انہوں نے کہا: جب آپ اپنے سر میں خوشبو (دہن عود) یا تیل لگاتے تو ان بالوں کی سفیدی نظر نہ آتی اور جب نہ لگاتے تو نظر آتی۔","الألباني: صحيح",{"u2":"حضرت سماک سے روایت ہے کہ میرے سامنے سیدنا جابر بن سمرہ رضی اللہ عنہ سے نبئ اکرم صلی اللہ علیہ وسلم کے سفید بالوں کے بارے میں پوچھا گیا۔ انہوں نے فرمایا: جب آپ سرکو تیل لگالیتے تھے تو سفید بال نظر نہیں آتے تھے اور جب تیل نہیں لگاتے تھے تو نظر آتے تھے۔","f2":"معلوم ہوا کہ سر اور ڈاڑھی کے بالوں کو تیل لگانا مستحب ہے کیونکہ خود رسول اللہ صلی اللہ علیہ وسلم اپنے سرمبارک اور ڈاڑھی مبارک کو تیل لگایا کرتے تھے۔ رسول اللہ صلی اللہ علیہ وسلم کی ڈاڑھی مبارک گھنی تھی۔ مزید برآں یہ کہ آپ کے سرمبارک اور ڈاڑھی مبارک کے اگلے حصے میں چند سفید بال تھے جو تیل لگانے کی صورت میں سفید نظر نہ آتے تھے۔ دیکھئے: (صحیح مسلم، الفضائل، باب اثبات خاتم النبوۃ وصفتہ، ومحلہ من جسدہ صلی اللہ علیہ وسلم حدیث:2344)"}],[5115,"زید سے روایت ہے کہ عبداللہ بن عمر رضی اللہ عنہما اپنے کپڑوں کو زعفران میں رنگتے تھے۔ ان سے (اس بارے میں) کہا گیا۔ تو انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم بھی رنگتے تھے ۱؎۔\n§وضاحت\n۱؎: دیکھے حاشیہ حدیث نمبر: ۵۰۸۸","الألباني: صحيح الإسناد",{"u2":"حضرت ابن عمر رضی اللہ عنہما اپنے کپڑے زعفران سے نگا کرتے تھے۔ ان سے پوچھا گیا تو انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم بھی(اپنے کپڑوں کو) اس سے رنگتے تھے۔","f2":"پیچھے گزر چکا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے زعفران سے رنگا ہوا کپڑا پہننے سے منع فرمایا ہے۔ یہاں جواز کا ذکر ہے۔ شاید یہ اجازت کبھی کبھار ایسا کرنے کے لیے ہو۔ البتہ مردوں کے لیے جسم پر زعفران لگانا قطعاً جائز نہیں۔ مزید تفصیل کےلیے دیکھئے، حدیث5089۔"}],[5116,"محمد بن علی باقر کہتے ہیں کہ میں نے عائشہ رضی اللہ عنہا سے پوچھا: کیا رسول اللہ صلی اللہ علیہ وسلم خوشبو لگاتے تھے؟ کہا: ہاں، مردانہ خوشبو: مشک اور عنبر۔","الألباني: ضعيف الإسناد",{"u2":"حضرت محمد بن علی رحمہ اللہ نے فرمایا کہ میں نے سیدہ عائشہ رضی اللہ عنہا سے پوچھا۔ کیا رسول اللہ صلی اللہ علیہ وسلم خوشبو لگایا کرتے تھے؟ انہوں نے فرمایا: ہاں، مردوں والی خوشبوئیں لگایا کرتے تھے، کستوری اور عنبر۔","f2":"’محمد بن علی‘ ان سے مراد سیدنا علی رضی اللہ عنہ کے بیٹے محمد ہیں جن کو محمد ابن الحنفیہ کہا جاتا ہے۔"}],[5117,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مردوں کی خوشبو وہ ہے جس کی مہک ظاہر ہو اور رنگ چھپا ہو اور عورتوں کی خوشبو وہ ہے جس کا رنگ ظاہر ہو اور مہک چھپی ہو\" ۱؎۔\n§وضاحت\n۱؎: مردوں کے لیے رنگلین خوشبو اس لیے منع ہے کہ رنگ عورتوں کی چیز ہے جو مردانہ وجاہت کے خلاف ہے، رنگدار خوشبو جیسے زعفران اور خلوق جس کا تذکرہ حدیث نمبر: ۵۱۲۳ :(وما بعدہ ) میں آ رہا ہے، سند کے لحاظ سے گرچہ وہ روایتیں ضعیف ہیں مگر اس حدیث سے ان کے معنی کو تقویت حاصل ہو رہی ہے اور عورتوں کے لیے یہ ممانعت اس صورت میں ہے جب عورت گھر سے باہر نکلے، ورنہ شوہر کے ساتھ گھر میں رہتے ہوئے ہر طرح کی خوشبو استعمال کر سکتی ہے۔","الألباني: صحيح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: مردوں کی خوشبو وہ ہے جس کی خوشبو ظاہر ہو اور رنگ مخفی اور اور عورتوں کی خوشبو و ہ ہے جس کا رنگ نمایاں ہو لیکن خوشبو مخفی ہو۔","f2":"1۔ مذکورہ روایت کو محقق کتاب نے سنداً ضعیف قراردیا ہے جبکہ دیگر محققین نے اسے دیگر شواہد کی بنا پر صحیح قراردیا ہے۔ دلائل کی روسے یہی بات درست ہے، لہذا مذکورہ روایت سنداً ضعیف ہونے کے باوجود قابل عمل اور قابل حجت ہے۔ واللہ اعلم. تفصیل کےلیے دیکھئے۔ ذخیرۃ العقبیٰ شرح من النسائی:38؍158۔161) 2۔ ’رنگ مخفی ہو‘ معلوم ہوا مردوں کی خوشبو میں ہلکا سا رنگ ہوسکتا ہے جو دور سے نمایاں نہ ہو، مثلاً: کستوری کا رنگ۔ اسی طرح عورتوں کی خوشبو میں معمولی سی مہک ہو جوراستہ چلنے والوں کو محسوس نہ ہو تو کوئی حرج نہیں کیونکہ آپ نے نفی نہیں فرمائی بلکہ فرمایا، مخفی ہو۔ گویا معمولی میں کوئی حرج نہیں۔ 3۔ عورتوں کےلیے رنگ والی خوشبو اس لیے مخصوص فرمائی کہ ان کے لیے پردہ فرض ہے، لہذا وہ لوگوں کو نظر نہیں آئے گی۔ خوشبو محسوس نہیں ہوگی، اس لیے لوگوں کی توجہ ان کی طرف مبذول نہیں ہوگی جبکہ مرد کےلیے پردہ نہیں ہے، اس لیے اسے رنگ والی چیز سے روک دیا گیا۔4۔ اگر عورت اپنے خاوند کے گھر میں ہو، باہر نہ جائے اور گھر میں غیر محرم مردوں کی آمد کا سلسلہ بھی نہ ہو تو پھر اسے کچھ نہ کچھ اجازت دی جاسکتی ہے۔ لیکن یہ پر فتن دور ہے،سدذریعہ کے طور پر اس سے محفوظ رہنا ہی بہتر ہے۔ واللہ اعلم"}],[5118,"ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"مردوں کی خوشبو وہ ہے کہ جس کی مہک ظاہر ہو اور رنگ چھپا ہو، عورتوں کی خوشبو وہ ہے جس کا رنگ ظاہر ہو اور مہک چھپی ہو\"۔","الألباني: صحيح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبئ اکرم صلی اللہ علیہ وسلم نے فرمایا: مردوں کی زینت (یا خوشبو) وہ ہے جس کی خوشبو ظاہر ہو، رنگ مخفی ہو اور عورتوں کی زینت (یا خوشبو) وہ ہے جس کا رنگ نمایاں ہو، خوشبو مخفی ہو۔"}],[5119,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بنی اسرائیل کی ایک عورت نے سونے کی ایک انگوٹھی بنائی اور اس میں مشک بھر دی\"، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یہ سب سے عمدہ خوشبو ہے\"۔","الألباني: صحيح",{"u2":"سیدنا ابوسعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: بے شک بنی اسرائیل کی ایک عورت نے سونے کی انگوٹھی بنائی اور اس میں کستوری بھری۔ (پھر) رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: یہ بہترین خوشبو ہے۔"}],[5120,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ ایک شخص نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا، وہ خلوق میں لتھڑا ہوا تھا تو اس سے آپ نے فرمایا: \"جاؤ اور اسے دھو ڈالو\"، پھر وہ آپ کے پاس آیا تو آپ نے فرمایا \": \"جاؤ اسے دھو ڈالو\"۔ وہ پھر آپ کے پاس آیا تو آپ نے فرمایا: \"جاؤ اسے دھو ڈالو، پھر آئندہ نہ لگانا\"۔","الألباني: ضعيف",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے، انہوں نے فرمایا کہ ایک آدمی نبئ اکرم صلی اللہ علیہ وسلم کے پاس آیا تو اس پر مخلوق کا نشان تھا۔ نبئ اکرم صلی اللہ علیہ وسلم نے اسے فرمایا: جاؤ، اسے اچھی طرح دھو کر آؤ۔وہ پھر ےآیا تو آپ نے فرمایا: پھر جاؤ، اچھی طرح دھو کر آؤ۔ وہ پھر آیا تو آپ نے فرمایا: پھر جاؤ، اسے اچھی طرح دھو ڈالو اور دوبارہ نہ لگانا۔","f2":"’خلوق‘ یہ رنگ دار خوشبو ہوتی ہے جسے زعفران وغیرہ سے بنایا جاتا ہے۔"}],[5121,"یعلی بن مرہ رضی اللہ عنہ سے روایت ہے کہ وہ نبی اکرم صلی اللہ علیہ وسلم کے پاس سے گزرے، اور وہ خلوق لگائے ہوئے تھے، آپ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"کیا تمہاری بیوی ہے؟\" کہا: نہیں۔ آپ نے فرمایا: \"تو اسے دھوؤ اور دھوؤ پھر نہ لگانا\"۔","الألباني: ضعيف",{"u2":"سیدنا یعلیٰ بن مرہ رضی اللہ عنہ سے روایت ہے کہ وہ نبئ اکرم صلی اللہ علیہ وسلم کےپاس سے گزرے جبکہ انہوں نے خلوق لگائی ہوئی تھی۔ آپ نے فرمایا: کیا تیری بیوی ہے؟ میں نےکہا: نہیں۔ آپ نے فرمایا: اس کو دھودے۔ اچھی طرح دھودے۔ اور پھر دوبارہ نہ لگانا۔"}],[5122,"یعلی بن مرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص کو خلوق لگائے ہوئے دیکھا تو فرمایا: \"جاؤ اسے دھو لو، اور پھر دھو لو اور دوبارہ نہ لگانا\"۔","الألباني: ضعيف",{"u2":"سیدنا یعلیٰ بن مرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک آدمی کو دیکھا جس نے خلوق لگا رکھی تھی۔ آپ نے فرمایا: جا، اس کو دھو، پھر دھو(اچھی طرح دھو) اور دوبارہ نہ لگانا۔"}],[5123,"اس سند سے بھی یعلی رضی اللہ عنہ سے اسی طرح مروی ہے۔ (ابوعبدالرحمٰن نسائی کہتے ہیں:) سفیان کی روایت اس کے برخلاف ہے، چنانچہ انہوں نے اسے عطاء بن سائب سے، انہوں نے عبداللہ بن حفص سے اور انہوں نے یعلی سے روایت کیا ہے۔ (عبداللہ بن حفص وہی ابوحفص بن عمرو ہے جو پچھلی سند میں ہے۔)","الألباني: سكت عنه الشيخ",{"u2":"سیدنا یعلیٰ رضی اللہ عنہ سےاس قسم کی روایت منقول ہے۔’خالفہ سفیان‘ اس روایت میں سفیان بن عیینہ نے شعبہ کی مخالفت کی ہے۔","f2":"سفیان بن عیینہ اور شعبہ، دونوں نےیہ روایت عطاء بن سائب سے بیان کی ہے لیکن سفیان بن عیینہ نے شعبہ کی مخالفت کی ہے اور وہ اس طرح کہ جب سفیان نے عطاء بن سائب سے بیان کیا تو کہا: عن عطاء ابن السائب، عبداللہ بن حفص‘ یعنی سفیان نے عطاء کا استاد عبداللہ بن حفص کہا ہے جبکہ امام شعبہ کو عطاء بن سائب کے استاد کے نام میں تردد ہے، کبھی ابو حفص بن عمرو، کبھی حفص بن عمرو اور بسا اوقات وہ ابن عمرو کہتے ہیں۔ واللہ اعلم. مزید تفصیل کےلیے دیکھئے(ذخیرۃ العقبیٰ شرح سنن النسائی للأ تیوبی: 38؍167۔168)"}],[5124,"یعلی بن مرہ ثقفی رضی اللہ عنہ کہتے ہیں کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے دیکھا، مجھ پر خلوق کا داغ لگا ہوا تھا، آپ نے فرمایا: \"یعلی! کیا تمہاری بیوی ہے؟\" میں نے کہا: نہیں، آپ نے فرمایا: \"اسے دھو لو، پھر نہ لگانا، پھر دھو لو اور نہ لگانا اور پھر دھو لو اور نہ لگانا\"، میں نے اسے دھو لیا اور پھر نہ لگایا، میں نے پھر دھویا اور نہ لگایا اور پھر دھویا اور نہ لگایا۔","الألباني: ضعيف",{"u2":"سیدنا یعلیٰ بن مرہ ثقفی رضی اللہ عنہ نے فرمایا: مجھے رسول اللہ صلی اللہ علیہ وسلم نے دیکھا جبکہ میرے جسم پر خلوق کے نشان تھے۔ آپ نے فرمایا: یعلیٰ! تیری بیوی ہے؟ میں نے کہا: نہیں، آپ نے فرمایا: جا، اسے دھو دے،پھر استعمال نہ کرنا۔ پھر دھو دے، پھر استعمال نہ کرنا۔ پھر دھودے، پھر استعمال نہ کرنا۔ انہوں نے کہا: میں نے اسے دھودیا۔ پھر دوبارہ استعمال نہیں کی۔ پھر دھودیا، پھر استعمال نہیں کی۔ پھر دھودیا، پھر دوبارہ استعمال نہیں کی۔"}],[5125,"یعلی رضی اللہ عنہ کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس سے گزرا، میں خلوق لگائے ہوئے تھا، آپ نے فرمایا: \"یعلی! کیا تمہاری بیوی ہے؟\" میں نے عرض کیا: نہیں۔ آپ نے فرمایا: \"جاؤ، اسے دھوؤ، پھر دھوؤ اور پھر دھوؤ، پھر ایسا نہ کرنا\"، میں گیا اور اسے دھویا پھر دھویا اور پھر دھویا پھر ایسا نہیں کیا۔","الألباني: ضعيف",{"u2":"سیدنا یعلیٰ رضی اللہ عنہ نے فرمایا: میں رسول اللہ صلی اللہ علیہ وسلم کے پاس سے گزرا جبکہ میں خلوق لگا رکھی تھی۔ آپ نے فرمایا: ’یعلیٰ! تیری بیوی ہے؟ میں نے کہا: نہیں، آپ نے فرمایا: اے دھودے، اچھی طرح دھودے۔ باربار دھودے۔ پھر دوبارہ نہ لگانا۔ میں گیا اور اس کو دھودیا، اچھی طرح دھو دیا۔ بار بار دھویا، پھر دوبارہ کبھی نہیں لگائی۔"}],[5126,"ابوموسی اشعری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو عورت عطر لگائے اور پھر لوگوں کے سامنے سے گزرے تاکہ وہ اس کی خوشبو سونگھیں تو وہ زانیہ ہے\"۔\n§وضاحت\n۱؎: یعنی وہ عطر مہک والا ہو، اور مہک والا عطر لگا کر باہر نکلنا عورتوں کے لیے حرام ہے، گھر میں شوہر کے لیے لگا سکتی ہیں۔","الألباني: حسن",{"u2":"سیدنا ابوموسیٰ اشعری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جو بھی عورت خوشبو لگا کر لوگوں کے پاس سے گزرتی ہے تاکہ وہ اس کی خوشبو سونگھیں (اور اس کی طرف متوجہ ہوں) تو وہ بدکارہ (زانیہ) ہے۔","f2":"1۔اس حدیث سے معلوم ہوا کہ خوشبو سے معطر عورت کا گھر سے باہر نکلنا شرعاً حرام ہے، جبکہ آج کی عورت خوشبو میں لت پت ہوکر دفتروں میں جاتی اور مختلف مخلوط پارٹیوں اور تقریبات میں شامل ہوتی ہے اور اسی حالت میں مختلف شاپنگ سنٹروں میں بھی اس کا آنا جانا رہتا ہے۔ فانا للہ وانا الیہ راجعون.\nدین و شریعت سے کوسوں دور، ایمان کی لذت سے ناآشنا اور تہذیب مغرب کی دل دادہ، نیز مسنون زندگی کی برکتوں سے محروم، شمع محفل بننے سے کے جنوں میں مبتلا آج کی بزعم خویش’ روشن خیال‘ درحقیقت ظلمتوں اور اندھیروں کی باسی عورت مخلوط محفلوں میں نہ صرف شمولیت اختیار کرتی ہے بلکہ ان محفلوں کی زینت بنتی ہے، ان کی روح رواں بننے کی کوشش کرتی اور پھر اس بے راہ روی پر نہ صرف وہ بلکہ اس کے دیوث اور بے حمیت عزیزو اقارت، نیز باپ، خاوند اور بھائی وغیرہ سرعام فخر بھی کرتے ہیں۔ کیا ان حضرات و خواتین نے کبھی یہ سوچا ہے کہ روزِ قیامت اپنے رب کے سامنے کون سامنہ لے کر جائیں گے؟اور کیا ایسی پیغمبر مخالفانہ زندگی گزار کر اس دنیا سے رخصت ہونے پر نبئ اکرم صلی اللہ علیہ وسلم کی شفاعت کے حق دار بن سکیں گے؟ اللہ کریم ہم سب کو اپنے دین متین کی سمجھ اور اس پر عمل پیرا ہو نے کی توفیق عطا فرمائے۔ آمین۔2 یہ حدیث مبارکہ اس بات پر بھی دلالت کرتی ہے کہ جو چیز کسی دوسری چیز کا سبب بنتی ہے اس سبب بننے والی چیز کا حکم بھی وہی ہوتا ہے جو اصل چیز کا ہوتا ہے جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے ایسی عورت کو زانیہ اور بدکارہ قراردیا ہے جو خوشبو لگا کر گھر سے باہر نکلتی اور مردوں کو فتنے میں مبتلا کرتی ہے اور یہ اس لیے کہ عورت کے وجود سے پھوٹنےوالی مہک مردوں کو ابھارتی ہے کہ وہ اسے دیکھیں، لہذا جب وہ اجنبی عورت کو دیکھیں گے تو یہ نظر اور آنکھ کا زنا ہوگا۔ عورت کو اس لیے زانیہ کہا گیا ہے کہ وہ اس کا سبب بنتی ہے، لہذا اس کا سبب بننے والی عورت پر بھی وہی حکم لگایا گیا ہے جو اصل چیز کا حکم ہے۔3۔ ’بدکار عور ت ہے‘ یعنی یہ بدکارہ اورزانیہ عورت کی علامت ہے کہ وہ لوگوں کے سامنےاپنی زینت ظاہر کرتی ہے تاکہ لوگ اس کی طرف مائل ہوں۔ یا اشارہ ہے کہ اس کا انجام بدکاری ہے۔ آخر کار وہ زانیہ بن جائے گی۔"}],[5127,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب عورت مسجد کے لیے نکلے تو خوشبو مٹانے کے لیے اس طرح غسل کرے جیسے غسل جنابت کرتی ہے\"، یہ حدیث مختصر ہے۔","الألباني: صحيح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سےروایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب کوئی عورت مسجد کو جانے لگے (اور اس نے پہلے خوشبو لگارکھی ہو)تو وہ اچھی طرح غسل کرے، جیسے وہ غسل جنابت کرتی ہے۔، یہ روایت مختصر ہے۔","f2":"1۔’ مسجدکو‘ مراد گھر سے باہر جانا ہے۔ مسجد کو جائے یا کسی دوسرے کے گھر میں یا کھیت میں۔ مسجد کا ذکر خصوصاً اس لیے کیا کہ مسجد پاکیزگی کی جگہ ہے۔وہاں خوشبوافضل ہے مگر عورت مسجد کو جاتے وقت بھی خوشبو استعمال نہیں کرسکتی چہ جائیکہ کسی اور جگہ خوشبو لگا کر جائے۔2۔ ’اچھی طرح غسل کرے‘ کیونکہ خوشبو تو ایک عضو سے دوسرے عضو کو لگ جاتی ہے، لہذا نہائے بغیر خوشبو کا اثر ختم نہ ہوگا۔ مقصد تو خوشبو کو ختم کرنا ہے۔ 3۔ ’ جیسے غسل جنابت کرتی ہے‘ یعنی خوب اچھی طرح، یہ مطلب نہیں کہ خوشبو لگانے سے غسل فرض ہو جاتا ہے۔"}],[5128,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب عورت خوشبو لگائے ہو تو ہمارے ساتھ عشاء کی جماعت میں نہ آئے\"۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: مجھے نہیں معلوم کہ کسی نے یزید بن خصیفہ کی بسر بن سعید سے روایت کرتے ہوئے «عن ابی ھریرہ» کہنے میں متابعت کی ہو۔ اس کے برعکس یعقوب بن عبداللہ بن اشج نے اسے روایت کرنے میں «عن زینب الثقفیۃ» کہا ہے ۱؎۔\n§وضاحت\n۱؎: یزید بن خصیفہ کی روایت صحیح مسلم میں بھی ہے، یہ بالکل ممکن ہے کہ روایت یزید کے پاس دونوں سندوں سے ہو۔","الألباني: صحيح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس عورت نے خوشبو لگائی ہو، وہ ہمارے ساتھ عشاء کی نماز پڑھنے مسجد میں نہ آئے۔\nابو عبدالرحمن (امام نسائی رحمہ اللہ) بیان کرتے ہیں کہ میرے علم کے مطابق یزید بن خصیفہ کی بسر بن سعید سے مروی روایت میں اس (یزید بن خصیفہ) کے قول عن ابی ہریرہ کی کسی نے متابعت نہیں کی بلکہ یعقوب بن عبداللہ بن اشج نے اس کے برعکس ابوہریرہ کی بجائے اسے زینب ثقفیہ کی مسند قراردیا ہے۔","f2":"1۔امام نسائی کے اس قول کا مطلب یہ ہے کہ مذکورہ روایت یزید بن خصیفہ نےبسر بن سعید سے بیان کی ہے اوراسے سیدنا ہریرہ رضی اللہ عنہ کی مسند بنایا ہے جب کہ ان کے علاوہ کسی نے بھی اسے سیدنا ابوہریرہ رضی اللہ عنہ کی مسند نہیں بنایا کہ بلکہ یعقوب بن عبداللہ بن اشج نے یزید کی مخالفت کی ہے اوراس روایت کو بسر بن سعید سے بیان کرتے ہوئے ابوہریرہ رضی اللہ عنہ کی بجائے سیدہ زینب ثقفیہ رضی اللہ عنہا (سیدنا عبداللہ بن مسعود رضی اللہ عنہ کی اہلیہ محترمہ) کی مسند بنایا ہے۔ مقصد یہ ہے کہ امام نسائی رحمہ اللہ کے نزدیک یعقوب بن عبداللہ بن اشج کی روایت راجح ہے۔ لیکن اصل بات یہ ہے کہ یزیدبن عبداللہ بن خصیفہ ثقہ راوی ہے اور ثقہ راوی کی حدیث میں زیادتی، جبکہ وہ اوثق کی روایت کے منافی یا اس کے مخالف نہ ہو، تو قابل قبول ہوتی ہے، لہذا یعقوب بن عبداللہ بن اشج کی مخالفت سے کوئی فرق نہیں پڑتا۔ واللہ اعلم۔ 2۔ اس حدیث مبارکہ سے یہ اہم مسئلہ ثابت ہوتا ہے کہ عورتیں نماز پڑھنے کی خاطر مسجد جاسکتی ہیں۔ 3۔ ’بخور‘ ایک قسم کی خوشبو ہے۔ جب اسے آگ سے سلگا یا جاتا ہے تو خوشبو محسوس ہوتی ہے، جیسے آج کل اگربتی وغیرہ۔ لیکن یہاں عام خوشبو مراد ہے کیونکہ کسی قسم کی خوشبو لگاکر بھی گھر سے باہر جانا عورت کےلیے جائز نہیں، خواہ مسجد کو جائے یا کہیں اور۔ عشاء کی نماز کا خصوصی ذکر اس لیے کہ اندھیرے میں عورتوں کے لیے خطرہ زیادہ ہوتا ہے یا اس لیے کہ عورتیں اپنے خاوندوں کے لیے عموماً مارات کو خوشبو لگاتی ہیں۔"}],[5129,"عبداللہ بن مسعود کی بیوی زینب رضی اللہ عنہما کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: \"جب تم میں سے کوئی عورت عشاء پڑھنے کے لیے (مسجد)آئے تو خوشبو نہ لگائے\"۔","الألباني: حسن صحيح",{"u2":"سیدنا عبداللہ بن مسعود رضی اللہ عنہ یک زوجۂ محترمہ سیدہ زینب رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب کسی عورت کا ارادہ عشاء کی نماز مسجد میں پڑھنے کا ہو تو وہ خوشبو نہ لگائے۔","f2":"معلوم ہوا کہ اگر گھر سے باہر نہ جانا ہو تو عورت اپنے خاوند کےلیے خوشبو لگا سکتی ہے۔"}],[5130,"عبداللہ بن مسعود کی بیوی زینب رضی اللہ عنہما کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: \"جب تم میں سے کوئی عورت مسجد میں عشاء میں آئے تو خوشبو نہ لگائے\"۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: یحیی اور جریر کی حدیث وہب بن خالد کی حدیث سے زیادہ قرین صواب ہے، واللہ اعلم ۱؎۔\n§وضاحت\n۱؎: جریر کی روایت یہی ہے، اور جریر و یحیی کی مشترکہ روایت نمبر ۵۲۶۲ پر آ رہی ہے، مؤلف کا مقصد یہ ہے زینب رضی اللہ عنہا کی روایت میں \" بسر بن سعید \" سے روایت کرنے والے \" بکیر \" کا ہونا یعقوب بن عبداللہ کے بالمقابل زیادہ قرین صواب بات ہے۔","الألباني: صحيح",{"u2":"سیدنا عبداللہ بن مسعود رضی اللہ عنہ کی زوجۂ محترمہ سیدہ زینب رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب کوئی عورت عشاء کی نماز مسجد میں پڑھنے کا ارادہ رکھتی ہو تو وہ خوشبو نہ لگائے۔\nابوعبدالرحمن (امام نسائی رحمہ اللہ) نے کہا کہ یحییٰ اور جریر کی حدیث وہیب بن خالد کی حدیث کی نسبت زیادہ درست ہے۔ واللہ اعلم","f2":"ہمارے سامنے جو نسخہ ہے اس میں یہی ہے کہ یحییٰ اور جریر کی حدیث وہیب بن خالد کی حدیث کی نسبت زیادہ درست ہے۔ اس میں جریر کی حدیث تو موجود ہے، (حدیث؟؟؟ جبکہ یحییٰ کی حدیث اس نسخے میں نہیں۔ شاید کاتب اور ناسخ سے یحییٰ کی روایت رہ گئی ہے اور وہ لکھ نہیں سکا۔ واللہ اعلم"}],[5131,"زینب ثقفیہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تم میں جو کوئی عورت مسجد جائے تو خوشبو نہ لگائے\"۔","الألباني: صحيح",{"u2":"سیدہ زینب ثقفیہ رضی اللہ عنہا سے مروی ہے کہ اللہ کے نبی صلی اللہ علیہ وسلم نے فرمایا: جو عورت مسجد کو جائے وہ خوشبونہ لگائے۔"}],[5132,"عبداللہ بن مسعود کی بیوی زینب ثقفیہ رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے انہیں حکم دیا کہ وہ \"جب عشاء کے لیے مسجد جائیں تو خوشبو نہ لگائیں\"۔","الألباني: صحيح",{"u2":"سیدہ زینب ثقفیہ رضی اللہ عنہا، جو حضرت عبداللہ (بن مسعود) کی زوجہ محترمہ تھیں، سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اسے (زینب کو) حکم دیا تھا کہ جب وہ عشاء کی نماز پڑھنے مسجد میں آئے تو خوشبو نہ لگائے۔","f2":"اس حدیث کا مطلب یہ نہیں کہ باقی نمازوں میں وہ خوشبو لگا کر آسکتی ہے بلکہ عشاء کا ذکر اس لیے کیا کہ یہ وقت عورتوں کے خوشبولگانے کا ہوتا ہے جیسا کہ حدیث نمبر5131 میں بیان ہوا، نیز حدین نمبر5137 میں عام نماز کا ذکر ہے۔ یہ بھی ممکن ہے کہ اندھیرے کی وجہ سے عورتیں اس وقت زیادہ حاضر ہوتی ہوں جیسا کہ فجر میں آتی تھیں۔"}],[5133,"زینب ثقفیہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب عورت عشاء کے لیے مسجد جائے تو خوشبو نہ لگائے\"۔","الألباني: صحيح",{"u2":"سیدہ زینب ثفقیہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب کوئی عورت عشاء کی نماز کے لیے (مسجد میں) آئے تو خوشبو نہ لگائے۔"}],[5134,"زینب ثقفیہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کوئی عورت جب نماز کے لیے مسجد جائے تو خوشبو نہ لگائے\"۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: یہ روایت زہری کی روایت سے غیر محفوظ ہے ۱؎۔\n§وضاحت\n۱؎: یعنی: بسر سے زہری کا راوی ہونا غیر محفوظ ہے، ان کی جگہ \" بکیر \" کا ہونا محفوظ ہے، بہرحال روایت محفوظ ہے۔","الألباني: صحيح لغيره",{"u2":"سیدہ زینب ثقفیہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب تم میں سے کوئی عورت نماز پڑھنے (مسجد میں) آ ئے تو کسی بھی قسم کی خوشبو نہ لگائے۔\nابوعبدالرحمن (امام نسائی رحمہ اللہ) نے کہا کہ یہ مذکورہ حدیث، زہری کی حدیث(کے طور پر) غیر محفوظ (اور شاذ) ہے۔","f2":"امام نسائی رحمہ اللہ کے اس قول کا مطلب یہ ہے کہ مذکورہ روایت بسند عن الزہری عن بسر بن سعید عن زینب الثقفیۃ درست نہیں بلکہ صحیح روایت بایں سند ہے: عن بکیر عن بسر بن سعید عن زینب الثقفیۃ کیونکہ حفاظ محدثین﷭ نے یہ روایت اسی طرح (بکری کی سندسے) بیان کی ہے۔ زہری کی سند سے بیان کرنے والا سنید ہے اور وہ ضعیف راوی ہے۔"}],[5135,"نافع کہتے ہیں کہ ابن عمر رضی اللہ عنہما جب دھونی لیتے تو کبھی خالص عود کی دھونی جس میں کچھ نہ ملا ہوتا لیتے اور کبھی کافور ملا کر دھونی لیتے، پھر کہتے کہ اسی طرح رسول اللہ صلی اللہ علیہ وسلم دھونی لیتے تھے۔","الألباني: صحيح",{"u2":"حضرت نافع سے روایت ہے کہ حضرت ابن عمر رضی اللہ عنہما جب خوشبو لگاتے تو ’اگر‘ کی لکڑی سلگاتے اور اس میں کوئی دوسری خوشبو نہ ڈالتے۔ البتہ کبھی ’ اگر‘ کے ساتھ کافور ڈال لیتے، پھر فرماتے کہ رسول اللہ صلی اللہ علیہ وسلم بھی اسی طرح خوشبو سلگایا کرتے تھے۔","f2":"’بخور‘ بخار سے ہے۔ چونکہ خوشبو دار لکڑی کو سلگانے سے بخارات اٹھتے ہیں جن سے خوشبو پھیلتی ہے، لہذا اس قسم کی خوشبو کو بخور کہہ دیتے ہیں ورنہ بخور کسی ایک چیز کانام نہیں۔"}],[5136,"عقبہ بن عامر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم اپنے گھر والوں کو زیورات اور ریشم سے منع فرماتے تھے اور فرماتے: \"اگر تم لوگ جنت کے زیورات اور اس کا ریشم چاہتے ہو تو اسے دنیا میں نہ پہنو\" ۱؎۔\n§وضاحت\n۱؎: اس باب میں مذکور بعض احادیث میں عورتوں کے لیے بھی سونے کے استعمال کو حرام بتایا گیا ہے، مؤلف نیز جمہور أئمہ عورتوں کے لیے سونے کے مطلق استعمال کے جواز کے قائل ہیں، اس لیے مؤلف نے ان احادیث کی گویا ایک طرح سے تاویل کرتے ہوئے یہ باب باندھا ہے، یعنی: ان احادیث میں جو عورتوں کے لیے سونے کے زیورات کو حرام قرار دیا گیا ہے، وہ اس صورت میں ہے جب وہ ان کو پہن کر بطور فخر و مباہات کی نمائش کرتی پھریں، ورنہ ہر طرح کا سونے کا زیور عورتوں کے لیے حلال ہے، بعض علماء ان احادیث کو اس حدیث سے منسوخ مانتے ہیں، \" رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: سونا اور ریشم کو مردوں کے لیے حرام کر دیا گیا ہے، اور عورتوں کے حلال کر دیا گیا ہے \"، اس حدیث میں کوئی قید نہیں کہ سونے کا زیور حلقہ دار ہو یا ٹکڑے والا، علامہ البانی نے دونوں طرح کی احادیث میں تطبیق کی راہ یہ نکالی ہے :(جس کی تائید بعض احادیث سے بھی ہوتی ہے ) کہ عورتوں کے لیے حلقہ دار سونے کا زیور :(جیسے کنگن، بالی اور انگوٹھی وغیرہ ) حرام ہے، ہاں ٹکڑے ٹکڑے والا زیور حلال ہے جیسے بٹن، ٹپ، اور ایسا ہار جس کا بعض حصہ دھاگہ ہو، وغیرہ وغیرہ، احتیاط علامہ البانی کے قول ہی میں ہے۔ :(ملاحظہ ہو: آداب الزفاف للألبانی )","الألباني: صحيح",{"u2":"سیدنا عقبہ بن عامر رضی اللہ عنہ فرماتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم اپنی بیویوں کو زیورات اور ریشم سے روکتے تھے اور فرماتے تھے: اگر تم جنت کے زیورات اور ریشم پہننا چاہتے ہو تو ان کو دنیا میں نہ پہنو۔","f2":"1۔اہل بیت کا مقام و مرتبہ بہت بلند و بالا ہے۔ ان کے لیے بعض ایسی چیزیں بھی نامناسب قرار دی گئیں جو عام مسلمانوں کےلیے جائز تھیں۔ ہر بیوی اپنے خاوند سے نقفے وغیرہ کا مطالبہ کرسکتی ہے مگر ازواج مطہرات کو ہر قسم کے مطالبے سے روک دیا گیا۔ان کو غلطی پر دگنی سزا کی وعید سنائی گئی جب کہ نیکی پر ان کا اجر بھی دوہرا ہے ارشادباری تعالی ہے: ﴿يـنِساءَ النَّبِىِّ مَن يَأتِ مِنكُنَّ بِفـحِشَةٍ مُبَيِّنَةٍ يُضـعَف لَهَا العَذابُ ضِعفَينِ وَكانَ ذلِكَ عَلَى اللَّهِ يَسيرً‌ا ﴿﴾وَمَن يَقنُت مِنكُنَّ لِلَّهِ وَرَ‌سولِهِ وَتَعمَل صـلِحًا نُؤتِها أَجرَ‌ها مَرَّ‌تَينِ وَأَعتَدنا لَها رِ‌زقًا كَر‌يمًا ﴿ سورۃ الاحزاب ’ اے نبی کی بیویو! تم میں سے جو کوئی کھلی بے حیائی کا ارتکاب کرے، اسے دوہرا عذاب دیا جائے گا اور اللہ کے لیے یہ نہایت آسان ہے۔ اور تم میں سے جو اللہ اور اس کے رسول کی فرماں برداری کرے اور نیک عمل کرے تو ہم اسے اس کا اجر دوگنا دیں گے اور اس کے لیے ہم نے عزت کا رزق تیار کر رکھا ہے۔ ‘مذکورہ حدیث بھی اہل بیت کے ساتھ خاص ہے کہ ان کو زیورات اور ریشم سے روک دیا گیا جب کہ دوسری عورتوں کےلیےآپ نے صراحتاً فرمایا: (احل الذہب والحریرلاناث امتی وحرم علی ذکورہا) ’ ریشم اور سونا میری امت کی عورتوں کے لیے حلال ہے، مردوں کےلیے حرام ہے۔‘ (جامع الترمذی، اللباس، حدیث:1720، وسنن النسائی، الزینۃ، باب تحریم الذہب علی الرجال، حدیث:5151) اس کی دوسری توجیہ یہ ہے کہ پہننا جائز ہے، نمائش مکروہ ہے۔2۔ اس حدیث مبارکہ کی بابت قوی احتمال یہی ہے کہ وہ یہ امہات المومنین ازواج رسول کریم صلی اللہ علیہ وسلم کے ساتھ خاص ہے، تاہم مسلمان خواتین کے شایان شان اور ان کے لائق بھی یہی ہے کہ وہ جنت کے زیورات سے آراستہ ہونے اور جنت کے ریشم سے شاد کا م ہونے کا خاطر ازواج مطہرات رضی اللہ عنہن کی اقتدا کرتے ہوئے دنیا میں سونے اور ریشم سے مزین ہونے سے حتی الامکان پرہیز کریں۔ ریشم اور سونا اگرچہ مسلمان خواتین کے لیے مباح اور حلال ہے، تاہم عزیمت اور استحباب اس میں ہے کہ ممکن حد تک دنیوی بناؤ سنگھار اور زیب و زینت سے محتاط رہا جائے۔"}],[5137,"حذیفہ رضی اللہ عنہ کی بہن کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہم سے خطاب کیا تو فرمایا: \"اے عورتوں کی جماعت! کیا تم چاندی کا زیور نہیں بنا سکتیں؟ دیکھو، تم میں سے جو عورت دکھانے کے لیے سونے کا زیور پہنے گی اسے عذاب ہو گا\"۔","الألباني: ضعيف",{"u2":"سیدنا حذیفہ رضی اللہ عنہ کی ہمیشرہ محترمہ فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں خطبہ دیتے ہوئے فرمایا: اے عورتوں کی جماعت! کیا تمہارے لیے یہ کافی نہیں کہ تم چاندی کے زیورات پہن لو؟ خبردار! جو بھی عورت سونے کے زیورات نمائش کےلیے پہنے گی، اسے اس کی بنا پر عذاب ہوگا۔"}],[5138,"حذیفہ رضی اللہ عنہ کی بہن کہتی ہیں کہ ہمیں رسول اللہ صلی اللہ علیہ وسلم نے خطاب کیا اور فرمایا: \"اے عورتوں کی جماعت! کیا تم چاندی کا زیور نہیں بنا سکتیں، دیکھو، تم میں سے جو عورت دکھانے کے لیے سونے کا زیور پہنے گی اسے عذاب ہو گا\"۔","الألباني: ضعيف",{"u2":"سیدنا حذیفہ رضی اللہ عنہ کی ہمشیرہ محترمہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں خطاب فرمایا: اے عورتوں کی جماعت! کیا تمہارے لیےچاندی کے زیورات کافی نہیں؟ خبردار! جوعورت سونا نمائش کے لیے پہنے گی، اسےاسی سونے سے عذا ب دیا جائے گا۔"}],[5139,"اسماء بنت یزید کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو عورت سونے کا ہار پہنے گی اللہ تعالی اس کی گردن میں اسی جیسا آگ کا ہار پہنائے گا، اور جو کان میں سونے کی بالیاں پہنے گی، اللہ تعالی اس کے کان میں اسی جیسی آگ کی بالیاں قیامت کے دن پہنائے گا\"۔","الألباني: ضعيف",{"u2":"سیدہ اسماء بنت یزید رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جو عورت(نمائش کے لیے) سونے کا ہار پہنے گی، اللہ تعالی(قیامت کےدن) اس کی گردن میں آگ کا ہار ڈالے گا۔ اور جو عورت (نمائش کےلیے) اپنے کانوں میں سونے کی بالیاں ڈالے گی، اللہ تعالی قیامت کے دن اس کے کان میں آگ کی بالیاں ڈالے گا۔"}],[5140,"ثوبان رضی اللہ عنہ کہتے ہیں کہ بنت ہبیرہ رضی اللہ عنہا رسول اللہ صلی اللہ علیہ وسلم کے پاس آئیں، ان کے ہاتھ میں بڑی بڑی انگوٹھیاں تھیں رسول اللہ صلی اللہ علیہ وسلم ان کے ہاتھ پر مارنے لگے، وہ آپ کی بیٹی فاطمہ رضی اللہ عنہا کے یہاں گئیں تاکہ ان سے اس برتاؤ کا گلہ شکوہ کریں جو رسول اللہ صلی اللہ علیہ وسلم نے ان کے ساتھ کیا تھا، تو فاطمہ رضی اللہ عنہا نے اپنے گلے کا سونے کا ہار نکالا اور بولیں: یہ مجھے ابوالحسن (علی) نے تحفہ دیا تھا، اتنے میں رسول اللہ صلی اللہ علیہ وسلم آ گئے اور ہار ان کے ہاتھ ہی میں تھا، آپ نے فرمایا: \"فاطمہ! تمہیں یہ بات پسند ہے کہ لوگ کہیں: رسول اللہ صلی اللہ علیہ وسلم کی بیٹی اور ہاتھ میں آگ کی زنجیر؟\"، پھر آپ بیٹھے نہیں چلے گئے، پھر فاطمہ رضی اللہ عنہا نے اپنا ہار بازار بھیج کر اسے بیچ دیا اور اس کی قیمت سے ایک غلام (لڑکا) خریدا اور اسے آزاد کر دیا، نبی اکرم صلی اللہ علیہ وسلم سے اس کا ذکر کیا گیا تو آپ نے فرمایا: \"شکر ہے اللہ کا جس نے فاطمہ کو آگ سے نجات دی\"۔","الألباني: صحيح",{"u2":"رسول اللہ صلی اللہ علیہ وسلم کے آزاد کردہ غلام ثوبان رضی اللہ عنہ نے بیان فرمایا کہ سیدہ فاطمہ بنت ہبیرہ رضی اللہ عنہا رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئیں تو ان کے ہاتھ میں بڑی بڑی انگوٹھیاں تھیں۔ رسول اللہ صلی اللہ علیہ وسلم ان کے ہاتھ پر (کوئی چیز) مارنے لگے۔ وہ حضرت فاطمہ بنت رسول اللہ صلی اللہ علیہ وسلم کے پاس گئیں اور ان سے رسول اللہ صلی اللہ علیہ وسلم کے اس سلوک کا شکوہ کیا۔ (یہ سن کر) سیدہ فاطمہ رضی اللہ عنہا نےاپنے گلے میں ڈالی ہوئی سونے کی زنجیر کھینچ ڈالی اور کہنے لگیں: یہ زنجیر مجھے ابوحسن (سیدنا علی رضی اللہ عنہ) نے تحفہ میں دی ہے۔ رسول اللہ صلی اللہ علیہ وسلم تشریف لائے تو زنجیران کے ہاتھ ہی میں تھی۔ آپ نے فرمایا: فاطمہ! کہ بات تیرے لیے عزت افزا ہے کہ (قیامت کے دن) لوگ کہیں، رسول اللہ صلی اللہ علیہ وسلم کی بیٹی کے ہاتھ میں آگ کی زنجیر ہے؟ پھر آپ واپس چلے گئے، بیٹھے نہیں۔ سیدہ فاطمہ رضی اللہ عنہا نے وہ زنجیر بازار بھیج کر بیچ دی اور اس کی قیمت سے ایک غلام خرید لیا اور اسے آزاد کردیا۔ رسول اللہ صلی اللہ علیہ وسلم کوساری بات بیان کی گئی توآپ نے فرمایا: شکر ہے اللہ تعالی کا اس نے فاطمہ کو آگ سے بچالیا۔","f2":"1۔’ مارنے لگے‘ کیونکہ اتنی بڑی بڑی اور کئی انگوٹھیاں نمائش اور فخر کےلیے ہی ہوسکتی تھیں۔ 2۔’ کوئی چیز‘ کیونکہ رسول اللہ صلی اللہ علیہ وسلم کا دست مبارک کبھی کسی نامحرم عورت کو نہیں لگا۔ 3۔ ’ آگ کی زنجیر‘ تفصیل دیکھئے حدیث نمبر،5139"}],[5141,"ثوبان رضی اللہ عنہ کہتے ہیں کہ ہبیرہ کی صاحب زادی رسول اللہ صلی اللہ علیہ وسلم کے پاس آئیں، ان کے ہاتھ میں سونے کی موٹی موٹی انگوٹھیاں تھیں، پھر آگے اسی طرح بیان کیا۔","الألباني: ضعيف",{"u2":"سیدنا ثوبان رضی اللہ عنہ نے فرمایا: حضرت (فاطمہ) بنت ہبیرہ رضی اللہ عنہا رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئیں تو ان کے ہاتھ میں سونے کی بڑی بڑی انگوٹھیاں تھیں۔ باقی روایت حسب سابق ہے۔","f2":"1۔ حضرت ثوبان رسول اللہ صلی اللہ علیہ وسلم کے آزاد کردہ غلام تھے۔ عربی میں آزاد کردہ غلام کو مولی کہتے ہیں۔ رضی اللہ عنہ وارضاہ۔ 2 ’سونے کی‘ تبھی تورسول اللہ صلی اللہ علیہ وسلم نے ناراضی کا اظہار فرمایا۔"}],[5142,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ میں نبی اکرم صلی اللہ علیہ وسلم کے ہاں بیٹھا ہوا تھا کہ ایک عورت نے آپ کے پاس آ کر کہا: اللہ کے رسول! میرے پاس سونے کے دو کنگن ہیں، آپ نے فرمایا: \"آگ کے دو کنگن ہیں\" وہ بولی: اللہ کے رسول! سونے کا ہار ہے، آپ نے فرمایا \"آگ کا ہار ہے\"، وہ بولی: سونے کی دو بالیاں ہیں، آپ نے فرمایا: \"آگ کی دو بالیاں ہیں\"، اس عورت کے پاس سونے کے دو کنگن تھے، اس نے انہیں اتار کر پھینک دئیے اور بولی: اگر عورت اپنے شوہر کے لیے بناؤ سنگار نہ کرے تو وہ اس کے لیے پھر کس کام کی؟ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تمہیں چاندی کی بالیاں بنانے پھر اسے زعفران یا عبیر سے پیلا کرنے سے کون سی چیز مانع ہے\"۔","الألباني: ضعيف",{"u2":"حضرت ابوہریرہ نے فرمایا: میں نبئ اکرم صلی اللہ علیہ وسلم کے پاس بیٹھاتھا کہ ایک عورت آپ کے پاس آئی اور کہا: اے اللہ کے رسو ل! میں سونے کے دو کنگن استعمال کرسکتی ہوں؟ آپ نے فرمایا: یہ آگ کے دو کنگن ہیں۔ اس نے کہا: اے اللہ کے رسول! سونے کاہار؟ آپ نے فرمایا: تیرے گلے میں ہار ہوگا آگ کا۔ وہ کہنے لگی:سونے کی بالیاں؟ آپ نے فرمایا: بالیاں بھی آگ کی ہیں۔ راوی نے کہا: اس عورت نے سونے کے دو کڑے پہن رکھے تھے، اس نے اتار کر وہ پھینک دیے۔ اس نے کہا: اے اللہ کے رسول! اگر عورت اپنے خاوند کے لیے زیب و زینت نہ لگائے تو وہ اس کے نزدیک کم مرتبہ ہو جاتی ہے۔ آپ نے فرمایا: کون سی چیز مانع ہے کہ وہ چاندی کی دو بالیاں بنالے۔ پھر اسے زعفران یا عبیر سے رنگ لے۔\nیہ الفاظ (استاد احمد) ابن حرب کےہیں۔"}],[5143,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے انہیں سونے کی پازیب پہنے دیکھا، تو فرمایا: \"میں تمہیں اس سے بہتر چیز بتاتا ہوں، تم اسے اتار دو اور چاندی کی پازیب بنا لو، پھر انہیں زعفران سے رنگ کر پیلا کر لو، یہ بہتر ہے\"۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: یہ حدیث محفوظ نہیں ہے۔ واللہ اعلم۔","الألباني: صحيح",{"u2":"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ان(حضرت عائشہ) کے ہاتھوں میں سونے کے دو کنگن دیکھے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: میں تجھے اس سے اچھی چیز نہ بتاؤں کہ تو انہیں اتار دے اور چاندی کے دو کنگن بنالے،پھر ان کو زعفران کے ساتھ سنہری بنالے۔\nابوعبدالرحمن (امام نسائی رحمہ اللہ) نے کہا: یہ(حدیث اس سیاق سے) غیر محفوظ ہے۔ واللہ اعلم","f2":"1۔ امام نسائی رحمہ اللہ کا اس سیاق کو غیر محفوظ کہنا محل نظر ہے۔ یہ حدیث سندا صحیح ہے، اس لیے اس کے غیر محفوظ ہونے کی وجہ نہیں بنتی۔ واللہ اعلم. 2۔سونا بہت قیمتی چیز ہے۔ اتنی مالیت والی چیز کو صرف زیب و زینت کے لیے رکھ چھوڑنا کوئی اچھی بات نہیں جبکہ اللہ تعالی نے اسے تجارت کے لیے پیدا فرمایا ہے۔ باقی رہی زینت! تو وہ اس کے رنگ سے بھی حاصل کی جاسکتی ہے، نیز سونے کی زیورات میں نمائش اور فخر کا غالب امکان ہے، لہذا باوجود جواز کے پرہیز بہتر ہے، خصوصاً اہل علم وفضل کےلیے۔"}],[5144,"علی بن ابی طالب رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے ریشم لے کر اسے اپنے دائیں ہاتھ میں رکھا، اور سونا لے کر اسے بائیں ہاتھ میں رکھا، پھر فرمایا: \"یہ دونوں میری امت کے مردوں پر حرام ہیں\" ۱؎۔\n§وضاحت\n۱؎: یعنی ان دونوں کا استعمال مردوں کے لیے حرام ہے۔","الألباني: صحيح",{"u2":"سیدنا علی بن ابی طالب رضی اللہ عنہ نے فرمایا کہ اللہ کے نبی صلی اللہ علیہ وسلم نے ریشم اپنے دائیں ہاتھ میں پکڑا اور سونا اپنے بائیں ہاتھ میں، پھر فرمایا: یہ دونوں چیزیں (پہننا) میری امت کے مردوں پر حرام ہیں۔","f2":"گویا عورتوں کےلیے جائزہیں جیسا کہ آئندہ روایات میں صراحتاً ذکر ہے اور مردوں کےلیے عورتوں کی مشابہت اختیار کرنا جائز نہیں۔ زیب و زینت عورتوں کا خاصہ ہے اور یہ مردانگی کے خلاف ہے۔"}],[5145,"عروہ سے روایت ہے کہ کچھ لوگوں نے رسول اللہ صلی اللہ علیہ وسلم کے اونٹ لوٹ لیے، تو آپ صلی اللہ علیہ وسلم ان کے ہاتھ اور پیر کاٹ دیے اور ان کی آنکھیں پھوڑ دیں۔\nعلی بن ابی طالب رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ریشم لے کر اسے دائیں ہاتھ میں رکھا، سونا لے کر اسے بائیں ہاتھ میں رکھا پھر فرمایا: \"یہ دونوں میری امت کے مردوں پر حرام ہیں\"۔","الألباني: صحيح لغيره",{"u2":"سیدنا علی بن ابی طالب رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نےریشم اپنے دائیں ہاتھ میں لیا اور سونا بائیں ہاتھ میں، پھر فرمایا: یہ دونوں میری امت کے مردوں پر حرام ہیں۔"}],[5146,"علی رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے ریشم لے کر اسے اپنے دائیں ہاتھ میں رکھا، اور سونا لے کر اسے اپنے بائیں ہاتھ میں رکھا، پھر فرمایا: \"یہ دونوں چیزیں میری امت کے مردوں پر حرام ہیں\"۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: ابن مبارک کی حدیث زیادہ قرین صواب ہے سوائے ان کے قول \"افلح\" کے، اس لیے کہ \"ابو افلح\" زیادہ صحیح ہے ۱؎۔\n§وضاحت\n۱؎: مولف کا مقصد یہ ہے کہ اس حدیث کی سند میں \" لیث بن سعد \" سے روایت کرنے والے پہلے \" عبداللہ بن مبارک \" کا ہونا بمقابلہ دوسروں کے زیادہ صواب ہے۔ :(جیسا کہ اس سند میں ہے ) مگر ابن مبارک سے \" ابو افلح \" کے بارے میں وہم ہو گیا ہے، صحیح \" ابوافلح \" ہے۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ نے فرمایا: نبی اللہ صلی اللہ علیہ وسلم نے ریشم لیا اور دائیں ہاتھ میں پکڑا اور سونا لیا اور اسے بائیں ہاتھ میں پکڑا، پھر فرمایا: یہ دونوں میری امت کے مردوں پر حرام ہیں۔\nابوعبدالرحمن (امام نسائی رحمہ اللہ) نے کہا کہ ابن المبارک کی حدیث درست ہے لیکن اس کا قول افلح (درست نہیں بلکہ) ابوافلح صحیح ہے۔"}],[5147,"علی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے دائیں ہاتھ میں سونا لیا اور بائیں ہاتھ میں ریشم، پھر فرمایا: \"یہ میری امت کے مردوں پر حرام ہے\"۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے سونا اپنے دائیں ہاتھ میں پکڑا اور ر یشم بائیں ہاتھ میں اور فرمایا: بے شک یہ دونوں میری امت کےمردوں پر حرام ہیں۔","f2":"اس حدیث میں دائیں بائیں کا فرق کسی راوی کی غلطی ہے کیونکہ حدیث بنیادی طور پر ایک ہی ہے۔"}],[5148,"سعید بن مسیب کہتے ہیں کہ خالی زمین کو سونے، چاندی کے بدلے کرائے پر اٹھانے میں کوئی حرج نہیں ہے۔\nابوموسی اشعری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سونا اور ریشم میری امت کی عورتوں کے لیے حلال اور مردوں کے لیے حرام ہیں\"۔","الألباني: ضعيف الإسناد مقطوع",{"u2":"سیدنا ابوموسیٰ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: سونا اور ریشم (پہننا) میری امت کی عورتوں کے لیے حلال کیا گیا ہے جبکہ مردوں پر حرام ہے۔"}],[5149,"معاویہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ریشم اور سونا پہننے سے منع فرمایا مگر جب «مقطع» یعنی تھوڑا اور معمولی ہو (یا ٹکڑے ٹکڑے ہو) ۱؎۔ (ابوعبدالرحمٰن نسائی کہتے ہیں:) عبدالوہاب نے سفیان کے برخلاف اس حدیث کو خالد سے، خالد نے میمون سے اور میمون نے ابوقلابہ سے روایت کیا ہے، (یعنی: سند میں ایک راوی \"میمون\" کا اضافہ کیا ہے)\n§وضاحت\n۱؎: «مقطع» کی ایک تفسیر «یسیر» :(یعنی کم ) بھی ہے، جب یہ معنی ہو تو یہ رخصت و اجازت عورتوں کے لیے ہے، مردوں کے لیے سونا مطلقا حرام ہے چاہے تھوڑا ہو یا زیادہ۔ عورتوں کے لیے جنس سونا حرام نہیں سونے کی اتنی مقدار جس میں زکاۃ واجب نہیں وہ اپنے استعمال میں لا سکتی ہیں، البتہ اس سے زائد مقدار ان کے لیے بھی مناسب نہیں کیونکہ بسا اوقات بخل کے سبب وہ زکاۃ نکالنے سے گریز کرنے لگتی ہیں جو ان کے گناہ اور حرج میں پڑ جانے کا سبب بن جاتا ہے، اور «مقطع» کا دوسرا معنی \" ریزہ ریزہ \" کا بھی ہے، اس کے لیے دیکھئیے حدیث نمبر ۵۱۳۹ کا حاشیہ۔","الألباني: صحيح",{"u2":"سیدنا معاویہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ریشم اور سونا پہننے سے منع فرمایا ہے مگر تھوڑا تھوڑا۔\nعبدالوہاب نے اس (سفیان بن حبیب) کی مخالفت کی ہے۔ اس نے یہ روایت خالد، عن میمون عن ابی قلابۃ کی سند سے روایت کی ہے۔ (اس نے ابو قلابہ اور خالد حذاء کےدرمیان میمون کا واسطہ بڑھادیا ہے۔) واللہ اعلم","f2":"’تھوڑا تھوڑا‘عربی میں لفظ ’ مقطع‘ استعمال کیاگیا ہے، یعنی قلیل ہو اور مختلف جگہوں پر ہو، مثلاً: تلوار کے دستے پر نقش و نگار کی صورت میں ہو یا نقاط کی صورت میں۔ پورے دستےمیں سونا نہ چڑھایا جائے۔ اسی طرح چاندی کی انگوٹھی پر سونے کے نشانات ہوں۔ اسی طرح ریشم بھی کسی اور کپڑے پر ٹکڑوں کی صورت میں قلیل مقدار میں ہو یا ریشم کی لائنیں ہوں ہوں یا چھوٹی پٹیاں ہوں تو کوئی حرج نہیں۔ گویا قلیل مقدار میں ہو اور مختلف جگہوں پر ہو۔یادر ہے کہ یہ مردوں کے لیے ہے۔ عورتوں کےلیے سونے اور ریشم کا استعمال مطلقاً جائز ہے جیسے سابقہ حدیث میں صراحت ہوچکی ہے۔"}],[5150,"معاویہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سونا پہننے سے منع فرمایا، مگر ریزہ ریزہ کر کے اور سرخ گدوں پر بیٹھنے سے (بھی منع فرمایا)۔","الألباني: صحيح",{"u2":"سیدنا معاویہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سونا پہننے سے منع فرمایا ہے الایہ کہ مختلف جگہوں پر قلیل مقدار میں ہو اور ریشمی گدیلوں پربیٹھنے سے بھی منع فرمایا۔","f2":"’ریشمی گدیلے‘ جو چیزیں مشترکہ استعمال کی ہیں انہیں عورتیں بھی استعمال کرتی ہیں اور مرد بھی اور ان میں امتیاز رکھنا مشکل ہے، وہ ریشم یا سونے سے نہیں ہونی چاہیئں۔ گدیلے پر کوئی بھی بیٹھ سکتا ہے۔"}],[5151,"ابوشیخ سے روایت ہے کہ انہوں نے معاویہ رضی اللہ عنہ کو بیان کرتے ہوئے سنا ان کے پاس کے صحابہ کرام کی ایک جماعت بھی تھی، انہوں نے کہا: کیا آپ لوگوں کو معلوم ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے سونا پہننے سے منع فرمایا ہے مگر ریزہ ریزہ کر کے؟ انہوں نے کہا: جی ہاں۔","الألباني: صحيح",{"u2":"حضرت ابوالشیخ سے روایت ہے کہ انہوں نے سیدنا معاویہ رضی اللہ عنہ کو فرماتے سنا جب کہ ان کے پاس بہت سے اصحاب محمد صلی اللہ علیہ وسلم بیٹھے تھے: کیا تم جانتے ہوکہ نبی اللہ صلی اللہ علیہ وسلم نے سونا پہننے سے منع فرمایا ہے الایہ کہ وہ مختلف جگہوں پر تھوڑا تھوڑا ہو؟ انہوں نے کہا: اللہ کی قسم! ہاں۔"}],[5152,"ابوشیخ کہتے ہیں کہ ہم لوگ ایک مرتبہ حج میں معاویہ رضی اللہ عنہ کے ساتھ تھے، اسی دوران انہوں نے صحابہ کرام کی ایک جماعت اکٹھا کی اور ان سے کہا: کیا آپ کو نہیں معلوم کہ رسول اللہ صلی اللہ علیہ وسلم نے سونا پہننے سے منع فرمایا ہے؟ مگر ریزہ ریزہ کر کے۔ لوگوں نے کہا: جی ہاں۔ (ابوعبدالرحمٰن نسائی کہتے ہیں:) یحیی بن ابی کثیر نے مطر کے خلاف روایت کی ہے جب کہ یحیی بن ابی کثیر کے شاگرد خود ان سے روایت کرنے میں مختلف ہیں۔","الألباني: صحيح",{"u2":"حضرت ابوالشیخ سے روایت ہے کہ ایک دفعہ سیدنا معاویہ رضی اللہ عنہ کے کسی حج کے دوران میں ہم ان کے ساتھ تھے کہ انہوں نے حضرت محمد صلی اللہ علیہ وسلم کے صحابہ میں سے کئی صحابہ کو جمع کیا اور فرمایا: کیا تم نہیں جانتے کہ رسول اللہ صلی اللہ علیہ وسلم نے (مردوں کو) سونا پہننے سے منع فرمایا ہے الا یہ کہ وہ مختلف جگہوں پر تھوڑا تھوڑا ہو؟ انہوں نے کہا: اللہ کی قسم! جی ہاں۔\nیحییٰ بن ابی کثیر نے مطر (الورق) کی مخالفت کی ہے، نیز اس (یحییٰ بن ابی کثیر) پر اس کے شاگردوں نے بھی اختلاف کیا ہے۔","f2":"مطر نے بایں سند حدیث بیان کی ہے: عن ابی شیخ قال: بینما نحن مع معاویۃ جبکہ یحییٰ بن ابی کثیر نے بیان کیا ہے تو کہا ہے: حدثنی ابوشیخ الہنائی عن ابی حمان: ان معاویۃ.... تو یحییٰ نے ابو شیخ اور حضرت معاویہ کے درمیان ابوحمان کا و اسطہ بڑھادیا ہے، نیز یحییٰ بن ابی کثیر کے شاگردوں میں بھی اختلاف ہے۔ علی بن مبارک نے یحییٰ سے بیان کیا ہے تو کہا ہے: حدثنی ابوشیخ الہنائی عن ابی حمان ان معاویۃ لیکن جب یحییٰ کے شاگردحرب بن شداد نے اس سے بیان کیا ہے تو کہا ہے:حدثنی ابوشیخ عن اخیہ حمان: ان معاویۃ...... اس کی تفصیل اگلی روایات میں آرہی ہے۔"}],[5153,"ابوحمّان سے روایت ہے کہ جس سال معاویہ رضی اللہ عنہ نے حج کیا، اس سال کعبے میں رسول اللہ صلی اللہ علیہ وسلم کے کئی صحابہ کو جمع کر کے کہا: میں آپ کو قسم دیتا ہوں! کیا رسول اللہ صلی اللہ علیہ وسلم نے سونا پہننے سے منع فرمایا ہے؟ لوگوں نے کہا: ہاں۔ وہ بولے: میں بھی اس کا گواہ ہوں۔ (ابوعبدالرحمٰن نسائی کہتے ہیں:)حرب بن شداد نے اسے علی بن مبارک کے خلاف روایت کرتے ہوئے «عن یحیی عن ابی شیخ عن أخیہ» حمان کہا ہے۔","الألباني: صحيح",{"u2":"حضرت ابوحمان سے مروی ہے کہ جس سال سیدنا معاویہ رضی اللہ عنہ نے حج کیا انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے بہت سے صحابہ کو کعبہ میں جمع کیا اور فرمایا کہ میں تم سے اللہ تعالی کا واسطہ دے کر پوچھتا ہوں: کیا رسول اللہ صلی اللہ علیہ وسلم ے سونا پہننے سے منع فرمایا ہے؟ ان سب نے فرمایا: جی ہاں۔ سیدنا معاویہ رضی اللہ عنہ نے فرمایا: میں بھی گواہی دیتا ہوں۔\nحرب بن شداد نے اس (علی بن مبارک) کی مخالفت کی ہے۔ اس(حرب) نے یہ حدیث (اس طرح) بیان کی ہے: عن یحییٰ، عن ابی شیخ عن اخیہ حمان۔","f2":"سابقہ حدیث کےتحت اس کی وضاحت ہوچکی ہے۔"}],[5154,"ابوشیخ کے بھائی حمان سے روایت ہے کہ جس سال معاویہ رضی اللہ عنہ نے حج کیا، صحابہ کرام کی ایک جماعت کو کعبے میں اکٹھا کر کے ان سے کہا: میں آپ کو اللہ کی قسم دیتا ہوں۔ کیا رسول اللہ صلی اللہ علیہ وسلم نے سونا پہننے سے منع فرمایا؟ لوگوں نے کہا: ہاں، انہوں نے کہا: میں بھی اس کا گواہ ہوں۔ (ابوعبدالرحمٰن نسائی کہتے ہیں:) اوزاعی نے حرب بن شداد کے خلاف روایت کی ہے جب کہ خود اوزاعی کے شاگرد ان سے روایت کرنے میں مختلف ہیں۔","الألباني: صحيح",{"u2":"حضرت حمان سے روایت ہے کہ جس سال سیدنا معاویہ رضی اللہ عنہ حج کو گئے انہوں نے بہت سے اصحاب رسول اللہ صلی اللہ علیہ وسلم کو کعبہ میں اکٹھے کرکے فرمایا: میں تم سے اللہ تعالی کے نام پر پوچھتا ہوں: کیا رسول اللہ صلی اللہ علیہ وسلم نے سونا پہننے سے منع فرمایا ہے؟ انہوں نے فرمایا: جی ہاں۔ سیدنا معاویہ رضی اللہ عنہ نے فرمایا: میں بھی گواہی دیتا ہوں۔\nاوزاعی نے اس (حرب بن شداد) کی مخالفت کی ہے، نیز اوزاعی کے شاگردوں نے اس پر اختلاف کیا ہے۔","f2":"اوزاعی رحمہ اللہ نے حرب بن شداد کی مخالفت اس طرح کی ہے کہ وہ یحییٰ بن ابی کثیر سے بیان کرتے ہوئے کہتے ہیں: حدثنی ابوشیخ، قال: حدثنی حمان، جبکہ حرب بن شداد نے ’حمان‘ کی بجائے عن اخیہ حمان‘ کہا ہے جیسا کہ پہلے اس کی وضاحت کی جا چکی ہے اوزاعی کے شاگر دوں کا اس پر اختلاف یوں ہے (جس کی تفصیل اگلی روایات میں آرہی ہے) کہ شعیب نے اوزاعی سے بیان کیا تو کہا: حدثنی ابوشیخ قال: حدثنی حمان، قال حج معاوبۃ..... عمارہ بن بشر نے اس سے بیان کیا تو کہا: حدثنی ابواسحاق، قال: حدثنی حمان، قال حج معاویۃ اوزاعی کے ایک شاگرد عقبہ (ابن علقمہ معافری بیروتی) نے اوزاعی سے بیان کیا تو کہا:حدثنی ابو اسحاق، قال: حدثنی ابن حمان، قال: حج معاویۃ.... اوزاعی کے چوتھے شاگرد یحیی بن حمزہ نے بیان کیا تو اوزاعی کے دیگر بیان کرنے والے تینوں شاگردوں سے اختلاف کرتے ہوئے کہا: حدثنا یحییٰ: حدثنا حمان قال: حج معاویۃ.... خلاصۂ کلام یہ ہے کہ شعیب نے، اپنے استاد اوزاعی سے یحیی بن ابی کثیر والی روایت بیان کی تو یحیی بن ابی کثیر کا استاد ابوشیخ کو بیان کیا ہے۔ عمارہ بن بشر نے اوزاعی سے یحیی کی روایت بیان کی تو یحییٰ بن ابی کثیر کا استاد ابو اسحاق السبیعی کو قراردیا ہے۔ اوزاعی کے ایک اورشاگرد یحییٰ بن حمزہ نے یہی روایت بیان کی تو یحییٰ بن ابی کثیر کا استاد حمان بیان کیا۔مزید تفصیل کےلیے دیکھئے (ذخیرۃ العقبیٰ شرح سنن النسائی للاتیوبی:38؍227۔229)"}],[5155,"حمان بیان کرتے ہیں کہ معاویہ رضی اللہ عنہ نے حج کیا تو انصار کے کچھ لوگوں کو کعبے میں بلا کر کہا: میں آپ کو اللہ کی قسم دیتا ہوں۔ کیا آپ لوگوں نے رسول اللہ صلی اللہ علیہ وسلم کو سونا سے منع فرماتے نہیں سنا؟ لوگوں نے کہا: ہاں۔ وہ بولے: اور میں بھی اس کا گواہ ہوں۔","الألباني: صحيح",{"u2":"حضرت حمان نے بیان فرمایا کہ سیدنا معاویہ رضی اللہ عنہ حج کو گئے تو آپ نے انصار کی ایک جماعت کو کعبہ میں بلایا اور فرمایا: میں تمہیں اللہ کا واسطہ دے کر پوچھتا ہوں، کیا تم نے رسول اللہ صلی اللہ علیہ وسلم کو سونے کے استعمال سے منع فرماتے نہیں سنا؟ ان سب نے کہا: ہاں! (ہم نے ضرور سنا ہے) سیدنا معاویہ رضی اللہ عنہ نے فرمایا: میں بھی اس بات پر گواہ ہوں(میں نے بھی سنا ہے۔)"}],[5156,"حمان کہتے ہیں کہ معاویہ رضی اللہ عنہ نے حج کیا تو کعبہ میں انصار کے کچھ لوگوں کو بلا کر کہا: میں آپ لوگوں کو اللہ کی قسم دیتا ہوں، کیا آپ لوگوں نے رسول اللہ صلی اللہ علیہ وسلم کو سونا سے منع فرماتے نہیں سنا؟ انہوں نے کہا: ہاں، وہ بولے: اور میں بھی اس کا گواہ ہوں۔","الألباني: صحيح",{"u2":"حضرت حمان نے بیان فرمایا کہ سیدنا معاویہ رضی اللہ عنہ حج کو گئے تو انہوں نے انصار کی ایک جماعت کو کعبہ میں بلایا اور فرمایا: میں تمہیں اللہ تعالی کا واسطہ دے کر پوچھتا ہوں، کیا تم نے رسول اللہ صلی اللہ علیہ وسلم کوسونے کے استعمال سے منع فرماتے نہیں سنا؟ انہوں نے کہا:اللہ کی قسم! جی ہاں! (ہم نے سنا ہے) سیدنا معاویہ رضی اللہ عنہ نے فرمایا: میں بھی گواہی دیتا ہوں (کہ میں نے بھی آپ سے سنا ہے)"}],[5157,"ابوحمان کہتے ہیں کہ معاویہ رضی اللہ عنہ نے حج کیا، تو انصار کے کچھ لوگوں کو کعبے میں بلا کر کہا: میں آپ لوگوں کو اللہ کی قسم دیتا ہوں! کیا آپ لوگوں نے رسول اللہ صلی اللہ علیہ وسلم کو سونا سے منع فرماتے نہیں سنا؟ انہوں نے کہا: ہاں۔ وہ بولے: اور میں بھی اس کا گواہ ہوں۔","الألباني: صحيح",{"u2":"حضرت ابن حمان سے روایت ہے کہ سیدنا معاویہ رضی اللہ عنہ حج کو گئے تو وہاں انہوں نے کعبہ میں انصار کی ایک جماعت کو بلایا اور فرمایا: کیا تم نے رسول اللہ صلی اللہ علیہ وسلم کو سونے کے استعمال سے منع فرماتے نہیں سنا؟ انہوں نے فرمایا: ہاں!(سنا ہے) سیدنا معاویہ رضی اللہ عنہ نے فرمایا: میں بھی گواہی دیتا ہوں۔"}],[5158,"حمان بیان کرتے ہیں کہ معاویہ رضی اللہ عنہ نے حج کیا، اور انصار کے کچھ لوگوں کو کعبے میں بلا کر کہا: میں آپ لوگوں کو اللہ کی قسم دیتا ہوں! کیا آپ لوگوں نے رسول اللہ صلی اللہ علیہ وسلم کو سونا سے منع فرماتے نہیں سنا؟ انہوں نے کہا: ہاں۔ وہ بولے: اور میں بھی اس کا گواہ ہوں۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: عمارہ یحیی(یحیی بن حمزہ) سے حفظ میں زیادہ پختہ ہیں اور ان کی حدیث زیادہ قرین صواب ہے ۱؎۔\n§وضاحت\n۱؎: یعنی یحیی بن ابی کثیر اور حمان کے درمیان ابواسحاق کا واسطہ اولی و انسب ہے۔","الألباني: صحيح",{"u2":"حضرت حمان نے فرمایا کہ سیدنا معاویہ رضی اللہ عنہ حج کرنے گئے تو انہوں نے انصار کے کچھ لوگوں کو کعبہ میں بلایا اور فرمایا: میں تمہیں اللہ تعالی کا واسطہ دے کر پوچھتا ہوں، کیا تم نے رسول اللہ صلی اللہ علیہ وسلم کو سونے کے استعمال سے منع فرماتے نہیں سنا؟ ان سب نے کہا:اللہ کی قسم! ہاں(سنا ہے) سیدنا معاویہ رضی اللہ عنہ نے فرمایا: میں بھی گواہی دیتا ہوں۔\nابوعبدالرحمن (امام نسائی رحمہ اللہ) نے کہا کہ عمارہ، یحیی کی نسبت زیادہ حافظ ہے اور اس کی حدیث درست اور صحیح ہونے کی زیادہ حق دار ہے۔","f2":"شارح سنن النسائی محمدبن علی الایتوبی کہتے ہیں کہ’ المجتبیٰ‘ والے نسخے میں’ عمارہ‘ ہے لیکن درست ’قتادہ‘ ہے جیسا کہ سنن نسائی ’الکبریٰ‘ 5؍349 اور تحفۃ الاشراف 8؍436 میں ہے۔ امام نسائی رحمہ اللہ نے عمارہ (در حقیقت قتادہ) کی روایت کو صحیح قرار دیا ہے۔ اس کی وجہ یہ ہے کہ’قتادہ‘ یحیی کی نسبت احفظ ہے، اس لیے اس کی بیان کردہ روایت راجح ہے کیونکہ اس طرح وہ محفوظ صحیح روایت بنتی ہے۔ خلاصۂ کلام یہ ہے کہ قتادۃ عن ابی شیخ عن معاویۃ رضی اللہ عنہ والی بلاواسطہ روایت ہی صحیح ہے جبکہ دیگر رواۃ نے ابوشیخ اور سیدنا معاویہ رضی اللہ عنہ کے درمیان حمان یا ابوحمان یا ابن حمان کا واسطہ بیان کیا ہے۔ واللہ اعلم"}],[5159,"ابوشیخ ہنائی کہتے ہیں کہ میں نے معاویہ رضی اللہ عنہ کو سنا، ان کے اردگرد مہاجرین و انصار کے کچھ لوگ تھے، معاویہ نے ان سے کہا: کیا آپ لوگ جانتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ریشم پہننے سے منع فرمایا ہے؟ انہوں نے کہا: ہاں، وہ بولے: اور سونا پہننے سے منع فرمایا ہے، مگر جب «مقطع» ہو؟ ان لوگوں نے کہا: ہاں۔ (ابوعبدالرحمٰن نسائی کہتے ہیں:) علی بن غراب نے نضر بن شمیل کے خلاف اس حدیث کو بیھس سے انہوں نے ابوشیخ سے اور انہوں نے ابن عمر رضی اللہ عنہما سے روایت کیا ہے۔","الألباني: صحيح",{"u2":"حضرت ابو شیخ ہنائی نے کہا: میں نے سیدنا معاویہ رضی اللہ عنہ سے سنا جب کہ ان کے اردگرد مہاجرین و انصار کے بہت سے لوگ تھے،انہوں نے فرمایا: کیا تم جانتے ہوکہ رسول اللہ صلی اللہ علیہ وسلم نے ریشم پہننے سے منع فرمایا ہے؟ ان سب نے کہا: اللہ کی قسم!جی ہاں۔ سیدنا معاویہ رضی اللہ عنہ نے فرمایا: اور آپ نے سونا استعمال کرنے سے بھی منع فرمایا: جی ہاں۔\nعلی بن غراب نے اس (نضربن شمیل) کی مخالفت کی ہے اور(اس حدیث کو) ابن عمر کی مسند قراردیا ہے۔"}],[5160,"ابوشیخ کہتے ہیں کہ میں نے ابن عمر رضی اللہ عنہما کو سنا کہ انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے سونا پہننے سے منع فرمایا ہے الا یہ کہ وہ «مقطع» ہو (تو جائز ہے)۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: نضر کی حدیث زیادہ قرین صواب ہے۔ (یعنی: بیھس کی سند سے بھی معاویہ رضی اللہ عنہ کی روایت سے ہونا زیادہ صواب ہے)۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے سونے کے استعمال سے منع فرمایا الا یہ کہ وہ بکھرا ہوا ہو۔\nابوعبدالرحمن (امام نسائی رحمہ اللہ) نے کہا کہ نضر(ابن شمیل) کی حدیث زیادہ درست ہے۔","f2":"1۔امام نسائی کا مقصد یہ بیان کرنا ہے کہ مذکورہ روایت سے پہلی روایت (حدیث: 5162)زیادہ درست ہے جو کہ نضربن شمیل بیہس بن فہد ان سے، وہ ابوشیخ ہنائی سے اور وہ سیدنا معاویہ رضی اللہ عنہ سے بیان کرتے ہیں جبکہ مذکورہ روایت: 5163 جو کہ علی بن غراب نے بیہس بن فہدان سے، اس نے ابوشیخ سےاور اس نےحضرت عبداللہ بن عمر رضی اللہ عنہما سے بیان کی ہے، یہ روایت ابن عمر کی مسند کے طور پر تو ضعیف ہے، تاہم اس کا متن سیدنا معاویہ رضی اللہ عنہ کی مسند کی وجہ سے صحیح ہے۔ نضربن شمیل علی بن غراب سے کہیں زیادہ حافظ اور اثبت ہے جبکہ علی بن غراب تو ضعیف و مدلس اور شیعہ تھا۔ واللہ اعلم۔ 2۔ ترجمے میں چونکہ سند ذکر نہیں ہوتی، لہذا قارئین کےلیے ایک روایت کا اس قدر زیادہ تکرار ملال و اکتاہٹ کا باعث بنتا ہے اور انہیں یہ بے فائدہ معلوم ہوتا ہے لیکن امام نسائی رحمہ اللہ نے مقصود سند کے بیان میں اختلاف ظاہر کرنا ہے جو حدیث کی حیثیت جانچنے کے لیے بنیاد کی حیثیت رکھتا ہے اور محدثین کے نزدیک یہ انتہائی، قیمتی مفید اور دلچسپ چیز ہوتی ہے۔"}],[5161,"عرفجہ بن اسعد رضی اللہ عنہ سے روایت ہے کہ زمانہ جاہلیت میں جنگ کلاب کے دن ان کی ناک کٹ گئی، تو انہوں نے چاندی کی ناک بنوا لی، پھر اس میں بدبو آ گئی تو نبی اکرم صلی اللہ علیہ وسلم نے انہیں سونے کی ناک بنوانے کا حکم دیا۔\n§وضاحت\n۱؎: کلاب ایک چشمے یا کنویں کا نام ہے، زمانہ جاہلیت میں اس کے پاس ایک عظیم جنگ لڑی گئی تھی۔ اسی حدیث سے استدلال کرتے ہوئے علماء نے بوقت حاجت سونے کی ناک بنوانے اور دانتوں کو سونے کے تار سے باندھنے کو مباح قرار دیا ہے۔","الألباني: حسن",{"u2":"سیدنا عرفجہ بن اسعد رضی اللہ عنہ سے روایت ہے کہ دور جاہلیت میں جنگ کلاب کے دن ان کی ناک کٹ گئی تھی تو انہوں نے چاندی کی ناک لگوالی لیکن (وہ خراب ہوگئی اور) اس سے بدبو آنے لگی تو نبئ اکرم صلی اللہ علیہ وسلم نے فرمایا کہ وہ سونے کی ناک لگوالے۔","f2":"۔ چاندی کو زنگ لگ جاتا ہے۔ ناک میں عموماً رطوبت رہتی ہے، اس لیے چاندی کو زنگ لگ گیا اور اس میں رطوبت اٹکنے لگی اور اس سے بدبوآنے لگی، بخلاف اس کے سونا بہت مضبوط اور نفیس دھات ہے۔ اسے اتنی جلدی زنگ نہیں لگتا اوریہ خراب بھی نہیں ہوتا، اس لیے آپ صلی اللہ علیہ وسلم نے انہیں سونے کی ناک لگوانے کا مشورہ دیا۔ 2۔ معلوم ہواکہ مرد کے لیے سونے کا استعمال بطور زینت منع ہے، بطور ضرورت جائزہے، مثلاً: دانت ہلنے لگیں تو انہیں سونے کے تار سے بندھوایا جاسکتا ہے۔ اسی طرح کوئی اور ضرورت پڑ جائے تو کوئی حرج نہیں۔ 3۔ ’ جنگ کلاب‘ کلاب ایک کنویں یا چشمے کا نام تھا۔ وہاں دور جاہلیت میں زبردست جنگ ہوئی تھی جو بہت مشہور ہوئی۔"}],[5162,"عبدالرحمٰن بن طرفہ کہتے ہیں کہ انہوں نے دیکھا کہ جاہلیت میں جنگ کلاب کے دن ان کے دادا (عرفجہ بن اسد رضی اللہ عنہ) کی ناک کٹ گئی، تو انہوں نے چاندی کی ناک بنوائی، پھر اس میں بدبو آ گئی تو نبی اکرم صلی اللہ علیہ وسلم نے انہیں حکم دیا کہ وہ سونے کی ناک بنوا لیں۔","الألباني: حسن",{"u2":"حضرت عبدالرحمن بن طرفہ نے اپنے دادا محترم سیدنا عرفجہ بن اسعد رضی اللہ عنہ سے بیان کیا اورانہوں نے اپنے دادا محترم کو دیکھا تھا کہ جنگ کلاب کے دن ان کی ناک کٹ گئی تھی۔ انہوں نے چاندی کی ناک لگوالی لیکن اس سے بدبو آنے لگی تو نبئ اکرم صلی اللہ علیہ وسلم نے انہیں فرمایا کہ سونے کی ناک لگوالو۔"}],[5163,"سعید بن مسیب کہتے ہیں کہ عمر رضی اللہ عنہ نے صہیب رضی اللہ عنہ سے کہا: کیا وجہ ہے کہ میں تمہیں سونے کی انگوٹھی پہنے دیکھتا ہوں؟ انہوں نے کہا: اسے تو انہوں نے بھی دیکھا ہے جو آپ سے بہتر تھے، لیکن اسے معیوب نہیں سمجھا۔ پوچھا: وہ کون ہیں؟ انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم۔\n§وضاحت\n۱؎: یہ حدیث منکر ہے، کیونکہ عطاء خراسانی مدلس ہیں اور عنعنہ کے ساتھ روایت کی ہے، اور ان کی یہ روایت صحیح روایات کے خلاف ہے۔","الألباني: ضعيف الإسناد",{"u2":"حضرت سعید بن مسیب رحمہ اللہ سےروایت ہے کہ سیدنا عمر رضی اللہ عنہ نےسیدنا صہیب رضی اللہ عنہ سے فرمایا:کیاوجہ ہے کہ میں تم پر سونے کی انگوٹھی دیکھتا ہوں؟ وہ فرمانے لگے: یہ آپ سے بہتر شخصیت نے دیکھی تھی۔ انہوں نے تو اس پر عیب نہیں لگایاتھا۔ حضرت عمر رضی اللہ عنہما نے فرمایا: وہ کون تھے؟ انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم۔"}],[5164,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سونے کی انگوٹھی بنوائی، پھر اسے پہنا، تو لوگوں نے بھی سونے کی انگوٹھی بنوائی، آپ نے فرمایا: \"میں یہ انگوٹھی پہنتا تھا لیکن اب کبھی نہیں پہنوں گا\" اور اسے پھینک دی تو لوگوں نے بھی اپنی انگوٹھیاں پھینک دیں۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما سے روایت ہے، انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے (پہلے) سونے کی انگوٹھی بنوائی اور پہنی تولوگوں نے بھی سونے کی انگوٹھیاں بنوا لیں۔ تب رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: میں یہ (سونے کی) انگوٹھی پہنا کرتا تھا لیکن آئندہ اسے کبھی نہیں پہنوں گا۔یہ فرمانے کے بعد آپ نے سونے کی انگوٹھی اتار پھینکی تو لوگوں نے بھی اپنی(سونے کی) انگوٹھیاں اتار پھینکیں۔","f2":"1۔اس حدیث سے معلوم ہوا کہ ابتداء مردوں کے لیے بھی سونے کی انگوٹھی پہننی جائز تھی، اس لیے رسول اللہ صلی اللہ علیہ وسلم نے اور آپ کے ساتھ ساتھ صحابۂ کرام رضی اللہ عنہم نے بھی سونے کی انگوٹھیاں بنوائیں اور پہنیں۔2۔ اس حدیث مبارکہ سے صحابۂ کرام رضی اللہ عنہم کی عظمت بھی آشکارا ہوتی ہے کہ وہ رسول اللہ صلی اللہ علیہ وسلم نے سونے کی انگوٹھی پہنی ہوئی ہے تو انہوں نے سونے کی انگوٹھیاں بنوا کر پہن لیں اور جب نبئ اکرم صلی اللہ علیہ وسلم نے اتار پھینکی تو ان سب نے بھی اتار دیں۔ رسول کریم صلی اللہ علیہ وسلم کے تمام اقوال و افعال میں حضرات صحابۂ کرام رضی اللہ عنہم کی فرماں برداری کا یہی تھا الا یہ کہ کوئی عمل آپ کی خصوصیت ہو۔ 3۔مردوں کے لیے یقیناً سونے کی انگوٹھی پہننے کی بابت، اہل شام کے بعض علماء کے علاوہ تمام اہل اسلام کا اس کے جواز پر اتفاق ہے۔ دیگر صحیح روایات میں صراحت ہے کہ پھر رسول اللہ صلی اللہ علیہ وسلم نے چاندی کی انگوٹھی بنوالی تاکہ خطوط وفرامین پر مہر لگاسکیں۔ نبئ اکرم صلی اللہ علیہ وسلم کے بعد وہی انگوٹھی خلیفۂ رسول، خلیفہ بلافصل سیدنا ابوبکر صدیق رضی اللہ عنہ نے پہنی، پھر ان کے بعد خلیفۂ ثانی، امیر المومنین سیدنا عمرفاروق رضی اللہ عنہ نے پہنی،، پھر ان کے بعد تیسرے خلیفۂ راشدین سیدنا عثمان ذوالنورین رضی اللہ عنہ نے پہنی حتی کہ وہ انگوٹھی بئر اریس میں گرگئی اور تلاش بسیار کے باوجود نہ ملی۔ (صحیح البخاری، اللباس، باب خاتم الفضۃ، حدیث:5866، وصحیح مسلم، اللباس والزینۃ، باب لبس النبی صلی اللہ علیہ وسلم خاتما من ورق.....، حدیث: 2019) 4۔’ کبھی نہیں پہنوں گا‘ گویا اجازت منسوخ ہوگئی۔ آئندہ احادیث میں حرمت کی صراحت ہے۔5۔ ’اتار پھینکی‘ پھر پکڑلی یا صحابۂ کرام رضی اللہ عنہم نے اٹھا کر پکڑا دی ہوگی۔ بعض کا خیال ہے یہ مطلب نہیں کہ اتار کر زمین پر پھینک دی بلکہ جیب وغیرہ میں ڈال لی کیونکہ مال ضائع کرنا حرام ہے۔ واللہ اعلم"}],[5165,"علی رضی اللہ عنہ کہتے ہیں کہ مجھے نبی اکرم صلی اللہ علیہ وسلم نے سونے کی انگوٹھی، ریشم، سرخ گدیوں اور گیہوں یا جو کی شراب سے منع فرمایا۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ نے فرمایا: نبئ اکرم صلی اللہ علیہ وسلم نے مجھے سونے کی انگوٹھی، ریشمی کپڑوں اور سرخ ریشمی گدیلوں اور جعہ(کے استعمال) سے منع فرمایا۔","f2":"1۔ ’ریشمی کپڑوں‘ عربی میں لفظ قسی استعمال کیا گیا ہے۔ قس مصر کے علاقے میں ایک بستی کا نام تھا، جہاں ریشمی کپڑے بنائے جاتے تھے۔ ان کو قسی کہا جاتا تھا۔ مراد ریشمی کپڑے ہیں، قس میں بنیں یا کہیں اور کیونکہ حرمت کی وجہ ریشم ہونا ہے نہ کہ قس بستی میں تیار ہونا۔ دوسری توجیہ یہ کی گئی ہے کہ قس اصل میں قز تھا اور اس کے معنی ہیں کچا ریشم۔ گویا قسی سے مراد کچے ریشم سے بنائے گئے کپڑے ہیں، یعنی ریشم کا استعمال مردوں کے لیے حرام ہے چاہے کچا ہو یا پکا۔ 2۔ ’ سرخ ریشمی گدیلوں‘ ریشمی گدیلے عموماً سرخ ہوتے تھے ورنہ ریشمی گدیلے حرام ہیں، سرخ ہوں یا سبز، سفید ہوں یا سیاہ۔ 3۔’ جعہ‘ جو کا نبیذ جس میں نشہ ہوتا تھا۔"}],[5166,"علی رضی اللہ عنہ سے روایت کہ رسول اللہ صلی اللہ علیہ وسلم نے سونے کی انگوٹھی، ریشمی کپڑے اور سرخ زین (گدے) کے استعمال سے منع فرمایا۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ سے روایت ہے، انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے مجھے سونے کی انگوٹھی قسی کپڑوں اورسرخ گدیلوں کے استعمال سے منع فرمایا ہے۔","f2":"’سرخ گدیلوں‘ ان میں روئی بھری ہوتی تھی اور انہیں اونٹ کے پالان کے اوپر رکھا جاتا تھا تاکہ پالان کی لکڑی سےجسم کو تکلیف محسوس نہ ہو۔ ریشمی نہ ہو تو کوئی حرج نہیں۔ بعض نے سرخ رنگ بھی منع کیا ہے کیونکہ اس کی شوخی زیادہ ہوتی ہے اور یہ آرام سے زیادہ زیب و زینت کے لیے ہوتا ہےاورمردوں کو زینت زیب نہیں دیتی۔"}],[5167,"علی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سونے کے چھلوں، سرخ زین، ریشمی کپڑے اور جعہ سے منع فرمایا، جعہ ایک قسم کی شراب ہے جو جو اور گیہوں سے بنائی جاتی ہے۔ اور راوی نے اس کی شدت (تیزی) کا ذکر کیا۔ (ابوعبدالرحمٰن نسائی کہتے ہیں:) عمار بن رزیق نے اس حدیث کو زہیر کے برخلاف ابواسحاق سے، ابواسحاق نے صعصعہ سے، اور صعصہ نے علی رضی اللہ عنہ سے روایت کیا ہے۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ نےفرمایا: رسول اللہ صلی اللہ علیہ وسلم نے سونے کی انگوٹھی (اور چھلے) ’سرخ ریشمی گدیلے، قسی کپڑوں اور جعہ (کےاستعمال) سے منع فرمایا ہے۔ جعہ ایک مشروب تھا جو جو اور گندم سےبنایا جاتا تھا اور نشہ آور ہوتا تھا۔\nعمار بن رزیق نے اس (زہیر) کی مخالفت کی ہے اور اس نے یہ روایت ’ عن ابی اسحاق، عن صعصعۃ عن علی‘ کی سند سے بیان کی ہے۔","f2":"امام نسائی رحمہ اللہ یہ کہنا چاہتے کہ مذکورہ حدیث:5170، زہیر(بن معاویہ) نے عن ابی، اسحاق عن ہبیرہ سمعہ من علی کی سند سے بیان کی ہے جبکہ عمار بن رزیق نے عن ابی اسحاق عن ہبیرۃ کی بجائے عن اسحاق، عن صعصعۃ بیان کیا ہے۔ دیکھئے، اگلی حدیث:5171."}],[5168,"علی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے سونے کے چھلوں، ریشمی کپڑوں، سرخ زین، جَو اور گیہوں کے شراب سے منع فرمایا۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: اس سے پہلی حدیث زیادہ قرین صواب ہے ۱؎۔\n§وضاحت\n۱؎: یعنی ابواسحاق کا ہبیرہ سے اور ان کا علی رضی اللہ عنہ سے روایت کرنا اولی و انسب ہے بمقابلہ: عن ابی اسحاق عن صعصعہ عن علی رضی اللہ عنہ۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ سے روایت ہے کہ رسو ل اللہ صلی اللہ علیہ وسلم نے مجھے سونے کی انگوٹھی، قسی کپڑوں‘ ریشمی گدیلے اور جعہ کےاستعمال سے منع فرمایا۔\nابوعبدالرحمن (امام نسائی رحمہ اللہ) نے کہا: اس (حدیث:5171) سے پہلی روایت(5170) زیادہ درست ہے۔","f2":"1۔ امام نسائی نے عن ابی اسحاق عن ہبیرۃ بن مریم، عن علی والی سابقہ روایت کو ترجیح دیتے ہوئے صحیح قراردیا ہے۔ اس کی وجہ یہ ہے کہ ابو اسحاق کے دیگر شاگرد، مثلاً: ابوالاحوص، زکریا بن ابوزائدہ اور زہیربن معاویہ تینوں نے بایں سند بیان کیا ہے: عن اسحاق عن ہبیرۃ بن مریم دیکھئے: (سنن النسائی، الزینۃ، باب خاتم الذہب، حدیث:5168، 5169، 5170) مزید برآں یہ کہ ابوداؤد کی روایت میں امام شعبہ رحمہ اللہ نے بھی ان تینوں کی متابعت کی ہے۔ انہوں نے بھی اسی طرح بیان کیا ہے: عن ابی اسحاق عن ہبیرۃ عن علی...... عمار بن رزیق نے ابواسحاق کے تمام شاگردوں کی مخالفت کی ہے اور یہ روایت عن ابی اسحاق، عن صعصعۃ عن علی کی سندسے بیان کی، اس لیے عمار بن رزیق کی بیان کردہ روایت شاذ اور ابواسحاق کے دیگر شاگردوں کی روایت محفوظ بنتی ہے، لہذا یہی روایت ارجح ہے۔ یاد رہے کہ یہ شذوذ صرف اس سند میں ہے۔ جہاں تک متن کا تعلق ہے تو وہ صحیح ہے کیونکہ صعصعہ کی روایت بھی سیدنا علی رضی اللہ عنہ سے دوسرے طریق سے صحیح ہے جیسا کہ آئندہ حدیث میں ہے۔ واللہ اعلم. 2۔ ہر نشہ آور مشروب حرام ہے، خواہ کسی چیز سے بنا ہو، قلیل ہو یا کثیر۔ تفصیل پیچھے گزر چکی ہے۔"}],[5169,"صعصعہ بن صوحان کہتے ہیں کہ میں نے علی رضی اللہ عنہ سے کہا: آپ ہمیں منع فرمایئے اس چیز سے جس سے آپ کو رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا، وہ بولے: مجھے منع فرمایا: کدو سے بنے اور سبز رنگ کے برتن سے، سونے کے چھلے، ریشمی لباس اور حریر اور سرخ زین کے استعمال سے۔","الألباني: صحيح",{"u2":"حضرت صعصعہ بن صوحان سے روایت ہے کہ میں نے سیدنا علی رضی اللہ عنہ سے کہا: ہمیں اس چیز سے منع فرمائیے جس سے رسول اللہ صلی اللہ علیہ وسلم نے آپ کو منع فرمایا ہے۔ انہوں نے فرمایا: آپ نے مجھے کدو کے برتن اور سبز مٹکے (کے نبیذ)، سونے کی انگوٹھی، ریشم ک لباس، قسی کپڑوں اورسرخ ریشمی گدیلے سے منع فرمایا تھا۔","f2":"کدو کا برتن اور تارکول لگا ہوا مٹکا بے مسام ہوتے ہیں، لہذا ان میں نبیذ بنایا جائے تو اس میں جلدی نشہ پیدا ہوجاتا تھا، اسی لیے لوگوں نے جاہلیت میں یہ برتن شراب بنانے کے لیے مخصوص کررکھے تھے، لہذا آپ نے ابتدا میں ان برتنوں کے نبیذ سے بھی روک دیا تھا، بعد میں اجازت دے دی بشرطیکہ نشہ پیدا نہ ہو۔ (تفصیل اپنے مقام پر گزر چکی ہے۔)"}],[5170,"مالک بن عمیر کہتے ہیں کہ صعصعہ بن صوحان نے علی رضی اللہ عنہ کے پاس آ کر عرض کیا: آپ ہمیں اس چیز سے منع کریں جس سے رسول اللہ صلی اللہ علیہ وسلم نے آپ کو منع فرمایا ہے، کہا: ہمیں رسول اللہ صلی اللہ علیہ وسلم نے کدو سے بنے، سبز رنگ والے اور کھجور کی لکڑی سے بنے برتنوں کے استعمال سے اور جَو اور گیہوں کی شراب پینے سے منع فرمایا اور ہمیں سونے کے چھلے، ریشم اور حریر کے لباس اور سرخ زین کے استعمال سے منع فرمایا ۱؎۔\n§وضاحت\n۱؎: «دبّاء»: کدو سے بنا ہوا برتن، حنتم: سبز رنگ کا برتن جس میں نبیذ بناتے ہیں، «نقیر»: کھجور کی جڑ کی لکڑی کھود کر بنایا ہوا برتن،«مزفت»: رنگ کیا ہوا برتن، ان برتنوں سے متعلق نہی منسوخ ہے، ممکن ہے علی رضی اللہ عنہ کو اس کے منسوخ ہونے کا علم نہ ہو سکا ہو۔","الألباني: صحيح",{"u2":"حضرت مالک بن عمیرسے روایت ہے کہ سیدنا صعصعہ بن صوحان سیدنا علی رضی اللہ عنہ کےپاس آئے اور کہا: ہمیں اس چیز سے منع فرمائیے جس سے رسول اللہ صلی اللہ علیہ وسلم نے آپ کو منع فرمایا ہو۔ انہوں نے فرمایا: آپ نے مجھے کدو کے برتن، سبز مٹکے، کھجور کی جڑ کے بنائے ہوئے برتن، جعہ (جوکے نشیلے نبیذ) سے منع فرمایا ہے، نیز ہمیں سونے کے انگوٹھی، ریشم کے لباس پہننے، قسی کپڑوں کے پہننے اور سرخ ریشمی گدیلے سے بھی روکا تھا۔","f2":"کھجور کی جڑکو اندر سے کرید کرید کر بڑا سا برتن بنالیا جاتاتھا۔ یہ بھی مساموں سے خالی ہوتا تھا، اس لیے اس برتن کو بھی انہوں نے شراب کےلیے مخصوص کررکھا تھا تاکہ جلدی نشہ پیدا ہو، نیز یہ روایت شواہد کی بنا پر صحیح ہے جیسا کہ محقق کتاب نے بھی لکھا ہے کہ سابقہ روایت اس سے کفایت کرتی ہے۔"}],[5171,"مالک بن عمیر کہتے ہیں کہ صعصعہ بن صوحان نے علی رضی اللہ عنہ سے کہا کہ امیر المؤمنین! ہمیں اس چیز سے منع فرمائیے جس چیز سے رسول اللہ صلی اللہ علیہ وسلم نے آپ کو منع فرمایا تو وہ بولے: ہمیں رسول اللہ صلی اللہ علیہ وسلم نے کدو سے بنے، اور سبز رنگ والے برتن کے استعمال سے اور جو اور گیہوں سے بنی شراب کے پینے سے، سونے کے چھلے، ریشمی لباس اور سرخ زین کے استعمال سے منع فرمایا۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: مروان اور عبدالواحد کی روایت (نمبر ۵۱۷۳ و ۵۱۷۴)اسرائیل کی روایت (نمبر ۵۱۷۲) سے زیادہ قرین صواب ہے۔","الألباني: صحيح",{"u2":"حضرت مالک بن عمیر سے روایت ہے کہ حضرت صعصعہ بن صوحان نے سیدنا علی رضی اللہ عنہ سے عرض کیا: امیر ا لمومنین! ہمیں اس چیز سے منع فرمائیے جس سے آپ کو رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا ہو۔ انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے ہمیں کدو کے برتن، مٹکے، جوکے نشیلے نبیذ، سونے کی انگوٹھی، ریشم کے لباس پہننے اور سرخ ریشمی گدیلے کے استعمال سے منع فرمایا ہے۔\nابوعبدالرحمن (امام نسائی رحمہ اللہ) نےکہا کہ مروان اور عبدالواحد کی حدیث، اسرائیل کی حدیث سے زیادہ درست اور صحیح ہے۔","f2":"یعنی مروان بن معاویہ کی بیان کردہ حدیث(5173) اور عبدالواحد کی بیان کردہ حدیث (5174)، اسرائیل کی بیان کردہ حدیث(5172) سے ارجح ہے۔ واللہ اعلم"}],[5172,"علی رضی اللہ عنہ کہتے ہیں کہ مجھے میرے محبوب رسول اللہ صلی اللہ علیہ وسلم نے تین چیزوں سے منع فرمایا، میں یہ نہیں کہتا کہ آپ نے لوگوں کو منع فرمایا، بلکہ مجھے منع فرمایا: سونے کی انگوٹھی پہننے سے، ریشمی لباس پہننے سے، زرد رنگ سے جو چمکیلا اور لال ہو، اور رکوع و سجدے کی حالت میں قرآن پڑھنے سے ۱؎۔ ضحاک بن عثمان نے داود بن قیس کی متابعت کی ہے۔\n§وضاحت\n۱؎: قرآن نہ پڑھنے کی بات مرد عورت سب کے لیے عام ہے، بقیہ باتوں میں مخاطب صرف مرد ہیں۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ سے روایت ہے، انہوں نے فرمایا: مجھے پیارے رسول اللہ صلی اللہ علیہ وسلم نے تین چیزوں سے منع فرمایا: میں یہ نہیں کہتا کہ آپ نے سب لوگوں کو منع فرمایا ہے۔ آپ نے مجھے سونے کی انگوٹھی پہننے، قسی کپڑے پہننے اور سرخ کسم رنگ کے کپڑے پہننے سے منع فرمایا، نیز یہ کہ میں نے رکوع یا سجدے میں قرآن مجید نہ پڑھوں۔\nضحاک بن عثمان نے اس (داؤد بن قیس) کی متابعت کی ہے۔","f2":"1۔ ضحاک بن عثمان نے داؤد بن قیس کی متابعت اس طرح کی ہے کہ سیدنا علی رضی اللہ عنہ اور عبداللہ بن حنین کے درمیان سیدنا عبداللہ بن عباس رضی اللہ عنہ کا واسطہ ذکر کیا ہے جیساکہ آگے آنےوالی حدیث:5176 کی سند میں ہے۔ واللہ اعلم. 2۔’ میں نہیں کہتا‘ مقصود یہ ہے کہ آپ نے مجھ سے خطاب فرماتے ہوئے مفرد کے صیغے استعمال فرمائے تھے، لہذا میں بھی مفرد کے صیغے ہی استعمال کرتا ہوں، جمع کے نہیں ورنہ بیان شدہ چیزیں سیدنا علی رضی اللہ عنہ کی طرح سب مسلمانوں کے لیے حرام ہیں، گویا سونے اور ریشمی کپڑے کی حرمت صرف مردوں کے لیے ہے۔3۔ ’کسم (کسمبھ) ‘یہ سرخ رنگ کی ان اقسام میں شامل ہے جو مردوں کےلیے حرام ہیں۔ ہر رنگ کی کئی قسمیں ہوتی ہیں۔"}],[5173,"علی رضی اللہ عنہ کہتے ہیں کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا، میں نہیں کہتا کہ تمہیں بھی منع فرمایا: سونے کی انگوٹھی پہننے سے، ریشمی کپڑا پہننے سے، سرخ اور چمکیلے لباس پہننے سے اور زرد رنگ کا لباس پہننے سے، اور رکوع (نیز سجدہ) کی حالت میں قرآن پڑھنے سے۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ سے روایت ہے، انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے مجھے سونے کی انگوٹھی پہننے اور قسی کپڑے کے لباس، سرخ اور کسم رنگ کے لباس اور رکوع کی حالت میں قراءت قرآن سے منع فرمایا ہے۔ میں یہ نہیں کہتا کہ تم کو منع فرمایا۔ (تفصیل سابقہ روایت میں ہے۔)"}],[5174,"علی رضی اللہ عنہ کہتے ہیں کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے رکوع کی حالت میں قرآن پڑھنے سے، اور سونا اور زرد رنگ کا لباس پہننے سے منع فرمایا۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے مجھے رکوع کی حالت میں قرآن پڑھنے، سونا پہننے اور کسم(کسمبھ) سے رنگا ہوا کپڑا پہننے سے منع فرمایا۔"}],[5175,"علی رضی اللہ عنہ کہتے ہیں کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا، میں یہ نہیں کہتا کہ تمہیں منع فرمایا: سونے کی انگوٹھی، ریشمی کپڑے اور زرد رنگ کے کپڑے کے استعمال سے اور اس بات سے کہ میں رکوع میں قرآن پڑھوں۔","الألباني: حسن صحيح",{"u2":"سیدنا علی رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے مجھے سونے کی انگوٹھی، قسی کپڑے اور کسم سے رنگے ہوئے کپڑے پہننے اور رکوع کی حالت میں قرآن مجید پڑھنے سے منع فرمایا ہے۔ میں نہیں کہتا کہ تم کو منع فرمایا۔"}],[5176,"علی رضی اللہ عنہ کہتے ہیں کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے سونے کی انگوٹھی پہننے، زرد رنگ کا لباس پہننے اور ریشمی لباس پہننے سے اور رکوع میں قرآن پڑھنے سے منع فرمایا۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ سے روایت ہے، انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نےمجھے سونے کی انگوٹھی، کسم سے رنگےہوئے کپڑے اور قسی کپڑے پہننے سے، نیز رکوع کی حالت میں قرآن کریم پڑھنے سے منع فرمایا ہے۔"}],[5177,"علی رضی اللہ عنہ کہتے ہیں کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے ریشمی کپڑے پہننے، زرد رنگ کے لباس پہننے اور سونے کی انگوٹھی پہننے سے منع فرمایا۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے مجھے قسی کپڑے، کسم سے رنگے ہوئے کپڑے اور سونے کی انگوٹھی پہننے سے منع فرمایا ہے۔"}],[5178,"علی رضی اللہ عنہ کہتے ہیں کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے چار باتوں سے منع فرمایا: سونے کی انگوٹھی پہننے، ریشمی کپڑے پہننے، اور رکوع کی حالت میں قرآن پڑھنے، اور زرد رنگ کا لباس پہننے سے۔ (ابوعبدالرحمٰن نسائی کہتے ہیں) ایوب نے عبیداللہ کی موافقت کی ہے مگر انہوں نے مولی کا نام ذکر نہیں کیا۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ سے روایت ہے، انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے مجھے چار چیزوں سے منع فرمایا: سونے کی انگوٹھی پہننا، قسی کپڑا پہننا، قرآن مجید رکوع کی حالت میں پڑھنا اورمعصفر (کسم سے رنگا ہوا) کپڑا پہننا۔\nایوب نے اس (عبیداللہ بن عمر) کی موافقت کی ہے لیکن اس نے(سند میں مذکور) مولی کا نام نہیں لیا۔"}],[5179,"علی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے زرد رنگ کے لباس، ریشمی کپڑے اور سونے کی انگوٹھی پہننے اور رکوع میں قرآن پڑھنے سے منع فرمایا۱؎۔\n§وضاحت\n۱؎: یحیی بن ابی کثیر کے چار شاگرد ہیں اور یہ چاروں کے چاروں یحیی کے شیوخ کے ذکر کرنے میں مختلف ہیں۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے مجھے معصفر اور قسی کپڑا پہننے، سونے کی انگوٹھی ڈالنے اور رکوع کی حالت میں قراءت قرآن سے منع فرمایا ہے۔"}],[5180,"علی رضی اللہ عنہ کہتے ہیں کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے زرد رنگ کے کپڑے، سونے کی انگوٹھی اور ریشمی کپڑے پہننے اور رکوع کی حالت میں قرآن پڑھنے سے منع فرمایا۔ (ابوعبدالرحمٰن نسائی کہتے ہیں) لیث بن سعد نے عمرو بن سعید کے برخلاف روایت کی ہے۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ نے بیان فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے معصفر کپڑوں، سونے کی انگوٹھی اور قسی کپڑوں کے پہننے سے اور رکوع کی حالت میں قرآن مجید پڑھنے سے منع فرمایا۔\nلیث بن سعد نے اس(عمرو بن سعید) کی مخالفت کی ہے۔","f2":"امام صاحب رحمہ اللہ کا مقصود یہ ہے کہ لیث بن سعد نے عمرو بن سعید کی مخالفت کی اور اس طرح بیان کیا ہے: عن نافع، عن ابراہیم بن عبداللہ بن حنین عن بعض موالی العباس عن علی..... جب کہ عمرو بن سعید نے یوں بیان کیا ہے: ان نافعاً اخبرہ قال: حدثنی ابن حنین ان علیاً..... اس کا مطلب یہ ہے کہ لیث بن سعد نے نافع کا استاد ابراہیم بن عبداللہ کوبنایا ہے جبکہ عمرو بن سعید نے نافع کا استاد ابن حنین، یعنی ابراہیم کے باپ عبداللہ کو قرار دیا ہے۔ اس میں دوسری بات یہ بھی ہے کہ عمرو بن سعید کی حدیث میں نافع نے عبداللہ بن حنین سےسماع کی تصریح کی ہے جبکہ لیث نے نافع سے بصیغۂ عن بیان کیا ہے اور عن بعض موالی العباس کہاہے مگر عمرو بن سعید نے عن بعض موالی العباس ذکر نہیں کیا۔ واللہ اعلم"}],[5181,"علی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے زرد رنگ سے، ریشمی کپڑے سے، اور رکوع کی حالت میں قرآن پڑھنے سے منع فرمایا۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کسم سے رنگے ہوئے اور قسی کپڑوں اور رکوع کی حالت میں قرآن مجید پڑھنے سے منع فرمایا ہے۔"}],[5182,"رافع بن خدیج رضی اللہ عنہ کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں زمین میں بٹائی کا معاملہ کرتے تھے، ہم اسے تہائی یا چوتھائی یا غلہ کی متعینہ مقدار کے عوض کرائیے پر دیتے تھے۔ تو ایک دن میرے ایک چچا آئے اور انہوں نے کہا: مجھے رسول اللہ صلی اللہ علیہ وسلم نے ایک ایسے معاملے سے روک دیا جو ہمارے لیے نفع بخش اور مفید تھا، لیکن اللہ اور اس کے رسول کی اطاعت ہمارے لیے زیادہ مفید اور نفع بخش ہے، آپ نے ہمیں زمین میں بٹائی کا معاملہ کر کے انہیں تہائی اور چوتھائی یا متعینہ مقدار کے غلے کے بدلے کرائیے پر دینے سے منع کیا ہے۔ اور زمین کے مالک کو حکم دیا ہے کہ وہ اس میں کھیتی کرے، یا اس میں (بلا کرایہ لیے) کھیتی کرائے اور اسے کرائے پر اٹھانا یا اس کے علاوہ جو صورتیں ہوں انہیں ناپسند فرمایا۔ ایوب نے اس حدیث کو یعلی سے نہیں سنا ہے، (بلکہ بذریعہ کتابت روایت کی ہے جیسا کہ اگلی سند سے ظاہر ہے)۔\nحنظلہ بن قیس انصاری کہتے ہیں کہ میں نے رافع بن خدیج رضی اللہ عنہ سے دینار اور چاندی کے بدلے زمین کو کرائے پر دینے کے بارے میں پوچھا تو انہوں نے کہا کہ اس میں کوئی حرج نہیں۔ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں لوگ اس پیداوار کے بدلے کرائے دیا کرتے تھے جو کیاریوں اور نالیوں کے اوپر پیدا ہوتی ہے، تو کبھی اس جگہ پیداوار ہوتی اور دوسری جگہ نہیں ہوتی اور کبھی یہاں نہیں ہوتی اور دوسری جگہ ہوتی، لوگوں کا بٹائی پر دینے کا یہی طریقہ ہوتا، اس لیے اس پر زجر و توبیخ ہوئی۔ رہی معین چیز (پر بٹائی) جس کی ضمانت دی جا سکتی ہو تو اس میں کوئی حرج نہیں۔ مالک بن انس نے بھی اوزاعی کی سند میں (چچا کے نہ ذکر کرنے میں)موافقت کی ہے لیکن الفاظ میں مخالفت کی ہے۔\nرافع بن خدیج رضی اللہ عنہ کہتے ہیں کہ ہمارے پاس (ہمارے چچا) ظہیر بن رافع رضی اللہ عنہ نے آ کر کہا: مجھے رسول اللہ صلی اللہ علیہ وسلم نے ایک ایسی چیز سے روکا ہے جو ہمارے لیے مفید و مناسب تھی۔ میں نے کہا: وہ کیا ہے؟ کہا: رسول اللہ صلی اللہ علیہ وسلم کا حکم اور وہ سچا (برحق) ہے، آپ نے مجھ سے پوچھا: \"تم اپنے کھیتوں کا کیا کرتے ہو؟\" میں نے عرض کیا: ہم انہیں چوتھائی پیداوار اور کچھ وسق کھجور یا جو کے بدلے کرائے پر اٹھا دیتے ہیں۔ آپ نے فرمایا: \"تم ایسا نہ کرو، یا تو ان میں خود کھیتی کرو یا پھر دوسروں کو کرنے کے لیے دے دو، یا انہیں یوں ہی روکے رکھو\"۔ بکیر بن عبداللہ بن اشج نے اسے اسید بن رافع سے روایت کیا ہے، اور اسے رافع کے بھائی سے روایت کیا ہے۔\nعلی رضی اللہ عنہ کہتے ہیں کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا، … پھر پوری حدیث بیان کی۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے منع فرمایا۔ پھر (راوی نے) پوری حدیث بیان کی۔"}],[5183,"علی رضی اللہ عنہ کہتے ہیں کہ مجھے نبی اکرم صلی اللہ علیہ وسلم نے ریشمی کپڑوں، ریشم، سونے کی انگوٹھی سے اور رکوع کی حالت میں قرآن پڑھنے سے منع فرمایا۔(ابوعبدالرحمٰن نسائی کہتے ہیں) ہشام نے اشعث کے برخلاف غیر مرفوع روایت کی ہے۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ نے فرمایا: نبئ اکرم صلی اللہ علیہ وسلم نے مجھے قسی کپڑوں، ریشم، سونے کی انگوٹھی اور دوران رکوع میں قراءت قرآن سے منع فرمایا ہے۔\nہشام نے اس (اشعث بن عبدالملک) کی مخالفت کی ہے اور اس نےاسے مرفوع بیان نہیں کیا۔","f2":"مقصد یہ ہے کہ اشعث نے محمد بن سیرین سے یہ روایت بیان کی تو کہا ہے: عن محمد، عن عبیدۃ، عن علی، قال: نہانی النبی صلی اللہ علیہ وسلم یعنی حدیث مرفوعا بیان کی ہے اور جب ہشام نے محمدبن سیرین سے بیان کی تو کہا ہے: عن عبیدۃ، عن علی، قال: نہی...... یعنی انہوں نے موقوف روایت بیان کی ہے، تاہم یہ حکماً مرفوع ہے۔"}],[5184,"علی رضی اللہ عنہ سے روایت ہے کہ انہوں نے لال زین، ریشمی کپڑوں اور سونے کی انگوٹھی استعمال کرنے سے منع کیا۔","الألباني: صحيح موقوف والأصح الرفع",{"u2":"سیدنا علی رضی اللہ عنہ نے فرمایا: آپ نے سرخ رنگ کے ریشمی گدیلوں، قسی کپڑوں اور سونے کی انگوٹھی سے منع فرمایا۔","f2":"’سرخ رنگ‘ عربی میں لفظ ارجوان استعمال کیا گیا ہے جوارجوان کا معرب ہے۔ یہ سرخ رنگ کا پھول ہوتا ہے۔ گدیلوں کو ارغوان کہنے کا مطلب رنگ میں تشبیہ دینا ہے، یعنی ارغوان جیسے سرخ گدیلے۔ البتہ حرمت کی وجہ ان کی سرخی کی بجائے ان کا ریشمی ہونا ہے۔ (مزید تفصیل کےلیے دیکھئے، حدیث:69۔5168)"}],[5185,"عبیدہ سے روایت ہے کہ انہوں نے سرخ زین اور سونے کی انگوٹھی سے منع فرمایا۔","الألباني: صحيح مقطوع والمرفوع هو الأصح",{"u2":"حضرت عبیدہ سے روایت ہے کہ ارجوانی سرخ گدیلے اور سونے کی انگوٹھیاں ممنوع ہیں۔"}],[5186,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سونے کی انگوٹھی پہننے سے منع فرمایا۔","الألباني: صحيح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے، انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے مجھے سونے کی انگوٹھی پہننے سے منع فرمایا ہے۔"}],[5187,"عمران رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ریشم پہننے، سونے کی انگوٹھی پہننے اور ہرے یا لال برتن میں پانی پینے سے منع فرمایا۔","الألباني: صحيح",{"u2":"حضرت حفص لیثی بیان کرتے ہیں کہ میں حضرت عمران(بن حصین) رضی اللہ عنہ کے بارے میں گواہی دیتا ہوں کہ انہوں نے ہمیں بیان فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے ریشم پہننے، سونے کی انگوٹھی استعمال کرنے اور سبز مٹکوں کا نبیذ پینے سے منع فرمایا ہے۔","f2":"1۔ ان دو روایات سے صراحتاً معلوم ہوا کہ مندرجہ بالا چیزوں سے نہی صرف سیدنا علی رضی اللہ عنہ سے خاص نہیں۔ 2۔ اگر آپ اس قدر تکرار سے ملول ہوں تو دیکھئے فائدہ حدیث نمبر5163."}],[5188,"ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ ایک شخص نجران سے رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، وہ سونے کی انگوٹھی پہنے ہوئے تھا، آپ نے اس سے منہ پھیر لیا اور فرمایا: \"تم میرے پاس اپنے ہاتھ میں جہنم کی آگ کا انگارہ لے کر آئے ہو\"۔","الألباني: صحيح",{"u2":"سیدنا ابوسعیدخدری رضی اللہ عنہ نے بیان فرمایا کہ نجران کے علاقے سے ایک آدمی رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوا۔ اس نے سونے کی انگوٹھی پہن رکھی تھی۔ رسول اللہ صلی اللہ علیہ وسلم نے اس سے منہ موڑلیا اور فرمایا: ’ تو میرے پاس اس حالت میں آیا ہے کہ تیرے ہاتھ میں آگ کا انگارہ ہے۔‘","f2":"راجح قول کے مطابق اس روایت کی سند ابو نجیب کے مجہول ہونے کی وجہ سے ضعیف ہے۔ دیکھئے حدیث:5209"}],[5189,"براء بن عازب رضی اللہ عنہما سے روایت ہے کہ ایک شخص نبی اکرم صلی اللہ علیہ وسلم کے پاس بیٹھا ہوا تھا، وہ سونے کی انگوٹھی پہنے ہوئے تھا اور رسول اللہ صلی اللہ علیہ وسلم کے ہاتھ میں چھڑی تھی یا ٹہنی، آپ صلی اللہ علیہ وسلم نے اس سے اس کی انگلی پر مارا۔ اس شخص نے کہا: کیا وجہ ہے اللہ کے رسول؟ آپ نے فرمایا: \"کیا تم اسے نہیں پھینکو گے جو تمہارے ہاتھ میں ہے؟\" چنانچہ اس شخص نے اسے نکال کر پھینک دیا، اس کے بعد نبی اکرم صلی اللہ علیہ وسلم نے اسے دیکھا اور فرمایا:\"انگوٹھی کیا ہوئی؟\" وہ بولا: میں نے اسے پھینک دی۔ آپ نے فرمایا: \"میں نے تمہیں اس کا حکم نہیں دیا تھا، میں نے تو تمہیں صرف اس بات کا حکم دیا تھا کہ اسے بیچ دو اور اس کی قیمت کو کام میں لاؤ\"۔ (ابوعبدالرحمٰن نسائی کہتے ہیں:) یہ حدیث منکر ہے۔","الألباني: ضعيف الإسناد",{"u2":"حضرت براء بن عازب رضی اللہ عنہما سے روایت ہے کہ ایک آدمی نبئ اکرم صلی اللہ علیہ وسلم کے پاس بیٹھا تھا جبکہ اس نے سونے کی انگوٹھی پہن رکھی تھی۔ رسول اللہ صلی اللہ علیہ وسلم کے ہاتھ میں ایک چھڑی یا شاخ تھی۔ رسول اللہ صلی اللہ علیہ وسلم نے وہ چھڑی اس کی انگلی پر ماری تو اس آدمی نے کہا: اے اللہ کے رسول! کیا ہوا؟ آپ نے فرمایا: کیا تو یہ انگوٹھی پھینک نہیں دیتا جو تیری انگلی میں ہے۔؟ اس آدمی نے وہ انگوٹھی اتار کر پھینک دی۔ پھر نبئ اکرم صلی اللہ علیہ وسلم نے اس کے بعد اسے دیکھا تو پوچھا: انگوٹھی کدھر ہے؟ نے کہا: وہ تو میں نے پھینک دی تھی۔ آپ نے فرمایا: میں نے تجھے یہ نہیں کہا تھا بلکہ میرا مقصد تو یہ تھا کہ تو اس کو بیچ کر اس کی قیمت سے فائدہ اٹھالے۔\nاور یہ حدیث منکر ہے۔","f2":"امام صاحب نے فرمایا:یہ حدیث منکر ‘یعنی ضعیف ہےہ۔ اور اس کے منکر ہونے کی وجہ یہ ہے کہ اس کا راوی مجہول ہے۔ یہ روایت صرف اسی کتاب میں ہے۔"}],[5190,"ابوثعلبہ خشنی رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے ان کے ہاتھ میں سونے کی انگوٹھی دیکھی تو آپ ایک چھڑی سے جو آپ کے پاس تھی اس پر مارنے لگے، جب آپ کی توجہ ہٹ گئی تو انہوں نے وہ انگوٹھی پھینک دی، آپ نے فرمایا: \"ہم سمجھتے ہیں کہ ہم نے تمہیں تکلیف دی اور تمہارا نقصان کیا\"۔ یونس نے نعمان بن راشد کے خلاف اسے زہری سے انہوں نے ابوادریس سے مرسلاً روایت کیا ہے۔","الألباني: صحيح",{"u2":"سیدنا ابو ثعلبہ رضی اللہ عنہ سے روایت ہے کہ نبئ اکرم صلی اللہ علیہ وسلم نے ان کے ہاتھ میں سونے کی انگوٹھی دیکھی تو آپ اسے اپنی چھڑی سے مارنے لگے۔ جب نبئ اکرم صلی اللہ علیہ وسلم کی توجہ کسی اور طرف ہوئی تو اس (ابوثعلبہ) نے اسے اتار پھینکا۔ آپ نے فرمایا:ہمارا خیال ہے کہ ہم نے تجھے (چھڑی مار کر) تکلیف دی اور تیرا نقصان بھی کیا۔\nیونس نے اس (نعمان بن راشد) کی مخالفت کی ہے اس نے یہ روایت عن الزہری عن ابی ادیس (کی سند)سے مرسل بیان کی ہے۔","f2":"امام نسائی رحمہ اللہ یہ کہنا چاہتے ہیں کہ نعمان بن راشد نے روایت موصول بیان کی ہے، جبکہ یونس نےیہ روایت موصول کی بجائے مرسل بیان کی ہے جیسا کہ آئند حدیث5194 میں ہے۔ لیکن نعمان بن راشد کی بیان کردہ موصول روایت غیر محفوظ ہے جبکہ یونس کی مرسل روایت محفوظ ہے کیونکہ زہری سے بیان کرنے میں یونس، نعمان کےمقابلے میں اوثق اور اثبت ہے۔ مزید برآں یہ کہ جلیل القدر آئمہ حدیث، مثلاً:امام بخاری، امام احمد، ابن معین، ابوحاتم، عقیلی، امام ابو داؤد اور امام نسائی رحمہ اللہ وغیرہم جیسے معروف محدثین نے بھی نعمان بن راشد پرکلام کیا ہے۔"}],[5191,"ابوادریس خولانی بیان کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کو پانے والے لوگوں میں سے ایک شخص نے سونے کی انگوٹھی پہنی … پھر آگے اسی طرح بیان کیا۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: یونس کی روایت نعمان کی روایت کی نسبت سے زیادہ قرین صواب ہے۔","الألباني: صحيح لغيره",{"u2":"حضرت ابو ادریس خولانی نے بیان فرمایا کہ ایک آدمی جس نے نبئ اکرم صلی اللہ علیہ وسلم سے ملاقات کی ہے، نے سونے کی انگوٹھی پہنی۔(پھر راوی نے) سابقہ حدیث کی طرح بیان کیا۔\nابوعبدالرحمن (امام نسائی رحمہ اللہ) نے فرمایا: یونس کی حدیث نعمان کی حدیث سے زیادہ درست ہے۔"}],[5192,"ابوادریس خولانی سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص کو سونے کی انگوٹھی پہنے دیکھا پھر آگے اسی طرح بیان کیا۔","الألباني: صحيح",{"u2":"حضرت ابو ادریس خولانی سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک آدمی کو سونے کی انگوٹھی پہنے دیکھا۔ (پھر راوی نے) حسب سابق پوری حدیث بیان کی۔"}],[5193,"ابوادریس خولانی سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے ایک شخص کے ہاتھ میں سونے کی ایک انگوٹھی دیکھی تو آپ نے اس کی انگلی کو ایک لکڑی سے مارا جو آپ کے پاس تھی، یہاں تک کہ اس نے وہ انگوٹھی پھینک دی۔","الألباني: صحيح لغيره",{"u2":"حضرت ابو ادریس سے روایت ہے کہ نبئ اکرم صلی اللہ علیہ وسلم نے ایک آدمی کے ہاتھ میں سونے کی انگوٹھی دیکھی تو آپ نے اپنی چھڑی اس کی انگلی پر ماری حتی کہ اس نے انگوٹھی اتار کر پھینک دی۔"}],[5194,"اس سند سے بھی ابن شہاب زہری سے، اسی طرح مرسلاً روایت ہے۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: مرسل روایتیں زیادہ قرین صواب ہیں۔","الألباني: سكت عنه الشيخ",{"u2":"حضرت ابن شہاب نے یہ روایت مرسلاً بیان کی ہے۔(صحابی کا واسطہ ذکر نہیں کیا۔)\nابو عبدالرحمن (امام نسائی رحمہ اللہ) نے کہا: مرسل روایتیں زیادہ ٹھیک اور درست ہیں۔","f2":"5193کی سند نعمان کی وجہ سے ضعیف ہے اور اس کی بعد والی روایت مرسل ہیں اور راجح قول کے مطابق مرسل از قسم ضعیف ہے، تاہم شیخ البانی رحمہ اللہ اور دیگر کئی محققین نے اس روایت کے مجموعی طرق اور شواہد کی بنا پر اس روایت کو قابل حجت قرار دیا ہے۔ تفصیل کےلیے دیکھئے: (الموسوعۃ الحدیثیۃ، مسند احمد:29؍283)"}],[5195,"بریدہ رضی اللہ عنہ سے روایت ہے کہ ایک شخص نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا، وہ لوہے کی انگوٹھی پہنے ہوئے تھا، آپ نے فرمایا: \"کیا وجہ ہے کہ میں تمہیں جہنمیوں کا زیور پہنے دیکھ رہا ہوں؟\" یہ سن کر اس نے وہ انگوٹھی پھینک دی۔ پھر پیتل کی انگوٹھی پہن کر آپ کے پاس آیا۔ آپ نے فرمایا: \"کیا وجہ ہے مجھے تم سے بتوں کی بو محسوس رہی ہے؟\" اس نے وہ انگوٹھی بھی پھینک دی اور بولا: اللہ کے رسول! پھر کس چیز کی بناؤں؟ آپ نے فرمایا: \"چاندی کی، لیکن ایک مثقال سے کم رہے\"۔","الألباني: ضعيف",{"u2":"سیدنا بریدہ رضی اللہ عنہ سے روایت ہے کہ ایک آدمی نبئ اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا تو اس نے لوہے کی انگوٹھی پہن رکھی تھی۔ آپ نے فرمایا: کیا وجہ ہے کہ میں تجھ پر جہنمیوں کا زیور دیکھتا ہوں؟ اس نے اسے اتار پھینکا۔ پھر وہ آپ کے پاس آیا تو اس نے پیتل کی انگوٹھی ڈالی ہوئی تھی۔ آپ نے فرمایا: کیا وجہ ہے کہ میں تجھ سے بتوں کی بو پاتا ہوں؟ اس نے اسے بھی اتار پھینکا(اور) کہا: اے اللہ کے رسول! میں کس چیز کی انگوٹھی بنواؤں؟ آپ نے فرمایا: چاندی سے اور اسے بھی ایک مثقال سے کم رکھنا۔","f2":"محقق کتاب کا اس روایت کی سند کو حسن کہنا محل نظر ہے کیونکہ اس کی سند میں عبداللہ بن مسلم راجح قول کے مطابق ضعیف ہے اور کسی نے اس کی متابعت بھی نہیں کی۔ تفصیل کےلیے دیکھئے: (ذخیرۃ العقبیٰ شرح سنن النسائی:38؍283) تاہم اس میں لوہے کی انگوٹھی کو جہنمیوں کا زیور قراردینے والا جملہ دیگر صحیح احادیث سے ثابت ہے۔ تفصیل کےلیے دیکھئے، حدیث:5208 کے فوائد۔"}],[5196,"انس رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے چاندی کی انگوٹھی بنوائی جس کا نگینہ حبشی تھا ۱؎ اور اس میں ـ «محمد رسول اللہ» نقش کیا گیا تھا۔\n§وضاحت\n۱؎: ایک دوسری حدیث نمبر :(۵۲۰۱ ) کے مطابق نگینہ چاندی ہی کا تھا، تطبیق کی صورت یہ ہے کہ حبشی طرز کا تھا یا اس کا بنانے والا حبشی تھا، ایک قول یہ بھی ہے کہ ممکن ہے آپ کے پاس دو انگوٹھیاں رہی ہوں۔","الألباني: صحيح",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ نبئ اکرم صلی اللہ علیہ وسلم نے چاندی کی انگوٹھی بنوائی۔ اس کا نگینہ حبشی تھا اور اس میں’ محمد رسول اللہ‘ کے الفاظ کندہ تھے۔","f2":"1۔ وہ سونے کی تھی یا چاندی کی یا کسی اور چیز کی، نیز اس کا نگینہ تھا یا نہیں تھا اور اگرتھا تو کس طرح کا تھا۔ وغیرہ۔ اور یہ تمام تر تفصیل مذکو رہ باب کے تحت مروی روایات میں مکمل طور پر بیان کی گئی ہیں۔2۔ اس حدیث مبارکہ سے یہ مسئلہ بھی معلوم ہوتا ہے کہ مرد اور عورت ہردو کے لیے چاندی کی انگوٹھی پہننا جائز اور مشروع ہے۔ بعض روایات میں سلطان اور حاکم کے علاوہ دوسرے لوگوں کو انگوٹھی پہننے سے منع کیا گیا ہے تو ان دونوں قسم کی روایات میں تطبیق اس طرح سے دی گئی ہے کہ نہی تنزیہ پر محمول ہے، یعنی حاکم وغیرہ کے علاوہ دیگر لوگوں کے لیے انگوٹھی نہ پہننا بہتر ہے۔ واللہ اعلم۔ 3۔ انگوٹھی یا اس کے نگینے پر کوئی نقش وغیرہ بنوانا جائز ہے، نیز اپنا نام یا کوئی کلمۂ حکمت وغیرہ بھی کندہ کرایا جاسکتا ہے۔ اہل علم کے صحیح قول کے مطابق اس پر اللہ تعالی کا اسم مبارک ’ اللہ‘ بھی کندہ کرایا اور لکھوایا جاسکتا ہے۔ بعض علماء نے اس سے منع کیا ہے لیکن ممانعت والا قول ضعیف اور مرجوح قراردیا گیا ہے۔ یادرہے کہ سونے کی انگوٹھی کی طرح سونے کا نگینہ بھی ناجائز ہوگا۔ 4۔ ’حبشی‘ یعنی حبشی انداز کا بنا ہوا تھا۔ یا حبشہ کا بنا ہوا تھا۔ یہ بھی ہوسکتا ہے کہ جس عقیق، ماربل یا قیمتی پتھر کا تھا وہ حبشہ سے لائے گئے تھے کیونکہ ایسے پتھروں وغیرہ کی کانیں ادھر، یمن اور حبشہ میں تھیں۔ بعض نے معنی کیے ہیں کہ ا س کا نگینہ سیاہ تھا۔ اس وجہ سے اسے حبش کہا گیا ہے۔ بعض روایات میں ہے کہ نگینہ بھی چاندی ہی کا تھا۔ اس کی بابت یہ بھی کہا گیا ہے کہ مختلف انگوٹھیاں تھیں، اس لیے کسی کا نگینہ چاندی کا تھا اور کسی کا حبشی تھا۔ بعض محققین نے یہ تطبیق دی ہے کہ حبشی نگینہ سونے کی انگوٹھی کا تھا اور چاندی کی انگوٹھی میں نگینہ چاندی ہی کا تھا۔ یہاں راوی کو غلطی لگی جو اس نے حبشی نگینہ چاندی کی انگوٹھی سے منسوب کردیا۔ یہ اما م بیہقی رحمہ اللہ کا قول ہے واللہ اعلم۔ 5۔’کندھ تھے‘ رسو ل اللہ صلی اللہ علیہ وسلم کے جو خطوط سامنے آئے ہیں ان میں محمدرسول اللہ کے الفاظ کی ترتیب اس طرح سے ہے کہ یہ تینوں الفاظ ایک سطر میں نہیں لکھے گئے بلکہ تین سطروں میں ہیں۔ سب سے اوپر لفظ’ اللہ ‘ درمیان میں لفظ ’ رسول ‘ اور نیچے لفظ ’ محمد‘ صلی اللہ علیہ وسلم ہے۔ اس ترتیب سے آپ کا حسن ادب واضح ہوتا ہے کہ آپ نے اپنانام باوجود ترتیب میں مقدم ہونے کے نیچے رکھا اور لفظ ’ اللہ‘ اوپر۔ فداہ ابی وامی ونفسی وروحی صلی اللہ علیہ وسلم."}],[5197,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کی چاندی کی ایک انگوٹھی تھی، اسے آپ دائیں ہاتھ میں پہنتے تھے، اس کا نگینہ حبشی تھا۔ آپ نگینہ ہتھیلی کی طرف رکھتے تھے۔","الألباني: صحيح لغيره",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم کے پاس چاندی کی انگوٹھی تھی جسے آپ اپنے دائیں ہاتھ میں پہنتے تھے۔ اس کا نگینہ حبشہ کا بنا ہوا تھا اور آپ نگینہ ہتھیلی کی جانب رکھتے تھے۔","f2":"1۔’دائیں ہاتھ‘ کیونکہ زینت کے لیے دایاں ہاتھ مناسب ہے۔ بایاں ہاتھ تو استنجا وغیرہ کےلیے استعمال کے لیے ہوتا ہے۔ بعض روایات میں بائیں کا بھی ذکر ہے بائیں میں انگوٹھی پہننے کی روایات بھی صحیح ہیں، لہذا دونوں ہاتھوں میں انگوٹھی پہننا جائز ہے مگر ترجیح دائیں کو ہے کیونکہ یہ اکثر روایات میں ہے۔ 2۔ ’ ہتھیلی کی جانب‘ کیونکہ آپ نے اسے زینت کے لیے نہیں پہنا تھا بلکہ مہر لگانے کےلیے پہنا تھا۔ ویسے کوئی حرج نہیں اگر نگینہ ہاتھ کی پشت کی طرف بھی کر لیا جائے کیونکہ منع کی کوئی دلیل نہیں۔ 3۔ مذکورہ احادیث صحیحہ سے یہ بات بالکل واضح ہوجاتی ہے کہ مردوں کےلیے چاندی کی انگوٹھی پہننا جائز ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے خود چاندی کی انگوٹھی بنوائی اور پہنی۔ آپ کے صحابہ نے بھی نبی صلی اللہ علیہ وسلم کے اس طریقے کو اپنایا اور ائمہ دین نے بھی اس پر عمل کیا۔"}],[5198,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کی انگوٹھی چاندی کی تھی اور اس کا نگینہ بھی چاندی ہی کا تھا۔","الألباني: صحيح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ نے فرمایا: رسو ل اللہ صلی اللہ علیہ وسلم کی انگوٹھی چاندی کی تھی اور نگینہ بھی اسی (چاندی) کا تھا۔"}],[5199,"انس رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کی انگوٹھی چاندی کی تھی اور اس کا نگینہ بھی چاندی ہی کا تھا۔","الألباني: صحيح",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ نبئ اکرم صلی اللہ علیہ وسلم کی انگوٹھی چاندی کی تھی اور نگینہ بھی چاندی کا تھا۔"}],[5200,"انس رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کی انگوٹھی چاندی کی تھی اور اس کا نگینہ بھی اسی کا تھا۔","الألباني: صحيح",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے، انہوں نے فرمایا: نبئ اکرم صلی اللہ علیہ وسلم کی انگوٹھی مبارک چاندی کی تھی۔ اس کا نگینہ بھی اسی(چاندی) کا تھا۔"}],[5201,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے رومی بادشاہ کو کچھ لکھنا چاہا تو لوگوں نے عرض کیا کہ وہ لوگ کوئی ایسی تحریر نہیں پڑھتے جس پر مہر نہ لگی ہو، چنانچہ آپ نے چاندی کی مہر بنوائی، گویا میں آپ کے ہاتھ میں اس کی سفیدی کو (ابھی ابھی) دیکھ رہا ہوں، اس میں «محمد رسول اللہ» نقش تھا۔","الألباني: صحيح",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے، انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے روم (اور فارس کے بادشاہوں) کی طرف خطوط لکھنے کا ارادہ فرمایا تو لوگوں نے کہا: وہ لوگ مہر کے بغیر خط نہیں پڑھتے تو آپ نے چاندی کی مہر(انگوٹھی) بنوالی۔ مجھے اب بھی ایسے محسوس ہوتا ہے کہ میں آپ کے ہاتھ مبارک میں اس کی چمک دیکھ رہا ہوں۔ اور آپ نےاس میں ’ محمد رسول اللہ‘ نقش کروایا ہے۔"}],[5202,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے عشاء میں تاخیر کی یہاں تک کہ آدھی رات گزر گئی، پھر آپ نکلے اور ہمیں نماز پڑھائی، گویا میں آپ کے ہاتھ میں چاندی کی انگوٹھی کی سفیدی (ابھی بھی) دیکھ رہا ہوں۔","الألباني: صحيح",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے، انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے ایک بار عشاء کی نماز میں تاخیر فرمادی حتی کہ تقریباً نصف رات گزر گئی۔ پھرآپ تشریف لائے اور ہمیں نماز پڑھائی۔ مجھے اب بھی یوس محسوس ہوتا ہے کہ میں(عالم تصور میں) آپ کے دست مبارک میں آپ کی چاندی کی انگوٹھی کی چمک دیکھ رہا ہوں۔"}],[5203,"علی رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم انگوٹھی اپنے داہنے ہاتھ میں پہنتے تھے۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ سے روایت ہے کہ نبئ اکرم صلی اللہ علیہ وسلم اپنی انگوٹھی دائیں ہاتھ میں پہنا کرتا تھے۔","f2":"تفصیل کےلیے دیکھئے، حدیث:5200"}],[5204,"عبداللہ بن جعفر رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم اپنے دائیں ہاتھ میں انگوٹھی پہنتے تھے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن جعفر سے روایت ہے کہ نبئ اکرم صلی اللہ علیہ وسلم اپنے دائیں ہاتھ میں انگوٹھی پہنا کرتے تھے۔"}],[5205,"معیقیب رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کی انگوٹھی لوہے کی تھی جس پر چاندی چڑھی ہوئی تھی اور کبھی کبھی وہ انگوٹھی میرے ہاتھ میں بھی ہوتی تھی۔","الألباني: ضعيف",{"u2":"سیدنا معیقیب رضی اللہ عنہ نے فرمایا: نبئ اکرم صلی اللہ علیہ وسلم کی انگوٹھی لوہے کی تھی جس پر چاندی کا خول چڑھایا گیا تھا۔ اور بسا اوقات وہ میرے ہاتھ میں رہتی تھی۔ (اور سیدنا معیقیبت رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کی انگوٹھی مبارک کی حفاظت پر مامور تھے۔)","f2":"1۔ امام نسائی رحمہ اللہ نے جو ترجمۃ الباب قائم کیا ہے اس کا مقصد یہ اہم مسئلہ بیان کرنا ہے کہ چاندی کا خول پڑھی لوہے کی انگوٹھی پہننا شرعاً جائز ہے۔ مطلقاً لوہے کی انگوٹھی پہننے سے گریز ضروری ہے کیونکہ اسے جہنمیوں کا زیور کہا گیا ہے۔ (الموسوعۃ الحدیثیۃ، مسند احمد:11؍69)۔ 2۔ اس حدیث مبارکہ سے یہ بھی ثابت ہوتا ہے کہ اہل علم و فضل کی خدمت کرنا مستحب ہے، نیز آزاد آدمی سے بھی خدمت کرائی جاسکتی ہے بشرطیکہ وہ برضاورغبت کرنے پر راضی ہو۔ 3۔ سرکاری اور اسی طرح دیگر اہم اداروں کی ایسی مہریں جن کے ساتھ خطوط و دستاویزات پر مہر لگائی جاتی ہے، ان کی حفاظت کرنا ضروری ہے تاکہ انہیں کوئی غلط استعمال نہ کرے کیونکہ اس طرح تمام دستاویزات اور خطوط وغیرہ غیر معتبر اور ناقابل اعتماد قرار پائیں گے۔ واللہ اعلم"}],[5206,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ بحرین (احساء) سے ایک شخص نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا اور سلام کیا، آپ نے اس کے سلام کا جواب نہیں دیا، اس کے ہاتھ میں سونے کی ایک انگوٹھی تھی اور ریشم کا جبہ، اس نے وہ دونوں اتار کر پھینک دیے اور پھر سلام کیا، تو آپ نے اس کے سلام کا جواب دیا، اب اس نے کہا: اللہ کے رسول! میں تو سیدھا آپ کے پاس آیا ہوں اور آپ نے مجھ سے رخ پھیر لیا؟ آپ نے فرمایا: \"تمہارے ہاتھ میں جہنم کی آگ کا انگارہ تھا\"، وہ بولا: تب تو اس میں سے بہت سارے انگارے لے کر آیا ہوں، آپ نے فرمایا: \"تم جو کچھ بھی لے کر آئے ہو وہ ہمارے لیے اس حرہ کے پتھروں سے زیادہ فائدہ مند نہیں ہے، البتہ وہ دنیا کی زندگی کی متاع ہے\"، وہ بولا: تو پھر میں کس چیز کی انگوٹھی بنواؤں؟ آپ نے فرمایا: \"لوہے کا یا چاندی کا یا پیتل کا ایک چھلا بنا لو\"۔","الألباني: ضعيف",{"u2":"سیدنا ابوسعید خدری رضی اللہ عنہ نے فرمایا:بحرین سے ایک آدمی نبئ اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور سلام کہا۔ آپ نے اسے جواب نہ دیا۔ اس کے ہاتھ میں سونے کی انگوٹھی تھی۔ اور اس نے ریشمی قمیص پہن رکھی تھی۔ اس نے وہ دونوں چیزیں اتارنے کے بعد پھر سلام عرض کیا تو آپ نے سلام کا جواب دیا: پھر اس نے کہا: اے اللہ کے رسول! میں ابھی آپ کےپاس حاضر ہوا تھا تو آپ نے مجھ سے اعراض فرمایا تھا۔ آپ نے فرمایا: تیرے ہاتھ میں آگ کا انگارہ تھا۔ اس نے کہا: پھر تو میں بہت سے انگارے لایا ہوں۔ آپ نے فرمایا: جو تولے کر آیا تھا ہمارے نزدیک اس کی حیثیت حرہ کے پتھروں سے زیادہ نہیں۔ البتہ دنیوی زندگی میں اس سے فائدہ اٹھایا جاسکتا ہے۔ اس نے عرض کی: میں کس چیز کی انگوٹھی پہنوں؟ آپ نے فرمایا: لوہے، چاندی یا پیتال کی انگوٹھی۔","f2":"یہ روایت ابونجیب کی جہالت کی وجہ سے ضعیف ہے اور اس کی کسی نے متابعت بھی نہیں کی۔ تفصیل کےلیے دیکھئے: (الموسوعۃ الحدیثیۃ، مسند احمد:17؍180و ذخیرۃ العقبیٰ شرح سنن النسائی:38؍308)"}],[5207,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے نکلے اور آپ نے چاندی ایک چھلا بنوایا تھا۔ آپ نے فرمایا: \"جو اس طرح کا چھلا بنوانا چاہے تو بنوا لے، البتہ جو کچھ اس پر نقش ہے اسے نقش نہ کرائے\"۔","الألباني: صحيح الإسناد",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے، انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم (گھر سے) باہر تشریف لائے جبکہ آپ نے چاندی کی انگوٹھی پہن رکھی تھی۔ آپ نے فرمایا: جو شخص اس کے مطابق انگوٹھی بنانا چاہے، بنالے لیکن اس کے نقش جیسا نقش نہ کروانا۔","f2":"1۔ نبئ اکرم صلی اللہ علیہ وسلم کی انگوٹھی مبارک پر’ محمد رسول اللہ‘ نقش تھا جو دراصل آپ کی مہر تھی۔ اگر دوسرے لوگوں کو بھی اس نقش کی اجازت ہوتی تو اس مہر میں امتیاز نہ رہنا اور جعل سازی ہوجاتی۔ مہر بنوانے کا مقصد ہی فوت ہوجاتا۔2۔ اس حدیث مبارکہ اور اس کے بعد والی حدیث کی مناسبت مذکورہ باب کے ساتھ نہیں بنتی۔ بہتر اور افضل یہ تھا کہ ان احادیث پر اسی طرح باب باندھا جاتا جیسا کہ سنن الکبریٰ میں قائم کیا گیا ہے، یعنی اس بات کی ممانعت کہ کوئی شخص انگوٹھی پر یہ الفاظ نقش کرائے ’ محمد رسول اللہ‘۔"}],[5208,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک انگوٹھی بنوائی اور اس پر نقش کرایا اور فرمایا: \"ہم نے ایک انگوٹھی بنوائی ہے اور اس میں کچھ نقش کرایا ہے، تو تم میں سے کوئی اسے نقش نہ کرائے\"، پھر انس رضی اللہ عنہ نے کہا: گویا اس کی چمک میں آپ کے ہاتھ میں (ابھی بھی) دیکھ رہا ہوں۔","الألباني: صحيح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے، انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے ایک انگوٹھی بنوائی اور اس پر (محمد رسول اللہ) نقش کروایا۔ پھر آپ نے فرمایا: ہم نے ایک انگوٹھی بنوائی ہے اور اس پر نقش کروایا ہے۔ کوئی شخص اس نقش کی طرح نقش نہ کروائے۔ حضرت انس نے فرمایا: مجھے(عالم تصور میں) یومحسوس ہوتا ہے کہ میں اب بھی آپ کے دست مبارک میں انگوٹھی کی چمک دیکھ رہا ہوں۔"}],[5209,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مشرکین کی آگ سے روشنی مت لو اور نہ اپنی انگوٹھیوں پر عربی نقش کراؤ\"۔","الألباني: ضعيف",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: مشرکین کی آگ سے روشنی حاصل نہ کرو۔ اور اپنی انگوٹھیوں پر عربی عبارت نقش نہ کرواؤ۔"}],[5210,"ابوبردہ کہتے ہیں کہ علی رضی اللہ عنہ نے کہا: مجھ سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"علی! اللہ سے ہدایت اور میانہ روی طلب کرو\"، اور آپ نے مجھے روکا کہ انگوٹھی اس میں اور اس میں پہنوں۔ اور اشارہ کیا یعنی شہادت کی انگلی اور بیچ کی انگلی کی طرف ۱؎۔\n§وضاحت\n۱؎: یہ نہی تنزیہی ہے، یعنی زیادہ بہتر اس کا نہ پہننا ہے۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے فرمایا: ’’ علی! اللہ تعالیٰ سے ہدایت اور میانہ روی مانگا کر۔ ‘‘ نیز آپ نے مجھے اس اور اس ‘ یعنی شہادت اور درمیانی انگلی میں انگوٹھی ڈالنے سے منع فرمایا۔","f2":"1۔ اس حدیث مبارکہ سے معلوم ہوا کہ (مردوں کے لیے) انگشت شہادت اور درمیان والی انگلی میں پہننا ممنوع ہے ‘ نیز ان دونوں انگلیوں کے علاوہ باقی دو یعنی چھنگلی اور اس کے ساتھ والی انگلی میں انگوٹھی پہننا درست ہے۔ امام نووی رحمہ اللہ فرماتے ہیں کہ مسلمانوں کا اس بات پر اجماع ہے کہ (مردوں کے لیے) چھنگلی (چیچی) میں انگوٹھی پہننا مسنون ہے جبکہ عورت اپنی تمام انگلیوں میں انگوٹھی پہن سکتی ہے ‘ نیز انہوں نے یہ بھی کہا ہے کہ شہادت والی اور درمیان والی انگلیوں میں مردوں کے لیے انگوٹھی پہننے کی جو ممانعت ہے تو یہ نہی تنزیہی ہے وجوب کی نہیں ہے۔ لیکن امام نووی رحمہ اللہ کی یہ (نہی تنزیہی والی) بات محل نظر ہے کیونکہ نہی تو تحریم کے لیے ہوتی ہے الا یہ کہ کوئی کوئی قرینہ صارفہ موجود ہو اور اس جگہ کوئی بھی قرینہ نہیں ہے لہذا یہ نہی تحریم کے لیے ہے۔ واللہ اعلم . 2۔ ہدایت وسداد (میانہ روی) کی دعا کرنا مستحب ہے۔"}],[5211,"علی رضی اللہ عنہ کہتے ہیں کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے انگوٹھی اس میں اور اس میں پہننے سے منع فرمایا یعنی شہادت کی اور بیچ کی انگلی میں\"۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے مجھے اس اور اس یعنی انگشت شہادت اور درمیانی انگلی میں انگوٹھی ڈالنے سے منع فرمایا ہے۔ یہ (استاد محمد) ابن المثنی کے لفظ ہیں۔"}],[5212,"علی رضی اللہ عنہ کہتے ہیں کہ مجھ سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کہو: «اللہم اهدني وسددني» اللہ! مجھے ہدایت دے، مجھے درست رکھ\"، اور آپ نے منع فرمایا کہ میں انگوٹھی اس میں اور اس میں پہنوں۔ اور اشارہ کیا شہادت کی اور بیچ کی انگلی کی طرف۔ عاصم بن کلیب نے ان میں سے صرف ایک کا تذکرہ کیا۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے فرمایا: ’’ کہو: اے اللہ! مجھے ہدایت اور میانہ روی پر قائم رکھ ‘‘۔ اور آٖپ نے مجھے اس اور اس یعنی انگشت شہادت اور درمیانی انگلی میں انگوٹھی ڈالنے سے منع فرمایا۔","f2":": ’’میانہ روی ‘‘ عربی میں لفظ سداد استعمال فرمایا گیا ہے۔ اس کے لفظی معنی درست بات اور درست کام کے ہیں۔ اور درست وہی ہوتا ہے جس میں میانہ روی ہو ‘ لہذا اس معنی کو ترجیح دی گئی ہے۔"}],[5213,"انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب پاخانہ جاتے تو اپنی انگوٹھی اتار لیتے ۱؎۔\n§وضاحت\n۱؎: بہتر یہی ہے کہ جس انگوٹھی میں قرآنی آیات اور ذکر الٰہی ہو اسے پاخانہ میں لے جانے سے بچا جائے۔","الألباني: ضعيف",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب بیت الخلاء میں ہوتے تو انگوٹھی اتار دیتے۔"}],[5214,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سونے کی ایک انگوٹھی بنوائی اور اس کا نگینہ اپنی ہتھیلی کی طرف رکھا، پھر لوگوں نے بھی سونے کی انگوٹھیاں بنوائیں، تو آپ نے اپنی انگوٹھی نکال پھینکی اور فرمایا: \"میں اسے کبھی نہیں پہنوں گا\" پھر لوگوں نے بھی اپنی انگوٹھیاں نکال پھینک دیں ۱؎۔\n§وضاحت\n۱؎: عبداللہ بن عمر رضی اللہ عنہما سے مروی اس حدیث اور بعد کی آنے والی حدیثوں کا تعلق مذکورہ باب سے نہیں ہے، ممکن ہے صاحب کتاب نے کوئی عنوان قائم کیا ہو، مگر نساخ حدیث اسے سہوا درج نہ کر سکے ہوں، یہ بھی کہا جاتا ہے کہ ابن عمر رضی اللہ عنہما سے مروی ان تمام طرق کے ذکر سے مصنف کا مقصد یہ ہے کہ پاخانہ میں داخل ہوتے وقت انگوٹھی اتار پھینکنے کی روایت ہمام کے وہم سے خالی نہیں ہے کیونکہ عام صحیح روایات سے جو ثابت ہے وہ کسی سبب سے سونے کی انگوٹھی کا اتار پھینکنا ہے نہ کہ پاخانہ جاتے وقت انگوٹھی کا اتارنا ہے، یہ بھی معلوم ہونا چاہیئے کہ ہمام کی حدیث غیر محفوظ ہے۔","الألباني: صحيح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے سونے کی انگوٹھی بنوائی اور اس کا نگینہ ہتھیلی کی طرف رکھا۔ لوگوں نے بھی سونے کی انگوٹھیاں بنوالیں۔ پھر رسول اللہ صلی اللہ علیہ وسلم نے وہ انگوٹھی پھینک دی اور فرمایا: ’’ اب میں اسے کبھی نہیں پہنوں گا۔ ‘‘ تو لوگوں نے بھی اپنی انگوٹھیاں پھینک دیں۔","f2":"ظاہرا ً اس روایت کا متعلقہ باب سے کوئی تعلق نہیں لہذا یا تو مصنف رحمہ اللہ یہاں نیا باب قائم کرنا بھول گئے ہیں یا اشارہ ہے کہ سابقہ روایت (5216) وہم ہے۔ اصل روایت میں سونے کی انگوٹھی اتارنے کا ذکر ہے وہ بھی بیت الخلاء میں داخل ہوتے وقت نہیں بلکہ دوبارہ نہ پہننے کے ارادے سے۔ واللہ اعلم . آئندہ احادیث کے بارے میں یہی کہا جائے گا۔"}],[5215,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سونے کی انگوٹھی بنوائی اور اس کا نگینہ ہتھیلی کی طرف رکھا۔ پھر لوگوں نے بھی انگوٹھیاں بنوائیں، تو آپ نے وہ انگوٹھی نکال پھینکی اور فرمایا: \"میں اسے کبھی نہیں پہنوں گا\"۔","الألباني: صحيح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سونے کی انگوٹھی بنوائی اور اس کا نگینہ ہتھیلی کی طرف رکھا۔ لوگوں نے بھی انگوٹھیاں بنوالیں۔ پھر نبی اکرم صلی اللہ علیہ وسلم نے وہ انگوٹھی اتار پھینکی اور فرمایا: ’’ میں اسے کبھی نہیں پہنوں گا۔ ‘‘"}],[5216,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے سونے کی ایک انگوٹھی پہنی پھر اسے نکال کر پھینک دی اور چاندی کی انگوٹھی پہنی اور اس میں«محمد رسول اللہ» نقش کرایا اور فرمایا: \"کسی کے لیے مناسب نہیں کہ وہ میری اس انگوٹھی کے نقش کی طرح نقش کرائے\"، پھر آپ نے اس کے نگینے کو ہتھیلی کی جانب کر لیا۔","الألباني: صحيح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے ‘ انہوں نے فرمایا: نبی اکر م صلی اللہ علیہ وسلم نے سونے کی انگوٹھی بنوائی تھی ‘ پھر آپ نے اسے پہننا چھوڑ دیا اور چاندی کی انگوٹھی پہنی اور اس میں ’’ محمد رسول اللہ ‘‘ نقش کروایا اور فرمایا: ’’ کسی کو لائق نہیں کہ وہ میری انگوٹھی کے نقش کے مطابق نقش بنوائے۔ ‘‘ پھر آپ نے اس کا نگینہ ہتھیلی کی طرف رکھا۔"}],[5217,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے تین دن تک سونے کی انگوٹھی پہنی، پھر جب صحابہ کرام رضی اللہ عنہم نے آپ کو دیکھا تو سونے کی انگوٹھی عام ہو گئی۔ یہ دیکھ کر آپ نے اسے نکال پھینکا۔ پھر معلوم نہیں وہ کیا ہوئی، پھر آپ نے چاندی کی انگوٹھی کا حکم دیا اور حکم دیا کہ اس میں \"محمد رسول اللہ\" نقش کر دیا جائے، وہ انگوٹھی رسول اللہ صلی اللہ علیہ وسلم کے ہاتھ میں رہی یہاں تک کہ آپ کی وفات ہو گئی، پھر ابوبکر رضی اللہ عنہ کے ہاتھ میں رہی یہاں تک کہ وہ بھی وفات پا گئے، پھر عمر رضی اللہ عنہ کے ہاتھ میں رہی یہاں تک کہ وہ بھی وفات پا گئے، پھر عثمان رضی اللہ عنہ کے ہاتھ میں ان کی مدت خلافت کے چھ سال تک رہی، پھر جب خطوط کثرت سے لکھے جانے لگے تو اسے انصار کے ایک شخص کے حوالے کر دیا، وہ اس سے مہریں لگاتا تھا۔ ایک بار وہ انصاری عثمان رضی اللہ عنہ کے ایک کنوئیں پر گیا، تو وہ انگوٹھی (اس میں) گر گئی، اور تلاش کے باوجود نہ ملی۔ پھر اسی جیسی انگوٹھی بنانے کا حکم ہوا اور اس میں \"محمد رسول اللہ\" نقش کیا گیا۔","الألباني: ضعيف الإسناد",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ رضی اللہ عنہ نے تین دن سونے کی انگوٹھی پہنی۔ جب آپ کے صحابہ رضی اللہ عنہم نے یہ دیکھا تو سونے کی انگوٹھیاں عام ہوگئیں۔ آپ نے اپنی انگوٹھی اتار دی۔ نہ معلوم آپ نے اسے کیا کیا؟ پھر آپ نے چاندی کی انگوٹھی بنانے کاحکم دیا اور فرمایا کہ اس میں ’’محمدرسول اللہ ‘‘ کےالفاظ کندہ کیے جائیں۔ یہ انگوٹھی رسول اللہ صلی اللہ علیہ وسلم کے دست مبارک میں رہی حتی کہ آپ اللہ تعالیٰ کو پیارے ہو گئے۔ پھر سیدنا ابو بکر رضی اللہ عنہ کے ہاتھ میں رہی حتی کہ وہ بھی اللہ کو پیارے ہو گئے۔ پھر عمر رضی اللہ عنہ کے ہاتھ میں رہی حتی کہ وہ بھی اللہ کو پیارے ہوگئے۔ پھر سیدنا عثمان رضی اللہ عنہ کی خلافت کے چھ سال تک ان کے ہاتھ میں رہی۔ پھر جب خطوط کی کثرت ہوئی توآپ نے وہ انگوٹھی ایک انصاری کے سپرد کر دی (تاکہ وہ مہر لگادیا کرے)۔ وہ مہر لگایا کرتا تھا۔ ایک دفعہ وہ انصاری سیدنا عثمان رضی اللہ عنہ کے ایک کنویں کی طرف گیا تو اس سےوہ انگوٹھی (اس کنویں میں) گر پڑی۔ بہت تلاش کی گئی مگر نہ ملی۔ پھر انہوں نےاس جیسی ایک اور انگوٹھی بنانے کاحکم دیا اور اس میں بھی ’’ محمد رسول اللہ ‘‘ کے الفاظ کندہ کروائے۔","f2":"1۔ رسول اللہ صلی اللہ علیہ وسلم کی مبارکہ انگوٹھی آپ کی وفات کےبعد خلفاء کےہاتھ میں بطور ضرورت وتبرک رہی نہ کہ بطور ملکیت۔ جب وہ انگوٹھی گم ہو گئی تو فتنہ وفساد کا دور شروع ہو گیا۔ گویا ایک بہت بڑی برکت اٹھ گئی۔ آخر خاتم النبین صلی اللہ علیہ وسلم کی انگوٹھی تھی۔ فداه أبي وأمي، نفسي وروحي صلی اللہ علیہ وسلم -\n2۔ ’’خطوط کی کثرت ‘‘ تو ان کو بار بار مہر لگانے میں وقت ہوتی تھی۔ انہوں نے مہر لگانے کےلیے ایک انصاری کو مقرر فرمالیا۔\n3۔ ’’ایک کنویں ‘‘ اس کنویں کانام بئر اریس تھا۔ انگوٹھی تلاش کرنے کےلیے کنویں کو پانی سے خالی کیاگیا اور پھر انچ انچ جگہ چھانی گئی مگر انگوٹھی کو نہ ملنا تھا نہ ملی۔ إِنّا لِلَّـهِ وَإِنّا إِلَيهِ ر‌اجِعونَ۔\n4۔ ’’الفاظ کندہ کروائے ‘‘ احادیث صحیحہ میں واضح طورپر موجود ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے انگوٹھیوں پر یہ الفاظ کندہ کرانے سے لوگوں کوروک دیا تھا لیکن یہ انگوٹھی تواصل انگوٹھی کے قائم مقام تھی، اس لیے اس پر یہ الفاظ کندہ کرائے گئے، نیز آپ کا مقصد اشتباہ اور جعل سازی کی بندش تھا۔ اصل کے گم ہونے پر نقل کی تیاری سے یہ خدشہ نہیں ہوتا۔ اشتباہ اور جعل سازی توتب ہوتی اگر بیک وقت کئی انگوٹھیاں ایک نقش والی ہوتیں۔ گویا احکام کا مدار مقاصد ہوتے ہیں نہ کہ ظاہر الفاظ۔ اور یہ بات یادرکھنے کی ہے۔ اس جیسے نقش والی انگوٹھی بنوانے سے ممانعت کی اک اہم وجہ یہ بھی تھی کہ اس نقش کی حیثیت سرکار ی تھی، اس لیے آپ کےبعد خلفائے راشدین وہ انگوٹھی استعمال کرتے رہے اور اس کے گم ہونے پر سندنا عثمان رضی اللہ عنہ نے ایسے ہی نقش والی انگوٹھی بنوائی۔ واللہ اعلم"}],[5218,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سونے کی ایک انگوٹھی بنوائی، اس کا نگینہ آپ اپنی ہتھیلی کی طرف رکھتے تھے، پھر لوگوں نے بھی سونے کی انگوٹھیاں بنوائیں، یہ دیکھ کر آپ نے اسے نکال پھینکی تو لوگوں نے بھی اپنی انگوٹھیاں نکال پھینکیں، پھر آپ نے چاندی کی ایک انگوٹھی بنوائی، اس سے آپ (خطوط پر) مہریں لگاتے تھے، اسے پہنتے نہیں تھے ۱؎۔\n§وضاحت\n۱؎: یعنی اکثر اوقات میں نہیں پہنتے تھے، ورنہ یہ ثابت ہے کہ آپ انگوٹھی پہنا کرتے تھے۔","الألباني: صحيح دون قوله ولا يلبسه فإنه شاذ",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سونے کی انگوٹھی بنوائی۔ آپ اس کا نگینہ ہتھیلی کی طرف رکھتے تھے۔ لوگوں نے بھی سونے کی انگوٹھیاں بنوالیں۔ پھر رسول اللہ صلی اللہ علیہ وسلم نے اسے اتار پھینکا۔ لوگوں نے بھی اپنی انگوٹھیاں اتار پھینکیں۔ پھر آپ نے چاندی کی انگوٹھی بنوائی۔ آپ اس سے مہر لگاتے تھے۔ اسے پہنتے نہیں تھے۔","f2":"1۔ ’’اتار پھینکیں ‘‘ صحابہ کرام رضی اللہ عنہم کے اس طرح کرنے سے معلوم ہوتا کہ رسول اللہ صلی اللہ علیہ وسلم کے افعال کی اقتدا بھی اسی طرح ضروری تھی اور ہے جس طرح آپ کے اقوال و احکام اور فرامین کی، الا یہ کہ خصوص کی کوئی دلیل ہو۔\n2۔ ان احادیث کی باب سے مناسبت کےبار ے میں دیکھیے فائدہ حدیث:5217۔\n3۔ ’’اسے پہنتے نہیں تھے ‘‘ یعنی ہمیشہ نہین پہنتے تھے تاہم اکثر اسے پہنا کرتے تھے۔"}],[5219,"ابوبکر بن ابی شیخ کہتے ہیں کہ میں سالم کے ساتھ بیٹھا ہو تھا۔ اتنے میں ام البنین کا ایک قافلہ ہمارے پاس سے گزرا ان کے ساتھ کچھ گھنٹیاں تھیں، تو نافع سے سالم نے کہا کہ ان کے والد عبداللہ بن عمر رضی اللہ عنہما نے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"فرشتے ایسے قافلوں کے ساتھ نہیں ہوتے جن کے ساتھ گھنگھرو یا گھنٹے ہوں، ان کے ساتھ تو بہت سارے گھنٹے دکھائی دے رہے ہیں\"۔","الألباني: صحيح",{"u2":"حضرت ابو بکر بن ابوشیخ سے روایت ہے کہ میں حضرت سالم کے پاس بیٹھا تھا کہ ہمارے پاس سے ام البنین کا ایک تجارتی قافلہ گزرا۔ ان کے ساتھ (بہت سی) گھنٹیاں تھیں تو حضرت سالم نے حضرت نافع کو اپنے والد محترم (سیدنا ابن عمر رضی اللہ عنہ) سے بیان کیا کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’فرشتے اس قافلے کا ساتھ نہیں جاتے جن میں ایک گھنٹی بھی ہو۔ کیا خیال ہے، ان کے ساتھ کتنی گھنٹیاں ہوں گی؟‘‘","f2":"گھنٹیوں وغیرہ سے روکنے کی وجہ میں اختلاف ہے۔ یاتو شیطانی آواز ہونے کی وجہ سے کیونکہ یہ جانوروں اور لوگوں کو مست کرتی ہے۔ گویا موسیقی کےحکم میں ہے۔ یا اس لیے کہ گھنٹی وغیرہ کی آواز سے لشکر کی آمد کا پتا چل جاتاتھا جب کہ بسااوقات اچانک حملہ مقصود ہوتا تھا۔ یہ وجہ ہو تو مخصوص حالات میں منع ہو گی۔ لیکن صحیح بات یہ ہے کہ یہ مطلقامنع ہے کیونکہ حدیث نمبر 5224میں گھر کا بھی ذکر ہے۔"}],[5220,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"فرشتے ایسے قافلوں کے ساتھ نہیں چلتے جن کے ساتھ گھنگھرو ہوں\"۔\nأَخْبَرَنَا مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الْمُبَارَكِ، قَالَ: حَدَّثَنَا أَبُو هِشَامٍ الْمَخْزُومِيُّ، قَالَ: حَدَّثَنَا نَافِعُ بْنُ عُمَرَ، عَنْ بُكَيْرِ بْنِ مُوسَى، عَنْ سَالِمٍ، عَنْ أَبِيهِ، رَفَعَهُ، قَالَ: \"لَا تَصْحَبُ الْمَلَائِكَةُ رُفْقَةً فِيهَا جُلْجُلٌ\".\nعبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"فرشتے ایسے قافلوں کے ساتھ نہیں چلتے جن کے ساتھ گھنگھرو ہوں\"۔","الألباني: صحيح — الألباني: صحيح",{"u2":"حضرت سالم نے اپنے والد محترم سے نقل کیا کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’فرشتے اس قافلے کے ساتھ نہیں جاتے جس میں گھنٹی ہو۔ ‘‘"}],[5222,"ام المؤمنین ام سلمہ رضی اللہ عنہا کہتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"اس گھر میں فرشتے داخل نہیں ہوتے، جس میں گھنگھرو یا گھنٹہ ہو، اور نہ فرشتے ایسے قافلوں کے ساتھ چلتے ہیں جن کے ساتھ گھنٹی ہو\"۔","الألباني: حسن",{"u2":"نبی اکرم صلی اللہ علیہ وسلم کی زوجہ محترمہ سیدہ ام سلمہ رضی اللہ عنہا نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ’’فرشتے اس گھر میں داخل نہیں ہوتے جس میں گھنگرو یا گھنٹی ہو۔ اورفرشتے اس قافلے کے ساتھ نہیں جاتے جس میں گھنٹی ہو۔ ‘‘","f2":"1۔ گھنگرو جانوروں، پروندوں حتی کہ بچوں کے گلے میں ڈالے جاتے ہیں۔ اسی طرح جانوروں،پرندوں اوربچوں کے پاؤں میں بھی باندھے جاتے ہیں جب کہ بڑے جانوروں کی گردنوں میں بھی گھنٹی ڈالی جاتی ہے۔ ویسے بھی سکولوں اورگرجوں میں گھنٹیوں بجائی جاتی ہین۔ نبی اکرم صلی اللہ علیہ وسلم نے گھنٹی کو شیطانی آواز فرمایا لہذا کہیں ضرورت اور مجبوری ہو تو اس کی گنجائش ہو سکتی ہے۔ بلاوجہ جائز نہیں ہے۔\n2۔ فرشتوں سے مراد رحمت کے فرشتے ہیں ورنہ محافظ فرشتے اور کاتبیں فرشتے توہر وقت ساتھ رہتے ہیں۔ گویا گھنٹی والی جگہ فرشتوں کی بجائے شیطان ہوتا ہے، اس لیے وہاں اللہ تعالیٰ کی رحمت نہیں ہوتی۔"}],[5223,"ابوالاحوص کے والد مالک بن نضلہ جشمی رضی اللہ عنہ روایت کرتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس بیٹھا ہوا تھا، آپ نے مجھے پھٹے کپڑے پہنے دیکھا تو فرمایا: \"کیا تمہارے پاس مال و دولت ہے؟\" میں نے کہا: جی ہاں، اللہ کے رسول! سب کچھ ہے، آپ نے فرمایا: \"جب تمہیں اللہ تعالی نے سب کچھ دیا ہے تو اس کے آثار بھی تمہارے اوپر ہونے چاہئیں\" ۱؎۔\n§وضاحت\n۱؎: یعنی اللہ کی دی ہوئی نعمت کی قدر کرو اور اس کی شکر گزاری کرتے ہوئے فضول خرچی کئے بغیر اسے حسب ضرورت استعمال کرو اور اس میں سے دوسروں کے حقوق ادا کرو۔","الألباني: صحيح",{"u2":"حضرت ابو الاحوص اپنے والد سے بیان کرتے ہیں کہ میں رسو ل اللہ صلی اللہ علیہ وسلم کے پاس بیٹھا ہوا تھا آپ نے میرے بوسیدہ سے کپڑے دیکھے تو فرمایا: ’’کیاتیرے پاس مال ہے؟ ‘‘ مین نے کہا: جی، اے اللہ کے رسول! ہر قسم کامال ہے۔ آپ نے فرمایا: ’’جب اللہ تعالیٰ نے تجھے مال دیا ہے تو تجھ پر اس کے اثرات نظرآنے چاہئیں۔ ‘‘","f2":"1۔اس حدیث اور آئندہ حدیث کا قریبی باب سے کوئی تعلق نہیں، البتہ کتاب الزینة سے تعلق ہے۔\n2۔ ’’اثرات نظر آنے چاہئیں ‘‘ یعنی اپنی حیثیت کے مطابق رہنا چاہیے۔ یہ بھی اللہ تعالیٰ کا شکر ادا کرنےکی ایک صورت ہے، نیز امیر آدمی اپنی حیثیت کےمطابق رہے تو سائلین کو سہولت رہے گی ورنہ لوگ اسے مستحق سمجھ کر اس کو زکاۃ پیش کریں گے جو اس کے لیے خجالت کا سبب ہو گی، البتہ اچھے کپڑے پہن کر کسی کو حقیر نہ سمجھے۔"}],[5224,"ابوالاحوص کے والد مالک بن نضلہ جشمی رضی اللہ عنہ روایت کرتے ہیں کہ وہ نبی اکرم صلی اللہ علیہ وسلم کے پاس گھٹیا کپڑے پہن کر آئے۔ تو آپ نے فرمایا: \"کیا تمہارے پاس مال و دولت ہے؟\" وہ بولے: جی ہاں، سب کچھ ہے۔ آپ نے فرمایا: \"کس طرح کا مال ہے؟\" وہ بولے: اللہ تعالی نے مجھے اونٹ، بکریاں، گھوڑے اور غلام عطا کئے ہیں۔ آپ نے فرمایا: \"جب اللہ تعالی نے تمہیں مال و دولت سے نوازا ہے تو اللہ تعالی کی نعمت اور اس کے فضل کے تم پر آثار بھی دکھائی دینے چاہیئے\"۔","الألباني: صحيح",{"u2":"حضرت ابو الاحوص اپنے والد سےروایت ہے کہ وہ نبی اکرم صلی اللہ علیہ وسلم کے پاس بہت کم مرتبہ لباس میں آئے۔ نبی اکرم صلی اللہ علیہ وسلم نے انہیں فرمایا: ’’کیاتیرے پاس کوئی مال ہے؟ ‘‘ انہوں نے کہا: جی ہاں! ہر قسم کا مال ہے۔ آپ نے فرمایا: ’’کس قسم کا؟ ‘‘ انہوں نے کہا: اللہ تعالیٰ نے مجھے اونٹ، گائے، بکریاں، گھوڑے اور غلام سب کچھ دیا ہے۔ آپ نے فرمایا: ’’جب اللہ تعالیٰ نے تجھے مال دیا ہے تو پھر تجھ پر اللہ تعالیٰ کے فضل وکرم کے آثار نظرآنے چاہئیں۔‘‘","f2":"لباس کسی کی شخصیت کا عکاس ہوتا ہے، نیز عمومالباس سے انسان کی مالی، ذہنی اورسماجی حیثیت کا پتا بھی چلتا ہے۔ مزید برآں یہ کہ لباس سے کسی کے مہذب اور غیر مہذب ہونے کا پتا چلتا ہے، اس لیے لباس صاف ستھرا،باپردہ او رمالی لحاظ سے حیثیت کے مطابق ہونا چاہیے۔ البتہ فخر و تکبر نہیں ہونا چاہیے۔ ﴿﴾صحیح لباس وہی ہے جس میں کنجوسی، فضول خرچی، عریانی، ریاکاری اور فخر سے پرہیز کیا گیا ہو۔ لباس کے معاملے میں زیادہ تکلف بھی معیوب ہے جس سے انسان خود تنگی میں پڑجائے۔ ریشم پہنا اور لباس ٹخنوں سے نیچے لٹکانا شرعاً حرام ہے، خواہ کسی بھی نیت سے ہو، البتہ شرعی عذر اور مجبوری قابل قبول ہے۔"}],[5225,"عبداللہ بن عباس رضی اللہ عنہما فرماتے ہیں کہ جو کچھ تم کرتے ہو اس میں سب سے بہتر یہ ہے کہ تم میں سے کوئی آدمی اپنی زمین سونے، چاندی کے بدلے کرائے پردے۔\nابوہریرہ رضی اللہ عنہ کہتے ہیں کہ مجھ سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"پانچ چیزیں دین فطرت میں سے ہیں: مونچھ کاٹنا، بغل کے بال اکھیڑنا، ناخن کترنا، ناف کے نیچے کے بال مونڈنا اور ختنہ کرنا\"۔\n§وضاحت\n۱؎: کتاب الزینہ کے جو ابواب اب تک گزرے وہ \" سنن کبری \" کے تھے، اور یہ ابواب اس مختصر :(سنن مجتبی ) میں بڑھائے گئے ہیں، یہ سنن کبری میں نہیں تھے۔ ۲؎: پانچ چیزوں کے ذکر سے «حصر» مقصود نہیں ہے کیونکہ بعض روایتوں میں «عشرۃ من الفطرۃ» \" فطرت میں دس باتیں ہیں \" بھی ہے۔ ۳؎: فطرت سے مراد جبلت یعنی مزاج و طبیعت کے ہیں جس پر انسان کی پیدائش ہوتی ہے، یہاں مراد قدیم سنت ہے جسے انبیاء کرام علیہم السلام نے پسند فرمایا ہے اور پچھلی شریعتیں اس پر متفق ہیں گویا کہ وہ پیدائشی معاملہ ہے۔","الألباني: صحيح الإسناد موقوف",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’پانچ چیزیں فطرت سے ہیں۔ مونچھیں تراشنا، بغلوں کے بال کھیڑنا،ناخن تراشنا، زیر ناف بال مونڈنا اور ختنہ کروانا ‘‘۔","f2":"تفصیل کے لیے دیکھیے‘حدیث:5043۔"}],[5226,"عبداللہ بن عمر رضی اللہ عنہما روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"مونچھیں کاٹو اور داڑھی بڑھاؤ\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر صلی اللہ علیہ وسلم سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’مونچھیں کو ختم کرو اور ڈاڑھی پوری رکھو۔ ‘‘","f2":"دیکھیے حدیث 15"}],[5227,"عبداللہ بن جعفر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے آل جعفر کو یہ کہہ کر کہ آپ ان کے پاس آئیں گے تین روز تک (رونے اور غم منانے کی) اجازت دی ۱؎، پھر آپ ان کے پاس آئے اور فرمایا: \"آج کے بعد میرے بھائی پر مت روؤ\"، پھر فرمایا: \"میرے بھائی کے بچوں کو بلاؤ\"۔ چنانچہ ہمیں لایا گیا گویا ہم چوزے بہت چھوٹے تھے پھر آپ نے فرمایا: \"نائی کو بلاؤ\"، پھر آپ نے ہمارے سر مونڈنے کا حکم دیا۔\n§وضاحت\n۱؎: اس حدیث سے پتہ چلا کہ میت پر بغیر آواز اور سینہ کوبی کے تین دن تک رونا اور اظہار غم کرنا جائز ہے۔","الألباني: صحيح",{"u2":"سیدنا عبد اللہ بن جعفر رضی اللہ عنہ سے روایت ہے، انہوں نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے (سیدنا جعفر طیار رضی اللہ عنہ کی شہادت کےموقع پر) تین دن تک تو حضرت جعفر کی اولاد کو کچھ نہ کہا بلکہ تشریف بھی نہ لائے۔ پھر ان کے پاس تشریف لائے تو فرمایا: ’’تم آج کے بعد میرے بھائی پر نہ رونا۔ ‘‘ پھر فرمایا: ’’میرے بھتیجوں کومیرے پاس لاؤ۔‘‘ ہمیں آپ ے پاس لایا گیا توہم چوزں کی طرح (چھوٹے چھوٹے) تھے۔ فرمایا: ’’حجام کومیرے پاس بلاؤ۔ ‘‘ پھر آپ نے اسےہمارے سرمونڈنے کاحکم دیا۔ یہ روایت مختصر ہے","f2":"1۔ معلوم ہوا کہ نوحہ اور بین کرنے کےبغیر،میت پر ورنا، اور آنسو بہانا، جبکہ وہ اونچی آواز میں نہ ہو جائز ہے، نیز میت پر غمزدہ اور غمگین ہونا بھی شرعاً جائز ہے۔ ہاں!البتہ، اس ’’برائے سوگ‘‘ رونے کی اجازت صرف تین تک دی گئی ہے۔ تین دن کے بعد اس کی اجازت بھی نہیں۔ واللہ اعلم .\n2۔سیدنا جعفر رضی اللہ عنہ سیدنا علی رضی اللہ عنہ کے بڑے بھائی تھے اور رسول اللہ صلی اللہ علیہ وسلم کے چچیرے بھائی تھے۔ اس کے ساتھ ساتھ وہ آپ کے رضاعی بھائی بھی تھے کیونکہ رسول اکرم صلی اللہ علیہ وسلم کو اور جعفر طیار رضی اللہ عنہ کوابولہب کی لونڈی ثوبیہ نے دودھ پلایا تھا۔ ابتدائی دور میں مسلمان ہوئے۔ حبشہ کو ہجرت فرمائی۔ پھرمدینہ منورہ کوہجرت فرمائی۔ غزوہ موتہ میں شہید ہوئے۔ رضی اللہ عنه وأرضاه.\n3۔ ’’نہ رونا ‘‘مطلقا رونے سے نہیں روکا بلکہ سوگ کے طور پر، جیسے عام وفات سے تین دن تک سوگ کیا جاتا ہے۔ تعزیت کے لیے آنے والےملتے رہتے ہیں اور وقتاً فوقتاً رونے کی آوازیں اٹھتی رہتی ہیں ورنہ آنسو تو کسی وقت بھی آسکتے ہیں۔ آنسوؤں پرکی کو اختیار نہیں ہوتا۔\n4۔ سر مونڈنے کے جواز میں کوئی اختلاف نہیں،بچہ ہویابڑا بشرطیکہ سارا سرمونڈا جائے۔ بودیاں نہ چھوڑی جائیں۔"}],[5228,"نافع سے روایت ہے کہ ابن عمر رضی اللہ عنہما اپنے کھیت کرایہ پر اٹھاتے تھے، یہاں تک کہ معاویہ رضی اللہ عنہ کی خلافت کے آخری دور میں انہیں معلوم ہوا کہ اس سلسلے میں رافع بن خدیج رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم سے ممانعت نقل کرتے ہیں تو وہ ان کے پاس آئے، میں ان کے ساتھ تھا، انہوں نے رافع سے پوچھا تو انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم کھیتوں کو کرائے پر دینے سے منع فرماتے تھے۔ اس کے بعد ابن عمر رضی اللہ عنہما نے اسے ترک کر دیا، پھر جب ان سے اس کے متعلق پوچھا جاتا تو کہتے کہ رافع رضی اللہ عنہ کا کہنا ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے اس سے روکا ہے۔ ایوب کی موافقت عبیداللہ بن عمر، کثیر بن فرقد اور جویریہ بن اسماء نے بھی کی ہے۔\nعبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ ہم لوگ مخابرہ کرتے تھے اور اس میں کوئی حرج نہیں سمجھتے تھے، یہاں تک کہ رافع بن خدیج رضی اللہ عنہ نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے مخابرہ سے منع فرمایا ہے ۱؎۔\n§وضاحت\n۱؎: یہاں \" مخابرہ \" سے مراد: بٹائی کا وہی معاملہ ہے جس کی تشریح حدیث نمبر ۳۸۹۳ کے حاشیہ میں گزری، یعنی: زمین کے بعض خاص حصوں میں پیدا ہونے والی پیداوار پر بٹائی کرنا، نہ کہ مطلق پیدا وار کے آدھا پر، جو جائز ہے۔\nجابر بن عبداللہ رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے زمین کرائے پر دینے سے منع فرمایا ہے ۱؎۔ محمد بن مسلم طائفی نے حماد کی متابعت کی ہے۔\n§وضاحت\n۱؎: یہاں بھی کرایہ پر دینے سے مراد زمین کے بعض حصوں کی پیداوار کے بدلے کرایہ پر دینا ہے، نہ کہ روپیہ پیسے، یا سونا چاندی کے بدلے، جو کہ اجماعی طور پر جائز ہے۔\nعبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے خیبر کے یہود کو خیبر کے باغات اور اس کی زمین اس شرط پر دی کہ وہ اس میں اپنے خرچ پر کام کریں گے اور اس کی پیداوار کا آدھا حصہ رسول اللہ صلی اللہ علیہ وسلم کا ہو گا۔\nعرفجہ بن شریح رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"میرے بعد فتنہ و فساد ہو گا، (آپ نے اپنے دونوں ہاتھ بلند کئے پھر فرمایا) تو تم جسے دیکھو کہ وہ امت محمدیہ میں اختلاف اور تفرقہ پیدا کر رہا ہے جب کہ وہ متفق و متحد ہیں تو اسے قتل کر دو خواہ وہ کوئی بھی ہو\"۔\nعبداللہ بن عمر رضی اللہ عنہما روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے «قزع» (کچھ بال مونڈنے اور کچھ چھوڑ دینے) سے منع فرمایا ۱؎۔\n§وضاحت\n۱؎: «قزع» یہ ہے کہ بچوں کے سر کے کچھ بال مونڈ دئیے جائیں اور کچھ چھوڑ دئیے جائیں۔","الألباني: صحيح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے قزع سے منع فرمایا ہے۔","f2":"قزع سے مراد یہی ہے کہ کچھ بال مونڈدیے جائیں، کچھ چھوڑ دیے جائیں۔ (تفصیل کےلیے دیکھیں حدیث:5051.)"}],[5229,"نافع سے روایت ہے کہ عبداللہ بن عمر رضی اللہ عنہما کھیتوں کو کرائیے پر دیتے تھے، ان سے کہا گیا کہ رافع بن خدیج رضی اللہ عنہ نقل کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اس سے روکا ہے۔ نافع کہتے ہیں کہ ابن عمر رضی اللہ عنہما مقام بلاط کی طرف نکلے، میں ان کے ساتھ تھا، تو آپ نے رافع رضی اللہ عنہ سے پوچھا تو انہوں نے کہا کہ ہاں، رسول اللہ صلی اللہ علیہ وسلم نے کھیتوں کو کرائے پر دینے سے روکا ہے، چنانچہ عبداللہ بن عمر رضی اللہ عنہما نے اسے کرائے پر دینا چھوڑ دیا۔\nابن جریج کہتے ہیں کہ میں نے عمرو بن دینار کو کہتے سنا: میں گواہی دیتا ہوں کہ میں نے ابن عمر رضی اللہ عنہما کو سنا اور وہ مخابرہ کے بارے میں پوچھ رہے تھے تو وہ کہہ رہے تھے کہ ہم اس میں کوئی حرج نہیں سمجھتے تھے یہاں تک کہ ہمیں رافع بن خدیج رضی اللہ عنہ نے (خلافت یزید کے) پہلے سال ۱؎ میں خبر دی کہ انہوں نے نبی اکرم صلی اللہ علیہ وسلم کو مخابرہ سے منع فرماتے سنا ہے۔ ان دونوں (سفیان و ابن جریج) کی موافقت حماد نے کی ہے۔\n§وضاحت\n۱؎: یہ واقعہ معاویہ رضی اللہ عنہ کے آخری دور خلافت کا ہے، اس لیے پہلے سال سے مراد یزید کی خلافت کا پہلا سال ہے۔ :(واللہ اعلم )\nعبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو «قزع» (کچھ بال مونڈنے اور کچھ چھوڑ دینے) سے منع فرماتے سنا ہے۔","الألباني: صحيح الإسناد",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے، انہوں نے فرمایا: میں نے رسول اللہ کو قزع سے منع فرماتے سنا ہے۔"}],[5230,"نافع سے روایت ہے کہ ابن عمر رضی اللہ عنہما زمین کا کرایہ لیتے تھے، انہیں رافع بن خدیج رضی اللہ عنہ کی کوئی بات سننے کو ملی تو انہوں نے میرا ہاتھ پکڑا اور رافع رضی اللہ عنہ کے پاس گئے اور میں ان کے ساتھ تھا، تو رافع رضی اللہ عنہ نے ان سے اپنے کسی چچا سے روایت کرتے ہوئے (یہ حدیث بیان کی) کہ رسول اللہ صلی اللہ علیہ وسلم نے زمین کرائے پر دینے سے منع فرمایا ہے، اس کے بعد عبداللہ بن عمر رضی اللہ عنہما نے اسے ترک کر دیا۔\nنافع سے روایت ہے کہ ایک آدمی نے ابن عمر رضی اللہ عنہما کو بتایا کہ رافع بن خدیج رضی اللہ عنہ زمین کو کرائے پر دینے کے سلسلے میں حدیث بیان کرتے ہیں، تو میں اور وہ شخص جس نے انہیں بتایا تھا ان کے ساتھ چلے یہاں تک کہ وہ رافع رضی اللہ عنہ کے پاس آئے، تو انہوں نے بتایا کہ رسول اللہ صلی اللہ علیہ وسلم نے زمین کرائے پر دینے سے منع فرمایا ہے، چنانچہ عبداللہ بن عمر رضی اللہ عنہما نے زمین کرائے پر اٹھانی چھوڑ دی۔\nجابر رضی اللہ عنہ کہتے ہیں کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے مخابرہ، محاقلہ اور مزابنہ سے منع فرمایا ہے۔ سفیان بن عیینہ نے دونوں حدیثوں کو جمع کر کے ہے اور«عن ابن عمر و جابر» کہا ہے۔\nعبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے قزع (کچھ بال مونڈنے اور کچھ چھوڑ دینے) سے منع فرمایا ہے۔","الألباني: صحيح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے، انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے قزع سے منع فرمایا ہے۔"}],[5231,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ وہ زمین کا کرایہ لیتے تھے، یہاں تک کہ رافع رضی اللہ عنہ نے اپنے کسی چچا سے روایت کرتے ہوئے ان سے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے زمین کرائیے پر دینے سے منع فرمایا ہے۔ چنانچہ اس کے بعد انہوں نے اسے ترک کر دیا۔ اسے ایوب نے نافع سے، انہوں نے رافع رضی اللہ عنہ سے روایت کیا ہے اور ان کے چچاؤں کا تذکرہ نہیں کیا ہے۔\nنافع سے روایت ہے کہ رافع بن خدیج رضی اللہ عنہ نے عبداللہ بن عمر رضی اللہ عنہما سے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے کھیتوں کو کرائے پر اٹھانے سے منع فرمایا ہے۔\nنافع کہتے ہیں کہ ابن عمر رضی اللہ عنہما اپنی زمین کو اس میں پیدا ہونے والے غلہ کے بعض حصے کے بدلے کرائے پر دیتے تھے، پھر انہیں معلوم ہوا کہ رافع بن خدیج رضی اللہ عنہ اس سے روکتے اور کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اس سے منع فرمایا ہے، اس پر عبداللہ بن عمر رضی اللہ عنہما نے کہا کہ رافع رضی اللہ عنہ کو جاننے سے پہلے ہم زمین کرائے پر اٹھاتے تھے۔ پھر آپ نے اپنے دل میں کچھ محسوس کیا، تو اپنا ہاتھ میرے مونڈھے پر رکھا یہاں تک کہ ہم رافع کے پاس جا پہنچے، پھر ابن عمر نے رافع سے کہا: کیا آپ نے نبی اکرم صلی اللہ علیہ وسلم کو زمین کرائے پر دینے سے منع فرماتے سنا ہے؟ رافع رضی اللہ عنہ نے کہا: میں نے نبی اکرم صلی اللہ علیہ وسلم کو فرماتے سنا ہے کہ \"کسی چیز کے بدلے زمین کرائے پر نہ دو\" ۱؎۔\n§وضاحت\n۱؎: «بشیٔ» :(کسی چیز کے بدلے ) کا لفظ شاذ ہے، کیونکہ سونے چاندی کے عوض زمین کو کرایہ پر دینے کی بات صحیح اور ثابت ہے۔\nعبداللہ بن عمر اور جابر رضی اللہ عنہم سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے پھل بیچنے سے منع فرمایا یہاں تک کہ اس کا پختہ ہو جانا واضح ہو جائے۔ نیز آپ نے مخابرہ یعنی زمین کو تہائی یا چوتھائی (پیداوار) کے بدلے کرایہ پر دینے سے منع فرمایا۔ اسے ابوالنجاشی عطاء بن صہیب نے بھی روایت کیا ہے اور اس میں ان سے روایت میں ان کے تلامذہ نے اختلاف کیا ہے۔\nعبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"قیامت کے دن مقتول قاتل کو ساتھ لے کر آئے گا، اس کی پیشانی اور اس کا سر اس(مقتول) کے ہاتھ میں ہوں گے اور اس کی رگوں سے خون بہہ رہا ہو گا، وہ کہے گا: اے میرے رب! اس نے مجھے قتل کیا، یہاں تک کہ وہ اسے لے کر عرش کے قریب جائے گا\"۔ راوی (عمرو) کہتے ہیں: لوگوں نے ابن عباس سے توبہ کا ذکر کیا تو انہوں نے یہ آیت: «ومن يقتل مؤمنا متعمدا» \"جو کسی مومن کو جان بوجھ کر قتل کرے گا\" تلاوت کی اور کہا: جب سے یہ نازل ہوئی منسوخ نہیں ہوئی پھر اس کے لیے توبہ کہاں ہے؟۔\nعرفجہ بن شریح اشجعی رضی اللہ عنہ کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم کو منبر پر لوگوں کو خطبہ دیتے دیکھا، آپ نے فرمایا: \"میرے بعد فتنہ و فساد ہو گا، تو تم جسے دیکھو کہ وہ جماعت سے الگ ہو گیا ہے یا امت محمدیہ میں افتراق و اختلاف ڈالنا چاہتا ہے، تو خواہ وہ کوئی بھی ہو اسے قتل کر دو، اس لیے کہ اللہ تعالی کا ہاتھ جماعت پر ہے اور جو جماعت سے الگ ہوا اس کے ساتھ شیطان دوڑتا ہے\"۔\nعبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے «قزع» (کچھ بال مونڈنے اور کچھ چھوڑ دینے) سے منع فرمایا ہے۔","الألباني: صحيح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے قزع سے منع فرمایا ہے۔"}],[5232,"براء رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم درمیانے قد کے، چوڑے مونڈھوں اور گھنی داڑھی والے تھے، آپ کے بدن پر کچھ سرخی ظاہر تھی، سر کے بال کان کی لو تک تھے ۱؎، میں نے آپ کو لال جوڑا پہنے ہوئے دیکھا اور آپ سے زیادہ کسی کو خوبصورت نہیں دیکھا۔\n§وضاحت\n۱؎: نبی اکرم صلی اللہ علیہ وسلم کے سر کے بالوں کے بارے میں متعدد و مختلف روایات وارد ہیں: آدھے کان تک، کانوں کے لو تک، کانوں کے لووں اور کندھوں کے درمیان تک، اور کندھوں تک، اور ان سب روایات میں کوئی تعارض و اختلاف نہیں ہے، بلکہ یہ مختلف حالات کی روایات ہیں، کبھی آپ نے بال کٹوائے تو آدھے کانوں تک کر لیا، اور وہ بڑھ کر کان کے لو تک ہو گئے، اور اسی حالت میں چھوڑ دیئے تو اور بڑھ گئے، کبھی اتنے ہی پر کٹوا لیا اور کبھی چھوڑ دیا تو تو کندھوں کے اوپر یا کندھوں تک ہو گئے، اب جس نے جو دیکھا وہی بیان کر دیا۔","الألباني: صحيح",{"u2":"سیدنا براء رضی اللہ عنہ سے روایت ہے، انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم درمیانے قد کے آدمی تھے۔ کندھوں کا درمیانی فاصلہ زیادہ تھا۔ ڈاڑھی گھنی تھی۔ آپ کے سفید رنگ میں سرخی جھلکتی تھی۔ آپ کے سر کےلمبے لمبے بال کانوں کی کونپلوں تک پہنچتےتھے۔ میں نے آپ کو سرخ جوڑے میں دیکھا۔ اللہ کی قسم! میں نے آپ سے بڑھ کرخوب صورت نہیں دیکھا","f2":"1۔امام نسائی رحمہ اللہ نے جوعنوان قائم کیا اس کا مقصد یہ مسئلہ بیان کرنا ہے کہ مرد کے لیےزلفیں چھوڑنا اور لمبے بال رکھنا جائز ہے، خواہ وہ کندھوں تک چلی جائیں، تاہم کندھوں سے نیچے بال لٹکانا مردوں کےلیے درست نہیں کیونکہ یہ عورتوں کےساتھ مشابہت ہے،نیز کندھوں سے نیچے بال لٹکانا رسو ل اللہ سے ثابت نہیں، حالانکہ آپ کےبال مبارک اکثر اوقات لمبے ہوتے تھے یعنی کانوں کی نزم کی نرم لوتک، کبھی کندھوں تک اور کبھی اس کے درمیان تک ہوا کرتے تھے۔\n2۔پیارے رسول اکرم صلی اللہ علیہ وسلم کے مبارک بالوں کےبارے میں تفصیل حدیث:5056، 5065میں ملاحظہ فرمائیے۔\n3۔ ’’سرخ جوڑے میں ‘‘ عربی جوڑے کےلیے حلہ کالفظ پولاجاتا ہے۔ یہ دو چادریں ہوتی تھیں۔ ایک تہبند کے طور پر باندھی جاتی تھی اور دوسری اوپر اوڑھ لی جاتی تھی۔ فداہ أبي ونفسي وروحي صلی اللہ علیہ وسلم."}],[5233,"براء رضی اللہ عنہ کہتے ہیں کہ میں نے کسی بال والے کو لباس پہنے ہوئے رسول اللہ صلی اللہ علیہ وسلم سے زیادہ خوبصورت نہیں دیکھا، آپ صلی اللہ علیہ وسلم کے بال مونڈھوں کے قریب تھے۔","الألباني: صحيح",{"u2":"سیدنا براء رضی اللہ عنہ نے فرمایا: میں نے کوئی لمبے لمبے بالوں والا سرخ حلہ پہنے ہوئے رسول اللہ صلی اللہ علیہ وسلم کی طرح خوبصورت نہیں دیکھا۔ آپ کے بال کندھوں سے ٹکراتے تھے۔ (آپ کی زلفیں کندھوں پر لہراتی تھیں)","f2":"تفصیل کےلیے دیکھیے، حدیث 5065’"}],[5234,"انس بن مالک رضی اللہ عنہ سے روایت ہے کہ عرینہ کے کچھ لوگ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، انہیں مدینے کی آب و ہوا راس نہیں آئی تو نبی اکرم صلی اللہ علیہ وسلم نے انہیں اپنے اونٹوں کے پاس بھیجا، انہوں نے ان کا دودھ اور پیشاب پیا، جب وہ اچھے ہو گئے تو اسلام سے پھر گئے اور رسول اللہ صلی اللہ علیہ وسلم کے چرواہے کو قتل کر دیا اور اونٹوں کو ہانک لے گئے، رسول اللہ صلی اللہ علیہ وسلم نے ان کے پیچھے کچھ لوگ روانہ کئے، تو انہیں گرفتار کر لیا گیا، پھر ان کے ہاتھ پاؤں کاٹ دیے گئے اور ان کی آنکھیں پھوڑ دی گئیں اور انہیں سولی پر چڑھا دیا گیا ۱؎۔\n§وضاحت\n۱؎: سولی پر چڑھانے کی بات کسی اور روایت میں نہیں ہے، بلکہ صحیح یہ ہے کہ آپ نے انہیں یونہی دھوپ میں ڈال دیا اسی حالت میں وہ تڑپ تڑپ کر مر گئے۔\nانس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس عرینہ کے کچھ لوگ آئے تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"اگر تم سب ہمارے اونٹوں میں جا کر رہتے، ان کا دودھ اور پیشاب پیتے (تو اچھا ہوتا)\" چنانچہ انہوں نے ایسا ہی کیا، پھر جب وہ اچھے ہو گئے تو انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے چرواہے کو جا کر قتل کر دیا اور کافر و مرتد ہو گئے اور نبی اکرم صلی اللہ علیہ وسلم کے اونٹوں کو ہانک لے گئے، آپ نے ان کی تلاش میں کچھ لوگ روانہ کئے، چنانچہ وہ سب گرفتار کر کے لائے گئے تو آپ صلی اللہ علیہ وسلم نے ان کے ہاتھ اور پیر کاٹ دیے اور ان کی آنکھوں کو گرم سلائی سے پھوڑ دیا۔\nانس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے بال آدھے کانوں تک تھے۔","الألباني: صحيح دون قوله وصلبهم",{"u2":"سیدنا انس رضی اللہ عنہ نے فرمایا: نبی اکرم صلی اللہ علیہ وسلم کے بال مبارک نصف کانوں تک ہوتے تھے۔","f2":"نبی صلی اللہ علیہ وسلم کےبالوں کی بابت احادیث میں تین الفاظ آئے ہیں: الجمة، اللمة اور الوفرة.\nالجمة: کندھوں اور شانوں تک لٹکی ہوئی زلفیں\nاللمة: کان کی لو سے بڑھی ہوئی زلفیں\nالوفرة: کانوں تک پہنچنے والے، یعنی کانوں سے ملے ہوئے بال وفرہ کہلاتے ہیں۔ رسول اللہ صلی اللہ علیہ وسلم کےبال مبارک، مختلف اوقات میں مختلف صورتوں میں ہوا کرتے تھے۔ مذکورہ حدیث میں ایک صورت کا ذکر ہے۔"}],[5235,"انس رضی اللہ عنہ کہتے ہیں کہ قبیلہ عرینہ کے کچھ لوگ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، انہیں مدینے کی آب و ہوا راس نہیں آئی، تو نبی اکرم صلی اللہ علیہ وسلم نے ان سے فرمایا: \"اگر تم جاتے اور ہمارے اونٹوں کا دودھ پیتے (تو اچھا ہوتا)\" (قتادہ نے «البانہا» (دودھ) کے بجائے «ابو الہا» (پیشاب) کہا ہے)چنانچہ وہ لوگ رسول اللہ صلی اللہ علیہ وسلم کے اونٹوں کے پاس گئے جب اچھے ہو گئے تو اسلام لانے کے بعد کافر (مرتد) ہو گئے اور رسول اللہ صلی اللہ علیہ وسلم کے مسلمان چرواہے کو قتل کر دیا اور آپ کے اونٹ ہانک لے گئے اور جنگجو (لڑنے والے) بن کر گئے۔ آپ نے ان کی تلاش میں کچھ لوگوں کو بھیجا تو وہ گرفتار کر لیے گئے، آپ نے ان کے ہاتھ پیر کاٹ دیے اور ان کی آنکھوں کو گرم سلائی سے پھوڑ دیا\"۔\nانس رضی اللہ عنہ سے روایت ہے کہ قبیلہ عرینہ کے کچھ لوگ حرہ میں ٹھہرے، پھر وہ نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے، انہیں مدینے کی آب و ہوا راس نہ آئی، تو آپ نے انہیں حکم دیا کہ وہ صدقے کے اونٹوں میں جا کر ان کے دودھ اور پیشاب پیئیں، تو انہوں نے چرواہے کو قتل کر دیا، اسلام سے پھر گئے اور اونٹوں کو ہانک لے گئے، رسول اللہ صلی اللہ علیہ وسلم نے ان کے پیچھے کچھ لوگوں کو بھیجا، انہیں پکڑ کر لایا گیا تو آپ نے ان کے ہاتھ پاؤں کاٹ دئیے، آنکھیں پھوڑ دیں اور انہیں حرہ میں ڈال دیا۔ انس رضی اللہ عنہ کہتے ہیں: میں نے ان میں سے ایک کو دیکھا کہ وہ پیاس کی وجہ سے زمین سے اپنے منہ کو رگڑ رہا تھا، (یعنی زمین کو اپنے منہ سے چاٹ رہا تھا) یہاں تک کہ سب مر گئے۔\nانس رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم اپنے بال مونڈھوں تک رکھتے تھے۔","الألباني: صحيح",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم کے مبارک بال کندھوں کو لگتے تھے۔"}],[5236,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ ہمارے پاس نبی اکرم صلی اللہ علیہ وسلم آئے، آپ نے ایک شخص کو دیکھا، اس کے سر کے بال الجھے ہوئے تھے، آپ نے فرمایا: \"کیا اس کے پاس کوئی چیز نہیں ہے جس سے اپنے بال ٹھیک رکھ سکے؟\"۔","الألباني: صحيح",{"u2":"سیدنا جابر بن عبد اللہ رضی اللہ عنہ نے فرمایا کہ نبی اکرم صلی اللہ علیہ وسلم ہمارے پاس تشریف لائے۔ آپ نے ایک آدمی کو دیکھا جس کے سر کےبال بکھرے ہوئے تھے۔ آپ نے (ناپسند کرتے ہوئے) فرمایا: ’’کیا اسے کوئی ایسی چیز نہیں ملتی جس سے اپنے بالوں کو سنوار سکے۔‘‘","f2":"1۔ مقصد یہ ہے کہ جب کوئی شخص لمبے بال اور زلفیں رکھے تو اسے چاہیے کہ ان کی عزت کرے، یعنی انہیں سنوارنے کر رکھے، تیل لگائے اور کنگھی کرے، نیز انہیں پراگندہ ہونے سے محفوظ رکھے۔ رسول اللہ صلی اللہ علیہ وسلم کا ارشاد گرامی ہے: [من كان له شعر فليكرمه] ’’جس شخص نے بال رکھے ہوٹ تو اسے چاہیے کہ ان کی عزت کرے، یعنی انہیں بنا سنوار کر رکھے۔ ‘‘ (سنن ابی داؤد، الترجل،باب فی اصلاح الشعر، حدیث: 4163، وقال الالبانی حسن صحیح) بالوں کی عزت یعنی انہیں سنوارنے کا یہ مفہوم قطعاً نہیں کہ ایک شیشہ اور کنگھی ہمیشہ جیب کی زینت بنی رہے۔ اس حوالے سے کچھ روایات بھی منقول ہیں لیکن وہ درجہ صحت کو نہیں پہنچیں۔ ہاں بوقت ضرورت ان کا خیال کیا جائے، اور اس کی حد ایک دن چھوڑ کر کنگھی کرناہے بلاناغہ ٹیپ ٹاپ کی ممانعت ہے۔ سیدنا عبد اللہ بن مغفل رضی اللہ عنہ فرماتے ہیں: [أن رسول الهل صلی اللہ علیہ وسلم نهي عن الترجل إلا غبا] (سنن ابی داؤد، الترجل،باب النهى عن كثير من الإرفاء، حدیث: 4159) ’’رسول اکرم صلی اللہ علیہ وسلم نے ہمیں روزانہ کنگھی کرنے سے منع فرمایا۔ ‘‘\n2۔ میلا کچیلا رہنا اور بالوں کو نہ سنوارنا زہد ہے نہ سادگی بلکہ یہ حماقت اور جہالت ہے، جو کسی بھی طرح ایک باوقار اور قابل احترام مسلمان کے لائق نہیں۔ اسلام انتہائی صاف ستھرا اور پاکیزہ دین ہے اور اپنے پیروکاروں سے بھی پاکیزگی اور صاف ستھرائی کا تقاضا کرتا ہے۔مزید برآں رسول کریم صلی اللہ علیہ وسلم کاارشادگرامی ہے:[إن الله يحب الجمال] ’’بلاشبہ اللہ تعالیٰ حسین و جمیل ہے اور حسن و جمال کو پسند فرماتا ہے۔‘‘ (مسند احمد:4/ 133،134)"}],[5237,"ابوقتادہ رضی اللہ عنہ کہتے ہیں کہ ان کے بال بڑے بڑے تھے، انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے پوچھا تو آپ نے حکم دیا: \"انہیں اچھی طرح رکھو اور ہر روز کنگھی کرو\"۔","الألباني: ضعيف",{"u2":"سیدنا ابو قتادہ رضی اللہ عنہ نے فرمایا کہ ان کے لمبے لمبے بال تھے۔ انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے اس بارے میں پوچھا تو آپ نے انہیں حکم دیا کہ ان (بالوں) سے اچھا سلوک کرو اور ہر روز کنگھی کیا کرو۔"}],[5238,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم اپنے بال چھوڑ دیتے تھے اور کفار و مشرکین بالوں میں مانگ نکالتے تھے، آپ ایسے معاملات میں جن میں کوئی حکم نہ ملتا اہل کتاب (یہود و نصاری) کی موافقت پسند فرماتے تھے، پھر اس کے بعد آپ نے بھی مانگ نکالی۔","الألباني: صحيح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم اپنے سر کےبال لٹکائے رکھتے (بالوں میں مانگ نہیں نکالا کرتے تھے) -جب کہ مشرکین اپنے سر کے بالوں کی مانگ نکالتے۔ اور رسول اللہ صلی اللہ علیہ وسلم کو جب تک کسی بات کے متعلق (بذریعہ وحی) کوئی حکم نہ آتا تو آپ اہل کتاب کی موافقت پسند فرماتے تھے۔ پھر اس کے بعد رسول اللہ صلی اللہ علیہ وسلم بھی (سرمیں) مانگ نکالنے لگے تھے۔","f2":"1۔ عادات میں جب تک نہی نہ آئے جواز قائم رہتا ہے۔ چونکہ مانگ نکالنے سے نہی وارد نہیں ہوئی لہذا مانگ نکالنا جائز ہے اور نہ نکالنا بھی جائز ہے کیونکہ نکالنے کاحکم وارد نہیں۔ آپ سے مانگ نکالنا بھی ثابت ہے اور نہ نکالنا بھی۔ اس کی اصل وجہ یہ ہے کہ اس کی بابت شریعت نے کوئی مخصوص حکم نہیں دیا۔ حالات کے تحت دونوں میں سے کسی کو بھی اختیار کیا جاسکتا ہے۔ ایسے مسائل میں آپ کا اہل کتاب کی موافقت کرنا ان کی تالیف قلب کے لیے تھا کہ شاید وہ اسلام کی طرف مائل ہو جائیں مگر جب محسوس فرمایا کہ ان کے لیے موافقت بھی مفید نہیں تو آپ نے ان کی موافقت چھوڑ دی۔ رسول اللہ صلی اللہ علیہ وسلم کو اہل کتاب کی موافقت اس لیے موافقت بھی مفید نہیں توآپ نے ان کی موافقت چھوڑ دی۔ رسول اللہ صلی اللہ علیہ وسلم کو اہل کتاب کی موافقت اس لیے بھی پسند تھی کہ وہ کم از کم دعوے کی حد تک ہی سہی سماوی دین پر عمل پیرا ہونے کے دعویدار تھے۔ اس کے برعکس مشرکین تو پکے بت پرست تھے۔\n2۔ مانگ سر کے درمیان میں نکالنے چاہیے کیونکہ رسول اللہ صلی اللہ علیہ وسلم کی عادت مبارکہ درمیان میں مانگ نکالنا ہی تھی۔ واللہ اعلم ."}],[5239,"عبید نامی ایک صحابی رسول رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم «ارفاہ» (بہت زیادہ عیش میں پڑ جانے) سے منع فرماتے تھے۔ عبداللہ بن بریدہ سے پوچھا گیا: «ارفاہ» کیا ہے؟ کہا: «ارفاہ» میں (ہر روز) کنگھی کرنا بھی شامل ہے ۱؎۔\n§وضاحت\n۱؎: لفظ «ترجل» کا معنی \" ہر روز کنگھی کرنا \" اس لیے کیا گیا ہے کہ نبی اکرم صلی اللہ علیہ وسلم خود بھی کنگھی کرتے تھے، اور اس کی ترغیب بھی دیتے تھے، :(جیسا کہ حدیث نمبر: ۵۲۳۸ میں ہے ) آپ نے صرف کثرت سے کنگھی کرنے سے منع فرمایا، اور ناغہ کر کے کرنے کی اجازت دی ہے۔","الألباني: صحيح",{"u2":"حضرت عبد اللہ بن بریدہ سے روایت ہے کہ اصحاب نب صلی اللہ علیہ وسلم میں سے ایک صحابی جن کو عبیدہ کہا جاتا تھا کہ رسول اللہ صلی اللہ علیہ وسلم نے زیادہ نازنخرے سے منع فرمایا ہے۔ حضرت بریدہ سے پوچھا گیا: ناز نخرے سے کیا مراد ہے؟ انہوں نے فرمایا: اسی میں سے (ہرروز) کنگھی کرنا ہے۔","f2":"تفصیل کے لیے دیکھیے:5061، 5057، 5239."}],[5240,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم طاقت بھر دائیں طرف سے شروع کرنا پسند فرماتے تھے: وضو کرنے، جوتے پہننے اور کنگھی کرنے (وغیرہ امور) میں۔","الألباني: صحيح",{"u2":"سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہر ممکن تک دائیں طرف سے ابتداء فرماتے تھے۔ وضو میں، جوتا پہنتے وقت اور کنگھی فرماتے وقت۔","f2":"دیکھیے، حدیث:5062."}],[5241,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یہودی اور نصرانی (بالوں کو) نہیں رنگتے، لہٰذا تم ان کی مخالفت کرو\" ۱؎۔\n§وضاحت\n۱؎: یعنی: سفید بالوں کو رنگ دو، البتہ کالے خضاب سے بچو۔","الألباني: صحيح",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ یہودی اور عیسائی اپنے بالوں کو نہیں رنگتے۔ تم ان کی مخالفت کرو۔ ‘‘","f2":"تفصیل کےلیے دیکھیے، احادیث:5072اور 5077."}],[5242,"جابر رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کے پاس (ابوبکر کے والد) ابوقحافہ رضی اللہ عنہما لائے گئے، ان کا سر اور داڑھی ثغامہ نامی گھاس کی طرح تھے، نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"ان کے بالوں کا رنگ بدلو\"، یا (فرمایا) \"خضاب لگاؤ\"۔\n§وضاحت\n۱؎: ثغامہ ایک گھاس ہے جس کے پھل اور پھول سب سفید ہوتے ہیں۔","الألباني: صحيح",{"u2":"سیدنا جابر رضی اللہ عنہ نے فرمایا: نبی اکرم صلی اللہ علیہ وسلم کے پاس سیدنا ابو قحافہ رضی اللہ عنہ کولایا گیا۔ ان کا سر اور ڈاڑھی ثغامہ کی طرح تھے۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’ان کا رنگ بدلو) یا فرمایا) ان کو خضاب کرو۔","f2":"ثغامةپہاڑ کی چوٹی پر اگنے والی گھاس جس کے پھل اور پھول بلکل سفید ہوتے ہیں نیز خشک ہونے پر اس کی سفیدی اور بڑھ جاتی ہے۔ تفصیل کےلیے دیکھیے، حدیث:5079۔"}],[5243,"عبید کہتے ہیں کہ میں نے ابن عمر رضی اللہ عنہما کو اپنی داڑھی پیلی کرتے دیکھا، تو ان سے اس کے بارے میں پوچھا؟ انہوں نے کہا: میں نے نبی اکرم صلی اللہ علیہ وسلم کو اپنی داڑھی زرد (پیلی) کرتے ہوئے دیکھا ہے ۱؎۔\n§وضاحت\n۱؎: دیکھئیے حدیث نمبر ۵۰۸۸ کا حاشیہ۔","الألباني: صحيح",{"u2":"حضرت عبید بیان کرتے ہیں کہ میں نے سیدنا ابن عمر رضی اللہ عنہ کودیکھا، وہ ڈاڑھی کو زرد کرتے تھے۔ میں نے ان سے اس کے متعلق بات کی توانہوں نے فرمایا:میں نے نبی اکرم صلی اللہ علیہ وسلم کو دیکھا آپ اپنی ڈاڑھی مبارک کو زرد کرتے تھے۔","f2":"تفصیل کےلیے دیکھیے، احادیث:5086تا 5089۔"}],[5244,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم چمڑے کا جوتا پہنتے اور اپنی داڑھی ورس اور زعفران سے پیلی کرتے تھے، اور ابن عمر رضی اللہ عنہما بھی ایسا کیا کرتے تھے ۱؎۔\n§وضاحت\n۱؎: دیکھئیے حاشیہ حدیث نمبر ۵۰۸۸۔","الألباني: صحيح الإسناد",{"u2":"سیدنا ابن عمر رضی اللہ عنہ نے فرمایا: نبی اکرم صلی اللہ علیہ وسلم سبتی جوتے پہنا کرتے تھے اور اپنی ڈاڑھی کوورس اور زعفران سے رنگتے تھے۔ اور سیدنا ابن عمر رضی اللہ عنہ بھی اسی طرح کیا کرتے تھے۔","f2":"1۔ ’’سبتی جوتے ‘‘ دباغت شدہ چمڑے سےبنائے گئے جوتوں کو کہتے ہیں۔ ان پر بال نہیں ہوتے۔ عرب میں بالوں سمیت چمڑے کے جوتوں کا بھی رواج تھا۔ ان کے مقابلے میں سبتی جوتوں کو قیمتی سمجھا جاتا تھا۔ ان کے پہننے میں کوئی حرج نہیں۔\n2۔ورس و زعفران رنگ دارخوشبو ئیں ہیں۔ ان کا استعمال مرد کے لیے جسم میں تو درست نہیں، البتہ بالوں کو رنگا جاسکتا ہے باقی رسول اللہ صلی اللہ علیہ وسلم کا ڈاڑھی کورنگنا تو اس کی تفصیل کےلیے دیکھیے حدیث:5082، 5089اور 5118۔"}],[5245,"حمید بن عبدالرحمٰن کہتے ہیں کہ میں نے معاویہ رضی اللہ عنہ کو سنا، وہ مدینے میں منبر پر تھے، انہوں نے اپنی آستین سے بالوں کا ایک گچھا نکالا اور کہا: مدینہ والو! تمہارے علماء کہاں ہیں؟ میں نے نبی اکرم صلی اللہ علیہ وسلم کو ان جیسی چیزوں سے منع فرماتے ہوئے سنا ہے، نیز آپ صلی اللہ علیہ وسلم نے فرمایا: \"بنی اسرائیل کی عورتوں نے جب ان جیسی چیزوں کو اپنانا شروع کیا تو وہ ہلاک و برباد ہو گئے\"۔","الألباني: صحيح",{"u2":"حضرت حمید بن عبدالرحمن نے فرمایا: میں نےسیدنا معاویہ رضی اللہ عنہ کومدینہ منورہ میں منبر پر فرماتے سنا جب کہ انہوں نے اپنی آستین سے بالوں کا ایک گچھا نکالا اور فرمایا: اے مدینہ والو! تمہارے علماء کہاں ہیں؟ میں نے نبی اکرم صلی اللہ علیہ وسلم کو اس جیسے جعلی بالوں سےمنع فرماتے، نیز آپ نے فرمایا: ’’جب بنی اسرائیل کی عورتوں نے اس قسم کے کام اختیار کیے تو وہ ہلاک ہو گئے۔‘‘","f2":"’’کہاں ہیں ‘‘ یعنی وہ تمہیں ان کاموں سے روکتے کیوں نہیں؟ باقی کےلیے تفصیل ملاحظہ فرمائیے، حدیث:5095۔"}],[5246,"سعید بن مسیب کہتے ہیں کہ معاویہ رضی اللہ عنہ مدینہ آئے اور ہمیں خطاب کیا، آپ نے بالوں کا ایک گچھا لے کر کہا: میں نے سوائے یہود کے کسی کو ایسا کرتے نہیں دیکھا ۱؎، اور رسول اللہ صلی اللہ علیہ وسلم تک جب یہ چیز پہنچی تو آپ نے اس کا نام دھوکا رکھا۔\n§وضاحت\n۱؎: یعنی: اپنے اصلی بالوں میں دوسرے کے بال جوڑنا یہودی عورتوں کا کام ہے، مسلمان عورتوں کو اس سے بچنا ضروری ہے۔","الألباني: صحيح",{"u2":"حضرت سعید بن مسیب سےر وایت ہے، انہوں نے فرمایا: سیدنا معاویہ رضی اللہ عنہ مدینہ آئے تو ہم سے خطاب فرمایا۔ انہوں نے بالوں کا ایک گچھا پکڑا اور فرمایا: میں نہیں سمجھتا کہ یہودیوں کے علاوہ اور کوئی شخص یہ کام کرتا ہو گا۔ رسول اللہ صلی اللہ علیہ وسلم کے سامنے اس کا تذکرہ ہوا تو آپ نے اسے ’’زور ‘‘ (جعل سازی) قرار دیا۔","f2":"الزور کے معنی ہیں:’’باطل، جھوٹ،جعل سازی ‘‘ وغیرہ۔ مذکورہ فعل کوزور کہنے کی وجہ بھی یہی ہے کہ یہ ایک فریب ہے کہ کسی دوسرے کے بال کوئی اپنےسر میں لگالے اور لوگوں کودکھائے کہ یہ میرے سر کے بال ہیں۔ یہ ناجائز ہے۔"}],[5247,"معاویہ رضی اللہ عنہ سے روایت ہے کہ انہوں نے کہا: لوگو! نبی اکرم صلی اللہ علیہ وسلم نے تمہیں جھوٹ اور فریب سے روکا ہے، راوی (ابن المسیب) کہتے ہیں: اور انہوں نے ایک کالا چیتھڑا نکالا پھر اسے ان کے سامنے رکھ دیا اور کہا: یہی ہے وہ (یعنی جھوٹ اور فریب کاری)، اسے عورت اپنے سر میں لگا کر دوپٹا اوڑھ لیتی ہے۱؎۔\n§وضاحت\n۱؎: اور لوگ یہ سمجھتے ہیں کہ اس عورت کے اپنے اصلی بال بڑے لمبے لمبے ہیں، اور لمبے بال عورتوں کی خوبصورتی میں شمار ہوتے ہیں، تو گویا غیر خوبصورت عورت خود کو مصنوعی ذریعے سے خوبصورت ظاہر کر کے اس کا فائدہ اٹھانا چاہتی ہے، یہ عمل اسلام کی نظر میں ناپسندیدہ ہے کیونکہ یہ دھوکا ہے۔","الألباني: صحيح الإسناد",{"u2":"سیدنا معاویہ رضی اللہ عنہ نے فرمایا: اے لوگو! نبی اکرم صلی اللہ علیہ وسلم نے تمہیں جعلی بال لگانے سے منع فرمایا ہے۔ پھر آپ ایک سیاہ رنگ کا کپڑ لائے اور لوگوں کے سامنے پھینکا اور فرمایا: یہ ہے وہ جعل سازی۔ عورت اسے اپنے بالوں میں لگاتی ہے۔ پھر اوپر سے اوڑھنی اوڑھ لیتی ہے۔","f2":"1۔ ’’خرق‘‘ اس کا مفرد خرقۃ ہے،یعنی دھجی (کپڑے کی لمبی پٹی)۔\n2۔ ’’اوڑھ لیتی ہے ‘‘ تاکہ جعل سازی کاپتا نہ چلے اور بال زیادہ محسوس ہوں۔ اس حدیث سے معلوم ہوا کہ بالوں میں کسی چیز کا اضافہ درست نہیں خواہ دوسری چیز بال ہوں یا کپڑے کے ٹکڑے جن سے کسی کو بالوں کی کثرت کا دھوکا دیا جاسکے۔ البتہ بالوں کوقابو کرنے کے لیے دھاگے وغیرہ کا پر اندہ استعمال کیا جاسکتا ہے خواہ وہ سیاہ ہی ہو کیونکہ اس سے دھوکا دہی نہیں ہوتی۔ وہ سر پر نہیں ہوتا کہ کثرت کاگمان ہو بلکہ وہ پشت پر لٹکتا ہے نیز اسے دیکھنے سے صاف پتا چلتا ہے کہ یہ بال نہیں دھاگا ہے۔\n3۔ اس حدیث کا ترجمہ ایک اورانداز سے بھی ممکن ہے کہ ’’آپ سیاہ رنگ کا کپڑالائے اور لوگوں کے سامنے پھینکا اور فرمایا: اسے عورت اپنے بالوں میں لگاسکتی ہے۔ اوپر سے اوڑھنی اور‎ڑھ لے۔ ‘‘ اس صورت میں سیاہ رنگ کے کپڑے سے مراد پراندہ ہی ہے کہ اس کا استعمل جائز ہے۔ حدیث کا مقصد یہ ہو گا کہ جعلی بال ملانے درست نہیں کیونکہ ان سے دھوکا دہی ہوتی ہے۔ البتہ کپڑایاپراندہ وغیرہ لگالیا جائے تاکہ بال منتشر نہ ہوں اور انہیں اس کے ساتھ باندھ لیا جائے تو کوئی حرج نہیں کیونکہ کپڑے کے ساتھ جعل سازی ممکن نہیں۔ وہ دور ہی سے بالوں سے مختلف نظر آتا ہے اور اس کا مقصد بھی سمجھ میں آتا ہے۔ پہلا ترجمہ الفاظ کے زیادہ قریب ہے۔ واللہ اعلم ."}],[5248,"معاویہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے جھوٹ اور فریب کاری سے منع فرمایا، اور جھوٹ اور فریب کاری یہ ہے کہ عورت (بال زیادہ دکھانے کے لیے) سر پر کچھ لپیٹ لے۔","الألباني: صحيح",{"u2":"سیدنا معاویہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے جعل سازی سے منع فرمایا۔ اور جعل سازی یہ ہے کہ عورت اپنےسرپر (جعلی بال وغیرہ) لپیٹ لے۔","f2":"’’لپیٹ لے‘‘ تاکہ زیادہ معلوم ہوں۔ مقصد دوسروں کو دھوکا دینا ہوتا ہے یا اپنے حسن میں اضافہ اور یہ دونوں چیزیں منع ہیں۔ دھوکا دہی بھی اور تکلف کے ساتھ حسن میں اضافہ بھی۔"}],[5249,"سالم بن عبداللہ بیان کرتے ہیں کہ عبداللہ بن عمر رضی اللہ عنہما اپنی زمین کرائے پر اٹھاتے تھے، یہاں تک کہ انہیں معلوم ہوا کہ رافع بن خدیج رضی اللہ عنہ زمین کو کرائے پر اٹھانے سے روکتے ہیں، تو عبداللہ بن عمر رضی اللہ عنہما نے ان سے ملاقات کی اور کہا: ابن خدیج! زمین کو کرائے پر اٹھانے کے بارے میں آپ رسول اللہ صلی اللہ علیہ وسلم سے کیا نقل کرتے ہیں؟ تو رافع رضی اللہ عنہ نے عبداللہ بن عمر رضی اللہ عنہما سے کہا: میں نے اپنے دو چچاؤں کو (کہتے) سنا (ان دونوں نے بدر میں شرکت کی تھی) وہ دونوں گھر والوں سے بیان کر رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے زمین کو کرائے پر اٹھانے سے روکا ہے۔ عبداللہ بن عمر رضی اللہ عنہما نے کہا: میں تو رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں جانتا تھا کہ زمین کرائے پر اٹھائی جا سکتی ہے، پھر عبداللہ بن عمر رضی اللہ عنہما کو خوف ہوا کہ کہیں رسول اللہ صلی اللہ علیہ وسلم نے اس سلسلے میں کوئی ایسی نئی بات کہی ہو گی جسے وہ نہ جان سکے ہوں، چنانچہ انہوں نے زمین کو کرائے پر اٹھانا چھوڑ دیا۔ اسے شعیب بن ابی حمزہ نے مرسلاً روایت کیا ہے ۱؎۔\n§وضاحت\n۱؎: شعیب نے اپنی روایت میں یوں کہا ہے: «عن الزھری قال بلغنا أن رافع بن خدیج» جب کہ آگے روایت آ رہی ہے۔\nرافع بن خدیج رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"کیا تم اپنے کھیتوں کو اجرت پر دیتے ہو؟\" میں نے عرض کیا: جی ہاں، اللہ کے رسول! ہم انہیں چوتھائی اور کچھ وسق جو پر بٹائی دیتے ہیں۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایسا نہ کرو، ان میں کھیتی کرو یا عاریتاً کسی کو دے دو، یا اپنے پاس رکھو\"۔ اوزاعی نے یحیی بن ابی کثیر کی مخالفت کی ہے اور «عن رافع عن ظہیر بن رافع» کہا ہے۔\nعبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے یہود خیبر کو خیبر کے باغات اور اس کی زمین اس شرط پر دی کہ وہ اپنے خرچ پر اس میں کام کریں گے اور رسول اللہ صلی اللہ علیہ وسلم کے لیے اس کے پھل کا آدھا ہو گا۔\nنافع سے روایت ہے کہ عبداللہ بن عمر رضی اللہ عنہما کہا کرتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں کھیت بٹائی پر دیے جاتے تھے اس شرط پر کہ زمین کے مالک کے لیے وہ پیداوار ہو گی جو نالیوں اور نہروں کی کیاریوں پر ہو اور کچھ گھاس جس کی مقدار مجھے معلوم نہیں۔\nابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: مجھے حکم دیا گیا ہے کہ میں لوگوں سے اس وقت تک جنگ کروں جب تک کہ وہ \"لا الٰہ الا اللہ\" نہ کہیں، جب وہ لوگ یہ کہنے لگیں تو اب انہوں نے اپنے خون، اپنے مال کو مجھ سے محفوظ کر لیا مگر (جان و مال کے) حق کے بدلے، اور ان کا حساب اللہ پر ہے، پھر جب «ردت» کا واقعہ ہوا (مرتد ہونے والے مرتد ہو گئے) تو عمر رضی اللہ عنہ نے ابوبکر رضی اللہ عنہ سے کہا: کیا آپ ان سے جنگ کریں گے حالانکہ آپ نے رسول اللہ صلی اللہ علیہ وسلم کو ایسا اور ایسا فرماتے سنا ہے؟ تو وہ بولے: اللہ کی قسم! میں نماز اور زکاۃ میں تفریق نہیں کروں گا، اور میں ہر اس شخص سے جنگ کروں گا جو ان کے درمیان تفریق کرے گا، پھر ہم ان کے ساتھ لڑے اور اسی چیز کو ہم نے ٹھیک اور درست پایا۔ ابوعبدالرحمٰن نسائی کہتے ہیں: زہری سے روایت کرنے والے سفیان قوی نہیں ہیں اور ان سے مراد سفیان بن حسین ہیں ۱؎۔\n§وضاحت\n۱؎: لیکن متابعات سے تقویت پا کر یہ روایت بھی صحیح ہے۔\nابوہریرہ رضی اللہ عنہ فرماتے ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم کی وفات ہوئی اور آپ کے بعد ابوبکر رضی اللہ عنہ خلیفہ ہوئے اور عرب کے جن لوگوں نے کفر (ارتداد) کی گود میں جانا تھا چلے گئے تو عمر رضی اللہ عنہ نے کہا: ابوبکر! آپ لوگوں سے کیسے جنگ کریں گے؟ حالانکہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے:\"مجھے حکم دیا گیا ہے کہ میں لوگوں سے اس وقت تک جنگ کروں جب تک کہ وہ \"لا الٰہ إلا اللہ\" نہ کہیں، تو جس نے \"لا الٰہ الا اللہ\" کہا اس نے مجھ سے اپنا مال، اپنی جان محفوظ کر لیا، مگر (جان و مال کے) حق کے بدلے میں، اور اس کا حساب اللہ پر ہے\"۔ ابوبکر رضی اللہ عنہ بولے: میں ہر اس شخص سے ضرور لڑوں گا جو نماز اور زکاۃ میں تفریق کرے گا کیونکہ زکاۃ یقیناً مال کا حق ہے، اللہ کی قسم! اگر ان لوگوں نے بکری کا ایک بچہ بھی مجھے دینے سے روکا جسے یہ رسول اللہ صلی اللہ علیہ وسلم کو دیتے تھے تو میں اس کے روکنے پر ان سے جنگ کروں گا۔ عمر رضی اللہ عنہ کہتے ہیں: اللہ کی قسم! اس کے سوا کچھ نہ تھا کہ میں نے دیکھا کہ اللہ تعالی نے ابوبکر رضی اللہ عنہ کے سینے کو جنگ کے لیے کھول دیا ہے، تو میں نے جان لیا کہ یہی حق ہے۔\nابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہم لوگوں سے اس وقت تک جنگ کریں گے جب تک کہ وہ لا الٰہ الا اللہ نہ کہیں، جب وہ لا الٰہ الا اللہ کہہ لیں تو ہم پر ان کے خون اور ان کے مال حرام ہو گئے مگر اس کے (جان و مال کے) حق کے بدلے، اور ان کا حساب اللہ تعالی پر ہے\"۔\nایک شخص ۱؎ کہتے ہیں کہ ہمارے پاس رسول اللہ صلی اللہ علیہ وسلم آئے اور ہم مدینے کی مسجد کے ایک خیمے میں تھے، وہاں آپ نے فرمایا: \"میرے پاس وحی آئی ہے کہ میں لوگوں سے اس وقت تک جنگ کروں جب تک کہ وہ \"لا الٰہ الا اللہ\" نہ کہیں … آگے حدیث اسی طرح ہے جیسی اوپر گزری۔\n§وضاحت\n۱؎: یہ شخص صحابی رسول صلی اللہ علیہ وسلم \" اوس بن ابی اوس حذیفہ ثقفی \" رضی اللہ عنہ ہیں، ان کے نام کی صراحت اگلی روایتوں میں آ رہی ہے۔\nجندب رضی اللہ عنہ کہتے ہیں کہ مجھ سے فلاں (صحابی) نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"قیامت کے روز مقتول اپنے قاتل کو لے کر آئے گا اور کہے گا: (اے اللہ!) اس سے پوچھ، اس نے کس وجہ سے مجھے قتل کیا؟ تو وہ کہے گا: میں نے اس کو فلاں کی سلطنت میں قتل کیا\"۔ جندب کہتے رضی اللہ عنہ ہیں: تو اس سے بچو ۱؎۔\n§وضاحت\n۱؎: یعنی اس طرح کے عذر لنگ والے جواب کی نوبت آنے سے بچو، یعنی تم کو اللہ کے پاس اس طرح کے جواب دینے کی نوبت نہ آئے، یہ خیال رکھو۔\nابوامامہ بن سہل اور عبداللہ بن عامر بن ربیعہ بیان کرتے ہیں کہ ہم عثمان رضی اللہ عنہ کے ساتھ تھے اور وہ (اپنے گھر میں) قید تھے۔ ہم جب کسی جگہ سے اندر گھستے تو بلاط ۱؎ والوں کی گفتگو سنتے۔ ایک دن عثمان رضی اللہ عنہ اندر گئے پھر باہر آئے اور بولے: یہ لوگ مجھے قتل کی دھمکی دے رہے ہیں۔ ہم نے کہا: آپ کے لیے تو اللہ کافی ہے۔ وہ بولے: آخر یہ لوگ مجھے کیوں قتل کرنے کے درپہ ہیں؟ حالانکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا ہے: \"کسی مسلمان شخص کا خون حلال نہیں مگر تین میں سے کسی ایک سبب سے: کسی نے اسلام لانے کے بعد کافر و مرتد ہو گیا ہو، یا شادی شدہ ہونے کے بعد زنا کیا ہو، یا ناحق کسی کو قتل کیا ہو\"، اللہ کی قسم! نہ تو میں نے جاہلیت میں زنا کیا، اور نہ اسلام لانے کے بعد، اور جب سے مجھے اللہ تعالی کی طرف سے ہدایت نصیب ہوئی میں نے یہ آرزو بھی نہیں کی کہ میرے لیے اس دین کے بجائے کوئی اور دین ہو، اور نہ میں نے ناحق کسی کو قتل کیا، تو آخر یہ مجھے کیوں کر قتل کریں گے؟۔\n§وضاحت\n۱؎: بلاط: مسجد نبوی اور بازار کے درمیان مدینہ میں ایک جگہ کا نام تھا۔ بلاط: دراصل ایسی خالی جگہ کو کہتے ہیں جس میں اینٹ بچھائی گئی ہو۔ اس جگہ اینٹ بچھائی گئی تھی، پھر اس مکان کا یہی نام پڑ گیا۔\nعبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بال جوڑنے کا کام کرنے والی پر لعنت فرمائی ہے۔","الألباني: صحيح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے جعلی بال لگانے والی عورت پر لعنت فرمائی۔","f2":"کسی برے کام یا وصف پر لعنت کرنا جائز ہے البتہ کسی معین شخص پر لعنت کرنا جائز نہیں الا یہ کہ وہ صریح کفر ہو یا اللہ اور اس کے رسول نے اس پر لعنت کی ہو جیسے ﴿ تَبَّت يَدا أَبي لَهَبٍ وَتَبَّ ﴾ (اللھب 111:1)"}],[5250,"اسماء رضی اللہ عنہا سے روایت ہے کہ ایک عورت نے رسول اللہ صلی اللہ علیہ وسلم کے پاس آ کر کہا: اللہ کے رسول! میری ایک بیٹی نئی نویلی دلہن ہے، اسے ایک بیماری ہو گئی ہے کہ اس کے بال جھڑ رہے ہیں اگر میں اس کے بال جوڑوا دوں تو کیا مجھ پر گناہ ہو گا؟ آپ نے فرمایا: \"بال جوڑنے اور جوڑوانے والی عورتوں پر اللہ تعالی نے لعنت کی ہے\"۔","الألباني: صحيح",{"u2":"سیدہ اسماء رضی اللہ عنہا سے مروی ہے کہ ایک عورت رسول اللہ صلی اللہ علیہ وسلم کے پاس آئی اور کہا: اے اللہ کے رسول! میری ایک بیٹی کی شادی تازہ تازہ ہوئی ہو۔ وہ بیمار ہو گئی اور اس کے بال جھڑ گئے۔ اگر میں ان میں مصنوعی بالوں سے اضافہ کرلوں تو کیا میں گناہ گار ہوں گی؟ آپ نے فرمایا: ’’اللہ تعالیٰ نے مصنوعی بال لگاانے والی اور لگوانے والی دونوں پر لعنت فرمائی ہے۔‘‘","f2":"معلوم ہوا گنجی عورت بھی بال نہیں لگاسکتی کیونکہ اس میں بھی دھوکا دہی پائی جاتی ہے نیز غیر ضروری تکلیف پایا جاتا ہے کیونکہ کم بالوں کے ساتھ بھی گزارا ہو سکتا ہے لیکن مصنوعی دانت اعضاء اور لینز وغیرہ لگوائے جاسکتے ہیں کیونکہ ان کے بغیر گزارا نہیں ہوتا۔"}],[5251,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے بال جوڑنے اور جوڑوانے والی عورت پر اور گودنے اور گودانے والی عورت پر لعنت فرمائی۔","الألباني: صحيح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے مصنوعی بال لگانے والی، لگوانے والی، رنگ بھر نے والی اور بھروانے والی عورتوں پر لعنت فرمائی ہے","f2":"حسن کی خاطر جسم کے بعض حصوں کو سوئی سے چھید کر سرمہ یا کوئی اور رنگ بھرا جاتا تھا۔ ظاہر ہے کہ یہ اپنے آپ کوعذاب میں ڈالنا نیز غیر ضروری تکلف ہے لہذا منع ہے۔ (دیکھیے حدیث:5094)"}],[5252,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ چہرہ کے روئیں اکھاڑنے والی اور دانتوں کو کشادہ کرنے والی عورتوں پر اللہ نے لعنت فرمائی ہے، کیا میں اس پر لعنت نہ بھیجوں جس پر رسول اللہ صلی اللہ علیہ وسلم نے لعنت بھیجی ہے۔","الألباني: صحيح",{"u2":"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ نے فرمایا: اللہ تعالیٰ نے بال اکھیڑنے والی اور دانت کھلے کرنے والی عورتوں پرلعنت فرمائی ہے۔ میں اس پر کیوں لعنت نہ کروں جس پر رسول ا للہ صلی اللہ علیہ وسلم نے لعنت فرمائی ہے۔","f2":"تفصیل کے لیے دیکھیے احادیث: 5102اور 5110۔"}],[5253,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے (جسم پر) گودنا گودنے والی، خوبصورتی کے لیے دانتوں کے درمیان کشادگی کروانے والی، پیشانی کے بال اکھاڑنے والی اور اللہ کی بنائی ہوئی چیز کو بدلنے والی عورتوں پر لعنت فرمائی۔","الألباني: صحيح",{"u2":"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ سے روایت ہے انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے رنگ بھرنے والی، دانت کھلے کرنے والی اور بال اکھیڑنے والی عورتوں پر لعنت فرمائی ہے جو اللہ عزوجل کی پیدا کردہ شکل وصورت کو بدلتی ہیں۔","f2":"تفصیل کےلیے دیکھیے حدیث: 5112۔"}],[5254,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ اللہ تعالی نے چہرہ کے بال اکھاڑنے والی، دانتوں میں کشادگی کرنے والی، گودنا گودانے والی اور اللہ کی فطرت کو تبدیل کرنے والی عورتوں پر لعنت فرمائی ہے، چنانچہ ایک عورت ان کے پاس آ کر کہا: آپ ہی ایسا ایسا کہتے ہیں؟ وہ بولے: آخر میں وہ بات کیوں نہ کہوں جو رسول اللہ صلی اللہ علیہ وسلم نے کہی ہے۔","الألباني: صحيح لغيره",{"u2":"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ نے فرمایا:اللہ تعالیٰ نے بال اکھیڑنے والی، دانتوں کو کھلا کرنے والی اور رنگ بھروانے والی عورتوں پر لعنت فرمائی ہے جواللہ تعالیٰ کی بنائی ہوئی صورت کو بدلتی ہیں۔ ایک عورت ان کے پاس آئی اور کہا: آپ ایسی ایسی باتیں کرتے ہیں؟ انہوں نے کہا میں وہ بات کیوں نہ کہوں جو رسول صلی اللہ علیہ وسلم نے فرمائی ہو؟"}],[5255,"عبداللہ بن مسعود رضی اللہ عنہ کہتے تھے کہ گودنا گودانے والی، چہرے کے بال اکھاڑنے والی اور دانتوں کے درمیان کشادگی کرانے والی عورتوں پر اللہ تعالی نے لعنت فرمائی ہے۔ کیا میں اس پر لعنت نہ بھیجوں جس پر رسول اللہ صلی اللہ علیہ وسلم نے لعنت بھیجی ہے۔","الألباني: صحيح",{"u2":"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ نے فرمایاکرتے تھے:اللہ تعالیٰ نے رنگ بھروانے والی اور بہ تکلف بال اکھیڑنے والی، دانت کھلے کرنےوالی عورتوں پر لعنت فرمائی ہے۔ میں اس پر کیوں نہ لعنت کروں جس پر رسول اللہ نے لعنت فرمائی ہے۔"}],[5256,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مردوں کو زعفرانی رنگ لگانے سے منع فرمایا ہے۔","الألباني: صحيح",{"u2":"سیدنا انس رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے مرد کو زعفران لگانے سے منع فرمایا ہے۔","f2":"مرد کے لیے اپنے جسم کو زعفران لگانے متفقہ حرام ہے۔ ڈاڑھی کو لگانا متفقہ حلال ہے اور کپڑوں کولگانا مختلف فیہ ہے۔ عورتوں کےلیے جسم میں بھی جائز ہے اور کپڑوں میں بھی۔"}],[5257,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مردوں کو بدن پر زعفرانی رنگ لگانے سے منع فرمایا۔","الألباني: ضعيف الإسناد",{"u2":"سیدنا انس رضی اللہ عنہ نے فرمایا: رسو ل اللہ نے منع فرمایا کہ مرد اپنے جسم کوزعفران لگائے۔","f2":"زعفران رنگ والی خوشبو ہے اور مرد کے لیے رنگ والی خوشبو حرام ہے۔ عورت کےلیے جائز ہے۔"}],[5258,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کے پاس جب بھی خوشبو لائی گئی، آپ نے اسے لوٹایا نہیں۔","الألباني: صحيح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ نے فرمایا کہ نبی اکرم صلی اللہ علیہ وسلم کے پاس جب خوشبو کا تحفہ لایا جاتا توآپ اسے رد نہیں فرماتے تھے۔","f2":"1۔ اس حدیث سے معلوم ہوا کہ خوشبو استعمال کرنا پسندیدہ عمل ہے نیز کوئی شخص خوشبو کا ہدیہ دے تو اسے قبول کر لینا چاہیے رد نہیں کرنا چاہیے۔ ایک دوسری حدیث میں خوشبو کےساتھ دو اور چیزوں کا بھی ذکر ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: [ثلاث لا ترد: الوسائد والدهن واللبن] الدهن: يعنى به الطيب] (جامع الترمذى، الأدب،حديث:2790)’’تین چیزوں ایسی ہیں کہ (کسی کو ہدیتاً دی جائیں تو) وہ ردنہ کی جائیں: سرہانہ و تکیہ (گدوغالیچہ) تیل اور دودھ۔ ‘‘ امام ترمذی فرماتے ہیں کہ تیل سے مراد خوشبو ہے۔\n2۔ رسول اللہ صلی اللہ علیہ وسلم کو خوشبو سے خصوصی لگاؤ تھا کیونکہ آپ کے پاس فرشتوں کا آنا جانا رہتا تھا فرشتے بدبو سے نفرت کرتے ہیں اس لیے رسول اللہ صلی اللہ علیہ وسلم ہر وقت بہترین خوشبو سےمعطر رہتے تھے۔ خود آپ کا جسم مبارک بھی ذاتی طور پر خوشبو دار تھا۔ فداء ابی ونفسی وروحی صلی اللہ علیہ وسلم"}],[5259,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جسے خوشبو پیش کی جائے وہ اسے نہ لوٹائے کیونکہ وہ اٹھانے میں ہلکی اور سونگھنے میں اچھی ہوتی ہے\"۔","الألباني: صحيح",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کسی کو خوشبو پیش کی جائے تو وہ اسے رد نہ کرے اس لیے کہ یہ اٹھانے میں ہلکی اورمہک میں پاکیزہ ہے۔ ‘‘","f2":"1۔ کوئی بھی تحفہ رد نہیں کرنا چاہیے کیونکہ اس سے اللہ تعالیٰ کی نعمت کی ناشکری اور تحفہ پیش کرنے والے کی دل شکنی ہوگی الا یہ کہ تحفہ دینے والا عوض لینے کی نیت سے تحفہ دے اور تحفہ لینےوالا دینے کی استطاعت نہ رکھتا ہو۔ خوشبو معمولی چیز ہے۔ اس کا عوض دینا بھی آسان ہے۔ اٹھانے میں ہلکی کے یہ معنی بھی ہو سکتے ہیں کہ اس کا معاوضہ دینا آسان ہے نیز یہ کوئی بہت بڑا احسان نہیں کہ دوسرا آدمی زیر بار ہو جائے لہذا خوشبو کا تحفہ لے لینا چاہیے۔\n2۔ حدیث سے ضمنامعلوم ہوا کہ تحفہ قلیل بھی ہو تو دینے یا لینے میں شرک محسوس نہیں کرنی چاہیے نیز کسی بھی تحفے کو حقیر نہیں سمجھنا چاہیے اور نہ رد کرنا چاہیے۔"}],[5260,"عبداللہ بن مسعود رضی اللہ عنہ کی بیوی زینب رضی اللہ عنہما کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم (عورتوں) میں سے کوئی جب عشاء کو آئے تو خوشبو نہ لگائے\"۔","الألباني: حسن صحيح",{"u2":"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ کی زوجہ محترمہ سیدہ زینت رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کوئی عورت عشاء کی نماز پڑھنے مسجد کو جائے تو کسی قسم کی خوشبو نہ لگائے۔‘‘","f2":"گویا گھر کے اندر اپنے خاوند کے سامنے خوشبو لگاسکتی ہے۔ طیب سے مراد زینت بھی ہو سکتی ہے کہ مسجد کو جاتے وقت زینت بھی نہ لگائے بلکہ شادہ حالت اور سادہ کپڑوں میں جائے تاکہ کسی کے لیے فتنے کا باعث نہ ہو۔ (تفصیل کےلیے دیکھیے احادیث:5130سے 5135۔)"}],[5261,"عبداللہ بن مسعود رضی اللہ عنہ کی بیوی زینب ثقفیہ رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے ان سے فرمایا: \"تم جب عشاء کے لیے نکلو تو خوشبو نہ لگاؤ\"۔","الألباني: صحيح",{"u2":"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ کی بیوی سیدہ زینب ثقفیہ رضی اللہ عنہا نے بتایا کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے فرمایا: ’’جب تو عشاء کی نماز پڑھنے مسجد میں جائے تو خوشبو وغیرہ نہ لگایا کر۔‘‘"}],[5262,"زینب ثقفیہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تم (عورتوں) میں سے جو کوئی مسجد کو جائے تو وہ خوشبو کے نزدیک بھی نہ جائے\"۔","الألباني: صحيح",{"u2":"سیدہ زینب ثقفیہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’تم میں سے عورت بھی مسجد کو جائے وہ خوشبو کے قریب بھی نہ جائے۔‘‘","f2":"جب مسجد میں جاتے وقت خوشبو کی اجازت نہیں حالانکہ وہ مقدس جگہ ہے تو بازار یا لوگوں کے گھروں یا کھیتوں میں جاتے وقت خوشبو کی اجازت کیسے ہو سکتی ہے؟"}],[5263,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو عورت (خوشبو کی) دھونی لے تو وہ ہمارے ساتھ عشاء کے لیے نہ آئے\"۔","الألباني: صحيح",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ جوعورت بھی خوشبو لگائے وہ ہمارے ساتھ عشاء کی نماز پڑھنے نہ آئے۔‘‘","f2":"تفصیل کےلیے دیکھیے حدیث: 5131۔"}],[5264,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے ایک عورت کا ذکر کیا، اس نے اپنی انگوٹھی میں مشک بھر رکھی تھی، آپ صلی اللہ علیہ وسلم نے فرمایا: \"وہ سب سے عمدہ خوشبو ہے\" ۱؎۔\n§وضاحت\n۱؎: لیکن ایسی انگوٹھی پہن کر شوہر کے گھر سے باہر نہ نکلے، جیسا کہ دیگر حدیثوں سے معلوم ہوا۔","الألباني: صحيح",{"u2":"سیدنا ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے ایک عورت کا ذکر فرمایا جس نے اپنی انگوٹھی کوکستوری سے بھر رکھا تھا۔پھرآپ نے فرمایا: ’’یہ سب سے اچھی اور پاکیزہ خوشبو ہے۔ ‘‘","f2":"1۔ انگوٹھی کے نگ میں کستوری بھری ہو گی۔ ممکن ہے ساری انگوٹھی کھوکھلی ہو۔ یہ عورت نبی اسرائیل میں سے تھی۔\n2۔ اگر عورت نے گھر میں باہر جانا ہو تو ایسی (خوشبو والی) انگوٹھی پہن کر نہیں جاسکتی۔ گھر کے اندر پہن سکتی ہے۔\n3۔ اس عورت کا ذکر بطور تعریف بھی ہو سکتا ہے اور بطور مذمت بھی۔ تعریف اور مذمت استعمال کے لحاظ سے ہے۔"}],[5265,"ابوموسی اشعری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی نے میری امت کی عورتوں کے لیے ریشم اور سونا حلال کیا، اور ان دونوں کو اس کے مردوں کے لیے حرام کیا\"۔","الألباني: صحيح",{"u2":"سیدنا ابو موسیٰ رضی اللہ عنہ سےروایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ عزوجل نے ریشم اور سونا میری امت کی عورتون کے لیے حلال قرار فرمایا ہے اور مردوں کے لیے حرام ہے۔ ‘‘","f2":"عورتوں کےلیے سونا پہننا حلال ہےمگر سونا چاندی کے برتنوں کا استعمال مرد وعورت سب کےلیے منع ہے کیونکہ یہ قطعاً غیر ضروری ہے اور سوائے فخر و نمائش کے اس کا کوئی مقصد نہیں۔ نہیں زیورات بھی صرف زینت کی حد تک عورت استعمال کر سکتی ہے فخر و مباہات کے لیے نہیں۔ (تفصیل کےلیے دیکھیے احادیث: 5139سے 5146تک۔)"}],[5266,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ مجھے لال کپڑے، سونے کی انگوٹھی اور رکوع کی حالت میں قرآن پڑھنے سے منع کیا گیا ہے۔\n§وضاحت\n۱؎: اس سند میں \" علی رضی اللہ عنہ \" کا ذکر نہیں ہے، جب کہ اکثر روایات میں اس حدیث کو ابن عباس رضی اللہ عنہما نے علی رضی اللہ عنہ سے روایت کیا ہے جیسا کہ متعدد سن دوں سے گزرا، نیز دیکھئیے اگلی حدیث۔ اسی لیے امام مزی نے ابن عباس کی علی سے روایت کو محفوظ کہا ہے۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابن عباس نے فرمایا نے فرمایا: مجھے سرخ کپڑے سونے کی انگوٹھی اور رکوع کی حالت میں قرآن مجید پڑھنے سے منع کیا گیا۔","f2":"’’سرخ کپڑا ‘‘ بعض محققین کا قول ہے کہ مرد کے لیے خالص سرخ کپڑا پہننا منع ہے۔ صرف سرخ دھاریاں ہوں تو کوئی حرج نہیں۔ یامطلق سرخ مراد نہیں بلکہ معصفر اور مزعفر مراد ہیں جن کی حرمت کا ذکر دوسری احادیث میں ہے۔ سرخ کی باقی اقسام جائز ہیں۔ واللہ اعلم۔ (باقی تفصیل کے لیے دیکھیے حدیث:5175)"}],[5267,"علی رضی اللہ عنہ کہتے ہیں کہ مجھے نبی اکرم صلی اللہ علیہ وسلم نے سونے کی انگوٹھی سے اور رکوع کی حالت میں قرآن پڑھنے سے، ریشم اور زرد رنگ کے کپڑے سے منع فرمایا۔","الألباني: حسن صحيح",{"u2":"سیدنا علی رضی اللہ عنہ نے فرمایا: مجھے نبی اکرم صلی اللہ علیہ وسلم نے سونے کی انگوٹھی پہننے رکوع کی حالت میں قرآن پڑھنے قسی اورمعصفر کپڑے پہننے سے منع فرمایا۔","f2":"دیکھیے احادیث: 5168، 5175۔"}],[5268,"علی رضی اللہ عنہ کہتے ہیں کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے سونے کی انگوٹھی سے، ریشم اور زرد رنگ کے کپڑے پہننے سے اور رکوع کی حالت میں قرآن پڑھنے سے منع فرمایا۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے مجھے سونے کی انگوٹھی قسی اور معصفر کے لباس پہننے اور رکوع کی حالت میں قرآن مجید پڑھنے سے روکا ہے۔"}],[5269,"۱؎: یعنی شعیب کی موافقت کی ہے اور یہ موافقت اس طرح ہے کہ زھری اور رافع کے درمیان سالم کا ذکر نہیں ہے جب کہ مالک اور عقیل نے سالم کا ذکر کیا ہے۔شرافع بن خدیج رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے زمین کرائے پر دینے سے منع فرمایا۔ زہری کہتے ہیں: اس کے بعد رافع رضی اللہ عنہ سے پوچھا گیا: وہ لوگ زمین کو کرائے پر کیوں کر اٹھاتے تھے؟ وہ بولے: غلے کی متعینہ مقدار کے بدلے میں اور اس بات کی شرط ہوتی تھی کہ ہمارے لیے وہ بھی ہو گا جو زمین میں کیاریوں اور نالیوں پر پیدا ہوتا ہے۔ اسے نافع نے بھی رافع بن خدیج رضی اللہ عنہ سے روایت کیا ہے اور اس کی روایت میں ان کے شاگردوں میں اختلاف ہوا ہے۔\nابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: مجھے حکم دیا گیا ہے کہ میں لوگوں سے اس وقت تک جنگ کروں جب تک کہ وہ \"لا الٰہ الا اللہ\" نہ کہیں، چنانچہ جس نے \"لا الٰہ الا اللہ\" کہہ لیا اس نے مجھ سے اپنا مال اور اپنی جان محفوظ کر لیا مگر (جان و مال کے) حق کے بدلے، اور اس کا حساب اللہ پر ہے۔ شعیب بن ابی حمزہ نے اپنی روایت میں دونوں حدیثوں کو جمع کر دیا ہے (یعنی: واقعہ ردت اور مرفوع حدیث)۔\nعلی رضی اللہ عنہ کہتے ہیں کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے رکوع کی حالت میں قرآن پڑھنے سے روکا۔","الألباني: صحيح لغيره",{"u2":"سیدنا علی رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے مجھے رکوع کےدوران میں قرآن مجید پڑھنے سےمنع فرمایا۔"}],[5270,"علی رضی اللہ عنہ بیان کرتے ہیں کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے زرد رنگ کے کپڑے سے، سونے کی انگوٹھی سے، ریشم کے کپڑے سے اور رکوع کی حالت میں قرآن پڑھنے سے روکا۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے کسم سےرنگے ہوئے کپڑے سونے کی انگوٹھی قسی کپڑے کےلباس پہننے اوررکوع کی حالت میں قرآن پڑھنے سے منع فرمایا ہے۔"}],[5271,"علی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے چار باتوں سے روکا: پیلے رنگ کا کپڑا پہننے سے، سونے کی انگوٹھی پہننے سے، ریشمی کپڑے پہننے سے، اور رکوع کی حالت میں قرآن پڑھنے سے۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے مجھے چار چیزوں سے منع فرمایا ہے: معصفر کپڑا پہننے سونے کی انگوٹھی پہننے قس بستی کے بنے ہوئے کپڑے پہنے اور رکوع کی حالت میں قرآن پڑھنے سے۔"}],[5272,"علی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے پیلے رنگ کے کپڑے، اور ریشم کے استعمال سے، رکوع کی حالت میں قرآن پڑھنے سے اور سونے کی انگوٹھی (پہننے) سے منع فرمایا۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے معفر کپڑے اورریشم پہننے دوران رکوع میں قرآن پڑھنے اور سونے کی انگوٹھی پہننے سے منع فرمایا ہے۔"}],[5273,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے سونے کی انگوٹھی پہننے سے منع فرمایا۔","الألباني: صحيح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے سونے کی انگوٹھی پہننے سےمنع فرمایا۔"}],[5274,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ قیامت کے روز سب سے پہلے لوگوں کے درمیان خون کا فیصلہ کیا جائے گا۔\nابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سونے کی انگوٹھی پہننے سے منع فرمایا۔","الألباني: صحيح موقوف وهو في حكم المرفوع",{"u2":"حضرت ابوہرہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سونے کی انگوٹھی پہننے سے منع فرمایا۔","f2":"مندرجہ بالا چیزوں سے نہی صرف حضرت علی سے خاص نہیں امت کے تمام مردوں کے لیے ہے۔ تفصیل کےلیے دیکھیے: 5175۔"}],[5275,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سونے کی انگوٹھی بنوائی، پھر اسے پہنا تو لوگوں نے بھی سونے کی انگوٹھیاں بنوائیں، آپ نے فرمایا: \"میں اس انگوٹھی کو پہن رہا تھا، لیکن اب میں اسے کبھی نہیں پہنوں گا\"، چنانچہ آپ نے اسے پھینک دی، تو لوگوں نے بھی اپنی انگوٹھیاں پھینک دیں۔","الألباني: صحيح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ نے فرمایا: رسو ل اللہ صلی اللہ علیہ وسلم نے سونے کی انگوٹھی بنوائی اور اسے اپنے دست مبارک میں پہنا۔ لوگوں نے بھی سونے کی انگوٹھیاں بنوا لیں تو رسول اللہ نے فرمایا: ’’میں یہ انگوٹھی پہنا کرتا تھا لیکن اب اسے ہرگز نہیں پہنوں گا۔ ‘‘ پھر آپ نے وہ انگوٹھی اتار پھینکی۔ لوگوں نے بھی اپنی انگوٹھیاں اتار پھینکیں۔","f2":"اتار پھینکنے کا مطلب یہ بھی ہوسکتا ہے انہیں بانداز نفرت اتار لیا اور آئندہ کبھی نہ پہننے کا عزم کرلیا تو یوں سمجھوں پھینک دیا۔ یہ لفظ نفرت پر دلالت کرتا ہے۔ واللہ اعلم۔"}],[5276,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کی انگوٹھی کا نقش «محمد رسول اللہ» تھا۔","الألباني: صحيح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ نے فرمایا: رسول اللہ کی انگوٹھی (کے نگینے) میں’’ محمد رسول اللہ‘‘ منقش تھا۔"}],[5277,"انس رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے چاندی کی انگوٹھی بنوائی، اس کا نگینہ حبشہ کا بنا ہوا تھا، اور اس پر «محمد رسول اللہ» نقش تھا۔","الألباني: صحيح",{"u2":"۔ سیدنا انس رضی اللہ عنہ فرماتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے چاندی کی انگوٹھی بنوائی۔ اس کا نگینہ حبشی انداز کا تھا اور اس پرب ’’محمد رسول اللہ‘‘ نقش کیا گیا تھا۔","f2":"تفصیل کے لیے دیکھیے حدیث:5199۔"}],[5278,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے شاہ روم کو خط لکھنے کا ارادہ کیا تو لوگوں نے کہا: وہ ایسی کوئی تحریر نہیں پڑھتے جس پر مہر نہ ہو، چنانچہ آپ نے چاندی کی انگوٹھی بنوائی، گویا میں آپ کے ہاتھ میں اس کی سفیدی کو (اس وقت بھی) دیکھ رہا ہوں، اس میں «محمد رسول اللہ» نقش تھا۔","الألباني: صحيح",{"u2":"سیدنا انس رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے رومیوں کے خط لکھنے کا ارادہ فرمایا۔ لوگوں نے کہا: حضور! وہ لوگ مہر کے بغیر خط نہیں پڑھتے۔ آپ نے چاندی کی مہر بنوالی۔ مجھے یوں محسوس ہو رہا ہے کہ میں اب بھی اس کی چمک آپ کے دست مبارک میں دیکھ رہا ہوں۔ اور آپ نے اس میں ’’محمدرسول اللہ‘‘ کے الفاظ کندہ کروائے۔"}],[5279,"انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے چاندی کی ایک انگوٹھی بنوائی، اس کا نگینہ حبشہ کا بنا ہوا تھا۔","الألباني: صحيح",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے چاندی کی انگوٹھی بنوائی۔ اس کا نگینہ حبشہ کا بنا ہوا تھا۔"}],[5280,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کی انگوٹھی چاندی کی تھی اور اس کا نگینہ بھی چاندی کا تھا۔","الألباني: صحيح",{"u2":"سیدنا انس رضی اللہ عنہ نے فرمایا: نبی اکرم صلی اللہ علیہ وسلم کی مبارک انگوٹھی چاندی کی تھی۔ اور اس کا نگینہ بھی چاندی ہی کا تھا۔","f2":"رسول اللہ صلی اللہ علیہ وسلم کی انگوٹھی مبارک کے نگینے کی تفصیل حدیث: 5199میں گزر چکی ہے۔"}],[5281,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہم نے انگوٹھی بنوائی ہے اور اس میں «محمد رسول اللہ» نقش کرایا ہے، لہٰذا اب کوئی ایسا نقش نہ کرائے\"۔","الألباني: صحيح",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ہم نےایک انگوٹھی بنوائی ہے اوراس پر ایک خاص نقش (محمد رسول اللہ) کندہ کروایا ہے لہذا کوئی شخص اس جیسا نقش نہ بنوائے۔","f2":"’’ہم نے ‘‘ممکن ہے یہ الفاظ کسی راوی کے ہوں یعنی اس نے احتراماً جمع کے الفاظ ذکر کر دیے ہیں۔ اگرچہ غالب امکان یہ ہے کہ آپ نے اسی طرح کے صیغے استعمال فرمائے ہوں گے۔ یہ بات کرنےکا شاہی اندازہ ہے اورانبیائے کرام خصوصاً خاتم النبین صلی اللہ علیہ وسلم سے بڑا ’’شاہ‘‘ کون ہو سکتا ہے؟ (باقی تفصیلات کےلیے دیکھیے احادیث: 5210، 5120)"}],[5282,"انس رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے ایک انگوٹھی بنوائی اور فرمایا: \"ہم نے ایک انگوٹھی بنوائی ہے اور اس پر نقش کرایا ہے، لہٰذا ایسا نقش کوئی نہ کرائے\"، گویا میں اس کی چمک رسول اللہ صلی اللہ علیہ وسلم کی چھنگلی میں (اب بھی) دیکھ رہا ہوں۔","الألباني: صحيح",{"u2":"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے ا یک انگوٹھی بنوائی اور فرمایا: ’’ ہم نے ایک انگوٹھی بنوائی ہے او رہم نے اس پر ایک عبارت کندہ کروائی ہے۔ کوئی شخص اس کے مطابق عبارت کندہ نہ کروائے۔ ‘‘ اللہ کی قسم! میں (عالم تصورمیں اب بھی) اس انگوٹھی کی چمک رسول اللہ صلی اللہ علیہ وسلم کی چھنگلی میں دیکھ رہا ہوں۔"}],[5283,"انس رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم انگوٹھی اپنے دائیں ہاتھ میں پہنتے تھے۔","الألباني: صحيح",{"u2":"سیدنا انس رضی اللہ عنہ نے فرمایا: نبی اکرم صلی اللہ علیہ وسلم اپنے داہنے ہاتہ میں انگوٹھی پہنا کرتے تھے۔"}],[5284,"انس رضی اللہ عنہ کہتے ہیں: گویا میں نبی اکرم صلی اللہ علیہ وسلم کی انگوٹھی کی سفیدی آپ کے بائیں ہاتھ کی انگلی میں (اب بھی) دیکھ رہا ہوں۔","الألباني: صحيح الإسناد",{"u2":"سیدنا انس رضی اللہ عنہ نے فرمایا:مجھے یوں محسوس ہوتا ہے کہ میں اب بھی رسول اللہ صلی اللہ علیہ وسلم کی انگوٹھی مبارک کی چمک آپ کی بائیں (چھوٹی) انگلی میں دیکھ رہا ہوں۔","f2":"دائیں بائیں کی تفصیل پیچھے گزر چکی ہے۔ دیکھیے حدیث: 5200۔"}],[5285,"ثابت بیان کرتے ہیں کہ لوگوں نے انس رضی اللہ عنہ سے رسول اللہ صلی اللہ علیہ وسلم کی انگوٹھی کے بارے میں سوال کیا، تو وہ بولے: گویا میں آپ صلی اللہ علیہ وسلم کی چاندی کی انگوٹھی کی چمک دیکھ رہا ہوں، پھر انہوں نے اپنے بائیں ہاتھ کی چھنگلی انگلی کو بلند کیا ۱؎۔\n§وضاحت\n۱؎: یعنی یہ بتار ہے تھے کہ آپ صلی اللہ علیہ وسلم انگوٹھی چھنگلی انگلی میں پہنتے تھے۔","الألباني: صحيح",{"u2":"حضرت ثابت بیان کرتے ہیں کہ لوگوں نے سیدنا انس رضی اللہ عنہ سے رسول اللہ صلی اللہ علیہ وسلم کی انگوٹھی کے بارے میں پوچھا تو انہوں نے فرمایا:مجھے یوں محسوس ہو رہا ہے میں آپ کی چاندی والی انگوٹھی کی چمک اب بھی دیکھ رہا ہوں۔ (یہ کہتے ہوئے) انہوں نے اپنے بائیں ہاتھ کی چھوٹی انگلی کو اٹھایا۔","f2":"’’اٹھایا ‘‘ ان کا مقصد یہ بتانا تھا کہ آپ بائیں ہاتھ کی چھوٹی انگلی میں انگوٹھی پہنتے تھے لیکن دیگر کثیر روایات سے ثابت ہوتا ہے کہ آپ دائیں ہاتھ میں انگوٹھی پہنتے تھے کیونکہ یہ زینت ہے اور آپ اچھے امور میں دائیں ہاتھ کو ترجیح دیتے تھے خصوصاً جب کہ آپ کی انگوٹھی پہنتے تھے کیونکہ یہ زینت ہے اور آپ اچھے امورمیں دائیں ہاتھ کو ترجیح دیتے تھے خصوصاً جب کہ آپ کی انگوٹھی میں اللہ تعالیٰ اور خود آپ کانام نامی تھا اوربایاں ہاتھ تو استنجا وغیرہ میں استعمال ہوتاہے۔ کیا ایسے متبرک اور مقدس نام استنجا والے ہاتھ کے لائق ہے؟ ہر گز نہیں۔\nہاں! یہ ممکن ہے کہ کبھی کبھار بائیں ہاتھ میں ڈالی گئی ہو۔ ویسے بھی عموماً کام دائیں ہاتہ سے کیے جاتے ہیں۔ آپ مہر لگانے کےلیے انگوٹھی پہنتے تھے اور مہر لگانا بھی ایک کام ہے لہذا یہ بھی دائیں ہاتھ ہی سے ہونا چاہیے اور بہ تبھی ہوگا اگر انگوٹہی دائیں ہاتھ میں ہو۔"}],[5286,"علی رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے مجھے شہادت اور بیچ کی انگلی میں انگوٹھی پہننے سے منع فرمایا ہے ۱؎۔\n§وضاحت\n۱؎: یہ نہی تنزیہی ہے، یعنی خلافِ اولی ہے، بہتر یہ ہے کہ ان انگلیوں میں نہ پہنا جائے۔","الألباني: صحيح",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ میں نے سیدنا علی رضی اللہ عنہ کو فرماتے سنا کہ نبی صلی اللہ علیہ وسلم نے مجھے انگشت شہادت اور درمیانی انگلی میں انگوٹھی ڈالنے سے منع فرمایا۔","f2":"’’انگشت شہادت ‘‘ عربی میں سبابہ استعمال فرمایاگیا ہے۔ اس کے لفظی معنی ہیں گالی دینے والی انگلی۔ جاہلیت میں لوگ گالی دیتے وقت اس انگلی سے اشارہ کرتے تھے اس لیے وہ اس کوسبابہ کہتے ہیں۔ مسلمان نمازمیں تشہد کے وقت اس انگلی سے اشارہ کرتے ہیں اس لیے ہم اسے شہادت والی انگلی کہتے ہیں۔ گالی دینا شریعت میں ویسے بھی منع ہے چہ جائیکہ کوئی انگلی سبابہ ہو۔ حدیث میں یہ لفظ عرف عام کے طور پر آگیا ہے۔ مختصر بھی ہے۔"}],[5287,"علی رضی اللہ عنہ کہتے ہیں کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے اس (شہادت کی) انگلی میں، بیچ کی انگلی اور اس سے لگی ہوئی انگلی میں انگوٹھی پہننے سے روکا ہے۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے مجھے منع فرمایا کہ میں اپنی اس انگلی میں درمیان والی اور ساتھ والی انگلی میں انگوٹھی ڈالوں۔"}],[5288,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم سونے کی انگوٹھی پہنتے تھے، پھر آپ نے اسے اتار پھینکا اور چاندی کی انگوٹھی پہنی، اور اس پر«محمد رسول اللہ» نقش کرایا، پھر فرمایا: \"کسی کے لیے جائز نہیں کہ میری اس انگوٹھی کے نقش پر کچھ نقش کرائے\"، آپ نے اس کا نگینہ ہتھیلی کی طرف رکھا تھا۔","الألباني: صحيح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ نے فرمایا: نبی اکرم صلی اللہ علیہ وسلم (پہلے) سونے کی انگوٹھی پہنا کرتے تھے۔ پھر آپ نے اسے اتار پھینکا اور چاندی پہننے لگے۔ اور آپ نے اس پر ’’محمد رسول اللہ‘‘ کندہ کروایا پھر آپ نے فرمایا: ’’ کسی کے لیے مناسب نہیں کہ میری اس انگوٹھی کے نقش کے مطابق (اپنی انگوٹھی پر) نقش بنوائے۔‘‘ آپ اس کا نگینہ ہتھیلی کی جانب رکھتے تھے۔","f2":"’’ہتھیلی کی جانب ‘‘ کیونکہ آپ کا مقصد انگوٹھی پہننے سےزینت نہیں تھا مہر لگانا تھا۔ نگینہ ہاتھ کی پشت کی طرف رکھنا زینت کےلیے ہوتا اور ایسی زینت مرد کومناسب نہیں اگرچہ اس سے منع بھی نہیں کیا جاسکتا۔"}],[5289,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک انگوٹھی بنوائی اور اسے پہنا، اور فرمایا: \"اس نے آج سے میری توجہ تمہاری طرف سے بانٹ دی ہے، ایک نظر اسے دیکھتا ہوں اور ایک نظر تمہیں\"، پھر آپ نے وہ انگوٹھی اتار پھینکی۔","الألباني: صحيح الإسناد",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ا نگوٹھی بنوائی اور پہنی پھرفرمایا: ’’اس انگوٹھی نے مجھے تم سے مصروف کیے رکھا۔ میں کبھی اس کو دیکھتا تھا کبھی تم کو۔ ‘‘ پھر آپ نے اسے اتار پھینکا۔","f2":"معلوم ہوتا ہے یہ سونے کی انگوٹھی تھی جس کا ذکر اوپر بھی گزرا۔ اس کی خوبی صورتی کی وجہ سے آپ کی توجہ بارہا اس کی جانب مبذول ہوئی تو آپ نے اسے پہننے رکھنا مناسب نہ سمجھا۔ اس سے معلوم ہوا کہ صرف زینت کےلیے انگوٹھی نہیں پہننی چاہیے۔"}],[5290,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سونے کی ایک انگوٹھی بنوائی، آپ اسے پہنتے تھے اور اس کا نگینہ ہتھیلی کی طرف رکھتے، تو لوگوں نے بھی (انگوٹھیاں) بنوائیں، پھر آپ منبر پر بیٹھے اور اسے اتار پھینکا اور فرمایا: \"میں یہ انگوٹھی پہنتا تھا اور اس کا نگینہ اندر کی طرف رکھتا تھا\"، پھر آپ نے اسے پھینک دی، پھر فرمایا: \"اللہ کی قسم! میں اسے کبھی نہیں پہنوں گا\"، پھر لوگوں نے بھی اپنی اپنی انگوٹھیاں پھینک دیں۔","الألباني: صحيح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسو اللہ صلی اللہ علیہ وسلم نے سونے کی انگوٹھی بنوائی۔ آپ اسے زیب تن فرمایا کرتے تھے۔ آپ اس کا نگینہ ہتھیلی کی جانب رکھتے تھے۔ لوگوں نے بھی (سونے کی) انگوٹھیاں بنوالیں پھر ایک دن آپ منبر پر تشریف فرم ہوئے تو اسے اتار پھینکا اور فرمایا: ’’میں یہ انگوٹھی پننا تھا اور اس کا نگینہ اندرونی جانب رکھتا تھا۔ ’’ پھر آپ نے اسے اتار پھینکا اور فرمایا: ’’ اللہ کی قسم! اب میں اسے کبھی نہیں پہنوں گا۔ ‘‘ لوگوں نے بھی اپنی اپنی انگوٹھیاں اتار پھینک","f2":"دیکھیے حدیث:5221۔"}],[5291,"انس رضی اللہ عنہ کہتے ہیں کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے ہاتھ میں چاندی کی ایک انگوٹھی ۱؎ صرف ایک دن دیکھی، تو لوگوں نے بھی بنوائی اور اسے پہنا، پھر نبی اکرم صلی اللہ علیہ وسلم نے پھینک دی تو لوگوں نے بھی پھینک دی۔\n§وضاحت\n۱؎: یہ راوی کا وہم ہے، کیونکہ صحیح یہ ہے کہ آپ نے سونے کی انگوٹھی بنوائی۔","الألباني: صحيح",{"u2":"سیدنا انس رضی اللہ عنہ نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کے دست مبارک میں ایک چاندی کی انگوٹھی دیکھی۔ لوگوں نے بھی انگوٹھیاں بنوالیں اور پہن لیں۔ پھر نبی اکرم صلی اللہ علیہ وسلم نے اپنی انگوٹھی اتار پھینکی اور لوگوں نے بھی اتار پھینکیں۔","f2":"روایت کے ظاہر الفاظ سے معلوم ہوتا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے جو انگوٹھی اتار پھینکی تھی وہ چاندی کی تھی لیکن یہ بات درست نہیں کیونکہ باقی تمام روایات میں صراحت ہے کہ پھینکی جانے والی انگوٹھی سونے کی تھی چاندی کی نہیں چاندی کی بعد میں بنوائی گئی۔ اس روایت میں یہ امام زہری رحمہ اللہ کا وہم ہے۔ غلطی کرنا اور وہم لگ جانا انسانی طبیعت کا خاصا ہے۔ یہ کوئی ان ہونی بات نہیں ہے لہذا درست بات یہی ہے کہ پھینکی جانے والی انگوٹھی سونے کی تھی نہ کہ چاندی کی۔ راوی حدیث کے ساتھ کبھی ایسے ہو جاتا ہے۔ اس میں گھبرانے یا تعجب کی کوئی بات نہیں۔"}],[5292,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سونے کی ایک انگوٹھی بنوائی اور اس کا نگینہ ہتھیلی کی طرف رکھا، تو لوگوں نے بھی سونے کی انگوٹھیاں بنوائیں، پھر آپ صلی اللہ علیہ وسلم نے اپنی انگوٹھی اتار دی تو لوگوں نے بھی اپنی انگوٹھیاں اتار دیں، اور رسول اللہ صلی اللہ علیہ وسلم نے چاندی کی انگوٹھی بنوائی، جس سے آپ (خطوط پر) مہر لگاتے تھے اور اس کو پہنتے نہیں تھے۔","الألباني: صحيح دون قوله ولا يلبسه فإنه شاذ",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سونے کی انگوٹھی بنوائی۔ آپ اس کا نگینہ ہتھیلی کی جانب رکھا کرتے تھے۔ لوگوں نے بھی سونے کی انگوٹھیاں بنوالیں۔ پھر رسول اللہ صلی اللہ علیہ وسلم نے اسے اتار پھینکا۔ لوگوں نے بھی اپنی انگوٹھیاں اتار پھینکیں۔ پھر آپ نے چاندی کی انگوٹھی بنوالی۔ آپ اس سے مہر لگاتے تھے۔ اوراسے (عموما)نہیں پہنتے تھے۔","f2":"’’پہننے نہیں تھے ‘‘ یعنی آپ اسے ہر وقت پہنے نہیں رکھتے تھے بلکہ ضرورت کے وقت پہنتے تھے کیونکہ اس سے آپ کا مقصد زینت نہیں تھا۔"}],[5293,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سونے کی ایک انگوٹھی بنوائی اور اس کا نگینہ ہتھیلی کی طرف رکھا، پھر لوگوں نے بھی انگوٹھیاں بنوائیں، تو آپ نے اسے نکال دیا اور فرمایا: \"میں اسے کبھی نہیں پہنوں گا\"، پھر آپ صلی اللہ علیہ وسلم نے چاندی کی انگوٹھی بنوائی اور اسے اپنے ہاتھ میں پہن لیا، پھر وہ انگوٹھی ابوبکر رضی اللہ عنہ کے ہاتھ میں رہی، پھر عمر رضی اللہ عنہ کے ہاتھ میں، پھر عثمان رضی اللہ عنہ کے ہاتھ میں یہاں تک کہ وہ اریس نامی کنویں میں ضائع ہو گئی۔","الألباني: صحيح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے سونے کی انگوٹھی بنوائی اور اس کا نگینہ ہتھیلی کی جانب رکھا۔ لوگوں نے بھی سونے کی انگوٹھیاں بنوالیں۔پھر رسول اللہ صلی اللہ علیہ وسلم نے اسے اتار پھینکا اور فرمایا: ’’میں آئندہ اسے کبھی نہیں پہنوں گا۔ ‘‘ پھر رسول اللہ صلی اللہ علیہ وسلم نے چاندی کی انگوٹھی بنوالی اور اسے اپنے دست مبارک میں پہنا۔ پھر وہ سیدنا ابو بکر رضی اللہ عنہ کے ہاتھ میں رہی پھرسیدنا عمر رضی اللہ عنہ کے ہاتھ میں پھر سیدنا عثمان رضی اللہ عنہ کے ہاتھ میں حتی کہ وہ اریش کےکنویں میں گم ہو گئی۔","f2":"اس کی تفصیل دیکھیے فوائد ومسائل حدیث: 5220۔"}],[5294,"ابوالاحوص کے والد عوف بن مالک رضی اللہ عنہ کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا، آپ نے مجھے خستہ حالت میں دیکھا، تو فرمایا:\"کیا تمہارے پاس کچھ مال و دولت ہے؟\" میں نے کہا: جی ہاں! اللہ تعالی نے مجھے ہر طرح کا مال دے رکھا ہے، آپ نے فرمایا: \"جب تمہارے پاس مال ہو تو اس کے آثار بھی نظر آنے چاہئیں ۱؎\"۔\n§وضاحت\n۱؎: یعنی: فضول خرچی اور ریاء و نمود کے کے بغیر، اور حیثیت کے مطابق آدمی کے اوپر اچھا لباس ہونا چاہیئے، ہاں۔ اسراف، فضول خرچی اور ریاء و نمود والا لباس ناپسندیدہ اور مکروہ ہے۔","الألباني: صحيح",{"u2":"حضرت ابو الاحوص کے والد محترم سے روایت ہے کہ میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا تو آپ نے مجھے خراب سی حالت میں دیکھا۔ نبی اکرم صلی اللہ علیہ وسلم فرمانے لگے: ’’کیاتیرے پاس کچھ مال ہے؟‘‘ میں عرض کیا: ہر قسم کامال اللہ تعالیٰ نے مجھے دےرکھا ہے۔ آپ نے فرمایا: ’’تیرے پاس مال ہے تو تجھ پرنظر بھی آنا چاہیے۔‘‘","f2":"تفصیل کےلیے دیکھیے فوائد ومسائل حدیث: 5225، 5226۔"}],[5295,"عمر بن خطاب رضی اللہ عنہ سے روایت ہے کہ مسجد کے دروازے کے پاس میں نے ایک ریشمی دھاری والا جوڑا بکتے دیکھا، تو عرض کیا: اللہ کے رسول! اگر آپ اسے جمعہ کے دن کے لیے اور اس وقت کے لیے جب آپ کے پاس وفود آئیں خرید لیتے (تو اچھا ہوتا) ۱؎، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یہ سب وہ پہنتے ہیں جن کا آخرت میں کوئی حصہ نہیں\"۔ پھر اس میں کے کئی جوڑے رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، تو ان میں سے آپ نے ایک جوڑا مجھے دے دیا، میں نے کہا: اللہ کے رسول! یہ جوڑا آپ نے مجھے دے دیا، حالانکہ اس سے پہلے آپ نے اس کے بارے میں کیا کیا فرمایا تھا؟ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"میں نے تمہیں یہ پہننے کے لیے نہیں دیا ہے، بلکہ کسی (اور) کو پہنانے یا بیچنے کے لیے دیا ہے\"، تو عمر رضی اللہ عنہ نے اسے اپنے ایک ماں جائے بھائی کو دے دیا جو مشرک تھا۔\n§وضاحت\n۱؎: آپ صلی اللہ علیہ وسلم نے عمر رضی اللہ عنہ کی اس بات پر کوئی نکیر نہیں کی، اس سے ثابت ہوا کہ ان مواقع کے لیے اچھا لباس اختیار کرنے کی بات پر آپ نے صاد کیا۔","الألباني: صحيح",{"u2":"سیدنا عمر بن خطاب رضی اللہ عنہ سے روایت ہے کہ میں نے مسجد (نبوی) کے دروازے پر ریشمی دھاریوں والا حلہ فروخت ہوتے دیکھا تو میں نے کہا:اے اللہ کے رسول! اگر آپ یہ حلہ جمعتہ المبارک کے دن او روفود کی آمد کے موقع پر استعمال کے لیے خرید لین تو مناسب رہے گا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ایسے حلے تو وہ لوگ پہنتے ہیں جن کا آخرت میں کوئی حصہ نہیں۔ ‘‘ پھر بعد میں رسول اللہ صلی اللہ علیہ وسلم کے پاس اسی قسم کے کچھ حلے آئے تو آپ نے مجھے بھی ان میں سے ایک حلہ دے دیا۔ میں نے عرض کیا: اے اللہ کے رسول! آپ نے یہ حلہ مجھے دیا ہے جب کہ آپ نے تو اس بارے میں بڑے سخت الفاظ فرمائےتھے۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا:’’ میں نے تجھے یہ پہننے کے لیے نہیں دیا بلکہ اس لیے دیا ہے کہ تو کسی اور کو پہناےئ یا بیچ لے۔‘‘ سیدنا عمر رضی اللہ عنہ نے وہ اپنے ایک مشرک اخیافی بھائی کو دے دیا۔","f2":"1۔ اس حدیث مبارکہ سے معلوم ہوا کہ تجمل اور خوبصورتی اختیار کرنا بالخصوص خاص موقعوں پر پسندیدہ ہے۔\n2۔ مسجد کے دروازے پر خرید وفروخت کرنا جائز ہے نیز فضلاء اور عظماء اہل علم اور نیک لوگوں کا منڈی میں جانا شرعاً درست ہے خواہ وہ خرید وفروخت کے لیے ہو یا ویسے ہی جائزہ لینے کےلیے ہو۔\n3۔ ریشمی کپڑا کا کاروبار جائز ہے۔\n4۔ کافر قرابت دار کےساتھ صلہ رحمی کرنا نیز اسے ہدیہ وغیرہ دینا بھی شرعاً جائز ہے۔ اس کا مقصد اگر تالیف قلب اور اسے اسلام کے قریب کرنا ہو تو یہ سونے پر سہاگا ہے۔\n5۔ ایسا حلہ دھاریوں کی وجہ سے ممنوع نہیں بلکہ ریشمی دھاریون کی وجہ سے ممنوع ہے۔\n6۔ ’’کوئی حصہ نہیں‘‘ مراد کفار ہیں یعنی اس قسم کے کپڑے تو کافر پہنتے ہیں لیکن اس کا یہ مطلب نہیں کہ جوشخص ایسے کپڑے پہنے گاوہ کافر بن جائے گا کیونکہ ریشم پہننا کبیرہ گناہ ضرور ہے کفر نہیں اور اگر ریشم پہننے سےمقصود دوسرے لوگوں کی تحقیر کرنا ہو یا ازراہ تکبر ریشم پہنا جائے تو گناہ کی قباحت میں اور اضافہ ہو جاتا ہے۔\n7۔ ’’بھائی کو دے دیا ‘‘ جوچیز کچھ افراد کےلیے حلال ہو کچھ کےلیے حرام، اس کالین دین، خرید وفروخت،تحفہ و عطیہ وغیرہ سب کچھ جائز ہے مثلاً: ریشم اور سونا وغیرہ البتہ جوچیز سب کےلیے حرام ہے اس کاکاروبار لین دین خرید وفروخت تحفہ عطیہ وغیرہ سب کچھ حرام ہے مثلا:شراب اوربت وغیرہ۔\n8۔ یہ بات یاد رہنی چاہیے کہ ریشم صرف مردوں کےلیے ناجائز اور حرام ہے عورتوں کوہر قسم کا ریشم پہننے کی مطلقاً اجازت ہے۔"}],[5296,"انس رضی اللہ عنہ کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم کی بیٹی زینب رضی اللہ عنہا کو ریشم کی دھاری والی قمیص پہنے دیکھا۔","الألباني: شاذ والمحفوظ أم كلثوم مكان زينب",{"u2":"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم کی بیٹی حضرت زینب کو دھاری دار ریشمی قمیص پہنے ہوئے دیکھا۔"}],[5297,"انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کی بیٹی ام کلثوم رضی اللہ عنہا کو سیراء دھاری دار ریشمی چادر پہنے دیکھا۔","الألباني: صحيح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ نے فرمایا: میں نے نبی اکرم صلی اللہ علیہ وسلم کی بیٹی ام کلثوم رضی اللہ عنہا کو ریشمی دھاری دار چادر اوڑھے دیکھا۔"}],[5298,"علی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کو سیراء چادر تحفے میں آئی، تو آپ نے اسے میرے پاس بھیج دی، میں نے اسے پہنا، تو میں نے آپ کے چہرے پر غصہ دیکھا، چنانچہ آپ نے فرمایا: \"سنو، میں نے یہ پہننے کے لیے نہیں دی تھی\"، پھر آپ نے مجھے حکم دیا تو میں نے اس کو اپنے خاندان کی عورتوں میں تقسیم کر دیا۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم کی خدمت عالیہ میں ایک ریشمی دھاریدار حلہ بطور تحفہ بھیجا گیا۔ آپ نے وہ مجھے بھیج دیا میں نے اسے پہن لیا۔ (آپ نے مجھے دیکھا تو) میں نےآپ کے چہرہ انور پر غصے کے آثار دیکھے۔ آپ نے فرمایا: ’’میں نے تجھے اس لیے نہیں دیاتھا کہ تو اسے پہنے۔ ‘‘ پھر میں نے آپ کےحکم سے اپنے گھرکی عورتوں میں تقسم کر دیا۔","f2":"’’گھروں کی عورتوں ‘‘بعض روایات میں فواطم کا لفظ ہے یعنی فاطمہ نامی عورتوں میں تقسیم کر دیا ہے۔ مراد ان کی والدہ محترمہ سیدہ فاطمہ بنت اسد رضی اللہ عنہا جنہیں فاطمہ کبری بھی کہا جاتا ہے اور ان کی بیوی حضرت فاطمہ بنت رسول اللہ صلی اللہ علیہ وسلم اور ان کی چچازاد بہن فاطمہ بنت حمزہ رضی اللہ عنہا اور ان کی بھائی سیدنا عقیل رضی اللہ عنہ کی بیوی فاطمہ بنت شیبہ ہیں۔"}],[5299,"عبداللہ بن عمر رضی اللہ عنہما بیان کرتے ہیں کہ عمر رضی اللہ عنہ نکلے تو دیکھا بازار میں استبرق کی چادر بک رہی ہے، آپ نے رسول اللہ صلی اللہ علیہ وسلم کے پاس آ کر کہا: اللہ کے رسول! اسے خرید لیجئے اور اسے جمعہ کے دن اور جب کوئی وفد آپ کے پاس آئے تو پہنئے۔ آپ نے فرمایا: \"یہ تو وہ پہنتے ہیں جن کا (آخرت میں) کوئی حصہ نہیں ہوتا\"، پھر آپ کے پاس تین چادریں لائی گئیں تو آپ نے ایک عمر رضی اللہ عنہ کو دی، ایک علی رضی اللہ عنہ کو اور ایک اسامہ رضی اللہ عنہ کو دی، عمر رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم کے پاس آ کر کہا: اللہ کے رسول! آپ نے اس کے بارے میں کیا کیا فرمایا تھا، پھر بھی آپ نے اسے میرے پاس بھیجوایا؟ آپ نے فرمایا: \"اسے بیچ دو اور اس سے اپنی ضرورت پوری کر لو یا اسے اپنی عورتوں کے درمیان دوپٹہ بنا کر تقسیم کر دو\"۔\n§وضاحت\n۱؎: \"استبرق\" ایک قسم کا ریشم ہے۔","الألباني: صحيح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ بیان کرتے ہیں کہ ایک دفعہ سیدنا عمر رضی اللہ عنہ (گھر سے) نکلے تو دیکھاکہ استبراق کا ایک جوڑا بازار میں فروخت ہو رہا ہے۔ وہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور کہا: اے اللہ کے رسول! یہ حلہ خرید لیحیے اور جمعۃ المبارک کے دن او روفود کی آمد کے موقع پر زیب تن فرمایا کیجیے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ایسے کپڑے تو وہ لوگ پہنتے ہیں جن کا آخرت میں کوئی حصہ نہیں۔ ’’پھر رسول اللہ صلی اللہ علیہ وسلم کے پاس اس قسم کے تین حلے لائے گئے۔ آپ نے ایک حلہ سیدنا عمر رضی اللہ عنہ کو،دوسرا سیدنا علی رضی اللہ عنہ کو اور تیسرا سیدنا اسامہ رضی اللہ عنہ کو دے دیا۔ سیدنا عمر رضی اللہ عنہ نے آپ کے پاس حاضر ہو کر عرض کی: اے اللہ کے رسول! ان حلوں کے بارے میں تو آپ نے بڑے سخت الفاظ ارشاد فرمائے تھے۔ اب آپ نے وہ حلہ مجھے بھیج دیا ہے۔ آپ نے فرمایا: ’’اسے بیچ کر اپنی ضروریات پوری کر لے یا دو پٹے بنا کر اپنی عورتوں میں تقسیم کر دے۔‘‘","f2":"1۔ ’’اپنی عورتوں ‘‘مراد صرف بیویاں نہیں بلکہ بیویاں، بہنیں، مائیں سب مراد ہیں۔\n2۔’’استبراق ‘‘ ریشم کی ایک قسم ہے۔ یہ موٹا اور کھردرا سا ریشم ہوتا ہے۔ اس کوفارسی میں استر کہتے ہیں۔ اسی لفظ کو عربوں نے استبراق بنا دیا۔ ریشم میں سونے کی تاریں بنی جائیں تب بھی اسے استبراق کہہ دیتے ہیں۔\n3۔سیدنا علی رضی اللہ عنہ اور حضرت عمر رضی اللہ عنہما باوجود انتہائی ذہین اور مجتہد ہونے کے نبی اکرم صلی اللہ علیہ وسلم کے مقصود کو نہ سمجھ سکے۔ ا س میں ان لوگوں کے لیے عبرت ہے جو بعض ائمہ کے استباطات اور اجتہادات کو بلاچون وچرا قبول کرلیتے اور انہیں حدیث پر ترجیح دیتے ہیں کہ وہ بڑے فقیہ تھے اور حدیث کا راوی صحابی فقیہ نہیں۔ معاذاللہ."}],[5300,"یحیی بن ابی اسحاق کہتے ہیں کہ سالم نے پوچھا: استبرق کیا ہے؟ میں نے کہا: ایک قسم کا ریشم ہے جو سخت ہوتا ہے، وہ بولے: میں نے عبداللہ بن عمر رضی اللہ عنہما کو کہتے ہوئے سنا کہ عمر رضی اللہ عنہ نے ایک شخص کے پاس ایک جوڑا سندس کا دیکھا، اسے لے کر نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے اور کہا: اسے خرید لیجئیے … پھر پوری روایت بیان کی۔\n§وضاحت\n۱؎: \"سندس\" یہ بھی ایک قسم کا ریشمی کپڑا ہے۔","الألباني: صحيح",{"u2":"حضرت یحیی بن ابی اسحاق نے کہا کہ حضرت سالم نے مجھ سے پوچھا استبرق کیا ہوتا ہے؟ میں نے کہا: موٹا کھردرا ریشم۔ وہ کہنے لگے: میں نے سیدنا عبد اللہ بن عمر رضی اللہ عنہ کو فرماتے سنا کہ سیدنا عمر رضی اللہ عنہ نے ایک آدمی کے پاس سندس کا حلہ دیکھا۔ وہ یہ حلہ لے کر نبی اکرم صلی اللہ علیہ وسلم کے پاس حاضر ہوئے اور عرض کیا: یہ خرید لیحیے۔ پھر راوی نے حسب سابق حدیث بیان کی۔","f2":"’’سندس‘‘ باریک ریشم کو کہتے ہیں۔"}],[5301,"عبداللہ بن عکیم سے روایت ہے کہ حذیفہ بن الیمان رضی اللہ عنہ نے پانی مانگا تو ایک اعرابی (دیہاتی) چاندی کے برتن میں پانی لے آیا، حذیفہ رضی اللہ عنہ نے اسے پھینک دیا، پھر جو کیا اس کے لیے لوگوں سے معذرت کی اور کہا: مجھے اس سے روکا گیا ہے۔ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: \"سونے اور چاندی کے برتن میں نہ پیو اور دیبا نامی ریشم نہ پہنو اور نہ ہی حریر نامی ریشم، کیونکہ یہ ان (کفار و مشرکین) کے لیے دنیا میں ہے اور ہمارے لیے آخرت میں ہیں\"۔","الألباني: صحيح",{"u2":"حضرت عبد اللہ بن عکیم سے روایت ہے کہ سیدنا خذیفہ رضی اللہ عنہ نے پانی مانگا تو ایک دیہاتی نمبردارچاندی کے برتن میں پانی لایا۔ انہوں نے وہ برتن اسی کو دے مارا۔ پھر حاضرین سے اس سلوک پر معذرت کی اور فرمایا: میں نے اسے کئی بار (چاندی کے برتن میں پانی لانے سے) روکا ہے جب کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: ’’سونےچاندی کے برتن میں پانی نہ پیو اور دیباج و حریر (کسی قسم کا ریشم) نہ پہنو کیونکہ یہ چیزیں ان (کافروں) کےلیے دنیامیں ہیں اور ہمارے لیے آخرت میں ہیں۔‘‘","f2":"1۔ دیباج بھی ریشم کی ایک قسم ہے۔ مقصد یہ ہے کہ ہر قسم کاریشم مردوں کے لیے حرام ہے۔ باریک ہو یاموٹا نرم ہویا سخت۔\n2۔ ’’سونے چاندی کے برتن ‘‘ یہ حکم مردوں اور عورتوں سب کےلیے برابر ہے، البتہ عورت کےلیے سونا پہننا جائز ہے۔\n3۔ ’’استعمال کرتے ہیں ‘‘ کیونکہ ان کے نزدیک آخرت اور جزا و سزا کا کوئی تصور نہیں، لہذا وہ ہر قسم کی آسائش دنیا ہی میں حاصل کرنا چاہتے ہیں جب کہ مومن دنیا میں صرف ضروریات استعمال کرتے ہیں۔ آسائشیں آخرت میں طلب کرتے ہیں۔"}],[5302,"واقد بن عمرو بن سعد بن معاذ کہتے ہیں کہ انس بن مالک رضی اللہ عنہ جب مدینے آئے، تو میں ان کے پاس گیا، میں نے انہیں سلام کیا تو انہوں نے کہا: تم کون ہو؟ میں نے کہا: میں واقد بن عمرو بن سعد بن معاذ ہوں، وہ بولے: سعد تو بہت عظیم شخص تھے اور لوگوں میں سب سے لمبے تھے، پھر وہ رو پڑے اور بہت روئے، پھر بولے: رسول اللہ صلی اللہ علیہ وسلم نے دومۃ کے بادشاہ اکیدر کے پاس ایک وفد بھیجا، تو اس نے آپ کے پاس دیبا کا ایک جبہ بھیجا، جس میں سونے کی کاریگری تھی، چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے اسے پہنا، پھر آپ منبر پر کھڑے ہوئے اور بیٹھ گئے، پھر کچھ کہے بغیر اتر گئے، لوگ اسے اپنے ہاتھوں سے چھونے لگے، تو آپ نے فرمایا: \"کیا تمہیں اس پر تعجب ہے؟ سعد کے رومال جنت میں اس سے کہیں زیادہ بہتر ہیں جسے تم دیکھ رہے ہو\" ۱؎۔\n§وضاحت\n۱؎: دیبا نامی ایسا ریشمی کپڑا پہننا منسوخ ہے، جیسا کہ اگلی روایت میں آ رہا ہے۔","الألباني: حسن صحيح",{"u2":"حضرت واقد بن عمرو بن سعد بن معاذسے روایت ہے کہ جب سیدنا انس بن مالک رضی اللہ عنہ مدینہ منورہ تشریف لائے تو میں ان کے پاس حاضر ہوا اور سلام عرض کیا۔ انہوں نے کہا: تو کن میں سے ہے؟ میں نے کہا: میں واقدبن عمروہوں۔ سیدنا سعد بن معاذ رضی اللہ عنہ کا پوتا۔ انہوں نے کہا: سیدنا سعد رضی اللہ عنہ بڑے سردار اور لمبے قد کے آدمی تھے۔پھر(ان کو یاد کرکے) روئے اور بہت روئے پھر فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے دومتہ الجندل کے حکمران اکیدر کی طرف ایک لشکر بھیجا تو اس نے (اطاعت قبول کی اور) آپ کی خدمت میں ریشم کا ایک حلہ بھیجا جوسونے کے تاروں سے بنا گیا تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے اسے زیب تن کیا پھر منبر پر تشریف فرما ہوئے۔ صرف بیٹھے رہے۔ کوئی تقریر نہیں فرمائی۔ کچھ دیر بعد اتر آئے۔ لوگ ہاتھ لگا لگا کر حلے کو دیکھتے تھے۔ آپ نے فرمایا:’’ کیاتم اس (کی عمدگی او رنرمی) پر تعجب کرتے ہو؟ اللہ کی قسم! (حضرت) سعد بن معاذ کے (ہاتھ منہ کی صفائی والے) رومال جنت میں اس سے کہیں بڑھ کر خوب صروت ہیں۔‘‘","f2":"1۔ اما م نسائی رحمہ اللہ کا ترجمتہ الباب سے مقصد یہ مسئلہ بیان کرناہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ریشم کا ایسا جوڑا زیب تن کیاتھا جس کی بنائی سونے کےتاروں سے کی گئی تھی۔ امام صاحب کا مقصد یہی ہے۔ لیکن حقیقت یہ ہے کہ اس حدیث میں مذکور الفاظ فلبسه رسول الله صلی اللہ علیہ وسلم شاذ ہیں۔ یہ حدیث صحیح بخاری میں بھی مذکور ہے لیکن اس میں یہ الفاظ (جنہیں شاذکہاگیا ہے) نہیں ہیں بہر حال یہ امام نسائی رحمہ اللہ کا اپنا رجحان ہے یہی وجہ ہے کہ انہوں نے اگلا باب اس کے نسخ کے متعلق قائم کیا ہے۔ واللہ اعلم . تفصیل کےلیے دیکھیے: (ذخیرہ العقبی شرح سنن النسائی:39/ 29، 29)\n2۔اس حدیث مبارکہ سے قبیلہ اوس کےسردار سیدنا سعد بن معاذ رضی اللہ عنہ کی فضیلت اور جنت میں اعلیٰ مقام نیز اللہ تعالیٰ کے ہاں ان کی قدرو منزلت معلوم ہوتی ہے کہ ان کے ’’اونی کپڑے ‘‘ دنیا کے قیمتی اور بہترین ریشم سے بہتر ہیں کیونکہ تولیہ یا ہاتھ صاف کرنے والا رومال دیگر کپڑوں اور لباس کے مقابلے میں انتہائی کم قیمت اورگھٹیا ہوتا ہے جب وہ اس قدر قیمتی ہے تو ان کے استعمال کے دوسرے کپڑے اور لباس کس قدر بہتر او رقیمتی ہوں گے۔\n3۔یہ حدیث مبارکہ اس بات پر بھی دلالت کرتی ہے کہ مشرک کا ہدیہ قبول کیا جاسکتا ہے۔ امام بخاری رحمہ اللہ نے صحیح بخاری میں مذکورہ حدیث پر ان الفاظ سے عنوان قائم کیا ہے: ’’قبول الهدية من المشركين ‘‘ (صحیح البخاری: الهبة وفضلها والتحريض عليها، بابL28))\n4۔’’تشریف لائے ‘‘ سیدنا انس رضی اللہ عنہ مدینہ منورہ کے انصاری تھے مگر سیدنا عمر رضی اللہ عنہ کے دور میں وہ بصرہ چلے گئے۔ کبھی کبھی اپنی جنم بھومی ’’مدینہ منورہ‘‘ میں تشریف لاتے تھے۔\n5۔ ’’لمبے قد کے ‘‘ ان کے پوتے واقد بھی لمبے قد کاٹھ کے تھے اس لیے ان کو دیکھ کر یہ ذکر فرمایا۔\n6۔ ’’ رومال‘‘ عربی میں لفظ مندیل استعمال ہوا ہے۔ مندیل چھوٹے رومال کو کہتے ہیں جو گردوغبار صاف کرنے کےلیے ہاتھ میں رکھا جاتا ہے۔ عموماً یہ باقی لباس سے کم تر ہوتا ہے۔"}],[5303,"جابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے دیبا کی ایک قباء پہنی جو آپ کو ہدیہ کی گئی تھی، پھر تھوڑی دیر بعد اسے اتار دیا اور اسے عمر رضی اللہ عنہ کے پاس بھیجا، عرض کیا گیا: اللہ کے رسول! آپ نے اسے بہت جلد اتار دی، فرمایا: \"مجھے جبرائیل علیہ السلام نے اس کے استعمال سے روک دیا ہے\"، اتنے میں عمر رضی اللہ عنہ روتے ہوئے آئے اور بولے: اللہ کے رسول! ایک چیز آپ نے ناپسند فرمائی اور وہ مجھے دے دی؟ فرمایا: \"میں نے تمہیں پہننے کے لیے نہیں دی، میں نے تمہیں بیچ دینے کے لیے دی ہے\"، چنانچہ عمر رضی اللہ عنہ نے اسے دو ہزار درہم میں بیچ دیا۔","الألباني: صحيح",{"u2":"سیدنا جابر رضی اللہ عنہ نے فرمایا: نبی اکرم صلی اللہ علیہ وسلم نے ریشم کی قبا پہنی جو آپ کو بطور تحفہ ملی تھی پھر جلدہی اتار دی اور سیدنا عمر رضی اللہ عنہ کے پاس بھیج دی۔ آپ سے عرض کیا گیا: اے اللہ کے رسول! آپ نے اتنی جلدی اتار دی؟ آپ نے فرمایا: ’’جبریل علیہ السلام نے مجھے اس سے روک دیا۔ ‘‘ پھر سیدنا عمر رضی اللہ عنہ روتے ہوئے آئے اور عرض پرداز ہوئے۔ اے اللہ کے رسول! آپ نے ایک چیز ناپسند فرمائی پھر وہ مجھے دے دی۔ آپ نے فرمایا: ’’میں نے تجھے پہننے کےلیے نہیں دی بلکہ اس لیے دی کہ تو اسے بیچ (کر اپنی ضروریات پوری کر) لے۔ ‘‘ پھر سیدنا عمر رضی اللہ عنہ نے اسے دوہزار درہم میں بیچ دیا۔","f2":"امام نسائی رحمہ اللہ کےنزدیک کیونکہ پچھلی حدیث کے الفاظ ’’زیب تن کیا‘‘ ثابت ہیں اس لیے انہوں نے یہ حدیث لاکر نسخ ثابت کیا ہے جبکہ دوسرے علماء کے نزدیک وہ الفاظ ’’زیب تن ‘‘ راوی کا وہم ہے۔"}],[5304,"ثابت کہتے ہیں کہ میں نے عبداللہ بن زبیر رضی اللہ عنہما کو سنا وہ منبر پر خطبہ دیتے ہوئے کہہ رہے تھے: محمد صلی اللہ علیہ وسلم نے فرمایا: \"جس نے دنیا میں ریشم پہنا وہ آخرت میں اسے ہرگز نہیں پہن سکے گا\" ۱؎۔\n§وضاحت\n۱؎: یہ مردوں کے لیے ہے۔ عورتوں کے لیے ریشم پہننا جائز ہے، جیسا کہ حدیث نمبر ۱۵۵۱ میں گزرا۔","الألباني: صحيح",{"u2":"حضرت ثابت نے فرمایا: میں نے حضر ت عبد اللہ بن زبیر رضی اللہ عنہ کو منبر پر دوران خطبہ فرماتے سنا کہ حضرت محمد مصطفےٰ صلی اللہ علیہ وسلم نے فرمایا:’’ جس آدمی نے نے دنیا میں ریشم پہنا وہ آخرت مں ہرگز نہیں پہن سکے گا۔‘‘","f2":"’’ہرگز نہیں پہن سکےگا‘‘ خواہ جنت میں چلا بھی جائے۔ گویا جنت میں اس نعمت سے محروم رہے گا۔ یا مراد ہے کہ جنت میں نہیں جائے گاکیونکہ جنت میں تو لباس ہی ریشم کا ہوگا۔ پھر اولیں دخول مراد ہو گا۔ گویا جنت میں دخول سے پہلے کا عرصہ وہ ریشم سے محروم رہے گا۔ واللہ اعلم"}],[5305,"عبداللہ بن زبیر رضی اللہ عنہما کہتے ہیں کہ تم اپنی عورتوں کو ریشم نہ پہناؤ اس لیے کہ میں نے عمر بن خطاب رضی اللہ عنہ کو کہتے سنا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے دنیا میں ریشم پہنا، وہ اسے آخرت میں نہیں پہن سکے گا\" ۱؎۔\n§وضاحت\n۱؎: یہ عبداللہ بن زبیر رضی اللہ عنہما کی اپنی سمجھ ہے، انہوں نے اس فرمان کو عام سمجھا حالانکہ یہ مردوں کے لیے ہے، ممکن ہے ان کو وہ حدیث رسول صلی اللہ علیہ وسلم نہیں پہنچ سکی ہو جس میں صراحت ہے کہ \" ریشم امت کی عورتوں کے لیے حلال اور مردوں کے لیے حرام ہے \"، واللہ اعلم۔","الألباني: صحيح",{"u2":"سیدنا عبد اللہ بن زبیر رضی اللہ عنہ نے فرمایا: اپنی عورتون کو ریشم نہ پہنایا کرو۔ میں نے سیدنا عمر رضی اللہ عنہ کو فرماتے ہوئے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ جوشخص دنیا میں ریشم پہنے گا آخرت میں نہیں پہنے گا۔","f2":"’’اپنی عورتوں کو ‘‘ سیدنا عبد اللہ بن زبیر رضی اللہ عنہ اس حکم کو عام سمجھتے تھے جب کہ صحیح بات یہ ہے کہ ریشم کی حرمت کا حکم مردوں کے ساتھ خاص ہے۔ صحیح اور صریح احادیث اس تخصیص پر دلالت کرتی ہیں یہ صرف سیدنا عبد اللہ بن زبیر رضی اللہ عنہ کا موقف ہے۔"}],[5306,"عمران بن حطان سے روایت ہے کہ انہوں نے عبداللہ بن عباس رضی اللہ عنہما سے ریشم پہننے کے بارے میں پوچھا تو انہوں نے کہا: عائشہ رضی اللہ عنہا سے پوچھ لو، چنانچہ میں نے عائشہ رضی اللہ عنہا سے پوچھا تو وہ بولیں: عبداللہ بن عمر رضی اللہ عنہما سے پوچھ لو، میں نے ابن عمر رضی اللہ عنہما سے پوچھا تو انہوں نے کہا: مجھ سے ابوحفص (عمر) رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے دنیا میں ریشم پہنا، اس کا آخرت میں کوئی حصہ نہیں\" ۱؎۔\n§وضاحت\n۱؎: یہ بطور زجر و تہدید ہے، جو صرف مردوں کے لیے حرام ہیں، البتہ سونے چاندی کے برتن، اور ریشمی زین دونوں کے لیے حرام ہیں۔","الألباني: صحيح",{"u2":"حضرت عمران بن حطان سے مروی ہے کہ انہوں نے سیدنا عبد اللہ بن عباس رضی اللہ عنہ سے ریشم پہننے کے بارے میں پوچھا تو انہوں نے فرمایا:سیدہ عائشہ رضی اللہ عنہا سے پوچھو۔ میں نے سیدہ عائشہ رضی اللہ عنہا سے پوچھا تو انہوں نے فرمایا: سیدنا عبد اللہ بن عمر رضی اللہ عنہ سے پوچھو۔ میں نے ابن عمر رضی اللہ عنہ سے پوچھا تو انہوں نے فرمایا: مجھے حضرت ابو حفص (عمر بن خطاب رضی اللہ عنہ) نے بیان فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو دنیا میں ریشم پہنے گا اس کا آخرت میں کوئی حصہ نہیں۔‘‘","f2":"۔ ’’عمران بن حطان‘‘ معتبر راوی ہیں۔ خارجی مذہب رکھتے تھے۔ بقول بعض بعد میں تائب ہو گئے۔ بالفرض تائب نہ بھی ہوئے ہوں تو بھی سچے آدمی کی بات معتبر ہونی ہے چاہے کسی عقیدے پر ہو بشرطیکہ اپنے مخصوص عقیدے کی حمایت میں بیان نہ کرے۔\n2۔ صحابہ کا سائل کو ایک دوسرے کے پاس بھیجنا اس حسن ظن کی بنا پر ہے کہ دوسرا صحابی مجھ سے زیادہ علم رکھتا ہے اور یہ حسن ظن علم کی دلیل ہے ورنہ علم پندار (غرور) بسا اوقات عالم کولے ڈوبتا ہے۔ اعاذنا اللہ منہ.\n3۔ ’’ابو حفص‘‘ یہ سیدنا عمر رضی اللہ عنہ کی کنیت ہے جو ان کی بڑی بیٹی سیدہ حفصہ رضی اللہ عنہا ام المومنین کی نسبت سے مشہور ہوئی۔ عرب میں کنیت سے ذکرکرنا راحترام کی علامت ہوتا تھا۔\n4۔ ’’کوئی حصہ نہیں ‘‘ یہ الفاظ بطور زجر و توبیح اور ڈانٹ کےہیں۔ ظاہر الفاظ مقصود نہیں ہوتے۔ دیگر احادیث اس تاویل کی تائید کرتی ہیں۔ کسی ایک حدیث کو باقی احادیث سے الگ نہیں کیا جاسکتا۔ ایک مسئلے کےبارے میں آنے والی تمام روایات کوملا کر نتیجہ نکالاجاتا ہے۔ (مسئلے کی تفصیل کے لیے دیکھیے، احادیث:5297، 5306)"}],[5307,"عبداللہ بن عمر رضی اللہ عنہما روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"حریر نامی ریشم تو وہی پہنتا ہے جس کا (آخرت میں) کوئی حصہ نہیں\"۔","الألباني: صحيح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نےفرمایا: ’’ریشم تو وہ لوگ پہنتے یہں جن کا آخرت میں کوئی حصہ نہیں۔‘‘","f2":"دیکھیے، حدیث:5297۔"}],[5308,"علی بارقی رضی اللہ عنہ کہتے ہیں کہ ایک عورت میرے پاس مسئلہ پوچھنے آئی تو میں نے اس سے کہا: یہ ابن عمر رضی اللہ عنہما ہیں، (ان سے پوچھ لو) وہ مسئلہ پوچھنے ان کے پیچھے گئی اور میں بھی اس کے پیچھے گیا تاکہ وہ جو کہیں اسے سنوں، وہ بولی: مجھے حریر نامی ریشم کے بارے میں بتائیے، ابن عمر رضی اللہ عنہما نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے اس سے منع فرمایا ہے۔","الألباني: صحيح",{"u2":"حضرت علی بارقی رحمہ اللہ سے بیان کرتے ہیں کہ میرے پاس ایک عورت مسئلہ پوچھنے آئی۔ میں نے اسے کہا: یہ سیدنا ابن عمر رضی اللہ عنہ تشریف فرما ہیں (ان سے پوچھ)۔ وہ ان کی طرف مسئلہ پوچھنے چلی اور میں بھی اس کے ساتھ چلاتا کہ سیدنا ابن عمر رضی اللہ عنہ کا جواب سن سکوں۔ وہ ان سے کہنے لگی: مجھے ریشم کے بارے میں فتوی دیجیے۔ انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے اس سے منع فرمایاہے۔","f2":"’’منع فرمایاہے ‘‘ یعنی مردوں کو نہ کہ عورتوں کہ جیسے کہ صحیح اور صریح احادیث گزر چکی ہیں۔"}],[5309,"براء بن عازب رضی اللہ عنہما کہتے ہیں کہ ہمیں رسول اللہ صلی اللہ علیہ وسلم نے سات باتوں کا حکم دیا اور سات باتوں سے منع فرمایا: \"آپ نے ہمیں سونے کی انگوٹھی سے، چاندی کے برتن سے، ریشمی زین سے، قسی، استبرق، دیبا اور حریر نامی ریشم کے استعمال سے منع فرمایا \"۱؎۔\n§وضاحت\n۱؎: یہ سب ریشم کی اقسام ہیں۔","الألباني: صحيح",{"u2":"سیدنا براء بن عازب رضی اللہ عنہ سے روایت ہے انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے ہمیں سات کاموں کا حکم دیا اور سات سے منع فرمایا۔ آپ نے ہمیں سونے کی انگوٹھیوں،چاندی کے برتنوں،ریشمی گدیلوں، قسی کپڑوں، موٹے، باریک اور عام ریشم پہننے سےمنع فرمایا۔","f2":"1۔ قسی کپڑوں اور ریشمی گدیلوں کی تفصیل کےبارے میں ملاحظہ فرمائیں احادیث:5168، 5169۔\n2۔’’موٹے،باریک اور عام ریشم‘‘ عربی میں استبرق، دیباج اور حریر کے لفظ آئے ہیں۔ یہ تینوں ریشم کی اقسام ہیں۔ تفصیل احادیث 5301، 5302میں گزر چکی ہے۔ مقصد یہ ہے کہ ہر قسم کے ریشم کے استعمال سے منع فرمایا گیا مگر یہ نہی مردوں کےلیے ہے البتہ چاندی کے برتنوں اور ریشمی گدیلوں سے نہی سےمرد وعورت سب کےلیے ہے کیونکہ یہ مشترکہ استعمال کی اشیاء ہیں۔"}],[5310,"انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے عبدالرحمٰن بن عوف اور زبیر بن عوام رضی اللہ عنہما کو کھجلی کی وجہ سے جو انہیں ہو گئی تھی ریشم کی قمیص (پہننے) کی اجازت دی ۱؎۔\n§وضاحت\n۱؎: یہ اجازت عذر :(کھجلی ) کی بنا پر تھی، اس لیے صرف عذر تک کی اجازت رہے گی، عذر ختم ہو جانے کے بعد ایسی قمیص نکال دینی ہو گی، یہ پوری قمیص پہننے کے بارے میں ہے، اور جہاں تک صرف ریشم کے بٹن کی بات ہے تو یہ مردوں کے لیے ہر حالت میں جائز ہے۔ :(دیکھئیے حدیث نمبر ۵۳۱۴ )","الألباني: صحيح",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے حضرت عبد الرحمن بن عوف اور سیدنا زبیر بن عوام رضی اللہ عنہ کو خارش کی بنا پر ریشم کی قمیص پہننے کی اجازت دے دی تھی","f2":"1۔ مردوں کےلیے بھی بعض حالتوں میں ریشم کا استعمال جائز ہے مثلا: اگر کسی کا خارش ہو تو بطور علاج ریشم کا لباس پہن سکتا ہے۔\n2۔ یہ حدیث مبارکہ اس بات پر بھی دلالت کرتی ہے کہ شریعت مطہرہ انتہائی آسان ہے نیز اس کے ساتھ ساتھ اس میں ضرورت مند او رمکلف لوگوں کی سہولت کا بھی پورا پورا لحاظ رکھا گیا ہے۔\n3۔ یہ دوران سفر کا واقعہ ہے اس لیے بعض فقہاء نے خارش کےساتھ ساتھ سفر کی شرط بھی لگائی گئی ہے کیونکہ گھر میں تو خارش کا اور علاج بھی ممکن ہے۔لیکن راجح بات یہی ہے کہ بطور علاج بہ حالت اقامت بھی اس کا استعمال جائز ہے۔ واللہ اعلم."}],[5311,"انس رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے عبدالرحمٰن اور زبیر رضی اللہ عنہما کو ریشم کی قمیص کی اجازت دی اس مرض یعنی کھجلی کے سبب جو انہیں ہو گئی تھی۔","الألباني: صحيح",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے حضرت عبد الرحمن اور زبیر رضی اللہ عنہما کو خارش کی وجہ سے ریشم کی قمیص پہننے کی اجازت دی۔","f2":"ریشم کی قمیص پہننے کی اجازت ہے اگر ضرورت محسوس ہو تو ریشم کی شلوار وغیرہ بھی پہن سکتا ہے۔"}],[5312,"ابوعثمان النہدی کہتے ہیں کہ ہم عتبہ بن فرقد کے ساتھ تھے کہ عمر رضی اللہ عنہ کا فرمان آیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: \"ریشم تو وہی پہنتا ہے جس کا اس میں سے آخرت میں کوئی حصہ نہیں مگر اتنا\"، ابوعثمان نے انگوٹھے کے پاس والی اپنی دونوں انگلیوں کے اشارے سے کہا، میں نے دیکھا وہ طیلسان کے کپڑوں کے چند بٹن تھے، یہاں تک کہ میں نے طیلسان کا کپڑا بھی دیکھا۔","الألباني: صحيح",{"u2":"حضرت ابو عثمان نہدی بیان کرتے ہیں کہ ہم سیدنا عتبہ بن فرقد رضی اللہ عنہ کے ساتھ تھے کہ ہمارے پاس (امیر المومنین) سیدنا عمر رضی اللہ عنہ کی تحریر پہنچی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ریشم تو وہی شخص پہنتا ہے جس کا آخرت میں اس (ریشم) سے کوئی حصہ نہیں البتہ اتناپہن سکتا ہے۔ ‘‘ حضرت ابو عثمان نے انگوٹھے کے ساتھ والی دوانگلیوں کےساتھ اشارہ کیا ہے۔ میں نے سمجھا کہ اس سے مراد چادروں کے کناروں والی پٹیاں ہیں حتی کہ جب میں نے طیلسان کی چادریں دیکھیں تو مجھے یقین آیا۔","f2":"1۔ اس حدیث مبارکہ سے جہاں بعض ضرورتوں کے تحت مردوں کے لیے ریشم کا لباس استعمال کرنے کی اجازت معلوم ہوتی ہے وہاں یہ بھی معلوم ہوتا ہے کہ بلاضرورت دویا چار انگلیوں کےبرابر ریشم کا حاشیہ اور پٹی لگائی سکتی ہے۔\n2۔ یہ حدیث مبارکہ ان لوگوں کی دلیل ہے جولباس میں ریشمی پٹی اور کنارے وغیرہ کے قائل ہیں۔\n3۔ اس حدیث مبارکہ سے یہ بھی استدلال ہو سکتا ہے کہ احادیث میں مذکورہ ریشم کی مقدار (دویا چار انگلیوں کے برابر) ایک ہی جگہ یا الگ الگ جگہوں پر استعمال کی جاسکتی ہے۔ اس میں شرط صرف یہ ہے کہ احادیث میں بیان کردہ مقدار سےزیادہ ریشم استعمال نہ کیا جائے۔\n4۔ ’’اتنا پہن سکتاہے ‘‘ چادروں اور قمیص کے کنارے کی پٹی سے بند کر دیے جاتے ہیں مثلا: دامن، کریبان اور باز وغیرہ۔ اس میں کوئی حرج نہیں۔ کبھی کبھار ریشمی پٹیاں کندھوں پر بھی لگادی جاتی ہیں۔ ان میں بھی کوئی حرج نہیں البتہ وہ زیادہ چوڑی نہ ہوں۔\n5۔ ’’تو مجھے یقین آیا ‘‘ گویا طیلسان ایک قسم کی چادر ہوتی تھی جسے کندھوں پر ڈالا جاتا تھا۔ کناروں پر ریشم کی پٹی لگی ہوتی تھی۔ یہ جملہ کہنے والے حضرت ابوعثمان نہدی کے شاگرد حضرت سلیمان تیمی ہیں۔"}],[5313,"عمر رضی اللہ عنہ سے روایت ہے کہ انہوں نے دیباج کی اجازت صرف چار انگلی تک دی گئی ہے ۱؎۔\n§وضاحت\n۱؎: یعنی چار انگل دیباج کے استعمال میں کوئی حرج نہیں۔","الألباني: صحيح",{"u2":"سیدنا عمر رضی اللہ عنہ سے روایت ہے کہ (مردوں کو) ریشم پہننےکی اجازت نہیں مگر چار انگلیوں کے برابر پٹی۔","f2":"سابقہ روایت میں دوانگلی کا ذکر تھا اس میں چار کا ہے۔ جمہور اہل علم چار انگلی کی پٹی کو جائز سمجھتے ہیں، زیادہ کو نہیں کیونکہ اس سے زائد کی اجازت مروی نہیں۔"}],[5314,"براء رضی اللہ عنہ کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم کو دیکھا، آپ لال جوڑا ۱؎ پہنے ہوئے اور کنگھی کیے ہوئے تھے، میں نے آپ سے زیادہ خوبصورت کسی کو نہیں دیکھا، نہ آپ سے پہلے، نہ آپ کے بعد۔\n§وضاحت\n۱؎: متعدد صحیح احادیث میں یہ بات صراحت کے ساتھ آئی ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے مردوں کے لیے لال رنگ کو ناپسند فرمایا ہے، :(دیکھئیے حدیث نمبر ۵۳۱۸، اور بعد کی حدیثیں ) آپ کی مذکورہ چادر میں تھوڑی سی لال رنگ کی ملاوٹ تھی، یا لال رنگ سے آپ نے اس کے بعد منع فرمایا تھا۔ :(لال رنگ کے جواز اور عدم جواز کے بارے میں تفصیلی بحث کے لیے دیکھئیے فتح الباری میں اس حدیث کی شرح، کتاب اللباس، باب الثوب الأحمر )۔","الألباني: صحيح",{"u2":"سیدنا براء رضی اللہ عنہ بیان کرتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم کو سرخ حلہ پہننے ہوئے دیکھا۔ آپ نے بالوں کو کنگھی کر رکھی تھی۔ میں نے کوئی شخص آپ سے بڑھ کر خوب صورت نہیں دیکھا نہ آپ سے پہلے نہ آپ کے بعد۔","f2":"حلہ دو چادروں کے جوڑے کو کہتے ہیں۔ ایک تہبند دوسری اوپر والی چادر۔ عرب میں یہ بہترین لباس سمجھا جاتا تھا۔ اگر حلہ ریشمی نہ ہو تو پہننا جائز ہے۔"}],[5315,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ قبیلہ عرینہ کے کچھ اعرابی (دیہاتی) نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے اور اسلام قبول کیا، انہیں مدینے کی آب و ہوا راس نہیں آئی، یہاں تک کہ ان کے رنگ پیلے پڑ گئے، ان کے پیٹ پھول گئے تو نبی اکرم صلی اللہ علیہ وسلم نے انہیں دودھ والی اونٹنیوں کے پاس بھیجا اور انہیں حکم دیا کہ وہ ان کا دودھ اور پیشاب پئیں، یہاں تک کہ جب وہ ٹھیک ہو گئے تو انہوں نے ان چرواہوں کو قتل کر دیا اور اونٹوں کو ہانک لے گئے، نبی اکرم صلی اللہ علیہ وسلم نے ان کی تلاش میں کچھ لوگ بھیجے، انہیں لایا گیا تو آپ نے ان کے ہاتھ اور پیر کاٹ دیے، اور ان کی آنکھوں میں گرم سلائی پھیر کر ان کو پھوڑ دیا۔ امیر المؤمنین عبدالملک نے انس رضی اللہ عنہ سے کہا (وہ ان سے یہ حدیث بیان کر رہے تھے): کفر (ردت) کی وجہ سے یا جرم کی وجہ سے (ان کے ساتھ ایسا کیا گیا) ؟ انہوں نے کہا: کفر(ردت) کی وجہ سے۔\nانس رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کا سب سے زیادہ پسندیدہ کپڑا یمن کی سوتی چادر تھی۔","الألباني: صحيح الإسناد",{"u2":"سیدنا انس رضی اللہ عنہ نے فرمایا:نبی اکرم صلی اللہ علیہ وسلم کوسب سے پسندیدہ کپڑا دھاری دار چادر تھی۔","f2":"اس حدیث مبارکہ سے واضح طور پر معلوم ہوتا ہے کہ دھاری دار کپڑے پہننے جاسکتے ہیں۔ دھاری دار کپڑاجلدی میلا محسوس نہیں ہوتا۔ اسی لیے آپ کو زیادہ پسند تھا نیز ایسا کپڑا دیکھنے میں بھلا محسوس ہوتا ہے۔ واللہ اعلم ."}],[5316,"عبداللہ بن عمرو رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ان کو دیکھا، وہ دو کپڑے زرد رنگ کے پہنے ہوئے تھے، آپ نے فرمایا: \"یہ کفار کا لباس ہے، اسے مت پہنو\"۔","الألباني: صحيح",{"u2":"سیدنا عبد اللہ بن عمرو رضی اللہ عنہ نے بتایا کہ رسول اللہ صلی اللہ علیہ وسلم نے انہیں معصفرکپڑے پہنے ہوئے دیکھا تو فرمایا: ’’یہ تو کافروں کالباس ہے۔ تو نہ پہن۔‘‘","f2":"معصفر سےمراد وہ کپڑا ہے جسے عصفر یعنی کسنبے سے رنگا گیا ہو۔ یہ زرد سرخ سا رنگ ہوتا ہے دیکھنے میں عجیب سا لگتا ہے۔ مردوں کی مردانگی کے خلاف ہے۔ باوقار نہیں اس لیے آپ نے اس سے منع فرمایا۔ سیدنا ابن عمر رضی اللہ عنہ سے اس رنگ کے کپڑے پہننا مذکورہے ہے۔ ممکن ہے ان کو نہی کا علم نہ ہو۔"}],[5317,"عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ وہ نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے، وہ پیلے رنگ کے دو کپڑے پہنے ہوئے تھے، یہ دیکھ کر نبی اکرم صلی اللہ علیہ وسلم غصہ ہوئے اور فرمایا: \"جاؤ اور اسے اپنے جسم سے اتار دو\"۔ وہ بولے: کہاں؟ اللہ کے رسول! آپ نے فرمایا: \"آگ میں\" ۱؎۔\n§وضاحت\n۱؎: چنانچہ انہوں نے اسے گھر کے تنور میں ڈال دیا، صحیح مسلم کی روایت میں ہے کہ خود رسول اللہ صلی اللہ علیہ وسلم نے آگ میں ڈال دینے کا حکم دیا، ایسا صرف زجر و توبیخ کے لیے تھا، ورنہ اس نوع کا کپڑا عورتوں کے لیے جائز ہے، نیز بیچ کر کے قیمت کا استعمال بھی جائز ہے۔","الألباني: صحيح",{"u2":"سیدنا عبد اللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ وہ نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے جبکہ انہوں نےمعصفر کپڑے پہن رکھتے تھے۔نبی اکرم صلی اللہ علیہ وسلم (دیکھ کر) ناراض ہوئے اور فرمایا:’’ جا ان کو اتار پھینک۔‘‘ انہوں نے عرض کی: کہاں پھینکوں؟ فرمایا: آگ میں۔‘‘","f2":"’’آگ میں‘‘ اور عبد اللہ بن عمرو رضی اللہ عنہ نے واقعتا ان کو تنور میں جلا ڈالا۔ رضي الله عنه وأضاه. اگرچہ ممکن ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے غصے میں فرمایا ہو اور آپ کا مقصد یہ نہ ہو کیونکہ ایسا کپڑا عورت استعمال کر سکتی ہے لہذا وہ گھر کی عورتوں کو دیا جاسکتا ہے۔ شاید اس کی وضع ایسی ہو کہ وہ عورتوں کےاستعمال میں نہ آسکتا ہو۔ ورنہ مال ضائع کرنا درست نہیں جیسے آپ نے سونے کی انگوٹھی کے بارے میں فرمایا کہ میرا مقصد اسے ضائع کرنے کا نہیں تھا۔ دیکھیے: (حدیث5292) لیکن دونوں واقعات میں صحابی کی نیت نیک تھی اور آپ کے ظاہر الفاظ ضائع کرنے کا تاثر دیتے تھے اس لیے ان کا یہ کام موجب اجر و ثواب اور باعث فضیلت ہے کہ انہوں نے نبی اکرم صلی اللہ علیہ وسلم کی ناراضی کے مدنظر اپنے مالی نقصان کی پرواہ نہ کی۔ رضی اللہ عنہ"}],[5318,"علی رضی اللہ عنہ کہتے ہیں کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے سونے کی انگوٹھی سے، ریشمی کپڑوں سے، زعفرانی رنگ کے لباس سے، اور رکوع میں قرآن پڑھنے سے منع فرمایا ہے۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ فرمایا کرتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے سونے کی انگوٹھی قسی ارو معصفر کپڑے پہننے اور دوران رکوع (اورسجود) قرآن مجید پڑھنے سے منع فرمایا۔"}],[5319,"ابورمثہ رضی اللہ عنہا کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم (ایک بار گھر سے) باہر نکلے، آپ دو ہرے کپڑے پہنے ہوئے تھے۔","الألباني: صحيح",{"u2":"سیدنا ابو رمثہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم (ایک دفعہ گھر سے) باہر تشریف لائے جبکہ آپ نے دو سبز چادریں پہن رکھی تھیں۔"}],[5320,"خباب بن ارت رضی اللہ عنہ کہتے ہیں کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم سے (کفار و مشرکین کی ایذا رسانی کی) شکایت کی، اس وقت آپ چادر کا تکیہ لگائے ۱؎کعبہ کے سائے میں بیٹھے ہوئے تھے، ہم نے کہا: کیا آپ ہمارے لیے مدد طلب نہیں کریں گے؟ کیا آپ اللہ تعالی سے ہمارے لیے دعائیں نہیں کریں گے؟۔\n§وضاحت\n۱؎: اسی جملے میں باب سے مطابقت ہے۔","الألباني: صحيح",{"u2":"سیدنا خباب بن ارث رضی اللہ عنہ نے فرمایا: ہم نے رسول اللہ سے (کفارکی طرف سے پہنچنےوالی تکالیف کی) شکایت کی۔ آپ نے اس وقت کعبے کے سائے میں ایک سیاہ دھاری دار چادر کو تکیہ بنا کر لیٹے ہوئے تھے۔ ہم نے کہا: آپ ہمارے لیے اللہ تعالیٰ سے مدد و نصرت طلب نہیں فرماتے؟ ہمارے لیے اللہ تعالیٰ سے دعا نہیں فرماتے","f2":"1۔ترجمتہ الباب کےساتھ حدیث کی مناسبت اس طرح بنتی ہے کہ ایسی دھاری دار چادر کو بطور تکیہ استعمال کیا۔ اس سےمعلوم ہوتا ہے جو چادر بطور تکیہ استعمال ہو سکتی ہے وہ پہنی بھی جاسکتی ہے۔\n2۔ یہ حدیث مبارکہ اس چیز پر واضح طور پر دلالت کرتی ہے کہ دعورت الی اللہ اور تبلیغ دن میں بے پناہ مشکلات او رآزمائشیں آسکتی ہیں لہذا ایسی صورت حال درپیش ہو توصبر کا دامن کسی بھی صورت میں ہاتھ سے نہیں چھوڑنا چاہیے۔ اللہ کی راہ میں مقدر بننے والی مشکلات پر صبر کرنے والوں کو عزت و نصرت او رمحبت الہی کی بشارت مبارک ہو۔\n3۔ رویت طویل ہے۔ مصنف رحمہ اللہ نے متعلقہ حصے کا ذکر فرمادیا۔\n4۔ ’’سیاہ دھاری دار چادر‘ یہ ترجمہ ہے عربی لفظ بردۃ کا۔یہ چادریں ایسی ہوتی تھیں۔"}],[5321,"سہل بن سعد رضی اللہ عنہ کہتے ہیں کہ ایک عورت ایک چادر لے کر آئی، جانتے ہو وہ کیسی چادر تھی؟ لوگوں نے کہا: ہاں، یہی شملہ، اس کی گوٹا کناری بنی ہوئی تھی، وہ بولی: اللہ کے رسول! میں نے یہ اپنے ہاتھ سے بنی ہے تاکہ آپ کو پہناؤں، رسول اللہ صلی اللہ علیہ وسلم نے اسے لے لیا کیونکہ آپ کو اس کی ضرورت تھی، پھر آپ باہر نکلے اور ہمارے پاس آئے اور آپ اسی کا تہبند باندھے ہوئے تھے۔","الألباني: صحيح",{"u2":"سیدنا سہل بن سعد رضی اللہ عنہ نے فرمایا: ایک عورت ایک بردہ لے کر آئی .......پھر حضرت سہل نے شاگردوں سے پوچھا: کیا تم جانتے ہو بردہ کیا ہوتی ہے؟انہوں نے کہا: جی ہاں! یہی سیاہ دھاری دار چادر جس کا کنارہ بھی ساتھ ہی بناگیا ہو ...... اورکہا: اے اللہ کے رسول! میں نے یہ چادر اپنے ہاتھ سے نبی ہے۔ میں آپ کو پہننے کےلیے پیش کرتی ہوں۔ رسول اللہ صلی اللہ علیہ وسلم نے اسے لے لیا جبکہ آپ کو اس کی ضرورت بھی تھی۔ پھر آپ (گھر سے ہوکر) ہماری طرف تشریف لائے تو آپ نے اسے بطور ازار (تہبند) باندھ رکھا تھا۔","f2":"حاکم وقت رعایا کی طرف سے تحفہ قبول کر سکتا ہے نیز اس سے سیاہ دھاری دار چادر کے استعمال کا جواز بھی معلوم ہوا۔"}],[5322,"سمرہ رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"سفید کپڑے پہنا کرو، اس لیے کہ یہ زیادہ پاکیزہ اور عمدہ ہوتے ہیں اور اپنے مردوں کو سفید کفن دیا کرو\"۔ (عمرو بن علی کہتے ہیں کہ) یحیی نے کہا: میں نے اس روایت کو نہیں لکھا، میں نے کہا: کیوں؟ کہا: میمون بن ابی شبیب کی وہ روایت جو سمرہ رضی اللہ عنہ سے ہے وہی میرے لیے کافی ہے ۱؎۔\n§وضاحت\n۱؎: جس کو ابن ماجہ اور ترمذی نے روایت کیا ہے۔","الألباني: صحيح",{"u2":"سیدنا سمرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’سفید کپڑے پہنا کرو۔ وہ زیادہ پاکیزہ او رصاف ستھرے رہتے ہیں اور فوت شدگان کو بھی انہی میں کفناؤ۔‘‘","f2":"1۔ امر یہاں استحباب کے معنی ہے یعنی سفید کپڑے ہی پہننا ضروری نہیں بلکہ دوسرے مباح رنگوں کے کپڑے بھی جائز ہیں کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے دوسرے رنگوں کے کپڑے بھی استعمال کیے اور صحابہ بھی کرتے تھے یہی حکم کفن کا ہے۔\n2۔’’پاکیزہ او ر صاف ستھرے‘‘ کیونکہ سفید رنگ میں داغ دھبہ بہت جلد نظر آجاتا ہے۔ اسے جتنا زیادہ دھویا جائے گا اتنا ہی پاکیزہ اور صاف ستھرا رہے گا جب کہ بعض رنگوں میل کچیل نظر نہیں آتا خواہ عرصہ دراز تک ایسے کپڑے نہ دھوئے جائیں۔ حقیقتاً وہ گندے اور بسااوقات پلید بھی رہتے ہیں۔\n3۔ ’’فوت شدگان‘‘ کیونکہ ان کےلیے سادگی اورصفائی دونوں مناسب ہیں۔ اور سفید کپڑے میں یہ دونوں وصف بدرجہ اتم پاتے جاتے ہیں۔"}],[5323,"سمرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم سفید کپڑوں کو پہنو، زندہ اسے پہنیں اور مردوں کو اسی کا کفن دو کیونکہ یہی کپڑوں میں سب سے عمدہ کپڑا ہے\"۔","الألباني: صحيح",{"u2":"سیدنا سمرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ سفید کپڑے پہنا کرو۔ زندہ لوگ بھی اسے پہنیں اور فوت شدگان کو بھی انہی میں کفن دو۔ یہ بہترین کپڑے ہیں۔‘‘"}],[5324,"مسور بن مخرمہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے قبائیں تقسیم کیں اور مخرمہ کو کچھ نہیں دیا تو مخرمہ رضی اللہ عنہ نے کہا: بیٹے! مجھے رسول اللہ صلی اللہ علیہ وسلم کے پاس لے چلو، چنانچہ میں ان کے ساتھ گیا، انہوں نے کہا: اندر جاؤ اور آپ کو میرے لیے بلا لاؤ، چنانچہ میں نے آپ کو بلا لایا، آپ نکل کر آئے تو آپ انہیں میں سے ایک قباء پہنے ہوئے تھے، آپ نے فرمایا: \"اسے میں نے تمہارے ہی لیے چھپا رکھی تھی\"، مخرمہ نے اسے دیکھا اور پہن لی۔","الألباني: صحيح",{"u2":"سیدنا مسور بن مخرمہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے قبائیں تقسیم کیں لیکن (میرے والد) حضرت مخرمہ کو کچھ نہ دیا تو سیدنا مخرمہ رضی اللہ عنہ نے کہا: بیٹا!آؤ رسول اللہ کے پاس چلیں۔ میں ان کے ساتھ چل پڑا (وہاں پہنچ کر) انہوں نے کہا: جاؤ آپ صلی اللہ علیہ وسلم کو باہر لاؤ۔ میں نے آپ کو بلایا تو آپ تشریف لے آئے تو آپ پر ان میں سے ایک قبا تھی۔ آپ نے فرمایا: ’’میں نے یہ تمہارے لیے چھپا رکھی تھی۔ ‘‘ والد محترم سیدنا مخرمہ رضی اللہ عنہ نے اسے دیکھا اور پہن لیا۔","f2":"1۔ امام نسائی رحمہ اللہ نے جو ترجمتہ الباب قائم کیا ہے اس کا مقصد یہ مسئلہ بیان کرنا ہے کہ چوغہ لمبی او رکھلی قمیص او راوور کوٹ پہننا جائز اور درست ہے البتہ اس میں یہ خیال رکھنا ضروری ہے کہ مرد جب ایسا لباس پہنیں تو ان کے ٹخنے ہر صورت میں ننگے ہونے چاہییں کیونکہ مردوں کے لیے ٹخنوں سے نیچے کپڑا لٹکانا حرام اور ناجائز ہے۔\n2۔ مخرمہ رضی اللہ عنہ نابینے تھے اس لیے وہ اپنے بیٹے کےہمراہ نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے۔ رسول اللہ صلی اللہ علیہ وسلم نے اپنے غریب اور نابینے صحابی کی دلجوئی فرمائی اور انہیں قبا پیش فرمائی اور ساتھ یہ بھی فرمایا کہ یہ ہم نے تمہارے لیے چھپا رکھی تھی تاکہ اس کی تالیف قلب ہو۔ صلی اللہ علیہ ولسم کثیرا کثیرا۔\n3۔ بعض لوگوں نے حضرت مسور کے صحابی ہونے کاانکار کیا لیکن اس حدیث سے ان لوگوں کی تردید ہوتی ہے۔ یہ حدیث سیدنا مسور رضی اللہ عنہ صحابی ہونے کی صریح دلیل ہے۔ واللہ اعلم۔\n4۔ قبا قمیص کی طرح ہوتی ہے مگر قمیص سے لمبی او ر کھلی ہوتی ہے اوور کوٹ کی طرح اس کے بٹن نہیں ہوتے۔"}],[5325,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ انہوں نے عرفات میں نبی اکرم صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"جسے تہبند نہ ملے تو وہ پاجامہ پہن لے، اور جسے چپل نہ ملے وہ خف (چمڑے کے موزے) پہن لے\" ۱؎۔\n§وضاحت\n۱؎: جب احرام کی حالت میں پاجامہ پہن سکتے ہیں تو احرام کے علاوہ حالت میں بدرجہ اولی پہن سکتے ہیں یہی باب سے مناسبت ہے۔","الألباني: صحيح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہ میں نے نبی اکرم صلی اللہ علیہ وسلم کوعرفات میں فرماتےسنا: ’’جوشخص (احرام کی حالت میں) تہبند نہ پائے وہ شلوار پہن سکتا ہے اور جوشخص جوتے نہ پائے وہ موزے پہن سکتا ہے۔ ‘‘","f2":"1۔ مقصد یہ ہے کہ اگر احرام کےلیے ان سلی چادریں میسر نہ ہوں تو مردوں کےلیے شلوار پہننا جائز ہے۔ یاد رہے کہ یہ صرف مجبوری کی حالت میں ہے عام حالات میں ایسا کرنا درست نہیں۔\n2۔اس حدیث مبارکہ سے یہ اہم مسئلہ معلوم ہوا کہ اگر کسی کے پاس جوتے نہ ہوں تو وہ ان کی جگہ موزے پہن سکتا ہے خواہ وہ کٹے ہوئے ہوں یا کٹے ہوئے نہ ہوں۔ کیونکہ یہ حدیث بعد کی ہے یعنی حجۃ الوداع کا واقعہ ہے۔ تو جب اس میں کاٹنے کا ذکر نہیں تویہ اس بات کی دلیل ہے کہ سابقہ کاٹنے کاحکم مسنوخ ہے یہ رائے حنابلہ کی ہے۔ جمہور اہل علم کی رائے یہ ہے کہ اگر محرم موزے پہنے تو انہیں کاٹ لے کیونکہ دیگر احادیث میں کاٹنے کا ذکر ہے۔ واللہ اعلم"}],[5326,"عبداللہ بن عمر رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک شخص تکبر (گھمنڈ) سے اپنا تہبند لٹکاتا تھا،) تو اسے زمین میں دھنسا دیا گیا، چنانچہ وہ قیامت تک زمین میں دھنستا جا رہا ہے\" ۱؎۔\n§وضاحت\n۱؎: اگر کسی مجبوری سے خود سے پاجامہ :(تہبند ) ٹخنے سے نیچے آ جاتا ہے تو اس میں کوئی حرج نہیں ہے، اور \" تکبر سے \" کی قید احتراز نہیں ہے، :(کہ اگر تکبر سے تہبند لٹکائے تو حرام ہے، ورنہ نہیں ) بلکہ یہ لفظ اس لیے آیا ہے کہ عام طور سے تہبند کا لٹکانا پہلے تکبر اور گھمنڈ ہی سے ہوتا تھا، بہت سی روایات میں لفظ «خیلاء» نہیں ہے، «ازار» میں وہ سارے کپڑے شامل ہیں جو تہبند :(لنگی ) کی جگہ پہنے جاتے ہیں، دیکھئیے حدیث نمبر ۵۳۳۱- ۵۳۳۷۔","الألباني: صحيح",{"u2":"سیدنا عبد اللہ بن عمر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ایک دفعہ ایک شخص تکبر سے اپنا تہبند زمین پر گھسیٹتا چلا جارہا تھا کہ اسے زمین میں دھنسا دیا گیا۔ وہ قیامت تک زمین میں دھنستا ہی رہےگا۔‘‘","f2":"1۔ تہ بند،شلوار اور پینٹ وغیرہ زمین پر گھسیٹ کر چلنا کبیرہ گناہ ہے جس کی تفصیل درج ذیل ہے:جوشخص اپنا کپڑا (تہبند، شلوار اور پینٹ) زمین پر گھسیٹ کر چلتا ہے تو اس کی دوہی وجہیں ہو سکتی ہین: ایک تو یہ کہ ایسا کرنے والا شخص ازراہ تکبر ہی اس طرح کرتا ہے۔ یہ شرعا ناجائز ہے اور حرام ہے اور قیامت والے دن ایسے شخص کی طرف اللہ نظر رحمت سے نہیں دیکھے گا، نہ ایسے شخص سے کلام فرمائے گا اور نہ اسے پاک ہی کرے گابلکہ اس کےلیے دردناک عذاب ہو گا: (صحیح مسلم، الایمان، باب بیان غلظ تحریم اسبال الازار ........حدیث:293، 294) دوسری وجہ غفلت وسستی اور مداہنت ہے۔ احکام شریعت کی بجاآوری میں سستی وغفلت و مداہنت بھی جرم ہے اس لیے ایسے شخص کی بابت رسول اللہ صلی اللہ علیہ وسلم کا واضح فرمان ہے: ’’ٹخنوں سے نیچے جہاں تک تہبند ہو گا تو وہ (حصہ جسم) کی آگ میں جلے گا۔‘‘ (صحیح البخاری،اللباس، باب ما اسفل الکعبین فھو فی النار، حدیث 578)یہ بات یاد رہے کہ چار قسم کے لوگ اس وعید سے شدیدمستثنی ہیں:\n٭عورتیں کہ ان کو حکم ہے کہ وہ اپنا کپڑا اتنا نیچے کریں کہ چلتے وقت پاؤں ننگے نہ ہوں۔\n٭اٹھتے وقت بے خیالی میں کپڑا ٹخنوں سے نیچے ہو جائے۔\n٭کسی کا پیٹ اور توندی بڑی ہو یا کمر پتلی ہو اور کوشش کے باوجود کبھی کبھار کپڑا ٹخنوں سے نیچے ہو جائے۔\n٭پاؤں یا ٹخنوں سے نیچے کوئی زخم ہو تو گردوغبار او رمکھیوں سے حفاظت کے پیش نظر کپڑا نیچے کرنا۔ (مختصر صحیح بخاری (اردو) فوائد حدیث:1984)\n2۔’’ایک شخص ‘‘ یہ شخص امت مسلمہ سے نہیں بلکہ بنی اسرائیل سے تھا۔ ظاہر تویہی ہے کہ قارون کے علاوہ کوئی اور شخص ہو گا۔ واللہ اعلم."}],[5327,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے تکبر (گھمنڈ) سے اپنا کپڑا (ٹخنے سے نیچے) لٹکایا (یا یوں فرمایا: جو شخص تکبر سے اپنا کپڑا لٹکاتا ہے) اللہ تعالی قیامت کے دن اس کی طرف نہیں دیکھے گا\"۔","الألباني: صحيح",{"u2":"سیدنا عبد اللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جوشخص تکبر کے ساتھ اپنا کپڑا زمین پر گھسیٹتا ہے قیامت کے دن اللہ اسے (نظر رحمت سے) نہیں دیکھے گا۔‘‘","f2":"’’اپنا کپڑا‘‘ گویا ازرا کے علاوہ قمیص یا چادر کو بھی زمین پر گھسیٹنا جائز نہیں جب کہ بعض فقہاء نے یہاں کپڑے سے مراد تہبند ہی لیا ہے۔ گویا قمیص لٹکا سکتا ہے مگر یہ اس صریح اور واضح حکم شریعت کے خلاف ہے۔ واللہ اعلم"}],[5328,"عبداللہ بن عمر رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے (ٹخنے سے نیچے) اپنا کپڑا تکبر سے لٹکایا، اللہ تعالی قیامت کے دن اس کی طرف نہیں دیکھے گا\"۔","الألباني: صحيح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جوشخص تکبر کے ساتھ اپنا کپڑا زمین پر گھسیٹے گا اللہ عزوجل قیامت کے دن اس کو (نظر رحمت سے) نہیں دیکھے گا۔‘‘","f2":"مذکورہ احادیث میں تکبر کی قید اتفاقی ہے کیونکہ دوسری حدیث میں صراحت ہے کہ لٹکانا از خود تکبر ہے۔"}],[5329,"حذیفہ بن الیمان رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تہبند آدھی پنڈلی تک جہاں گوشت ہوتا ہے ہونا چاہیئے۔ اگر ایسا نہ ہو تو کچھ نیچے، اور اگر ایسا بھی نہ ہو تو پنڈلی کے اخیر تک، اور ٹخنوں کا تہبند میں کوئی حق نہیں\"۔","الألباني: صحيح",{"u2":"سیدنا خذیفہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تہبند کی جگہ نصف پنڈلی ہے۔ جہاں موٹا پٹھہ ہوتا ہے۔ اگر تو وہاں تک نہیں چاہتا تو کچھ نیچا کر لے اور اگر وہاں بھی نہیں رکھنا چاہتا تو پنڈلی سے نیچے کر لے۔ لیکن تہبند کا ٹخنوں کا کوئی حق نہیں۔ ‘‘\nیہ الفاظ استاد محمد (ابن قدامہ) کے ہیں۔","f2":"ازرا سے گٹھنے ڈھانپنا ضروری ہے۔ کسی بھی حالت میں رکوع سجدے کام کاج وغیرہ کے دوران میں گھٹنے نظر نہیں آنے چاہیئں اور ٹحنے ہر حال میں ننگے رہنے چاہیں ج نصف پنڈلی سے اوپر رکھنا بھی درست نہیں اور ٹخنوں سے نیچے رکھنا بھی۔رسم ورواج کی بناپر ان کے درمیان جہاں مناسب سمجھے رکھ لے۔ شلوار بھی ازار کےحکم میں داخل ہے لہذا اسے بھی ٹخنوں سے اوپر رکھنا چاہیے۔ خوب صورتی اللہ اور اس کے رسول صلی اللہ علیہ وسلم کی اطاعت ہی میں ہے۔"}],[5330,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ٹخنوں سے نیچے کا تہبند جہنم کی آگ میں ہو گا\" ۱؎۔\n§وضاحت\n۱؎: یعنی جسم کا وہ حصہ جو ٹخنے سے نیچے ازار :(تہبند ) سے چھپا ہوا ہے جہنم کی آگ میں جلے گا۔","الألباني: صحيح",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ نے فرمایا: ’’ ازار ٹخنوں سے نیچا ہو تو اتنی جگہ آگ میں جلے گی۔‘‘","f2":"یہ سزا تہبند ٹخنوں رکھنے کی ہے خواہ تکبر کے بغیر ہو۔ الا یہ کہ سستی سے کبھی کبھار تہبند نیچا ہو جائے اور توجہ ہونے پر فوراً اونچا کر لیا جائے تو پھر یہ وعید اور سزا نہیں ہو گی۔ واللہ اعلم."}],[5331,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تہبند کا جتنا حصہ ٹخنوں سے نیچے ہو گا وہ جہنم کی آگ میں ہو گا\"۔","الألباني: صحيح",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ سے منقول ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’تہبند ٹخنوں سے نیچا ہو تو وہ جگہ آگ میں جائے گی۔‘‘","f2":"’’آگ میں جائے گی ‘‘ گویا وہ شخص آگ میں جائےگا البتہ آگ متعلقہ حصے تک ہی ہو گی۔ جب تک سزا پوری نہیں ہو گی وہ جنت میں نہیں جاسکے گا۔"}],[5332,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ ایک (مشرک) قوم کے لوگوں نے بہت زیادہ قتل کئے، کثرت سے زنا کیا اور خوب حرام اور ناجائز کام کئے۔ پھر نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے، اور کہا: محمد! جو آپ کہتے ہیں اور جس چیز کی طرف دعوت دیتے ہیں یقیناً وہ ایک بہتر چیز ہے لیکن یہ بتائیے کہ جو کچھ ہم نے کیا ہے کیا اس کا کفارہ بھی ہے؟، تو اللہ تعالی نے «والذين لا يدعون مع اللہ إلها آخر» سے لے کر «فأولئك يبدل اللہ سيئاتهم حسنات» تک آیت نازل فرمائی، آپ صلی اللہ علیہ وسلم نے فرمایا: \"یعنی اللہ ان کے شرک کو ایمان سے، ان کے زنا کو عفت و پاک دامنی سے بدل دے گا اور یہ آیت «قل يا عبادي الذين أسرفوا على أنفسهم» نازل ہوئی\" ۱؎۔\n§وضاحت\n۱؎: میرے ان بندوں سے کہہ دیجئیے جن ہوں نے اپنی جانوں پر زیادتی کی ہے، الآیۃ۔\nعبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی اس شخص کو نہیں دیکھے گا جو (ٹخنے سے نیچے) تہبند لٹکاتا ہے\"۔","الألباني: صحيح لغيره",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہ نبی اکرک صلی اللہ علیہ وسلم نے فرمایا:’’ اللہ تعالیٰ تہبند لٹکانے والے کی طرف (نظر رحمت) نہیں دیکھے گا۔‘‘"}],[5333,"ابوذر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تین لوگ ہیں، جن سے اللہ تعالی قیامت کے دن بات نہ کرے گا، نہ انہیں (گناہوں سے)پاک کرے گا، اور ان کے لیے درد ناک عذاب ہے: کچھ دے کر حد سے زیادہ احسان جتانے والا، (ٹخنے سے نیچے) تہبند لٹکانے والا، اور جھوٹی قسم کھا کر اپنا سامان بیچنے والا\"۔","الألباني: صحيح",{"u2":"سیدنا ابو ذر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ تین شخص ایسے ہیں کہ اللہ تعالیٰ قیامت کے دن ان سے کلام نہیں فرمائے گا نہ ان کی گناہوں سے پاک کرے گا اور ان کے لیے دردناک عذاب ہو گا۔ اپنے عطیے کا احسان جتلانے والا تہبند (ٹخنوں سے نیچے) لٹکانے والا اور اپنا سامان جھوٹی قسم کھا کر بیچنے والا‘‘"}],[5334,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تہبند، قمیص اور پگڑی میں کسی کو بھی کوئی تکبر (گھمنڈ) سے لٹکائے تو قیامت کے دن اللہ اس کی طرف نہیں دیکھے گا\" ۱؎۔\n§وضاحت\n۱؎: تکبر اور گھمنڈ اللہ تعالی کو قطعی پسند نہیں ہے، نیز تہبند، قمیص اور عمامہ :(پگڑی ) میں تکبر اور گھمنڈ کے قبیل سے جو زائد حصہ لگ رہا ہے وہ اسراف سے خالی نہیں ہے۔","الألباني: صحيح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ اسبال(لٹکانا) تہبند، قمیص او رپگڑی سب میں ہوتا ہے۔ جوشخص ان میں سے کسی بھی چیز کو تکبر کے ساتھ زمین پر گھسیٹے گا اللہ تعالیٰ قیامت کے دن اس کی طرف (نظر رحمت سے) نہیں دیکھے گا۔‘‘"}],[5335,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو اپنا کپڑا تکبر (گھمنڈ) سے گھسیٹے گا، قیامت کے دن اللہ تعالی اس کی طرف نہیں دیکھے گا\"، ابوبکر رضی اللہ عنہ نے کہا: اللہ کے رسول! میرے تہبند کا ایک کونا لٹک جاتا ہے، إلا اس کے کہ میں اس کا بہت زیادہ خیال رکھوں، نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تم ان لوگوں میں سے نہیں ہو جو تکبر (گھمنڈ) کی وجہ سے ایسا کرتے ہیں\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ جوشخص تکبر کے ساتھ اپنا کپڑا(زمین پر) گھسیٹے گا اللہ تعالیٰ قیامت کے دن اس کی طرف نہیں دیکھے گا۔ ‘‘ سیدنا ابو بکر رضی اللہ عنہ نے کہا:اے اللہ کے رسول میرے تہبند کا ایک پلو لٹک جاتا ہے الایہ کہ میں (ہرقوت) اس کا خیال رکھوں۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’تو ان لوگوں میں شامل نہیں جو یہ کام تکبر سے کرتے ہیں۔‘‘","f2":"معلوم ہوا کہ تہبند لٹکانے کی مندرجہ بالا سزا متکبر شخص کےلیے ہے یا جس نے اسے عادت بنارکھا ہو۔ اگرکبھی کبھار بے اختیار یاسستی سے کسی کا تہبند لٹک جائے اور توجہ ہونے پر وہ اسے اونچا بھی کر لے تو معاف ہے۔ واللہ اعلم."}],[5336,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے تکبر (گھمنڈ) سے اپنا کپڑا لٹکایا، اللہ تعالی اس کی طرف نہیں دیکھے گا\"، ام المؤمنین ام سلمہ رضی اللہ عنہا نے کہا: اللہ کے رسول! تو پھر عورتیں اپنے دامن کیسے رکھیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"وہ اسے ایک بالشت لٹکائیں\"، وہ بولیں: تب تو ان کے قدم کھلے رہیں گے؟، آپ نے فرمایا: \"تو ایک ہاتھ لٹکائیں، اس سے زیادہ نہ کریں\"۔","الألباني: صحيح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ جوشخص تکبر سے اپنا کپڑا لٹکائے اللہ تعالیٰ اس کی طرف (نظر رحمت سے) نہیں دیکھے گا۔‘‘ سیدہ ام سلمہ رضی اللہ عنہا نے کہا: اے اللہ کے رسول! عورتیں اپنے دامنوں سے کیا سلوک کریں؟ آپ نے فرمایا: ’’وہ (مردوں سے) ایک بالشت نیچا رکھ لیں۔‘‘ انہوں نے کہا: پھر تو ان کے پاؤں ننگے ہوں گے۔ آپ نے فرمایا:’’ پھر وہ ایک ہاتھ لٹکالیں لیکن اس سے زیادہ نہیں۔‘‘","f2":"1۔ ’’ایک بالشت‘‘ یعنی نصف پنڈلی سے ایک بالشت نیچے تبھی پاؤں ننگے ہوں گے۔ اگر ٹخنوں سے بالشت نیچے ہو تو پاؤں ڈھانکے جائیں گے۔ ’’ ایک ہاتھ ‘‘ سے مراد بھی نصف پنڈلی سے نیچے ایک ہاتھ ہے۔ اس صورت میں دامن زمین پرگھسیٹنے لگے گا اور پاؤں بھی ننگے نہیں ہوں گے خواہ عورت چل ہی رہی ہو۔\n2۔ ’’ننگے ہوں‘‘ گویا عورتوں کےلیے مناسب ہے کہ ان کے قدم ننگے نہ ہوں البتہ قدم ڈھانکنا ضروری نہیں کیونکہ آپ نے ایک بالشت نیچے ہی کو ضروری قرار دیا ہے۔\n3۔ ’’ایک ہاتھ‘‘ عربی میں لفظ ذراع استعمال کیا گیا ہے یعنی کہنی کی ہڈی کے کنارے سے درمیانی انگلی کے بالائی کنارے تک عربی میں اس فاصلے کو ذراع کہتے ہیں۔ اردو میں اسے ہاتھ کہہ لیتے ہیں۔"}],[5337,"ام المؤمنین ام سلمہ رضی اللہ عنہا سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے عورتوں کے دامن لٹکانے کا ذکر کیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"وہ ایک بالشت لٹکائیں\" ۱؎، ام سلمہ رضی اللہ عنہا بولیں: تب تو کھلا رہے گا؟ آپ نے فرمایا: \"تب ایک ہاتھ لٹکائیں، اس سے زیادہ نہ کریں\"۔\n§وضاحت\n۱؎: عورتیں ایک بالشت یا ایک ہاتھ زیادہ کہاں سے لٹکائیں ؟ اس بارے میں صحیح قول یہ ہے کہ مردوں کی جائز حد :(ٹخنوں ) سے زیادہ ایک بالشت لٹکائیں یا حد سے حد ایک ہاتھ زیادہ لٹکا لیں، اس سے زیادہ نہیں، یہ اجازت اس لیے ہے تاکہ عورتوں کے قدم اور پنڈلیاں چلتے وقت ظاہر نہ ہو جائیں، آج ٹخنوں تک پاجامہ :(شلوار ) کے بعد لمبے موزوں سے عورتوں کا مذکورہ پردہ حاصل ہو سکتا ہے، لیکن عورتوں کے لباس اصلی شلوار وغیرہ میں اس بات کی احتیاط ہونی چاہیئے کہ وہ سلاتے وقت ٹخنے کے نیچے ناپ کر سلاتے جائیں۔","الألباني: صحيح",{"u2":"سیدہ ام سلمہ رضی اللہ عنہا سے روایت ہے کہ انہوں نے رسو ل اللہ صلی اللہ علیہ وسلم کے سامنے عوتوں کے دامن کا مسئلہ ذکر کیا تو رسول اللہ صلی اللہ علیہ وسلم نےفرمایا:’’ وہ ایک بالشت لٹکالین۔ ‘‘ سیدہ ام سلمہ رضی اللہ عنہا نے کہا: پھر ان کے پاؤں ننگے ہو گے۔ آپ نے فرمایا:’’ پھر ایک ہاتھ لٹکا لیں۔ اس سے زیادہ نہ لٹکائیں۔‘‘"}],[5338,"ام المؤمنین ام سلمہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے جب تہبند کے بارے میں جو کچھ کیا اس پر ام سلمہ رضی اللہ عنہا نے کہا: پھر عورتیں کیسے کریں؟ آپ نے فرمایا: \"ایک بالشت لٹکائیں\"، وہ بولیں تب تو ان کے قدم کھل جائیں گے! آپ نے فرمایا: \"پھر ایک ہاتھ اور لٹکا لیں، اس سے زیادہ نہ لٹکائیں\"۔","الألباني: صحيح",{"u2":"سیدہ ام سلمہ رضی اللہ عنہا سے روایت ہے کہ جب نبی اکرم صلی اللہ علیہ وسلم نے ازار کے بارے میں مسئلہ ذکر فرمایا تو سیدہ ام سلمہ رضی اللہ عنہا نے کہا: عورتیں کیا کریں؟ آپ نے فرمایا:’’ ایک بالشت نیچا رکھ لیں۔‘‘ وہ کہنے لگیں:پھر تو ان کے پاؤں ننگے ہوں گے۔آپ نے فرمایا:’’ پھر ایک ہاتھ نیچا کرلیں۔ اس سے زائد نہ کریں۔‘‘"}],[5339,"ام المؤمنین ام سلمہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سے سوال کیا گیا: عورت اپنا دامن کس قدر لٹکائے؟ آپ نے فرمایا: \"ایک بالشت\"، وہ بولیں: تب تو کھلا رہ جائے گا! آپ نے فرمایا: \"ایک ہاتھ، اس سے زیادہ نہ لٹکائیں\"۔","الألباني: صحيح",{"u2":"سیدہ ام سلمہ رضی اللہ عنہا نے فرمایا: رسو ل اللہ صلی اللہ علیہ وسلم سے پوچھا گیا عورت اپنا دامن کس قدر نیچا کر سکتی ہے؟ آپ نے فرمایا: ’’ایک بالشت۔ انہون نے کہا پھر تو اس کے پاؤں ننگے ہوں گے۔ آپ نے فرمایا: ’’ایک ہاتھ نیچا کر لے اس سے زائد نہ کرے۔‘‘"}],[5340,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اشتمال صماء سے اور ایک ہی کپڑے میں احتباء سے کہ شرمگاہ پر کچھ نہ ہو منع فرمایا۔\n§وضاحت\n۱؎: \"اشتمال صماء\" اہل لغت کے یہاں اشتمال صماء: یہ ہے کہ ایک آدمی کپڑے کو اپنے جسم پر اس طرح سے لپیٹ لے کہ ہاتھ پاؤں کی حرکت مشکل ہو، اس طرح کا تنگ کپڑا پہننے سے آدمی بوقت ضرورت کسی تکلیف دہ چیز سے اپنا دفاع نہیں کر سکتا، اور فقہاء کے نزدیک \" اشتمال صماء \" یہ ہے کہ پورے بدن پر صرف ایک کپڑا لپیٹے اور ایک جانب سے ایک کنارہ اٹھا کر گندھے پر رکھ لے، اس طرح کہ ستر :(شرمگاہ ) کھل جائے، اہل لغت کی تعریف کے مطابق یہ مکروہ ہے، اور فقہاء کی تعریف کے مطابق حرام۔ \"احتباء\" یہ ہے کہ آدمی ایک کپڑا پہنے اور گوٹ مار کر اس طرح بیٹھے کہ کپڑا اس کے ستر :(شرمگاہ ) سے ہٹ جائے۔","الألباني: صحيح",{"u2":"سیدنا ابو سعید رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے اشتمال صماء اور ایک کپڑے میں اس طرح گوٹھ مارنے سے منع فرمایا ہے کہ اس کی شرم گاہ پر کچھ نہ رہے۔","f2":"1۔ اشتمال صمَّأ لغت میں تو اس سے مراد اس طرح بکل مارنا ہے کہ ہاتھ وغیرہ بند ہو جائیں اور ضرورت پڑنے پر آسانی سے باہر نہ نکل سکیں جبکہ پنجابی میں اسے ’’کہتے بکل‘‘ کہتے ہیں۔ اللہ نہ کرے آدمی گرنے لگے تو ہاتھوں سے بچت نہ ہو سکے۔ کوئی مار کر بھاگے تو پکڑ نہ سکے۔ مگر فقہاء نے اس کا مطلب یہ بتایا ہے کہ جسم پر ایک ہی کپڑا لپیٹنا ہو، کوئی اور کپڑا نہ ہو۔ پھر اسے بھی ایک جانب سے اٹھا کر کندھے پر ڈال لے اور دوسری طرف سے ننگا ہو جائے اور فرض پردہ قائم نہ رہے۔ یہ صورت تو بالاتفاق حرام ہے کیونکہ ننگا ہونا جائز نہیں۔ پہلی صورت بھی مناسب نہیں۔ اگر چہ شرعاً کوئی حرج نہیں، البتہ نماز میں صورت صحیح نہیں کیونکہ بار بار بکل کو ٹھیک کرنا پڑے گا اور کپڑا اترتا رہے گا۔ نماز کی بجائے توجہ کپڑے کو درست کرنے کی طرف رہے گی۔\n2۔ ’’گوٹھ مارنا‘‘ اوپر والی چادر کو کمر اور دونوں گھٹنوں کے ارد گرد باندھ لینا جب کہ گھٹنے کھڑے ہوں اور مقعد اور پاؤں زمین پر ہوں۔ اس میں بھی بکل ولای خرابی ہے کہ آدمی مقید سا ہو جاتا ہے۔ جلدی ٹھنا پڑے تو مشکل پیش آتی ہے، نیز چادر وغیرہ کی صورت میں ستر کھلنے کا بھی اندیشہ ہے۔"}],[5341,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کپڑا پورے بدن پر لپیٹ لینے اور ایک ہی کپڑے میں آدمی کے احتباء کرنے سے کہ شرمگاہ کھلی ہوئی ہو، منع فرمایا۔","الألباني: صحيح",{"u2":"سیدنا ابو سعید خدری رضی اللہ عنہ نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے اس طرح اشتمال صماء اور ایک کپڑے میں گوٹھ مارنے سے منع فرمایا ہے کہ اس کی شرم گاہ پر کوئی پردہ نہ رہے۔"}],[5342,"جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے پورے بدن پر کپڑا لپیٹ لینے اور ایک ہی کپڑے میں لپیٹ کر بیٹھنے سے منع فرمایا۔","الألباني: صحيح",{"u2":"سیدنا جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اشتمال صماء اور ایک کپڑے میں گوٹھ مارنے سے منع فرمایا ہے۔","f2":"معلوم ہوا اگر پورے کپڑے پہنے ہوں اور کسی زائد کپڑے سے گوٹھ مارے جس سے پردے پر کوئی اثر نہ پڑے تو کوئی حرج نہیں۔"}],[5343,"عمرو بن حریث رضی اللہ عنہ کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم کو کی پگڑی باندھے دیکھا۔\n§وضاحت\n۱؎: «حرقانیہ» لفظ «حرق» :(جلنا ) سے ہے، یعنی: جلنے کے بعد کسی چیز کا جو رنگ ہوتا ہے، وہ \" سرمئی \" ہوتا ہے، لیکن مؤلف کے سوا سب کے یہاں، یہاں لفظ «سوداء» ہے، :(خود مؤلف کے یہاں بھی آگے «سوداء» ہی ہے ) اس لحاظ سے دونوں حدیثوں کو ایک ہی باب :(۱۰۹ ) میں لانا چاہیئے تھا، مگر کسی راوی کے یہاں «حرقانیۃ» ہونے کی وجہ سے اور رنگ میں ذرا سا فرق ہونے کی وجہ سے مؤلف نے شاید الگ الگ دو باب باندھے ہیں، واللہ اعلم۔","الألباني: صحيح",{"u2":"حضرت عمر بن حریث نے فرمایا: میں نے نبیٔ اکرم صلی اللہ علیہ وسلم کو سیاہی مائل پہنے دیکھا۔","f2":"’’سیاہی مائل‘‘ عربی میں لفظ حرقانية استعمال فرمایا گیا ہے جو حرق سے ہے۔ اس کے معنی آگ میں جلنا ہے۔ گویا ایسا رنگ جو آگ میں جلی ہوئی چیز کے رنگ جیسا ہو۔ اسے سیاہی مائل کہا گیا کیونکہ ضروری نہیں،وہ خالص سیاہ ہو۔"}],[5344,"جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم فتح مکہ کے دن مکہ میں احرام کے بغیر داخل ہوئے اور آپ کالی پگڑی باندھے ہوئے تھے۔","الألباني: صحيح",{"u2":"حضرت جابر سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم فتح مکہ کے دن احرام کے بغیر (مکہ مکرمہ میں) داخل ہوئے جبکہ آپ (کے سرمبارک) پر سیاہ پگڑی تھی۔","f2":"’’احرام کے بغیر‘‘ کیونکہ احرام میں سر ڈھانپنا منع ہے۔ معلوم ہوا اگر کوئی شخص حج یا عمرے کا ارادہ رکھتا ہو، کسی اور کام سے مکہ مکرمہ جانا چاہتا ہو اور وہ میقات سے باہر رہتا ہو تو اسے میقات سے گزرتے وقت احرام باندھنا ضروری نہیں۔ احناف نے یہاں سختی برتی ہے کہ جو بھی شخص مکہ مکرمہ جانا چاہتا ہو اور وہ میقات سے باہر رہتا ہو تو میقات سے گزرتے وقت اس کے لیے احرام باندھنا ضروری ہے۔ حج یا عمرے کا ارادہ ہو یا نہ۔ اس حدیث کو وہ آپ کا خاصہ بناتے ہیں مگر یہ بات کمزور ہے۔ اور صریح احادیث کے خلاف ہے کیونکہ صحیح احادیث میں یہ صراحت ہے کہ میقات اس شخص کے لیے ہیں جو حج یا عمرے کا ارادہ رکھتا ہو۔ رسول اللہ صلی اللہ علیہ وسلم نے حج و عمرے کی سعادت حاصل کرنے کے لیے مختلف اطراف سے مکہ معظمہ آنے والے مختلف لوگوں کے لیے میقات (احرام باندھنے کی جگہیں) مقرر فرمائیں تو ارشاد فرمایا: [فهن لهن ولمن أتيٰ عليهن من غير أھلين لمن ك ان يريد الحج ولاعمرة] ’’يه میقات ان علاقوں کے باسیوں کے لیےہیں، نیز ان لوگوں کے لیے بھی جو کسی دوسری جگہ سے آتے ہیں، ان علاقوں کے باسی نہیں۔ (یہ میقات) ہر اس شخص کے لیے جو حج و عمرےکا ارادہ کرتا ہے۔‘‘ (صحيحالبخاري، الحج، باب مهل أهل الشام، حديث:1526، وصحيح مسلم، الحج، باب مواقيت الحج، حديث: 1181) معلوم ہوا اگر کوئی شخص حج و عمرہ نہ کرنا چاہے تو اس کے لیے یہ میقات بھی نہیں اور نہ اس کے لیے یہاں گزرتے ہوئے احرام باندھنا ضروری ہے۔"}],[5345,"جابر رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم فتح مکہ کے دن (مکہ میں) داخل ہوئے اور آپ کالی پگڑی باندھے ہوئے تھے۔","الألباني: صحيح",{"u2":"حضرت جابر نے فرمایا: نبیٔ اکرم صلی اللہ علیہ وسلم فتح مکہ کے دن مکہ مکرمہ میں داخل ہوئے جبکہ آپ نے سیاہ پگڑی زیب تن کر رکھی تھی۔"}],[5346,"عمرو بن امیہ رضی اللہ عنہ کہتے ہیں: گویا میں اس وقت رسول اللہ صلی اللہ علیہ وسلم کو منبر پر دیکھ رہا ہوں اور آپ کالی پگڑی باندھے ہوئے ہیں، اس کا کنارہ اپنے دونوں مونڈھوں کے درمیان (پیچھے) لٹکا رکھا ہے۔","الألباني: صحيح",{"u2":"سیدنا عمرو بن امیہ رضی اللہ عنہ نے فرمایا: مجھے ایسے محسوس ہوتا ہے کہ میں اب بھی رسول اللہ صلی اللہ علیہ وسلم کو منبر پر رونق افروز دیکھ رہا ہوں جبکہ آپ پر سیاہ پگڑی ہے اور آپ نے اس کا شملہ اپنے دونوں کندھوں کے درمیان لٹکا رکھا ہے۔","f2":"پگڑی باندھنے کا انداز رواجی مسئلہ ہے۔ کسی علاقے میں جس طرح پگڑی باندھی جاتی ہو، جائز ہوگی کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے پگڑی باندھنے کا کوئی خصوصی طریقہ بیان نہیں فرمایا: لیکن بہتر طریقہ وہی ہے جو آپ صلی اللہ علیہ وسلم نے اختیار فرمایا۔ اگر اتباع کی نیت ہے تو اس میں بھی ان شاءاللہ ثواب ہوگا، ہاں غلو اور علامتی پگڑی سے پرہیز ضروری ہے، اگر کسی علاقے میں مسلمان اور کافر اکٹھے رہتے ہوں تو مسلمانوں کا انداز کفار سے مختلف ہونا چاہیے تا کہ امتیاز قائم رہے۔"}],[5347,"سالم بن ابی الجعد سے روایت ہے کہ ابن عباس رضی اللہ عنہما سے اس شخص کے بارے میں پوچھا کیا گیا جس نے کسی مومن کو جان بوجھ کر قتل کیا، پھر توبہ کی، ایمان لایا، اور نیک عمل کئے پھر راہ راست پر آ گیا؟ ابن عباس رضی اللہ عنہما نے کہا: اس کی توبہ کہاں ہے؟ میں نے تمہارے نبی کریم صلی اللہ علیہ وسلم کو فرماتے سنا ہے: \"وہ قاتل کو پکڑے آئے گا اور اس کی گردن کی رگوں سے خون بہہ رہا ہو گا، تو وہ کہے گا: اے میرے رب! اس سے پوچھ، اس نے مجھے کیوں قتل کیا؟\" پھر (ابن عباس رضی اللہ عنہما نے) کہا: اللہ تعالی نے اس آیت :(«ومن يقتل مؤمنا متعمدا...») کو نازل کیا اور اسے منسوخ نہیں کیا ۱؎۔\n§وضاحت\n۱؎: یہ آیت: «ومن يقتل مؤمنا متعمدا فجزاؤه جهنم خالدا فيها» \" جو کوئی مؤمن کو عمداً قتل کرے تو اس کا بدلہ جہنم ہے وہ اس میں ہمیشہ ہمیش رہے گا \" :(النساء: ۹۳ ) مدنی ہے اور بقول ابن عباس مدنی زندگی کے آخری دور میں نازل ہونے والی آیات میں سے ہے۔ اس لیے یہ اس مکی آیت کی بظاہر ناسخ ہے جو سورۃ الفرقان میں ہے: «والذين لا يدعون مع الله إلها آخر ولا يقتلون النفس التي حرم الله إلا بالحق» سے لے کر«إلا من تاب و عمل صالحا» تک \" اور اللہ کے ساتھ کسی دوسرے معبود کو نہیں پکارتے اور کسی ایسے شخص کو جسے قتل کرنا اللہ تعالی نے منع کر دیا ہو وہ بجز حق کے قتل نہیں کرتے۔۔۔۔ مگر جس نے توبہ کر لی اور نیک عمل کیے۔۔۔ \" :(الفرقان: ۶۸-۷۰ ) علماء نے تطبیق کی صورت یوں نکالی ہے کہ پہلی آیت کو اس صورت پر محمول کریں گے جب قتل کرنے والا مؤمن کے قتل کو مباح بھی سمجھتا ہو تو اس کی توبہ قبول نہیں ہو گی اور وہ جہنمی ہو گا۔ ایک جواب یہ دیا جاتا ہے کہ مدنی آیت میں «خلود» سے مراد زیادہ عرصہ تک ٹھہرنا ہے، ایک نہ ایک دن توحید کی بدولت اسے ضرور جہنم سے خلاصی ہو گی۔ یہ بھی جواب دیا جا سکتا ہے کہ آیت میں زجر و توبیخ مراد ہے۔ یا جو بغیر توبہ مر جائے، یہ ساری تاویلات اس لیے کی گئی ہیں کہ جب کفر و شرک کے مرتکب کی توبہ مقبول ہے تو مومن کو عمداً قتل کرنے والے کی توبہ کیوں قبول نہیں ہو گی، یہی وجہ ہے کہ ابن عباس رضی اللہ عنہما نے اپنے اس قول سے رجوع کر لیا۔ دیکھئیے :(صحیح حدیث نمبر: ۲۷۹۹ )\nابوطلحہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"فرشتے ایسے گھر میں داخل نہیں ہوتے جس میں کتا ہو یا تصویر (مجسمہ)\"۔","الألباني: صحيح",{"u2":"سیدنا ابو طلحہ رضی اللہ عنہ سے روایت ہے کہ نبیٔ اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’فرشتے اس گھر میں داخل نہیں ہوتے جس میں کتایا صورت (تصویر) ہو۔‘‘","f2":"1۔ کتا گھر میں رکھنے کی اجازت نہیں۔ اگر ضرورت کی بنا پر رکھا جائے تو کھیتوں اور باڑوں میں رکھا جاسکتا ہے۔ گھر میں نہیں کیونکہ گھر میں اس کا کوئی کام نہیں۔ (تصیل کے لیے دیکھیے، احادیث 4281 تا 4296)\n2۔ تصویر سے مراد کسی ذی روح کی مصنوعی تصویر ہے جو عزت و احترام کے ساتھ رکھی گئی ہو، خواہ وہ مجسمے کی صورت میں ہو یا کسی کاغذ، دیوار یا کپڑے پر بنائی گئی ہو۔ پھر ہاتھسے بنائی گئی ہو یا کسی آلے یا مشین کے ذریعے سے، کیونکہ تصاویر بے فائدہ بنائی جاتی ہیں یا تعظیم کی خاطر۔ پہلی صورت میں اسراف ہے جو کہ حرام ہے اور دوسری صورت میں شرک کا پیش خیمہ ہے۔ جو چیز گناہ ہو، اس کا سبب اور ذریعہ بھی گناہو، جو چیز گناہ ہو، اس کا سبب اور ذریعہ بھی گناہ ہی ہوتا ہے۔ البتہ اگر تصویر کسی فائدے کی خاطر ہو، مثلاً: شناخت کے لیے تو کوئی حرج نہیں کیونکہ شریعت ضرورت کے مخالف نہیں ہوتی۔ لیکن یہ ضروری ہے کہ اسے شناخت کی حد تک ہی رکھا جائے، زینت اور فخر نہ بنایا جائے اور نہ اسے احتراماً لٹکایا جائے۔ اسی طرح علاج وغیرہ میں تصویر سے مدد لی جاسکتی ہے۔ اگر کوئی شخص مجبور ہو توغیر ضروری تصویر اس کے لیے گناہ کا موجب نہ ہوگی، البتہ تصویر بنانے والاے یا اس کا حکم دینے والے مجرم ہوں گے، مثلاً: کرنسی نوٹوں اور اخبارات کی تصاویر۔ ان چیزوں پر تصویر کی ضرورت تو نہیں مگر عام انسان اس مسئلے میں بے بس ہیں کیونکہ ان چیزوں کے بغیر گزارہ نہیں۔ یاد رکھنا چاہیے کہ جہاں تصویر ضروری وہاں ضرورت کی حد تک ہی محدود رہنا چاہیے، مثلاً: شناختی تصویر میں صرف چہرے کی حد تک ہونی چاہیے، قدم آدم نہ ہو۔ اسی طرح غیر ضروری تصاویر جن میں عام انسان مجبور ہے، احترام ولای جگہ نہ رکھی جائیں بلکہ نیچے رکھی جائیں جہاں پاؤں لگتے ہوں، نیز اخبارات کہ تہہ کر کے رکھا جائے تا کہ احترام کا تاثر نہ ہو۔ (مزید دیکھیے، حدیث:4251)\n3۔ فرشتوں سے مراد رحمت کے فرشتے ہیں ورنہ محافظ اور کاتب فرشتے تو ہر جگہ ہی ہوتے ہیں۔ اس کلام سے مقصود رحمت کی نفی ہے جو فرشتوں کی خصوصیت ہے۔"}],[5348,"ابوطلحہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"فرشتے ایسے گھر میں داخل نہیں ہوتے جس میں کتا ہو، اور نہ ایسے گھر میں جس میں مورتیاں (مجسمے)\"۔","الألباني: صحيح",{"u2":"سیدنا ابو طلحہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’فرشتے اس گھر میں داخل نہیں ہوتے جس میں کتا یا ذی روح کی تصویر ہو۔‘‘","f2":"’’ذی روح کی‘‘ اگر کسی جگہ تصویر کا جواز ذکر ہو تو مراد غیر ذی روح کی تصویر ہوگی، مثلاً: حضرت سلیمان علیہ السلام کے دور کی تصاویر جن کا قرآن میں ذکر ہے۔ اسی طرح آئندہ حدیث میں ذکر شدہ تصاویر۔"}],[5349,"عبیداللہ بن عبداللہ سے روایت ہے کہ وہ ابوطلحہ انصاری رضی اللہ عنہ کے پاس عیادت کے لیے گئے، ان کے پاس انہیں سہل بن حنیف مل گئے۔ تو ابوطلحہ رضی اللہ عنہ نے ایک شخص کو حکم دیا کہ وہ ان کے نیچے سے بچھونا نکالے۔ ان سے سہل نے کہا: اسے کیوں نکال رہے ہیں؟ وہ بولے؟ اس لیے کہ اس میں تصویریں (مجسمے)ہیں اور اسی کے بارے میں رسول اللہ صلی اللہ علیہ وسلم کا وہ فرمان ہے جو تمہارے علم میں ہے، وہ بولے: کیا آپ نے یہ نہیں فرمایا: \"اگر کپڑے میں نقش ہوں تو کوئی حرج نہیں\"، انہوں نے کہا: کیوں نہیں، لیکن مجھے یہی بھلا معلوم ہوتا ہے (کہ میں نقش والی چادر بھی نہ رکھوں) ۱؎۔\n§وضاحت\n۱؎: تصویر کے سلسلہ میں صحیح بات یہ ہے کہ ذی روح :(جاندار ) کی تصویر حرام ہے، خواہ یہ تصاویر جسمانی ہیئت :(مجسموں کی شکل ) میں ہوں یا نقش و نگار کی صورت میں، إلا یہ کہ ان کے اجزاء متفرق ہوں، البتہ گڑیوں کی شکل کو علماء نے مستثنی قرار دیا ہے۔","الألباني: صحيح",{"u2":"حضرت عبید اللہ بن عبد اللہ سے روایت ہے کہ وہ سیدنا ابو طلحہ انصاری رضی اللہ عنہ کی عیادت کرنے کے لیے ان کے ہاں حاضر ہوئے تو وہاں حضرت سہل بن حنیف رضی اللہ بھی موجود تھے۔ سیدنا ابو طلحہ رضی اللہ عنہ نے ایک آدمی سے فرمایا کہ میرے نیچے سے بستر کی چادر نکال دے۔ سیدنا سہل رضی اللہ عنہ نے فرمایا: آپ چادر کیوں نکلوا رہے ہیں؟ انہوں نے فرمایا: اس لیے کہ اس کے بارے میں جو کچھ فرمایا ہے، وہ اآپ بھی جانتے ہیں۔ وہ فرمانے لگے: کیا آپ نے یہ نہیں فرمایا تھا کہ جو تصویر کپڑے میں نقش ہو، اس میں کوئی حرج نہیں۔ انہوں نے کہا: ہاں، مگر مجھے یہ زیادہ اچھا لگتا ہے (کہ کپڑے میں بھی نہ ہو بلکہ سادگی ہو)۔","f2":"غیر ذی روح اشیا کی تصویر اگرچہ جائز ہے مگر وسیع پیمانے پر نہیں کہ اس کو کاروبار بنا لیا یا زینت کے لیے جگہ جگہ غیر ذی روح اشیا کی تصویریں بنائی یا لٹکائی جائیں کیونکہ اسلام سادہ مذہب ہے۔ اسراف کو پسند نہیں کرتا، اسی لیے سیدنا ابو طلحہ رضی اللہ عنہ نے اپنے بستر کی چادر پر غیر ذی روح تصویروں کو بھی مناسب نہ سمجھا اگرچہ وہ جائز ہیں، لہٰذا کپڑے یا کاغذ پر منقس تصویریں بھی وہی جائز ہیں جو غیر ذی روح اشیاء کی ہوں۔ یہ اس روایت کی ایک توجیہہ ہے۔ بعض محققین کے نزدیک کپڑے پر منقش تصویر ذی روح چیز کی بھی جائز ہے مگر وہ ثابت نہ ہو بلکہ کٹی ہوئی ہو، یعنی کسی کا سر نہیں، کسی کا دھڑ نہیں، کسی کے بازو نہیں، کسی کا ٹانگیں نہیں۔ گویا تصویر کو ٹکڑوں میں بانٹ کر کپڑا استعمال میں لایا جاسکتا ہے۔ یا وہ کپڑا اور کاغذ توہین کی جگہ ہو، مثلاً: پاؤں کے نیچے آتا ہو۔ بعض حضرات نے رقماً فی ثوب (کپڑے میں منقش تصویر) کے الفاظ سے اس وسیع کاروبار کو جائز قرار دینے کی کوشش کی ہے جو آج کل فن اور آرٹ بلکہ فیشن کی صورت اختیار کر چکا ہے اور عمومی طور پر عریانی اور فحاشی کا ذریعہ بن رہا ہے۔ فَاِنَّا للهِ وَ إِنَّا إِليهِ راجعون"}],[5350,"ابوطلحہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"فرشتے ایسے گھر میں داخل نہیں ہوتے جس میں تصویر (مجسمہ) ہو\"، بسر کہتے ہیں: پھر زید بیمار پڑ گئے تو ہم نے ان کی عیادت کی، اچانک دیکھا کہ ان کے دروازے پر پردہ ہے جس میں تصویر ہے، میں نے عبیداللہ خولانی سے کہا: کیا زید نے ہمیں تصویر کے بارے میں پہلے روز حدیث نہیں سنائی تھی؟ کہا: عبیداللہ نے کہا: کیا تم نے انہیں یہ کہتے ہوئے نہیں سنا: کپڑے کے نقش کے سوا۔","الألباني: صحيح",{"u2":"حضرت زید بن خالد کا بیان ہے کہ سیدنا ابو طلحہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’فرشتے اس گھر میں داخل نہیں ہوتے جس میں تصویر ہو۔‘‘ (رواویٔ حدیث) بسر نے کہا: پھر حضرت زید بیمار پڑ گئے۔ ہم ان کی بیمارپرسی کو گئے تو ان کے دروازے پر ایک با تصویر پردہ لٹک رہا تھا۔ میں نے (اپنے ساتھی) عبد اللہ خولانی سے کہا: کیا ہمیں حضرت زید نے اس سے پہلے تصویر کے بارے میں حدیث نہیں بتائی تھی؟ عبید اللہ نے کہا: آپ نے ان کو یہ کہتے ہوئے نہیں سنا تھا؟ مگر کپڑے میں منقش تصویر جائز ہے؟","f2":"کپڑے میں منقش تصویر کے جواز کی صورتیں سابقہ حدیث کی تشریح میں گزر چکی ہیں۔ تمام موافق و مخالف احادیث کو ملانے سے یہی نتیجہ نکلتا ہے کہ یا تو اس سے غیر ذی روح چیز کی تصویر مراد ہے یا مقطع تصویر یا جو توہین کی جگہ پر ہو۔"}],[5351,"علی رضی اللہ عنہ کہتے ہیں کہ میں نے کھانا تیار کیا اور نبی اکرم صلی اللہ علیہ وسلم کو مدعو کیا، چنانچہ آپ تشریف لائے اور اندر داخل ہوئے تو ایک پردہ دیکھا جس میں تصویریں بنی ہوئی تھیں ۱؎، تو آپ باہر نکل گئے اور فرمایا: \"فرشتے ایسے گھر میں داخل نہیں ہوتے جن میں تصویریں ہوں\"۔\n§وضاحت\n۱؎: جو جاندار کی تھیں۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ سے روایت ہے، انہوں نے فرمایا: میں نے کھانا تیار کیا اور نبیٔ اکرم صلی اللہ علیہ وسلم کو کھانے پر بلایا۔ آپ تشریف لائے تو آپ نے ایک پردہ دیکھا جس پر تصویر یں تھیں۔ آپ واپس چلے گئے اور فرمایا: ’’ جس گھر میں تصویریں ہوں، وہاں فرشتے داخل نہیں ہوتے۔‘‘","f2":"1۔ اس حدیث سے بھی تصویر کی حرمت ثابت ہوتی ہے۔\n2۔ اہل علم و فضل کے لیے کھانا تیار کرنا اور انہیں کھانے پر بلانا مستحب اور پسندیدہ عمل ہے۔\n3۔ یہ حدیث مبارکہ نبیٔ اکرم صلی اللہ علیہ وسلم کے حسن خلق اور تواضع پر صریح دلالت کرتی ہے کہ آپ اپنے صحابۂ کرام کی دعوت پر ان کے ہاں کھانا کھانے کے لیے تشریف لے جایا کرتے تھے۔\n4۔ جس گھر میں تصویر ہو اس میں رحمت کے رشتے قطعاً داخل نہیں ہوتے، لہٰذا اس سے بڑی محرومی کیا ہو سکتی ہے کہ انسان کے گھر یا اس کی دکان اور کاروباری مرکز میں رحمت کا نزول نہ ہو۔ جب رحمت کے رشتے نہیں آئیں گے تو رحمت کے کس طرح آئے گی۔\n5۔ فرشتوں کی جبلت اور فطرت میں اطاعت الٰہی رکھ دی گئی ہے، اس لیے وہ کدی ایسی جگہ جاتے ہیں نہیں جہاں اللہ تعالیٰ کی معصیت و نافرمانی ہوتی ہو۔\n6۔ رسول اللہ صلی اللہ علیہ وسلم سیدنا علی رضی اللہ عنہ کے ہاں سے کھان کھائے بغیر ہی واپس چلے گئے کیونکہ وہاں منقش اور تصویروں والا پردہ لٹکا ہوا تھا۔ اولاد یا عزیز و اقارب کو سمجھانے کا یہ انداز نہایت مؤثر ہے، اس لیے جس مجلس و محفل یا گھر میں اللہ اور اس کے رسول صلی اللہ علیہ وسلم کے کسی صریح حکم کی مخالفت اور نافرمانی ہو رہی ہو اہل علم، خصوصاً وارثان منبر و محراب کو وہاں نہیں جانا چاہے۔ واللہ أعلم۔"}],[5352,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ ایک مرتبہ رسول اللہ صلی اللہ علیہ وسلم باہر نکلے پھر اندر چلے گئے، میں نے وہاں ایک باریک رنگین کپڑا لٹکا رکھا تھا جس میں پر دار گھوڑے بنے ہوئے تھے، جب آپ نے اسے دیکھا تو فرمایا: \"اسے نکال دو\"۔","الألباني: صحيح",{"u2":"سیدہ عائشہ رضی اللہ عنہا نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم کچھ دیر کے لیے گھر سے باہر تشریف لے گئے۔ پھرآپ تشریف لائے تو میں انے ایک پردہ لٹکا رکھا تھا جس میں پروں والے گھوڑوں کی تصویریں تھیں۔ آپ نے دیکھا تو فرمایا: ’’اسے اتار دے۔‘‘"}],[5353,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ ہمارے پاس ایک پردہ تھا جس پر چڑیا کی شکل بنی ہوئی تھی جب کوئی آنے والا آتا تو وہ ٹھیک سامنے پڑتا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"عائشہ! اسے بدل دو، اس لیے کہ جب میں اندر آتا ہوں اور اسے دیکھتا ہوں تو دنیا یاد آتی ہے\"، ہمارے پاس ایک چادر تھی جس میں نقش و نگار تھے، ہم اسے استعمال کیا کرتے تھے۔ لیکن اسے ہم نے کاٹا نہیں ۱؎۔\n§وضاحت\n۱؎: بقول امام نووی: یہ تصویروں کی حرمت سے پہلے کی بات ہے، اس لیے آپ نے \" حرمت \" کی بجائے \" ذکرِ دنیا \" کا حوالہ دیا اور ہٹوا دیا، یا یہ غیر جاندار کے نقش و نگار تھے جنہیں دنیاوی اسراف و تبذیر کی علامت ہونے کے سبب آپ نے ہٹوا دیا۔","الألباني: صحيح",{"u2":"ٔ اکرم صلی اللہ علیہ وسلم کی زوجہ محترمہ سیدہ عائشہ رضی اللہ عنہا سے روایت ہے، انہوں نے فرمایا: ہمارے پاس ایک پردہ تھا جس پر پرندوں کی تصاویر تھیَ جب کوئی شخص گھر میں داخل ہوتا تھا تو اسے سب سے پہلے وہ نظر آتا تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’عائشہ! اسے ہٹادو۔ میں جب بھی گھر میں داخل ہوتا ہوں، اس پر نظر پڑتی ہے تو توجہ دنیا کی طرف ہو جاتی ہے۔‘‘ اور ہمارے پاس ایک چادر تھی جس میں دھاریاں تھیں۔ ہم اسے اوڑھا کرتے تھے۔ اس کے ہم نے ٹکڑے نہیں کیے۔","f2":"1۔ یہ حدیث مبارکہ دنیا کی رنگینیوں سے کنارہ کچی اور اس سے بے رغبتی پر دلالت کرتی ہے۔\n2۔ اس حدیث مبارکہ سے یہ اشارہ بھی ملتا ہے کہ بوقت ضرورت پردہ وغیرہ لٹکانا درست ہے۔ لیکن یاد رہے کہ پردے میں تصویر نہ بنی ہو۔\n3۔ ’’توجہ دنیا کی طر ہو جاتی ہے‘‘ کیونکہ و زینت کے لیے لٹکایا گیا تھا اور دنیوی زینت تھی۔ ظاہر ہے توجہ اس طرف ہونا تو لازمی امر تھا وہاں سے آپ گزرتے تھے۔ اگرچہ آپ کے دل میں کراہت ہوتی تھی، توجہ کراہت کے منافی نہیں۔ دنیا سے محبت مذموم ہے نہ کہ توجہ بہ کراہت۔"}],[5354,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میرے گھر میں ایک کپڑا تھا جس میں تصویریں تھیں ۱؎، چنانچہ میں نے اسے گھر کے ایک روشندان میں لٹکا دیا، اور رسول اللہ صلی اللہ علیہ وسلم اسی کی طرف منہ کر کے نماز پڑھتے تھے، پھر آپ نے فرمایا: \"عائشہ! اسے ہٹا دو\"، پھر میں نے اسے نکال دیا اور اس کے تکیے بنا دیے۔\n§وضاحت\n۱؎: یہ بھی تصویروں کی حرمت سے پہلے کی بات ہے، یا یہ بھی غیر جاندار چیزوں کے نقش و نگار تھے، لیکن دیواروں یا روشن دانوں پر پردہ اسراف وتبذیر ہے جس کی وجہ سے آپ نے ہٹوا کر بچھونے بنوا دیئے۔","الألباني: صحيح",{"u2":"حضرت عائشہ فرماتی ہیں کہ میرے گھر میں ایک کپڑا تھا جس میں تصویریں تھیں۔ میں نے اسے گھر میں ایک طاق کے آگے لگا دیا۔ رسول اللہ صلی اللہ علیہ وسلم اس طاق کی طرف نماز پڑھا کرتے تھے۔ آپ صلی اللہ علیہ وسلم نے دیکھا تو فرمایا: ’’عائشہ! اس کو مجھ سے دور ہٹادے۔‘‘ میں نے اسے اتار کر اس کے تکیے بنا لیے۔","f2":"’’تصویریں‘‘ ممکن ہے غیر ذی روح کی تصویریں ہوں مگر نماز میں قبلہ کی جانب نقش و نگار توجہ بٹنے کا سبب بن جاتے ہیں، اس لیے ہٹانے کا حکم دیا۔ اور اگر ذی روح کی تصویریں تھیں تو پھر ایسا کپڑا احترام والی جگہ لٹکانا ناجائز تھا، اس لیے اتار کر تصویریں کاٹنے کا حکم دیا۔"}],[5355,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ انہوں نے ایک پردہ لٹکایا جس میں تصویریں تھیں، پھر رسول اللہ صلی اللہ علیہ وسلم اندر آئے تو اسے نکال دیا، چنانچہ میں نے اسے کاٹ کر دو تکیے بنا دیے۔ اس وقت مجلس میں بیٹھے ایک شخص نے جسے ربیعہ بن عطا کہا جاتا ہے: نے کہا میں نے ابو محمد، یعنی قاسم کو، عائشہ رضی اللہ عنہا سے روایت کرتے ہوئے سنا، وہ بولیں: رسول اللہ صلی اللہ علیہ وسلم ان پر ٹیک لگاتے تھے۔","الألباني: صحيح",{"u2":"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ میں نے ایک پردہ لگایا جس میں تصویریں تھیں۔ رسول اللہ صلی اللہ علیہ وسلم تشریف لائے تو آپ صلی اللہ علیہ وسلم نے اسے اتار پھینکا۔ میں نے اس کے دو تکیے بنا لیے جن سے رسول اللہ صلی اللہ علیہ وسلم ٹیک لگایا کرتے تھے۔","f2":"1۔ رسول اللہ صلی اللہ علیہ وسلم نے اپنے مبارک ہاتھوں سے تصاویر والا پردہ ہٹا دیا اور اس طرح آپ نے اپنے ہاتھ سے ازالۂ منکر فرمایا۔ اس حدیث مبارکہ سے یہ بھی معلوم ہوا کہ اگر تصویر والے کپڑے کو اس طرح کاٹ دیا جائے کہ تصویریں کٹ جائیں اور ثابت نہ رہیں تو ہو کپڑا فرشی استعمال میں لایا جاسکتا ہے، یعنی اس سے تکیے، سرہانے گدے وغیرہ بنائے جا سکتے ہیں۔ واللہ اعلم"}],[5356,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سفر سے آئے، میں نے ایک روشندان میں ایک پردہ لٹکا رکھا تھا، جس میں تصویریں تھیں، چنانچہ آپ نے اسے اتار دیا اور فرمایا: \"قیامت کے روز سب سے سخت عذاب والے وہ لوگ ہوں گے جو اللہ کی مخلوق کی تصویریں بناتے ہیں\"۔","الألباني: صحيح",{"u2":"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے، انہوں فرمایا: رسول اللہ صلی اللہ علیہ وسلم ایک سفر سے واپس تشریف لائے جبکہ میں نے اپنے ایک طاق کو تصویروں والے پردے کے ساتھے چھپا رکھا تھا۔ آپ نے اسے اتار پھینکا اور فرمایا: ’’قیامت کے دن سخت ترین عذاب ان لوگوں کو ہوگا جو اللہ تعالیٰ کی پیدا کردہ صورتوں جیسی صورتیں بناتے ہیں۔‘‘","f2":"1۔ اس حدیث سے معلوم ہوا کہ تصویر سازی حرام ہے، ہاتھ سے ہو یا کیمرے وغیرہ سے بسا اوقات تصویر شرک کا ذریعہ بھی بن سکتی ہے۔\n2۔ ’’سخت ترین عذاب‘‘ اگرچہ خلق اللہ (اللہ تعالیٰ کی پیدا کردہ صورتیں) عام لفظ ہے، غیر ذی روح اشیاء پر بھی بولا جاسکتا ہے مگر یہاں ذیر روح کی صورت مراد ہے کیونکہ متعلقہ پردہ پر ذی روح کی تصاویر تھیں جیسا کہ احادیث 5354 اور 5355 میں بیان ہے۔ ویسے بھی ’’صورۃ‘‘ چہرے کو کہا جاتا ہے اور چہرہ ذی روح کا ہی ہوتا ہے۔ سخت ترین عذاب کی تفسیر آئندہ احادیث میں مذکور ہے۔"}],[5357,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میرے پاس رسول اللہ صلی اللہ علیہ وسلم آئے، میں نے ایک پردہ لٹکا رکھا تھا جس پر تصاویر تھیں، چنانچہ جب آپ نے اسے دیکھا تو آپ کے چہرے کا رنگ بدل گیا، پھر آپ نے اسے اپنے ہاتھ سے پھاڑ دیا اور فرمایا: \"قیامت کے روز سب سے سخت عذاب والے وہ لوگ ہوں گے جو اللہ کی مخلوق کی تصویریں بناتے ہیں\"۔","الألباني: صحيح",{"u2":"نبیٔ اکرم صلی اللہ علیہ وسلم کی زوجۂ محترمہ سیدہ عائشہ رضی اللہ عنہا نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم میرے ہاں تشریف لائے جبکہ میں نے تصویروں والا ایک پردہ لٹکا رکھا تھا۔ جب آپ صلی اللہ علیہ وسلم نے دیکھا تو (غصے سے) آپ کے چہرۂ انور کا رنگ بدل گیا۔ پھر آپ صلی اللہ علیہ وسلم نے اسے اپنے دست مبارک سے پھاڑ دیااور فرمایا: ’’قیامت کے دن سخت ترین عذاب ان لوگوں کو ہگا جو اللہ تعالیٰ کی پیدا کردہ صورتوں جیسی صورتیں بنانے تکلف کرتے ہیں۔‘‘"}],[5358,"نضر بن انس کہتے ہیں کہ میں ابن عباس رضی اللہ عنہما کے پاس بیٹھا ہوا تھا کہ ان کے پاس اہل عراق میں سے ایک شخص آیا اور بولا: میں یہ تصویریں بناتا ہوں، آپ اس سلسلے میں کیا کہتے ہیں؟ انہوں نے کہا: قریب آؤ۔ میں نے محمد صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا ہے: \"جس نے دنیا میں کوئی صورت بنائی قیامت کے روز اسے حکم ہو گا کہ اس میں روح پھونکے، حالانکہ وہ اس میں روح نہیں پھونک سکے گا\"۔","الألباني: صحيح",{"u2":"حضرت نضر بن انس رحمہ اللہ سے روایت ہے کہ میں حضرت ابن عباس﷞ کے پاس بیٹھا تھا کہ ایک عراقی آدمی ان کے پاس آیا اور کہا: میں تصویر سازی کا کام کرتا ہوں۔ اس کے بارے میں آپ کیا فرماتے ہیں؟آپ نے فرمایا: نزدیک آ، نزدیک آ، میں نے حضرت محمد صلی اللہ علیہ وسلم کو فرماتے سنا ہے: ’’جو شخص دنیا میں (ذی روح اشیاء کی) تصویر بنائے گا، اسے قیامت کے دن اس بات کا پابند کیا جائے گا کہ وہ اس میں روح پھونکے لیکن وہ پھونک نہیں سکے گا۔‘‘","f2":"1۔معلوم ہو کہ جاندار اور ذی روح اشیاء کی تصویر بنانا اور فروخت کرنا حرام ہے، اس لیے فن تصویر سازی سے وابستہ حضرات و خواتین، نیز شوقیہ تصویر کشی کرنے والے لوگوں کو سنجیدگی سے اپنے اس خطرناک پیشے کا جائزہ لینا چاہیے۔ تصویر ہاتھ سے بنائی جائے یا کیمرے وغیرہ سے، اس کا اپنا وجود ہو یا کسی چیز پر نقش کی جائے، سب کا ایک ہی حکم ہے، نیز شادی بیاہ اور دیگر تقریبات کے موقع پر جو تصویر کشی کی جاتی ہے اور ویڈیو فلم بنائی جاتی ہے، یہ سب ناجائز ہے۔\n2۔ سیدنا ابو ہریرہ رضی اللہ عنہ نے ایک مصور کو مکان کی دیوار بناتے دیکھا تو درج ذیل حدیث بیان کی، فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ فرمارہے تھے: ’’اللہ تعالیٰ کا ارشاد گرامی ہے کہ اس شخص سے زیادہ ظالم کو ہو سکتا ہے جو پیدا کرنے میں میری نقالی کرتا ہے۔ ایک دانہ یا ایک چیونٹی تو پیدا کردیں۔‘‘ ایک روایت کے یہ الفاظ ہیں: ’’ایک جو ہی پیدا کرکے دکھائیں۔‘‘ دیکھیے: (صحیح البخاری، اللباس، حدیث:5953، وکتاب التوحید، حدیث:7559)\n3۔ اللہ تعالیٰ نے مفید تصویریں بنائیں جو بولتی، دیکھتی، سنتی، سمجھتی اور چلتی پھرتی ہیں مگر مصورین بے فائدہ صورتیں بناتے ہیں جو نہ دیکھ سکتی ہیں، نہ بول سکتی ہیں، نہ سن سکتی ہیں اور نہ سمجھ سکتی ہیں۔ اپنی صلاحیتیں ایسے بے مصرورف کاموں میں ضائیں کرنے کا کیا فائدہ؟ بلکہ یہ اللہ تعالیٰ کی ناشکری اور اس کے مقبلے میں ایک ناکام کوشش ہے۔ تبھی تو اللہ تعالیٰ کو غصہ آئے گا اور ان کو روح پھونکنے کا حکم دیا جائے گا جو ان کے بس کی بات نہیں۔"}],[5359,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے کوئی تصویر بنائی، تو اسے عذاب ہو گا یہاں تک کہ وہ اس میں روح ڈال دے، اور وہ اس میں روح نہیں ڈال سکے گا\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس﷞ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص کسی (ذی روح) چیز کی صورت بنائے گا، اسے عذاب دیا جائے گا حتیٰ کہ وہ اس میں روح پھونکے جبکہ وہ روح نہیں پھونک سکے گا۔‘‘","f2":"گویا اسےصرف روح پھونکنے کا ہی حکم نہیں دیا جائے گا بلکہ اس کو مسلسل عذاب بھی دیا جائے گا۔ جب تک وہ روح نہیں پھونکے گا، اسے عذاب میں مبتلا رکھا جائے گا اور روح تو وہ پھونک ہی نہیں سکے گا، لہٰذا قیامت کا مکمل دن وہ عذاب و رسوائی اور ڈنٹ ڈپٹ میں گزارے گا۔ اور یہ وقعی شدید ترین عذاب ہوگو۔ أستغفر اللہ"}],[5360,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے کوئی تصویر بنائی، قیامت کے روز اسے حکم ہو گا کہ وہ اس میں روح ڈالے اور وہ اس میں روح نہیں ڈال سکے گا\"۔","الألباني: صحيح",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے رمایا: ’’جس آدمی نے (کسی ذی روح کی) تصویر بنائی، اسے قیامت کے دن مجبور کیا جائے گا کہ اس میں ر وح پھونکے جو وہ پھونک نہیں سکےگا۔‘‘"}],[5361,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"بلاشبہ وہ لوگ جو تصویریں بناتے ہیں، قیامت کے روز عذاب میں مبتلا ہوں گے، ان سے کہا جائے گا: زندگی عطا کرو اسے جسے تم نے بنایا تھا\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر﷞ سے روایت ہے کہ نبیٔ اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’ان تصویریں بنانے والوں کو قیامت کے دن عذاب دیا جائے گا۔ انہیں کہا جائے گا۔ جو تم نے تصویریں بنائی ہیں، ان میں زندگی بھی پیدا کرو۔‘‘","f2":"’’پیدا کرو‘‘ اور یہ محال ہےکیونکہ اللہ تعالیٰ کے سوا یہ کام کوئی اور نہیں کر سکتا۔ ألا له الخلق، کسی کو سزا دینے کے لیے محال حکم دیا جاتا ہے کیونکہ وہاں مقصود صرف ڈانٹنا اور سزاد ینا ہوتا ہے نہ کہ عمل یا اطاعت۔ اور اسے ’’تعلیق بالمحال‘‘ کہا جاتا ہے۔"}],[5362,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بلاشبہ یہ تصویریں بنانے والے قیامت کے دن عذاب پائیں گے اور ان سے کہا جائے گا: زندگی عطا کرو اسے جسے تم نے بنایا تھا\"۔","الألباني: صحيح",{"u2":"نبی ٔ اکرم صلی اللہ علیہ وسلم کی روجۂ محترمہ سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’یقیناً ان صورتیں بنانے والوں کو قیام کے دن عذاب دیا جائے اور انہیں کہا جائے: جو بنایا ہے اس مٰں زندگی ڈالو۔‘‘","f2":"’’اور کہا جائے گا‘‘ گویا عذاب اس کے علاوہ بھی ہوگا۔ اور کہ کہنا الگ عذاب ہوگا۔"}],[5363,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ قیامت کے دن سب سے زیادہ سخت عذاب ان لوگوں کو ہو گا جو مخلوق کی تصویر بنانے میں اللہ تعالی کی مشابہت اختیار کرتے ہیں۔","الألباني: صحيح",{"u2":"نبیٔ اکرم صلی اللہ علیہ وسلم کی زوجۂ محترمہ حضرت عائشہ﷞ نے فرمایا: بلا شبہ قیامت کے دن سب سے زیادہ عذاب ان لوگوں کو ہوگا جو (تصویریں بنا کر) پیدا کرنے میں اللہ تعالیٰ کی نقل کرتے ہیں۔","f2":"یعنی ان کا یہ فعل نقل کی طرح ہی ہے اگر چہ ان کی نیت ایسی نہ ہو۔ واضح کام میں نیت نہیں دیکھی جاتی کیونکہ وہ تو مخفی ہوتی ہے۔ اس کے بارے میں کچھ بھی دعویٰ کیا جاسکتا ہے۔"}],[5364,"زہری سے روایت ہے کہ سالم بن عبداللہ نے کہا، اور پھر اسی طرح روایت بیان کی، اور (اس روایت میں) عقیل بن خالد نے مالک کی متابعت کی ہے۔\nعبداللہ بن مسعود رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"لوگوں میں سے سب سے زیادہ سخت عذاب والے تصویر بنانے والے لوگ ہیں\"۔","الألباني: صحيح",{"u2":"حضرت عبد اللہ بن مسعود سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بلاشبہ قیامت کے دن سب سے زیادہ عذاب ان لوگوں کو ہوگا جو (جاندارچیزوں کی)تصویریں بناتے ہیں۔‘‘"}],[5365,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ جبرائیل علیہ السلام نے نبی اکرم صلی اللہ علیہ وسلم سے اجازت طلب کی، تو آپ نے فرمایا: اندر آئیے، وہ بولے: میں کیسے اندر آؤں؟ آپ کے گھر میں تو ایسا پردہ لٹکا ہے جس میں تصویریں ہیں، لہٰذا یا تو آپ ان کے سر کاٹ دیجئیے، یا پھر ان کا بچھونا بنا دیجئیے تاکہ وہ روندا جائے۔ کیونکہ ہم فرشتے ایسے گھر میں داخل نہیں ہوتے جس میں تصویریں ہو۔","الألباني: صحيح",{"u2":"حضرت ابو ہریرہ سے روایت ہے، انہوں نے فرمایا: حضرت جبریل نے نبیٔ اکرم صلی اللہ علیہ وسلم سے داخل ہونے کی اجازت طلب کی۔ آپ نے فرمایا: ’’آجائیں۔‘‘ انہوں نے کہا: میں کیسے داخل ہو سکتا ہوں جب کہ آپ کے گھر میں ایک پردہ ہے جس میں تصویریں بنی ہوئی ہیں؟ یا تو آپ ان کے سر کاٹ دیں یا اسے چٹائی بنا کر بچھا لیں۔ ہم فرشتے کسی گھر میں داخل نہیں ہوتے جس میں تصویریں ہوں۔","f2":"معلوم ہوا تصویر والا کپڑا اگر نیچے بچھایا جائے جہاں پاؤں لگتے ہوں تو کئی حرج نہیں، یا تصویر کو اس طرح کاٹ دیا جائے کہ چہرہ مکمل نہ رہے۔ تفصیل پیچھے بیان ہو چکی ہے۔"}],[5366,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہماری اوڑھنے کی چادر میں نماز نہیں پڑھتے تھے ۱؎۔\n§وضاحت\n۱؎: ایسا آپ احتیاط کے طور پر کرتے تھے، کیونکہ اس بات کا امکان تھا کہ کوئی ایسی چیز ہو جو آپ کے لیے باعث تکلیف ہو، بہرحال اس سے یہ تو ثابت ہوا کہ آپ کے اہل خانہ لحاف استعمال کرتے تھے۔","الألباني: صحيح",{"u2":"حضرت عائشہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم ہمارے لحافوں میں نماز نہیں پڑھتے تھے۔\nسفیان نے (لحف کی بجائے ملاحف) کے الفاظ بیان کیے ہیں۔","f2":"1۔ امہات المومنین اور خودرسول اللہ صلی اللہ علیہ وسلم لحاف استعمال کیا کرتے تھے، نیز مذکورہ حدیث سے یہ اشارہ بھی ملتا ہے کہ خواتین و بچوں کے استعمال کے کپڑے اور دیگر ایسے کپڑے بھی جن کی بابت یہ گمان ہو کہ ان میں نجاست اور پلیدی ہو سکتی ہے، ان میں نماز پڑھنے سے احتیاط کرنی چاہیے کیونکہ مشکوک چیز سے پر ہیز کرنا اور یقین پر بنیاد رکھنا مطلوب شریعت ہے۔\n2۔ لحافوں وغیرہ میں نماز نہ پڑھنے کی ایک حکمت یہ بھی ہو سکتی ہے کہ عموماً لحاف بھاری ہوتے ہیں جنہیں جلدی نہیں دھویا جا سکتا، اس لیے ان میں اگر کوئی نجاست لگ جائے تو وہ عرصۂ دراز تک باقی رہتی ہے، جب کہ ان کا استعمال روزانہ ہوتا ہے۔ گندگی لگنے کا احتمال تو جماع کے وقت بھی ہوتا ہے، اس لیے عموماً اوپر اوڑھے جانے ولاے لحافوں سے نماز کے وقت پرہیز کیا جائے۔ واللہ اعلم۔\n3۔ اگر لحاف کے پاک ہونے کا یقین ہو تو پھر نماز جائز ہے۔ مذکورہ حدیث میں عمومی بات کا ذکر ہے کہ اکثر ان کا خیا ل نہیں رکھا جاتا۔ رسول اللہ صلی اللہ علیہ وسلم مجامعت والے کپڑوں میں جبکہ وہ صاف ہوتے، نماز پڑھ لیتے تھے۔ اسی طرح حضرت عائشہ کے لحاف میں وحی بھی نازل ہو جاتی تھی۔"}],[5367,"اسید بن رافع بن خدیج سے روایت ہے کہ رافع کے بھائی نے اپنے قبیلے سے کہا: آج رسول اللہ صلی اللہ علیہ وسلم نے ایسی چیز سے منع فرمایا ہے، جو تمہارے لیے سود مند تھی اور آپ کا حکم ماننا واجب، آپ نے بیع محاقلہ سے منع فرمایا ہے۔\nعیسی بن سہل بن رافع بن خدیج کہتے ہیں کہ میں یتیم تھا اور اپنے دادا رافع بن خدیج رضی اللہ عنہ کی گود میں پرورش پا رہا تھا، میں جوان ہوا اور میں نے ان کے ساتھ حج کیا تو میرے بھائی عمران بن سہل بن رافع بن خدیج آئے اور کہا: اے ابا جان (دادا جان)! ہم نے اپنی زمین فلاں عورت کو دو سو درہم پر کرائے پردے دی ہے۔ انہوں نے کہا: میرے بیٹے! اسے چھوڑ دو، اللہ تعالی تمہیں اس کے علاوہ روزی دے گا کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے زمین کرائے پر دینے سے روک دیا ہے۔\nنعمان بن بشیر رضی اللہ عنہما کہتے ہیں کہ ہم نبی اکرم صلی اللہ علیہ وسلم کے ساتھ تھے کہ ایک شخص نے آ کر آپ سے رازدارانہ گفتگو کی۔ آپ نے فرمایا: \"اسے قتل کر دو\"، پھر آپ نے فرمایا: \"کیا وہ گواہی دیتا ہے کہ اللہ کے سوا کوئی حقیقی معبود نہیں؟\" کہا: جی ہاں، مگر اپنے کو بچانے کے لیے وہ ایسا کہتا ہے، پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اسے قتل نہ کرو۔ اس لیے کہ مجھے حکم دیا گیا ہے کہ میں لوگوں سے جنگ کروں جب تک کہ وہ \"لا الٰہ الا اللہ\" نہ کہیں: جب وہ اسے کہہ لیں تو انہوں نے مجھ سے اپنے خون اور اپنے مال کو محفوظ کر لیا، مگر اس کے (جان و مال کے) حق کے بدلے، اور ان کا حساب اللہ تعالی پر ہے\"۔\n§وضاحت\n: مزی نے تحفۃ الأشراف :(۹/۲۱ ) میں اس حدیث کے ذکر کے بعد نسائی کا یہ قول نقل کیا ہے کہ \" اسود \" کی روایت صحیح نہیں ہے۔ :(جنہوں نے یہ نعمان بن بشیر رضی اللہ عنہما کی مسند سے روایت کیا ہے، صحیح اگلی پانچ روایتیں ہیں، جن میں یہ حدیث اوس رضی اللہ عنہ کی مسند سے روایت کی گئی ہے )\nاوس رضی اللہ عنہ کہتے ہیں کہ ہمارے پاس رسول اللہ صلی اللہ علیہ وسلم تشریف لائے اور ہم لوگ خیمہ میں تھے پھر مذکورہ حدیث بیان کی۔\nانس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے جوتوں کے دو تسمے تھے۔","الألباني: صحيح الإسناد",{"u2":"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے جوتے مبارک پر دو پٹیاں تھیں۔","f2":"جوتے کے تسمے پاؤں کو جوتے کے ساتھ قائم رکھنے کے لیے ہوتے ہیں۔ ایک ہو یا دو یا زائد، کوئی حرج نہیں۔ نہ یہ شرعی مسئلہ ہے اور نہ شریعت نے اس بارے مٰں کوئی ہدایت کی ہے، لہٰذا وقتی رواج کے کسی بھی قسم کے جوتے استعمال کیے جا سکتے ہیں جو وقتی ضرورت کو پورا کرتے ہیں۔"}],[5368,"حنظلہ بن قیس کہتے ہیں کہ میں نے رافع بن خدیج رضی اللہ عنہ سے زمین کو کرائے پر دینے کے بارے میں پوچھا، تو انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے زمین کرائے پر دینے سے روکا ہے، میں نے کہا: سونے، چاندی کے بدلے؟ کہا: نہیں (اس سے نہیں روکا ہے)۔ آپ نے تو اس سے صرف اس کی پیداوار کے بدلے روکا ہے۔ رہا سونا اور چاندی (کے بدلے کرایہ پر دینا) تو اس میں کوئی حرج نہیں سفیان ثوری نے بھی اسے ربیعہ سے روایت کیا ہے لیکن اسے مرفوع نہیں کیا ہے۔\nرافع بن خدیج رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے زمین کرائے پر دینے سے منع فرمایا ہے۔ عبداللہ بن عمر رضی اللہ عنہما نے اسے رافع بن خدیج رضی اللہ عنہ سے روایت کیا ہے، اور (اس روایت میں ابن عمر رضی اللہ عنہما سے رویت کرنے والے) عمرو بن دینار سے روایت میں ان کے شاگردوں نے اختلاف کیا ہے۔\nعروہ بن زبیر کہتے ہیں کہ زید بن ثابت رضی اللہ عنہ نے کہا: اللہ تعالی رافع بن خدیج رضی اللہ عنہ کی مغفرت فرمائے۔ اللہ کی قسم! میں یہ حدیث ان سے زیادہ جانتا ہوں، دو آدمی جھگڑ پڑے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اگر تمہارا یہ حال ہے تو تم کھیتوں کو کرائے پر مت دیا کرو\"، تو رافع نے آپ کا صرف یہ قول سن لیا کہ \"کھیتوں کو کرائے پر نہ دیا کرو\"۔\nقَالَ أَبُو عَبْد الرَّحْمَنِ: كِتَابَةُ مُزَارَعَةٍ عَلَى أَنَّ الْبَذْرَ وَالنَّفَقَةَ عَلَى صَاحِبِ الْأَرْضِ وَلِلْمُزَارِعِ رُبُعُ مَا يُخْرِجُ اللَّهُ عَزَّ وَجَلَّ مِنْهَا، هَذَا كِتَابٌ كَتَبَهُ فُلَانُ بْنُ فُلَانِ بْنِ فُلَانٍ فِي صِحَّةٍ مِنْهُ، وَجَوَازِ أَمْرٍ لِفُلَانِ بْنِ فُلَانٍ إِنَّكَ دَفَعْتَ إِلَيَّ جَمِيعَ أَرْضِكَ الَّتِي بِمَوْضِعِ كَذَا فِي مَدِينَةِ كَذَا مُزَارَعَةً وَهِيَ الْأَرْضُ الَّتِي تُعْرَفُ بِكَذَا وَتَجْمَعُهَا حُدُودٌ أَرْبَعَةٌ يُحِيطُ بِهَا كُلِّهَا وَأَحَدُ تِلْكَ الْحُدُودِ بِأَسْرِهِ لَزِيقُ كَذَا، وَالثَّانِي وَالثَّالِثُ وَالرَّابِعُ دَفَعْتَ إِلَيَّ جَمِيعَ أَرْضِكَ هَذِهِ الْمَحْدُودَةِ فِي هَذَا الْكِتَابِ بِحُدُودِهَا الْمُحِيطَةِ بِهَا وَجَمِيعِ حُقُوقِهَا وَشِرْبِهَا وَأَنْهَارِهَا وَسَوَاقِيهَا أَرْضًا بَيْضَاءَ فَارِغَةً لَا شَيْءَ فِيهَا مِنْ غَرْسٍ، وَلَا زَرْعٍ سَنَةً تَامَّةً أَوَّلُهَا مُسْتَهَلَّ شَهْرِ كَذَا مِنْ سَنَةِ كَذَا وَآخِرُهَا انْسِلَاخُ شَهْرِ كَذَا مِنْ سَنَةِ كَذَا عَلَى أَنْ أَزْرَعَ جَمِيعَ هَذِهِ الْأَرْضِ الْمَحْدُودَةِ فِي هَذَا الْكِتَابِ الْمَوْصُوفُ مَوْضِعُهَا فِيهِ هَذِهِ السَّنَةَ الْمُؤَقَّتَةَ فِيهَا مِنْ أَوَّلِهَا إِلَى آخِرِهَا كُلَّ مَا أَرَدْتُ وَبَدَا لِي أَنْ أَزْرَعَ فِيهَا مِنْ حِنْطَةٍ، وَشَعِيرٍ، وَسَمَاسِمَ، وَأُرْزٍ، وَأَقْطَانٍ، وَرِطَابٍ، وَبَاقِلَّا، وَحِمَّصٍ، وَلُوبْيَا، وَعَدَسٍ، وَمَقَاثِي، وَمَبَاطِيخَ، وَجَزَرٍ، وَشَلْجَمٍ، وَفُجْلٍ، وَبَصَلٍ، وَثُومٍ، وَبُقُولٍ، وَرَيَاحِينَ، وَغَيْرِ ذَلِكَ مِنْ جَمِيعِ الْغَلَّاتِ شِتَاءً وَصَيْفًا بِبُزُورِكَ، وَبَذْرِكَ وَجَمِيعُهُ عَلَيْكَ دُونِي عَلَى أَنْ أَتَوَلَّى ذَلِكَ بِيَدِي وَبِمَنْ أَرَدْتُ مِنْ أَعْوَانِي وَأُجَرَائِي وَبَقَرِي وَأَدَوَاتِي وَإِلَى زِرَاعَةِ ذَلِكَ وَعِمَارَتِهِ وَالْعَمَلِ بِمَا فِيهِ نَمَاؤُهُ وَمَصْلَحَتُهُ وَكِرَابُ أَرْضِهِ وَتَنْقِيَةُ حَشِيشِهَا، وَسَقْيِ مَا يُحْتَاجُ إِلَى سَقْيِهِ مِمَّا زُرِعَ، وَتَسْمِيدِ مَا يُحْتَاجُ إِلَى تَسْمِيدِهِ، وَحَفْرِ سَوَاقِيهِ وَأَنْهَارِهِ وَاجْتِنَاءِ مَا يُجْتَنَى مِنْهُ وَالْقِيَامِ بِحَصَادِ مَا يُحْصَدُ مِنْهُ وَجَمْعِهِ وَدِيَاسَةِ مَا يُدَاسُ مِنْهُ وَتَذْرِيَتِهِ بِنَفَقَتِكَ عَلَى ذَلِكَ كُلِّهِ دُونِي وَأَعْمَلَ فِيهِ كُلِّهِ بِيَدِي وَأَعْوَانِي دُونَكَ عَلَى أَنَّ لَكَ مِنْ جَمِيعِ مَا يُخْرِجُ اللَّهُ عَزَّ وَجَلَّ مِنْ ذَلِكَ كُلِّهِ فِي هَذِهِ الْمُدَّةِ الْمَوْصُوفَةِ فِي هَذَا الْكِتَابِ مِنْ أَوَّلِهَا إِلَى آخِرِهَا فَلَكَ ثَلَاثَةُ أَرْبَاعِهِ بِحَظِّ أَرْضِكَ وَشِرْبِكَ وَبَذْرِكَ وَنَفَقَاتِكَ وَلِي الرُّبُعُ الْبَاقِي مِنْ جَمِيعِ ذَلِكَ بِزِرَاعَتِي وَعَمَلِي وَقِيَامِي عَلَى ذَلِكَ بِيَدِي وَأَعْوَانِي وَدَفَعْتَ إِلَيَّ جَمِيعَ أَرْضِكَ هَذِهِ الْمَحْدُودَةِ فِي هَذَا الْكِتَابِ بِجَمِيعِ حُقُوقِهَا وَمَرَافِقِهَا، وَقَبَضْتُ ذَلِكَ كُلَّهُ مِنْكَ يَوْمَ كَذَا مِنْ شَهْرِ كَذَا مِنْ سَنَةِ كَذَا فَصَارَ جَمِيعُ ذَلِكَ فِي يَدِي لَكَ لَا مِلْكَ لِي فِي شَيْءٍ مِنْهُ وَلَا دَعْوَى وَلَا طَلِبَةَ إِلَّا هَذِهِ الْمُزَارَعَةَ الْمَوْصُوفَةَ فِي هَذَا الْكِتَابِ فِي هَذِهِ السَّنَةِ الْمُسَمَّاةِ فِيهِ، فَإِذَا انْقَضَتْ فَذَلِكَ كُلُّهُ مَرْدُودٌ إِلَيْكَ وَإِلَى يَدِكَ وَلَكَ أَنْ تُخْرِجَنِي بَعْدَ انْقِضَائِهَا مِنْهَا وَتُخْرِجَهَا مِنْ يَدِي وَيَدِ كُلِّ مَنْ صَارَتْ لَهُ فِيهَا يَدٌ بِسَبَبِي أَقَرَّ فُلَانٌ وَفُلَانٌ، وَكُتِبَ هَذَا الْكِتَابُ نُسْخَتَيْنِ.\nابوعبدالرحمٰن (نسائی) کہتے ہیں: بٹائی کے معاملات کو (اس طرح) لکھنا چاہیئے کہ بیج اور اس کا خرچ زمین کے مالک پر ہو گا اور کھیتی کرنے والے کے لیے کھیتی میں اللہ تعالی کی دی ہوئی پیداوار کا چوتھائی حصہ ہو گا ۱؎۔ یہ تحریر ہے جسے فلاں بن فلاں نے فلاں بن فلاں کے لیے لکھی ہے، صحت و تندرستی کی حالت میں لکھا اور اس حال میں جب اس کے احکام نافذ ہوتے ہیں۔ آپ نے اپنی ساری زمین جو فلاں مقام پر فلاں علاقے میں ہے مجھے بٹائی پر دی، اور یہ وہ زمین ہے جس کی پہچان یہ ہے: اس کی چوحدی یہ ہے کہ ان میں سے ایک فلاں مقام سے لگی ہوئی ہے، اسی طرح پھر دوسری، تیسری اور چوتھی حد بیان کرے۔ اس کتاب میں مذکور تمام حدود والی اپنی پوری زمین آپ نے مجھے دے دی۔ اور اس کے سارے حقوق، اس کا پانی، اس کی نہریں، اور نالیاں دے دیں، ایک ایسی زمین جو ہر چیز سے خالی ہے، نہ اس میں کھیتی ہے، نہ کوئی پودا، پورے ایک سال کے لیے جو فلاں سال، فلاں مہینے کی ابتداء سے شروع ہو گا، اور اس معاہدے کا اختتام فلاں سن کے فلاں مہینے کے خاتمے تک ہو گا۔ اس شرط پر کہ یہ پوری زمین جس کی حدیں اس معاہدہ میں بیان کی گئی ہیں اور جو فلاں مقام میں ہے اسے میں نے معینہ سال کے لیے شروع سے آخر تک کھیتی کے لیے لی، اور اس میں جب چاہوں اور جو چاہوں میں کھیتی کروں۔ گیہوں، جو، تل، چاول، روئی، کھجوریں، ساگ، چنا، لوبیا، مسور، کھیرا ککڑی، خربوزہ، گاجر، شلجم، مولی، پیاز، لہسن، یا ساگ یا بیل پھول وغیرہ، یعنی گرمی و سردی کے سارے غلے، اس طرح کہ بیج آپ کا ہو گا اور اس کی ساری محنت میری ہو گی، میرے ہاتھ کی یا اس کی جسے میں چاہوں اپنے دوستوں، مزدوروں اور بیل و ہل وغیرہ میں سے، میں اس میں کھیتی کروں گا، اسے آباد کروں گا اور ایسا کام کروں گا کہ اس سے نشو و نما ہو، وہ درست رہے، زمین میں ہل جوتوں گا، اس کی گھاس صاف کروں گا۔ اگی ہوئی کھیتی میں جسے پانی کی ضرورت ہو گی اس کی سینچائی کروں گا، اور جہاں کھاد کی ضرورت ہو گی کھاد ڈالوں گا، اس کی نالیاں اور نہریں کھودوں گا اور جو پھل توڑنا ضروری ہو گا اسے توڑوں گا۔ اور جس کھیتی کا کاٹنا ضروری ہو گا کاٹوں گا اور اکٹھا کروں گا اور جس فصل کی کٹائی ضروری ہو گی اسے کٹواؤں گا اور اس پر جو کچھ خرچ ہو گا وہ آپ کے ذمے ہو گا، نہ کہ میرے، اور یہ سب کام میں اپنے ہاتھ سے کروں گا یا اپنے مدد گاروں کے ذریعے نہ کہ آپ کی مدد سے، اس شرط پر کہ اس عہد نامے میں اس کے شروع سے لے کر آخر تک جو مدت ذکر کی گئی ہے اس پوری مدت میں جو اللہ تعالی اس کھیت میں سے اگائے گا آپ کے لیے تین چوتھائی حصہ ہو گا، اس لیے کہ زمین آپ کی تھی، بیج آپ کا تھا اور خرچہ بھی آپ نے کیا تھا، اور میرے لیے اس پورے میں سے باقی چوتھائی حصہ ہو گا اس لیے کہ میں نے کھیتی کی، کام کیا اور اپنے ہاتھ سے اور اپنے کے مدد گاروں کے ہاتھ سے اسے سر کیا، اور آپ نے وہ پوری زمین جس کی حدود اس عہد نامے میں بیان کی گئی ہیں میرے حوالے کی، اس کے تمام حقوق اور لوازمات کے ساتھ اور میں نے یہ زمین آپ سے اپنے قبضے میں لی، فلاں سال کے فلاں ماہ کے فلاں دن سے۔ تو یہ پوری کی پوری میرے ہاتھ میں ہے جو آپ کی ہے، میری اس میں نہ کوئی ملکیت ہے اور نہ ہی کوئی دعوی اور نہ ہی کوئی مطالبہ، سوائے اس فصل اور پیداوار کے جو اس معینہ سال میں اس عہد نامے میں ذکر کی گئی ہے، اور جب مدت پوری ہو گی تو یہ پوری زمین آپ کو لوٹا دی جائے گی، وہ آپ کے ہاتھ میں ہو گی اور مدت گزرنے کے بعد آپ کو اختیار ہو گا کہ آپ مجھے اس میں سے نکال دیں اور اسے میرے ہاتھ سے نکال لیں اور ہر اس شخص کے ہاتھ سے جس کا میری وجہ سے اس میں کوئی دخل تھا۔ فلاں اور فلاں نے یہ طے کیا، اور عہد نامہ کی دو کاپیاں لکھی گئیں۔\n§وضاحت\nبیج اور دیگر سارے اخراجات زمین کے مالک کی طرف سے اٹھانے کی صورت میں پیداوار کا تین حصہ مالک کا ہو گا اور ایک حصہ کاشت کار کا، اور اگر بیج اور دیگر سارے اخراجات کاشتکار برداشت کرے تو مالک کو پیداوار کا آدھا ملے گا، جیسا کہ خیبر کے معاملے میں اللہ کے رسول صلی للہ علیہ وسلم نے کیا تھا (دیکھئے حدیث نمبر ۳۹۶۱۱) ایسا بالکل نہیں ہے کہ بہر حال بیج و اخراجات صرف مالک پر ہوں تب ہی بٹائی کا معاملہ جائز ہے۔ جیسا کہ بعض فقہاء کا کہنا ہے۔ مذکورہ حدیث سے ان کے قول کی تردید ہوتی ہے۔\nاوس رضی اللہ عنہ کہتے ہیں کہ میں قبیلہ ثقیف کے ایک وفد میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، میں آپ کے ساتھ ایک خیمہ میں تھا، میرے اور آپ کے علاوہ خیمے میں موجود سبھی لوگ سو گئے۔ اتنے میں ایک شخص نے آپ سے چپکے سے کہا تو آپ نے فرمایا: \"جاؤ اسے قتل کر دو\" ۱؎، پھر آپ نے فرمایا: \"کیا یہ گواہی نہیں دیتا کہ اللہ کے سوا کوئی معبود برحق نہیں اور میں اللہ کا رسول ہوں\"۔ اس نے کہا: وہ گواہی دے رہا ہے۔ آپ نے فرمایا: \"اسے چھوڑ دو\" پھر فرمایا: \"مجھے حکم دیا گیا ہے کہ میں لوگوں سے اس وقت تک جنگ کروں جب تک کہ وہ «لا إله إلا اللہ» نہ کہیں: جب وہ یہ کہنے لگ جائیں تو ان کے خون، ان کے مال حرام ہو گئے مگر اس کے (جان و مال کے) حق کے بدلے\"۔ محمد (محمد بن جعفر غندر) کہتے ہیں: میں نے شعبہ سے کہا: کیا حدیث میں یہ نہیں ہے \" «أليس يشهد أن لا إله إلا اللہ وأني رسول اللہ» ؟\" وہ بولے: میرے خیال میں «أني رسول اللہ» کا جملہ «لا إله إلا اللہ» کے ساتھ ہے، مجھے معلوم نہیں۔\n§وضاحت\n۱؎: اس سے معلوم ہوا کہ حدیث نمبر ۳۹۸۴ میں «فاقتلوہ» میں جو «ہ» ضمیر ہے اس سے مراد وہ شخص ہے جس کے متعلق اس نے رازدارانہ سرگوشی کی تھی، نہ کہ بذات خود سرگوشی کرنے والا مراد ہے، کیونکہ «اذھب فاقتلہ» کا جملہ صریح طور پر اسی مفہوم کی وضاحت کر رہا ہے۔\nعرفجہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"میرے بعد فتنہ و فساد ہو گا پس اگر امت محمدیہ میں کوئی انتشار و تفرقہ ڈالنا چاہے جب کہ وہ متفق و متحد ہوں تو اسے قتل کر دو\"۔\nعمرو بن اوس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے جوتوں کے دو تسمے تھے۔","الألباني: صحيح",{"u2":"سیدنا عمرو بن اوس رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم کے جوتے مبارک میں دو تسمے تھے۔"}],[5369,"ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کسی کے جوتے کا تسمہ ٹوٹ جائے تو ایک جوتا پہن کر نہ چلے یہاں تک کہ اسے ٹھیک کرا لے\" ۱؎۔\n§وضاحت\n۱؎: ایسا کرنے سے آپ نے اس لیے منع کیا تاکہ ایک پاؤں اونچا اور دوسرا نیچا نہ رہے کیونکہ ایسی صورت میں پھسلنے کا خطرہ ہے، ساتھ ہی دوسروں کی نگاہ میں برا بھی ہے۔","الألباني: صحيح",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبیٔ اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’جب کسی کے جوتے کا تسمہ ٹوٹ جائے تو وہ ایک جوتے میں نہ چلے حتیٰ کہ اسے ٹھیک کرلے۔","f2":"ایک جوتے میں چلنا انسان وقار کے خلاف ہے۔ لوگوں کے لیے عجوبہ بننے والی بات ہے۔ لوگ دیکھ کر ہنسیں گے۔ دور سے وہ لنگڑا محسوس ہوگا۔ توازن خراب ہونے کی وجہ سے وہ گر بھی سکتا ہے، لہٰذا بجائے ایک جوتا پہننے کے ٹوٹے ہوئے تسمے کو ٹھیک کروائے ورنہ ننگے پاؤں چلے۔ البتہ اگر کسی بیماری یا تکلیف کی وجہ سے ایک پاؤں میں جوتا نہ پہنا جا سکے تو کوئی حرج نہیں، کیونکہ یہ تکلیف من جانب اللہ ہے، نیز بیماری اور تکلیف زیادہ عرصے تک بھی جاری رہ سکتی ہے۔ اتنے عرصے تک ننگے پاؤں چلنا مزید تکلیف کا سبب ہوگا۔"}],[5370,"ابورزین کہتے ہیں کہ میں نے ابوہریرہ رضی اللہ عنہ کو دیکھا وہ اپنی پیشانی پر ہاتھ مار رہے تھے، اور کہہ رہے تھے: عراق والو! تم کہتے ہو کہ میں رسول اللہ صلی اللہ علیہ وسلم پر جھوٹ گھڑتا، میں گواہی دیتا ہوں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا ہے: \"جب تم میں سے کسی کے جوتے کا تسمہ ٹوٹ جائے تو ایک جوتا پہن کر نہ چلے یہاں تک کہ اسے ٹھیک کرا لے\"۔","الألباني: صحيح",{"u2":"حضرت ابو رزین بیان کرتے ہیں کہ میں نے حضرت ابو رہریرہ کو دیکھا، وہ اپنا ہاتھ اپنے ماتھے پر (بطور تعجب و تاسف) ماررہے تھے اور فرمارہے تھے: او عراقیو! تم سمجھتے ہو کہ میں رسول اللہ صلی اللہ علیہ وسلم کا نام لے کر جھوٹ بول رہا ہوں؟ میں گواہی دیتا ہوں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ’’جب تم میں سے کسی شخص کے جوتے کا تسمہ ٹوٹ جائے تو وہ دوسرا (ایک) جوتا پہن کر نہ چلے حتیٰ کہ اسے ٹھیک کرلے۔‘‘","f2":"1۔ ’’سمجھتے ہو‘‘ شاید کسی نے ان کے بکثرت روایت کرنے پر کچھ زبان درازی کی ہو۔ عراقی کچھ ایسے ہی تھے۔\n2۔ ’’ٹھیک کرے‘‘ مولوم ہو امومن کو اپنے وقار کا لحاظ رکھنا چاہے، لباس میں بھی اور چال ڈھال میں بھی ایسا بھی سادہ نہ ہو کہ وقار کی پرواہی نہ کرے اور لوگوں کے لیے اضحو کہ اور طنز کا سامان بنا رہے۔"}],[5371,"انس بن مالک رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم ایک کھال پر لیٹے تو آپ کو پسینہ آ گیا، ام سلیم رضی اللہ عنہا اٹھیں اور پسینہ اکٹھا کر کے ایک شیشی میں بھرنے لگیں، نبی اکرم صلی اللہ علیہ وسلم نے انہیں دیکھا تو فرمایا: \"ام سلیم! یہ تم کیا کر رہی ہو؟\" وہ بولیں: میں آپ کے پسینے کو عطر میں ملاؤں گی، یہ سن کر نبی اکرم صلی اللہ علیہ وسلم ہنسنے لگے ۱؎۔\n§وضاحت\n۱؎: یہ نبی اکرم صلی اللہ علیہ وسلم کے پسینے کے ساتھ خاص تھا، چنانچہ سلف میں ایسی کوئی مثال نہیں ملتی کہ کسی نے کسی کا پسینہ محفوظ رکھا ہو۔","الألباني: صحيح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہےکہ نبیٔ اکرم صلی اللہ علیہ وسلم (ایک دفوہ ہمارے گھر میں) چمڑے کے بچھونے پر استراحت فر ہوئے۔ آپ کو پسینہ آگیا۔ (میری والدہ) حضر ام سلیم رضی اللہ عنہا اٹھیں اور آپ کے بابرکت پسینے کو اکٹھا کرکے ایک شیشی میں ڈال لیا۔ نبیٔ اکرم صلی اللہ علیہ وسلم نے ان کو (ایسے کرتے ہوئے) دیکھا تو فرمایا: ’’ام سلیم! کیا کرتی ہے؟‘‘ انہوں نے کہا: میں آپ کا پسینہ اپنی خوشبو میں ڈال لوں گی۔ آپ مسکرانے لگے۔","f2":"1۔یہ حدیث مبارکہ میں اس مسئلے کی دلیل ہے کہ رسول اللہ صلی اللہ علیہ وسلم کا پسینہ مبارک متبرک تھا۔ صحابۂ کرام رضی اللہ عنہم نے اس سےتبرک حاصل کیا ہے۔ نبیٔ اکرم صلی اللہ علیہ وسلم کو اس بات کا علم تھا اور آپ نے انہیں ایسا کرنے سے منع نہیں فرمایا۔ مزید برآں یہ کہ صحابۂ کرام رضی اللہ عنہم آپ کے مبارک بالوں اور ناخنوں کو بھی بابرکت سمجھتے تھے صحابۂ کرام رضی اللہ عنہم کو آپ صلی اللہ علیہ وسلم سے بے انتہا محبت تھی۔ یہی وجہ ہے کہ وہ آپ کے پسینے مبارک کو بھی محبوب متاع سمجھتے تھے اور آپ کے آثار کریمہ سے تبرک حاصل کرتے تھے۔\n2۔ یہ حدیث مبارکہ اس بات پر بھی دلالت کرتی ہے کہ انسان کا چمڑا، اس کا پسینہ اور اسی طرح انسانی بال بھی پاک اور طاہر ہیں، نیز اس سے قیلولے کی مشروعیت بھی ثابت ہوئی۔\n3۔ ’’چمڑے کا بچھونا‘‘ کپڑے کی چادر سے بہر صورت بہتر ہوتا ہے۔ مقصد یہ ہے کہ اچھی چیز کا استعمال معیوب نہیں۔\n4۔ ’’استراحت فرما ہوئے‘‘ پیچھے گزرچکا ہے کہ حضرت ام سلیم اور حضرت ام حرام سے جہ وکہ بہنیں تھیں، آپ کا کوئی ایسا رشتہ تھا جس کی بنا پر وہ آپ کی محرم تھیں، اس لیے آپ کبھی کبھی ان کے گھروں میں جاتے تھے اور کبھی استرحت بھی فرماتے تھے۔\n5۔ ’’اکٹھا کرکے‘‘ عربی میں لفظ نشَّفَتْهُ استعمال کیا گی اہے جس کے معنی خشک کرنے کے ہیں۔ گویا انہوں نے کسی کپڑے میں پسینہ جذب کر لیا اور وہ کپڑا اپنی خوشبو میں نچوڑ لیا یا خالی شیشی میں۔ واللہ أعلم۔\n6۔ ’’مسکرانے لگے‘‘ ان کے حسن عقیدت پر اور حسن ادب کو دیکھ کر۔ یہ بحث پیچھے گزر چکی ہے کہ ایسا تبرک صرف رسول اللہ صلی اللہ علیہ وسلم سے خاص تھا۔"}],[5372,"ابووائل سے روایت ہے کہ سمرہ بن سہم جو ابووائل کے قبیلے کے ہیں کہتے ہیں کہ میں نے ابوہاشم بن عتبہ رضی اللہ عنہ کے یہاں ٹھہرا، وہ طاعون میں مبتلا تھے، چنانچہ ان کی عیادت کے لیے معاویہ رضی اللہ عنہ آئے، تو ابوہاشم رونے لگے، معاویہ رضی اللہ عنہ نے کہا: کیوں رو رہے ہو؟ کیا کسی تکلیف کی وجہ سے رو رہے ہو یا دنیا کے لیے؟ دنیا کی راحت تو اب گئی، انہوں نے کہا: ایسی کوئی بات نہیں ہے، دراصل مجھے رسول اللہ صلی اللہ علیہ وسلم کا ایک عہد یاد آ گیا جو آپ نے مجھ سے لیا تھا، میں چاہتا تھا کہ میں اس کی پیروی کروں، آپ نے فرمایا: \"تیرے سامنے ایسے اموال آئیں گے جو لوگوں کے درمیان تقسیم کیے جائیں گے، لیکن تمہارے لیے اس میں سے صرف ایک خادم اور اللہ کی راہ کے لیے ایک سواری کافی ہے، لیکن میں نے مال پایا پھر اسے جمع کیا\"۔","الألباني: حسن",{"u2":"حضرت سمرہ بن سہم سے روایت ہے کہ میں سیدنا ہاشم عتبہ رضی اللہ عنہ کا مہمان بنا۔ ان کو طاعون کا عرضہ لاحق ہوچکا تھا۔ ھضرت معاویہ رضی اللہ عنہ ان کی بیمارپرسی کے لیے آئے تو حضرت ابو ہاشم رونے لگے۔ سیدنا معاویہ رضی اللہ عنہ نے فرمایا: آپ کیوں رو رہے ہیں؟ کیا کوئی تکلیف آپ کو بے چین کر رہے ہے؟ یا دنیا (سے جانے) کا غم ہے جب کہ آپ کی دنیا کا بہترین حصہ گزر چکا ہے؟ انہوں نے فرمایا: ان دونوں میں سے کوئی نصیحت فرمائی تھی۔ کاش میں اس پر قائم رہتا آپ صلی اللہ علیہ وسلم نے فرمایا تھا: شاید تجھ پر وہ دور آئے جب لوگوں میں بے تحاشا مال تقسیم کیے جائیں گے۔ تجھے صرف ایک نوکر اور ایک سواری جہاد کے لیے کافی ہے۔ ‘‘\n(واقعتاً وہ دور یا مال) میں نے پایا لیکن میں نے زیادہ مال جمع کر لیا۔","f2":"1۔ امام نسائی رحمہ اللہ نے جو عنوان قائم کیا ہے اس کا مقصد یہ مسئلہ بیان کرنا ہے کہ آدمی نوکر اور سواری رکھ سکتا ہے۔ یہ عیش عشرت یا عیاشی کے قبیل سے نہیں بلکہ ایک ضرورت ہے۔\n2۔ یہ حدیث مبارکہ دنی، اس کی رنگینیوں، نیز دنیا کی نعمتوں اور اس کا زیادہ مال و متاع جمع کرنے سے بے رغبتی پر دلالت کرتی ہے۔ حقیقت بھی یہی ہے کہ ایک بندۂ مومن کی کوشش دنیا کمانے کی بجائے آخرت کمانے کی ہوتی ہے اور اس کی اصل ترجیح اس فانی دنیا کی نعمتوں کا حصول نہیں بلکہ ابدی و دائمی اور لازوال اخروی نعمتوں کا حصول ہی ہوتی ہے حرام اور ناجائز کمائی کے ڈھیر جمع کرنے کی بجائے تھوڑی لیکن حلال اور پاکیزہ کمائی پر توجہ دینا ہی فرض ہے۔ اس کی واضح دلیل حضرات صحابۂ کرام رضی اللہ عنہم کا انداز حیات ہے۔ اللّهُمَّ وَفقنا لما تحِبُّه و تر ضاه\n3۔ ’’بہترین حصہ‘‘ یعنی رسول اللہ صلی اللہ علیہ وسلم کی رفاقت یا جوانی والا۔\n4۔ ’’مال‘‘ یعنی غنیمتیں زیادہ ہوں گی۔\n5۔ ’’جمع کرلیا‘‘ یہ ان کی کسر نفسی تھی ورنہ انہوں نے کوئی ترکہ نہیں چھوڑا تھا۔ رضي الله عنه وأرضاه۔"}],[5373,"ابوامامہ بن سہل رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کی تلوار کا دستہ چاندی کا تھا۔","الألباني: صحيح",{"u2":"سیدنا ابو امامہ بن سہل رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم کی تلوار کے دستے کے کنارے پر چاندی لگی تھی۔","f2":"چاند سونے کے برتنوں میں کھانا پینا منع ہے، نیز مرد کے لیے سونے کے زیورات بھی منع ہیں کیونکہ ان میں تکبر اور تعیش ہے مگر تلوار تو جاں کوشی بلکہ جاں فشانی کی علامت ہے۔ اس پر تھوڑا بہت سونا چاندی لگا ہو تو کوئی خرابی نہیں۔ جہاد تعیش سے کوسوں دور ہے، اس لیے تلوار کو چاندی سونے سےمزین کیا جاسکتا ہے بشرطیکہ سونا مقطع، یعنی چھوٹے چھوٹے نشانات کی صورت میں ہو، نیز زیادہ مقدار میں نہ ہو۔ تفصیل پیچھے گزر چکی ہے۔ دیکھیے: (حدیث:5152)"}],[5374,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کی تلوار کے نیام کا نچلا حصہ چاندی کا تھا، آپ کی تلوار کا دستہ بھی چاندی کا تھا، اور ان کے درمیان میں چاندی کے حلقے تھے۔","الألباني: صحيح",{"u2":"سیدنا انس رضی اللہ عنہ نے فرمایا؛ رسول اللہ صلی اللہ علیہ وسلم کی تلوار کا نعل چاندی کا تھا۔ اس کے دستے کے کنارے پر بھی چاندی لگی تھی اور درمیان میں بھی چاندی کے حلقےبنے تھے۔","f2":"نعل سے مراد وہ چاندی یا لوہا ہے جو تلوار کی میان کے نبیچے لگا ہوتا ہے۔ گویا آپ کی میان میں لوہے کی بجائے چاندی لگی تھی۔ اور قبیعہ سے مراد وہ چاندی یا لوہا ہے جسے تلوار کے دستے کے ایک کنارے میں لگایا جاتا ہے۔"}],[5375,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ قبیلہ عکل کے آٹھ آدمی نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے، انہیں مدینے کی آب و ہوا راس نہیں آئی، بیمار پڑ گئے، انہوں نے اس کی شکایت رسول اللہ صلی اللہ علیہ وسلم سے کی۔ آپ نے فرمایا: \"کیا تم ہمارے چرواہوں کے ساتھ اونٹوں میں جا کر ان کا دودھ اور پیشاب پیو گے؟\" وہ بولے: کیوں نہیں، چنانچہ وہ نکلے اور انہوں نے ان کا دودھ اور پیشاب پیا ۲؎، تو اچھے ہو گئے، اب انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے چرواہے کو قتل کر ڈالا، آپ صلی اللہ علیہ وسلم نے ان کے پیچھے کچھ لوگ روانہ کئے، جنہوں نے انہیں گرفتار کر لیا، جب انہیں لایا گیا تو آپ نے ان کے ہاتھ اور قبیلہ عرینہ کے مجرمین کے پاؤں کاٹ دئیے، ان کی آنکھیں (گرم سلائی سے) پھوڑ دیں اور انہیں دھوپ میں ڈال دیا گیا یہاں تک کہ وہ مر گئے ۳؎۔\n§وضاحت\n۱؎: اس آیت کے سبب نزول کے سلسلہ میں علماء کا اختلاف ہے، جمہور کا کہنا ہے کہ اس کا نزول قبیلہ عرنین کے مجرمین کے بارے میں ہوا ہے جب کہ مالک، شافعی، ابوثور اور اصحاب رأے کا کہنا ہے کہ اس کے نزول کا تعلق مسلمانوں میں سے ہر اس شخص سے ہے جو رہزنی اور زمین میں فساد برپا کرے، امام بخاری اور امام نسائی جمہور کے موافق ہیں۔ ۲؎: جمہور علماء محدثین کے نزدیک جن جانوروں کا گوشت حلال ہے ان کا پیشاب پائخانہ پاک ہے، اور بوقت ضرورت ان کے پیشاب سے علاج جائز ہے۔ جیسا کہ آپ صلی اللہ علیہ وسلم نے ان کو حکم دیا۔ ۳؎: ان لوگوں نے رسول اللہ صلی اللہ علیہ وسلم کے چرواہے کے ساتھ جس طرح کیا تھا اسی طرح آپ نے ان کے ساتھ قصاص کے طور پر کیا، یا یہ لوگ زمین میں فساد برپا کرنے والے باغی تھے اس لیے ان کے ساتھ ایسا کیا، جمہور کے مطابق اگر اس طرح کے لوگ مسلمان ہوں تو جن ہوں نے قتل کیا ان کو قتل کیا جائے گا، اور جنہوں نے صرف مال لیا ان کے ہاتھ پاؤں کاٹے جائیں گے، اور جنہوں نے نہ قتل کیا اور نہ ہی مال لیا بلکہ صرف ہنگامہ مچایا تو ایسے لوگوں کو اس جگہ سے ہٹا کر دوسری جگہ قید کر دیا جائے گا۔\nسعید بن ابی الحسن کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کی تلوار کا دستہ چاندی کا تھا۔","الألباني: صحيح",{"u2":"حضرت سعید بن ابی الحسن نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم کی تلوار کے دستے کے کنارے پر چاندی لگی ہوئی تھی۔"}],[5376,"علی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا: کہو: \" «اللہم سددني واهدني» اے اللہ مجھے درست رکھ اور ہدایت عطا کر\" اور آپ نے مجھے «میاثر» پر بیٹھنے سے منع فرمایا، «میاثر» ایک قسم کا ریشمی کپڑا ہے، جسے عورتیں اپنے شوہروں کے لیے پالان پر ڈالنے کے لیے بناتی تھیں۔ جیسے گلابی رنگ کی چھوردار چادریں۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے فرمایا: ’’تو یہ دعا کیا کر [اللّہمَّ! سَدِّدّنِیْ وَہدِنی] ’’اے اللہ! مجھے سیدھا رکھنا اور ہدایت پر قائم رکھنا۔‘‘ نیز آپ نے مجھے ریشمی گدیلوں پر بیٹھنے سے منع فرمایا۔ اور یہ گدیلے قسی (ریشمی) کپڑے سے بنے ہوتے تھے جنہیں عورتیں اپنے خاوندوں کے لیے پالان پر رکھنے کی غرض سے بناتی تھیں اور یہ رنگ میں ارجوانی رنگ کی چادروں جیسے ہوتے تھے۔","f2":"تفصیل کے لیے دیکھیے، احادیث: 69، 5168، 5187"}],[5377,"ابورفاعہ رضی اللہ عنہ کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس گیا، آپ خطبہ دے رہے تھے۔ میں نے عرض کیا: اللہ کے رسول! ایک اجنبی شخص اپنے دین کے بارے میں معلومات کرنے آیا ہے، اسے نہیں معلوم کہ اس کا دین کیا ہے؟ چنانچہ رسول اللہ صلی اللہ علیہ وسلم متوجہ ہوئے اور خطبہ روک دیا یہاں تک کہ آپ مجھ تک پہنچ گئے، پھر ایک کرسی لائی گئی، میرا خیال ہے اس کے پائے لوہے کے تھے، رسول اللہ صلی اللہ علیہ وسلم اس پر بیٹھے اور مجھے سکھانے لگے جو اللہ تعالی نے انہیں سکھایا تھا، پھر آپ لوٹ کر آئے اور اپنا خطبہ مکمل کیا۔","الألباني: صحيح",{"u2":"سیدنا ابو رفاعہ رضی اللہ عنہ نے فرمایا: میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا جبکہ آپ خطاب فرمارہے تھے۔ میں نے کہا: اے اللہ کے رسول! ایک اجنبی آدمی آیا ہے، اپنے دین کے بارے میں سوال کرتا ہے۔ وہ نہیں جانتا کہ دین کیا ہوتا ہے؟ رسول اللہ صلی اللہ علیہ وسلم متوجہ ہوئے، اپنا خطبہ چھوڑ اور میرے پاس پہنچ گئے۔ آپ کے پاس ایک کرسی لائی گئی میرا خیال ہے کہ اس کے پائے لوہے کے تھے۔ رسول اللہ صلی اللہ علیہ وسلم اس پر تشریف فرما ہوگئے۔ اور مجھے وہ علم سکھانے لگے جو اللہ تعالیٰ نے آپ کو سکھایاتھا، پھر خطبے کی جگہ تشریف لے گئے اور اپنا خطبہ مکمل فرمایا۔","f2":"۔ یہ حدیث مبارکہ رسول اللہ صلی اللہ علیہ وسلم کی تواضع عالی ظرفی اور اہل اسلام کے ساتھ آپ کی بے پناہ محبت و شفقت کی دلیل ہے، نیز اس سے یہ معلوم ہوا کہ اہل علم کو سائلین اور طلبہ علم کے ساتھ انتہائی نرمی اور شفقت کا رویہ اپنانا چاہیے۔ علم کے پیاسوں کی علمی پیاس بجھانی چاہیے اور فتویٰ طلب کرنے والوں کو کتاب و سنت کے مطابق صحیح اور درست فتویٰ دے کر ان کی کما حقہ دینی رہنمائی کا فریضہ سر انجادم دینا چاہیے جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنا خطبہ مبارک ادھورا چھوڑ کر سائل کی علمی پیاس اور تشنگی بجھائی، اسے قرآن و ھدیث کا علم سکھایا اور بعد ازاں اپنا خطبہ مکمل فرمایا۔ فِدَاه أبي و نفسي و روحي۔\n2۔ باب كا مقصود یہ ہے کہ کرسی پر بیٹھنا جب کہ دیگر لوگ نیچے بیٹھے ہوں، منع نہیں، اگر اس کی ضرورت ہو، مثلاً: خطاب کرنا تا کہ سب لوگ سننے کے ساتھ ساتھ آسانی سے دیکھ بھی سکیں، ویسے بھی کرسی پر بیٹھنا تکبر کو مستلزم نہیں۔"}],[5378,"ابوحجیفہ رضی اللہ عنہ کہتے ہیں کہ ہم لوگ بطحاء میں نبی اکرم صلی اللہ علیہ وسلم کے ساتھ تھے، آپ ایک لال خیمے میں تھے اور آپ کے پاس تھوڑے سے لوگ بیٹھے تھے، اتنے میں آپ کے پاس بلال رضی اللہ عنہ آئے اور انہوں نے اذان دینی شروع کی، تو اپنا منہ اِدھر اُدھر کرنے لگے ۱؎۔\nكتاب آداب القضاة\n§وضاحت\n۱؎: یعنی «حي على الصلاة» اور «حي على الفلاح» کے وقت اپنا رخ دائیں اور بائیں کرنے لگے۔","الألباني: صحيح",{"u2":"سیدنا ابو جحیفہ رضی اللہ عنہ بیان کرتے ہیں کہ ہم نبیٔ اکرم صلی اللہ علیہ وسلم کے ساتھ بطحاء مکہ میں تھے جبکہ آپ سرخ رنگ کے ایک خیمے میں تشریف فرماتھے اور اآپ کے پاس کچھ لوگ تھے آپ سفر شروع کرنا چاہتے تھے۔ حضرت بلال آپ کے پاس آئے اور آذان دی۔ وہ اپنا منہ ادھر ادھر کرتے تھے۔","f2":"1۔ سرخ رنگ کا بلکہ کسی بھی رنگ کا خیمہ لگانا جائز ہے۔\n2۔ ’’ادھر ادھر‘‘ یعنی حيَّ علي الصلاة حيَّ عليَ الفلاح کہتے وقت دائیں بائیں کرتے تھے نہ کہ ساری اذان میں۔\n3۔ جس طرح خیمہ سرخ ہو سکتا ہے، اس طرح عمارت بھی سرخ ہو سکتی ہے۔"}],[5379,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ مومن کا قتل اللہ تعالی کے نزدیک دنیا کے ہلاک و برباد ہونے سے زیادہ بڑی بات ہے۔\nعبداللہ بن عمرو بن العاص رضی اللہ عنہما روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی کے نزدیک انصاف کرنے والے لوگ رحمان (اللہ)کے دائیں نور کے منبر پر ہوں گے\" ۱؎، یعنی وہ لوگ جو اپنے فیصلوں میں اپنے گھر والوں کے ساتھ اور ان لوگوں کے ساتھ جو ان کے تابع ہیں انصاف کرتے ہیں۔ مدد بن آدم کی روایت میں ہے: \"اللہ کے دونوں ہاتھ داہنے ہیں\"۔\n§وضاحت\n۱؎: حقیقت میں انہیں نور کے منبر ملیں گے اور ساتھ ہی ساتھ انہیں بلند درجات بھی نصیب ہوں گے۔","الألباني: سكت عنه الشيخ",{"u2":"سیدہ عبد اللہ بن عمرو بن عاص رضی اللہ عنہا سے روایت ہے کہ نبیٔ اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’انصاف کرنے والے اللہ تعالیٰ کے ہاں نور کے منبروں پر رحمٰن کی دائٰں جانب ہوں گے۔ جو عدل کرتے ہیں اپنے فیصلوں میں اور اپنے گھر والوں کے ساتھ اور اپنی رعایا کے ساتھ۔‘‘\nاستاد محمد بن آدم نے اپنی روایت میں کہا: اللہ تعالیٰ کے دونوں ہاتھ داہنے ہی ہیں۔","f2":"1۔ عدل و انصاف سے مراد ہر حق والے کو اس کا حق دینا ہے۔ اور لوگوں سے ان کے مقام و مرتبے کے مطابق سلوک کرنا ہے، خواہ عدالت کی کرسی ہو یا حاکم ک تخت، گھر ہو یا باہر، مسجد ہو یا مدرسہ۔\n2۔ ’’دائیں جانب‘‘ مراد عزت و احترام ہے کیونکہ دایاں ہاتھ یا دائیں جانب عزت و احترام کی علامت خیال کیے جاتے ہیں ورنہ اللہ تعالیٰ کے دونوں ہاتھ ہی داہنے ہیں، جیسا کہ خود حدیث کے آخری الفاظ صریح ہیں۔\n3۔ ’’نور کے ممبر‘‘ لکڑی اور پتھی کا منبر ہو سکتا ہے تو نور کا کیوں نہیں؟ جب کہ فرشتے قطعاً نوری مخلوق ہیں۔ بعض محققین نے اس سے بلند درجات مراد لیے ہیں مگر منبر کی نفی کی ضرورت نہیں جب کہ انسان کا بایاں دائیں سے ناقص سہوتا ہے۔\n5۔ اس روایت میں اللہ تعالیٰ کے لیے لفظ یدٌ یعنی ’’ہاتھ‘‘ استعمال فرمایا گیا ہے۔ گویا اللہ تعالیٰ کی شان میں یہ لفظ استعمال ہوسکتا ہے۔ اس سے تشبیہ یا تجسیم لازم نہیں آئے گی۔ اسی طرح آنکھ، کان پاؤں وغیرہ۔ اگر ان لافاظ سے کوئی خرابی لازم آتی ہوتی یا یہ باری تعالیٰ کے شایان شان نہ ہوتے تو قرآن و حدیث میں اللہ تعالیٰ کے لیے یہ الفاظ استعمال نہ ہوتے۔ ان پچیدہ مسائل کو اللہ اور اس کا رسول ہی بہتر جانتے ہیں۔ ہمیں خواہ مخواہ اس میں ٹانگ نہیں اڑانی چاہیے اور اللہ اور اس کے رسول صلی اللہ علیہ وسلم کو مشورے نہیں دینے چاہئیں۔ رموز مصلحت ملک خسرواں دانند۔ البتہ ہم ان الفاظ سے اللہ تعالیٰ کی ذات میں وہ مفہوم مراد نہیں لے سکتے جو انسانوں وغیرہ میں لیے جاتے ہیں۔ وہ ایسے ہیں جیسے اس کی شان کے لائق ہیں کیونکہ ﴿لَيْسَ كَمِثْلَهٖ شَيْءٌ﴾ (الشوریٰ، 11:42)\nاللہ تعالیٰ کی ذات اور اس کی صفات ہماری عقل میں آنے والی چیزیں نہیں اور نہ ہماری عقل ان مسائل کو حل کرنے یا سمجھنے کے لیے بنائی گئی ہے اور نہ اس میں یہ استعداد ہی ہے بھلا ایک محدود سے لا محدود کا احاطہ کس طرح ممکن ہے۔ ہمارا کام صرف یہ ہے کہ ہم انہیں تسلیم کریں، استعمال کریں اور حقیقت کی بحث نہ کریں کیونکہ ہم سے ایسی باتیں نہیں پوچھی جائیں گی۔ درحقیقت یہ عقل مندی ہے۔"}],[5380,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سات لوگ ہیں اللہ تعالی انہیں قیامت کے دن (عرش کے) سائے میں رکھے گا، جس دن کہ اس کے سوا کسی کا سایہ نہ ہو گا: انصاف کرنے والا حاکم، وہ نوجوان جو اللہ تعالی کی عبادت میں بڑھتا جائے، وہ شخص جس نے تنہائی میں اللہ تعالی کو یاد کیا تو اس کی آنکھیں آنسوؤں سے بھر آئیں، وہ شخص جس کا دل مسجد میں لگا رہتا ہے، دو ایسے لوگ جو اللہ تعالی کے لیے آپس میں دوست ہوں، ایسا شخص جسے رتبے والی خوبصورت عورت (اپنے ساتھ غلط کام کرنے کے لیے) بلائے تو وہ کہہ دے: مجھے اللہ تعالی کا ڈر لگ رہا ہے، ایک ایسا شخص جو صدقہ کرے تو اس طرح چھپا کر کہ اس کے بائیں ہاتھ کو خبر نہ ہو کہ اس کے دائیں ہاتھ نے کیا کیا ہے؟\"۔","الألباني: صحيح",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ‘‘سات قسم کے لوگ ایسے ہیں جن کو اللہ تعلایٰ قیامت کے دن سایہ مہیا فرمائے گا۔ جس دن اللہ تعالیٰ کے سائے کے علاوہ اور کوئی سایہ نہیں ہوگا۔\nعادل حکمران۔\n2۔ وہ نوجوان جو اللہ تعالیٰ کی عبادت میں پھلے پھولے۔\n3۔ جو شخص اللہ تعالیٰ کو تنہائی میں یاد کرے اور اس کی آنکھوں سے نے ساختہ آنسو بہہ نکلیں۔\n4۔ وہ آدمی جس کا دل مسجد میں اٹکا رہتا ہے۔\n5۔ وہ دو شخص جو ایک دوسرے سے اللہ تعالیٰ کی خاطر محبت کریں۔\n6۔ وہ شخص جسے کوئی خوب رو اور معزز عورت (برائی کی) دعوت دے اور وہ کہہ دے کہ میں اللہ تعالیٰ سے ڈرتا ہوں۔\n7۔ وہ شخص جو اس قدر چھپا کر صدقہ کرے کہ اس کے بائیں ہاتھ کو بھی پتا نہ چلے کہ دائیں نے کیا کیا ہے۔‘‘","f2":"1۔ صدقہ خیرات کرنا افضل ہے۔ اس حدیث مبارکہ سے پوشیدہ طور پر صدقہ خیرات کرنے کی بابت معلوم ہوتا ہے کہ وہ بہت ہی افضل عمل ہے کہ ایسے عامل کو عرش الٰہی کا سایہ نصیب ہوگا۔ زہے نصیب! اللّهُمَّ اجْلعلْنا مِنهُم۔ آمين۔\n2۔ یہ حدیث مبارکہ خشیت الٰہی، یعنی اللہ تعالیٰ کے خوف سے رونے کی فضیلت پر بھی دلالت کرتی ہے بالخصوص مخلوق سے چھپ چھپا کر رونے کی تو بات ہی اور ہے۔ جس خوش بخت کو یہ عظیم دولت مل جائے واقعی وہ شخص خوش قسمت ترین انسان ہوتا ہے۔ ایسا صرف وہ شخص کرے گا جسے کمال اخلاص کی دولت حاصل ہو۔ ایسا کرنے والا شخص بھی روز قیامت عرش الٰہی کے سائے کا حق دار ہوگا۔ اَلَّهُمَّ اجْعَلْنا مِنهُم۔\n3۔یہ حدیث مبارکہ محض اللہ تعالیٰ کی رضا اور خوشنودی حاصل کرنے کی خاطر باہم محبت کرنے کا شوق دلاتی ہے، نیز ایسا کرنے والوں کی عظیم فضیلت اور ان کے لیے خوبصورت اجر و ثواب بھی بیان کرتی ہے۔\n4۔ ’’سات قسم کے لوگ‘‘ دیگر احادیث میں ان سات قسموں کے علاوہ بھی مذکور ہیں۔ ان سے ان کی نفی نہیں ہوتی۔\n5۔ ’’اللہ تعالیٰ کا سایہ‘‘ جیسا اس کی شان کے لائق ہے یا پھر اس سے مراد عرش کا سایہ ہے جیسا کہ بعض روایات میں ہے۔ دیکھیے: (المعجم الكبير للطبراني، ج:20، حديث:146، 147، و صحيح الجامع الصغير، حديث:1937)\n6۔ ’’جوان‘‘ كيونكه بوڑھا آدمی عبادت نہیں کرے گا تو کیا کرے گا؟ وقت پیری گرگ ظالم می شود پرہیز گار۔ اصل فضیلت جوانی کی عبادت کی ہے۔\n7۔ ’’اٹکا رہتا ہے‘‘ اس کو مسجد میں سکون حاصل ہوتا ہے۔ مسجد سے باہر بے چین رہتا ہے اور اگلی نماز کے لیے منتظر رہتا ہے۔"}],[5381,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب حاکم فیصلہ (کا ارادہ) کرے اور اجتہاد سے کام لے پھر وہ صحیح فیصلہ تک پہنچ جائے تو اس کے لیے دو اجر ہیں، اور اگر اجتہاد کرنے میں غلطی کر بیٹھے تو اس کے لیے ایک اجر ہے۔\n§وضاحت\n۱؎: \"حاکم\" مراد وہ حاکم ہے جو عالم ہونے کے ساتھ ساتھ فیصلہ کرنے کی صلاحیت بھی رکھتا ہو، قدیم و جدید سارے علما مجتہدین کے اجتہادات کا بھی یہی حکم ہے۔ کسی غلط فیصلہ یا اجتہاد کا گناہ حاکم یا عالم یا امام پر تو نہیں ہو گا، مگر جان بوجھ کر کسی امام یا عالم کے کسی فتوے پر اڑے رہ جانے والوں کو ضرور گناہ ہو گا۔","الألباني: صحيح",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب کوئی حاکم فیصلہ کرتے وقت صحیح نتیجے تک پہنچنے کی کوشش کرے اور صحیح فیصلہ کر دے تو اس کو دگنا ثواب ملے گا اور اگر وہ کوشش کرے لیکن صحیح فیصلے تک نہ پہنچ سکے تو اس کے لیے اکہرا ثواب ہے۔‘‘","f2":"انسان کے بس میں کوشش ہی ہے۔ اگر وہ کوشش کرے تو اسے کوشش کا ثواب ضرور ملتا ہے، نتیجہ حاسل ہو یا نہ کیونکہ نتیجہ انسان کے اختیار میں نہیں۔ حسن نیت اور کوشش ہی اصل ہے۔"}],[5382,"ابوموسی اشعری رضی اللہ عنہ کہتے ہیں کہ میرے پاس قبیلہ اشعر کے کچھ لوگوں نے آ کر کہا: ہمیں رسول اللہ صلی اللہ علیہ وسلم کے پاس لے چلئے، ہمیں کچھ کام ہے، چنانچہ میں انہیں لے کر گیا، ان لوگوں نے کہا: اللہ کے رسول! ہم سے اپنا کوئی کام لیجئیے ۱؎ میں نے آپ سے ان کی اس بات کی معذرت چاہی اور بتایا کہ مجھے نہیں معلوم کہ ان کی غرض کیا تھی، چنانچہ آپ نے میری بات کا یقین کیا اور معذرت قبول فرما لی اور فرمایا: ہم اپنے کام (عہدے) میں ایسے لوگوں کو نہیں لگاتے جو ہم سے اس کا مطالبہ کرتے ہیں ۲؎۔\n§وضاحت\n۱؎: یعنی ہمیں کوئی عہدہ دیجئیے۔ ۲؎: یعنی جو شخص منصب و عہدے کا طالب ہو ہم اسے یہ چیز نہیں دیتے کیونکہ اگر اسے صحیح طور پر انجام نہ دے سکا تو ایسے شخص کی صرف دنیا ہی نہیں بلکہ آخرت کی تباہی و بربادی کا بھی ڈر ہے، اور عہدہ و منصب کا طالب تو وہی ہو گا جو حصول دنیا کا خواہاں ہو۔","الألباني: صحيح",{"u2":"سیدنا ابو موسیٰ رضی اللہ عنہ سے روایت ہے، انہوں نے فرمایا کہ میرے پاس کچھ اشعری لوگ آئے اور کہا: ہمارے ساتھ رسول اللہ صلی اللہ علیہ وسلم کے پاس چلیں کیونکہ ہمیں (آپ سے) ایک کام ہے۔ میں ان کے ساتھ چل پڑا۔ وہ آپ سے کہنے لگے: اے اللہ کے رسول! ہمیں کسی کام پر مقرر فرمائیے۔ حضرت ابو موسیٰ نے کہا: میں نے ان کی اس بات پر (آپ سے) معذرت کی اور آپ کو بتلایا کہ مجھے علم نہیں تھا کہ انہیں کیا کام ہے؟ (ورنہ میں ان کے ساتھ نہ آتا) آپ نے مجھے سچا جانتے ہوئے میری معذرت کو تسلیم فرمایا اور ارشاد فرمایا: ’’ہم کسی ایسے شخص کو اپنے کسی کام پر مقرر نہیں کرت ے جو خود طلب کرے۔‘‘","f2":"جو شخص عہدے کا حریص ہو، وہ دیانت داری کےساتھ اپنے فرائض ادا نہیں کر سکے گا۔ وہ اپنے عہدے کو شان و شوکت یا دولت کے حصول کا ذریعہ بنائے گا، نیز اسے اللہ تعالیٰ کی طرف سے مدد اور توفیق بھی حاصل نہیں ہوگی، لہٰذا اسے عہدے پر مقرر نہ کیا جائے۔ البتہ اگر حکومت خود درخواستیں طلب کرے تو درخواست دی جاسکتی ہے۔ اس میں کوئی حرج نہیں اور ایسے شخص کو عہدہ بھی دیا جا سکتا ہے۔ (مزید تفصیل کے لیے دیکھیے، حدیث:4)"}],[5383,"اسید بن حضیر رضی اللہ عنہ سے روایت ہے کہ انصار کے ایک شخص نے رسول اللہ صلی اللہ علیہ وسلم کے پاس آ کر کہا: کیا آپ مجھے کام نہیں دیں گے جیسے فلاں کو دیا ہے؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"میرے بعد تم پاؤ گے کہ ترجیحات ۱؎ ہوں گی ایسے حالات میں تم صبر سے کام لینا یہاں تک کہ حوض پر تم مجھ سے ملو\"۔\n§وضاحت\n۱؎: مستحق اور اہلیت والے کو محروم کر کے نالائق کو کام پر رکھنا۔","الألباني: صحيح",{"u2":"سیدنا اسید بن حضیر رضی اللہ عنہ سے منقول ہے کہ ایک انصاری رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور کہا کیا آپ مجھے عامل مقرر نہیں فرمائیں گے جس طرح فلاں کو مقرر فرمایا ہے؟ آپ نے فرمایا: ’’میرے بعد تم محسوس کروگے کہ دوسروں کو تم پر ترجیح دی جارہی ہے، تو تم صبر کرنا حتیٰ کہ مجھے حوض پر ملو۔‘‘","f2":"1۔ حدیث مبارکہ انصار کی منقبت و عظمت پر دلالت کرتی ہے کہ نبیٔ اکرم صلی اللہ علیہ وسلم نے ان کی مدح فرمائی ہے، نیز آپ نے انہیں صبر کی تلقین بھی فرمائی۔\n2۔ یہ حدیث مبارکہ اعلام نبوت میں سے ایک بہت بڑی نشانی بھی ہے کہ جس طرح آپ نے پیش گوئی فرمائی تھی بعد ازاں اسی طرح ہوا۔\n3۔ ہر شخص کو عہدے پر مقرر نہیں کیا جاسکتا کیونکہ اسامیں اتنی نہیں ہوتیں، لہٰذا دوسرے لوگوں کو حسد اور بغاوت کا اظہار نہیں کرنا چاہیے بلکہ صبر کرنا چاہیے ورنہ افراتفری پھیل سکتی ہے۔\n4۔ ’’تم محسوس کروگے‘‘ تم سے مراد عام لوگ بھی ہو سکتے ہیں اور خصوصا! انصار بھی کیونکہ بعد میں حکومت قریش کے پاس ہی رہی اور سرکاری عہدوں پر عموماً قریشی ہی فائز رہے۔\n5۔ ’’حتیٰ کہ مجھے حوض پر ملو‘‘ یعنی صبر کے نتیجے میں تمہیں حوض کو ثر نصیب ہوگا۔ یہ معنی بھی ہوسکتے ہیں کہ ’’صبر کرنا تا کہ تمہیں حوض کوثر نصیب ہو‘‘ اور میرا دیدار حاصل ہو جب کہ لڑائی جھگڑے کی صورت میں دونوں چیزوں سے محرومی ہو سکتی ہے۔"}],[5384,"عبدالرحمٰن بن سمرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"منصب طلب مت کرو، اس لیے کہ اگر مانگے سے وہ تمہیں ملا تو تم اسی کے سپرد کر دئیے جاؤ گے ۱؎ اور اگر وہ تمہیں بن مانگے مل گیا تو تمہاری اس میں مدد ہو گی\"۔\n§وضاحت\n۱؎: یعنی اللہ کی نصرت و تائید سے تم محروم رہو گے اور کوئی مدد نہیں ملے گی۔","الألباني: صحيح",{"u2":"سیدنا عبد الرحمٰن بن سمرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’حکومت نہ مانگ کیونکہ اگر تجھے مانگنے کے نتیجے میں حکومت مل بھی گئی تو تجھے حکومت کے لیے اکیلا چھوڑ دیا جائے گا۔ اور اگر تجھے مانگے بغیر حکومت ملی تو (اللہ تعالیٰ کی طرف سے) تیری مدد کی جائے گی۔‘‘","f2":"1۔ حکومت اور امارت ایک ذمے داری ہے جس کی جو اب دہی بھی کرنا ہوگی۔ کمی کوتاہی کی صورت میں سزا بھی بھگتنا ہوگی۔ اور کمی کوتاہی ہو جانا لازمی امر ہے، اس لیے خواہ مخواہ اس مصیبت کو گلے نہ ڈالا جائے، البتہ اللہ تعالیٰ کی طرف سے کوئی ذمہ داری آن پڑے، لوگ زبردستی گلے میں ڈال دیں تو اللہ کا نام لے کر سنبھال لے۔ اس صورت میں اللہ تعالیٰ کی توفیق بھی شامل حال ہوگی اور لوگ بھی تعاون کریں گے۔\n2۔ ’’اکیلا چھوڑ دیا جائے گا‘‘ یعنی نہ اللہ تعالیٰ توفیق عطا فرامئے گا نہ لوگوں کا تعاون حاصل ہوگا۔ ظاہر ہے، پھر صرف بدنامی ہی ہوگی اور ناکامی کا سامنا ہوگا۔ لفظی معنی ہیں: ’’تجھے امرت کے سپرد کر دیا جائےگا۔‘‘ (نیز دیکھیے: حدیث:5384)"}],[5385,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"عنقریب تم لوگ منصب کی خواہش کرو گے، لیکن وہ باعث ندامت و حسرت ہو گی پس دودھ پلانے والی کتنی اچھی ہوتی ہے، اور دودھ چھڑانے والی کتنی بری ہوتی ہے، (اس لیے کہ ملتے وقت وہ بھلی لگتی ہے اور جاتے وقت بری لگتی ہے\") ۱؎۔\n§وضاحت\n۱؎: یعنی: حکومت اور منصب والی زندگی تو بھلی لگے گی لیکن اس کے بعد والی زندگی ابتر اور بری ہو گی۔","الألباني: صحيح",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی ٔ اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’امارت کی خواہش کرو گے جبکہ یہ قیامت کے دن ندامت اور افسوس و حسرت (کا سبب) بن جائے گی۔ یہ دودھ پلاتی رہے تو اچھی لگتی ہے۔ دودھ چھڑادے تو بری لگتی ہے۔‘‘","f2":"اس حدیث میں حکومت کو عورت کے ساتھ تشبیہ دی گئی ہے کہ دودھ پلانے والی (عورت) بچے کو اچھی لگتی ہے۔ وہ اس سے محبت کرتا ہے لیکن جب وہی عورت دودھ چھڑا دے تو پھر وہ اس سے نفرت کرنا لگتا ہے۔ لاتیں مارتا ہے اور چیختا چلاتا ہے۔ یہی حالت حکومت اور حاکم کا ہے کہ جب تک وہ برسر اقتدار رہے، وہ حکومت کے نشے میں مست رہتا ہے اور اپنے آپ کو خوش قسمت ترین آدمی سمجھتا ہے۔ بلکہ خوب عیاشیاں کرتا لیکن جب حکومت چھن جاتی ہے تو آنکھیں کھل جاتی ہیں۔ اقتدار رہ رہ کر یاد آتا ہے۔ پھر وہ آہ و بکا کرتا ہے اور جب اسے پانے دور اقتدار کا حسب دینا پڑتا ہے تو پھر وہ حکومت سے نفرت کرنے لگتا ہے اور اپنے آپ کو بدقسمت ترین انسان سمجھتا ہے۔ اور اگر کوئی صاحب اقتدار اپنی موت تک حکمران رہے تو پھر آخرت میں اس سے برا حال ہوتا ہے۔ إلَّا مَا رحم ربّي۔ حدیث میں بھی اس طرف اشارہ موجود ہے۔ سیدنا عمر رضی اللہ عنہ جیسے بے مثال عادل حکمران کا قول ہے: ’’کاش میں اپنے دور اقتدار کے حساب سے بغیر کچھ لیے دیے (ثواب و عذاب) چھوڑ دیا جا ؤں۔‘‘ یہ اسی حقیقت کا اظہار رہے ورنہ ان کی خلافت کی تعریف تو خود رسول اللہ صلی اللہ علیہ وسلم نے پیش گوئی کی صورت میں فرمائی ہے۔ رَضِيَ اللهُ عَنْهُ وَ أَرْضَاهُ"}],[5386,"عبداللہ بن زبیر رضی اللہ عنہما بیان کرتے ہیں کہ بنو تمیم کے کچھ سوار نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے، ابوبکر رضی اللہ عنہ نے کہا: قعقاع بن معبد کو سردار بنائیے، اور عمر رضی اللہ عنہ نے کہا: اقرع بن حابس کو سردار بنائیے، پھر دونوں میں بحث و تکرار ہو گئی، یہاں تک کہ ان کی آواز بلند ہو گئی، تو اس سلسلے میں یہ حکم نازل ہوا \"اے لوگو! جو ایمان لائے ہو! اللہ اور اس کے رسول کے سامنے آگے مت بڑھو\" (یعنی ان سے پہلے اپنی رائے مت پیش کرو) یہاں تک کہ یہ آیت اس مضمون پر ختم ہو گئی: \"اگر وہ لوگ تمہارے باہر نکلنے تک صبر کرتے تو ان کے حق میں بہتر ہوتا\" ۱؎۔\n§وضاحت\n۱؎: شیخین :(ابوبکر و عمر رضی اللہ عنہما ) کی بحث و تکرار کے سبب ابتداء سورۃ سے «أجر عظیم» تک ۳ آیتیں نازل ہوئیں، اور آیت: «ولو أنهم صبروا حتى تخرج إليهم لكان خيرا لهم» اقرع بن حابس رضی اللہ عنہ کے آپ صلی اللہ علیہ وسلم کو زور زور سے «یا محمد اخرج» کہنے کی وجہ سے نازل ہوئی، ان میں سے اقرع شاعر تھے، یہی بات باب سے مناسبت ہے، یعنی: کسی شاعر ہونے کے سبب اس کو کسی عہدہ سے دور نہیں رکھا جا سکتا۔","الألباني: صحيح",{"u2":"سیدہ عبد اللہ بن زبیر رضی اللہ عنہا نے بیان فرمایا کہ بنو تمیم کا ایک قافلہ نبیٔ اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا۔ سیدنا ابوبکر رضی اللہ عنہ نے کہا: قعقاع بن معبد کو ان کا امیر مقرر فرما دیجیے۔ سیدنا عمر رضی اللہ عنہ نے کہا: اس کی بجائے اقرع بن حابس کو میر مقرر فرمائیں۔ اس بات پر دونوں آپس میں بحث و تکرار کرنے لگے حتیٰ کہ ان کی آوازیں بلند ہو گئیں تو اس کی بابت یہ آیت اتری: ’’اے اللہ ایمان والو! اللہ تعالیٰ اور اس کے رسول (صلی اللہ علیہ وسلم) سے آگے نہ بڑھو۔۔۔ اگر یہ لوگ صبر کرتے (اور آپ کو باہر سے آوازیں نہ دیتے) حتیٰ کہ آپ خود ان کے پاس تشریف لاتے تو ان کے لیے بہتر ہوتا۔‘‘","f2":"1۔ اس حدیث مبارکہ سے معلوم ہوا کہ کبھی کبھار بڑے بڑے عطماء اور جلیل القدر لوگوں سے بھی غلطی ہو جاتی ہے جیسا کہ امت محمدیہ کے افضل ترین انسان صدیق و فاروق رضی اللہ عنہا سے خطا صادر ہوئی، تاہم انہوں نے ایسی سچی توبکہ کی کہ مذکورہ وقعے کے بعد کبھی رسول اللہ صلی اللہ علیہ وسلم کے سامنے بلند آواز سے بات نہیں کی۔\n2۔ اس حدیث سے رسول اللہ صلی اللہ علیہ وسلم کی عظیم قدر و منزلت بھی واضح ہوتی ہے۔ کہ آپ کے سامنے کسی کو اونچی آواز سے بات کرنے کا حق بھی نہیں چہ جائیکہ آپ کے مقابلے میں کسی امتی کو درجۂ امامت پر فائز کر دیا جائے اور اس کی ہر بات کوآنکھیں بند کر کے تسلیم کر لیا جائے اور ساری زندگی نہ صرف اس کی اندھا دھند تقلید میں گزار دی جائے بلکہ بلا دلیل اس کی بات تسلیم نہ کرنے والوں کو طعن و تشنع کا نشانہ بنایا جائے۔\n3۔ اس حدیث میں مسئلہ الباب کا صراحتاً ذکر نہیں اگر کہیں اس کا ثبوت ملتا ہے کہ اقرع بن حابس بھی شاعری کرتے تھے تو پھر بات واضح ہے۔ واللہ أعلم۔\n4۔ قرآن مجید اور احادیث میں عموما! شعراء کی مذمت کی گئی ہے کیونکہ شعراء مبالغہ آرائی بلکہ جھوٹ، خوشامد اور تعلی کے عادی ہوتے ہیں اور شریعت ان اوصاف کو برا سمجھتی ہے۔ ویسے بھی حاکم کے لیے سنجیدہ طبع ہونا ضروری ہے اور یہ چیز پیشہ ور شعراء میں مفقود ہوتی ہے، اس لیے ظاہری طورپر سمجھ میں یہی آتا ہے کہ شعراء کو حاکم نہیں نبانا چاہیے مگر چونکہ ضروری نہیں کہ ہر شاعر ایسا ہی ہو خصوصاً جو پیشہ ور شاعر نہ ہو، لہٰذا اگر امارت کا اہل ہو تو اسے امیر بنایا جا سکتا ہے۔\n5۔ ’’آگے نہ بڑھو‘‘ یعنی اللہ اور اس کے رسول کے فیصلے سے قبل جلد بازی نہ کرو بلکہ ان کے فیسلے کا انتظار کرو جب تک رسول اللہ صلی اللہ علیہ وسلم خود مشورہ طلب نہ فرمائیں، تم خود بخود مشورہ نہ دو۔ امیر منتخب کرنا رسول اللہ صلی اللہ علیہ وسلم کا کام ہے نہ کہ تمہارا۔\n6۔ ’’صبر کرتے‘‘ اشارہ بنو تمیم کے وفد کی طرف ہے کہ جب وہ آئے تھے تو انہوں نے باہر کھڑے ہو کر زور زور سے آوازیں دینی شروع کردی تھیں: يَا مُحمّد! اُخْرُجْ ظاہر ہے یہ معقول انداز نہیں تھا۔ نبیٔ اکرم صلی اللہ علیہ وسلم جیسی عطیم شخصیت کو اس طرح نہیں بلایا جا سکتا بلکہ ان کا انتظار کیا جاتا ہے۔"}],[5387,"ہانی رضی اللہ عنہ سے روایت ہے کہ وہ جب رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور آپ نے لوگوں کو سنا کہ وہ ہانی کو ابوالحکم کی کنیت سے پکارتے تھے تو رسول اللہ صلی اللہ علیہ وسلم نے انہیں بلایا اور ان سے فرمایا: \"حکم تو اللہ ہے اور حکم کرنا بھی اسی کا کام ہے\"، وہ بولے: میری قوم کے لوگوں کا جب کسی چیز میں اختلاف ہوتا ہے تو وہ میرے پاس چلے آتے ہیں، میں ان کے درمیان فیصلے کرتا ہوں اور دونوں فریق رضامند ہو جاتے ہیں۔ آپ نے فرمایا: \"اس سے بہتر کیا ہو سکتا ہے، تمہارے کتنے لڑکے ہیں؟\" وہ بولے: شریح، عبداللہ اور مسلم، آپ نے فرمایا: \"ان میں بڑا کون ہے؟\" وہ بولے: شریح، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تو تم اب سے ابوشریح ہو\"، پھر آپ نے ان کے لیے اور ان کے بیٹے کے لیے دعا کی۔","الألباني: صحيح",{"u2":"سیدنا ہانی رضی اللہ عنہ سے منقول ہے کہ جب وہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا، آپ نے لوگوں کو اسے ابو الحکم کی کنیت سے پکارتے سنا۔ رسول اللہ صلی اللہ علیہ وسلم نے اسے بلایا اور فرمایا: ’’اصل حکم تو اللہ تعالیٰ ہے اور اسی کا فیصلہ چلتا ہے۔ پھر تجھے ابو الحکم کیوں کہا جاتا ہے۔؟ اس نے کہا: میری قوم میں جب کوئی اختلاف ہوتا ہے تو وہ میرے پاس آتے ہیں۔ میں ان میں فیصلہ کر دیتا ہوں جسے وہ دونوں فریق پسند کرتے ہیں۔ آپ نے فرمایا: ’’یہ تو بہت اچھی بات ہے۔ تیرے کتنے لڑکے ہیں‘‘ میں نے کہا: شریح، عبد اللہ اور مسلم۔ آپ نے فرمایا: ’’تیری کنیت آج سے ابو شریح ہے۔‘‘ پھر آپ نے اس کے لیے اور اس کی اولاد کے لیے دعا فرمائی۔","f2":"1۔ اس حدیث مبارکہ سے یہ اشارہ ملتا ہے کہ ثالث کا کیا ہوا صحیح اور درست فیصلہ نافذ ہونا چاہیے کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے سیدنا ہانی رضی اللہ عنہ کے فعل کی تحسین فرمائی ہے۔\n2۔ بڑے بیتے کے نام پر کنیت رکھنا مستحب ہے کیونکہ بڑا ہونے کی وجہ سے یہ اس کا حق بنتا ہے۔\n3۔ اس حدیث مبارکہ سے یہ مسئلہ بھی معلوم ہوتا ہے کہ قبیح اور برے نام کو بدل دینا مستحب اور پسندیدہ شرعی عمل ہے، نیز یہ حدیث مبارکہ اس مسئلے کی طرف راہ نمائی بھی کرتی ہے کہ ’’ابو الحکم‘‘ کنیت رکھنے احتراز کرنا چاہیے، اس لیے کہ عربی میں حکم فیصلہ کرنے والے کو کہتے ہیں۔ ابو الحکم سے مراد ہے سب سے بڑا فیصل ہ کرنے والا۔ ظاہر ہے اس میں فخر اور تعلی کا اظہار ہے جسے شریعت مناسب نہیں سمجھتی، اس لیے آپ نے اس کنیت کو حقیقی کنیت سے تبدیل فرمادیا۔\n4۔ یہ بہت اچھی بات ہے۔‘‘ عربی جملے کے لفظی معنی ہیں: ’’اس سے اچھی کوئی بات نہیں۔‘‘ مفہوم وہی ہے۔"}],[5388,"ابوبکرہ رضی اللہ عنہ کہتے ہیں کہ مجھے اللہ تعالی نے ایک چیز کی وجہ سے روکے رکھا ۱؎ جو میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنی، جب کسری ہلاک ہوا تو آپ نے فرمایا: \"انہوں نے کسے جانشین بنایا؟\" لوگوں نے کہا: اس کی بیٹی کو، آپ صلی اللہ علیہ وسلم نے فرمایا: \"وہ قوم کبھی کامیاب نہیں ہو سکتی جس نے کسی عورت کو حکومت کے اختیارات دے دیے\"۔\n§وضاحت\n۱؎: یعنی عائشہ رضی اللہ عنہا کی طرف سے علی رضی اللہ عنہ سے جب جنگ کا ارادہ کیا تو اللہ تعالی نے مجھے اس فرمان رسول صلی اللہ علیہ وسلم کے سبب محفوظ رکھا۔","الألباني: صحيح",{"u2":"سیدنا ابو بکر رضی اللہ عنہ سے روایت ہے، انہوں نے فرمایا: اللہ تعالیٰ نے مجھے ایک فرمان کی بدولت بچا لیا جو میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا تھا۔ جب (شاہ ایران) کسریٰ مر گیا تو آپ نے پوچھا: ’’ان لوگوں (ایرانیوں) نے کسے جانشین بنایا ہے۔‘‘ لوگوں نے کہا: اس کی بیٹی کو آپ نے فرمایا: ’’وہ قوم ہر گز کامیاب نہیں ہوگی جنہوں نے اپنی حکومت ایک عورت کے سپرد کردی۔‘‘","f2":"1۔ عورت کو قاضی اور جج بنانا اور اس سے فیصلے کرانا درست نہیں، شرعاً یہ ممنوع ہے۔\n2۔ عورت کا دائرہ کار مرد کے دائرہ کار سے مختلف ہے۔ عورت کے ذمے گھریلو امور کی نگرانی ہے جب کہ بیرونی امور، مثلاً: کاروبار، ملازمت، حکومت و قضاء وغیرہ مرد کی ذمہ داری ہے۔ پھر جن معاملات میں مرد و عورت کا اختلاط ہوتا ہے، ان میں عورت ذمہ داری نہیں سنبھال سکتی۔ اسی لیے عورت کا امام نہیں بنایا جا سکتا، خواہ وہ صاحب علم و فضل ہی ہو۔ قضاء اور امارت میں تو عموماً واسطہ ہی مردوں سے پڑتا ہے۔ ویسے بھی یہ گھریلو معاملہ نہیں، لہٰذا عورت کے لیے قضاء و امارت جائز نہیں۔ یہی وجہ ہے کہ خلفائے راشدین کے دور میں کسی عورت کو کسی ملکی منصب پر مقرر نہیں کیا گیا اگرچہ اس دور میں بلند مرتبہ خواتین کی کمی نہیں تھی کیونکہ وہ پردے میں رہنے کی پابند ہیں۔ بعد والے ادوار میں بھی اس بات پر ہی عمل جاری رہا۔ اور اہل علم کا بھی اس بات پر اجماع ہے۔\n3۔ ’’بچا لیا‘‘ سیدنا ابوبکرہ رضی اللہ عنہ کا اشارہ حضرت عائشہ﷞ کی طرف ہے۔ جب وہ قصاص عثمان رضی اللہ عنہ کے سلسلے میں مکہ سے بصرہ تشریف لائی تھیں۔ ان کے ساتھ بڑے بڑے صحابہ تھے۔ راستے میں لوگ ملتے گئے حتیٰ کہ لشکر عظیم بن گیا کیونکہ ان کا مطالبہ صحیح تھا، اس لیے سیدنا ابوبکرہ رضی اللہ عنہ نے بھی ان کا ساتھ دینے کا ارادہ فرمایا مگر جب دیکھا کہ لشکر کی قیادت عورت کے ہاتھ میں ہے تو مندرجہ بالا فرمان رسول کے پیش نظر وہ پیچھے ہٹ گئے۔\n4۔ اگرچہ حضرت عائشہ﷞ نہ تو حکومت کے خواہاں تھیں، نہ کوئی عہدہ طلب کر رہی تھیں صرف قصاص کا مطالبہ کر رہی تھیں اور یہ مطالبہ ہر مسلمان کر سکتا تھا مگر لشکر کی قیادت کی صورت میں یہ بات مناسب نہیں تھی۔ اس پر ہ خود بھی بعد میں اظہار تأسف کرتی رہیں کہ مجھے ایسا نہیں کرنا چاہیے تھا، لہٰذا کوئی اعتراض نہ رہا۔ رَضِيَ اللهُ عَنْهَا\n5۔ ’’اس کی بیٹی کو ‘‘ درمیان میں کسریٰ پرویز کا بیٹا بھی بادشاہ رہا مگر وہ صرف چھ مہینے کے لیے، اس لیے اس کا شمار نہیں کیا گیا۔\n6۔ ’’کامیاب نہیں ہوگی‘‘ آخرت میں یاد دنیا میں بھی کیونکہ حکومت عورت کا میدان نہیں۔ وہ اس میں مردوں سے مات کھا جاتی ہے۔ تاریخ ملاخطہ فرمائیں"}],[5389,"فضل بن عباس رضی اللہ عنہما سے روایت ہے کہ وہ قربانی کے دن (یعنی دسویں ذی الحجہ کو) رسول اللہ صلی اللہ علیہ وسلم کے پیچھے سوار تھے، آپ کے پاس قبیلہ خثعم کی ایک عورت آئی اور بولی: اللہ کے رسول! اللہ کا اپنے بندوں پر عائد کردہ فریضہ حج میرے والد پر کافی بڑھاپے میں واجب ہوا ہے، وہ سوار ہونے کی بھی استطاعت نہیں رکھتے سوائے اس کے کہ انہیں باندھ دیا جائے، تو کیا میں ان کی جانب سے حج کر لوں؟ آپ نے فرمایا: \"ہاں، ان کی طرف سے حج کر لو۔ اس لیے کہ اگر ان پر کوئی قرض ہوتا تو وہ بھی تم ہی ادا کرتیں\" ۱؎۔\n§وضاحت\n۱؎: گویا اس مثال کے ذریعہ آپ صلی اللہ علیہ وسلم نے اس عورت پر اس کے معذور باپ کے اوپر فرض حج کی ادائیگی کا فیصلہ دیا، اسی طرح دنیا کی ہر عدالت میں «اشباہ و نظائر» کے سہارے فیصلہ کیا جاتا ہے۔","الألباني: صحيح",{"u2":"سیدہ فضل بن عباس رضی اللہ عنہا سے روایت ہےکہ وہ نحر کے دن رسول اللہ صلی اللہ علیہ وسلم کے پیچھے سواری پر بیٹھے تھے کہ خثعم قبیلے کی ایک عورت آپ کے پاس حاضر ہوئی اور کہا: اے اللہ کے رسول! اللہ تعالیٰ کا اس کے بندوں پر فریضۂ حج، میرے والد پر اس وقت (فرض) ہوا جبکہ وہ بہت بوڑھے ہیں۔ (سواری پر) سوار نہیں ہوسکتے الا یہ کہ انہیں لٹا دیا جائے تو کیا میں ان کی طرف سے حج کرلوں؟ آپ نے فرمایا: ’’ہاں تو اس کی طرف سے حج کر، کیونکہ اگر اس کے ذمے قرض ہوتا تو تو اسے ادا کرتی۔‘‘","f2":"1۔ اس حدیث مبارکہ سے یہ اہم مسئلہ ثابت ہوتا ہے کہ کسی دوسرے شخص کی طرف سے حج کرنا شرعاً جائز ہے بشرطیکہ حج بدل کرنے والا شخص اس سے پہلے اپنا حج کر چکا ہو جیسا کہ شبرمہ والی حدیث میں ہے کہ رسو اللہ صلی اللہ علیہ وسلم نے اسے فرمایا تھا کہ پہلے اپنا حج کر،پھر شبرمہ کی طر سے حج کرنا۔\n2۔ یادرہے جس شخص پر حج فرض ہو چکا ہو اور اسے کوئی شرعذر آڑے آرہا ہو جس کی وجہ سے وہ خود حج نہ کرسکتا ہو، مثلاً: وہ دائمی مریض ہو یا انتہائی بوڑھا ہو یا سواری پر بیٹھنے کے قابل نہ ہو، وغیرہ تو ایسے زندہ شخص کی طرف سے حج کرنا درست ہے۔\n3۔ یہ اشارہ بھی ملتا ہے کہ اگر سواری کا جانور برداشت کر سکتا ہو تو اس پر بیک وقت ایک سے زیادہ آدمی سوار ہو سکتے ہیں، نیز یہ رسول اللہ صلی اللہ علیہ وسلم کی عظیم تواضع اور سیدنا فضل رضی اللہ عنہ کے عظیم المرتبت ہونے کی صریح دلیل بھی ہے کہ آپ نے اپنے سے کہیں کم مرتبہ شخص کو نہ صرف اپنے ساتھ بلکہ اپنے پیچے ایک ہی سواری پر سوارکر لیا۔\n4۔ اس حدیث مبارکہ سے یہ اہم مسئلہ بھی معلوم ہوا کہ غیر محرم شخص کے لیے عورت کی آواز سننا شرعاً جائز ہے۔ جو لوگ عورت کی آواز کو بھی عورت یعنی چھپانے کے قابل قراردیتے ہیں، اس حدیث مبارکہ سے ان کے مؤقف کا رد ہوتا ہے۔\n5۔ عالم اور استاد اگر مناسب سمجھے تو سائل اور شاگرد کو مثال بیان کرکے مسئلہ سمجھا سکتا ہے جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے کیا تھا۔\n6۔ یہ حدیث مبارکہ والدین کے ساتھ نیکی اور حسن سلوک کرنے پر دلالت کرتی ہے۔ ان کا خیال رکھنا، ان کے ذمے قرض ہو تو ادا کرنا، ان کے نان و نفقہ اور اخراجات وغیرہ کا دھیان کرنا، نیز ان کی دیگر دینی اور دنیاوی ضرورتیں پوری کرنا اولاد کی ذمہ داری ہے۔\n7۔ یہ حجۃ الوداع کی بات ہے۔ یوم نحر سے مراد 10 ذی الحجہ ہے جس دن حاجی منیٰ میں واپس آتے ہیں اور رمی کرتے ہیں۔\n8۔ ’’اگر اس کے ذمے قرض ہوتا‘‘ یہ ایک مثال ہے جو آپ صلی اللہ علیہ وسلم نے اس کو مسئلہ سمجھانے کے لیے بیان فرمائی ورنہ یہ ضروری نہیں کہ آپ نے حج کا سمئلہ قرض کے مسئلہ سے معلوم فرمایا ہو بلکہ یہ دونوں احکام شرع میں معلوم تھے۔ اسی لیے امام بخاری رحمہ اللہ نے اس حدیث کا عنوان یوں باندھا ہے: ’’جو شخص ایک معلوم حکم سمجھانے کے لیے ایک زیادہ واضح حکم بطور مثال بیان کرے۔۔۔۔الخ‘‘ ورنہ بہت سے مسئل میں یہ قیاس نہیں چلتا، مثلاً: کسی شخص کے ذمے نماز یا روزہ ہو اوروہ خد ادا کرنے کے قابل نہ ہو تو کوئی دوسرا شخص اس کی طرف سے ادا نہیں کر سکتا اور یہ اتفاقی مسئلہ ہے۔\n9۔ یاد رکھنا چاہیے کہ قیاس وہاں چلتا ہے جہاں شریعت کا صریح حکم موجود نہ ہو، اس لیے قرآن و حدیث کے حکم کے مقابلے میں قیاس جائز نہیں۔"}],[5390,"عبداللہ بن عباس رضی اللہ عنہما بیان کرتے ہیں کہ قبیلہ خثعم کی ایک عورت نے رسول اللہ صلی اللہ علیہ وسلم سے فتوی پوچھا (فضل اس وقت رسول اللہ صلی اللہ علیہ وسلم کے پیچھے سوار تھے۔) وہ بولی: اللہ کے رسول! اللہ کا اپنے بن دوں پر عائد کردہ فرض فریضۂ حج میرے والد پر اس وقت فرض ہوا ہے جب وہ کافی بوڑھے ہو چکے ہیں، وہ سواری پر بیٹھ بھی نہیں سکتے، تو ان کی طرف سے میرا حج کرنا کافی ہے؟ (محمود نے :(«فهل يجزي» یعنی کافی ہے؟ کے بجائے) «فهل يقضي» (یعنی کیا ادا ہو جائے گا) کہا۔) آپ صلی اللہ علیہ وسلم نے اس سے فرمایا: \"ہاں\"۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: اس حدیث کو زہری سے ایک سے زائد لوگوں نے روایت کیا ہے، لیکن ان لوگوں نے اس کا ذکر نہیں کیا جس کا ذکر ولید نے کیا ۱؎۔\n§وضاحت\n۱؎: یعنی ولید نے اس حدیث کو مسند فضل سے روایت کیا ہے جب کہ زہری سے روایت کرنے والے دوسرے شاگردوں نے اسے مسند ابن عباس رضی اللہ عنہما سے روایت کیا ہے۔","الألباني: صحيح",{"u2":"سیدہ ابن عباس رضی اللہ عنہا نے بیان فرمایا کہ خثعم قبیلے کی ایک عورت نے رسول اللہ صلی اللہ علیہ وسلم سے مسئلہ پوچھا جب کہ فضل رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ آپ کی سواری کے پیچھے بیٹھے تھے۔ اس نے کہا: اے اللہ کے رسول صلی اللہ علیہ وسلم! اللہ تعالیٰ کا اس بندوں پر فریضہ حج، میرے والد پر اس وقت (فرض) ہوا جبکہ وہ بہت بوڑھے ہیں۔ وہ سواری پر بیٹھ نہیں سکتے تو کیا یہ درست ہے کہ میں ان کی طرف سے حج ادا کروں؟ آپ نے فرمایا: ’’ہاں‘‘ اور (راویٔ حدیث استاد) محمود نے کہا: یقضی (جبکہ استاد عمرو بن عثمان کے لفظ تھے: یجزیءٌ)\nابو عبد الرحمان (امام نسائی رحمہ اللہ) نے کہا ہے کہ امام زہری سے کئی لوگوں نے یہ روایت بیان کی ہے مگر جوولید بن مسلم نے بیان کیا ہے، وہ کسی نے نے بیان نہیں کیا۔"}],[5391,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ فضل بن عباس رضی اللہ عنہما رسول اللہ صلی اللہ علیہ وسلم کے پیچھے سوار تھے، اتنے میں قبیلہ خثعم کی ایک عورت آپ سے مسئلہ پوچھنے آئی، فضل رضی اللہ عنہ اس کی طرف دیکھنے لگے وہ ان کی طرف دیکھنے لگی، رسول اللہ صلی اللہ علیہ وسلم فضل کا رخ دوسری طرف موڑ دیتے، وہ بولی: اللہ کے رسول! اپنے بندوں پر اللہ تعالی کا فرض کردہ فریضہ حج میرے والد پر اس وقت فرض ہوا جب وہ بہت بوڑھے ہو چکے ہیں، وہ سواری پر سیدھے بیٹھ بھی نہیں سکتے، کیا میں ان کی طرف سے حج کر لوں؟ آپ نے فرمایا: \"ہاں\"، اور یہ حجۃ الوداع کی بات ہے۔","الألباني: صحيح",{"u2":"سیدہ عبد اللہ بن عباس رضی اللہ عنہا نے فرمایا: کہ سیدہ فضل بن عباس رضی اللہ عنہا رسول اللہ صلی اللہ علیہ وسلم کے ساتھ پیچھے سواری پر بیٹھے تھے کہ خثعم قبیلے کی ایک عورت آپ کے پاس مسئلہ پوچھنے آئی۔ فضل اس کو دیکھنے لگے اور وہ فضل کو دیکھنے لگی۔ رسول اللہ صلی اللہ علیہ وسلم نے فضل کا چہرہ دوسری طرف پھیرنا شروع کر دیا وہ کہنے لگی: اے اللہ کے رسول! اللہ تعالیٰ کا اس کے بندوں پر فریضۂ حج، میرے والد پر س وقت فرض ہوا جبکہ میرا باپ بہت بوڑھا ہے۔ وہ سواری پر ٹھہر (بیٹھ) نہیں سکتا تو کیا میں اس کی طرف سے حج کر لوں؟ آپ نے فرمایا: ’’ہاں‘‘ اور یہ حجۃ الوداع کی بات ہے۔","f2":"’’ہاں‘‘ یعنی اگلے سال اس کی طرف سے حج کر لینا کیونکہ فی الوقت تو وہ اپنا حج کر رہی تھی۔"}],[5392,"عبداللہ بن عباس رضی اللہ عنہما بیان کرتے ہیں کہ قبیلہ خثعم کی ایک عورت نے کہا: اللہ کے رسول! اللہ کا اپنے بندوں پر عائد کردہ فریضہ حج میرے والد پر اس وقت فرض ہوا جبکہ وہ کافی بوڑھے ہو چکے ہیں، وہ سواری پر بیٹھ نہیں سکتے، اگر میں ان کی طرف سے حج کر لوں تو کیا وہ ان کی طرف سے ادا ہو جائے گا؟ رسول اللہ صلی اللہ علیہ وسلم نے اس سے فرمایا: \"ہاں\"، فضل اس کی طرف مڑ مڑ کر دیکھنے لگے، وہ ایک حسین و جمیل عورت تھی، رسول اللہ صلی اللہ علیہ وسلم نے فضل کو پکڑا اور ان کا رخ دوسری جانب گھما دیا۔","الألباني: صحيح",{"u2":"سیدہ ابن عباس رضی اللہ عنہا نے فرمایا کہ خثعم قبیلے کی ایک عورت نے کہا: اے اللہ کے رسول! اللہ تعالی کا اس کے بندوں پر فریضۂ حج میرے والد پر اس وقت فرض ہوا جبکہ وہ بہت بوڑھے ہیں۔ سواری پر نہیں بیٹھ سکتے۔ اگر میں ان کی طرف سے حج کروں تو کیا ان کی طرف سے ادائیگی ہو جائے گی؟ رسو اللہ صلی اللہ علیہ وسلم نے اسے فرمایا: ’’ہاں‘‘ فضل رضی اللہ عنہ اس کی طرف دیکھنے لگے کیونکہ وہ خوب صورت عورت تھی (اور فضل بھی ایسے ہی تھے) رسول اللہ صلی اللہ علیہ وسلم نے فضل کا چہرہ پکڑ کر دوسری طرف پھیر دیا۔","f2":"1۔ معلوم ہوا کہ بدنی استطاعت نہ ہو لیکن مالی لحاظ سے حج فرض ہوتا ہو تو اپنی جگہ کسی دوسرے کو حج کروئے جو اس کی طرف سے حج کرے۔\n2۔ اس حدیث مبارکہ سے یہ اہم مسئلہ بھی معلوم ہوتا ہے کہ عالم اور امام و حاکم کی شرعی ذمہ داری ہے کہ وہ منکر اور غیر شرعی کام کو روکے۔ ممکن ہو تو ہاتھ سے روکے جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے حضرت نے سیدنا فضل رضی اللہ عنہ کا چہرہ دوسری طرف پھیر دیا تھا۔"}],[5393,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ ایک شخص نے نبی اکرم صلی اللہ علیہ وسلم سے پوچھا: میرے والد پر حج فرض ہو گیا ہے، اور وہ اس قدر بوڑھے ہو گئے ہیں کہ سواری پر بیٹھ نہیں سکتے، اور اگر انہیں باندھ دوں تو خطرہ ہے کہ وہ اس سے مر نہ جائیں، کیا میں ان کی طرف سے حج ادا کر لوں؟ آپ نے فرمایا: اگر ان پر کچھ قرض ہوتا اور تم اسے ادا کرتے تو کیا وہ کافی ہوتا؟ اس نے کہا: ہاں، آپ نے فرمایا: \"تو تم اپنے باپ کی طرف سے حج کر لو\"۔","الألباني: شاذ مضطرب والمحفوظ أن السائل امرأة والمسؤول عنه أبوها",{"u2":"سیدہ عبد اللہ بن عباس رضی اللہ عنہا سے روایت ہے کہ ایک آدمی نے نبیٔ اکرم صلی اللہ علیہ وسلم سے سوال کیا کہ میرے باپ پر حج اس حال میں فرض ہوا ہے کہ وہ انتہائی بوڑھے ہیں۔ سواری پر نہیں بیٹھ سکتے۔ اگر میں انہیں پالان پر باندھ دوں تو مجھے خطرہ ہے، وہ مر جائیں گے تو کیا میں ان کی طرف سے حج کروں؟ آپ نے فرمایا: ’’تو بتا اگر اس کے ذمے قرض ہوتا اور تو ادا کر دیتا تو کیا اسے کفایت ہو جاتا؟‘‘ اس نے کہا: جی ہاں۔ آپ نے فرمایا: ’’تو اپنے باپ کی طرف سے حج کر۔‘‘"}],[5394,"فضل بن عباس رضی اللہ عنہما سے روایت ہے کہ وہ نبی اکرم صلی اللہ علیہ وسلم کے پیچھے سوار تھے، اتنے میں ایک شخص نے آ کر کہا: اللہ کے رسول! میری ماں بہت بڑی بوڑھی عورت ہیں، اگر میں انہیں سوار کر دوں تو وہ اسے پکڑ نہیں سکیں گی اور اگر انہیں باندھ دوں تو خطرہ ہے کہ وہ میرے اس عمل سے مر نہ جائیں، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اگر تمہاری ماں پر کچھ قرض ہوتا تو تم اسے ادا کرتے یا نہیں؟\" اس نے کہا: جی ہاں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تو تم اپنی ماں کی طرف سے حج کرو\"۔","الألباني: شاذ والمحفوظ خلافة كما ذكرت في الذي قبله",{"u2":"سیدہ فضل بن عباس رضی اللہ عنہا سے منقول ہے کہ وہ نبیٔ اکرم صلی اللہ علیہ وسلم کے پیچھے سواری پر سوار تھے کہ ایک آدمی نے آکر کہا: اے اللہ کے رسول! میری والدہ بہت بوڑھی ہیں۔ اگر میں انہیں سواری پر سوار کرتو بھی وہ نہیں بیٹھ سکیں گی اور اگر میں انہیں (پالان پر) باندھ دوں تو مجھے خطرہ ہے کہ وہ مرجائیں گی۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تو بتا اگر تیری والدہ کے ذمے قرض ہوتا تو کیا تو اسے ادا کرتا؟ اس نے کہا: جی ہاں۔ آپ نے فرمایا: ’’پھر اپنی ماں کی طرف سے حج بھی کر۔‘‘"}],[5395,"فضل بن عباس رضی اللہ عنہما کہتے ہیں کہ ایک شخص نے نبی اکرم صلی اللہ علیہ وسلم کے پاس آ کر کہا: اللہ کے نبی! میرے والد بہت بوڑھے ہیں، حج نہیں کر سکتے، اگر میں انہیں سوار کر دوں، تو اسے پکڑ کر بیٹھ نہیں سکیں گے، کیا میں ان کی طرف سے حج کر سکتا ہوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم اپنے باپ کی طرف سے حج کرو\"۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: سلیمان کا فضل بن عباس رضی اللہ عنہما سے سماع ثابت نہیں ہے۔","الألباني: شاذ",{"u2":"سیدہ فضل بن عباس رضی اللہ عنہا سے روایت ہے، انہوں نے فرمایا کہ ایک آدمی نے نبیٔ اکرم صلی اللہ علیہ وسلم کے پاس آکر کہا: اللہ کے نبی! میرے والد بہت بوڑھے ہیں۔ حج کی طاقت نہیں رکھتے اگر میں انہیں اٹھا کر سواری پر لاد بھی دوں، تب بھی وہ بیٹھ نہیں سکیں گے۔ کیا میں ان کی طرف سے حج ادا کرسکتا ہوں؟ آپ نے فرمایا: ’’تو اپنے والد کی طرف سے حج کر۔‘‘\nابو عبد الرحمٰن (امام نسائی رحمہ اللہ) نے کہا: سلیمان (ابن یسار) نے فضل بن عباس رضی اللہ عنہا سے نہیں سنا۔"}],[5396,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ ایک شخص نے نبی اکرم صلی اللہ علیہ وسلم کے پاس آ کر کہا: میرے والد کافی بوڑھے ہیں، کیا میں ان کی طرف سے حج کروں؟ آپ نے فرمایا: \"ہاں، تمہارا کیا خیال ہے اگر ان پر قرض ہوتا اور تم اسے ادا کرتے تو کافی ہوتا یا نہیں؟\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابن عباس سے روایت ہے کہ ایک آدمی نے نبیٔ اکرم صلی اللہ علیہ وسلم کے پاس آکر کہا: میرا باپ بہت بوڑھا ہے۔ کیا میں اس کی طرف سے ح ج کر سکتا ہوں؟ آپ نے فرمایا: ’’ہاں۔ تو بتا اگر اس کے ذمے قرض ہوتا اور تو ادا کر دیتا اسے کفایت نہ کرتا؟‘‘","f2":"اس باب کی پہلی چار روایت میں سائل عورت ہے اورآخری چار روایات میں سائل مرد ہے جہ کہ واقعہ ایک ہی ہے۔ اسی طرح عام روایات میں سوال والد کے بارے میں کیا گیا ہے جبکہ روایت 5396 میں سوال والدہ کے بارے میں کیا گیا ہے۔ تطبیق یوں ہے کہ کہ سائل آدمی تھا۔ اس کے ساتھ اس کی نوجوان بیٹی بھی تھی۔ پہلے بیٹی نے سوال کیا، پھراس شخص نے بھی کیا۔ سوال اس آدمی کے والد اور والدہ کے بارے میں تھا۔ لڑکی چونکہ انے باپ کی طرف سے سوال پوچھ رہی تھی، لہٰذا اس نے الفاظ اپنے والد والے ہی استعمال کیے۔ جبکہ جس شخص کے بارے میں سوال کیا گیا تھا، وہ اس لڑکی کا دادا۔ ویسے بھی دادا کو باپ بھی کہا جا سکتا ہے۔ اور یہ استعمال میں عام ہے۔ اس آدمی کے والدین دونوں بوڑھے تھے، لہٰذا سوال دونوں کے بارے میں کیا گیا۔ مسند ابو یعلی(حدیث:6731، بہ تحقیق حسین سلیم اسد) کی ایک روایت سے مذکورہ تطبیق کا اشارہ ملتا ہے کہ سائل مرد اور اس کی نوجوان بیٹی دونوں تھے۔ واللہ اعلم۔ بعض علماء محققین ترجیح کی طرف مائل ہیں، وہ کہتے ہیں کہ جو روایات امام زہری کے واسطے سے مروی ہیں ان سب میں عورت ہی کا ذکر ہے۔ اور یہ بخاری و مسلم کی روایات ہیں، اس لیے انہیں ترجیح حاصل ہے۔ مقصد یہ ہے کہ سائلہ عورت ہی تھی، مرد نہ تھا، مرد کے ذکر والی روایت مرجوح ہیں۔ مزید دیکھیے: (تعلیقات سلفیہ، طبع جدید: 5/458)"}],[5397,"عبدالرحمٰن بن یزید کہتے ہیں کہ لوگوں نے ایک دن عبداللہ بن مسعود رضی اللہ عنہ سے بہت سارے موضوعات پر بات چیت کی، عبداللہ بن مسعود رضی اللہ عنہ نے کہا: ہم پر ایک زمانہ ایسا بھی گزر چکا ہے کہ ہم نہ تو کوئی فیصلہ کرتے تھے اور نہ ہی فیصلہ کرنے کے قابل تھے، پھر اللہ تعالی نے ہمارے لیے مقدر کر رکھا تھا کہ ہم اس مقام کو پہنچے جو تم دیکھ رہے ہو، لہٰذا آج کے بعد سے جس کسی کو فیصلہ کرنے کی ضرورت آ پڑے تو چاہیئے کہ وہ اس کے مطابق فیصلہ کرے جو اللہ کی کتاب(قرآن) میں ہے، پھر اگر ایسا کوئی معاملہ اسے درپیش آئے جو کتاب اللہ (قرآن) میں نہ ہو تو اس کے مطابق فیصلہ کرے جو نبی اکرم صلی اللہ علیہ وسلم نے کیا تھا، اور اگر کوئی ایسا معاملہ ہو جو نہ کتاب اللہ (قرآن) میں ہو اور نہ اس سلسلے میں نبی اکرم صلی اللہ علیہ وسلم کا کوئی فیصلہ ہو تو اس کے مطابق فیصلہ کرے جو نیک لوگوں نے کیا ہو ۱؎، اور اگر کوئی ایسا معاملہ آئے جو نہ کتاب اللہ (قرآن) میں ہو، نہ نبی اکرم صلی اللہ علیہ وسلم کا اس سلسلے میں کوئی فیصلہ ہو اور نہ ہی نیک لوگوں کا) تو اسے چاہیئے کہ اپنی عقل سے اجتہاد کرے اور یہ نہ کہے کہ مجھے ڈر ہے، مجھے ڈر ہے، کیونکہ حلال واضح ہے اور حرام واضح ہے اور ان کے درمیان کچھ مشتبہ چیزیں ہیں تو تم ان باتوں کو چھوڑ دو جو تمہیں شک میں ڈالیں اور وہ کرو جو شک سے بالاتر ہوں۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: یہ حدیث بہت اچھی ہے۔\n§وضاحت\n۱؎: مراد \" نیک علماء \" ہیں، کیونکہ ابن مسعود رضی اللہ عنہ کے زمانہ میں \" صالحین \" صحابہ کرام ہی تھے، اور ان کی اکثریت عالم تھی، خلاصہ کلام یہ کہ صحابہ کرام کا اجماع مراد ہے، اسی طرح ہر زمانہ کے نیک علماء و ائمہ کرام کا اجماع بھی دلیل ہو گا، اور چونکہ مراد زمانہ کے علماء کا اجماع ہے اس لیے اس سے ایک عالم کی تقلید شخصی ہرگز مراد نہیں ہو سکتی، جیسا کہ بعض مقلدین نے اس سے تقلید شخصی ثابت کرنے کی کوشش کی ہے۔","الألباني: صحيح الإسناد موقوف",{"u2":"حضرت عبد الرحمٰن بن یزید نے فرمایا: ایک دن لوگوں نے حضرت عبد اللہ بن مسعود پر کسی مسئلے کے فیصلے کے بارے میں بہت زور دیا تو حضرت عبد اللہ بن مسعود نے فرمایا: ایک وقت تھا کہ ہم فیصلے نہیں کیا کرتے تھے اور نہ ہمارا یہ مقام تھا، پھر اللہ تعالیٰ نے ہمارے لیے مقدر فرمایا کہ ہم اس مرتبے کو پہنچ گئے ہیں جو تم دیکھ رہے ہو۔ آج کے بعد جس کے پاس کوئی فیصلہ آئے تو وہ اللہ تعالیٰ کی کتاب کے حکم کے مطابق فیصلہ کرے۔ اگر کوئی ایسا مسئلہ درپیش ہو جس کے بارے میں اللہ تعالیٰ کی کتاب میں کوئی حکم ذکر نہیں تو پھر وہ نبیٔ اکرم صلی اللہ علیہ وسلم کے فیصلے کے مطابق فیصلہ کرے۔ اور اگر کوئی ایسا مسئلہ سامنے آئے جس کے بارے میں نہ تو اللہ تعالیٰ کی کتاب میں کوئی حکم ہے اور نہ رسول اللہ صلی اللہ علیہ وسلم کو کائی فیصلہ ہے تو پھر وہ نیک لوگوں کے فیصلے مطابق فیصلہ کرے… اور اگر کوئی ایسا معاملہ سامنے آئے جس کے بارے میں نہ تو اللہ تعالیٰ کی کتاب میں کوئی حکم ہے اور نہ رسول اللہ صلی اللہ علیہ وسلم نے کوئی فیصلہ فرمایا ہو اور نہ سلف صالحین نے کوئی فیصلہ کیا ہو تو وہ اپنی رائے کے ساتھ حق بات تک پہنچنے کی کوشش کرے۔ یہ نہ کہے کہ (مجھے فتویٰ دیتے ہوئے) ڈر لگتا ہے۔ اور میں خطرہ محسوس کرتا ہوں، اس لیے کہ حلال کا حکم واضح ہے اور حرام کا بھی۔ درمیان میں کچھ چیزیں مشتبہ ہیں تو (ان کے بارے میں اصول یہ ہے کہ) شک و شبہ والی چیز کو چھوڑ دے اور غیر مشتبہ چیز کو اختیار کر۔\nابوعبد الرحمٰن (امام نسائی رحمہ اللہ) نے کہا: یہ حدیث جید (قابل حجت) ہے۔","f2":"1۔ اس باب سے امام صاحب رحمہ اللہ کا مقصود اجماع کی ح حجیت ثابت کرنا ہے کیونکہ قرآن مجید کی آیات اور دیگر احادیث سے اس کی حجیت ثابت ہوتی ہے، جیسے ﴿ وَ مَنْ یُّشَاقِقِ الرَّسُوْلَ مِنْۢ بَعْدِ مَا تَبَیَّنَ لَهُ الْهُدٰی وَ یَتَّبِعْ غَیْرَ سَبِیْلِ الْمُؤْمِنِیْنَ نُوَلِّهٖ مَا تَوَلّٰی وَ نُصْلِهٖ جَهَنَّمَ ؕ وَ سَآءَتْ مَصِیْرًا۠﴾(النساء، 115:4) اور ﴿ وَ كَذٰلِكَ جَعَلْنٰكُمْ اُمَّةً وَّسَطًا ﴾ (البقرۃ، 143:2) اسی طرح [إنَّ اللہ قدْ أَجَارَ أَمَّتِیْ مِنْ أَنْ تَجْتَمِعَ علیٰ ضَلالَۃٍ] (سلسلۃ الأحادیث الصحیحۃ، حیدث:1331) اس قسم کی آیات و احادیث سے ثابت ہوتا ہے کہ جب اہل علم ایک بات پر اتفاق کر لیں تو کسی شخص کو اس کی مخالفت نہیں کرنی چاہیے، خواہ اس بات پر قرآن و حدیث سے کوئی صریح دلیل نہ ملتی ہو۔ خلفائے راشدین کا طرز عمل یہی تھا کہ جب کسی مسئلے کی بابت صریح حکم نہ ہوتا تو اہل علم سے مشورہ فرماتے، پھر جس پر اتفاق ہو جاتا اسے اختیار کر لیتےلہٰذا اجماع کی مخالفت نہیں کرنی چاہیے کیونکہ جو اجتہاد شرعی تقاضوں کے عین مطابق ہو اس سے رو گردانی اور اعراض کرنا نہ صرف گمراہی و بے دینی بلکہ شیطان کا آلۂ کار بننا ہے۔ یہ ضرورہی ہے کہ اجتہاد، نصوص کتاب وسنت کے مطابق ہونا چاہیے مخالف نہیں۔\n2۔ ’’ایک وقت تھا‘‘ اس سے رسول اللہ صلی اللہ علیہ وسلم اور شیخین دور مراد ہے۔\n3۔ ’’نیک لوگوں‘‘ مراد اہل علم اور متقی حضرات ہیں۔"}],[5398,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ ہمارے اوپر ایک ایسا وقت آیا کہ اس وقت نہ ہم فیصلہ کرتے تھے اور نہ ہی فیصلہ کرنے کے اہل تھے، پھر اللہ تعالی نے ہمارے لیے وہ مقام مقدر کر دیا جہاں تم ہمیں دیکھ رہے ہو، لہٰذا جس کسی کو آج کے بعد کوئی معاملہ درپیش ہو تو وہ اس کا فیصلہ اس کے مطابق کرے جو اللہ کی کتاب(قرآن) میں ہے، اور اگر اس کے پاس کوئی ایسا معاملہ آئے جو اللہ کی کتاب (قرآن) میں نہیں ہے تو وہ اس کے مطابق فیصلہ کرے جو نبی اکرم صلی اللہ علیہ وسلم نے اس بارے میں کیا تھا، اور اگر کوئی ایسا معاملہ درپیش ہو جو نہ کتاب اللہ (قرآن) میں ہو اور نہ ہی نبی اکرم صلی اللہ علیہ وسلم نے اس بارے میں کوئی فیصلہ کیا ہو تو اس کے مطابق فیصلہ کرے جو نیک لوگوں نے کیا ہو، اور تم میں سے کوئی یہ نہ کہے کہ مجھے ڈر لگ رہا ہے، مجھے ڈر لگ رہا ہے، کیونکہ حلال واضح ہے اور حرام واضح ہے اور ان کے درمیان کچھ شبہ والی چیزیں ہیں، لہٰذا جو شک میں ڈالے اسے چھوڑ دو اور جو شک میں نہ ڈالے اسے لے لو۔","الألباني: صحيح لغيره",{"u2":"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ نے فرمایا: ہم پر ایک ایسا وقت گزرا کہ ہم فیصلے نہیں کیا کرتے تھے اور نہ ہمارا یہ مرتبہ تھا۔ پھر اللہ تعالیٰ کا کرنا ایسا ہوا کہ ہم اس درجے کو پہنچے جو تم دیکھ رہے ہو۔ اب جس شخص کے سامنے کوئی مسئلہ پیش ہو تو وہ اس کے بارے میں اللہ تعالیٰ کی کتاب کے ساتھ فیصلہ کرے۔ اگر کوئی ایسا مسئلہ درپیش ہو جو کتاب اللہ میں مذکور نہ ہو تو وہ نبیٔ اکرم صلی اللہ علیہ وسلم کے فیصلے کے مطابق فیصلہ کرے۔ اور اگر کوئی ایسا مسئلہ پیش آئے جو نہ کتاب اللہ میں مذکور ہو اور نہ نبیٔ اکرم صلی اللہ علیہ وسلم نے اس کی بابت فیصلہ فرمایا ہو تو وہ سلف صالحین کے فیصلے کے مطابق فیصل کرے۔ یہ نہ کہے کہ مجے ڈر لگتا ہے۔ اور میں خطرہ محسوس کرتا ہوں، اس لیے کہ حلال واضح ہے اور حرام بھی واضح ہے، البتہ ان کے درمیان کچھ مشتبہ چیزیں ہیں۔ تو شک و شبہ والی چز کو چھوڑ کر غیر مشتبہ چیز کو اختیار کر۔","f2":"’’حلال وضح ہے۔‘‘ یعنی بعض چیزوں کی حلت واضح اور غیر متنازعہ ہے۔ اور بعض چیزیں قطعاً حرام ہیں۔ ان کے بارے میں تو فیصلہ آسان ہے۔ البتہ کچھ معامالات مشتبہ ہوتے ہیں کیونکہ اس میں حلت کی وجہ بھی موجود ہوتی ہے اور حرمت کی بھی۔ یا دونوں قسم کی احادیث ہیں۔ یا اس میں سلف صالحین کا اختلاف ہے۔ ان میں احتیاط پر عمل کرنا چاہیے۔ واللہ اعلم"}],[5399,"شریح سے روایت ہے کہ انہوں نے عمر رضی اللہ عنہ سے ایک مسئلہ پوچھنے کے لیے انہیں ایک خط لکھا تو انہوں نے لکھا: فیصلہ کرو اس کے مطابق جو کتاب اللہ(قرآن) میں ہے، اور اگر وہ کتاب اللہ (قرآن) میں نہ ہو تو سنت رسول (حدیث) کے مطابق، اور اگر وہ نہ کتاب اللہ (قرآن) میں ہو اور نہ سنت رسول (حدیث)میں تو اس کے مطابق فیصلہ کرو جو نیک لوگوں نے کیا تھا، اور اگر وہ نہ کتاب اللہ (قرآن) میں ہو اور نہ سنت رسول صلی اللہ علیہ وسلم میں اور نہ ہی نیک لوگوں کا کوئی فیصلہ ہو تو اگر تم چاہو تو آگے بڑھو (اور اپنی عقل سے کام لے کر فیصلہ کرو) اور اگر چاہو تو پیچھے رہو (فیصلہ نہ کرو) اور میں پیچھے رہنے ہی کو تمہارے حق میں بہتر سمجھتا ہوں۔ والسلام علیکم۔","الألباني: صحيح الإسناد موقوف",{"u2":"حضرت شریح سے روایت ہے کہ انہوں نے ایک مسئلہ پوچھنے کے لیے سیدنا عمر رضی اللہ عنہ کو خط لکھا۔ انہوں نے جواب میں لکھا کہ اللہ تعالیٰ کی کتاب کے مطابق فیصل کرو۔ اگر وہ مسئلہ کتاب اللہ میں نہ ہو تو سنت رسول اللہ کے مطابق فیصلہ کرو اور اگر وہ مسئلہ کتاب اللہ اور رسول اللہ صلی اللہ علیہ وسلم کی سنت میں مذکور نہ ہو تو پھر سلف صالحین کے فیصلے کے مطابق فیصلہ کرو اور اگر وہ مسئلہ نہ کتاب اللہ میں ہو، نہ رسول اللہ صلی اللہ علیہ وسلم کی سنت میں ہو اور نہ اس کے بارے میں سلف صالحین سے کوئی فیصلہ منقول ہو تو پھر تیری مرضی ہے، چاہے تو آگے بڑھ (کر جواب دے) اور چاہے تو پیچھے ہٹ جا (خاموشی اختیار کر)۔ اور میرے خیال میں خاموشی ہی تیرے لیے بہتر ہے۔ والسلام علیکم","f2":"’’خاموشی بہتر ہے‘‘ کیونکہ اجتہاد میں غلطی کا امکان بہر صورت موجود رہتا ہے۔ ان روایات سے معلوم ہوا کہ قرآن و حدیث اور اجماع کے بعداجتہاد یا قیاس کا درجہ ہے، یعنی اگر کوئی مسئلہ قرآن حدیث میں مذکور نہ ہو اور اس بارے میں اجماع بھی موجود نہ ہو تو اسے اجتہاد و قیاس سے حل کیا جائے گا بشر طیکہ اجتہاد کرنے والا صاحب علم ہو، اجتہاد کے قابل ہولیکن اگر کوئی مسئلہ قرآن و حدیث میں موجود ہو یا اس کےبارے میں صحابہ یا تابعین کا اجماع پایا جاتا ہو تو اس کے بارے میں اجتہاد جائز نہیں کیونکہ اجتہاد سے مراد منصوص مسائل میں تبدیلی کرنا نہیں بلکہ غیر منصوص مسائل کا حل معلوم کرنا ہے۔ آج کل بعض علم سے بے بہرہ لوگ یہ سمجھتے ہیں کہ اجتہاد مطلب قرآن و سنت کے احکام معلوم کرنا ہے آج کل بعض علم سے بے بجہرہ لوگ یہ سمجھتے ہیں کہ اجتجہاد کا مطلب قرآن و سنت کے احکام میں تبدیلی کرنا ہے اور ان کے بقول قرآن و سنت کے مسائل کو موجودہ حالات کے مطابق کرنا ہے، حالانکہ حق یہ ہے حالات کو قرآن و سنت کے مطابق بدلنا چاہیے نہ کہ قرآن و سنت میں حالات کے مطابق تبدیلی کرنی چاہیے۔"}],[5400,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ عیسی بن مریم علیہ السلام کے بعد کئی بادشاہ ہوئے جن ہوں نے تورات اور انجیل کو بدل ڈالا، ان میں کچھ مومن تھے جو توراۃ پڑھتے تھے، ان کے بادشاہوں سے عرض کیا گیا: ہمیں اس سے زیادہ سخت گالی نہیں ملتی جو یہ ہمیں دیتے ہیں، یہ لوگ پڑھتے ہیں \"جس نے اللہ کے نازل کردہ حکم کے مطابق فیصلہ نہ کیا وہ کافر ہیں\" یہ لوگ اس قسم کی آیات پڑھتے ہیں ور ساتھ ہی وہ چیزیں پڑھتے ہیں جس میں ہمارا عیب نکلتا ہے تو انہیں بلا کر کہو کہ وہ بھی ویسے ہی پڑھیں جیسے ہم پڑھتے ہیں اور اسی طرح کا ایمان لائیں جیسا ہم لائے ہیں، چنانچہ اس (بادشاہ) نے انہیں بلایا اور اکٹھا کیا اور کہا: قتل منظور کرو یا پھر توراۃ اور انجیل کو پڑھنا چھوڑ دو، البتہ وہ پڑھو جو بدل دیا گیا ہے۔ وہ بولے: تمہارا اس سے کیا مقصد ہے؟ ہمیں چھوڑ دو۔ ان میں سے کچھ لوگوں نے کہا: ہمارے لیے ایک مینار بنا دو اور ہمیں اس پر چڑھا دو پھر ہمیں کھانے پینے کی کچھ چیزیں دے دو، تو ہم تمہارے پاس کبھی لوٹ کر نہ آئیں گے۔ ان میں سے کچھ لوگوں نے کہا: ہمیں چھوڑ دو، ہم زمین میں گھومیں ور بھٹکتے پھریں اور جنگلی جانوروں کی طرح پئیں، پھر اگر تم ہمیں اپنی زمین میں دیکھ لو تو مار ڈالنا، ان میں سے بعض لوگوں نے کہا: ہمارے لیے صحراء و بیابان میں گھر بنا دو، ہم خود کنویں کھود لیں گے اور سبزیاں بولیں گے، پھر پلٹ کر تمہارے پاس نہ آئیں گے اور نہ تمہارے پاس سے گزریں گے، اور کوئی قبیلہ ایسا نہ تھا جس کا دوست یا رشتہ دار اس میں نہ ہو۔ چنانچہ انہوں نے ایسا ہی کیا، تو اللہ تعالی نے آیت: «ورهبانية ابتدعوها ما كتبناها عليهم إلا ابتغاء رضوان اللہ فما رعوها حق رعايتها» \"اور جو درویشی انہوں نے خود نکالی تھی ہم نے انہیں اس کا حکم نہیں دیا تھا سوائے اللہ کی رضا جوئی کے، پھر انہوں نے اس کی بھی پوری رعایت نہیں کی\" (الحدید: ۲۷) نازل فرمائی، کچھ دوسرے لوگوں نے کہا: ہم بھی فلاں کی طرح عبادت کریں گے اور فلاں کی طرح گھومیں گے اور فلاں کی طرح گھر بنائیں گے حالانکہ وہ شرک میں مبتلا تھے، یہ ان لوگوں کے ایمان سے باخبر نہ تھے جن کی پیروی کا یہ دم بھر رہے تھے، پھر جب اللہ تعالی نے نبی اکرم صلی اللہ علیہ وسلم کو بھیجا تو ان میں سے بہت تھوڑے سے لوگ بچے تھے، ایک شخص اپنے عبادت خانے سے اترا اور جنگل میں گھومنے والا گھوم کر لوٹا اور گرجا گھر میں رہنے والا گرجا گھر سے لوٹا اور یہ سب کے سب آپ پر ایمان لائے اور آپ کی تصدیق کی، تو اللہ تبارک وتعالی نے فرمایا: «يا أيها الذين آمنوا اتقوا اللہ وآمنوا برسوله يؤتكم كفلين من رحمته» \"اے لوگو! جو ایمان رکھتے ہو، اللہ سے ڈرو اور اس کے رسول پر ایمان لاؤ وہ تمہیں اپنی رحمت کا دوگنا حصہ دے گا\" (الحدید: ۲۹) دوہرا اجر ان کے عیسی، تورات اور انجیل پر ایمان کے بدلے اور محمد صلی اللہ علیہ وسلم پر ایمان اور تصدیق کے بدلے، پھر فرمایا: \"وہ تمہارے چلنے کے لیے ایک روشنی دے گا\" یعنی قرآن اور نبی اکرم صلی اللہ علیہ وسلم کی پیروی \"تاکہ اہل کتاب\" یعنی وہ اہل کتاب جو تمہاری مشابہت کرتے ہیں \"جان لیں کہ وہ اللہ تعالی کے فضل کو حاصل کرنے کی قدرت نہیں رکھتے\"۔","الألباني: صحيح الإسناد موقوف",{"u2":"سیدہ ابن عباس رضی اللہ عنہا نے فرمایا: حضرت عیسیٰ ابن مریم علیہ السلام کے بعد کچھ ایسے بادشاہ ہوئے جنہوں نے تورات و انجیل کو بدل دیا اور ان میں کچھ ایمان پر قائم رہے۔ وہ (اصل) تورات پڑھتے تھے۔ ان بادشاہوں سے کہا گیا: ہم کوئی گالی اس گالی سے سخت نہیں پاتے جو یہ ہمیں دیتے ہیں کیونکہ یہ پڑھتے ہیں: ’’جو شخص اللہ تعالیٰ کے اتارے ہوئے احکام کے مطابق فیصلہ نہ کرے، وہ کافر ہے۔‘‘ اور اس قسم کی دوسری آیات، نیز وہ اپنی قرأت میں ہم پر عملی عیب بھی لگاتے ہیں۔ ان کو بلائیں اور انہیں کہیں کہ جس طرح ہم پڑھتے ہیں، وہ بھی اسی طرح پڑھیں اور وہ بھی اسی طرح ایمان لائیں جس طرح ہمارا ایمان ہے۔ بادشاہ نے ان کو بلایا اور ان کو قتل کی دھمکی دی الَّا یہ کہ وہ تورات و انجیل کی صحیح قرأت چھوڑ کر ان کی طرح تبدیل شدہ قرأت کریں۔ ان (مومن) لوگوں نے کہا: تمہیں اس سے کیا فائدہ ہوگا؟ تم ہمیں چھوڑ دو۔ ان میں سے ایک گروہ نے کہا: تم ہمارے لیے کوئی بلند عمارت بنا دو۔ پھر ہمیں اس پر چڑھا دو۔ہمیں کوئی یسی چیز دو کہ ہم اپنا کھانا پینا اوپر لے جا سکیں۔ ہم تمہارے پاس نہیں آئیں گے۔ ایک گروہ نے کہا: ہمیں چھوڑو۔ ہم زمین میں گھومتے پھریں گے اور بلا وجہ چکر لگاتے رہیں گے۔ اگر تم ہمیں اپنے علاقے میں پکڑ لو تو بے شک ہمیں قتل کر دینا۔ ایک اور گروہ نے کہا: ہمارے لیے صحراؤں رضی اللہ عنہ میں گھر بناد و۔ ہم کنویں کھود لیں گے۔ اور سبزیاں کاشت کریں گے۔ نہ ہم تمہارے پاس آئیں گے، نہ تمہارے قریب سے گزریں گے۔ ان قبائل میں سے کوئی قبیلہ بھی ایسا نہ تھا جس کا کوئی دوست اور رشتے دار ان(مومن) لوگوں میں نہ ہو اس لیے انہوں نے یہ باتیں مان لیں پھر اللہ تعالیٰ نے یہ آیت اتاری: ’’اور رہبانیت انہوں نے خود ایجاد کرلی، ہم نے اسے ان پر فرض نہیں کیا تھا، مگر اللہ کی خوشنودی کی طلب میں انہوں نے آپ ہی یہ بد عت نکالی اور پھر اس کی پابندی کرنے کا جو حق تھا اسے ادا نہ کیا۔‘‘ اور کچھ دوسرے لوگ بھی کہنے لگے کہ ہم تو اس طرح عبادت کریں گے جیسے کہ فلاں (اونچی عمارتوں والے) کرتے ہیں اور ہم بھی اسی طرح گھومتے پھریں گے جیسے یہ گھومتے پھرتے ہیں۔ اور ہم بھی آبادیوں سے دور جھونپڑیاں بنالیں گے جس طرح انہوں نےبنائی ہیں، حالانکہ یہ لوگ مشرک تھے اور ان کو ان لوگوں کے ایمان کا کوئی علم نہ تھا جن کی قتدا کا وہ دم بھرتے تھے۔ جب اللہ تعالیٰ نے بنیٔ اکرم صلی اللہ علیہ وسلم کو مبعوث فرمایا اور ان میں سے بھی چند لوگ ہی رہ گئے تو مناروں والے (راہب لوگ) اپنے مناروں سے اتر آئے اور گھومنے پھرنے والے بھی واپس آگئے اور جھونپڑیوں والے اپنی جھونپڑیوں سے لوٹ آئے۔ اور یہ سب لوگ آپ پر ایمان لے آئے اور آپ کی تصدیق کی۔ اللہ تبارک وتعالیٰ نے فرمایا: ’’اے ایمان والو! اللہ سے ڈرو اورا س کے رسول پر ایمان لاؤ۔ اللہ تعالیٰ تمہیں اپنی رحمت سے دوہر اجر عطا فرمائے گا۔‘‘ ایک اجر حضرت عیسیٰ علیہ السلام اور تورات و انجیل پر ایمان لانے کا اور دوسرا اجر حضرت محمد صلی اللہ علیہ وسلم پر ایمان و تصدیق کا۔ اللہ تعالیٰ نے فرمایا: ’’ اور اللہ تعالیٰ تمہیں نور عطا فرمائے گا جس کی روشنی میں تم (راہ حق پر چلو گے۔‘‘ اس نور سے مراد قرآن مجید اور نبیٔ اکرم صلی اللہ علیہ وسلم کی پیروی ہے۔ اللہ تعالیٰ نے مزید فرمایا: ’’تاکہ اہل کتاب (یہود و نصاریٰ) جان لیں، یعنی تمہاری مشابہت اختیار کریں (تمہاری طرح ایمان لے آئیں) کہ وہ بذات خود اللہ تعالیٰ کا کچھ بھی فضل حاصل نہیں کر سکتے۔۔۔ الخ‘‘","f2":"1۔ محقق کتاب کے علاوہ دیگر محققین نے اس روایت کو موقوفاً صحیح کہا ہےاور یہی بات درست ہے۔\n2۔ اس حدیث میں مذکورہ آیت کی تشریح تو نہیں البتہ اس کی مثال ضرور ہے کہ اللہ تعالیٰ کی کتاب کو بدلنا کفر ہے۔ ظاہر ہے کہ کتاب اللہ کے مطابق فیصلہ نہ کیا جائے تو وہ حکم بد ل جاتا ہے۔ یہ بھی کفر ہے۔ باقی حدیث کا اس آیت سے کوئی تعلق نہیں۔\n3۔ ’’سخت نہیں پاتے‘‘ کیونکہ وہ ہمیں کافر کہتے ہیں۔\n4۔ ’’عملی عیب‘‘ یعنی ہماری عملی خرابیاں بیان کرتے ہیں۔\n5۔ ’’ہمیں چھوڑ دو‘‘ گویا کچھ لوگ مناروں پر چڑھ گئے اور وہاں رہ کر عبادت کرن لگ گئے۔ کچھ ملنگ بن گئے جو بے مقصد ادھر ادھر آبادیوں سے دور تعلق نہ رہا اور بد عمل لوگ یہی چاہتے تھے کہ کوئی روک ٹوک کرنے والا نہ رہے۔\n6۔ ’’رہبانیت‘‘ ترک کر دینا، یعنی لوگوں سے الگ تھلگ رہنا حتیٰ کہ معاشرتی معاملات، مثلاً: نکاح، کاروبار، لین دین اور تعلقات سے بھی منہ موڑ لینا۔ ظاہر ہے شریعت میں اس کے خلاف فطرت طریقے کی اجازت کیسے ہو سکتی ہے؟ شریعت کا مقصود تو لوگوں میں رہ کر اللہ تعالیٰ سے تعلق قائم رکھنا ہے۔\n7۔ ’’کچھ دوسرے لوگ‘‘ یعنی پہلے لوگ تو واقعتاً دین حق پر تھے اور اپنے دین کو بچانے کے لیے مذکورہ طریقے اختیار کر بیٹھےتھے۔ بع میں کچھ بے دین لوگوں نے بھی ان کی نقالی شروع کردی جو راہب ہونے کے ساتھ ساتھ مشرک اور بے دین بھی تھے۔"}],[5401,"ام المؤمنین ام سلمہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم لوگ میرے سامنے مقدمات لاتے ہو، میں تو بس تمہاری طرح ایک انسان ہوں ۱؎، ممکن ہے تم میں سے کوئی اپنی دلیل میں دوسرے سے زیادہ چرب زبان ہو، لہٰذا اگر میں کسی کو اس کے بھائی کا حق دلا دوں (اور وہ حقیقت میں اس کا نہ ہو) تو اسے وہ نہ لے کیونکہ میں تو اسے جہنم کا ایک ٹکڑا کاٹ کر دے رہا ہوں\"۔\n§وضاحت\n۱؎: یعنی غیب کا علم صرف اللہ کو ہے، میں تو صرف ظاہر کو دیکھ کر فیصلہ کرتا ہوں۔","الألباني: صحيح",{"u2":"سیدہ ام سلمہ رضی اللہ عنہا سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تم میرے پاس مقدمات لاتے ہو۔ میں بھی ایک انسان ہوں۔ ہو سکتا ہے تم میں سے کوئی شخص اپنی دلیل کو فریق ثانی سے زیادہ وضاحت کے ساتھ بیان کر سکتا ہو، لہٰذا اگر میں (ظاہر دلائل کی بنا پر) کسی شخص کے لے اس کے بھائی کے حق کا فیصل کر دوں تو وہ اسے نہ لے۔ یوں سمجھے امیں اسے آگ کا ٹکڑا دے رہا ہوں۔‘‘","f2":"1۔ امام نسائی رحمہ اللہ نے جو عنوان قائم کیا ہے اس کا مقصد یہ اہم مسئلہ بیان کرنا ہے کہ قاضی اور جج ظاہری دلائل کے مطابق فیصلہ کرے گا، اس لیے اگر کسی قاضی یا حاکم وغیرہ نے غلط فیصلہ کر دیا تو غلط ہی ہوگا اور ناجائز بھی۔ کسی بھی شخص کے ناجائز فیصلہ کرنے سے وہ فیصلہ شرعی طور پر جائز قرار نہیں پاتا۔ قاضی، ثالث یا حاکم اور جج وغیرہ کے سامنے جس قسم کے دلائل ہوں گے، وہ انہیں کے مطابق فیصلہ صادر کریں گے، اس لیے ان کے فیصلہ کرنے سے نہ کوئی حرام کام حلال قرار پائے گا اور نہ حلال کام حرام ہی ہوگابلکہ اس کا وبال غلط دلائل مہیا کرنے والے کے سر ہوگا۔\n2۔ باطل پ ڈٹ جان، نیز باطل کی حمایت اور وکالت کرنا شرعاً حرام اور ناجائزہے۔ جو وکیل ناجائز اور باطل کیس لڑتا ہے اور ان کا معاوضہ لیتا ہے، وہ خود بھی حرام کھاتا اور اپنے اہل عیال کو بھی حرام ہی کھلاتا ہے۔ أعاذنا اللہ منہ\n3۔ اس حدیث مبارکہ سے بی بھی معلوم ہوتا ہے کہ بڑے سے بڑا مجتہد بھی غلطی کر سکتا ہے اور اس کی غلطی شرعاً غلطی ہی ہوگی، ظاہر دلائل کی وجہ سے وہ چیز حقیقت میں حلال یا حرام نہیں ہوگی، تاہم مجتہد کو اپنے اجتہاد اور کوشش کرنے کا اجر و ثواب ضرور ملے گا بشرطیکہ اس نے جان بوجھ کر غلطی نہ کی ہو۔ جانتے بوجھتے غلطی کرنے والا تو گناہ گار ہوگا۔\n4۔ اس حدیث مبارکہ سے یہ بھی ثابت ہوتا ہے کہ جس مسئلی کی بابت وحی نازل نہ ہوئی ہوتی رسول اللہ صلی اللہ علیہ وسلم اس کی بابت اپنے اجتہاد سے فیصلہ فرماتے۔ واللہ أعلم\n5۔ ’’انسان ہوں‘‘ دلائل سمجھنے میں غلطی لگ سکتی ہے۔ غیب دان نہیں کہ عین حقیقت پر پہنچ جاؤں۔ میں ظاہری دلائل کی بنا پر فیصل کر سکتا ہوں۔"}],[5402,"ابوہریرہ رضی اللہ عنہ روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"دو عورتیں تھیں ان دونوں کے ساتھ ان کا ایک ایک بچہ تھا، اتنے میں بھیڑیا آیا اور ایک کا بچہ اٹھا لے گیا، تو اس نے دوسری سے کہا: وہ تمہارا بچہ لے گیا، دوسری بولی: تمہارا بچہ لے گیا، پھر وہ دونوں مقدمہ لے کر داود علیہ السلام کے پاس گئیں تو آپ نے بڑی کے حق میں فیصلہ کیا۔ پھر وہ دونوں سلیمان علیہ السلام کے پاس گئیں اور ان سے بیان کیا تو انہوں نے کہا: ایک چھری لاؤ، میں اسے دونوں کے درمیان تقسیم کر دیتا ہوں، چھوٹی بولی: ایسا نہ کیجئیے، اللہ تعالی آپ پر رحم کرے، وہ اسی کا بیٹا ہے، تو انہوں نے چھوٹی کے حق میں فیصلہ دے دیا۔ ابوہریرہ رضی اللہ عنہ کہتے ہیں: اللہ کی قسم! سوائے اس دن کے ہم نے کبھی چھری کا نام «سکین» نہیں سنا، ہم) تو اسے «مدیہ» کہا کرتے تھے۔","الألباني: صحيح",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ وسلم نے فرمایا: ’’دو عورتیں تھیں۔ ان کے ساتھ ان کے دو بیٹے بھی تھے۔ بھیڑیا آیا اور ایک کے بیٹے کو اٹھا کر لے گیا۔ یہ (جس کا بچہ بھیڑیا اٹھا کر لےگیا) دوسری کو کہنے لگی: وہ تیرے بیٹے کو لے گیا ہے۔ دونوں حضرت داود علیہ السلام کے پاس فیصل لے گئیں۔ آپ نے بڑی کے حق میں فیصل کر دیا۔ وہ باہر نکلیں تو حضرت سلیمان بن داؤد علیہ السلام ملے۔ انہوں نے ان سے پورا واقعہ بیان کیا۔ آپ نے فرمایا: میرے پاس چھری لاؤ۔ میں اسے کاٹ کر دونوں میں تقسیم کردوں۔ چھوٹی بولی: اللہ تعالیٰ آپ رحم کرے! ایسے نہ کریں۔ یہ اسی کا بیٹا ہے آپ نے وہ چھوٹی کو دے دیا۔‘‘\nحضرت ابو ہریرہ رضی اللہ نے فرمایا: میں نے سِکِّیْن کا لفظ اسی دن سنا ورنہ ہم چھری کو مُدْیَہُ کہتے تھے۔","f2":"1۔ ’’بڑی کے حق یں‘‘ کیونکہ بچہ اس کے ہاتھ میں تھا۔ دلیل کسی کے پاس نہیں تھی۔ انہوں نے ظاہری قبضے کی رعایت سے فیصلہ کر دیا۔ حضرت سلیمان علیہ السلام نے حکمت سے کام لیا اور حقیقت تک پہنچ گئے۔ باب کا مقصد بھی یہی ہے کہ قاضی اپنی ذہانت سے بھی معاملے کیہ تہہ تک پہنچ کر حقیقت کے مطابق فیصلہ کر سکتا ہے، خواہ گوہ اور دلائل ن ہ ہوں مگر یہ تب ہے جب حاکم یا قاضی کے خلاف بدگمانی پیدا نہ ہوتی ہو، نیز فریق ثانی بھی چپ ہو جائے اور مان لے۔\n2۔ ’’یہ اسی کا ہے‘‘ کیونکہ کاٹ دینے اور ٹکڑے کرنے سے کسی کا بھی نہیں رہے گا۔ اس کو دینے کی صورت میں بچہ نظر توآئے گا اور ممتا کو کچھ نہ کچھ سکون تو ملتا رہے گا۔ اسی سے معلوم ہوا کہ بیٹا اس کا ہے تبھی تو اسے زیادہ تکلیف ہوئی۔\n3۔ ’’سکین‘‘ عربی میں چھری کو سکین کہتے ہیں اور مدیہ بھی۔\nسیدنا ابو ہریرہ رضی اللہ عنہ کے علاقے میں صرف مدیہ کہتے ہوں گے۔"}],[5403,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"دو عورتیں نکلیں، ان کے ساتھ ان کے دو بچے بھی تھے، ان میں سے ایک پر بھیڑیئے نے حملہ کر دیا اور اس کے بچے کو اٹھا لے گیا، وہ دونوں اس بچے کے سلسلے میں جو باقی تھا جھگڑتی ہوئی داود علیہ السلام کے پاس آئیں، تو انہوں نے ان میں سے بڑی کے حق میں فیصلہ دیا، پھر وہ سلیمان علیہ السلام کے پاس گئیں، وہ بولے: تم دونوں کا کیا قضیہ ہے؟ چنانچہ انہوں نے پورا واقعہ بیان کیا، تو انہوں نے کہا: چھری لاؤ، بچے کے دو حصے کر کے ان دونوں کے درمیان تقسیم کروں گا ۱؎، چھوٹی عورت بولی: کیا آپ اسے کاٹیں گے؟ کہا: ہاں، وہ بولی: ایسا نہ کیجئیے، اس میں جو میرا حصہ ہے وہ بھی اسی کو دے دیجئیے، سلیمان علیہ السلام نے کہا: یہ تمہارا بیٹا ہے، چنانچہ آپ نے اس کے حق میں فیصلہ کر دیا۔\n§وضاحت\n۱؎: اسی جملے میں باب سے مطابقت ہے، سلیمان علیہ السلام کا مقصد بچے کو حقیقت میں ٹکڑے کر کے تقسیم کرنا نہیں تھا، بس اس طریقے سے وہ بچے کی حقیقی ماں کو پہچاننا چاہتے تھے، واقعی میں جس کا بچہ تھا وہ :(چھوٹی عورت ) بچے کے ٹکڑے کرنے پر راضی نہیں ہوئی، جب کہ جس کا بچہ نہیں تھا وہ خاموش رہی، اسے دوسری کے بچے سے کیا محبت ہو سکتی تھی ؟ اس لیے ٹکڑے کرنے پر خاموش رہی، اس طرح آپ نے حقیقت کا پتہ چلا لیا۔","الألباني: صحيح",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’دو عورتیں (کسی کام سے) نکلیں۔ ان کے ساتھ ان کے دو بچے بھی تھے۔ بھیڑیےنے ان میں سے ایک پر حملہ کیا اور اس کے بچے کو چھین کر لے گیا۔ وہ دونوں بچ رہنے والے بچے کے بارے میں باہم جھگڑنے لگیں اور مقدمہ حضرت داؤد علیہ السلام کے پاس لے گئیں۔ انہوں نے فیصلہ بڑی کے حق میں دے دیا، پھر وہ دونوں حضرت سلیمان علیہ السلام کے پاس لے گئیں۔ انہوں نے فیصلہ بڑی کے حق میں دے دیا، پھر وہ دونوں حضرت سلیمان علیہ السلام کے پاس سے گزریں تو انہوں نے فرمایا: تمہارا کیا معاملہ ہے؟ ان عورتوں نے پوری بات بیان کر دی۔ آپ نے فرمایا: میرے پاس چھر لاؤ میں بچہ دو ٹکڑے کرکے ان میں تقسیم کر دیتا ہوں چھوٹی کہنے لگی: کیا آپ بچہ چیر دیں گے؟ فرمایا: ہاں۔ اس نے کہا: ایسا نہ کریں۔ میں اپنا حق اس کو دیتی ہوں۔ آپ نے فرمایا: یہ تیر بیٹا ہے، پھر اس کے حق میں فیصلہ فر مادیا۔‘‘","f2":"معلوم ہوا حق کو ثابت کرنے یا حق کو جاننے کے لیے حیلہ جائز ہے۔ حیلہ وہ ناجائز، مثلاً: بعض صاحبان جبہ و دستار نے زکاۃ سے بچنے یا شفعہ ساقط کرنے کے جو حیلے بتائے ہیں وہ نہ صرف شرعاً حرام و ناجائز ہیں بلکہ اخلاق و شرافت کے ادنیٰ درجے سے بھی گرے ہوئے ہیں۔"}],[5404,"ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"دو عورتیں نکلیں، ان کے ساتھ ان کے دو بچے بھی تھے، ان میں سے ایک پر بھیڑیئے نے حملہ کر دیا اور اس کے بچے کو اٹھا لے گیا، وہ اس بچے کے سلسلے میں جو باقی رہ گیا تھا جھگڑتی ہوئی داود علیہ السلام کے پاس آئیں، انہوں نے ان میں سے بڑی کے حق میں فیصلہ دیا، وہ سلیمان علیہ السلام کے پاس گئیں تو انہوں نے کہا: تم دونوں کے درمیان کیا فیصلہ کیا؟ (چھوٹی) بولی بڑی کے حق میں فیصلہ کیا، سلیمان علیہ السلام نے کہا: میں اس بچے کو دو حصوں میں تقسیم کروں گا، ایک حصہ اس کے لیے اور دوسرا حصہ اس کے لیے ہو گا، بڑی عورت بولی: ہاں! آپ اسے کاٹ دیں، جب کہ چھوٹی عورت نے کہا: ایسا نہ کیجئیے، یہ بچہ اسی کا ہے، چنانچہ انہوں نے اس کے حق میں فیصلہ کیا جس نے بچہ کو کاٹنے سے روکا تھا\" ۱؎۔\n§وضاحت\n۱؎: سلیمان علیہ السلام نے اپنے باپ داود علیہ السلام کے فیصلے کو کالعدم قرار دے دیا، یہی باب سے مطابقت ہے۔","الألباني: صحيح",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ سے منقول ہے ہ نبیٔ اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’ دو عورتیں (گھر سے) نکلیں۔ ان کے ساتھ ان کے دو نچے (بیٹے) بھی تھے۔ بھیڑیا ان میں سے ایک بچے کو پکڑ کر لے گیا۔ وہ دوسرے بچے کے بارے میں جھگڑا کرتی ہوئی حضرت داؤد علیہ السلام کے پاس پہنچ گئیں۔ انہوں نے بچے کا فیصلہ ان میں میں سے بڑی کے حق میں دے دیا، پھر وہ حضرت سلیمان علیہ السلام کےپاس سے گزریں تو انہوں نے پوچھا تمہارے درمیان کیا فیصلہ ہوا؟ چھوٹی نے کہا: بڑی کے حق میں فیصلہ ہوا ہے۔ حضرت سلیمان علیہ السلام فرمانے لگے: میں اس کو دو ٹکڑے کر دیتا ہوں۔ نصف اس کا نصف اس کا۔ بڑی کہنے لگی: ہاں ہاں، دو ٹکڑے کر دو۔ چھوٹی نے کہاں نہ نہ اسے دو ٹکڑے نہ کریں۔ یہ بچہ اسی کا ہے۔ پھر انہوں نے بچے کا فیصلہ اس کے حق میں کیا جس نے اس کو کاٹنے کی تجویز نہیں مانی تھی۔‘‘","f2":"1۔ مذکورہ مفہوم کی ان احادیث اور ان میں بیان کردہ واقع سے معلوم ہوتا ہے کہ عقل و دانش اور فہم و فراست قطعی طور پر وہبی چیز ہے، اللہ تعالیٰ جسے چاہے عطا فرمادے۔ چھوٹی اور بڑی عمر یا امیری و فقیری اور اقتدار اختیار وغیرہ کااس سے قطعاً کوئی تعلق نہیں۔\n2۔ یہ مسئلہ بھی معلوم ہوتا ہے کہ صحیح اور درست بات معلوم کرنے اور معاملے کی تہہ تک پہنچنے کے لیے حیلہ کیا جاسکتا ہے بشرطیکہ اس حیلے کا مقصد احقاق حق یا ابطال باطل ہی ہو۔ باطل اور ناجائز کو درست اور جائز قرار دینے کے لیے حیلہ کرنا شرعاً مذموم اور حرام ہے۔\n3۔ اگر فریقین اپنے حق کے بارے میں دوبارہ کسی اور سے فیصلہ کرانے کے حق میں ہوں تو بڑی خوشی سے کرواسکتے ہیں، خواہ دوسرا قاضی پہلے کے برابر ہو یا اس سے کم مرتبہ ہو جیسا کہ مندرجہ بالا حدیث سے واضح ہے، خصوصاً جب کہ دوسرے کے فیصلے کے بعد کسی اور کی طرف رجوع کرنا بے ایمانی کی دلیل ہے۔\n4۔ ’’بچہ اسی کا ہے‘‘ چونکہ اس قول کا مقصد صرف بچے کی جان بچانا تھا نہ کہ اقرار، اسی لیے حضرت سلیمان علیہ السلام نے اس کے اقراری کلام پر عمل نہیں فرمایا بلکہ بچہ اسی کو دے دیا کیونکہ ان کو حق معلوم ہو چکا تھا بلکہ ہر ایک کے لیے واضح ہو چکا تھا۔"}],[5405,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے خالد بن ولید رضی اللہ عنہ کو بنی جذیمہ کی طرف روانہ کیا، خالد رضی اللہ عنہ نے انہیں اسلام کی دعوت دی، مگر وہ اچھی طرح «اسلمنا» \"ہم اسلام لائے\" نہ کہہ سکے بلکہ کہنے لگی: ہم نے اپنا دین چھوڑا، چنانچہ خالد رضی اللہ عنہ نے بعض کو قتل کر دیا اور بعض کو قیدی بنا لیا اور ہر شخص کو اس کا قیدی حوالے کر دیا، جب صبح ہوئی تو خالد رضی اللہ عنہ نے ہم میں سے ہر شخص کو اپنا قیدی قتل کرنے کا حکم دیا، ابن عمر رضی اللہ عنہما نے کہا: اللہ کی قسم! میں اپنا قیدی قتل نہیں کروں گا اور نہ ہی (میرے ساتھیوں میں سے) کوئی دوسرا، پھر ہم نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے اور خالد رضی اللہ عنہ کی اس کارروائی کا آپ سے ذکر کیا تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا (اور آپ دونوں ہاتھ اٹھائے ہوئے تھی): \"اے اللہ میں اس سے برأت کا اعلان کرتا ہوں جو خالد نے کیا\" ۱؎۔ بشر کی روایت میں ہے کہ آپ نے یوں فرمایا: \"اے اللہ! میں اس سے بَری ہوں جو خالد نے کیا ہے\"، ایسا آپ نے دو مرتبہ کہا۔\n§وضاحت\n۱؎: یہی باب سے مناسبت ہے، آپ صلی اللہ علیہ وسلم نے خالد بن ولید کے فیصلہ کو رد کر دیا۔","الألباني: صحيح",{"u2":"حضرت سالم کے والد محترم (سیدنا عبد اللہ بن عمر رضی اللہ عنہ) بیان کرتے ہیں کہ نبیٔ اکرم صلی اللہ علیہ وسلم نے حضرت خالد بن ولیدکو بنو جذیمہ کی طرف بھیجا۔ حضرت خالد نے ان کو اسلام کی دعوت دی۔ وہ (مسلمان ہو گئے لیکن) اچھی طرح یہ نہ کہہ سکے کہ ہم مسلمان ہوگئے اور کہنے لگے: ہم نے اپنا دین چھوڑا (أسلمنا کہنے کی بجائے صبأنا، صبأنا کہنے لگے) حضرت خالد ان کو قتل اور قید کرنے لگ گئے۔ انہوں نے (ہم میں سے) ہر شخص کو اس کا قیدی سپرد کر دیا۔ اگلے دن صبح کے وقت حضرت خالد بن ولید نے حکم دیا کہ ہر شخص اپنا قیدی قتل کر دے۔ عبد اللہ بن عمر نے کہا: اللہ کی قسم! میں اپنا قیدی قتل نہیں کروں گا اور میرے ساتھیوں میں سے کوئی دوسرابھی اپنا قیدی قتل نہیں کرے گا۔ پھر ہم نے نبیٔ اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے تو آپ سے حضرت خالد کی یہ کار گزاری ذکر کی گئی۔ نبیٔ اکرم صلی اللہ علیہ وسلم نے اپنے دونوں ہاتھ اٹھائے اور فرمایا: ’’اے اللہ! میں اس کام سے بری ہوں جو خالد نے کیا۔‘‘ آپ نے یہ دو مرتبہ فرمایا۔","f2":"1۔ امام نسائی رحمہ اللہ نے جو عنوان قائم کیا ہے اس کا مقصد یہ ہے کہ اگر کوئی حاکم و امیر وغیرہ غلط فیصلہ کرے تو وہ فیصلہ مردود قرار پائے گا، اس لیے اس پر عمل نہیں کیا جائے گا جیسا کہ سیدنا عبد اللہ بن عمر رضی اللہ عنہ نے شرعی امیر سیدنا خالد بن ولید رضی اللہ عنہ کا فیصلہ اور حکم ماننے سے انکار کر دیا۔ بعد ازاں رسول اللہ صلی اللہ علیہ وسلم نے بھی اس کی تائید فرمائی۔\n2۔ اس حدیث مبارکہ سے حضرت عبد اللہ بن عمر رضی اللہ عنہما کی عظمت کردار اور استقامت دین کے ساتھ ان کا دین پرسختی سے عمل پیرا ہونے کا حقیقی جذبہ بھی معلوم ہوا، نیز یہ بھی واضح ہوا کہ دینی معاملات میں آپ نہایت جراأت مند تھے۔\n3۔ یہ حدیث مبارکہ اس اہم مسئلے کے لیے بھی نص صریح کی حیثیت رکھتی ہے کہ خالق کی معصیت کرتے ہوئے، مخلوق میں سے کسی بھی بڑی سے بڑی شخصیت کی اطاعت کرنا اور اس کی بات ماننا حرام اور ناجائز ہے۔\n4۔ کافر مسلمان کو صابی کہتے تھے۔ اس کے معنی ہیں: اپنے دین سے نکل جانے والا۔ وہ اس سے بے دین مراد لیتے تھے۔ صبأنا اسی سے ہے۔ بنو جزیمہ کا مقصود تو یہ تھا کہ ہم اپنے آبائی دین سے نکل کر مسلمان ہو چکے ہیں مگر انہوں نے وہ لفظ استعمال کیا جو کفار طنزاً مسلمانوں کے لیے استعمال کرتے تھے۔ اسی سے سیدنا خالد بن ولید رضی اللہ عنہ کو غلط فہمی ہوئی کہ شاید یہ اپنے کفر پر قائم ہیں اور ہمیں طنز کر رہے ہیں حالانکہ یہ بات نہیں تھی۔ حضرت خالد نے تادیبی کاروائی شروع کردی۔ چونکہ یہ ان کی اجتہادی غلطی تھی، اس لیے رسول اللہ علیہ وسلم نے صرف براءت کے اظہار پر اکتفا کیا اور انہیں کوئی سزا نہیں دی۔"}],[5406,"عبدالرحمٰن بن ابی بکرہ کہتے ہیں کہ میرے والد نے لکھوایا تو میں نے عبیداللہ بن ابی بکرہ کے پاس لکھا وہ سجستان کے قاضی تھے، تم دو لوگوں کے درمیان غصے کی حالت میں فیصلہ نہ کرو، اس لیے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا ہے: \"کوئی شخص دو لوگوں کے درمیان غصے کی حالت میں فیصلہ نہ کرے\"۔","الألباني: صحيح",{"u2":"حضرت عبد الرحمان بن ابوبکرہ سے منقول ہے کہ میرے والد نے مجھ سے (میرے بھائی) عبید اللہ بن ابوبکرہ کو جو سجستان (سیستان) کے قاضی تھے، یہ لکھوایا کہ غصے کی حالت میں دوآدمیوں (فریقین) کے درمیان فیصلہ نہ کرنا کیونکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: ’’کوئی شخص غصے کی حالت میں دو آدمیوں (فریقین) کے درمیان فیصلہ نہ کرے۔‘‘","f2":"رسول اللہ صلی اللہ علیہ وسلم کے علاوہ دوسرے کسی بھی شخص کو غصے کی حالت میں فیصلہ کرنے کا حق نہیں ہے۔ جس غصے کی حالت میں حاکم اور قاضی و جج وغیرہ کو فیصلہ کرنے سے روکا گیا ہے، اس غصے سے مراد زیادہ غصہ ہے جو سوچنے سمجھنے کی صلاحیت کو وقتی طور پر ختم کر دیتا ہے اور غلط فیصلے کا خطرہ ہوتا ہے، البتہ معمولی غصہ ج وکسی مجرم کا جرم سننے سے فطرتاً آجاتا ہے، فیصلے سے مانع نہیں۔ غصے کے علاوہ بھی جو چیز سوچنے سمجھنے کی صلاحیت پر اثر ڈالے، مثلاً: زیدہ بھوک، پیاس، پریشانی، بیماری اور نیند کا غلبہ وغیرہ ان کا حکم بھی غصے والا ہی ہے۔ بہتر ہے کہ فیصلہ مقدمےکی سماعت سے الگ مجلس میں لکھا جائے تا کہ وقتی جذبات اثر انداز نہ ہو سکیں۔"}],[5407,"زبیر بن عوام رضی اللہ عنہما سے روایت ہے کہ انصار کا ایک شخص سے جو بدر میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ شریک ہوا تھا حرہ کی نالیوں کے سلسلہ میں ان کا جھگڑا ہو گیا۔ وہ دونوں ہی اس سے اپنے کھجوروں کے باغ کی سنیچائی کرتے تھے۔ انصاری نے کہا: پانی چھوڑ دو وہ اس سے گزر کر چلا جائے، انہوں نے پانی چھوڑنے سے انکار کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"زبیر! پہلے سنیچائی کرو، پھر پانی اپنے پڑوسی کے لیے چھوڑ دو\"، انصاری کو غصہ آ گیا وہ بولا: اللہ کے رسول! وہ(زبیر) آپ کے پھوپھی زاد (بھائی) ہیں نا؟ یہ سن کر رسول اللہ صلی اللہ علیہ وسلم کے چہرے کا رنگ بدل گیا ۱؎، پھر فرمایا: \"زبیر! سینچائی کرو، پھر پانی اس قدر روکو کہ میڈوں تک ہو جائے\"، اس طرح رسول اللہ صلی اللہ علیہ وسلم نے زبیر کو ان کا پورا پورا حق دلایا، حالانکہ اس سے پہلے آپ نے جو مشورہ دیا تھا اس میں ان کا بھی فائدہ تھا اور انصاری کا بھی۔ لیکن جب رسول اللہ صلی اللہ علیہ وسلم کو انصاری نے غصہ دلایا تو آپ نے زبیر رضی اللہ عنہ کو صریح حکم دے کر ان کا حق دلا دیا۔ زبیر رضی اللہ عنہ کہتے ہیں کہ میں سمجھتا ہوں کہ یہ آیت اسی بارے میں نازل ہوئی ہے: «فلا وربك لا يؤمنون حتى يحكموك فيما شجر بينهم»\"نہیں، آپ کے رب کی قسم! وہ مومن نہیں یہاں تک کہ وہ اپنے جھگڑوں میں آپ کو حکم تسلیم نہ کر لیں\" (النساء: ۶۵) (اس حدیث کے دو راوی ہیں) اس واقعہ کو بیان کرنے میں ایک کے یہاں دوسرے کے بالمقابل کچھ کمی بیشی ہے۔\n§وضاحت\n۱؎: یہی باب سے مطابقت ہے کہ غصہ کی حالت میں ایک فیصلہ صادر فرمایا، چونکہ آپ امین تھے اس لیے آپ کو غصہ کی حالت میں بھی فیصلہ کرنے کا حق تھا، عام قاضیوں کو یہ حق نہیں ہے۔","الألباني: صحيح",{"u2":"سیدنا زبیر بن عوام رضی اللہ عنہ سے روایت ہے کہ ان کا ایک انصارآدمی سے، جو رسول اللہ صلی اللہ علیہ وسلم کی معیت میں جنگ بدر میں حاضر ہوئے تھے، حرہ کے برساتی نالوں (کے پانی) کے بارے میں جھگڑا ہو گیا۔ وہ دونوں اس برساتی نالے سے کھجور کے درختوں کو پانی لگاتے تھے۔ اس انصاری نے کہا: پانی گرزنے دو تا کہ میرے کھیت کو لگے۔ میں نے انکار کیا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’زبیر! ہلکا سا پانی لگا لو پھر اپنے پڑوسی کی طرف چھوڑ دو۔‘‘ انصاری کو غصہ آگیا اور ا س نے کہا: اللہ کے رسول! (آپ نے یہ فیصلہ اس لیے کی ہے کہ) یہ آپ کی پھوپھی کا بیٹا ہے؟ رسول اللہ صلی اللہ علیہ وسلم کا چہرہ انور غصے سے بدل گیا۔ پھر آپ نے فرمایا: ’’زبیر! پانی لگا اور پھر لگنے دے حتیٰ کہ پانی منڈیروں تک پہنچ جائے۔‘‘\nاب رسول اللہ صلی اللہ علیہ وسلم نے حضرت زبیر کو ان کا پورا حق دلوایا جب کہ اس سے پہلے آپ نے حضرت زبیر کو ایسا مشورہ دیا تھا جس میں زبیر اور انصاری دونوں کے لیے بہتری تھی لیکن جب انصاری نے رسول اللہ صلی اللہ علیہ وسلم کو ناراض کر دیا تو آپ نے واضح فیصلہ کی صورت میں زبیر کو ان کا پورا حق دلایا۔ حضرت زبیر رضی اللہ نے فرمایا: میرا خیال ہے کہ یہ آیت اسی (یا اس جیسے) واقعہ کے بارے میں اتری: ’’آپ کے رب تعالیٰ کی قسم! یہ لوگ صاحب ایمان نہیں ہو سکتے جب تک آپ کو اپنے اختلافی مسائل میں حکم نہ مان لیں‘‘\n(یونس بن عبد الاعلیٰ اور حارث بن مسکین) دونوں میں سے ہر ایک مذکورہ قصہ اپنے دوسرے ساتھی کے مقابلے میں کمی بیشی کے ساتھ روایت کرتا ہے۔","f2":"1۔جو پانی قدرتی طریقے سے بہتا ہو، اس کا اصول اور ضابطہ یہ ہے کہ ایسے پانی کے استعمال پر سب سے پہلا حق اس کا ہے جو اس کی طرف سبقت لے جائے اور اسی کی زمین وغیرہ ابتدا میں ہو۔ ایسے شخص کو اپنی زمین، کھیتی اور باغات وغیرہ مکمل طور پر سیراب کرنے کا حق ہے، تاہم اس کے لیے یہ ضروری ہے کہ جب اس کی ضرورت پوری ہو جائے تو پھر اس پانی کو آگے والے لوگوں کے لیے چھوڑ دے۔ اس پانی کو روک رکھنے کا حق پہلے شخص کو قطعا! نہیں۔\n2۔ حاکم کو یہ حق حاصل ہے کہ اگر وہ مناسب سمجھے تو باہم جھگڑنے والے فریقوں میں درمیانی راہ نکال کر صلح کرادے۔ فریقین اس پر راضی نہ ہوں تو حقیقی فیصلہ کردے اورہر فریق کو اس کا پورا پورا حق دلادے۔\n3۔ یہ صحابی انصاری اور بدری تھےا ور بدری صحابہ کے بارے میں قرآن و حدیث کی نصوص سے ثابت ہے کہ وہ قطعاً مومن اور جنتی ہیں، لۃذ انصاری سے لافاظ نفاق کی بنا پر نہیں بلکہ وقتی جذبات کے تحت صادر ہوئے تبھی تو آپ کے حتمی فیصلے پر اس نے سر تسلیم خم کر دیا اور کوئی اعتراض نہیں کیا۔ یہی اس کے ایمان کی دلیل ہے۔ ویسے بھی آپ نے پہلے فیصلہ نہیں فرمایا تھا بلکہ مصالحت کا مشورہ دیا تھا۔ جب مصالحت کار گر نہ ہوئی تو آپ نے حتمی فیصلہ دے دیا۔\n4۔ باب کا مقصود یہ ہے کہ غصے کی حالت میں بھی غلطی کا امکان نہیں۔۔ اس بارے میں سابقہ حدیث کا فائدہ بھی ملحوظ رکھا جائے۔"}],[5408,"کعب رضی اللہ عنہ سے روایت ہے کہ انہوں نے ابن ابی حدرد رضی اللہ عنہ سے اپنے قرض کا جو ان کے ذمہ تھا تقاضا کیا، ان دونوں کی آوازیں بلند ہو گئیں، یہاں تک کہ رسول اللہ صلی اللہ علیہ وسلم کو سنائی دیں، آپ اپنے گھر میں تھے، چنانچہ آپ ان کی طرف نکلے، پھر اپنے کمرے کا پردہ اٹھایا اور پکارا: \"کعب!\" وہ بولے: حاضر ہوں اللہ کے رسول! آپ نے فرمایا: \"اتنا قرض معاف کر دو\" اور آپ نے آدھے اشارہ کیا۔ کہا: میں نے معاف کیا، پھر آپ نے (ابن ابی حدرد سے) کہا: \"اٹھو اور قرض ادا کرو\"۔","الألباني: صحيح",{"u2":"سیدنا کعب رضی اللہ عنہ سے روایت ہے کہ میں نے ابن حدرد سے اپنے قرض کی واپسی کا مطالبہ کیا جو اس کے ذمے تھا۔ ہماری آوازیں اونچی ہو گئیں حتیٰ کہ رسول اللہ صلی اللہ علیہ وسلم نے بھی سن لیں۔ آپ اپنے گھر میں تشریف فرماتھے۔ آپ باہر تشریف لائے۔ اپنے حجرۂ مبارک کا پردہ ہٹایا اور بلند آواز سے فرمایا: ’’اے کعب!‘‘ میں نے کہا: اے اللہ کے رسول! میں حاضر ہوں۔ آپ نے فرمایا: ’’اتنا معاف کردے۔‘‘ اور ہاتھ سے نصف کا اشارہ فرمایا۔ میں نے کہا: مان لیا۔ آپ نے (ابن ابی حدرد سے) فرمایا: ’’اٹھ اور باقی ادا کر۔‘‘","f2":"1۔ کسی ضروت کی بنا پر حاکم یا قاضی وغیر اپنے گھر میں یا ’’کمرۂ عدالت‘‘ سے باہر کوئی فیصلہ کرے تو یہ جائز ہے۔ بشر طیکہ اس کی وجہ سے لوگوں کے لیے کوئی مشکل یا تکلیف وغیرہ نہ ہو۔\n2۔ اس ھدیث مبارکہ سے یہ بھی معلوم ہوتاہے کہ اگر بوقت ضرورت کبھی مسجد میں آواز اونچی ہو جائے تو کوئی حرج نہیں، البتہ اس کو معمول بنانا اور خواہ مخواہ اپنی آواز مسجد میں بلند اور اونچی کرنا درست نہیں۔\n3۔ اس ھدیث مبارکہ سے یہ بھی واضح ہوتا ہے کہ ایسا اشارہ جس سے مفہوم سمجھ میں آجائے وہ بمنزلہ لام کے ہوتا ہے کیونکہ اس اشارے کی دلالت کلام پر ہوتی ہے۔ بنا بریں گونگے کی گواہی، اس کی قسم، اس کی خریدو فروخت اور4 دیگر معاملات درست قرار پائیں گے۔\n4۔ یہ حدیث اس مسئلے کی بھی وضاحت کرتی ہے ہے کہ اگر صاحب حق سے سفا رش کرکے اس کے حق میں سے سارا یا کچھ معاف کر الیا جائے تو ایسا کرنا شرعاً درست ہے، نیز صاحب حق یا کسی دوسرے شخص کو اگر جائز سفارش کی جائے، تو سے سفارش قبول کر لینی چاہیے۔\n5۔ مسجد میں ادائیگی قرض کا مطالبہ اور تقاضا کرنا درست ہے، نیز قرض کے علاوہ اپنےدیگر حقوق کا مطالبہ بھی مسجد میں کیا جاسکتا ہے۔\n6۔ اس حدیث مبارکہ سے یہ بھی معلوم ہو اکہ کسی ضرورت کی بنا پر کھڑکیوں اور دروازوں پرپردے لٹکانا شرعاً جائز داور درست ہے۔"}],[5409,"عباد بن شرحبیل رضی اللہ عنہ کہتے ہیں کہ میں اپنے چچاؤں کے ساتھ مدینے آیا تو وہاں کے ایک باغ میں گیا اور ایک بالی (توڑ کر) مسل ڈالی، اتنے میں باغ کا مالک آ گیا، اس نے میری چادر چھین لی اور مجھے مارا، میں نے رسول اللہ صلی اللہ علیہ وسلم کے پاس آ کر آپ سے اس کے خلاف مدد چاہی، چنانچہ آپ نے اس شخص کو بلا بھیجا۔ لوگ اسے لے کر آئے، آپ نے فرمایا: \"اس اقدام پر تمہیں کس چیز نے اکسایا؟\" وہ بولا: اللہ کے رسول! یہ میرے باغ میں آیا اور بالی توڑ کر مسل دی، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"نہ تو تم نے اسے بتایا جب کہ وہ ناسمجھ تھا، نہ تم نے اسے کھلایا جبکہ وہ بھوکا تھا، اس کی چادر اسے لوٹا دو\"، اور مجھے رسول اللہ صلی اللہ علیہ وسلم نے ایک وسق یا آدھا وسق دینے کا حکم دیا ۱؎۔\n§وضاحت\n۱؎: ابوداؤد کے الفاظ ہیں «وأعطانی» یعنی اس باغ والے نے مجھے ایک یا آدھا صاع غلہ دیا \" یعنی اس نے جو میری ساتھ زیادتی کی تھی اس کے بدلے میں آپ صلی اللہ علیہ وسلم نے میرے لیے اس تاوان کا حکم دیا۔","الألباني: صحيح",{"u2":"سیدنا عباد بن شرجیل رضی اللہ عنہ سے روایت ہے، انہوں نے فر مایا: میں اپنے چچاؤں کے ساتھ مدینہ منورہ آیا۔ میں ایک باغ میں داخل ہوا اور میں نے کچھ سٹے توڑ کر ان کے دانے نکال لیے۔ باغ کا مالک آیا، اس نے میری چادر چھین لی اور مجھے مارا بھی۔ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور دعویٰ دائر کر دیا۔ آپ نے اس شخص کو بلا بھیجا۔ لوگو اس کے لے کر آپ کے پاس آئے۔ آپ نے فرمایا: ’’تو نے ایسے کیوں کیا؟‘‘ اس نے کہا: اے اللہ کے رسول یہ میرے باغ میں داخل ہوا۔ اس نے کچھ سٹے توڑے اور ان کے دانے نکال لیے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’یہ جاہل تھا، تو نے اسے تعلیم نہ دی۔ یہ بھوکا تھا، تونے اسے کھانے کو نہ دیا۔ اس کی چادر واپس کر۔‘‘ اور مجھے ایک یا نصف وسق دینے کا حکم جاری فرمایا۔","f2":"1۔ باب کا مقصد یہ ہے کہ دعویٰ دائر کرنا شرعاً جائز ہے۔ یہ فریق ثانی پر زیادتی نہیں بلکہ اپنا حق لینے کے لیے درست ہے۔\n2۔ ’’جاہل تھا‘‘ مقصود یہ ہے کہ غلطی کرنے والے کو صحیح اور درست عمل بتانا چاہیے تھا، اجنبی تھا پھر بھوکا بھی تھا، اس لیے تجھے چاہیے تھا کہ اسے پیار کے ساتھ بتاتا کہ اس طرح اپنی مرضی سے توڑنے کی بجائے مالک سے مانگ لینا چاہیے۔ پھر تو اسے کھانے کو مزید دیتا تا کہ اس کی ضرورت پوری ہوتی جب کہ تو نے اس غریب کی چادر بھی چھین لی اور مارا بھی۔\n3۔ معلوم ہوا جرائم کی سزا دینے سے پہلے لوگوں کی تولیم تربیت ضروری ہے، نیز ان کی بنیادی ضروریات بھی پوری کی جائیں تا کہ وہ جان بچانے کے لیے جرم نہ کریں۔\n4۔ اس حدیث مبارکہ سے معلوم ہو اکہ ضرورت مند، بقدر ضرورت کسی کے باغ یا کھیت سے لے اور کھا سکتا ہے، البتہ اتنا زیادہ لینا درست نہیں جو ضرورت پوری ہونے کے بعد ساتھ بھی لے جائے۔ یاد رہے کہ بغیر اجازت کسی کے باغ سے کھا پی لینا ایسا جرم نہیں کہ اس پر چوری کی حد نافذ ہو بلکہ اگر وہ بھوکا ہو تو اسے کچھ نہیں کہا جائے گا اور اگر وہ بھوک کے بغیر ہو تا سے جرمانہ وغیرہ کیا جاسکتا ہے۔ اگر ضرورت محسوس ہو تو جسمانی سزا بھی دی جا سکتی ہے۔\n5۔ ’’حکم جاری فرمایا‘‘ یعنی بیت المال سے نہ کہ اس آدمی کے مال سے۔ ابو داؤد کی روایت میں صراحت ہے کہ آپ نے غلے کا ایک یا نصف وسق مجھے عطا فرمایا۔ (سنن أبی داؤد، الجہاد، حدیث:2620)\n6۔ ایک اونٹ پر جتنا غلہ لادا جاتا ہے، اس ے بھی سوسق کہتے ہیں۔\n7۔ کسی کی تھوڑی بہت چیز بلا اجازت لے لینا اس چوری میں شامل نہیں جس کی سزا ہاتھ کاٹنا ہے۔ اس پر مناسب تعزیر ہی کافی ہے، لبتہ بلا اجازت کسی کا مال لینے والے سے پہلے اس کا سبب معلوم کرنا چاہیے اور اگر اس کا کوئی معقول عذر ہو تو پھر اسے معاف کردینا چاہیے کیونکہ بعض حالات اس قسم کے ہوتے ہیں کہ ان میں معافی ہی درست ہوتی ہے۔\n8۔ اس حدیث مبارکہ سے یہ بھی معلوم ہوا کہ ایسے مستحق شخص کی مدد بیت المال اور حکومتی خزانے سے کرنی چاہیے۔ یہ اس کا حق ہے۔"}],[5410,"ابوہریرہ اور زید بن خالد جہنی اللہ عنہما بیان کرتے ہیں کہ دو آدمی جھگڑا لے کر رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، ان میں سے ایک نے کہا: ہمارے درمیان کتاب اللہ (قرآن) سے فیصلہ فرمایئے اور دوسرا جو زیادہ سمجھدار تھا بولا: ہاں، اللہ کے رسول اور مجھے کچھ بولنے کی اجازت دیجئیے، وہ کہنے لگا: میرا بیٹا اس آدمی کے یہاں نوکر تھا، اس نے اس کی عورت کے ساتھ زنا کیا، تو لوگوں نے مجھے بتایا کہ میرے بیٹے کی سزا رجم ہے، چنانچہ میں نے اسے بدلے میں سو بکریاں اور اپنی ایک لونڈی دے دی، پھر میں نے اہل علم سے پوچھا، تو انہوں نے بتایا کہ میرے بیٹے کی سزا سو کوڑے اور ایک سال کی جلا وطنی ہے، اور رجم کی سزا اس کی عورت کی تھی، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! میں تمہارے درمیان کتاب اللہ (قرآن) کے مطابق فیصلہ کروں گا، تمہاری بکریاں اور لونڈی تو تمہیں لوٹائی جائیں گی\"، اور آپ نے اس کے بیٹے کو سو کوڑے لگائے اور اسے ایک سال کے لیے جلا وطن کر دیا، اور انیس (رضی اللہ عنہ) کو حکم دیا کہ وہ دوسرے کی بیوی کے پاس جائیں ۱؎، اگر وہ اس جرم کا اعتراف کر لے تو اسے رجم کر دو، چنانچہ اس نے اعتراف کر لیا تو انہوں نے اسے رجم کر دیا۔\n§وضاحت\n۱؎: اسی میں باب سے مطابقت ہے، یعنی: وہ عورت مجلس قضاء میں طلب نہیں کی گئی، اسی لیے آپ نے انیس رضی اللہ عنہ کو اس کے پاس اس کے گھر بھیجا، ہاں اگر کسی معاملہ میں عورتوں کی حاضری مجلس قضاء میں ضروری ہو تو پردے کے ساتھ ان کو لایا جا سکتا ہے، اور پردے کی آڑ سے ان کا بیان لیا جا سکتا ہے۔","الألباني: صحيح",{"u2":"حضرت ابو ہریرہ اور زید بن خالد جہنی رضی اللہ عنہما سے مروی ہے، انہوں نے بیان فرمایا کہ دو آدمی رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک مقدمہ لائے۔ ان میں سے ایک نے کہا: ہمارے درمیان اللہ تعالیٰ کی کتاب کے مطابق فیصلہ فرمائیے۔ دوسرے شخص نے کہا، جو ان میں سے زیادہ سمجھ دار تھا: اے اللہ کے رسول! ضرور اور مجھے اجازت دیجیے کہ میں بات چیت کروں۔ (پھر اجازت ملنے کے بعد) اس نے کہا: میر بیٹا اس کا نوکر تھا۔ اس نے اس کی بیوی سے زنا کر لیا۔ لوگوں نے مجھے بتایا کہ میرے بیٹے کو رجم کی سزا ملے گی تو میں نے سو بکریوں اورا یک لونڈی کےت عوض (اپنے بیٹے) چھڑا لیا۔ پھر میں نے اہل علم سے مسئلہ پوچھا تو انہوں نے مجھے بتایا کہ تیرے بیٹے کو سو کوڑے لگیں اور ایک سال کے لیےجلا وطن ہوگا۔ رجم تو اس کی بیوی ہوگی۔ رسول اللہ صلی اللہ علیہ وسلم نے قسم اس ذات کی جس کے ہاتھ میں میری جان ہے، میں تمہارے درمیان اللہ تعالیٰ کی کتاب کے مطابق فیصلہ کروں گا۔ باقی رہی تیری بکریاں اور لونڈی، تو وہ تجھے واپس مل جائیں گی۔‘‘ پھر آپ نے اس کے بیٹے کو سو کوڑے لگوائے اور اسے ایک سال کے لیے جلا وطن کر دیا۔ اور آپ نے حضرت انیس کو حکم دیا کہ اس (دوسرے شخص) کی بیوی کے پاس جاؤ۔ اگر وہ (زنا کے جرم کو) تسلیم کرے تو اسے رجم کردو۔ عورت نے گنا ہ تسلیم کر لیا تو انہوں نے اسے رجم کر دیا۔","f2":"1۔ امام نسائی رحمہ اللہ علیہ نے جو عنوان قائم کیا ہے اس کا مقصد یہ ہے کہ اگر عورت کو عدالت اور پنچائت وغیرہ میں لائے بغیر مسئلہ حل ہو سکتا ہو تو انہیں عدالتوں اور پنچائتوں وغیرہ میں نہیں گھسیٹنا چاہیے کہ رسول اللہ صلی اللہ علیہ وسلم نے اس متعلقہ خاتون کو اپنے ہاں بلانے کی بجائے، اپنی طرف سے آدمی بھیج کر اس عورت سے حقیقت حال معلوم کی اور پھر اس کے اقرار کرنے پر اس پر زنا کی مذکورہ حد نافذ کی، یعنی اسے رجم کر دیا گیا۔\n2۔ اس حدیث مبارکہ سے معلوم ہو اکہ اپنے تمام مسائل بالخصوص حدود سے متعلق معاملات میں قرآن کے فیصلے کی طرف رجوع کرنا چاہیے۔ اور جب کوئی مجرم و ملزم اقرار جرم کر لے تو حاکم پر واجب ہے کہ وہ اس پر حد قائم کرے۔ ہمارے ہاں ملک کے صدر کو سزائے موت ختم کرنے اک جو اختیار ہے، شرعاً ناجائز اور حرام ہے۔\n3۔ اس حدیث مبارکہ سے معلوم ہو اکہ معاملے کہ پختگی ظاہر کرنے کے لیے قسم کھانا درست ہے، نیز یہ بھی معلوم ہوا کہ قسم کھانے کا مطالبہ نہ کیا گیا ہو تو بھی قسم کھائی جاسکتی ہے۔\n4۔ یہ حدیث مبارکہ رسول اللہ صلی اللہ علیہ وسلم کے حسن خل اور عظیم حوصلے کی صریح دلیل ہے، نیز اس بات کی بھی دلیل ہے کہ مدعی، مستفتی (فتویٰ طلب کرنے والے) اور طلاب کے لیے مستحب بات یہ ہے کہ وہ قاضی، عالم دین اور حاکم کےپاس اپنا مسئلہ پیش کرنے پہلے اجازت طلب کرے، نیز معلوم ہوا کہ ظن و تخمین پر مبنی حکم اور فیصلہ قطعی اور یقینی دلائل و براہین کے آنے پر ختم ہوجائے گا، اس طرح خلاف شریعت کی گئی صلح مردود ہوگی اور اس سلسلے میں دیا گیا مال و متاع بھی واپس ہو جائے گا۔\n5۔ حد کے مقبلے میں فدیہ (مالی معاوضہ) شرعاً قابل قبول نہیں ہوگا اور نہ مالی معاوضۃ لے کر کوئی شرعی حد ساط کی جاسکتی ہے۔ اس پر اہل علم کا اجماع ہے بالخصوص زنا چوری اور شراب نوشی وغیرہ جرم کے مرتکب پر ھد قائم کی جائے گی… واللہ أعلم\n6۔ ’’چھڑالیا‘‘ اس نے سمجھا کہ کسی کی بیوی سے زنا خاوند کی حق تلفی ہے، اس لیے اسے راضی کرلینا کافی ہے، حالانکہ یہ شرعی امر کی خلاف ورزی ہے جس کا تعلق معاشرے کے ساتھ ہے، لہٰذا یہ جرم خاوند کے معاف کرنے سے معاف نہیں ہوگا بلکہ مقدمہ عدالت میں آنے کے بعد لازماً سزا نافذ ہوگی۔\n7۔ ’’کوڑے لگائے‘‘ کیونکہ وہ خود معترف تھا۔ جرم ثابت ہو چکا تھا۔ امام مالک رحمہ اللہ علیہ کے نزدیک جلاوطن کرنےکی بجائے جیل میں بھی ڈالا جا سکتا ہے۔ اور یہ صحیح ہے۔ کیونکہ مقصود حاصل ہو جاتا ہے کہ وہ اپنے گھر سے باہر رہے اور متعلقہ کی جگہ کے قریب نہ جائے۔ احناف کے نزیدیک جلاوطنی سزا کا حصہ نہیں۔ لہٰذا ضروری نہیں۔ لیکن صریح حدیث کی روشنی میں یہ مؤقف محل نظر ہے۔"}],[5411,"ابوہریرہ، زید بن خالد اور شبل رضی اللہ عنہم کہتے ہیں کہ ہم لوگ نبی اکرم صلی اللہ علیہ وسلم کے پاس تھے، تو ایک شخص نے کھڑے ہو کر کہا: میں آپ کو اللہ کی قسم دیتا ہوں کہ آپ ہمارے درمیان اللہ کی کتاب (قرآن) کے مطابق فیصلہ کیجئے، پھر اس کا فریق مخالف کھڑا ہوا اور وہ اس سے زیادہ سمجھ دار تھا، اس نے کہا: اس نے ٹھیک کہا ہے، آپ ہمارے درمیان اللہ کی کتاب (قرآن) کے مطابق فیصلہ فرمایئے۔ آپ نے فرمایا: \"بتاؤ\" تو اس نے کہا: میرا بیٹا اس کے یہاں نوکر تھا، تو وہ اس کی بیوی کے ساتھ زنا کر بیٹھا۔ چنانچہ میں نے اس کے بدلے سو بکریاں اور ایک خادم (غلام) دے دیا (گویا اسے معلوم تھا کہ اس کے بیٹے پر رجم ہے، چنانچہ اس نے تاوان دے دیا)، پھر میں نے اہل علم سے پوچھا تو انہوں نے مجھے بتایا کہ میرے بیٹے پر سو کوڑے اور ایک سال کی جلا وطنی کی سزا ہے، یہ سن کر رسول اللہ صلی اللہ علیہ وسلم نے اس سے فرمایا: \"اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! میں تمہارے درمیان اللہ کی کتاب (قرآن) کے مطابق فیصلہ کروں گا: رہیں سو بکریاں اور خادم (غلام) تو وہ تمہیں لوٹائے جائیں گے، اور تمہارے لڑکے پر سو کوڑے اور ایک سال کی جلا وطنی کی سزا ہے، اور انیس! تم صبح اس کی عورت کے پاس جاؤ، اگر وہ اقبال جرم کر لے تو اسے رجم کر دینا\"، چنانچہ وہ گئے، اس نے اقبال جرم کیا تو انہوں نے اسے رجم کر دیا۔","الألباني: صحيح",{"u2":"حضرت ابو ہریرہ، خالد بن زید اور شبل رضی اللہ عنہم سے منقول ہے کہ ہم نبیٔ اکرم صلی اللہ علیہ وسلم کے پاس حاضر تھے کہ ایک آدمی کھڑا ہو کر کہنے لگا: میں آپ کو اللہ کی قسم دیتا ہوں کہ آپ ہمارے درمیان کتاب اللہ کے مطابق فیصلہ فرمائیں۔ پھر فریق ثانی بھی اٹھا جو کہ پہلے شخص سے زیادہ سمجھ دار تھا اور کہا: یہ صحیح کہتا ہے۔ آپ ہمارے درمیان کتاب اللہ کے مطابق فیصلہ فرمائیں۔ آپ نے فرمایا: ’’بات کرو۔‘‘ اس نے کہا: میرا بیٹا اس کے ہاں نوکر تھا۔ اس نے اس کی بیوی سے زنا کر لیا۔ میں نے سو بکریاں اور ایک نوکر دے کر اپنےبیٹے کی جان بخشی کروائی۔ گویا کہ اس شخص کو بتلایا گیا تھا کہ اس کے بیٹے کو رجم کر دیا جائے گا، اس لیے اس نے اس طریقے سے اس کی جان بخشی کروائی۔ پھر میں نے بہت سے اہل علم سے پوچھا تو انہوں نے مجھے بتایا کہ میرے بیٹے کو سو کوڑے لگیں گے اور ایک سال کے لیے جلا وطن ہوگا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’قسم اس ذات کی جس کے ہاتھ میں میری جان ہے! میں تمہارے درمیان کتاب اللہ کے مطابق ہی فیصلہ کروں گا۔ تیری سوبکریاں اور نوکر تجھے واپس مل جائیں گے۔ تیرے بیٹے کو سو کوڑے لگیں گے۔ اور اے انیس! تو اس کی بیوی کے پاس جا۔ اگر وہ جرم تسلیم تو اسے رجم کردے۔‘‘ وہ اس کے پاس گئے، اور اس (عورت) نے مان لیا تو انہوں نے سے رجم کردیا۔","f2":"کتاب اللہ سے مراد اللہ تعالیٰ کی شریعت ہے، خواہ وہ قرآن مجید میں بیان ہو یا سنت رسول میں۔"}],[5412,"ابوامامہ بن سہل بن حنیف سے (مرسلاً) ۱؎ روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم کے پاس ایک عورت لائی گئی، جس نے زنا کا ارتکاب کیا تھا تو آپ نے فرمایا:\"کس کے ساتھ؟\" وہ بولی: اپاہج سے جو سعد رضی اللہ عنہ کے باغ میں رہتا ہے، آپ نے اسے بلا بھیجا چنانچہ وہ لاد کر لایا گیا اور اسے آپ کے سامنے رکھا گیا، پھر اس نے اعتراف کیا تو رسول اللہ صلی اللہ علیہ وسلم نے کھجور کے خوشے منگا کر اسے مارا اور اس کے لنجے پن کی وجہ سے اس پر رحم کیا اور اس پر تخفیف کی ۲؎۔\n§وضاحت\n۱؎: نسائی کی روایت مرسل ہے، لیکن دیگر لوگوں کے یہاں \" سعید بن سعد بن عبادہ :(ایک چھوٹے صحابی ) یا: بعض اصحاب نبی اکرم صلی اللہ علیہ وسلم کا واسطہ موجود ہے، اس لیے حدیث متصل مرفوع صحیح ہے۔ ۲؎: چونکہ وہ غیر شادی شدہ تھا اس لیے اس کو رجم کی سزا نہیں دی گئی، اور کوڑے میں بھی تخفیف سے کام لیا گیا۔","الألباني: صحيح",{"u2":"سیدنا ابو امامہ بن سہل بن حنیف رضی اللہ عنہ سے منقول ہے کہ نبیٔ اکرم صلی اللہ علیہ کے پاس عورت لائی گئی جس نے زنا کیا تھا۔ آپ نے فرمایا: ’’کس کے ساتھ؟‘‘ کسی نے کہا: اس اپاہج کے ساتھ جو حضرت سعد کے گھر میں رہتا ہے۔ آپ نے اسے بلا بھیجا۔ اس کو اٹھاکر لایا گیا۔ اور آپ کے سامنےرکھ دیا گیا۔ اس نے جرم کا اعتراف کر لیا۔ رسول اللہ صلی اللہ علیہ وسلم نے کھجور کی شاخ منگوائی اور اس کو پیٹا۔ آپ نے اس پر اس پر اس کے اپاہج ہونے کی وجہ سے ترس کیا اور اس کو ہلکی سزا دی۔","f2":"1۔ امام نسائی رحمہ اللہ علیہ نے جو عنوان قائم کیا ہے اس کا مقصد یہ مسئلہ بیان کرنا ہے کہ اگر کسی شخص کے بارے میں جج کو اطلاع ملے کہ اس نے زنا کیا ہے تو وہ اسے بلا کر اس سے منسوب جر م کی تحقیق کر سکتا ہے، نیز جرم ثابت ہونے پر اسے حد بھی لگائی جائے گی۔ موجودہ دور میں سپریم کورٹ کے چیف جسٹس کا ’’سومو‘‘ نوٹس لینا اسی قبیل سے ہے اور یہ مشروع عمل ہے۔\n2۔ اس حدیث مبارکہ سے معلوم ہوا کہ ایک بار اقرار ِ زنا کرنے سے زنا ثابت ہوجاتا ہے۔ تین یا چار بار اقرار کرانا ضروری نہیں۔\n3۔ ’’ترس کیا‘‘ وہ شادی شدہ تو نہیں تھا۔ اس کو ڑے تو لگنا ہی تھےت لیکن اس کی بیماری کی وجہ سے خطرہ تھا کہ وہ مرجائے گا، لہٰذا بجائے کوڑوں کے کھجور کی شاخ سے پیٹا گیا کیونکہ کوڑے لگا کر مجرم کو قتل نہیں کیا جاسکتا۔"}],[5413,"سہل بن سعد ساعدی رضی اللہ عنہ کہتے ہیں کہ انصار کے دو قبیلوں کے درمیان تکرار ہوئی یہاں تک کہ وہ ایک دوسرے کو پتھر مارنے لگے، تو نبی اکرم صلی اللہ علیہ وسلم ان کے درمیان صلح کرانے گئے، اتنے میں نماز کا وقت ہو گیا، تو بلال رضی اللہ عنہ نے اذان دی اور آپ کا انتظار کیا اور رکے رہے، پھر اقامت کہی اور ابوبکر رضی اللہ عنہ آگے بڑھے، اتنے میں نبی اکرم صلی اللہ علیہ وسلم آ گئے، ابوبکر رضی اللہ عنہ لوگوں کو نماز پڑھا رہے تھے، جب لوگوں نے آپ کو دیکھا تو (بتانے کے لیے)تالی بجا دی۔ (ابوبکر نماز میں کسی اور طرف توجہ نہیں دیتے تھے) پھر جب انہوں نے ان سب کی تالی کی آواز سنی تو مڑے، دیکھا کہ رسول اللہ صلی اللہ علیہ وسلم ہیں، انہوں نے پیچھے ہٹنے کا ارادہ کیا، تو آپ نے وہیں رہنے کا اشارہ کیا، تو ابوبکر رضی اللہ عنہ نے اپنے دونوں ہاتھ اٹھائے اور الٹے پاؤں پیچھے ہٹے، پھر رسول اللہ صلی اللہ علیہ وسلم آگے بڑھے اور نماز پڑھائی، پھر جب رسول اللہ صلی اللہ علیہ وسلم نے نماز پوری کر لی تو فرمایا: \"تمہیں وہیں رکنے سے کس چیز نے روکا؟\" وہ بولے: یہ ممکن نہیں کہ اللہ تعالی ابوقحافہ کے بیٹے کو اپنے نبی کے آگے دیکھے، پھر آپ لوگوں کی طرف متوجہ ہوئے اور فرمایا: \"تمہیں کیا ہو گیا ہے کہ جب تمہیں نماز میں کوئی چیز پیش آتی ہے تو تالی بجانے لگتے ہو، یہ تو عورتوں کے لیے ہے، تم میں سے کسی کو جب کوئی بات پیش آئے تو وہ «سبحان اللہ» کہے\"۔","الألباني: صحيح",{"u2":"سیدنا سہل بن سعد ساعدی رضی اللہ عنہ فرماتےہیں کہ انصار کے دو قبیلوں کے درمیان جھگڑا ہو گیا حتیٰ کہ انہوں نے ایک دوسرے پر پتھر وغیرہ بھی پھینکے۔ نبیٔ اکرم صلی اللہ ان کے درمیان صلح کروانے کے لیے تشریف لے گئے۔ اتنے میں نماز کا وقت ہوگیا تو سیدنا بلال رضی اللہ عنہ نے کہی، پھر رسول اللہ صلی اللہ علیہ کا انتظار کیا گیا لیکن آپ کو زیادہ دیر ہوگئی تو سیدنا بلال رضی اللہ عنہ نے اقامت کہی۔ سیدنا ابوبکر صدیق رضی اللہ عنہ آگے بڑھے (جماعت شروع کرادی)۔ اتنے میں رسول اللہ صلی اللہ علیہ وسلم بھی تشریف لے آئے جبکہ سیدنا ابوبکر رضی اللہ عنہ نماز میں ادھر توجہ نہیں کرتے تھے لیکن جب انہوں نے بہت زیادہ تالیوں کی آواز سنی تو متوجہ ہوئے۔ اچانک ان کی نظر رسول اللہ صلی اللہ علیہ وسلم پر پڑی۔ انہوں نے پیچھے ہٹنے کا ارادہ کیا۔ آپ نے اشارہ فرمایا کہ اپنی جگہ ٹھہرے رہو۔ سیدنا ابوبکر رضی اللہ عنہ نے (نبیٔ اکرم صلی اللہ علیہ وسلم کی اس عظیم ترین عزت افزائی پر اللہ تعالیٰ کی حمد و ثنا کرتے ہوئے) اپنے ہاتھ اٹھائے، پھر الٹے پاؤں پیچھے آگئے۔ رسول اللہ صلی اللہ علیہ وسلم آگے بڑھے اور نماز پڑھائی۔ جب رسول اللہ صلی اللہ علیہ وسلم نے نماز مکمل فرمائی تو (سیدنا ابوبکر رضی اللہ عنہ سے) فرمایا: ’’تم اپنی جگہ کیوں نہ کھڑے رہے؟‘‘ سیدنا ابوبکر رضی اللہ عنہ سے) فرمایا: ’’تم اپنی جگہ کیوں نہ کھڑے رہے؟‘‘ سیدنا ابوبکر رضی اللہ عنہ نے کہا: یہ مناسب نہیں تھا کہ اللہ تعالیٰ ابو قحافہ کے بیٹے کو اپنے نبیٔ اکرم صلی اللہ علیہ وسلم کے آگے کھڑا دیکھے۔ پھر رسول اللہ صلی اللہ علیہ وسلم لوگوں کی طرف متوجہ ہوئے اور فرمایا: ’’کیاوجہ ہےئ جب تمہیں نماز میں کوئی مشکل پیش آتی ہے تو تم تالیاں بجانے لگ جاتے ہو! یہ تو عورتوں کے لیے ہے۔ جس مرد کو نماز میں کوئی مشکل پیش آئے تو وہ سبحان اللہ کہے۔‘‘","f2":"باب کا مقصد یہ ہے کہ حاکم اس انتظار میں نہ رہے کہ لوگ لڑنے کے بعد میرے پاس آئیں گے توفیصلہ کروں گا بلکہ کوشش کرے کہ لڑائی ہو ہی نہ۔ صلح سے کام چل جائے۔ حدیث کے باقی مباحث پیچھے گزر چکے ہیں۔"}],[5414,"عبدالرحمٰن بن ہرمز کہتے ہیں کہ میں نے اسید بن رافع بن خدیج انصاری کو بیان کرتے سنا کہ انہیں (یعنی صحابہ کو) بیع محاقلہ سے روک دیا گیا ہے، بیع محاقلہ یہ ہے کہ زمین کو اس کی کچھ پیداوار کے بدلے کھیتی کرنے کے لیے دے دیا جائے۔ اسے عیسی بن سہل بن رافع نے بھی روایت کیا ہے۔\nکعب بن مالک رضی اللہ عنہ سے روایت ہے کہ عبداللہ بن ابی حدرد اسلمی رضی اللہ عنہ پر ان کا قرضہ تھا، وہ راستے میں مل گئے تو انہیں پکڑ لیا، پھر ان دونوں میں تکرار ہو گئی، یہاں تک کہ ان کی آوازیں بلند ہو گئیں، ان کے پاس سے رسول اللہ صلی اللہ علیہ وسلم کا گزر ہوا تو آپ نے فرمایا: \"کعب!\" پھر اپنے ہاتھ سے ایک اشارہ کیا گویا آپ کہہ رہے تھے: \"آدھا\"، چنانچہ انہوں نے آدھا قرضہ لے لیا اور آدھا چھوڑ دیا۔","الألباني: صحيح الإسناد",{"u2":"سیدنا کعب بن مالک رضی اللہ عنہ سے روایت ہے کہ ان کا حضرت عبد اللہ بن ابی حدرد اسلمی کے ذمے قرض تھا۔ وہ اسے ملے تو انہوں نے اسے پکڑلیا۔ پھر وہ دونوں جھگڑنے لگے حتیٰ کہ (ان کی) آوازیں بلند ہوئیں، پھر رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس سے گزرے اور فرمایا: ’’کعب!‘‘ نیز آپ نے اپنے ہاتھ سے اشارہ فرمایا۔ مقصد یہ تھا کہ نصف معاف کردے۔ انہوں نے نصف لے لیا اور نصف معاف کردیا۔"}],[5415,"وائل رضی اللہ عنہ کہتے ہیں کہ میں اس وقت رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر تھا جب قاتل کو مقتول کا ولی ایک رسی میں باندھ کر گھسیٹتا ہوا لایا، رسول اللہ صلی اللہ علیہ وسلم نے مقتول کے ولی سے فرمایا: \"کیا تم معاف کر دو گے؟\" وہ بولا: نہیں، آپ نے فرمایا: \"کیا دیت لو گے؟\" وہ بولا: نہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تو اسے قتل کرو گے؟\" کہا: جی ہاں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اسے لے جاؤ\" (اور قتل کرو) جب وہ چلا اور آپ کے پاس سے چلا گیا تو آپ نے اسے بلایا اور فرمایا: \"کیا معاف کر دو گے؟\" کہا: نہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"دیت لو گے؟\" کہا: نہیں، آپ نے فرمایا: \"تو اسے قتل کرو گے؟\" کہا: ہاں، آپ نے فرمایا: \"لے جاؤ اسے\" (اور قتل کرو) جب وہ چلا اور آپ کے پاس سے چلا گیا تو آپ نے اسے بلایا اور فرمایا: \"کیا معاف کر دو گے؟\" کہا: نہیں، آپ نے فرمایا: \"دیت لو گے؟\" کہا: نہیں، آپ نے فرمایا: \"تو اسے قتل کرو گے؟\" کہا: ہاں، آپ نے فرمایا: \"لے جاؤ اسے\" (اور قتل کرو) پھر رسول اللہ صلی اللہ علیہ وسلم نے اس وقت فرمایا: \"اگر تم اسے معاف کر دو تو یہ اپنے گناہ اور تمہارے (مقتول) ساتھی کے گناہ سمیٹ لے گا\"، یہ سن کر اس نے معاف کر دیا اور اسے چھوڑ دیا، میں نے دیکھا کہ وہ اپنی رسی کھینچ رہا تھا۔","الألباني: صحيح",{"u2":"سیدنا وائل رضی اللہ عنہ بیان کرتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر تھا جب ایک مقتول کا ولی قاتل کو چمڑے کی تندی کے ساتھ جکڑ کا لایا۔ رسول اللہ صلی اللہ علیہ وسلم نے مقتول کی ولی سے فرمایا: ’’کیا تو معاف کرتا ہے؟‘‘ اس نے کہا: نہیں۔ آپ نے فرمایا: ’’دیت لے گا؟‘‘ اس نے کہا: نہیں۔ آپ نے فرمایا: ’’پھر قتل کرے گا؟‘‘ اس نے کہا: جی ہاں۔ آپ نے فرمایا: ’’پھر تو اس کو لے جا۔‘‘ جب وہ اس کو لے کر چل پڑا تو آپ نے اسے بلایا اور فرمایا: ’’معاف کرے گا؟‘‘ اس نے کہا: نہیں۔ آپ نے فرمایا: ’’دیت لے گا؟‘‘ اس نے کہا: نہیں۔ آپ نے فرمایا: ’’پھر قتل ہی کرے گا؟‘‘ اس نے کہا: جی ہاں۔ آپ نے فرمایا: ’’پھر اسے لےجا۔‘‘ جب وہ لے چلا تو آپ نے پھر اسے بلایا اور فرمایا: ’’معاف کرے گا؟‘‘ اس نے کہا: نہیں۔ آپ نے فرمایا: ’’پھر ضرور قتل ہی کرے گا؟‘‘ اس نے کہا: جی ہاں۔ اس وقت رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اگر تو اسے معاف کردے تو وہ اپنے گناہ اور تیرے مقتول کے گناہ کا ذمہ دار ہوگا۔‘‘ یہ سن کر اس نے اسے معاف کر دیا اور چھوڑ دیا۔ میں نے دیکھا، وہ اپنی تندی (رسی) کو اسی طرح گھسیٹتا ہوا جا رہا تھا۔","f2":"جو معاملات قابل معافی ہوں، ایسے معاملات میں معافی اور صلح کی ترغیب اچھی بات ہے کیوں کہ مافی یا صلح کی صورت میں آپس میں دشمنی ختم ہو جاتی ہے۔ محبت بڑھتی ہے۔ معاشرہ پر سکون ہو جاتا ہے۔ بدلہ لینااگرچہ جائز ہے مگر بسا اوقات بدلہ لینے کی صورت میں اشتعال پیدا ہوتا ہے۔ ناراضی اور دشمنی پیدا ہوتی ہے، اس لیے شریعت نے معافی کو بدلہ لینے سے افضل قرار دیا ہے بشرطیکہ فریق ثانی عجز کے ساتھ اپنی غلطی کا اعتراف کرے اور خلوص دل سے معافی طلب کرے۔ البتہ اگر وہ تکبر اور غرور کا مظاہرہ کرے تو بدلہ لینا افضل ہے تا کہ اس متکبر کا غرور ٹوٹے۔ حاکم کے لیے مناسب ہے کہ مذکورہ بالا قسم کے مقدمات میں مصالحت کی کوشش کرے۔ اگر نہ ہو سکے تو حق کا فیصلہ کرے۔ البتہ بعض معاشرتی جرائم قابل معافی نہیں ہوتے، مثلاًَ: چوری، زنا وغیرہ ایسے مقدمات عدالت تک پہنچیں تو فیصلہ لازم ہے۔ قتل پہلی قسم میں داخل ہے۔ (روایت سے متعلقہ مزید تفصیلات کے لیے دیکھے، احادیث: 4726، 4735)"}],[5416,"عبداللہ بن زبیر رضی اللہ عنہما بیان کرتے ہیں کہ انصار کے ایک شخص نے زبیر رضی اللہ عنہ سے حرہ کی نالیوں کے سلسلے میں جھگڑا کیا، (جن سے وہ باغ کی سینچائی کرتے تھے) اور مقدمہ رسول اللہ صلی اللہ علیہ وسلم کے پاس لے کر آئے، انصاری نے کہا: پانی کو بہتا چھوڑ دو، تو انہوں نے انکار کیا، ان دونوں نے رسول اللہ صلی اللہ علیہ وسلم کے پاس مقدمہ پیش کیا، تو آپ نے فرمایا: \"زبیر! سینچائی کر لو پھر پانی اپنے پڑوسی کے لیے چھوڑ دو\"، انصاری کو غصہ آ گیا، وہ بولا: اللہ کے رسول! وہ آپ کے پھوپھی زاد ہیں نا؟ یہ سن کر رسول اللہ صلی اللہ علیہ وسلم کے چہرے کا رنگ بدل گیا، پھر آپ نے فرمایا: \"زبیر! سینچائی کرو، اور پانی مینڈوں تک روک لو\"، زبیر رضی اللہ عنہ کہتے ہیں: میرا خیال ہے کہ یہ آیت: «فلا وربك لا يؤمنون» \"نہیں، تمہارے رب کی قسم! وہ مومن نہیں ہوں گے\" (النساء: ۶۵) اسی سلسلے میں اتری۔","الألباني: صحيح",{"u2":"سیدنا عبداللہ بن زبیر رضی اللہ عنہ نےبیان فرمایا کہ ایک انصاری صحابی رسول اللہ صلی اللہ علیہ وسلم کے ہاں سیدنا زبیر رضی اللہ عنہ سے حرہ کے نالے (کے پانی) کے بارے میں جھگڑے پڑے جووہ کھجور کے درختوں کولگاتے تھے۔ اس انصاری نےکہا کہ پانی آگے گزرنے دو۔ حضرت زبیر نےانکار کیا فریقین یہ جھگڑا رسول اللہ صلی اللہ علیہ وسلم کے پاس لے گئے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’زبیر‘تھوڑا تھوڑا پانی لگا لو۔ پھر اپںے پڑوسی کےلیے پانی چھوڑ دو۔انصاری نے غصے میں آکرکہا: اے اللہ کے رسول!یہ اس لیے کہ یہ آپ کی پھوپھی کا بیٹا ہے؟ رسول اللہ صلی اللہ علیہ وسلم کے چہرہ انور کا رنگ بدل گیا۔ پھر آپ نے فرمایا: زبیرّ پانی لگاو اور لگتا رہنے دو حتٰی کہ منڈیروں تک پہنچ جائے۔ ‘‘حضرت زبیر نے فرمایا: میرا خیال ہے کہ یہ آیت اسی بارے میں نازل ہوئی:’’آپ کےرب تعالی کی قسم!یہ لوگ مومن نہیں بن سکتے ........الخ‘","f2":"دیکھیے‘حدیث:5409"}],[5417,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ بریرہ رضی اللہ عنہا کے شوہر غلام تھے جنہیں مغیث کہا جاتا تھا، گویا میں اب بھی دیکھ رہا ہوں کہ وہ اس (بریرہ)کے پیچھے پیچھے روتے پھر رہے ہیں، اور ان کے آنسو ڈاڑھی پر بہہ رہے ہیں، نبی اکرم صلی اللہ علیہ وسلم نے عباس رضی اللہ عنہ سے کہا: عباس! کیا آپ کو حیرت نہیں ہے کہ مغیث بریرہ سے کتنی محبت کرتا ہے اور بریرہ مغیث سے کس قدر نفرت کرتی ہے؟، رسول اللہ صلی اللہ علیہ وسلم نے اس (بریرہ) سے فرمایا: \"اگر تم اس کے پاس واپس چلی جاتی (تو بہتر ہوتا) اس لیے کہ وہ تمہارے بچے کا باپ ہے\"، وہ بولیں: اللہ کے رسول! کیا مجھے آپ حکم دے رہے ہیں؟ آپ نے فرمایا: \"نہیں، میں تو سفارش کر رہا ہوں\"، وہ بولیں: پھر تو مجھے اس کی ضرورت نہیں ۱؎۔\n§وضاحت\n۱؎: مغیث اور بریرہ :(رضی اللہ عنہما ) کے معاملہ میں عدالتی قانونی فیصلہ تو آپ صلی اللہ علیہ وسلم نے یہی فرمایا کہ \" بریرہ رضی اللہ عنہا کو آزادی مل جانے کے بعد مغیث کے نکاح میں نہ رہنے کا حق حاصل ہے \" مگر اس عدالتی فیصلہ سے پہلے بریرہ رضی اللہ عنہا سے قانوناً نہیں اخلاقی طور پر مغیث کے نکاح میں باقی رہنے کی سفارش کی، یہی باب سے مناسبت ہے، اور اس طرح کی سفارش صرف ایسے ہی معاملات میں کی جا سکتی ہے، جس میں مدعی کو اختیار ہو :(جیسے بریرہ کا معاملہ اور قصاص ودیت والا معاملہ وغیرہ ) لیکن چوری و زنا کے حدود کے معاملے میں اس طرح کی سفارش نہیں کی جا سکتی۔","الألباني: صحيح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سےر وایت ہے کہ حضرت بریرہ ضی اللہ عنہا کاخاوند سیدنا مغیث رضی اللہ عنہ غلام تھا۔مجھے یوں محسوس ہوتاہےکہ میں اسے بریرہ کے پیچھے گھومتے ہوئے دیکھ رہا ہوں۔ وہ رہ رہا ہے اور اس کے آنسو اس کی ڈاڑھی پر گررہے ہیں۔نبئ اکرم صلی اللہ علیہ وسلم نے سیدنا عباس رضی اللہ عنہ سےفرمایا:’’عباس! آپ کو تعجب نہیں کہ مغیث کوبریرہ سے کس قدر محبت ہے اوربریرہ کو مغیث سے کس قدر نفرت ہے؟‘‘ رسول اللہ صلی اللہ علیہ وسلم نے بریرہ سے فرمایا:’’اگرتواپنےخاوند کوقبول کرلے (توبہتر ہے)۔ آخر وہ تیرے بچوں کا باپ ہے۔ ‘‘انھوں نے کہا: اللہ کے رسول!آپ حکم دیتے ہیں؟ آپ نے فرمایا:’’نہیں ‘میں نے توصرف سفارش کرتا ہوں۔‘‘انھوں نے کہا:پھر مجھے اس کی کوئی ضرورت نہیں۔","f2":"1۔ اگر کوئی فریق یا شخص کسی اہم راہنما یا حاکم وغیرہ کی سفارش قبول نہ کرے تو کوئی رحرج نہیں۔ سفارش کرنا مشروع ہے جبکہ سفارش قبول کرنا ضروری نہیں ‘لہذا سفارش کرنے والے شخص کوسفارش قبول نہ کرنے پرغصہ نہیں کرنا چاہیے اورنہ اسے کسی قسم کا کوئی اورنقصان ہی پہنچانا چاہیے۔\n2۔اس حدیث مبارکہ سے یہ بھی معلوم ہواکہ کسی کی درخواست کےبغیر ازخود بھی سفارش کرنا درست اور جائز ہے جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے سیدنا مغیث رضی اللہ عنہ کے مطالبہ سفارش کےبغیر ہی سیدہ بریرہ رضی اللہ عنہا سے سفارش فرمائی تھی۔ اور پھر ان کے سفارش قبول نہ کرنے پراظہار ناراضی قطعا نہیں فرمایا ‘البتہ اصلاح کی کوشش ضرور فرمائی ہے اور یہ مستحب ہے۔\n3۔یہ حدیث مبارکہ حضر ت بریرہ رضی اللہ عنہا کےاس حسن ادب کی طرف بھی اشارہ کرتی ہے جوان سے رسول اللہ صلی اللہ علیہ وسلم کی بابت صادر ہواکہ انھوں نے پوچھا: آپ حکم فرمارہے ہیں یا سفارش؟ نیز انھوں نے صراحتا آپ کی سفارش کورد نہیں کیابلکہ یہ کہ مجھے ان کی ضرورت نہیں۔\n4۔ کسی چیز کی حد سے زیادہ محبت حیا ختم کر دیتی ہے اور آدمی اندھا بہرا ہوجاتاہے۔\n5۔ جھگڑاکرنے والے‘خواہ میاں بیو ی ہوں یا کوئی اور ان کے مابین صلح کرانا اورجھگڑا ختم کرنے کی سفارش کرنا مستحب اورپسندیدہ شرعی عمل ہے نیز مومن کے دل کو مسرور کرنا اورقلبی مسرت وخوشی بہم پہنچانا بھی مستحب ہے۔\n6۔ یہ مسئلہ پہلے بیان ہوچکا ہے کہ لونڈی آزاد ہوجائے اوراس کا خاوند ابھی غلام ہوتواسے اختیار ہے نکاح قائم رکھے یاتوڑدے۔ یہاں یہی مسئلہ تھا۔ گویا ضروری نہیں حاکم فیصلہ ہی کرے بلکہ وہ کسی ایک فریق سے دوسرے کےحق میں سفارش کرکے مصالحت بھی کراسکتا ہے بلکہ یہ افضل ہے خصوصا جہاں ٹوٹ پھوٹ کامعاملہ ہو۔"}],[5418,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ انصار کے ایک شخص نے مدابرہ کے طور پر اپنا ایک غلام آزاد کر دیا، حالانکہ وہ ضرورت مند تھا اور اس پر قرض بھی تھا۔ تو رسول اللہ صلی اللہ علیہ وسلم نے اسے آٹھ سو درہم میں بیچ کر مال اسے دے دیا اور فرمایا: \"اپنا قرض ادا کرو اور اپنے بال بچوں پر خرچ کرو\"۔\n§وضاحت\n۱؎: مدابرہ یہ کہنا کہ میرے مرنے کے بعد تو آزاد ہے۔","الألباني: صحيح",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ نے فرمایا کہ ایک انصاری آدمی نے اپنا غلام مدبر کردیا جب کہ وہ خود محتاج تھا۔ اس کے ذمے قرض بھی تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے وہ غلام آٹھ سودرہم میں بیچ کر وہ رقم اس کو دے دی اور فرمایا:’’اپنا قرض اداکراوراپنے بال بچوں پرخرچ کر۔‘","f2":"1۔امام نسائی رحمتہ اللہ نےاس مقام پر جوعنوان قائم کیا ہے اس سے ان کا مقصد یہ مسئلہ بیان کرناہے کہ حاکم کویہ حق حاصل ہے کہ وہ محتاجوں اورضرورت مندوں کوان کے مال بیچنے یا اس طرح خیرات کرنےسے جیسا کہ مذکورہ صحابی نےکیاتھا روک دے نیز اسے یہ حق بھی حاصل ہے کہ وہ مالکان کے تصرف کوکالعدم قراردے کر خود ان کےمالوں میں تصرف کرے۔\n2۔ یہ حدیث مبارکہ اس بات پر بھی دلالت کرتی ہے کہ عام صدقہ خیرات کرنےسے ادائیگی قرض مقدم ہے کیونکہ عام صدقہ خیرات کرنا نفلی عبادت ہے جبکہ قرض کی ادائیگی فرض ہے۔ اگر نفلی عبادت نہیں کی جائے گی توزیادہ سےزیادہ یہ ہوگا کہ اجروثواب نہیں ملے گا‘بازپرس تونہیں ہوگی جبکہ قرض ادانہ کرنے کی صورت میں توجواب دہی کےساتھ ساتھ بازپرس بھی ہوگی۔ رسول اللہ صلی اللہ علیہ وسلم نےایسے شخص کی نماز جنازہ پڑھانے سے انکار فرمادیاتھا جس کےذمے قرض تھا اور ادائیگی کےلیے کچھ نہیں تھا۔\n3۔ مدبر کرنے کا مطلب یہ ہے کہ اس نےاس سے کہہ دیاکہ تومیرےمرنے کےبعد آزاد ہو گا۔ ظاہرہےکہ رسول اللہ صلی اللہ علیہ وسلم غلام کونہ بیچنے تووہ اس انصاری کےمرنے کے بعدآزاد ہوجاتا‘اس لیے آپ نےاسے بیچ دیا۔ معلوم ہوا صدقہ وہی صحیح ہے جو اپنی حاجت پوری کرنے اورقرض وغیرہ کی ادائیگی کےبعدہو ورنہ صدقہ رد کردیا جائے گا۔"}],[5419,"ابوامامہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو آدمی کسی مسلمان آدمی کا حق قسم کھا کر مار لے گا تو اللہ تعالی نے اس کے لیے جہنم واجب کر دے گا اور جنت اس پر حرام کر دے گا\"، ایک شخص نے آپ سے کہا: اگرچہ وہ معمولی سی چیز ہو؟ اللہ کے رسول! آپ نے فرمایا: \"گرچہ وہ پیلو کی ایک ڈال ہو\" ۱؎۔\n§وضاحت\n۱؎: جب جھوٹی قسم کھا کر پیلو کی ایک ڈال ہڑپ کر لینے پر اتنی سخت وعید ہے تو اتنی سی معمولی چیز کے بارے میں عدالتی فیصلہ بھی ہو سکتا ہے، یہی باب سے مناسبت ہے۔","الألباني: صحيح",{"u2":"سیدنا ابو امامہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فریایا:’’ جوشخص جھوٹی قسم کھا کر کسی مسلمان شخص کامال ناجائز حاصل کرلے‘اللہ تعالی اس پرآگ واجب اورجنت حرام کردیتا ہے۔‘‘ایک آدمی نےکہا:اے اللہ کے رسول!اگرچہ معمولی چیز ہو۔ آپ نے فرمایا:’’اگرچہ پیلو کی ٹہنی ہی ہو۔","f2":"1۔ باب کا مقصد یہ ہے کہ مال تھوڑا ہوزیادہ اس کی بابت فیصلہ کیا جاسکتاہے خواہ حاکم فیصلہ کرے یا عدالت۔ رسول اللہ صلی اللہ علیہ وسلم کایہ فرمانا کہ خواہ وہ پہلو کی ٹہنی ہی ہو ا اگر جھوٹی قسم ہے ہڑپ کیاگیا تواس پرجہنم واجب اورجنت حرام ہوجاتی ہے کیونکہ یہ ظالم ہے۔\n2۔ جھوٹی قسم کھانا کبیرہ گناہ ہے۔\n3۔ آگ واجب کردیتاہے یعنی ایک دفعہ تووہ لازما آگ میں جائےگااگرچہ بعد میں نکل آئے۔ جنت کےحرام ہونے سے مراد بہی جنت میں اولیں دخول کاحرام ہوناہے ورنہ ہرمومن کاجنت میں جانا قطعی ہے نیز یہ بھی تب ہے اگراسے معافی نہ ملے۔اگرمعافی مل جائے توپھریہ سزانہیں ہوگی۔"}],[5420,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ ہند رضی اللہ عنہا نے رسول اللہ صلی اللہ علیہ وسلم کے پاس آ کر کہا: اللہ کے رسول! ابوسفیان بخیل شخص ہیں، وہ مجھ پر اور میرے بچوں پر اس قدر نہیں خرچ کرتے ہیں جو کافی ہو، تو کیا میں ان کے مال میں سے کچھ لے لیا کروں اور انہیں پتا بھی نہ چلے؟ آپ نے فرمایا: \"بھلائی کے ساتھ اس قدر لے لو کہ تمہارے لیے اور تمہارے بچوں کے لیے کافی ہو\" ۱؎۔\n§وضاحت\n۱؎: اس غائب اور غیر موجود کو پہچانتا ہو، اور مدعی کی صداقت اور مدعی علیہ کے حالات سے گہری واقفیت رکھتا ہو جیسا کہ ہند اور ابوسفیان رضی اللہ عنہما کے معاملہ کی بابت آپ صلی اللہ علیہ وسلم جانتے تھے، ہر مدعی علیہ کے بارے میں اس طرح فیصلہ نہیں کیا جا سکتا، کیونکہ عام حالات میں مدعی کی گواہی یا قسم اور مدعا علیہ کے بیان سننے کی ضرورت ہے۔","الألباني: صحيح",{"u2":"سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں کہ حضرت ہند رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضرہوئی اورکہا:اےاللہ کے رسول!ابوسفیان کنجوس آدمی ہے۔ وہ نہ تو مجھے کافی اخراجات دیتاہےاورنہ میرےبچوں کےلیے۔ توکیامیں اس کے مال میں سے اس کے علم کےبغیر لےسکتی ہوں؟آپ نے فرمایا: تواتنالے سکتی ہےجوتجھےاورتیرےبچوں کومناسب اندازمیں کفایت کرے۔‘","f2":"1۔عنوان کامقصدیہ ہےکہ جس شخص کی بابت حاکم جانتاہوکہ یہ ایسا ہے اور اس کے متعلق کوئی مسئلہ پیش ہوجائے تواس کی عدم موجودگی میں بھی اس کے خلاف فیصلہ دیا جاسکتاہےجیسا کہ رسول اللہ صلی اللہ علیہ وسلم نےکیاکہ نہ توسیدنا ابوسفیان رضی اللہ عنہ کوبلایا اورنہ ان سے کچھ پوچھنا کیونکہ آپ ان کی بابت جانتےتھے۔\n2۔ کسی کی غیبت کرنا کبیرہ گناہ ہے تاہم بعض مواقع ایسے ہیں جہاں یہ شرعاًجائزہے۔امام نوی رحمتہ اللہ نےان کی تعداد چھ بیان کی ہے۔ وہ فرماتےہیں:شرعی ضرورت کی بنا پرکسی زندہ یامردہ شخص کی غیبت کرنا مباح ہے جبکہ اس کے بغیر چارہ کارنہ ہو:\nکسی منکر کوتیدیل کرنےیا کرانے کےلیےکسی کی مددواستعانت کی ضرورت ہویاکسی خطاکارکودرستی کی طرف لانا مقصود ہوتواس شخص کےسامنے جوازالہ منکر کی قدرت واختیار رکھتاہومعاملے کی توضیح کرنا جائز ہ اس وقت بھی مباح ہے۔\nکسی مفتی اورعالم سے فتوی لینے کےلیے اسے حقیقت حال سے باخبر کرنا مثلا یہ کہنا کہ فلاں شخص نے مجھ پریہ ظلم کیاہے اس نے مجھے میرے حق سےمحروم کردیا ہے وغیرہ یہ بھی حرام غیبت کی قسم سے نہیں بلکہ جائز ہے۔\nکسی ظالم کےظلم اوراس کے شرسے دیگر مسلمانوں کوبچانے کےلیے اس کےسیاہ کرتوتوں سےباخبر کرنا یا اہل اسلام کوان کی خیر خواہی کےپیش نظریہ بتانا کہ فلاں شخص میں یہ کمینہ پن ہے اوروہ اس اس طرح کی گھٹیا حرکتیں کرسکتاہے لہذا تمھیں اس سے محتاط اورہوشیارہنے کی ضرورت ہے۔ رواۃ حدیث پرجرح نیز کہیں رشتے ناتےکرنے والوں کواگلےاہل خانہ کی بابت مشورہ دینااوران کی کمزوریاں اورکوتاہیاں وغیرہ بیان کرنا اسی قبیل سےہے۔ اوریہ بالاتفاق جائز اورمباح بلکہ بوقت ضرورت واجب ہے۔\nپانچواں مقام جہاں غیبت کرنا شرعا مباح ہے یہ ہے کہ کوئی شخص سرعام فسق وفجورکاارتکاب کرتاہویا پکا بدعتی ہویا برسرعام شراب پینے والا اورجوا وغیرہ کھیلنے والا ہوتودیگر لوگوں کواس کے ان مذکورہ سیاہ کارناموں کی اطلاع دینا جائز ہے تاکہ وہ اپنےآپ کواس سے محفوظ رکھ سکیں۔\nچھٹا مقام یہ ہے کہ کوئی شخص کسی ایسے لقب یانام سےمعروف ہوجوظاہراًغیبت بنتا ہو مثلاً اعرج (لنگڑا) اعمش (کمزورنگاہ والا یعنی چوندھا) اعمی (اندھا) احول(بھینگا) وغیرہ تواسے بلانا بشرطیکہ تنقیص کی نیت نہ ہوتو جائز ہےورنہ حرام ہے۔ واللہ اعلم۔\n3۔قاضی اورحاکم کےلیے باہم جھگڑے والوں کادرست فیصلہ کرنے کےلیے فریق مخالف سےدوسرے کی غیبت سننا مباح ہے جیسا کہ ذکر ہوچکا۔\n4۔اس حدیث مبارکہ سے یہ اہم مسئلہ بھی ثابت ہواکہ مرد کےلیے کسی اجنبی اورغیرمحرم عورت کی آواز بوقت ضررت سننا جائز ہے۔\n5۔ اس حدیث مبارکہ سےیہ بھی معلوم ہواکہ بیوی اوربچوں کاخرچہ خاوند اورباپ کے ذمے ہے۔ اکثر اہل علم کا قول ہے کہ ہ اسی قدرواجب ہے جس قدر بیوی بچوں کی جائز ضرورت ہو نیز یہ بھی معلو ہوا کہ شریعت نے جب امور کی تجدید نہیں کی ان میں عرف کالحاظ کیاجائے۔\n6۔ مناسب انداز میں یعنی تمھاری سماجی حثیت کےلحاظ سےاوریہ حیثیت بدلتی رہتی ہے۔ امیر گھرانے میں اخراجات کی حیثیت اورہوتی ہے اورغریب گھرانے میں اور۔"}],[5421,"عبدالرحمٰن بن ابوبکرہ (سجستان کے گورنر تھے) کہتے ہیں کہ مجھے ابوبکرہ رضی اللہ عنہ نے لکھ بھیجا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا ہے:\"کوئی ایک قضیہ میں دو فیصلے نہ کرے ۱؎، اور نہ کوئی دو فریقوں کے درمیان غصے کی حالت میں فیصلہ کرے\"۔\n§وضاحت\n۱؎: کیونکہ قضاء کا مقدمہ جھگڑے کو ختم کرنا ہے، اور ایک ہی معاملہ میں دو طرح کے فیصلے سے جھگڑا ختم نہیں ہوتا۔","الألباني: صحيح",{"u2":"حضرت عبدالرحمن بن ابوبکرہ جوکہ سجستان کےحاکم تھے نےبیان کیاکہ (میرے والد محرم) سیدنا ابوبکرہ رضی اللہ عنہ نےمجھے لکھاکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کوفرمانےسنا:کوئی شخص ایک مقدمے میں دومختلف نہ کرے۔ اورکوئی شخص فریقین کےدرمیان غصے کی حالت میں فیصلہ نہ کرے۔‘","f2":"ایک ہی مقدمےیاایک جیسے دومقدمات میں مختلف فیصلے کرنا قاضی کی ساکھ کوختم کردیتاہے نیز اس سے لوگوں میں جھگڑے اوراختلاف بڑھیں گے جب کہ فیصلہ توانھیں ختم کرنے کےلیے کیاجاتاہے۔"}],[5422,"ام المؤمنین ام سلمہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم لوگ میرے پاس جھگڑے لے کر آتے ہو، حالانکہ میں ایک انسان ہوں، اور ممکن ہے کہ تم میں سے کوئی دوسرے سے دلیل دینے میں چرب زبان ہو۔ میں تو صرف اس کی بنیاد پر فیصلہ کرتا ہوں جو میں سنتا ہوں، اب اگر میں کسی کو اس کے بھائی کا کوئی حق دلا دوں (اور وہ حقیقت میں اس کا نہ ہو) تو گویا میں اس کو جہنم کا ٹکڑا دلا رہا ہوں\"۔\n§وضاحت\n۱؎: تو کیا وہ پانے والے کے لیے ہر حال میں حلال ہو گا ؟ نہیں، خود جب نبی اکرم صلی اللہ علیہ وسلم کے فیصلے پر ملنے سے حلال نہیں ہو سکتا، :(اگر حقیقت میں اس کا نہ ہو ) تو دوسرے کسی قاضی کے فیصلے سے کیسے جائز ہو سکتا ہے، اس لیے اس طرح کے معاملے میں سخت محتاط رہنے کی ضرورت ہے، جھگڑے کو ختم کرنے کے لیے تو یہ فیصلہ ٹھیک ہے، لیکن اس طرح کے فیصلے حرام کو حلال، اور حلال کو حرام نہیں کر سکتے، اسی لیے نبی اکرم صلی اللہ علیہ وسلم نے خود اپنے فیصلے پر یہ عرض کیا کہ حقیقت میں غلط فیصلہ پر عمل آدمی کو جہنم پہنچا سکتا ہے۔","الألباني: صحيح",{"u2":"سیدہ ام سلمہ رضی اللہ عنہا سےروایت ہے وہ بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’تم میرے پاس جھگڑے لاتے ہو۔میں تو بس ایک انسان ہی ہوں۔ممکن ہے کہ تم میں سے کوئی شخص اپنی دلیل کو دوسرےشخص سے زیادہ واضح طور پربیان کرنے والاہو۔میں تو تمھارے درمیان دلائل سن کر (ان کے مطابق) فیصلہ کر دوں گا۔(لیکن یاد رکھو!)میں جس شخص کے لیے اس کے (اسلامی)بھائی کے حق میں سے کسی چیز کا فیصلہ کر دوں تو درحقیقت میں اسے آگ کا ٹکڑا کاٹ کر دے رہا ہوں۔‘‘","f2":"قاضی کا فیصلہ حرام کو حلال نہیں کر سکتا۔جمہور اہل علم کا یہی مسلک ہے۔ احناف اس روایت کواموال کے ساتھ خاص کرتے ہیں۔ان کے خیال میں گو یا عقود‘ مثلا:بیع ‘نکاح‘ طلاق وغیرہ قاضی کے فیصلے سے مفقود ہو جائیں گے لیکن یہ بات بلا دلیل ہے۔عقود کے لیے فریقین کی رضامندی ضروری ہے نہ کہ قاضی کا فیصلہ (مزید دیکھیے حدیث:5403)"}],[5423,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی کو سب سے زیادہ بغض و نفرت لڑاکے اور جھگڑالو شخص سے ہے\" ۱؎۔\n§وضاحت\n۱؎: مراد: باطل کے لیے جھگڑا کرنے والا اور چرب زبانی کرنے والا ہے۔","الألباني: صحيح",{"u2":"سیدہ عائشہ رضی اللہ عنھا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:اللہ تعالیٰ کے نزدیک سب سے ناپسندیدہ اور قابل نفرت شخص وہ ہے جو ضدی اور جھگڑالو ہے۔‘","f2":"اس سے وہ شخص مراد ہے جو ہر وقت جھگڑتا رہتا ہے ‘باطل اور جھوٹ پر ہونے کے باوجود ضد اور جھگڑا نہیں چھوڑتا ‘نیز مخالفت حق میں ہر شخص اور ہر بات پر جھگڑتا ہے۔واللہ اعلم"}],[5424,"ابوموسی اشعری رضی اللہ عنہ سے روایت ہے کہ دو لوگ ایک جانور کے بارے میں جھگڑا لے کر نبی اکرم صلی اللہ علیہ وسلم کے پاس پہنچے، ان میں سے کسی کے پاس کوئی گواہ نہ تھا، تو آپ نے اس کے آدھا کیے جانے کا فیصلہ کیا۔","الألباني: ضعيف",{"u2":"سیدنا ابو موسیٰ رضی اللہ عنہ سے روایت ہے کہ دو آدمی نبی اکرم صلی اللہ علیہ وسلم کے پاس ایک جانور کے بارے میں جھگڑتے ہوئے آئے۔دلیل کسی کے پاس بھی نہیں تھی۔آپ نے دونوں کو نصف نصف دے دیا۔","f2":"’’دلیل ‘‘مثلا:گواہ یا دستاویز وغیرہ۔ اسی طرح قبضہ بھی کسی کا نہیں تھا یا دونوں کا قبضہ تھا۔قرائن بھی کسی ایک جانب کو ترجیح نہیں دیتے تھے۔ایسی صورت میں یہی فیصلہ ہو گا یا پھر قرعہ اندازی کی جائے گی جس پربھی فریقین راضی ہو جائیں یا جسے قاضی مناسب خیال کرے۔"}],[5425,"ابن ابی ملیکہ کہتے ہیں کہ دو لڑکیاں طائف میں موزے (خف) بنایا کرتی تھیں، ان میں سے ایک باہر نکلی، تو اس کے ہاتھ سے خون نکل رہا تھا، اس نے بتایا کہ اس کی سہیلی نے اسے زخمی کیا ہے، لیکن دوسری نے انکار کیا، تو میں نے اس سلسلے میں ابن عباس رضی اللہ عنہما کو لکھا تو انہوں نے جواب لکھا کہ رسول اللہ صلی اللہ علیہ وسلم نے فیصلہ کیا کہ قسم تو مدعا علیہ سے لی جائے گی، اگر لوگوں کو ان کے دعوے کے مطابق (فیصلہ) مل جایا کرے تو بعض لوگ دوسرے لوگوں کے مال اور ان کی جان کا بھی دعوی کر بیٹھیں، اس لیے اس عورت کو بلا کر اس کے سامنے یہ آیت پڑھو: «إن الذين يشترون بعهد اللہ وأيمانهم ثمنا قليلا أولئك لا خلاق لهم في الآخرة» \"جو لوگ اللہ کے عہد اور قسموں کو معمولی قیمت سے بیچ دیتے ہیں، ان کے لیے آخرت میں کوئی حصہ نہیں\" (آل عمران: ۷۷) یہاں تک کہ آیت ختم کی، چنانچہ میں نے اسے بلایا اور یہ آیت اس کے سامنے تلاوت کی تو اس نے اس کا اعتراف کیا، جب انہیں (ابن عباس کو) یہ بات معلوم ہوئی تو خوش ہوئے۔\n§وضاحت\n۱؎: یعنی: کسی معاملہ میں قسم کی ضرورت پڑے تو پہلے حاکم جس سے قسم لے اس کو نصیحت کرے۔","الألباني: صحيح",{"u2":"حضرت ابن ابی ملیکہ بیان کرتے ہیں کہ دو لڑکیاں طائف کے علاقے میں کچھ سلائی کر رہی تھیں۔ان سے ایک نکلی تو کے ہاتھ سے خون بہہ رہا تھا۔اس نے کہا کہ میرےساتھ والی لڑکی نے اسے زخم لگایاہے جبکہ دوسری نے انکار کر دیا۔میں نےاس بارےمیں سیدنا ابن عباس رضی اللہ عنہ کی طرف لکھا تو انھوں نے (جوابًا)تحریر فرمایا کہ رسول صلی اللہ علیہ وسلم کا فیصلہ ہے کہ مد عی علیہ کے ذمے ہو گی۔اگرلوگوں کو صرف ان کے دعوے کی بنا پران کی مطلوبہ دے دی جاتی تو لوگ دوسرے لوگوں کے جان ومال کی بابت دعوے کر دیتے۔اس لڑکی کو بلاؤاور اس کو یہ آیت پڑھ کرسناؤ:’’بلا شبہ جو لوگ اللہ تعالیٰ کا عہداور اپنی قسمیں تھوڑی قیمت کے بدلے بیچ ڈالتے ہیں ان کا آخرت میں کوئی حصہ نہیں ہو گا ....الخ.میں نے اس لڑکی کو بلایا اور یہ آیت پڑھ کر سنائی۔اس نے اعتراف کر لیا۔سیدنا ابن عباس رضی اللہ عنہ کو یہ بات پہنچی تو بہت خوش ہوئے۔","f2":"یہ قطعی بات ہے کہ مدعی سے اس کے دعوے کا ثبوت طلب کیا جاے گا۔اگر ثبوت ‘یعنی کوئی دستاویز یا گواہ مل جائے تو وہ چیز مدعی کو دے دی جائے گی۔اگر مدعی دلیل پیش نہ سکے تو پھر مدعی علیہ سے پوچھا جائے گا۔ اگر وہ (مدعی علیہ) مدعی کے دعوے کا منکر ہو تو اس سے قسم لی جائے گی۔قسم کھا لے تو مدعی کو کچھ نہیں ملے گا۔ اگر قسم نہ کھائے تو پھر مدعی سے قسم لے کر چیز اسے دے دی جائے گی اسے یمین نکول کہتے ہیں۔واللہ اعلم"}],[5426,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ معاویہ رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم اپنے صحابہ کے حلقے کی طرف نکل کر آئے اور فرمایا: \"کیوں بیٹھے ہو؟\" وہ بولے: ہم بیٹھے ہیں، اللہ سے دعا کر رہے ہیں، اس کا شکر ادا کر رہے ہیں کہ اس نے ہمیں اپنے دین کی ہدایت بخشی اور آپ کے ذریعے ہم پر احسان فرمایا، آپ نے فرمایا: \"اللہ کی قسم! ۲؎ تم اسی لیے بیٹھے ہو؟\" وہ بولے: اللہ کی قسم! ہم اسی لیے بیٹھے ہیں، آپ نے فرمایا: \"سنو، میں نے تم سے قسم اس لیے نہیں لی کہ تمہیں جھوٹا سمجھا، بلکہ میرے پاس جبرائیل آئے اور مجھے بتایا کہ اللہ تعالی اپنے فرشتوں پر تمہاری وجہ سے فخر کرتا ہے\"۔\n§وضاحت\n۱؎: یعنی جب کسی معاملہ میں قاضی کو قسم لینے کی ضرورت ہو تو کن الفاظ کے ساتھ قسم لے۔ ۲؎: اسی لفظ میں باب سے مناسبت ہے، یعنی آپ صلی اللہ علیہ وسلم لفظ «واللہ» سے قسم کھایا یا لیا کرتے تھے۔","الألباني: صحيح",{"u2":"سیدنا ابوسعیدخدری رضی اللہ عنہ سے روایت ہے کہ سیدنا معاویہ رضی اللہ عنہ نے فرمایا:رسول اللہ صلی اللہ علیہ وسلم اپنے صحابہ کے ایک حلقے پر تشریف لائے اور فرمایا:’’کیسے بیٹھے ہو؟‘‘انھوں نے کہا کہ ہم بیٹھےاللہ تعالیٰ سے دعائیں کر رہے ہیں اور اس کی تعریف کررہے ہیں کہ اس نے ہمیں اپنے دین کی رہنمائی فرمائی اور آپ کو بھیج کرہم پرعظیم احسان فرمایا۔آپ نے فرمایا:’’ کیا اللہ کی قسم!تم صرف اسی لیے بیٹھے ہو؟‘‘انھوں نے کہا:جی ہاں۔ اللہ کی قسم!ہم صرف اسی لیے بیٹھے ہیں۔آپ نے فرمایا:’’میں نے تم سے کسی شک و الزام وغیرہ کی بنا پر قسم نہیں لی بلکہ بات یہ ہے کہ جبریل علیہ السلام میرے پاس آئے اور مجھے بتایا کہ اللہ تعالیٰ تمھاری وجہ سے فرشتوں کے سامنے فخر فرما رہا ہے(کہ یہ میری مخلوق ہے)۔‘","f2":"1۔امام نسائی رحمہ اللہ نے جو باب قائم کیا ہے اس کا مقصد قسم اٹھوانے کی کیفیت بیان کرنا ہے کہ قسم کن الفاظ سے اٹھوائی جائے گی۔(2)اللہ تعالیٰ کی حمدوثنا اور عظمت و بزرگی بیان کرنے کے لیے مسجد انتہائی موزوں ومناسب جگہ ہوتی ہے۔وہاں نہ تو خریدو فروخت جائز ہے اور نہ دیگر عام گپ شپ لگانا ہی درست ہے بلکہ وہاں اللہ کاذکر اور اس کی تسبیح و تحمیدہی کی جانی مشروع ہے۔ انسان کو وہاں بیٹھ کر اللہ تعالیٰ کے انعامات و احسانات یاد کر کے اس کا شکر ادا کرنا چاہیے۔(3)مومن کی شان یہ ہے کہ وہ اللہ تعالیٰ کا شکر گزار بن کر رہے ‘ایک تو اس لیے کہ اللہ تعالیٰ نے اسے اسلام کی ہدایت عطا فرمائی اور دوسرا اس لیے کہ اسے محمد رسول اللہ صلی اللہ علیہ وسلم کا امتی بنایا۔اہل ایمان کے لیے اس سے بڑی عظمت اور اس سے بڑھ کر فخر کی اور کیا بات ہو سکتی ہے کہ وہ (کنتم خیر امۃ)(اٰل عمران3:110) اور (جعلنٰکم امۃ وسطا)البقرہ2:143) کا مصداق قرار پائے۔(4)درس تدریس اور وعظ وذکر کی مجالس یقینًانہایت پسندیدہ ہیں۔اللہ تعالیٰ ایسے لوگوں پر فخر کرتا ہے بدعی اور شرکیہ مجالس اس کے برعکس اللہ کی ناراضی کا باعث ہوں گی۔(5)آپ کا مقصود یہ ہے کہ میں نے تمھارے فعل کی اہمیت کے پیش نظر تم سے قسم لی ہے ‘نہ کہ شک و شبہ کی بنا پر۔(6) حدیث سے معلوم ہوا کہ اللہ تعالیٰ کے نام کی قسم لینی چاہیے اور صرف اتنا کافی ہے۔ بعض لوگ قسم کے الفاظ میں تغلیظ کے قائل ہیں ‘یعنی کہ ساتھ اللہ تعالیٰ کے اوصاف بھی ملائے جائیں تا کہ قسم کی عظمت جاگزین ہو جائے اور قسم کھانےوالا جھوٹی قسم نہ کھائے۔ ظاہر ہے اس میں کوئی حرج نہیں بلکہ یہ بھی وعظ کے قائم مقام ہے۔"}],[5427,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"عیسی بن مریم علیہ السلام نے ایک شخص کو چوری کرتے دیکھا، تو اس سے پوچھا: کیا تم نے چوری کی؟ وہ بولا: نہیں، اس اللہ کی قسم جس کے سوا کوئی حقیقی معبود نہیں ۱؎، عیسی علیہ السلام نے کہا: میں نے یقین کیا اللہ پر اور جھوٹا سمجھا اپنی آنکھ کو۔\nكتاب الاستعاذة\n§وضاحت\n۱؎: اس حدیث میں یہی قسم کے الفاظ ہیں، ان الفاظ کے ساتھ بھی کبھی کبھی رسول اللہ صلی اللہ علیہ وسلم قسم کھایا یا لیا کرتے تھے، دونوں حدیثوں میں مذکور دونوں الفاظ کے علاوہ بھی کچھ الفاظ کے ذریعہ آپ صلی اللہ علیہ وسلم قسم کھایا یا کرتے تھے جیسے «لا ومصرف القلوب»، «لا ومقلب القلوب»وغیرہ۔","الألباني: صحيح",{"u2":"سیدنا ابوھریرہ رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:حضرت عیسیٰ بن مریم علیہ السلام نے ایک آدمی کو چوری کرتے ہوئے دیکھا تو آپ نےفرمایا:اوے! تو چوری کرتا ہے!اس نے کہا نہیں۔ قسم اس اللہ کی جس کے سوا کوئی معبود نہیں!حضرت عیسیٰ علیہ السلام نے فرمایا:میں اللہ (کی قسم)پر ایمان لاتا ہوں اور اپنی آنکھ (کی دیکھی ہوئی چیز)کو جھٹلاتا ہوں۔‘","f2":"(1)’’جھٹلاتا ہوں‘‘مقصد یہ ہے جب کسی سے قسم لی جائے تو اس کی قسم مان لینی چاہیے۔ اپنی بات پر نہیں اڑنا چاہیے۔کوئی جھوٹی کھائے گا تو خود بھگتے گا۔مذکورہ واقعہ میں ممکن ہے وہ اپنی ہی چیز اٹھا رہا ہو یا دوسرے کی چیز اس کی اجازت سے اٹھا رہا ہو۔یا صرف چیز پکڑ کر دیکھنا مقصد ہو نہ کہ اٹھا کر لے جانا وغیرہ۔ایسے كئ احتمالات ہوسکتے ہیں۔گویا ظاہر دیکھنے میں چوری کی صورت تھی۔قسم سے حقیقت واضح ہو گئ۔(یہ سب کچھ تب ہے اگر وہ اپنی قسم میں سچا تھا۔)چور نے اللہ کے نام کی قسم کھا کر اپنی براءت کا اظہار کیا ‘اس لیے سیدناعیسیٰ علیہ السلام نے اللہ تعالیٰ کے نام کی لاج رکھتے ہوئے اسے سچا سمجھااور اپنی آ نکھ کو جھوٹا قراردیا۔واللہ اعلم.(2)ہر جگہ عیسیٰ علیہ السلام کو عیسیٰ ابن مریم کہنا دلیل ہے کہ وہ بن باپ کے پیدا ہوئے تا کہ لوگوں کے لیے اپنے صدق پر معجزہ بنیں-(3)حدیث میں قسم مؤ کدومغلظ ہے۔گویا ایسی قسم بھی لی جا سکتی ہے۔"}],[5428,"عبداللہ بن خبیب رضی اللہ عنہ کہتے ہیں کہ اندھیرے کے ساتھ بارش ہوئی تو ہم نے رسول اللہ صلی اللہ علیہ وسلم کا نماز پڑھانے کے لیے انتظار کیا، پھر کچھ کہا جس کا مفہوم یہ تھا کہ رسول اللہ صلی اللہ علیہ وسلم ہمیں نماز پڑھانے کے لیے نکلے تو آپ نے فرمایا: \"کچھ کہو\"، میں نے کہا: کیا کہوں؟ آپ نے فرمایا: «قل هو اللہ أحد» اور \"معوذتین\" (سورۃ الفلق اور سورۃ الناس) صبح و شام تین بار پڑھ لیا کرو، یہ (سورتیں) تمہارے لیے ہر تکلیف و مصیبت میں کافی ہوں گی۔","الألباني: حسن",{"u2":"سیدنا عبداللہ رضی اللہ عنہ سے مروی ہے کہ ایک رات ہلکی سی بارش ہوئی۔سخت اندھیراتھا۔ہم انتظار میں تھے کہ رسول اللہ صلی اللہ علیہ وسلم تشریف لائیں اور نماز پڑھائیں۔پھر رسول اللہ صلی اللہ علیہ وسلم نماز کے لیے تشریف لائے اور (مجھے)فرمایا:’’ پڑھ‘‘میں نے کہا:کیا پڑھوں؟آپ نے فرمایا:‘‘(قل ھو اللہ احد)اور معوذتین صبح وشام تین تین دفعہ پڑھا کر۔تجھے ہر مصیبت میں کفایت کریں گی۔‘","f2":":(1)امام نسائی رحمہ اللہ نے جو عنوان قائم کیا ہے اس کا مقصداستعاذے کی مشروعیت بیان کرنا ہے۔(2)یہ حدیث مبارکہ ان مذکورہ تینوں سورتوں ‘یعنی سورہ اخلاص‘سورہ فلق ‘اور سورہ ناس کی فضیلت کی واضح دلیل ہے ‘نیز یہ حدیث اس بات کی دلیل ہے کہ معوذتین‘یعنی (قل اعوذبدب الفلق)اور (قل اعوذبدب الناس)قرآن کریم کی سورتیں اور اس کا حصہ ہیں۔یہ محض استعاذے کی دعائیں نہیں۔مزید برآں امت کا اس بات پر اجماع ہے کہ ان صورتوں کے ابتدا میں جو لفظ(قل)وارد ہے ‘یہ قرآن ہی کا لفظ ہے اور متواتر ثابت ہے اور اس کا مقام بسم اللہ الرحمٰن الرحم کے بعدہے۔(2)ہر مصیبت سے ‘‘یعنی جن سے پناہ ممکن ہے ورنہ موت وغیرہ سےبچاؤتو ممکن نہیں‘البتہ ہر چیز کے شر سے بچاؤحاصل ہو گا ‘مثلاًبری موت سے۔ واللہ اعلم"}],[5429,"عبداللہ بن خبیب رضی اللہ عنہ کہتے ہیں کہ میں مکہ کے راستے میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھا، آپ کو اکیلا پا کر جب میں آپ سے قریب ہوا تو آپ نے فرمایا: \"کچھ کہو\"، میں نے کہا: کیا کہوں؟ آپ نے فرمایا: \"کچھ کہو\"، میں نے کہا: کیا کہوں؟ آپ نے فرمایا: «قل أعوذ برب الفلق» یہاں تک کہ آپ نے پوری سورت پڑھی، پھر فرمایا: «قل أعوذ برب الناس» یہاں تک کہ اسے بھی پوری پڑھی پھر فرمایا: ان دونوں سے بہتر لوگوں نے کسی اور چیز کے ذریعہ پناہ نہیں مانگی۔","الألباني: صحيح الإسناد",{"u2":"سیدنا عبداللہ بن خبیب رضی اللہ عنہ نے فرمایا کہ میں مکہ مکرمہ کے راستے ہوئی تو میں آپ کے قریب ہو گیا۔آپ نے فرمایا ’’پڑھ‘‘میں نے عرض کی:کیا پڑھوں؟آپ نے فرمایا:تو(قل اعوذ برب الفلق)آخرسورۂ تک پڑھا کر۔پھر سورہ ٔ(قل اعوذبرب الناس)آخرسورۂ تک پڑھا کر۔پھر فرمایا:’’کسی انسان نے ان دو سورتوں سے افضل کلام کے ساتھ اللہ تعالیٰ کی پناہ حاصل نہیں کی۔","f2":"’’پناہ حاصل نہیں کی‘‘مطلب یہ ہے کہ پناہ حاصل کرنے کے سلسلے میں یہ دو سورتیں سب سے افضل ہیں کیونکہ ان کو اتارا ہی اس مقصد کے لیے گیا ہے۔ دوسرے مقاصد کے لیے کوئی اور سورتیں بھی افضل ہو سکتی ہیں۔"}],[5430,"عقبہ بن عامر جہنی کہتے ہیں کہ ایک مرتبہ جب ایک غزوہ میں، میں رسول اللہ صلی اللہ علیہ وسلم کی اونٹنی کی نکیل پکڑے آگے آگے چل رہا تھا تو اس وقت آپ نے فرمایا: \"عقبہ! کہو\"، میں آپ کی طرف متوجہ ہوا، پھر آپ نے فرمایا: \"عقبہ! کہو\"، میں پھر متوجہ ہوا۔ پھر آپ نے تیسری بار فرمایا تو میں نے عرض کیا: کیا کہوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: «قل هو اللہ أحد» پھر پوری سورت پڑھی، اس کے بعد «قل أعوذ برب الفلق» پوری پڑھی، میں نے بھی آپ کے ساتھ پڑھی، پھر آپ نے «قل أعوذ برب الناس» پوری پڑھی اور میں نے بھی آپ کے ساتھ پڑھی، اور فرمایا: \"ان جیسی کسی اور چیز کے ذریعہ کسی نے پناہ نہیں مانگی\" ۱؎۔\n§وضاحت\n۱؎: یعنی: پناہ طلب کرنے کے لیے ان دو سورتوں سے بڑھ کر کوئی اور ذکر یا دعا نہیں ہے۔","الألباني: صحيح",{"u2":"سیدنا عقبہ بن عامر جہنی رضی اللہ عنہ سے روایت ہے ‘انھوں نے فرمایا:ایک دفعہ میں ایک جنگی سفر میں آپ کی سواری کی مہار پکڑآگے آگے چل رہا تھا کہ آپ نے فرمایا:’’اے عقبہ پڑھ۔‘‘میں نے آپ کی طرف کان لگایا(تاکہ آپ جو فرمائیں‘وہ میں سن کر پڑھوں۔)پھر کچھ دیر کے بعد فرمایا:’’اے عقبہ!پڑھ۔‘‘میں پھر متوجہ ہوا۔آپ نے تیسری مرتبہ پھر یہی فرمایا۔میں نے عرض کی:کیا پڑھوں؟آپ نے فرمایا:سورۂ(قل ھو اللہ احد)‘‘پھر آپ نے آخر تک سورت پڑھی۔پھر آپ نے سورۂ(قل اعوذ برب الفلق)آخر تک پڑھی۔میں بھی آپ کے ساتھ پڑھتا رہا۔پھر آپ نے سورۂ(قل اعوذ برب الناس)آخر تک پڑھی۔میں بھی آپ کے ساتھ پڑھتا رہا۔پھر آپ نے فرمایا:’’کسی شخص نے ان جیسی سورتوں یا کلام کے ساتھ اللہ تعالیٰ کی پناہ حاصل نہیں کی۔‘‘","f2":"یعنی کوئی اور سورت یا کلام پناہ حاصل کر نے کے سلسلے میں ان کے برابر نہیں چہ جائکہ افضل ہو۔"}],[5431,"عقبہ بن عامر جہنی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا: \"پڑھو\"، میں نے کہا: کیا پڑھوں؟ آپ نے فرمایا: \"پڑھو «قل هو اللہ أحد»، «قل أعوذ برب الفلق»، «قل أعوذ برب الناس» \" پھر رسول اللہ صلی اللہ علیہ وسلم نے انہیں پڑھا اور فرمایا: \"لوگوں نے ان جیسی کسی اور چیز کے ذریعہ پناہ نہیں مانگی\"، یا فرمایا: \"لوگ نہیں مانگتے ان جیسی کسی اور چیز کے ذریعہ پناہ\"۔","الألباني: صحيح",{"u2":"سیدنا عقبہ بن عامر جہنی رضی اللہ عنہ سےروایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے فرمایا:پڑھ۔‘‘میں نے عرض کی:کیا پڑھوں؟آپ نے فرمایا:’’قل ھواللہ احد)‘(قل اعوذ برب الفلق اور قل اعوذبرب الناس)‘‘پھر آپ نے یہ سورتیں پڑھیں اور فرمایا:’’لوگوں نے ان جیسی سورتوں کے ساتھاللہ تعالیٰ کی پناہ حاصل نہیں کی یا لوگ ان جیسی سورتوں کے ساتھ پناہ حاصل نہیں کریں گے۔‘"}],[5432,"ابن عابس جہنی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"ابن عابس! کیا میں تمہیں نہ بتاؤں؟\" یا کہا: \"کیا میں تمہیں خبر نہ دوں سب سے بہتر پناہ کی جس کے ذریعہ پناہ مانگنے والے پناہ مانگیں؟\" انہوں نے کہا: کیوں نہیں؟ اللہ کے رسول! آپ نے فرمایا: «قل أعوذ برب الفلق» اور«قل أعوذ برب الناس» یہ دونوں سورتیں (پناہ مانگنے کے لیے سب سے بہتر ہیں)۔","الألباني: صحيح",{"u2":"سیدنا ابن عابس جہنی رضی اللہ عنہ نے بتلایاکہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے فرمایا:’’اے ابن عابس!کیا میں تجھے وہ افضل کلام نہ بتلاؤں جس کے ساتھ پناہ حاصل کرنے والے اللہ تعالیٰ کی پناہ حاصل کر سکتے ہیں؟‘‘میں نے کہا:اے اللہ کے رسول!کیوں نہیں؟ضرور۔آپ نے فرمایا:’’(قل اعوذ برب الفلق)(قل اعوذبرب الناس)یہ دو سورتیں۔‘‘"}],[5433,"عقبہ بن عامر رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کے پاس ایک سفید اونٹنی تحفے میں آئی۔ آپ اس پر سوار ہوئے اور میں نے اس کی نکیل پکڑ کر چلنا شروع کیا، پھر رسول اللہ صلی اللہ علیہ وسلم نے عقبہ سے فرمایا: \"پڑھو\"، وہ بولے: اللہ کے رسول! کیا پڑھوں؟ آپ نے فرمایا: \"پڑھو « قل أعوذ برب الفلق * من شر ما خلق» آپ نے اسے دہرایا یہاں تک کہ میں نے بھی اسے پڑھا، پھر آپ نے جان لیا کہ میں اس سے کچھ زیادہ خوش نہیں ہوا۔ (چنانچہ) آپ نے فرمایا: شاید تم نے اسے بہت ہلکا سمجھا۔ لیکن مجھے (پناہ مانگنے کے لیے) اس جیسی سورۃ نہیں ملی۔","الألباني: صحيح الإسناد",{"u2":"سیدنا عقبہ بن عامر رضی اللہ عنہ نے فرمایا کہ نبئ اکرم صلی اللہ علیہ وسلم کو ایک سفیدخچر بطورتحفہ پیش کیا گیا۔آپ اس پر سوار ہوئے اور عقبہ اس کی لگام پکڑکر آگے آگے چلنے لگا۔رسول اللہ صلی اللہ علیہ وسلم نے عقبہ سے فرمایا:’’پڑھ۔‘‘اس نے عرض کیا: اے اللہ کے رسول!کیا پڑھوں؟آپ نے فرمایا:’’پڑھ(قل اعوذبرب الفلق۔من شرماخلق)‘‘آپ نے مجھ پر پوری سورت پڑھی حتٰی کہ میں نے بھی پڑھی۔آپ نے محسوس فرمایا کہ میں اس کے ساتھ زیادہ خوش نہیں ہوا۔آپ نے فرمایا:’’شاید تو نے اس کو معمولی سمجھا ہے۔میں نے کبھی نماز میں اس جیسی سورت نہیں پڑھی۔‘","f2":"یعنی استعاذے کے سلسلے میں یہ سب افضل ہے کیونکہ یہ انتہائی جامع ہے اور اس میں ہر قسم کاشر ذکر کر کے اس سے اللہ تعالیٰ کی پناہ حاصل کی گئی ہے۔"}],[5434,"عقبہ بن عامر رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے معوذتین کے بارے میں پوچھا، تو آپ صلی اللہ علیہ وسلم نے فجر میں یہی دونوں سورتیں ہمیں پڑھائیں ۱؎۔\n§وضاحت\n۱؎: اس وقت خاص طور پر ان دونوں سورتوں کی اہمیت بتانے کے لیے آپ نے نماز انہیں دونوں سورتوں سے پڑھائی، فجر کی نماز میں جہاں آپ بڑی بڑی سورتیں پڑھا کرتے تھے وہیں کبھی متوسط اور کبھی چھوٹی چھوٹی سورتیں حتی کہ \" معوذتین \" بھی پڑھا کرتے تھے، یہ سب حالات، نشاط، اور کبھی بیان جواز کے لیے کرتے تھے۔","الألباني: صحيح",{"u2":"سیدنا عقبہ بن عامر رضی اللہ عنہ سے روایت ہے کہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے معوذتین کے بارے میں پوچھا۔عقبہ نے کہا کہ (آپ نے اس وقت تو کوئی جواب نہ دیا لیکن)پھر رسول اللہ صلی اللہ علیہ وسلم نے ہمیں صبح کی نمازکی امامت کراتے ہوئے یہ دونوں سورتیں تلاوت فرمائیں۔","f2":"صبح کی نماز میں لمبی قراءت مسنون ہے۔آپ کا طرز عمل یہی تھا مگر اس دن ان\nدو چھوٹی سورتوں کو صبح کی نماز میں پڑھناان کی اہمیت ظاہر کرنے کے لیے تھا کہ یہ\nباوجودمختصر ہونے کے بہت جامع اور افضل ہیں حتٰی کہ صبح کی نماز میں طویل قراءت کی جگہ کفایت کر سکتی ہیں۔"}],[5435,"عقبہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فجر میں معوذتین پڑھیں۔","الألباني: صحيح",{"u2":"حضرعقبہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے یہ دو سورتیں صبح کی نماز میں پڑھیں۔"}],[5436,"عقبہ بن عامر رضی اللہ عنہ کہتے ہیں کہ میں ایک سفر میں رسول اللہ صلی اللہ علیہ وسلم کی سواری کی نکیل پکڑ کر آگے آگے چل رہا تھا، تو آپ نے فرمایا: \"عقبہ! کیا میں تمہیں دو بہترین سورتیں نہ بتاؤں جو مجھے پڑھائی گئی ہیں؟\" پھر آپ نے مجھے «قل أعوذ برب الفلق» اور «قل أعوذ برب الناس» سکھائی، لیکن آپ نے مجھے ان دونوں پر خوش ہوتے نہیں دیکھا، پھر جب آپ فجر کے لیے مسجد آتے تو انہیں دونوں سورتوں سے لوگوں کو فجر پڑھائی، جب رسول اللہ صلی اللہ علیہ وسلم نماز سے فارغ ہوئے تو میری طرف متوجہ ہوئے اور فرمایا: \"عقبہ! تم نے (ان کو) کیسا پایا\"۔","الألباني: صحيح",{"u2":"حضرت عقبہ بن عامر نے فرمایا کہ میں ایک سفر میں رسول اللہ صلی اللہ علیہ وسلم کی سواری کی لگام پکڑکر آگے آگے چل رہا تھا کہ رسول اللہ نے فرمایا:’’عقبہ!میں تجھ دو بہترین سورتیں نہ سکھاؤں جو کبھی پڑھی گئی ہوں؟‘‘پھر آپ نے مجھے سورۂ(قل اعوذبرب الفلق)اور (قل اعوذ برب الناس)سکھائیں۔آپ نے محسوس فرمایا کہ میں یہ سورتیں سیکھ کر زیادہ خوش نہیں ہوا‘لہذا جب آپ صبح کی نماز کے لیے اترے تو یہ دونوں سورتیں صبح کی نماز میں لوگوں کی امامت کرواتے ہوئے پڑھیں۔جب رسول ا للہ صلی اللہ علیہ وسلم نماز سے فارغ ہوئےتو میری طرف توجہ ہوئے اور فرمابا:’’اے عقبہ!تیر ا کیا خیال ہے؟‘","f2":"’’کیا خیال ہے؟‘‘یعنی اب تجھے ان سورتوں کی اہمیت محسوس ہوئی؟"}],[5437,"عقبہ بن عامر رضی اللہ عنہ کہتے ہیں کہ ایک مرتبہ میں رسول اللہ صلی اللہ علیہ وسلم کی سواری (اونٹنی) کی نکیل ان گھاٹیوں میں سے ایک گھاٹی میں پکڑے آگے آگے چل رہا تھا تو اس وقت آپ نے فرمایا: \"عقبہ! کیا تم سوار نہیں ہو گے؟\" میں نے آپ کی بزرگی کا خیال کیا کہ میں رسول اللہ صلی اللہ علیہ وسلم کی سواری پر ہو جاؤں، پھر آپ نے فرمایا: \"کیا تم سوار نہیں ہو گے عقبہ؟\" تو مجھے ڈر لگا کہ کہیں نافرمانی نہ ہو جائے، پھر آپ اترے اور میں تھوڑی دیر کے لیے سوار ہوا پھر میں اتر گیا اور رسول اللہ صلی اللہ علیہ وسلم سوار ہوئے اور فرمایا: \"لوگ جو سورتیں پڑھتے ہیں، ان میں سے میں تمہیں دو بہترین سورتیں نہ بتاؤں؟\" چنانچہ آپ نے مجھے پڑھ کر سنائی «قل أعوذ برب الفلق» اور « قل أعوذ برب الناس»، پھر نماز قائم کی گئی، تو آپ آگے بڑھے اور ان دونوں سورتوں کو پڑھا، پھر آپ میرے پاس سے گزرے، اور فرمایا: \"عقبہ! یہ کیسی لگیں؟ جب جب سوؤ اور جب جب جاگو انہیں پڑھا کرو\"۔","الألباني: حسن الإسناد",{"u2":"سیدنا عقبہ بن عامر جہنی رضی اللہ عنہ سے روایت ہے ‘انھوں نے کہا کہ ایک دفعہ میں رسول اللہ صلی اللہ علیہ وسلم کی سواری کی لگام پکڑ کر ان گھاٹیوں میں سے کسی گھاٹی میں چل رہا تھا کہ آپ نے فرمایا:’’عقبہ!تو(میرے ساتھ)؟‘‘ میں نے اس بات کو بہت بڑا محسوس کیا کہ میں رسول اللہ صلی اللہ علیہ وسلم کی سواری پر سوار ہو جاؤں۔کچھ دیر بعد آپ نے فرمایا:’’عقبہ توسوار کیوں نہیں ہو جاتا؟‘‘مجھے خطرہ محسوس ہوا کہ کہیں آپ کی نافرمانی نہ ہو۔آخر ‎آپ اترے تو میں تھوڑی دیر کے لیے سوار ہو گیا۔پھر میں اتر آیااور رسول اللہ صلی اللہ علیہ وسلم سوار ہو گئے۔پھر آپ نے فرمایا:’’کیا میں تجھ دو بہترین سورتیں نہ سکھاؤں جو لوگوں نے پڑھی ہیں۔‘‘پھر آپ نے مجھے سورۂ(قل اعوذ برب الفلق)او رسورۂ(قل اعوذ برب الناس)پڑھائیں۔پھر جماعت کے لیے اقامت کہی گئی تو آپ آگے بڑھے اور یہی دو سورتیں پڑھیں۔پھر (نماز سے فراغت کے بعد)میرے پاس سے گزرے تو فرمایا:’’عقبہ بن عامر!تیری کیا رائے ہے؟ان سورتوں کو پڑھ کر جب بھی سوئے یا جاگے۔‘‘","f2":"تیر ی کیا رائے ہے؟‘‘یعنی ان دو سورتوں کی شان وعظمت کے بارے میں کہ ان کو صبح کی نماز میں پڑھا گیا۔"}],[5438,"عقبہ بن عامر رضی اللہ عنہ کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ چل رہا تھا، تو آپ نے فرمایا: \"عقبہ! کہو\"، میں نے عرض کیا: کیا کہوں؟ اللہ کے رسول! آپ خاموش رہے، پھر فرمایا: \"عقبہ! کہو\"، میں نے عرض کیا: کیا کہوں؟ اللہ کے رسول! آپ خاموش رہے، میں نے کہا: اللہ کرے آپ اسے پھر دہرائیں، آپ نے فرمایا: \"عقبہ! کہو\"، میں نے عرض کیا: اللہ کے رسول! میں کیا کہوں؟ آپ نے فرمایا: «قل أعوذ برب الفلق» میں نے اسے پڑھا یہاں تک کہ اسے مکمل کیا، پھر آپ نے فرمایا: \"کہو\"، میں نے عرض کیا: کیا کہوں اللہ کے رسول! آپ نے فرمایا: \" «قل أعوذ برب الفلق» \"، پھر میں نے اسے بھی مکمل پڑھا، اس وقت رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کسی مانگنے والے نے اس جیسی کسی اور چیز کے ذریعہ نہیں مانگا اور نہ کسی پناہ مانگنے والے نے اس جیسی کسی اور چیز کے ذریعہ پناہ مانگی\"۔","الألباني: حسن صحيح",{"u2":"سیدنا عقبہ بن عامر رضی اللہ عنہ سےروایت ہے ‘انھوں نے کہا کہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ چل رہا تھا کہ آپ نے فرمایا:’’اے عقبہ!پڑھ۔‘‘میں نے عرض کی:اے اللہ کے رسول!کیا پڑھوں؟آپ حاموش ہو گۓ۔پھر فرمایا:’’اے عقبہ کہہ۔‘‘میں نے عرض کی:اے اللہ کے رسول!کیا کہوں؟آپ پھر خاموش ہو گئے۔میں نے(دل میں)کہا:یااللہ!آپ کو میری طرف متوجہ فرما۔آپ نے فرمایا:’’اے عقبہ!پڑھ۔‘‘میں نے کہا اے اللہ کے رسول!میں کیا پڑھوں؟آپ نے فرمایا:’’سورۂ(قل اعوذ برب الفلق)میں نے سورت پڑھنا شروع کی حتی کہ مکمل کر دی۔پھر آپ نے فرمایا:’’پڑھ:‘‘میں نے کہا:اے اللہ کے رسول کیا پڑھوں؟آپ نے فرمایا:’’سورۂ(قل اعوذ برب الناس ‎)۔‘‘اس وقت ےمیں نے آخر تک پوری پڑھ دی۔ پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’کسی سوال کرنے والے نے ان جیسی سورتوں کے ساتھ سوال نہیں کیا اور نہ کسی پناہ طلب کرنے والے نے ان جیسی سورتوں کے ساتھ پناہ طلب کی ہے۔‘‘","f2":"خاموش ہو گئے ‘‘آپ کا ایک ہی بات فرمانا اور پھر خاموش ہو جانا مخاطب کے دل میں شوق او ر توجہ پیدا کرنے کے لیے تھا تا کہ اس کے نزدیک آئندہ بات کی اہمیت واضح ہو جائے۔"}],[5439,"عقبہ بن عامر رضی اللہ عنہ کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، آپ سوار تھے، میں نے اپنا ہاتھ آپ کے پاؤں پر رکھا، میں نے عرض کیا: مجھے سورۃ ہود پڑھایئے، مجھے سورۃ یوسف پڑھایئے، آپ نے فرمایا: \"تم اللہ کے نزدیک «قل أعوذ برب الفلق» سے زیادہ بہتر کوئی اور سورۃ نہیں پڑھو گے۔","الألباني: صحيح",{"u2":"حضرت عقبہ بن عامر رضی اللہ عنہما نے کہا کہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوا جبکہ آپ سوار تھے میں نے اپنا ہاتھ آپ صلی اللہ علیہ وسلم کے قدم مبارک پر رکھ دیا اور عرض کی مجھے سورۂ ہود پڑھایئے۔مجھے سورۂیوسف پڑھائیے۔ آپ نے فرمایا:’’تو کوئی ایسی سورت نہیں پڑے گا جو اللہ تعالیٰ کے نزدیک سورۂ(قل اعوذ برب الفلق)اور سورۂ(قل اعوذ برب الناس)زیادہ عظمت والی","f2":":زیادہ عظمت والی ہو ‘‘یعنی پناہ طلب کرنے کے بارے میں ورنہ کسی اور لحاظ سے کوئی اور سورت افضل ہو سکتی ہے۔‘حدیث:5442۔حضرت عقبہ بن عامر سے روایت ہے کہ بنئ اکرم صلی اللہ علیہ وسلم نے فرمایا:’’مجھ پر ایسی آj\nکہ (استعاذہ کے سلسلے میں)کوئی اور آیات ان جیسی نہیں (قل اعوذ برب الفلق)آخر سورت اور (قل اعوذ برب الناس)آخر تک۔‘"}],[5440,"عقبہ بن عامر رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"مجھ پر کچھ ایسی آیات نازل ہوئی ہیں کہ ان جیسی آیات پہلے کبھی نہیں دیکھی گئیں، «قل أعوذ برب الفلق» پوری سورت اور «قل أعوذ برب الناس» \" پوری سورۃ۔","الألباني: صحيح",{"u2":"حضرت عقبہ بن عامر سے روایت ہے کہ بنئ اکرم صلی اللہ علیہ وسلم نے فرمایا:’’مجھ پر ایسی آیات اتاری گئی ہیں کہ (استعاذہ کے سلسلے میں)کوئی اور آیات ان جیسی نہیں (قل اعوذ برب الفلق)آخر سورت اور (قل اعوذ برب الناس)آخر تک۔‘"}],[5441,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ مجھ سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جابر! پڑھو\"، میں نے کہا: میرے ماں باپ آپ پر قربان ہوں، میں کیا پڑھوں؟ اللہ کے رسول! آپ نے فرمایا: \"پڑھو «قل أعوذ برب الفلق» اور «قل أعوذ برب الناس» \" میں نے یہ دونوں سورتیں پڑھیں۔ پھر آپ صلی اللہ علیہ وسلم نے فرمایا:: \"انہیں پڑھا کرو، تم ان جیسی سورتیں ہرگز نہ پڑھو گے\"۔","الألباني: حسن صحيح",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت ہے ‘انھوں نے کہا کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ جابر!پڑھو۔‘‘میں نے عرض کی:میرے ماں باپ آپ پر فدا ہو جائیں اے اللہ کے رسول!میں کیا پڑھوں؟آپ نے فرمایا:’’سورۂ(قل اعوذ برب الفلق)اور سورۂ(قل اعوذ برب الناس)پڑھ۔‘‘میں نے دونوں سورتیں پڑھیں تو آپ نے فرمایا:’’ان کو پڑھا کر اور (یاد رکھ کہ)تو (استعاذے کے بارے میں)ان جیسی کوئی اور سورت نہیں پڑھے گا۔‘"}],[5442,"عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم چار باتوں سے پناہ مانگتے تھے: ایسے علم سے جو نفع بخش نہ ہو، ایسے دل سے جس میں اللہ کا ڈر نہ ہو، ایسی دعا سے جو قبول نہ ہو اور ایسے نفس سے جو آسودہ نہ ہو ۱؎۔\n§وضاحت\n۱؎: ایک امتی ان چاروں چیزوں سے اس طرح پناہ مانگے «اللٰھم إنی أعوذبک من علم لاینفع ومن قلب لایخشع ومن دعا لایسمع ومن نفس لاتشبع» اسی طرح آگے جہاں بھی یہ آیا ہے کہ اللہ کے رسول صلی اللہ علیہ وسلم ان چیزوں سے پناہ مانگا کرتے تھے وہاں واحد متکلم کا صیغہ بنا لے، جیسے اگلی حدیث میں «أعوذ من الجبن»۔","الألباني: صحيح",{"u2":"حضرت عبد اللہ بن عمر سے منقول ہے۔کہ نبئ اکرم صلی اللہ علیہ وسلم چار چیزوں سے اللہ تعالیٰ کی پناہ طلب فرمایا کرتے تھے:ایسے علم سے جو نفع نہ دے ‘ایسے دل سے جو اللہ تعالیٰ سے نہ ڈرے ‘ایسی دعا سے جو قبول نہ ہو اور ایسے نفس سے جو سیر نہ ہو۔","f2":"(1)حدیث میں مذکورہ ان چار چیزوں سے اللہ تعالیٰ کی پناہ حاصل کرنا مستحب اور پسندیدہ عمل ہے۔(2)ظاہری معنیٰ مراد نہیں بلکہ مقصود یہ ہے یا کہ اللہ!میرے علم کو مفید بنا۔دل کو عاج اور خشوع والا بنا۔میری دعائیں قبول فرما اور نفس کو قناعت پسند بنا۔(3)آپ کا استعاذہ امت کی تعلیم اور اظہار عبودیت کے لیے تھا ورنہ آپ کو یہ پناہ پہلے سے حاصل تھی۔اس میں یہ اشارہ ہے کہ بندے کو ہر حال میں اللہ تعا لیٰ سے ڈرتے رہنا چاہیےاور اللہ تعالیٰ کے سامنے محتاج بن کر رہنا چاہیے۔(4)علم نافع سے مراد علم کے مطابق عمل ہے کیونکہ علم کا سب سے پہلافائدہ عالم کو ہونا چاہیے ‘پھر دوسرں کو ‘مثلا:تبلیغ و تعلیم وغیرہ۔(5)دعا کی قبولیت سے مراد اس پر ثواب حاصل کرنا ہے نہ کہ بعینہٖبات کا پورا ہو جانا کیوں کہ یہ بہت سے امور میں ممکن نہیں۔(6)’’نفس کے سیر نہ ہونے ‘‘سے مراد نفس کا حریص اور لالچی ہونا ہے ‘البتہ علم اور ثواب کی حرص اچھی چیز ہے۔ واللہ اعلم"}],[5443,"عمر رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم بزدلی، کنجوسی، سینے (دل) کے فتنے اور قبر کے عذاب سے (اللہ تعالی کی) پناہ مانگتے تھے۔","",{"u2":"سیدنا عمر رضی اللہ عنہ سے منقول ہے کہ نبئ اکرم صلی اللہ علیہ وسلم بزدلی ‘بخل ‘سینے کے فتنے اور قبر کے عذاب سے بچنے کے لیے اللہ تعالیٰ کی پناہ طلب فرمایا کرتے تھے۔","f2":"(1)باپ کا مقصد بالکل واضح ہے کہ مذکورہ تمام بیماریوں سے چھٹکارے کے لیے اللہ تعالیٰ کا سہارہ ضروری ہے۔اللہ تعالیٰ کے سہارے کے بغیر کے ان ’’موذی اور مہلک ‘‘بیماریوں سے بچنابہت ہی مشکل کام ہے۔ پھر جس سے یہ روحانی بیماریاں لگ جائیں تو اس کے لیے جہنم اور آگ کا عذاب ہے۔اعا ذنا اللہ منہ.(2)رسول اللہ صلی اللہ علیہ وسلم کا مذکورہ دعا پڑھنا اور امت کو اس کی تعلیم دینا صرف اس بنا پر تھا کہ امت کو عملاًیہ بتایا جائے کہہ ان کی تمام بیماریوں کا صرف اللہ تعالیٰ کی پناہ میں آنا ‘اس کا سہارہ لینا اور اس سے امان طلب کرنے ہی میں ہے۔لوگ مصائب سے بچنے کےلیے تعویذوں اور خود ساختہ وظائف کا سہارہ لیتے ہیں ‘حالانکہ تمام مشکلات کا حل رسوللہ صلی اللہ علیہ وسلم کے بتائے ہوئے اذکامیں ہے۔انھی کو اختیار کرنا چاہیے تا کہ روحانی اور جسمانی بیماریوں سے چھٹکارہ حاصل ہو سکے -(3)بزدلی سے مراد اللہ تعالیٰ کے راستے میں جان قربان کرنے سے بھاگنا ہے اور بخل سے مراد اللہ تعالیٰ کے راستے میں مال کرنے سے کنی کترانا ہے۔(4)سینے کے فتنے سے مراد شیطانی وساوس‘باطل عقائد اور دل کی خرابیاں ‘مثلاً:حسد ‘ کینہ بغض اور عناد وغیرہ ہیں۔پیچھے یہ ہو چکا ہے کہ نبئ اکرم صلی اللہ علیہ وسلم کا استعاذہ اصل امت کی تعلیم کے لیے ہے ورنہ آپ تو رذائل سے قطعاًپاک و صاف تھے۔آپ کے بارہ میں ان کا تصور بھی نہیں کیا جاسکتا۔"}],[5444,"شکل بن حمید رضی اللہ عنہ کہتے ہیں کہ میں نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا، میں نے عرض کیا: اللہ کے نبی! مجھے کوئی ایسا تعوذ (شر و فساد سے بھاگ کر اللہ کی پناہ میں آنے کی دعا) بتائیے، جس کے ذریعہ میں اللہ تعالی کی پناہ مانگوں۔ آپ نے میرا ہاتھ پکڑا اور فرمایا: کہو: \" «أعوذ بك من شر سمعي وشر بصري وشر لساني وشر قلبي وشر منيي» \"اے اللہ! میں تیری پناہ مانگتا ہوں اپنے کان کی برائی سے، اپنی آنکھ کی برائی سے، اپنی زبان کی برائی سے، اپنے دل کی برائی سے، اپنی منی کی برائی سے\"، شکل کہتے ہیں: یہاں تک کہ میں نے اسے یاد کر لیا۔ سعد کہتے ہیں: منی سے مراد نطفہ (پانی) ہے۔","الألباني: صحيح",{"u2":"سیدنا شکل بن حمید رضی اللہ عنہ سے روایت ہے ‘انھوں نے فرمایا کہ میں نبئ اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور عرض کی:اے اللہ کے نبی!مجھے ایسے کلمات سکھادیجیے جن کے ساتھ میں اللہ تعالیٰ کی پناہ طلب کیا کروں۔آپ نے میرا ہاتھ پکڑا اور فرمایا:’’تو یہ کلمات کہہ:اے اللہ!میں اپنے کانوں‘آنکھوں‘زبان‘دل اور منی کے شر سے تیری پناہ طلب کرتا ہوں۔‘‘میں نے یہ کلمات یاد کر لیے۔سعد(ابن اوس راوی حدیث)نے کہا کہ منی سے مراد نطفہ ہے (اس کی برائی یہ ہے کہ اسے حرام میں بہائے)۔","f2":"(1)یہ حدیث مبارکہ اس بات پر دلالت کرتی ہے کہ حدیث میں مذکورہ اشیاء سے ا للہ تعالیٰ کی پناہ حاصل کرنا مشروع اور پسندیدہ عمل ہے ‘لہذاہر مسلمان مرد عورت کو اس مسنون دعا کا التزام کرنا چاہیے (2)اس حدیث مبارکہ سے صحابۂ کرام رضی اللہ عنہم کا نبئ اکرم صلی اللہ علیہ وسلم سے ایسے سوال پوچھنے کا اہتمام بھی واضح ہوتا ہے جن سے انھیں اپنے دینی اور دنیاوی معاملات میں فائدہ ہوتا اور ان سے ان کی دنیاو آخرت سنورتی۔(3)قرآن حدیث میں مذکورہ دعاؤں سے اصل مطلوب و مقصود یہ ہے کہ بندہ ہمیشہ اور ہر حال میں اپنے رب کریم کی طرف متوجہ رہے ‘اس سے جڑا رہے ‘اس کا در نہ چھوڑے اور اسی کی بارگاہ میں اپنی ساری عاجزیاں پیش کرے ‘نیز تمام ظاہری وباطنی (اندرونی وبیرونی)تکالیف و پریشانیوں سے بچنے کے لیے حفاظت میں رہنے کی کوشش کرتا رہے۔ان سے بچنے کے لیے اللہ کی مدد ہی سب سے بڑا اور مؤثر ذریعہ ہے۔(4)مذکورہ چیزوں کی شر سے مراد ان کا نا جائز اور بے محل استعمال ہے اور اللہ سے پناہ طلب کرنے کا مقصد ان کی حفاظت ہے کہ یہ غلط استعمال نہ ہوں۔مزید تفصیل کے لیے دیکھیۓ‘(سنن ابو داؤد (مترجم)‘فائدہ حدیث:1551۔مطبوعہ دارالسلام)"}],[5445,"مصعب بن سعد سے روایت ہے کہ سعد رضی اللہ عنہ ہمیں پانچ باتیں سکھاتے تھے، کہتے تھے: رسول اللہ صلی اللہ علیہ وسلم ان الفاظ کے ساتھ دعا مانگتے تھے، آپ فرماتے تھے: «اللہم إني أعوذ بك من البخل وأعوذ بك من الجبن وأعوذ بك أن أرد إلى أرذل العمر وأعوذ بك من فتنة الدنيا وأعوذ بك من عذاب القبر» \"اے اللہ! میں کنجوسی سے تیری پناہ مانگتا ہوں، بزدلی سے تیری پناہ مانگتا ہوں، مجبوری و لاچاری والی عمر تک پہنچنے سے تیری پناہ مانگتا ہوں، دنیا کے فتنے سے تیری پناہ مانگتا ہوں، قبر کے عذاب سے تیری پناہ مانگتا ہوں\"۔","الألباني: صحيح",{"u2":"حضرت مصعب بن سعد سے روایت ہے ‘انھوں نے کہا کہ ہمارے والد محترم (سیدنا سعد بن ابی وقا رضی اللہ عنہ)ہمیں پانچ کلمات سکھایا کرتے تھے اور فرماتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم دعا میں یہ کلمات پڑھا کرتے تھے:’’اے اللہ!میں بخل سے بچنے کے لیے تیری پناہ میں آتا ہوں۔میں بزدلی سے بچنے کے لیے تیری پناہ میں آتا ہوں اور میں اس بات سےبھی تیری پناہ میں آتا ہوں کہ میں ذلیل ترین عمر پاؤں۔میں دنیا کے فتنے سے تیری پناہ میں آتا ہوں اور میں قبر کے عذاب سے بچاؤکے لیے تیری پناہ میں آتا ہوں۔‘","f2":"(1)پناہ میں آنے کا مقصود بچاؤہے ‘یعنی اے اللہ مجھے ان چیزوں سے بچا کر رکھنا۔(2)ذلیل ترین عمر ‘‘جس میں انسان کی قوتیں جواب دے جائیں۔انسان کلی طور پر محتاج بن جائے۔نہ اپنے کام کا رہے نہ کسی کے کام کا ‘یعنی شدید تر ین بڑھاپا۔(3)دنیا کے فتنے سے مرادگمراہی ہے جس پر عذاب قبر مرتب ہوتا ہے۔"}],[5446,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم پانچ باتوں سے اللہ تعالی کی پناہ مانگتے تھے: \"بخیلی سے، بزدلی سے، مجبوری و لاچاری والی عمر سے، سینے (دل) کے فتنے سے اور قبر کے عذاب سے\"۔","الألباني: ضعيف",{"u2":"سیدنا ابن مسعود رضی اللہ عنہ نے فرمایا کہ نبئ اکرم صلی اللہ علیہ وسلم پانچ چیزوں سے اللہ تعالیٰ کی پناہ کیا کرتے تھے:بخل‘بزدلی‘بری عمر ‘سینے کے فتنے اور قبر کے عذاب سے۔","f2":"ظاہرتو یہی ہے کہ بری عمرسے مرادذلیل ترین عمر ہی ہے جس کا ذکر سابقہ حدیث میں گزرا ہے ‘مگر بری عمر سے مراد گمراہی والی عمر بھی ہو سکتی ہے ‘خواہ وہ جوانی کی عمر ہو یا بڑھاپے کی۔"}],[5447,"عمرو بن میمون اودی کہتے ہیں کہ سعد رضی اللہ عنہ اپنے بیٹوں کو یہ کلمات سکھاتے تھے جیسے معلم لڑکوں کو سکھاتا ہے اور کہتے کہ رسول اللہ صلی اللہ علیہ وسلم نماز کے بعد ان کلمات کے ذریعے پناہ مانگتے تھے۔ \" «اللہم إني أعوذ بك من البخل وأعوذ بك من الجبن وأعوذ بك أن أرد إلى أرذل العمر وأعوذ بك من فتنة الدنيا وأعوذ بك من عذاب القبر» \"اے اللہ! میں کنجوسی سے تیری پناہ مانگتا ہوں، بزدلی سے تیری پناہ مانگتا ہوں، اور اس بات سے تیری پناہ مانگتا ہوں کہ میں لاچاری اور مجبوری کی عمر کو پہنچوں، میں دنیا کے فتنے سے تیری پناہ مانگتا ہوں قبر کے عذاب سے تیری پناہ مانگتا ہوں\"۔ پھر میں نے اسے مصعب سے بیان کیا تو انہوں نے اس کی تصدیق کی۔","الألباني: صحيح",{"u2":"حضرت عمرو بن میمون اودی سے مروی ہے کہ سیدنا سعد رضی اللہ عنہ اپنے بیٹوں کو یہ کلمات اس طرح سکھلاتے تھے جس طرح استاد بچوں کے سبق رٹاتا ہے اور فرماتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم (فرض)نماز کے بعد ان کلمات کے ساتھ اللہ تعالی کی پناہ طلب کیا کرتے تھے:’’اے اللہ!میں بخل سے تیری پناہ میں آتا ہوں۔بزدلی سے تیری پناہ حاصل کرتا ہوں۔اس بات سے بھی پناہ طلب کرتا ہوں کہ مجھے ذلیل ترین عمر میں پہنچایا جائے۔میں دنیا کے فتنے سے تیری پناہ میں آتا ہوں اور قبر کے عذاب سے (بچنے کے لیے)میں تری پناہ حاصل کرتا ہوں۔‘‘(راوی نے کہا)میں نے یہ کلمات (سیدنا سعد رضی اللہ عنہ کے بیٹے)مصعب کو بیان کیے تو انھوں نے تصدیق کی۔"}],[5448,"انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم فرماتے تھے: «اللہم إني أعوذ بك من العجز والكسل والبخل والهرم وعذاب القبر وفتنة المحيا والممات» \"اے اللہ! میں عاجزی، سستی و کاہلی، بخیلی، بڑھاپے، قبر کے عذاب اور موت و زندگی کے فتنے سے تیری پناہ مانگتا ہوں\"۔","الألباني: صحيح",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم یوں دعا فرماتے تھے:’’اے اللہ!میں عجز ‘سستی ‘بخل ‘شدید بڑھاپے ‘قبر کے عذاب اور زندگی وموت کے فتنے سے تیری پناہ میں آتا ہوں۔‘","f2":"’’عجز ‘‘سے مراد یہ ہے کہ انسان کوئی کام نہ کرسکے۔کرنا نہ آتا ہو یا کرنے کی طاقت نہ ہو یامجبورومقہور ہو کہ طاقت ہونے کے باوجود کر نہ سکتا ہو۔اور ’’سستی ‘‘سے مراد یہ ہے کہ کام کر سکتا ہے مگر ہمت نہیں کرتا۔موت ک فتنے سے مراد مرتے وقت گمراہ ہو جانا ہے یا کوئی ایسا کام کر بیٹھنا ہے جو قابل معافی نہ ہو۔عذاب قبر بھی مراد ہو سکتا ہے"}],[5449,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کی کچھ دعائیں تھیں جنہیں آپ (پڑھنا) نہیں چھوڑتے تھے: آپ فرماتے: «اللہم إني أعوذ بك من الهم والحزن والعجز والكسل والبخل والجبن وغلبة الرجال» \"اے اللہ! میں فکر و سوچ اور پریشانی سے، عاجزی و سستی سے، کنجوسی و بزدلی سے اور لوگوں کے غالب آنے سے تیری پناہ مانگتا ہوں\"۔","الألباني: صحيح لغيره",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے ‘انھوں نے فرمایا:کچھدعائیں ایسی ہیں جنھیں رسول اللہ صلی اللہ علیہ وسلم کبھی نہیں چھوڑتے تھے۔آپ فرمایا کرتے تھے:’’اے اللہ!میں فکر‘غم‘عجز‘سستی‘بخل‘بزدلی اور اور لوگوں کے غلبے سے تیری پناہ میں آتا ہوں۔‘۔","f2":"(1)فکر کسی آئندہ چیز کے بارے میں ہوتی ہے جب کہ غم کسی گزشتہ چیز پر۔فکر اور غم سے اللہ تعالیٰ کی پناہ طلب کرنے کا مطلب یہ ہے کہ میں ان چیزوں کے بارے میں فکر مند ہوکر اور سوچ سوچ کر نہ گھلتا رہوں جن میں مجھے کچھ دخل نہیں ‘نہ کوئی اختیار ہے یاآئندہ کے بارے میں مو ہوم تصورات میں کھویارہوں اور اپنے ضروری کام بھی نہ کر سکوں۔اسی طرح میں بیت جانے والے واقعات کے غم میں نہ پڑا رہوں کہ میں اپنی مودہ زندگی کو بھی حیران بنا لوں جب کہ گزشتہ واقعات نہ بدل سکتے ہیں نہ غم ان کے اثرات کو ختم کرسکتا ہے ‘بلکہ اللہ تعالیٰ کی رضا پر راضی ہونتا اور اسی پر بھروسہ رکھنا ہی گزشتہ اور آئندہ کے بارے میں انسان کو پر سکون بناتا ہے (2)لوگوں کے غلبے سے مراد یہ ہے کہ کوئی شخص لوگوں کے لیے اضحوکہ اور کھلونا بن جائے یا لوگوں کے ستم کے لیے تختہ مشق بن جائے کہ جو شخص چاہے ‘اسے ذلیل کرنے لگ جائے۔"}],[5450,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کی کچھ دعائیں تھیں جنہیں آپ (پڑھنا) نہیں چھوڑتے تھے: «اللہم إني أعوذ بك من الهم والحزن والعجز والكسل والبخل والجبن والدين وغلبة الرجال» \"اے اللہ! میں فکر و سوچ اور پریشانی سے، عاجزی و کاہلی سے، کنجوسی و بزدلی سے، قرض سے اور لوگوں کے غالب آنے سے تیری پناہ مانگتا ہوں\"۔ ابوعبدالرحمٰن (نسائی) نے کہا: یہ حدیث صحیح ہے اور ابن فضیل کی حدیث میں غلطی ہے۱؎۔\n§وضاحت\n۱؎: یعنی محمد بن اسحاق کی حدیث جو عمرو بن ابی عمرو سے بواسطہ انس بن مالک مروی ہے یہ صحیح ہے، جب کہ ابن اسحاق کی روایت جو منہال ابن عمرو سے بواسطہ انس بن مالک مروی ہے یہ صحیح نہیں ہے، کیونکہ منہال کا سماع صحابہ سے ثابت نہیں ہے۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک سے روایت ہے کہ کچھ دعائیں رسول اللہ صلی اللہ علیہ وسلم کی عادت بن چکی تھیں کبھی چھوڑتے تھے۔’’اے اللہ!میں فکر و غم ‘عجز و سستی ‘بخل اور قرض‘نیز لوگوں کے غلبے سےتیری پناہ آتا ہوں۔‘‘امام ابو عبد الرحمٰن(نسائی رحمہ اللہ) نے کہا یہ حدث درست ہے اور صحیح ہے جبکہ ابن فضیل کی (اس سے پہلی)حدیث غلط ہے۔","f2":"قرض سے مراد وہ قرض ہے جو ادا نہ سکے بلکہ بڑھتا جائے۔مقروض کے لیے ذلت اور بے عزتی کا سبب ہو ورنہ مطلق قرض تو رسول اللہ صلی اللہ علیہ وسلم نے بھی لیا ہے اور اس سے مفر بھی نہیں۔"}],[5451,"انس رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم دعا فرماتے تھے: «اللہم إني أعوذ بك من الكسل والهرم والجبن والبخل وفتنة الدجال وعذاب القبر» \"اے اللہ! میں کاہلی سے، بڑھاپے سے، بزدلی سے، کنجوسی سے، دجال کے فتنے سے، اور قبر کے عذاب سے تیری پناہ مانگتا ہوں\"۔","الألباني: صحيح الإسناد",{"u2":"سیدنا انس رضی اللہ عنہ نے فرمایا کہ نبئ اکرم صلی اللہ علیہ وسلم یہ دعا کیا کرتے تھے:’’ اے اللہ میں بے جاسستی ‘شدید بڑھاپے ‘بزدلی‘بخل ‘دجال کے فتنے اور قبر کے عذاب سے تیری پناہ حاصل کرتا ہوں۔‘","f2":"دجال کسی مخصوص شخص کا نام نہیں بلکہ یہ صفت کا صیغہ ہے۔اس کے معنی ہیں:فراڈی ‘جعل ساز‘جھوٹا اور دغا باز۔ہر جھوٹا نبئ‘فراڈی لیڈر اور قائد دجال ہے ‘البتہ سب سے بڑا دجال قریب قیامت پیدا ہو گا جو رب ہونے کا دعویٰ بھی کرے گا۔اسے حضرت عیسیٰ علیہ السلام قتل کریں گے اور اس کا فتنہ فرو کریں گے‘عموماًاس کو دجال کہا جاتا ہے۔"}],[5452,"انس رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم فرماتے تھے: «اللہم إني أعوذ بك من العجز والكسل والهرم والبخل والجبن وأعوذ بك من عذاب القبر ومن فتنة المحيا والممات» \"اے اللہ! میں عاجزی، کاہلی، بڑھاپے، کنجوسی، اور بزدلی سے تیری پناہ مانگتا ہوں، نیز قبر کے عذاب سے اور موت اور زندگی کے فتنے سے تیری پناہ مانگتا ہوں\"۔","الألباني: صحيح الإسناد",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ نبئ اکرم صلی اللہ علیہ وسلم یوں فرمایا کرتے تھے ’’اے اللہ!میں نکمے پن ‘بے جا سستی‘شدید بڑھاپے‘کنجوسی اور بزدلی سے تیری پناہ میں آتا ہوں ‘نیز قبر کے عذاب اور زندگی اور موت کے فتنے سے تیری پناہ مانگتا ہوں‘‘"}],[5453,"انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب دعا کرتے تو فرماتے: «اللہم إني أعوذ بك من الهم والحزن والعجز والكسل والبخل والجبن وضلع الدين وغلبة الرجال» \"اللہ! میں حزن و ملال، رنج و غم، عاجزی و کاہلی، کنجوسی و بزدلی، قرض کے بوجھ اور لوگوں کے غلبے سے میں تیری پناہ مانگتا ہوں\"۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: سعید بن سلمہ ضعیف ہیں ۱؎۔ ہم نے ان کی روایت اس لیے بیان کی ہے کہ اس کی سند (ایک راوی کا) اضافہ ہے ۲؎۔\n§وضاحت\n۱؎: جب حفظ سے روایت کریں تب ضعیف ہیں، ورنہ صحیح الکتاب ہیں۔ ۲؎: اور وہ \" عبداللہ بن عبدالمطلب \" ہیں، لیکن سند حدیث نمبر ۵۴۵۲ میں ان کا اضافہ نہیں ہے، اور اس اضافہ کے بغیر بھی سند متصل ہے۔","الألباني: صحيح لغيره",{"u2":"سیدنا اانس بن مالک رضی اللہ عنہ سے مروی ہے کہ رسو ل اللہ صلی اللہ علیہ وسلم جب دعا کرتے تو یوں فرماتے:’’اے اللہ!میں فکرو غم ‘عجز وکاہلی‘کنجوسی و بزدلی‘قرض کے شدید بوجھ اور لوگوں کے غلبے سے تیری پناہ میں آتا ہوں۔‘‘ابو عبدالرحمٰن (امام نسائی رحمہ اللہ)نے کہا: (اس حدیث کی سند کا راوی)سعید بن سلمہ ضعیف ہے۔(ضعیف روایت ہونے کے باوجود)ہم نے یہ روایت اس لیے بیان کی ہے کہ ای میں (کچھ عبارت)زیادہ ہے۔","f2":"فکرو غم سے پناہ مانگنے کا مفہوم یہ بھی ہو سکتا ہے کہ مجھے کوئی غم ناک چیز نہ پہنچے اور نہ نقصان دہ چیز کا خطرہ رہے۔"}],[5454,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم قرض اور معصیت (گناہ) سے پناہ مانگتے تھے، میں نے عرض کیا: اللہ کے رسول! آپ قرض سے بہت پناہ مانگتے ہیں؟ آپ نے فرمایا: \"جو قرض دار ہو گا وہ بولے گا تو جھوٹ بولے گا اور وعدہ کرے گا تو وعدہ خلافی کرے گا\" ۱؎۔\n§وضاحت\n۱؎: اس لیے آدمی قرض لینے سے طاقت بھر بچے، ایسی نوبت ہی نہ آنے دے کہ قرض لینے کے لیے مجبور ہو، طاقت و قناعت سے کام لے۔","الألباني: صحيح",{"u2":"سیدہ عائشہ رضی اللہ عنھا سے روایت ہے انھوں نے فرمایا:رسول اللہ صلی اللہ علیہ وسلم (جان لیوا)قرض اور گناہ سے بہت زیادۂپناہ طلب فرمایا کرتے تھے۔میں نے کہا:اے اللہ کے رسول!آپ قرض سے اس قدرپناہ کیوں مانگتے ہیں؟آپ نے فرمایا:’’اس لیے کہ جو شخص مقروض ہو جائے (قرض تلے دب جائے)وہ بات کرتا ہے تو جھوٹ بولتا ہے اور وعدہ کرتا ہے تو خلاف ورزی کرتا ہے۔‘","f2":"خلاف ورزی کرتا ہے ‘‘کیونکہ یہ اس کی مجبوری ہوتی ہے اس کے پاس ادائیگی کے لیے کچھ نہیں ہوتا مگر جان چھڑانے کے لیے اسے جان بوجھ کر جھوٹ بولنا پڑتا ہے اور ممکن وعدہ کرنا پڑتا ہے۔اس سے معلوم ہوا کہ یہاں قرض سے مطلق یا معمولی قرض مراد نہیں بلکہ وہ بھاری قرض ہے جس کی ادائیگی اس کے لیے نا ممکن بن جائے۔ اس روایت میں گنا سے مراد بھی ہوہ گنا ہے جو انسان جان بوجھ کر دھڑلے سے کرے‘ یا اس سے مراد وہ گنا ہے جو قرض کے نتیجے میں مقروض کو کرنا پڑتا ہے جیسا کہ ابھی گزرا۔ واللہ اعلم"}],[5455,"شکل بن حمید رضی اللہ عنہ کہتے ہیں کہ میں نبی اکرم صلی اللہ علیہ وسلم کے پاس گیا، میں نے عرض کیا: اللہ کے نبی! مجھے تعوذ سکھائیے جس کے ذریعے میں اللہ کی پناہ مانگوں، آپ نے میرا ہاتھ پکڑا پھر فرمایا: \"کہو، «أعوذ بك من شر سمعي وشر بصري وشر لساني وشر قلبي وشر منيي» میں اللہ تعالی کی پناہ مانگتا ہوں کان کی برائی سے، آنکھ کے کی برائی سے، زبان کی برائی سے، دل کی برائی سے، منی کی برائی سے، یہاں تک کہ یہ چیز مجھے یاد ہو گئی، سعد رضی اللہ عنہ کہتے ہیں: منی سے مراد نطفہ (پانی) ہے۔ وکیع نے الفاظ حدیث میں ابونعیم کی مخالفت کی ہے۔","الألباني: صحيح",{"u2":"سیدنا شکل بن حمید رضی اللہ عنہ نے فرمایا کہ میں نبئ اکرم صلی اللہ علیہ وسلم کے پاس حاضر ہوا اور کہا:اے اللہ کے نبی!مجھے ایسے کلمات سکھائیے جن کے ساتھ میں پناہ حاصل کیا کروں۔آپ نے میرا ہاتھ پکڑ کر ارشاد فرمایا:’’(یوں)کہہ(اے اللہ!)میں اپنے کان ‘آنکھ‘زبان‘دل اور منی کے شر سے تیری پناہ میں آت ہوں۔‘‘حتیٰ کہ میں نے ان کلمات یاد کر لیا۔(راوی حدیث)سعد بن اوس نے کہا:منی سے مراد اس (شخص)کا پانی ‘یعنی نطفہ ہے۔وکیع(ابن الجراح)نے اس حدیث کے لفظوں میں اس(ابو نعیم)کی مخالفت کی ہے۔(اگلی روایت کے الفاظ دیکھنے سے اختلاف صریح طور پر کھل جاتا ہے۔)"}],[5456,"شکل بن حمید رضی اللہ عنہ کہتے ہیں کہ میں نے عرض کیا: اللہ کے رسول! مجھے دعا سکھائیے جس سے میں فائدہ اٹھاؤں، آپ نے فرمایا: \"کہو «اللہم عافني من شر سمعي وبصري ولساني وقلبي ومن شر منيي» اے اللہ! تو مجھے پناہ دے کان، نگاہ، زبان، دل اور منی (نطفہ) کی برائی سے۔","الألباني: صحيح",{"u2":"حضرت شکل بن حمید سے روایت ہے انھوں نے کہا کہ کہ میں نے عرض کی:اے اللہ کے رسول!مجھے کوئی دعاسکھلائیے جس سے میں فائدہ اٹھا سکوں آپ نے فرمایا:’’کہہ:اے اللہ!مجھے میرے کان ‘آنکھ‘زبان ‘دل اور منی ‘یعنی شرم گا ہ کے شر سے محفوظ رکھ۔‘"}],[5457,"حمید بیان کرتے ہیں کہ انس بن مالک رضی اللہ عنہ سے قبر کے عذاب اور دجال کے بارے میں پوچھا گیا تو انہوں نے کہا کہ نبی اکرم صلی اللہ علیہ وسلم فرماتے تھے:«اللہم إني أعوذ بك من الكسل والهرم والجبن والبخل وفتنة الدجال وعذاب القبر» \"اے اللہ! میں تیری پناہ مانگتا ہوں سستی و کاہلی سے، بڑھاپے سے، بزدلی سے، بخیلی اور کنجوسی سے، دجال کے فتنے سے اور قبر کے عذاب سے\"۔","الألباني: صحيح الإسناد",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ سے عذاب قبر اور دجال کے بارے میں پوچھا گیا تو انھوں نے کہا کہ اللہ کے نبئ صلی اللہ علیہ وسلم فرمایا کرتے تھے:’’ اے اللہ!میں کاہلی ‘شدید بڑھاپے ‘بزدلی ‘بخل ‘فتنہ دجال اور عذاب قبر سے (بچنے کے لیے)تیری پناہ حاصل کرتا ہوں۔‘","f2":"سیدنا انس رضی اللہ عنہ کے جواب کا مطلب یہ ہے کہ واقعتاًدجال آئے گا اور عذاب قبر بر حق ہے۔فتنہ دجال س مراد اس کی پیروی کرنا ہے۔یا مقصود یہ ہے کہ ہماری زندگی میں دجال آئے ہی نہ تا کہ ہم اس آزمائش سے بچ جائیں۔ پہلی صورت میں فتنے کے معنیٰ ہوں گے گمراہی جو آزمائش کا نتیجہ بن سکتی ہے۔"}],[5458,"زید بن ارقم رضی اللہ عنہ کہتے ہیں کہ میں تمہیں وہی سکھاتا ہوں جو رسول اللہ صلی اللہ علیہ وسلم ہمیں سکھاتے تھے، آپ فرماتے تھے: «اللہم إني أعوذ بك من العجز والكسل والبخل والجبن والهرم وعذاب القبر اللہم آت نفسي تقواها وزكها أنت خير من زكاها أنت وليها ومولاها اللہم إني أعوذ بك من قلب لا يخشع ومن نفس لا تشبع وعلم لا ينفع ودعوة لا يستجاب لها» \"اے اللہ! میں تیری پناہ مانگتا ہوں، عاجزی و مجبوری اور بے بسی سے، کاہلی سے، بخیلی و کنجوسی سے، بزدلی و کم ہمتی سے، بڑھاپے سے، قبر کے عذاب سے، اللہ! تو میرے نفس کو تقوی عطا کر، اسے (برائیوں سے) پاک کر دے، تو ہی بہترین پاک کرنے والا ہے، تو ہی اس کا مالک اور سر پرست ہے، اے اللہ! میں ایسے دل سے تیری پناہ مانگتا ہوں جس میں تیرا ڈر نہ ہو، ایسے نفس سے جو سیراب نہ ہو، ایسے علم سے جو نفع بخش اور مفید نہ ہو، اور ایسی دعا سے جو قبول نہ ہو سکے\"۔","الألباني: صحيح",{"u2":"سیدنا زید بن ارقم رضی اللہ عنہ نے فرمایا:میں تمہیں وہی دعا سکھلاؤں گا جو رسول اللہ صلی اللہ علیہ وسلم ہمیں سکھایا کرتے تھے۔آپ فرماتے تھے:’’اے اللہ!میں نکمے پن ‘کاہلی‘کنجوسی‘بزدلی ‘شدید بڑھاپے اور عذاب قبر سے تیری پناہ میں آتا ہوں۔اے اللہ!میرے نفس کو تقوٰی عطا فرما اور اس کو پاکیزہ فرما تو ہی بہترین پاکیزہ فرمانے والا ہے۔ تو ہی اس کا مدد گار اور مالک ہے۔ اے اللہ!تیری پناہ کا طلب گار ہوں اس دل سے جو تیرےسامنے عاجز نہ ہو ‘اس نفس سے جو سیر نہ ہو ‘اس علم سے جو مفید نہ ہو اور دعا سے جو قبول نہ ہو۔‘","f2":"تفصیل کے لیے دیکھیے ‘حدیث:5444"}],[5459,"انس رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «اللہم إني أعوذ بك من العجز والكسل والبخل والجبن والهرم وعذاب القبر وفتنة المحيا والممات» \"اے اللہ! میں تیری پناہ مانگتا ہوں عاجزی و بے بسی، سستی و کاہلی، بخیلی و کنجوسی، بزدلی و کم ہمتی، بڑھاپے، قبر کے عذاب اور موت و زندگی کے فتنے سے\"۔","الألباني: صحيح",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے اللہ کے نبی صلی اللہ علیہ وسلم نے یوں دعا فرمائی:’’اے اللہ!میں نکمے پن ‘کاہلی‘کنجوسی‘بزدلی‘ذلیل بڑھاپے ‘عذاب قبر اور زندگی و موت کے فتنے سے (بچنے کے لیے)تیری پناہ حاصل کرتاہوں۔‘","f2":"تفصیل کے لیےدیکھیے:5445‘5447‘5450۔"}],[5460,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم فرماتے تھے: «اللہم إني أعوذ بك من الفقر وأعوذ بك من القلة والذلة وأعوذ بك أن أظلم أو أظلم» \"اے اللہ! میں فقر و غربت سے تیری پناہ مانگتا ہوں، کمی اور ذلت سے پناہ مانگتا ہوں، ظلم کرنے اور ظلم کیے جانے سے تیری پناہ مانگتا ہوں\"۔ (ابوعبدالرحمٰن نسائی کہتے ہیں) اوزاعی نے حماد کی مخالفت کی ہے ۱؎۔\n§وضاحت\n۱؎: یعنی دونوں کی روایتوں میں اسحاق بن عبداللہ بن ابی طلحہ کے شیخ مختلف ہیں، کیونکہ حماد کی روایت میں سعید بن یسار ہیں جب کہ اوزاعی کی روایت میں ان کے شیخ جعفر بن عیاض ہیں، :(جو ضعیف ہیں ) نیز ان دونوں کے الفاظ بھی مختلف ہیں۔","الألباني: صحيح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم فرمایا کرتے تھے:’’اے اللہ!میں فقر سے تیری پناہ میں آتا ہوں اور قلت اور ذلت سے تیری پناہ حاصل کرتا ہوں‘نیز اس بات سے بھی تیری پناہ چاہتا ہوں کہ میں کسی پر ظلم کروں یا کسی کے ظلم کا تختۂ مشق بنوں۔‘‘\nاوزاعی نے اس(حماد بن سلمہ)کی مخالفت کی۔","f2":"اوزاعی نے اس حدیث کے بیان کرنے میں حماد بن سلمہ کی مخالفت کی ہے اور وہ اس طرح کہ حماد بن سلمہ نے اسحاق بن عبد اللہ سے بیان کرتے ہوئے کہا ہے:عن سعید بن یسار عن ابی ہریرۃ جبکہ اوزاعی نے اسحاق بن عبد اللہ سے بیان کیا ہے تو کہا ہے:حدثنی جعفر بن عیاض‘قال حدثنی ابی ہریرۃ‘یعنی اوزاعی نے سعید بن یسار کی بجائے جعفر بن عیاض کہا ہے۔واللہ اعلم\n(1) سنن ابوداؤد مترجم ‘مطبوعہ دارالسلام ‘حدیث:1544 کے فائدے میں ابو عمار عمر فاروق سعیدی ﷾ رقم طراز ہیں کہ فقر دو طرح سے ہوتا ہے:مال کا یا دل کا۔انسان کے پاس مال نہ ہو مگر دل کا غنی اور سیر چشم ہو تو یہ ممدوح ہے مگر اس کے بر عکس انسان’’حرص‘‘کا مریض ہو تو یہ بہت ہی قبیح خصلت ہے ‘نیز فقیری اور غریبی کی کیفیت کہ انسان ضروریات زندگی کے حصول سے محروم اور عاجز ہو کر لازمی واجبات کی ادا نہ کر سکے ‘اس سے رسول اللہ صلی اللہ علیہ وسلم نے پناہ مانگی ہے۔قلت سے مراد اعمال خیر اور ان کے اسباب کی قلت ہے اور ذلت یہ کہ انسان عصیان (اللہ تعالی ٰ نافرمانی)کا مرتکب ہو کر الل کے سامنے رسوا ہو جائے یا لوگوں کی نظروں میں اس کا وقار نہ رہے کہ اس کی دعوت ہی نہ سنی جائے۔اس سے اللہ تعالیٰ کی پناہ مانگنے کی تعلیم دی گئی ہے۔ اسی طراح انسان کا اپنے معاشرے میں ظالم بن جانا یا مظلوم بن جانا ‘کوئی بھی صورت ممدوح نہیں۔(2)فقر سے مراد وہ فقر بھی ہو سکتا ہے جس سے کفر اور گمراہی کا خطرہ ہو کیونکہ عوام الناس کے لیے فقر گمراہی کا ذریعہ بن سکتا ہے۔ہاں اللہ تعالیٰ کے خاص بندوں کے لیے مالی فقر ایک نعمت ہے۔آپ کی دعائیں دراصل اوت کےلیے تعلیم ہیں۔یا فقر سے مراد جسے انسان برداشت نہ کر سکے اور دست سوال دراز کرنے پر مجبور ہو جاۓ۔فقر سے فقرقلب بھی مراد ہو سکتا ہے جیسا کہ گزشتہ سطور میں ذکر ہوا۔ (3)قلت سے مراد افراد بھی ہو سکتی ہے اور قلت مال بھی جسے اوپر فقر کہا گیا ہے ورنہ کثرت مال تو بسا اوقات گمراہی کا سبب بن جاتی ہے۔ذلت سے مراد اوگوں کا غلبہ ہے کہ آدمی اپنا حق بھی حاصل نہ کر سکے۔تفصیل کے لیے دیکھیے ‘حدیث:5451۔(4) اس حدیث میں ہر بعد والا لفظ پہلے کا نتیجہ ہے فقر سے قلت پیدا ہوتی ہے ‘قلت ذلت کو جنم دیتی ہے اور ذلت انسان کو مظلوم بنا دیتی ہے۔یا وہ ت"}],[5461,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"فقر سے، قلت، کمی اور ذلت سے اور ظلم کرنے اور کیے جانے سے اللہ کی پناہ مانگو\"۔","الألباني: ضعيف",{"u2":"سیدنا ابوھریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’تم فقر ‘قلت ‘ذلت اور اس بات سے اللہ تعالیٰ کی پناہ مانگا کرو کہ تم کسی پر ظلم کرو یا کسی کے ظلم وستم کا نشانہ بنو۔‘","f2":":یہ روایت امر (حکم) کے صیغے کے ساتھ ضعیف ہے کیونکہ اس کی سند میں جعفر بن عیاض مجہول راوی ہے ‘تا ہم آپکے فعل کے طور پر ثابت ہے کہ آپ یہ دعا پڑھا کرتے تھے جیسا کہ سابقہ روایت میں ہے۔"}],[5462,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ آپ کہا کرتے تھے: «اللہم إني أعوذ بك من القلة والفقر والذلة وأعوذ بك أن أظلم أو أظلم»\"اے اللہ! میں قلت سے، فقر سے، ذلت سے، تیری پناہ مانگتا ہوں اور ظلم کرنے اور کئے جانے سے تیری پناہ مانگتا ہوں\"۔","",{"u2":"سیدنا ابو ھریرہ رضی اللہ عنہ سے مروی ہے کہ بنئ اکرم صلی اللہ علیہ وسلم فومایا کرتے تھے:’’اے اللہ!میں قلت فقر اور ذلت سے (بچنے کے لیے)تیری پناہ میں آتا ہوں۔اور اس بات سے بھی تیری پناہ مانگتا ہوں کہ میں ظلم کروں یا مجھ پر ظلم کیا جائے۔‘"}],[5463,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"فقر سے، قلت اور ذلت سے اور ظلم کرنے اور کیے جانے سے اللہ کی پناہ مانگو\"۔","",{"u2":"حضرت ابوھریرہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’تم فقر ‘قلت ‘ذلت اور ظالم یا مظلوم بننے سے اللہ تعالیٰ کی پناہ مانگا کرو۔‘","f2":":تفصیل کے لیے دیکھیے فائدہ حدیث:5463۔"}],[5464,"ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی سے پناہ مانگو فقر سے، قلت اور ذلت سے اور ظلم کرنے اور کیے جانے سے\"۔","الألباني: ضعيف",{"u2":"حضرت ابوھریرہ نے بیان فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’تم فقر‘قلت‘ذلت اور ظالم یا مظلوم بننے سے اللہ تعالیٰ کی پناہ حاصل کیا کرو۔‘‘","f2":"تفصیل کے لیے دیکھیے فائدہ حدیث:5463۔"}],[5465,"مسلم بن ابی بکرہ بیان کرتے ہیں کہ میں نے نماز کے بعد اپنے والد کو یہ دعا مانگتے ہوئے سنا: «اللہم إني أعوذ بك من الكفر والفقر وعذاب القبر»\"اے اللہ! میں تیری پناہ چاہتا ہوں کفر سے، فقر سے، اور عذاب قبر سے\"، تو میں بھی وہی دعا کرنے لگا، وہ بولے: اے میرے بیٹے! تم نے (دعا کے) یہ کلمات کہاں سے سیکھے؟ میں نے عرض کیا: ابو جان! میں نے آپ کو نماز کے بعد (یا نماز کے اخیر میں) یہی دعا مانگتے سنا۔ تو میں نے آپ سے ہی یہ لیے ہیں، وہ بولے: میرے بیٹے! اس دعا کو لازم کر لو، اس لیے کہ نبی اکرم صلی اللہ علیہ وسلم بھی نماز کے بعد یہ دعا مانگتے تھے ۱؎۔\n§وضاحت\n۱؎: حدیث میں «دبر الصلاۃ» جس کے معنی \" نماز کے بعد \" بھی ہو سکتے ہیں، اور نماز کے اخیر میں بھی ہو سکتے ہیں، دونوں معنوں میں یہ لفظ وارد ہوا ہے، لیکن بقول شیخ الاسلام ابن تیمیہ سلام سے پہلے دعا کی قبولیت زیادہ متوقع ہے، بمقابلہ سلام کے بعد کے، کیونکہ سلام سے پہلے بندہ اللہ تعالی سے زیادہ قریب ہوتا ہے۔","الألباني: صحيح الإسناد",{"u2":"حضرت مسلم بن ابی بکرہ رحمہ اللہ سے روایت ہے کہ انھوں نے اپنے والد (سیدنا ابو بکرہ رضی اللہ عنہ)کو نماز کے بعد یہ دعا پڑھتے سنا:’’اے اللہ!میں کفر فقر اور عذاب قبر سے (بچنے کے لیے)تیری پناہ میں آتا ہوں۔‘‘میں بھی یہ دعا پڑھنے لگ گیا۔ (ایک دفعہ)انھوں نے مجھ سے کہا بیٹا!یہ کلمات تو نے کہاں سے سیکھے ہیں؟میں نے کہا: ابا جان!میں نے ڑپ کو نماز کے بعد یہ کلمات پڑھتے سنا تو میں نے آپ سے سن کر یاد کر لیے۔انھوں نے فرمایا:پیارے بیٹے!ان پر پابندی کرنا کیونکہ اللہ کے نبی صلی اللہ علیہ وسلم نماز کے بعد ان کلمات کے ساتھ دعا فرمایاکرتے تھے۔","f2":"نماز کے بعد‘‘’’عربی لفظ دُبُر استعمال ہوا ہے جس کے معنیٰ بعد بھی ہے اور آخر بھی‘ لہذا دوسرا ترجمہ یہ ہو سکتا ہے ’’نماز کے آخر میں ‘‘یعنی درود پڑھنے کے بعد پڑھی جانے والی دعاؤں میں ‘سلام سے پہلے۔واللہ اعلم"}],[5466,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم اکثر ان کلمات کے ذریعہ دعا مانگتے تھے: «اللہم إني أعوذ بك من فتنة النار وعذاب النار وفتنة القبر وعذاب القبر وشر فتنة المسيح الدجال وشر فتنة الفقر وشر فتنة الغنى اللہم اغسل خطاياى بماء الثلج والبرد وأنق قلبي من الخطايا كما أنقيت الثوب الأبيض من الدنس وباعد بيني وبين خطاياى كما باعدت بين المشرق والمغرب اللہم إني أعوذ بك من الكسل والهرم والمأثم والمغرم» \"اے اللہ! میں تیری پناہ مانگتا ہوں آگ کے فتنے، جہنم کے عذاب سے، قبر کے فتنے سے، قبر کے عذاب سے، مسیح دجال کے فتنے کے شر سے، فقر کے فتنے کے شر سے، مالداری کے فتنے کے شر سے، اے اللہ! میرے گناہ برف اور اولے کے پانی سے دھو دے، میرا دل گناہوں سے پاک کر دے جیسے تو نے سفید کپڑا گندگی سے صاف کیا ہے، اور مجھ میں اور میرے گناہوں میں دوری پیدا کر دے جیسے تو نے پورب اور پچھم کے درمیان کی ہے۔ اے اللہ! میں کاہلی، بڑھاپے، گناہ اور قرض سے تیری پناہ مانگتا ہوں\"۔","الألباني: صحيح",{"u2":"۔سیدہ عائشہ رضی اللہ عنھا نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم بسا اوقات ان کلمات کے ساتھ دعا فرمایاکےتے تھے:’’اے اللہ میں آگ تک پہنچانے والے فتنے ‘آگ کے عذاب ‘فبر کی آزمائش ‘عذاب قبر ‘مسیح دجال کے فتنے کی خرابی ‘آزمائش فقر کی خرابی اور آزمائش دولت کی خرابی سے تیری پناہ میں آتا ہوں۔اے اللہ!میری غلطیوں کو برف کے پانی اور اولوں سے دھو ڈال.اور میرے دل کو غلطیوں کے اثرات سے یوں صاف فرما دے ‘جیسے تو نے سفید کپڑے کو میل کچیل سے صا ف رکھا ہے ‘نیز میرے اور میری غلطیوں کے درمیان اتنا فاصلہ فرما دے جتنا فاصلہ تو نے مشرق اور مغرب کے درمیان رکھا ہے۔اے اللہ!کاہلی شدید پڑھاپے ‘گناہ اور جان لیوا قرض سے تیری پناہ چاہتا ہوں۔‘‘","f2":"(1)فتنہ دراصل کسی چیز کی آزمائش کو کہا جاتا ہے ‘مثلاًسونے کو آگ میں ڈال کر کھرے کھو ٹے کو جاننا۔انسان کو بھی مختلف چیزوں کے ساتھ آزمائش میں ڈالا جاتا ہے ‘مثلاًفقر اور دولت وغیرہ تا کہ اس کا ایمان یا کفر ظاہر ہو سکے۔اسی طرح دجال کے ذریعے سے بھی لوگوں کی آزمائش ہو گی۔قبر کے سوال و جواب سے بھی ایمان وکفر کا پتا چلے گا ‘اس لیے ان چیزوں کو فتنہ کہا گیا ہے۔(2)فتنہ قبر سے مراد سوال و جواب ہیں جو فرشتوں اور مدفون انسان کے درمیان ہوتے ہیں۔اور ان فتنوں کی خرابی سے مرا دیہ ہے کہ ان چیزوں کے ساتھ آزمائش کے دوران انسان ناکام ہو جائے اور ایمان کے بجائے کفر ظاہر ہو۔(3)غلطیوں کو دھو ڈالنے کا مفہوم ملا خط فرمائیے ‘حدیث:61 اور 896۔"}],[5467,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کہا کرتے تھے: «اللہم إني أعوذ بك من الأربع من علم لا ينفع ومن قلب لا يخشع ومن نفس لا تشبع ومن دعا لا يسمع» \"اللہ! میں چار چیزوں سے تیری پناہ مانگتا ہوں: ایسے علم سے جو نفع بخش اور مفید نہ ہو، ایسے دل سے جس میں (اللہ کا) ڈر نہ ہو، ایسے نفس سے جو سیراب نہ ہو، اور ایسی دعا سے جو (اللہ کے یہاں) قبول نہ ہو\"۔","الألباني: صحيح",{"u2":"حضرت ابوھریرہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم فرمایا کرتے تھے:’’اے اللہ!میں چار چیزوں سے تیری پناہ طلب کرتا ہوں: اس علم سے جو نفع نہ دے ‘اس دل سے جو اللہ تعالیٰ کے سامنے خشوع وخضوع نہ کرے ‘اس نفس سے سیر نہ ہو اور ایسی دعا سے جو قبول نہ ہو۔","f2":"فائدہ:تفصیل کے لیے دیکھیے ‘حدیث:5444۔"}],[5468,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کہا کرتے تھے: «اللہم إني أعوذ بك من الجوع فإنه بئس الضجيع وأعوذ بك من الخيانة فإنها بئست البطانة» \"اے اللہ! میں بھوک سے تیری پناہ مانگتا ہوں کیونکہ وہ برا ساتھی ہے، اور خیانت سے پناہ مانگتا ہوں کیونکہ وہ بری خصلت(عادت) ہے\"۔","الألباني: حسن صحيح",{"u2":"سیدنا ابوھریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم فرمایا کرتے تھے:’’اے اللہ!میں بھوک سے تیری پناہ چاہتا ہوں کیونکہ یہ بدترین ساتھی ہے۔اور خیانت سے بھی پناہ چاہتا ہوں کیونکہ یہ بد ترین خصلت ہے۔‘","f2":"(1)بھوک لازمۂ انسان ہے اس سے مف رنہیں ‘لہذا اس بھوک سے مراد سے مراد مطلق بھوک نہیں بلکہ مسلسل بھوک ہے جسے حدیث:5462 میں فقرکے لفظ سے بیان کیا گیا ہے ‘یعنی انسان کھانے پینے کے لیے اتنا کچھ نہ بھی پا سکے جس سے اپنی بھوک مٹاتا رہے۔استعارۃًبھوک سے ’’حرص‘‘مراد لی جا سکتی ہے۔پھر دنیا کی بھوک مراد ہو گی کیونکہ نیکی کی حرص تو اچھی چیز ہے۔دنیا کی حرص اس لیے مذموم ہے کہ یہ‘\nکبھی ختم نہیں ہوتی جب کہ دنیا تھوڑی ہی ہے۔بادشاہوں کی جوع الارض(مملکت وسیع کرنے کی خوہش)بھی دنیا کی حرص کی صورت ہے جو آخ کار ان کی ہلاکت کا باعث بنتی ہے۔(2)خیانت حقوق اللہ میں ہو یا حقوق العباد میں ‘قابل مذمت ہے کیونکہ یہ ایمان کے منافی ہے۔نفاق کی دلیل ہے۔ اعا ذنا اللہ منھما۔آمین"}],[5469,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم فرماتے تھے: «اللہم إني أعوذ بك من الجوع فإنه بئس الضجيع ومن الخيانة فإنها بئست البطانة» \"اے اللہ! میں بھوک سے تیری پناہ مانگتا ہوں کیونکہ وہ برا ساتھی ہے اور خیانت سے کیونکہ وہ بری خصلت (عادت) ہے\"۔","الألباني: حسن صحيح",{"u2":"سیدنا ابوھریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم فرمایا کرتے تھے:’’اے اللہ!میں بھوک سے تیری پناہ چاہتا ہوں کیونکہ یہ بدترین ساتھی ہے۔اور خیانت سے بھی پناہ چاہتا ہوں کیونکہ یہ بد ترین خصلت ہے۔‘"}],[5470,"انس رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم یہ دعائیں مانگتے تھے: «اللہم إني أعوذ بك من علم لا ينفع وقلب لا يخشع ودعا لا يسمع ونفس لا تشبع» \"اللہ! میں ایسے علم سے تیری پناہ مانگتا ہوں جو مفید اور نفع بخش نہ ہو، ایسے دل سے جس میں (اللہ کا) ڈر نہ ہو، ایسی دعا سے جو قبول نہ ہو اور ایسے نفس سے جو سیراب نہ ہو\"، پھر فرماتے: «اللہم إني أعوذ بك من هؤلاء الأربع » \"اے اللہ! میں ان چاروں سے تیری پناہ مانگتا ہوں\"۔\n§وضاحت\n۱؎: اس حدیث کا اس باب سے کوئی تعلق بظاہر نظر نہیں آتا، شاید نسّاخ کی غلطی سے یہاں درج ہو گئی ہے۔","الألباني: صحيح",{"u2":"سیدنا انس رضی اللہ عنہ سے منقول ہے کہ نبئ اکرم صلی اللہ علیہ وسلم یہ دعائیں فرمایا کرتے تھے:’’اے اللہ!میں تیری پناہ میں آتا ہوں ایسے علم سے جو نفع نہ دے ‘ایسے دل سے جس میں (اللہ تعالیٰ کا)ڈر نہ ہو ‘ایسی دعا سے جو سنی نہ جائے (قبول نہ کی جائے۔)اور ایسے نفس سے سیر نہ ہو۔‘‘پھر فرماتے:’’اے اللہ!میں ان چاروں چیزوں سے تیری پناہ کا طالب ہوں۔‘","f2":"یہ حدیث صراحتاًباب سے مطابقت نہیں رکھتی بلکہ آئندہ حدیث باب کے مطابق ہے۔معلوم ہوتا ہے کہ یہ حدیث کسی ناسخ کی غلطی سے یہاں لکھی گئی ہے"}],[5471,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم دعا کرتے تھے، «اللہم إني أعوذ بك من الشقاق والنفاق وسوء الأخلاق» \"اے اللہ! میں دشمنی، نفاق اور برے اخلاق سے تیری پناہ مانگتا ہوں\"۔","الألباني: ضعيف",{"u2":"سیدنا ابوھریرہ رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم یہ دعا فرمایا کرتے تھے:’’اے اللہ!میں مخالفت و دشمنی ‘نفاق اور بد اخلاق سے تیری پناہ میں آتا ہوں۔‘"}],[5472,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم قرض اور معصیت (گناہ) سے کثرت سے اللہ تعالی کی پناہ مانگتے تھے، آپ سے عرض کیا گیا: اللہ کے رسول! آپ قرض اور معصیت (گناہ) سے کثرت سے اللہ کی پناہ مانگتے ہیں؟ تو آپ نے فرمایا: \"آدمی جب مقروض ہوتا ہے تو جب باتیں کرتا ہے جھوٹ بولتا ہے، اور جب وعدہ کرتا ہے تو وعدہ خلافی کرتا ہے\"۔","الألباني: صحيح",{"u2":"سیدہ عائشہ رضی اللہ عنھا سے روایت ہے ‘انھوں نے فرمایا:رسول اللہ صلی اللہ علیہ وسلم قرض اور گناہ سے بہت زیادہ پناہ طلب کیا کرتے تھے۔آپ سے عرض کی گئی:اے اللہ کے رسول!(کیا وجہ ہےکہ)آپ قرض اور گناہ سے بہت زیادہ پناہ طلب فرماتے ہیں؟آپ نے فرمایا:’’آدمی جب مقروض ہو جاتا ہے پھر بات کرتا ہے تو جھوٹ بولتا ہے اور وعدہ کرتا ہے تو خلاف ورزی کرتا ہے۔‘","f2":"دیکھیے رواین:5456)"}],[5473,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: «أعوذ باللہ من الكفر والدين» \"میں کفر اور قرض سے اللہ کی پناہ چاہتا ہوں\"، ایک شخص نے کہا: اللہ کے رسول! آپ کفر اور قرض کا درجہ برابر کر رہے ہیں؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہاں\"۔","الألباني: ضعيف",{"u2":"سیدنا ابوسعید رضی اللہ عنہ سے روایت ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:’’میں کفر اور قرض سے اللہ تعالیٰ کی پناہ میں آتا ہوں۔‘‘ایک آدمی نے کہا:اے اللہ کے رسول!کیا آپ قرض کو کفر کے برابر قرار دیتے ہیں؟رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ہاں۔‘‘"}],[5474,"ابو سعید خدری رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «أعوذ باللہ من الكفر والدين» \"میں کفر اور قرض سے اللہ کی پناہ مانگتا ہوں\"، ایک شخص نے کہا: آپ قرض اور کفر کو برابر کر رہے ہیں؟ آپ نے فرمایا: \"ہاں\"۔","الألباني: ضعيف",{"u2":"سیدنا ابوسعید رضی اللہ عنہ سے منقول ہے کہ نبئ اکرم صلی اللہ علیہ وسلم نے فرمایا:’’میں کفر اور کسی کے واجب الا داحق(کی حالت میں موت)سے اللہ تعالیٰ سے پناہ مانگتا ہوں۔‘‘ایک آدمی نے کہا:کیا آپ واجب الاداحق کو کفر کے برابر رکھ رہے ہیں؟آپ نے فرمایا:’’ہاں۔‘"}],[5475,"عبداللہ بن عمرو بن العاص رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم، دعا میں یہ کلمات کہتے تھے: «اللہم إني أعوذ بك من غلبة الدين وغلبة العدو وشماتة الأعداء» \"اے اللہ! میں قرض کے غلبے، دشمن کے غلبے اور مصیبت میں دشمنوں کی خوشی سے تیری پناہ چاہتا ہوں\"۔\n§وضاحت\n۱؎: «شماتت اعداء» یہ ہے کہ دشمن پہنچنے والی مصیبت پر خوشی کا اظہار کرے۔","الألباني: صحيح",{"u2":"حضرت عبد اللہ بن عمر و بن عاص رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم ان کلمات کے ساتھ دعا فرمایا کرتے تھے:’’اے اللہ!میں قرض اور واجب الادا حق کے غلبے (اور بوجھ)‘دشمن کے غلبے اور دشمنوں کی دل آزار خوشی سے تیری پناہ چاہتا ہوں۔‘","f2":"1۔غلبے مراد یہ ہے کہ میں اسے ادا کےنے سے عاجز آ جاؤں اور اپنے سر پر لے کر مر جاؤں۔(2)’’دل آزار خوشی ‘‘سے مراد وہ خوشی ہے جو کسی دوسرے کی مصیبت پر کی جائے جیسا کہ دشمنوں کا دستور ہے۔مقصود یہ ہے مولا!مجھے ایسے مصائب سے محفوظ رکھنا جس سے دشمن خوش ہوں۔یہاں ان کی ذاتی خوشی مراد نہیں۔"}],[5476,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کہا کرتے تھے: «اللہم إني أعوذ بك من الهم والحزن والكسل والبخل والجبن وضلع الدين وغلبة الرجال» \"اے اللہ! فکر و سوچ، رنج و غم، کاہلی و بزدلی، بخیلی و کنجوسی، قرض کے بوجھ اور لوگوں کے غلبے سے تیری پناہ مانگتا ہوں\"۔","الألباني: صحيح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ نبئ اکرم صلی اللہ علیہ وسلم یوں فرمایا کرتے تھے:’’اے اللہ!میں فکرو غم ‘کاہلی اور بزدلی ‘کنجوسی‘قرض کے بوجھ اور لوگوں کے غلبے سے تیری پناہ چاہتا ہوں۔‘"}],[5477,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کہا کرتے تھے: «اللہم إني أعوذ بك من عذاب القبر وفتنة النار وفتنة القبر وعذاب القبر وشر فتنة المسيح الدجال وشر فتنة الغنى وشر فتنة الفقر اللہم اغسل خطاياى بماء الثلج والبرد ونق قلبي من الخطايا كما نقيت الثوب الأبيض من الدنس اللہم إني أعوذ بك من الكسل والهرم والمغرم والمأثم» \"اے اللہ! میں قبر کے عذاب، جہنم کے فتنے، قبر کے فتنے، قبر کے عذاب، مسیح دجال کے فتنے کی برائی، مال داری کے فتنے کی برائی، اور فقر کے فتنے کی برائی سے تیری پناہ مانگتا ہوں، اے اللہ! میرے گناہوں کو برف اور اولے کے پانی سے دھو دے، اور میرے دل کو گناہوں سے اسی طرح صاف کر دے جیسے تو نے سفید کپڑے کو میل کچیل سے صاف کیا ہے، میں سستی، کاہلی، بڑھاپے، قرض اور گناہ سے پناہ مانگتا ہوں\"۔","الألباني: صحيح",{"u2":"سیدہ عائشہ رضی اللہ عنھا نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم یوں فرمایا کرتے تھے:’’اے اللہ!میں قبر کے عذاب ‘آگ تک پہنچانے والے فتنے ‘قبر کی آزمائش ‘قبر کی تکلیف ‘مسیح دجال کے فتنے کی خرابی ‘فتنہ مالداری کی خرابی اور فتنہ فقر کی خرابی سے تیری پناہ میں آتا ہوں۔ اے اللہ!میر ی غلطیوں کو برف کے پانی اور اولوں سے دھو دے۔جیسے تو نے سفید کپڑے کو میل کچیل سے صاف رکھا ہے۔اے اللہ!میں کاہلی ‘شدید بڑھاپے ‘قرض اور گناہ سے تیری پناہ چاہتا ہوں۔‘‘","f2":"دیکھیے روایت:5467"}],[5478,"مصعب بن سعد کہتے ہیں کہ سعد رضی اللہ عنہ انہیں دعا کے یہ کلمات سکھاتے اور انہیں نبی اکرم صلی اللہ علیہ وسلم سے روایت کرتے «اللہم إني أعوذ بك من البخل وأعوذ بك من الجبن وأعوذ بك من أن أرد إلى أرذل العمر وأعوذ بك من فتنة الدنيا وعذاب القبر» \"اے اللہ! میں بخل و کنجوسی سے تیری پناہ مانگتا ہوں، بزدلی سے تیری پناہ مانگتا ہوں اور اس بات سے پناہ مانگتا ہوں کہ میں لاچاری و مجبوری کی عمر کو پہنچوں، دنیا کے فتنے اور قبر کے عذاب سے تیری پناہ مانگتا ہوں\"۔","الألباني: صحيح",{"u2":"حضرت مصعب بن سعد سے مروی ہے کہ (الد محترم)سیدنا سعد رضی اللہ عنہ اسے یہ کلمات سکھایا کرتے تھے اور انھیں نبئ اکرم صلی اللہ علیہ وسلم سے بیان فرماتے تھے:’’اے اللہ!میں بخل سے تیری پناہ میں آتا ہوں۔میں بزدلی سے تیری پناہ میں آتا ہوں۔میں اس بات سے بھی تیری پناہ میں آتا ہوں کہ مجھے ذلیل ترین میں داخل کیا جائے۔میں دنیا کے فتنے اور عذاب فبر سے تیری پناہ حاصل کرتا ہوں۔‘","f2":"دنیا کے فتنے سے مراد یہ ہے کہ میں دنیا کی رنگینیوں میں کھو کر آخرت سے غافل ہو جاؤں یا وہ تکالیف شاقہ مراد ہیں جو انسانی بس سے باہر ہوں۔"}],[5479,"مصعب بن سعد اور عمرو بن میمون اودی سے روایت ہے کہ سعد رضی اللہ عنہ اپنے بیٹوں کو یہ کلمات سکھاتے جیسے استاذ بچوں کو سکھاتا ہے، اور کہتے کہ رسول اللہ صلی اللہ علیہ وسلم بھی ہر نماز کے آخر میں انہیں کلمات کے ذریعے پناہ مانگتے تھے «اللہم إني أعوذ بك من البخل وأعوذ بك من الجبن وأعوذ بك من أن أرد إلى أرذل العمر وأعوذ بك من فتنة الدنيا وعذاب القبر» \"اے اللہ! میں بخل و کنجوسی سے تیری پناہ مانگتا ہوں، بزدلی و کم ہمتی سے تیری پناہ چاہتا ہوں، لاچاری و مجبوری کی عمر سے تیری پناہ چاہتا ہوں اور دنیا کے فتنے اور قبر کے عذاب سے تیری پناہ مانگتا ہوں\"۔","الألباني: صحيح",{"u2":"حضؤت مصعب بن سعد اور عمرو بن میمون اودی سے روایت ہے ‘انھوں نے کہا سیدنا سعد رضی اللہ عنہ اپنے بیٹوں کو یہ کلمات اس طرح سکھاتے تھے جس طرح استاد بچوں کو سبق رٹاتا ہے۔وہ فرماتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم ہر (فرض)نماز کے بعد ان کلمات کے ساتھ اللہ تعالیٰ کی پناہ مانگا کرتے تھے:’’اے اللہ!میں کنجوسی سے تیری پناہ میں آتا ہوں۔میں بزدلی سے تیری پناہ میں آتا ہوں۔میں تیری پناہ چاہتا ہوں اس سے کہ مجھے ذلیل ترین عمر میں پہنچایاجائے اور دنیا کے فتنے او ر قبر کے عذاب سے تیری پناہ میں آتا ہوں۔‘"}],[5480,"عمر رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم بزدلی و کم ہمتی، کنجوسی و بخیلی، بری اور لاچاری و مجبوری کی عمر، سینے کے فتنے اور قبر کے عذاب سے اللہ تعالی کی پناہ مانگتے تھے۔","",{"u2":"سیدنا عمر رضی اللہ عنہ سے روایت ہے کہ نبئ اکرم صلی اللہ علیہ وسلم بزدلی‘کنجوسی ‘بری عمر‘سینے اور دل کے فتنے اور عذاب قبر سے اللہ تعالیٰ کی پناہ طلب فرمایا کرتے تھے۔","f2":"دیکھیے روایات:5446‘5447۔"}],[5481,"عمرو بن میمون کہتے ہیں کہ میں نے عمر بن خطاب رضی اللہ عنہ کو کہتے ہوئے سنا: رسول اللہ صلی اللہ علیہ وسلم پانچ چیزوں سے اللہ کی پناہ مانگتے تھے: «اللہم إني أعوذ بك من الجبن والبخل وسوء العمر وفتنة الصدر وعذاب القبر» \"اے اللہ! میں بزدلی، کنجوسی، بری عمر، دل کے فتنے اور قبر کے عذاب سے تیری پناہ چاہتا ہوں\"۔","",{"u2":"سیدنا عمر بن خطاب رضی اللہ عنہ نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم پانچ چیزوں سے اللہ تعالیٰ کی پناہ طلب فرمایا کرتے تھے:’’اے اللہ!میں بزدلی‘کنجوسی ‘بری عمر‘سینے کے فتنے اور قبر کے عذاب سے تیری پناہ میں آتا ہوں۔‘‘"}],[5482,"عمرو بن میمون کہتے ہیں کہ مجھ سے صحابہ کرام رضی اللہ عنہم نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم بخیلی، بزدلی، سینے کے فتنے اور قبر کے عذاب سے اللہ کی پناہ مانگتے تھے۔","",{"u2":"حضرت عمر بن میمون نے کہا کہ مجھے بہت سے اصحاب رسول رضی اللہ عنہم نے بیان فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم حرص‘کنجوسی ‘بزدلی ‘سینے کے فتنے اور عذاب قبر سے اللہ تعالیٰ کی پناہ مانگا کرتے تھے۔"}],[5483,"عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"ناحق جو بھی خون ہوتا ہے اس کے گناہ کا ایک حصہ آدم کے اس بیٹے پر جاتا ہے جس نے سب سے پہلے قتل کیا، کیونکہ اسی نے سب سے پہلے (ناحق) خون کرنے کی کا راستہ نکالا\"۔\nعبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ لوگوں کے درمیان قیامت کے روز سب سے پہلے خون کا فیصلہ کیا جائے گا۔\nانس رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کے پاس قبیلہ عکل یا عرینہ کے چند آدمی آئے، انہیں جب مدینے کی آب و ہوا راس نہیں آئی تو آپ صلی اللہ علیہ وسلم نے اونٹوں کا یا دودھ والی اونٹنیوں کا دودھ اور پیشاب پینے کا حکم دیا، تو انہوں نے چرواہے کو قتل کیا اور اونٹ ہانک لے گئے۔ نبی اکرم صلی اللہ علیہ وسلم نے ان کی تلاش میں کچھ لوگوں کو روانہ کیا اور ان کے ہاتھ پیر کاٹ دیے، اور ان کی آنکھیں پھوڑ دیں۔\nعمرو بن میمون کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم اللہ تعالی کی پناہ مانگتے تھے۔ یہ روایت مرسل ہے۔","الألباني: صحيح",{"u2":"حضرت عمر بن میمون سے مرسل روایت ہے کہ نبئ اکرم صلی اللہ علیہ وسلم ان چیزوں سے پناہ طلب کیا کرتے تھے۔","f2":"یہاں مرسل کا مطلب یہ ہے کہ انہوں نے کسی صحابی کا ذکر نہیں کیا۔"}],[5484,"شکل بن حمید رضی اللہ عنہ کہتے ہیں کہ میں نے عرض کیا: اللہ کے رسول! مجھے ایسی دعا سکھائیے جو میرے لیے نفع بخش اور مفید ہو، آپ نے فرمایا: \"کہو: «اللہم عافني من شر سمعي وبصري ولساني وقلبي وشر منيي» \"اے اللہ مجھے میرے کان، میری نگاہ، میری زبان، میرے دل اور منی کی برائی سے بچائے\" ۱؎۔\n§وضاحت\n۱؎: عضو تناسل کی برائی یہ ہے کہ اس کا استعمال حرام جگہ میں ہو، اس کی برائی سے پناہ مانگنے کی تعلیم آپ صلی اللہ علیہ وسلم نے شکل رضی اللہ عنہ کو دی۔","الألباني: صحيح",{"u2":"سیدنا شکل بن حمید رضی اللہ عنہ سے مروی ہے کہ میں نے کہا:اے اللہ کے رسول!مجھے کوئی دعا سکھائیے جس سے میں فائدہ حاصل کروں۔آپ نے فرمایا:’’کہہ:اے اللہ!مجھے میرے کانوں ‘آنکھوں ‘زبان‘دل اور منی‘یعنی شرم گاہ کے شر سے محفوظ رکھنا۔‘","f2":"تفصیل کے لیے دیکھیے ‘فوائد و مسائل روایت:5446"}],[5485,"ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کہا کرتے تھے: «اللہم إني أعوذ بك من الكفر والفقر» \"اے اللہ! میں کفر اور فقر سے تیری پناہ مانگتا ہوں\"، ایک شخص نے کہا: کیا یہ دونوں برابر ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"ہاں\"۔","الألباني: ضعيف",{"u2":"سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم یوں دعا فرمایا کرتے تھے:’’اے اللہ!میں کفر اور فقر سے تیری پناہ میں آتا ہوں۔‘‘ ایک آدمی نے کہا:یہ دونوں برابر ہیں؟آپ نے فرمایا:’’ہاں۔‘‘"}],[5486,"ام المؤمنین ام سلمہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم جب اپنے گھر سے نکلتے تو کہتے: «بسم اللہ رب أعوذ بك من أن أزل أو أضل أو أظلم أو أظلم أو أجهل أو يجهل على» \"اللہ کے نام سے شروع کرتا ہوں، میرے رب! میں تیری پناہ مانگتا ہوں اس بات سے کہ میں پھسل جاؤں، یا گمراہ ہو جاؤں، یا ظلم کروں، یا مجھ پر ظلم کیا جائے، یا جہالت کروں، یا مجھ سے جہالت کی جائے\"۔","الألباني: صحيح",{"u2":"سیدہ ام سلمہ رضی اللہ عنھا سے روایت ہے کہ نبئ اکرم صلی اللہ علیہ وسلم جب گھر سے باہر نکلتے تو یوں دعا فرماتے:’’اللہ تعالیٰ کے نام کی برکت سے۔اے میرے رب!میں اس بات سے تیری پناہ میں آتا ہوں کہ میں لغزش کر جاؤں یا گمراہ ہو جاؤں یا کسی پر ظلم کروں یا مظلوم بن جاؤں یا کسی سے نا مناسب سلوک کروں یا مجھ سے نا مناسب سلوک کیا جاۓ۔‘‘\nسیدہ ام سلمہ رضی اللہ عنھا سے روایت ہے کہ نبئ اکرم صلی اللہ علیہ وسلم جب گھر سے باہر نکلتے تو یوں دعا فرماتے:’’اللہ تعالیٰ کے نام کی برکت سے۔اے میرے رب!میں اس بات سے تیری پناہ میں آتا ہوں کہ میں لغزش کر جاؤں یا گمراہ ہو جاؤں یا کسی پر ظلم کروں یا مظلوم بن جاؤں یا کسی سے نا مناسب سلوک کروں یا مجھ سے نا مناسب سلوک کیا جاۓ۔‘‘","f2":"’’نامناسب سلوک ‘‘یہ ترجمہ ہے جہالت کا۔ جہالت علم کے مقابل ہے۔جہالت سے جومفاسد پیدا ہو سکتے ہیں‘ان سب کو جہالت ہی کہا جائے گا۔حقوق العباد میں جہالت نا مناسب سلوک کا سبب بنتی ہے کیونکہ جب کسی کے حق کا علم نہ ہو گا تو اس کے ساتھ مناسب سلوک کیسے ہو گا؟"}],[5487,"عبداللہ بن عمرو بن العاص رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم ان کلمات کے ذریعہ دعا کرتے تھے: «اللہم إني أعوذ بك من غلبة الدين وغلبة العدو وشماتة الأعداء» \"اے اللہ! میں قرض کے غلبے سے، دشمن کے قہر و غلبے سے، اور مصیبت میں دشمنوں کے خوش ہونے سے تیری پناہ مانگتا ہوں\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر بن عاص سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم ان کلمات کے ساتھ دعا فرمایا کرتے تھے:’’اے اللہ!میں حقوق العباد کے غالب آنے ‘دشمن کے غالب آ جانے اور دشمنوں کی دل آزارخوشی سے تیری پناہ مانگتا ہوں۔‘","f2":"دیکھیے روایت:5477۔"}],[5488,"عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم ان کلمات کے ذریعہ دعا کرتے تھے: «اللہم إني أعوذ بك من غلبة الدين وشماتة الأعداء» \"اللہ! میں قرض کے دباؤ اور شماتت اعداء یعنی دشمنوں کے ہنسنے سے تیری پناہ مانگتا ہوں\"۔","الألباني: صحيح",{"u2":"سیدنا عبداللہ بن عمرو رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم ن﷾ان کلمات کے ساتھ دعا فرمایا کرتے تھے:’’اے اللہ!میں واجب الادا حق (قرض وغیرہ)کے غلبے اور دشمنوں کی ناروا خوشی سے تیری پناہ مانگتا ہوں۔‘‘"}],[5489,"عثمان بن ابی العاص رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم ان کلمات کے ذریعہ دعا فرماتے تھے: «اللہم إني أعوذ بك من الكسل والهرم والجبن والعجز ومن فتنة المحيا والممات» \"اے اللہ! میں سستی و کاہلی، بڑھاپے ۱؎، بزدلی، عاجزی اور موت و زندگی کے فتنے سے تیری پناہ مانگتا ہوں۔\n§وضاحت\n۱؎: مراد ایسا بڑھاپا ہے جس میں آدمی بالکل بے بس و لاچار ہو جاتا ہے، اسی کو «ارذل العمر» کہا گیا ہے جس میں آدمی کی بھلے برے کی تمیز بھی ختم ہو جاتی ہے، عام بڑھاپا جو ساٹھ سال کی عمر میں میں ہوتا ہے تو اس سے تو آپ صلی اللہ علیہ وسلم خود دوچار ہوئے تھے :(نیز بہت سارے صحابہ کرام بھی ) جو یہ دعا مانگا کرتے تھے۔","الألباني: صحيح الإسناد",{"u2":"سیدنا عثمان بن ابی العاص رضی اللہ عنہ سے منقول ہے کہ نبیٔ اکرم صلی اللہ علیہ وسلم یہ دعائیں مانگا کرتے تھے:’’اے اللہ!میں کاہلی‘شدید بڑھاپے ‘بزدلی ‘نکمے پن اور زندگی و موت کے فتنے سے تیری پناہ طلب کرتا ہوں۔‘"}],[5490,"عبداللہ بن عمرو رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو کہتے ہوئے سنا: «اللہم إني أعوذ بك من الكسل والهرم والمغرم والمأثم وأعوذ بك من شر المسيح الدجال وأعوذ بك من عذاب القبر وأعوذ بك من عذاب النار» \"اے اللہ! میں سستی و کاہلی، بڑھاپے، قرض اور معصیت (گناہ) سے تیری پناہ مانگتا ہوں، اور مسیح دجال کے شر و فتنے سے تیری پناہ مانگتا ہوں، قبر کے عذاب سے تیری پناہ مانگتا ہوں، اور جہنم کے عذاب سے تیری پناہ مانگتا ہوں\"۔","الألباني: حسن صحيح الإسناد",{"u2":"حضرت عمر وبن شعیب کے پردادا محترم (سیدنا عبداللہ بن عمرو بن عاص رضی اللہ عنہ)سے مروی ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:’’اے اللہ!میں کاہلی‘شدید بڑھاپے ‘جان نہ چھوڑنے والے قرض اور گناہ سے تیری پناہ میں آتا ہوں ‘نیز مسیح دجال کے شر سے تیری پناہ میں آتا ہوں۔قبر کے عذاب سے بچاؤ کے لیے تیری یناہ کا طالب ہوں او رآگ کے عذاب سے بچنے کے لیے بھی تجھی سے پناہ مانگتا ہوں۔‘‘","f2":"’’مسیح دجال‘‘مسیح در اصل حضرت عیسیٰ علیہ السلام کا لقب ہے مگر چونکہ یہ شخص ابتدا میں مسیح ہونے کا دعویٰ کرے گا اور یہودی اسے مسیح مانے گے ‘اس لیے اسے یوں کہا گیا لیکن اس سے وہ مسیح نہ بن جائے گا جس طرح کسی کو جھوٹانبی کہنے سے اس کی نبوت کی تصدیق نہیں ہوتی کیونکہ ’’مسیح دحال ‘‘کے معنیٰ ہیں فراڈکرنے والا اور دھوکہ باز مسیح ‘یعنی جھوٹا مسیح۔دجال اس شخص کا نام نہیں ‘وصف ہے۔(دیکھیےحدیث:5453)\nتعجب کی بات ہےیہودیوں نے حضرت عیسیٰ علیہ السلام کو تو مسیح نہ مانا ‘اس دغا باز کو مسیح مانیں گے۔فلعنۃ اللہ علیھم"}],[5491,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم ان تین چیزوں سے پناہ مانگتے تھے: \"شقاوت و بدبختی آ جانے سے، شماتت اعداء (یعنی دشمنوں کی مصیبت میں ہنسی)، بری تقدیر اور بری بلا سے\"۔ سفیان کہتے ہیں: ان میں کوئی تین باتیں تھیں، چوں کہ مجھے نہیں یاد ہے کہ ان میں سے کون سی ایک بات نہیں تھی اس لیے چار کا ذکر کیا ہے۔","الألباني: صحيح",{"u2":"سیدنا ابوھریرہ رضی اللہ عنہ سے روایت ہے ‘انھوں نے فرمایا کہ نبیٔ اکرم صلی اللہ علیہ وسلم ان تین چیزوں سے اللہ تعالیٰ کی پناہ مانگا کرتے تھے:بدبختی کے آپکڑنے سے ‘دشمنوں کی نارواخوشی سے ‘بری تقدیر سے اور شدید آزمائش اور مصیبت سے۔(راوی حدیث)سفیان (ابن عیینہ)نے کہا:حدیث میں تو تین چیزیں ذکر تھیں مگر میں نے چار اس لیے ذکر کر دیں کہ مجھے یاد نہ رہا ‘وہ تین کون سی ہیں؟او ر چوتھی کون سی جو ان میں شامل نہیں۔(ویسے یہ چاروں آئندہ صحیح حدیث میں مذکور ہیں","f2":"(1)باقی تین چیزیں بھی سُوء القضاء کے تحت ہی آتی ہیں کیونکہ دنیامیں بری تقدیر شدید آزمائش اور مصیبت کی صورت میں ہوتی ہے جس سے دشمن ناروا طور پر خوش ہوتے ہیں۔اور اگر اس کا تعلق آخرت سے ہو تو یہ انتہا درجے کی بد بختی ہے۔(2)تقدیر کا برا ہونا متعلقہ شخص کے لحاظ سے ہے ورنہ اللہ تعالیٰ کا ہر فیصلہ اور ہر قضاو قدردرست اور اچھا ہے۔والشر لیس الیک .اگرچہ ہم اس کی حقیقت کو نہ جان سکیں۔(3) بری تقدیر سے بچاؤکی دعا کی جا سکتی ہے کیونکہ اللہ تعالیٰ مختارکل ہے۔جب چاہیے تقدیر بدل دے (لا یسٔل عما یفعل)نیز دعا بھی اسباب میں سے ہے اور اسباب تقدیر کا حصہ ہیں۔گویا تقدیر یوں تھی کہ یہ شخص دعا کرے گا اور اس سے سختی ڈال دی جائے گی‘نیز دعا بھی عبادت ہے۔ثواب تو ملے گا ہی۔بندہ ہونے کے ناطے دعا کرنا ضروری ہے دعا سے انکار تکبر ہے۔ (4)شدید مصیبت اور آزمائش سے مراد وہ حالت ہے جس سے موت آسان معلوم ہو ‘جسمانی مصیبت ہو یا مالی۔"}],[5492,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم بری تقدیر، شماتت اعداء (دشمنوں کی مصیبت پر ہنسنے)، شقاوت بدبختی کے آنے اور بری بلا سے اللہ تعالی کی پناہ مانگتے تھے۔","الألباني: صحيح",{"u2":"سیدنا ابوھریرہ رضی اللہ عنہ سے منقول ہے کہ بنئ اکرم صلی اللہ علیہ وسلم بری تقدیر ‘دشمنوں کی نارواخوشی‘بدبختی کی گرفت اور شدید مصیبت و آزمائش سے اللہ تعالیٰ کی پناہ مانگا کرتے تھے۔","f2":"بد بختی دنیا میں بھی ہو سکتی ہے کہ انسان حالات کے ہاتھوں پریشان رہے۔اور بدبختی یہ ہے کہ زندگی گمراہی میں گزرے حتیٰ کہ موت بھی گمراہی پر آئے۔العیاذ باللہ من سوءالخاتمۃ."}],[5493,"انس رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم کہتے تھے: «اللہم إني أعوذ بك من الجنون والجذام والبرص وسييء الأسقام»\"اے اللہ! جنون (پاگل پن)، جذام، برص اور برے امراض سے تیری پناہ مانگتا ہوں\"۔","الألباني: صحيح",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ نبئ اکرم صلی اللہ علیہ وسلم یوں بھی دعا فرمایا کرتے تھے:’’اے اللہ!میں پا گل پن ‘کوڑھ‘پھلبہری او ر دوسری بری بیماریوں سے تیری پناہ چاہتا ہوں۔‘","f2":"(1)بعض بیماریاں دیرپا ہوتی ہیں اور ان کے اثرات ختم نہیں ہوتے۔موت تک کے لیے لازمہ بن جاتی ہیں۔لوگ نفرت کرنے لگتے ہیں۔جسم عیب دار بن جاتا ہے یا وہ انسانی عقل کے لیے نقصان وہ دہ ہوتی ہیں کہ انسان جانورں جیسے کام کرنے لگ جاتا ہے۔ایسی بیماریوں کو بری بیماریوں میں شمار کیا جاتا ہے۔حدیث میں مذکورہ بیماریوں کے علاوہ دور حاضر کی بیماریاں فالج ‘کینسر‘ایڈز‘پولیو وغیرہ ایسی ہی بیماریاں ہیں۔اعاذناللہ منھا.جبکہ بعض بیماریاں عارضی ہوتی ہیں ‘برے اقرات نہیں چھوڑتیں بلکہ بسا اوقات جسم کی اصلاح کرتی ہیں ‘مثلاً:معمولی بخار‘زکام اور سر درد وغیرہ۔ایسی بیماریاں انسان کے گناہوں کا کفارہ بنتی ہیں اور بڑی بیماریوں سے بچاؤ کا ذریعہ بھی ہوتی ہیں۔(2)یہ روایت دیگر محققین کے نزدیک صحیح ہے اور انھی کی بات راجح ہے۔تفصیل کے لیے دیکھیے:الموسوعۃ الحدیثیۃ‘مسند الامام احمد:20؍309)"}],[5494,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جنوں کی نظر بد اور انسانوں کی نظر بد سے اللہ کی پناہ مانگتے تھے، پھر جب معوذتین اتری تو آپ نے ان کو پڑھنا شروع کیا اور باقی سب چھوڑ دیا۔","الألباني: صحيح",{"u2":"سیدنا ابوسعید رضی اللہ عنہ سے روایت ہے ‘انھوں نے فرمایا:رسول اللہ صلی اللہ علیہ وسلم جن وانس کی نظر بد سے بچاؤ کی دعا کیا کرتے تھے۔جب معوذتین (سورۂ فلق وناس)نازل ہوئیں تو آپ نے انھیں پڑھنا شروع کر دیااور دوسری پناہ والی دعائیں چھوڑ دیں۔","f2":"(1)یہ حدیث مبارکہ اس بات پردلالت کرتی ہے کہ جن ‘انسانوں کو ایذا دینے اور تکلیف پہنچانے کے لیے ان پر غلبہ و تسلط حاصل کر سکتے ہیں ‘لہذا انسانوں کو چاہیے کہ اپنے اللہ رب العزت کی بارگاہ میں التجائیں کےتے رہا کریں تا کہ وہ خبیث و شریر جنوں کی شرارتوں سے محفوظ رہیں۔(2)اس حدیث مبارکہ سے یہ بھی ثابت ہوتا ہے کہ نظربد‘برحق ہے اور یہ بھی ضروری نہیں کہ کسی انسان ہی کی نظر لگے بلکہ جنات کی نظر بھی لگ سکتی ہے۔(3)معوذتین میں ہر قسم کے شر سے پناہ موجود ہے ‘لہذا یہ جامع ہیں۔ان کی موجودگی میں دوسری معوذات کی ضرورت نہیں اگرچہ ان کے پڑھنے کی ممانعت بھی نہیں ہے۔(4)نظر بد کا اثر صرف انسان پر نہیں بلکہ بسا اوقات جمادات پر بھی اس کا ایسا شدید اثر ہوتا ہے جو دواؤںوغیرہ سے ختم نہیں ہوتابلکہ معوذات کی ضرورت پڑتی ہے۔اس اثر کی عقلی تو جیہ نہ بھی ہو سکے تو اس کا انکار ممکن نہیں۔اس دنیا میں سب کچھ عقل کے مطابق نہیں ہوتا بلکہ بہت سے مسائل میں انسان کی عقل دھنگ رہ جاتی ہے‘علوم جواب دے جاتے ہیں۔مقناطیس کے ایک سرے کا شمال کی جانب ہی رہنابھی اس کی ایک مثال ہے۔مگر اس کا انکار ممکن نہیں۔(5) راجح قول کے مطابق یہ روایت صحیح ہے۔ تفصیل کے لیے دیکھیے:(سنن ابن ماجہ مترجم (دارالسلام)‘حدیث:3511)"}],[5495,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ان کلمات کے ذریعے پناہ مانگتے تھے، آپ کہتے تھے: «اللہم إني أعوذ بك من الكسل والهرم والجبن والبخل وسوء الكبر وفتنة الدجال وعذاب القبر» \"اے اللہ! میں سستی و کاہلی، بڑھاپے، بزدلی و کم ہمتی، بخیلی و کنجوسی، بڑھاپے کی برائی، دجال کے فتنے اور قبر کے عذاب سے تیری پناہ مانگتا ہوں\"۔","الألباني: صحيح الإسناد",{"u2":"سیدنا انس رضی اللہ عنہ نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم ان کلمات کے ساتھ اللہ تعالیٰ کی پناہ کیا کرتے تھے:’’اے اللہ!میں کاہلی ‘شدیدبڑھاپے ‘بزدلی‘ کنجوسی‘ ذلیل عمر ‘دجال کے فتنے اور قبر کے عذاب سے تیری پناہ میں آتا ہوں۔‘‘"}],[5496,"مصعب بن سعد اپنے والد سے روایت کرتے ہیں کہ وہ ہمیں پانچ باتیں سکھاتے تھے جن کے ذریعے رسول اللہ صلی اللہ علیہ وسلم دعا کرتے تھے، آپ کہتے تھے:«اللہم إني أعوذ بك من البخل وأعوذ بك من الجبن وأعوذ بك من أن أرد إلى أرذل العمر وأعوذ بك من عذاب القبر» \"اے اللہ! میں بخل سے تیری پناہ مانگتا ہوں، بزدلی و کم ہمتی سے تیری پناہ مانگتا ہوں، لاچاری و مجبوری کی عمر کو پہنچنے سے تیری پناہ مانگتا ہوں اور قبر کے عذاب سے تیری پناہ مانگتا ہوں\"۔","الألباني: صحيح",{"u2":"حضرت مصعب بن سعد اپںے والد سے روایت کرتےہیں کہ ہمیں وہ پانچ کلمات سکھایا کرتےتھے جنھیں پڑھ کررسول اللہ صلی اللہ علیہ وسلم دعا فرمایا کرتےتھے:اے اللہ میں بخل سے تیری پناہ میں آتا ہوں میں بزدلی سے تیری پناہ طلب کرتا ہوں اوراس بات سے بھی تیری پناہ مانگتا ہوں کہ مجھے ذلیل ترین عمر میں لے جایا جائے نیز میں عذاب قبر سے تیری پناہ کا طالب ہوں۔‘‘"}],[5497,"عمرو بن میمون کہتے ہیں کہ میں نے عمر رضی اللہ عنہ کے ساتھ حج کیا، تو مقام جمع میں انہیں کہتے ہوئے سنا: سنو! نبی اکرم صلی اللہ علیہ وسلم پانچ چیزوں سے پناہ مانگتے تھے، فرماتے تھے: «اللہم إني أعوذ بك من البخل والجبن وأعوذ بك من سوء العمر وأعوذ بك من فتنة الصدر وأعوذ بك من عذاب القبر» \"اے اللہ! میں بخیلی و کنجوسی اور کم ہمتی و بزدلی سے تیری پناہ مانگتا ہوں، بری (لاچاری کی) عمر سے تیری پناہ مانگتا ہوں، سینے (دل) کے فتنے سے تیری پناہ مانگتا ہوں، اور قبر کے عذاب سے تیری پناہ مانگتا ہوں\"۔\n§وضاحت\n۱؎: مقام جمع سے مراد مزدلفہ ہے۔","الألباني: ضعيف",{"u2":"حضرت عمرہ بن میمون نے بیان کیاکہ میں سیدنا عمر رضی اللہ عنہ کےساتھ حج کو گیا۔ میں نے ان کو مزدلفہ میں فرماتے سنا: خبر دار!نبئ اکرم صلی اللہ علیہ وسلم پانچ چیزوں سے اللہ تعالی کی پناہ طلب فرمایا کرتےتھے:’’اے اللہ!میں کنجوسی اوربزدلی سے تیری پناہ میں آتا ہوں۔ میں بری عمر سے تیری پناہ طلب کرتاہوں۔سینے کےفتنے سےتیری پناہ مانگتا ہوں اورعذاب قبرسے تیری پںاہ چاہتاہوں۔‘","f2":"تفصیل کےلیے دیکھیے احادیث:5445،5447،5448"}],[5498,"عبداللہ بن سرجس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب سفر کرتے تو کہتے تھے: «اللہم إني أعوذ بك من وعثاء السفر وكآبة المنقلب والحور بعد الكور ودعوة المظلوم وسوء المنظر في الأهل والمال» \"اے اللہ! میں سفر کی مشقت و دشواری، سفر سے لوٹنے کے وقت کے رنج و غم، خوشحالی کے بعد بدحالی، مظلوم کی بد دعا، گھربار اور مال میں بری صورت حال سے تیری پناہ مانگتا ہوں\"۔","الألباني: صحيح",{"u2":"سیدنا عبداللہ بن سرجس رضی اللہ عنہ سےروایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب سفر کرتےتویوں دعافرماتے:’’اےاللہ! میں سفر کی مشکلات واپسی کی غمگینی وپریشانی نفع کےبعد نقصان مظلوم کی بددعا اوراہل ومال میں برا منظر دیکھنےسے تیری پناہ مانگتاہوں۔‘‘","f2":"1۔۔ہر انسان کواپنے اہل وعیال ورمال ومتاع کی ہلاکت وبربادی اوراس کی تباہی وآزمائش سے بچنے کےلیے اللہ عزوجل کے حضور ہر وقت دست بدعا رہنا چاہیے۔\n2۔ یہ حدیث مبارکہ اس بات پر دلالت کرتی ہے کہ مظلوم کی دعا اوربددعا قبول ہوتی ہے اس لیے ہر عقیل وفہیم اورباشعور مسلمان مرودعورت کومظلوم کی دعا حاصل کرنے اوراس کی بدعا سے بچنے کی پوری پوری کوشش کرنی چاہیے نیزظالم اورمظلوم بن جانے سے بچنے کی دعا کرنی چاہیے۔\n3۔اس حدیث مبارکہ سےمعلوم ہواکہ مذکورہ ذکرودعا کاکرنا اورآغاز سفرمیں التزام کرنا مستحب ہے۔اس کےمتعلق بہت سی احادیث وارد ہیں۔ بعض اہل علم نےان اذکار کوکتابی صورت میں جمع کیاہےجیسا کہ امام نوری رحمتہ اللہ علیہ کی کتاب الاذکار۔‘‘\n4۔ واپسی کی غمگین ‘‘یعنی میں اپںے مقصد میں ناکام ہوکر مغموم واپس لوٹوں۔\n5۔ نفع کےبعد نقصان ‘‘ یہ جامع الفاظ ہیں جن میں ہر نفع نقصان اورخیروشرآجاتاہے مثلاً ایمان کےبعد کفر صحت کےبعد بیماری اورغنی کےبعد فقر وغیرہ۔\n6۔ مظلوم کی بدعا ‘‘مقصود یہ ہے کہ میں کسی پرظلم نہ کروں تاکہ مجھے بددعا نہ دے۔\n7۔ اہل ومال میں برا منظر یعنی میری عدم موجودگی میں ان کانقصان نہ ہو۔"}],[5499,"عبداللہ بن سرجس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم سفر کرتے تو کہتے تھے: «اللہم إني أعوذ بك من وعثاء السفر وكآبة المنقلب والحور بعد الكور ودعوة المظلوم وسوء المنظر في الأهل والمال والولد» \"اے اللہ! میں سفر پر جاتے وقت کی دشواری و پریشانی، لوٹنے کے وقت کے رنج و غم، خوشحالی کے بعد بدحالی اور مظلوم کی بد دعا سے اور گھر والوں، مال اور بچوں میں بری صورت حال سے تیری پناہ مانگتا ہوں\"۔","الألباني: صحيح",{"u2":"سیدنا عبداللہ بن سرجس رضی اللہ عنہ سےروایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب سفر کرتےتھےتویوں دعافرماتے:’’اےاللہ! میں سفر کی مشکلات واپسی کی غمگینی نفع کےبعد نقصان مظلوم کی بددعا اوراہل وعیال اورمال میں برا منظر دیکھنےسے تیری پناہ مانگتاہوں۔‘‘"}],[5500,"عبداللہ بن سرجس رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم جب سفر کرتے تو سفر پر جاتے وقت کی دشواری و پریشانی، لوٹنے کے وقت کے رنج و غم، خوشحالی کے بعد بدحالی، مظلوم کی بد دعا اور بری صورت حال سے پناہ مانگتے۔","الألباني: صحيح",{"u2":"سیدنا عبداللہ بن سرجس رضی اللہ عنہ نے فرمایا: نبئ اکرم صلی اللہ علیہ وسلم جب سفر کرتےتوسفر کی مشکلات واپسی کی پریشانی نفع کے بعد نقصان مظلوم کی بدعا اوربرے منظرسے پناہ طلب فرماتے تھے۔"}],[5501,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ \"مومن کا (ناحق) قتل اللہ تعالی کے نزدیک پوری دنیا کے ہلاک و برباد ہونے سے زیادہ بڑی بات ہے\"۔\nابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب سفر کرتے اور سواری پر سوار ہوتے تو انگلی سے اشارہ کرتے (شعبہ نے اپنی انگلی دراز کی) اور کہتے تھے: «اللہم أنت الصاحب في السفر والخليفة في الأهل والمال اللہم إني أعوذ بك من وعثاء السفر وكآبة المنقلب» \"اے اللہ! تو ہی سفر کا ساتھی ہے، اور گھر والوں اور مال میں ہمارا نگہبان و خلیفہ ہے، اے اللہ! میں سفر پر جاتے وقت کی دشواری و پریشانی اور لوٹتے وقت کے رنج و غم سے تیری پناہ مانگتا ہوں\"۔","الألباني: صحيح موقوف وهو في حكم المرفوع",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے انھوں نے فرمایا:رسول اللہ صلی اللہ علیہ وسلم جب سفر شروع کرتےاوراونٹ پرسوار ہتے تواپنی انگشت شہادت سے (آسمان کی طرف)اشارہ فرماتے(راوی حدیث) شعبہ نے اپنی انگلی کولمبا کیا(اوراشارہ کرکےدکھایا) اوریہ دعا پڑھتے:’’اے اللہ! توہی سفر میں اصلی ساتھی ہے۔اوراہل ومال میں توہی نگران ہے۔ اے اللہ!میں سفر کے مصائب اورغمناک واپسی سے تیری پناہ میں آتا ہوں۔‘","f2":"’’اصلی ساتھی‘‘کیونکہ دوسرے ساتھی کسی بھی وقت ساتھ چھوڑ سکتے ہیں۔ خوشی سے ناخوشی سے۔ ’’نگران ‘‘عربی میں لفظ ’’خلیفہ‘‘استعمال ہوا ہے جس کے معنی نائب اورجانشین ہے۔ مطلب یہ ہے کہ میری عدم موجودگی میں توہی میری جگہ کفایت فرمائے گا۔ اس مفہوم کونگران کےلفظ سےبیان کیاگیاہے۔"}],[5502,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مستقل رہنے کی جگہ میں برے اور خراب پڑوسی سے اللہ کی پناہ مانگو، اس لیے کہ صحراء کا پڑوسی ۱؎ تو تم سے جدا ہی ہو جائے گا\"۔\n§وضاحت\n۱؎: جو کچھ دیر کے لیے پڑوسی ہو اور اس کی مستقل رہائش گاہ وہاں نہ ہو، جیسے سفر کا پڑوسی، کلاس کا پڑوسی وغیرہ۔","الألباني: حسن صحيح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: مستقل رہائش میں برے پڑوسی سے پںاہ مانگنی چاہیے۔عارضی پڑوسی توجلد بدیر تجھ سے دور ہوجائے گا۔‘","f2":"مستقل رہائش گاہ سے مراد شہر اوربستیاں ہیں جہاں مکانات بنائے جاتےہیں جوصدیوں تک قائم رہتےہیں اورعارضی پروسی سےمراد سفر اورصحراکا پڑوسی ہے جہاں عارضی خیمے لگائے جاتےہیں اورکچھ دیربعد اکھیڑ لیے جاتےہیں۔ ظاہر ہےبستی کاپڑوسی توساری زندگی کاپڑوسی رہے گا لہذا وہ اچھا ہونا چاہیے ورنہ زندگی اجیرن بنی رہے گی۔"}],[5503,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ابوطلحہ رضی اللہ عنہ سے فرمایا: \"میری خدمت کے لیے اپنے لڑکوں میں سے ایک لڑکا تلاش کرو\"، تو ابوطلحہ مجھے اپنے پیچھے بٹھائے ہوئے لے کر نکلے۔ چنانچہ میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت کرتا تھا، جب جب آپ قیام کرتے میں اکثر آپ کو کہتے ہوئے سنتا: «اللہم إني أعوذ بك من الهرم والحزن والعجز والكسل والبخل والجبن وضلع الدين وغلبة الرجال» \"اے اللہ! میں بڑھاپے سے، حزن و غم، عاجزی و کاہلی، بخیلی و بزدلی سے، قرض کے بوجھ اور لوگوں کے قہر اور غلبے سے تیری پناہ مانگتا ہوں\"۔","الألباني: صحيح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نےسیدنا ابو طلحہ رضی اللہ عنہ سے فرمایا:’’اپنے نوجوان لڑکوں میں سے کوئی لڑکا تلاش کرو جومیری خدمت کیاکرے۔‘‘حضرت ابوطلحہ مجھے اپںے پیچھے سواری پربٹھا کرلے گئے۔ جب رسول اللہ صلی اللہ علیہ وسلم پڑاؤ فرماتے تومیں آپ کی خدمت کیاکرتاتھا۔ میں آپ کواکثریہ دعا پڑھتے سنتاتھا:’’اے اللہ! میں شدید بڑھاپے غم نکمے پن کاہلی کنجوسی بزدلی قرض کے بوجھ اورلوگوں کےغلبے سے تیری پںاہ چاہتا ہوں۔‘‘","f2":"یہ جنگ خیبر کاواقعہ ہے۔ سیدنا ابو طلحہ رضی اللہ عنہ سیدنا انس رضی اللہ عنہ کی والدہ محترمہ کےخاوند تھے۔ سیدنا انس رضی اللہ عنہ پہلے بھی آپ کی خدمت کیاکرتےتھے مگر چونکہ عمر میں چھوٹے تھے ‘ اس لیے آپ نے محسوس فرمایا کہ شاید گھر والے اتنے چھوٹے بچے کوجنگی سفر میں ساتھ بھیجنے پرراضی نہ ہوں۔ آپ نے سیدنا ابو طلحہ رضی اللہ عنہ ہی سے خادم کی خواہش فرمائی۔ انھوں نے حضرت انس کوہی ساتھ لے لیا۔ رضی اللہ عنہ وارضاہ"}],[5504,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم قبر کے عذاب اور دجال کے فتنے سے اللہ کی پناہ مانگتے اور فرماتے: \"قبروں میں تمہاری آزمائش ہو گی\"۔","الألباني: صحيح الإسناد",{"u2":"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ نبئ اکرم صلی اللہ علیہ وسلم قبر کی عذاب اوردجال کےفتنے سے اللہ تعالی کی پناہ طلب کیا کرتے تھے نیز آپ نےفرمایا:’’قبروں میں بھی تمھاری آزمائش ہوگی۔‘","f2":"عذاب قبراورقتنہ دجال میں مناسبت یہ ہے کہ دونوں میں ایمان کاامتحان ہے۔ منافق یہ دونوں امتحان پاس نہیں کرسکیں گے۔ مخلص لوگ ہی کامیاب ہوں گے۔یہاں دجال کا اقتدار ہوگا ‘وہا ں فرشتوں کے سوالات۔"}],[5505,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میں جہنم کے عذاب سے اللہ کی پناہ مانگتا ہوں، قبر کے عذاب سے اللہ کی پناہ مانگتا ہوں، مسیح دجال کے شر و فتنہ سے اللہ کی پناہ مانگتا ہوں، اور موت و زندگی کے فتنے کے شر سے اللہ کی پناہ مانگتا ہوں\"۔","الألباني: سكت عنه الشيخ",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سےروایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:میں جہنم سےاللہ تعالی کی پناہ میں آتا ہوں۔ میں قبر کےعذاب سے اللہ تعالی کی پناہ حاصل کرتاہوں۔ میں مسیح دجال کےشرسےاللہ تعالی کی پناہ چاہتا ہوں اورزندگی وموت کی آزمائش کےشرسے اللہ تعالی کی پناہ مانگتاہوں۔‘‘","f2":"1۔اس حدیث مبارکہ سے ثابت ہوتاہے کہ عذاب قبر نیز زندگی اورموت کےفتنے سے پناہ مانگنا مشروع ہے۔ عذاب قبر کابرحق ہونا بھی اس حدیث سے ثابت ہوا اور برزخی)زندگی کی طرف اشارہ بھی ہوتاہے اگرچہ وہ ہمارے شعور اورفہم سے بالاتر ہے۔\n2۔ یہ حدیث مبارکہ رسول اللہ صلی اللہ علیہ وسلم کی نبوت کی بھی بہت بڑی دلیل ہے کہ آپ نےیہ خبر دی ہے کہ آخری زمانے میں مسیح دجال آئے گا۔ اورامت کواس کے فتنے سےخبر دار کرنے کےساتھ ساتھ اس کے شراورفتنے سے بچنے کی دعائیں بھی سکھلائی ہیں۔"}],[5506,"ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کہا کرتے تھے: «اللہم إني أعوذ بك من عذاب القبر وأعوذ بك من عذاب النار وأعوذ بك من فتنة المحيا والممات وأعوذ بك من شر المسيح الدجال» \"اے اللہ! میں عذاب قبر سے تیری پناہ مانگتا ہوں، جہنم کے عذاب سے تیری پناہ مانگتا ہوں، موت و زندگی کے فتنے سے تیری پناہ مانگتا ہوں اور مسیح دجال کے شر و فتنے سے تیری پناہ مانگتا ہوں\"۔","الألباني: صحيح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے منقول ہے ہ رسول اللہ صلی اللہ علیہ وسلم یہ دعا فرمایا کرتےتھے:’’!میں قبر کےعذاب سے بچنےکےلیے تیری پناہ میں آتا ہو ں۔ میں آگ کےعذاب سے تیری پناہ مانگتاہوں۔ میں زندگی اورموت کے فتنے سے تیری پںاہ چاہتا ہوں اورمسیح دجل کےفتنے سے تیری پناہ کاطالب ہوں۔‘"}],[5507,"ابوذر رضی اللہ عنہ کہتے ہیں کہ میں مسجد میں داخل ہوا، رسول اللہ صلی اللہ علیہ وسلم اندر تھے، میں آپ کے پاس بیٹھ گیا، آپ نے فرمایا: \"ابوذر! جن اور انس کے شیاطین کے شر سے (اللہ کی) پناہ مانگو\"، میں نے عرض کیا: کیا انسانوں میں بھی شیطان ہوتے ہیں؟ آپ نے فرمایا: \"ہاں\"۔","الألباني: ضعيف الإسناد",{"u2":"حضرت ابوذررضی اللہ سے روایت ہے انھوں نے کہا کہ میں مسجد نبوی داخل ہوا۔رسول اللہ صلی اللہ علیہ وسلم بھی وہیں تشریف فرما تھے۔ میں آکر آپ کےپاس بیٹھ گیا۔ آپ نےفرمایا: ’’ابوذر!شیطان جنوں اورانسانوں سےاللہ تعالی کی پناہ مانگا کر۔ ‘‘میں نے عرض کی:انسانوں میں بھی شیطان ہوتےہیں؟آپ نے فرمایا:’’ہاں‘‘"}],[5508,"ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"قبر کے عذاب سے اللہ کی پناہ مانگو، موت اور زندگی کے فتنے سے اللہ کی پناہ مانگو، مسیح دجال کے فتنے سے اللہ کی پناہ مانگو\"۔","الألباني: صحيح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبئ اکرم صلی اللہ علیہ وسلم نے فرمایا:’’قبر کےعذاب سے اللہ تعالی کی پناہ حاصل کیاکرو۔ زندگی اورموت کے فتنےسے اللہ تعالی کی پناہ مانگا کرو۔ مسیح دجال کےفتنے سے اللہ تعالی کی پناہ طلب کیاکرو۔‘","f2":"زندگی کےفتنےسےمرادگمراہی ہے یا مصائب وآزمائشیں جنھیں انسان برداشت نہ کرسکے۔"}],[5509,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم پانچ چیزوں سے پناہ مانگتے تھے، فرماتے تھے: \"قبر کے عذاب سے، جہنم کے عذاب سے، موت اور زندگی کے فتنے سے اور مسیح دجال (کانا دجال) کے فتنے سے اللہ کی پناہ مانگو\"۔","الألباني: صحيح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم پانچ چیزوں سے پناہ مانگا کرتےتھے۔ آپ فرماتے:’’تم قبر کےعذاب ‘جہنم کےعذاب ‘زندگی وموت کےفتنے اورمسیح دجال کےشرسے اللہ تعالی کی پناہ مانگا کرو۔‘"}],[5510,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"جس نے میری اطاعت کی، اس نے اللہ کی اطاعت کی، جس نے میری نافرمانی کی اس نے اللہ کی نافرمانی کی\"، آپ قبر کے عذاب، جہنم کے عذاب، زندہ اور مردہ لوگوں کو پہنچنے والے فتنے اور مسیح دجال (کانا دجال) کے فتنے سے پناہ مانگتے تھے۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابوہریرہ نے فرمایا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کوفرماتےسنا:’’جس شخص نےمیری اطاعت کی ‘اس نے اللہ تعالی کی اطاعت کی اورجس نےمیری نافرمانی کی اس نے اللہ تعالی کی نافرمانی کی۔‘‘آپ قبر کےعذاب ‘جہنم کےعذاب ‘زندوں اورمردوں کےفتنے اورمسیح دجال کےفتنے سے اللہ تعالی کی پناہ مانگاکرتےتھے۔","f2":"زندوں اورمردوں کےفتنے سےمراد بھی زندگی اورموت کافتنہ ہی ہے یعنی وہ فتنہ جوزندوں یا مردوں کولاحق ہوتاہے۔ زندوں کافتنہ گمراہی اورمردوں کافتنہ براانجام یعنی برموت ہے۔"}],[5511,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"پانچ چیزوں سے اللہ کی پناہ طلب کرو، جہنم کے عذاب سے، قبر کے عذاب سے، موت اور زندگی کے فتنے سے اور مسیح دجال (کانا دجال) کے فتنے سے\"۔","الألباني: صحيح",{"u2":"حضرت ابوعلقمہ نے کہاکہ مجھے سیدنا ابوہریرہ رضی اللہ عنہ نے بالمشافہ بیان کیاکہ نبئ اکرم صلی اللہ علیہ وسلم نے فرمایا:’’پانچ چیزوں سے اللہ تعالی کی پناہ طلب کیا کرو:جہنم کےعذاب،قبرکےعذاب،زندگی وموت کےفتنے اورمسیح دجال کےفتنےسے۔‘‘","f2":"زندگی اورموت کافتنہ گنتی میں دوہیں۔ تبھی پانچ چیزیں بنیں گی یعنی زندگی کافتنہ اورموت کافتنہ۔"}],[5512,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم انہیں یہ دعا سکھاتے تھے جیسے آپ قرآن کی سورت سکھاتے تھے (فرماتے تھے:)کہو: «اللہم إنا نعوذ بك من عذاب جهنم وأعوذ بك من عذاب القبر وأعوذ بك من فتنة المسيح الدجال وأعوذ بك من فتنة المحيا والممات» \"اے اللہ! میں جہنم کے عذاب سے تیری پناہ مانگتا ہوں، قبر کے عذاب سے تیری پناہ مانگتا ہوں، مسیح دجال (کانا دجال) کے فتنے سے تیری پناہ مانگتا ہوں اور موت اور زندگی کے فتنے سے تیری پناہ مانگتا ہوں\"۔","الألباني: صحيح",{"u2":"سیدنا عبداللہ بن عباس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم اپنے صحابہ کویہ دعا یوں سکھاتے جیسے قرآن مجید کی سورت یاد کرواتے تھے۔ (فرماتے:) ’’کہو:اےاللہ! ہم جہنم کےعذاب سےتیری پناہ میں آتے ہیں۔ میں قبر کےعذاب سے تیری پناہ چاہتا ہوں۔ میں مسیح دجال کےفتنے سے تیری پناہ طلب کرتا ہوں اور میں زندگی اورموت کے فتنے سے تیری پناہ مانگتاہوں ‘‘"}],[5513,"ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اللہ کے عذاب سے اللہ کی پناہ مانگو اور موت اور زندگی کے فتنے سے، قبر کے عذاب سے اور مسیح دجال (کانا دجال) کے فتنے سے اللہ کی پناہ مانگو\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ سے روایت ہے کہ نبئ اکرم صلی اللہ علیہ وسلم نے فرمایا:’’اللہ کے عذاب سے (بچنے کےلیے)اللہ تعالی کی پںاہ حاصل کرو۔ زندگی اورموت کےفتنے سے(بچنے کےلیے) اللہ تعالی کی پناہ طلب کرو عذاب قبر اورمسیح دجال کےفتنے سے اللہ تعالی کی پناہ مانگو۔‘‘"}],[5514,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم دعا کرتے تو اپنی دعا میں کہتے: «اللہم إني أعوذ بك من عذاب جهنم وأعوذ بك من عذاب القبر وأعوذ بك من فتنة المسيح الدجال وأعوذ بك من فتنة المحيا والممات» \"اے اللہ! میں جہنم کے عذاب سے تیری پناہ مانگتا ہوں، قبر کے عذاب سے تیری پناہ مانگتا ہوں، مسیح دجال (کانا دجال) کے فتنے سے تیری پناہ مانگتا ہوں اور موت اور زندگی کے فتنے سے تیری پناہ مانگتا ہوں\"۔","الألباني: صحيح",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم اپںی دعا میں یوں فرمایا کرتے تھے: ’’اے اللہ! میں جہنم کےعذاب سے تیری پںاہ میں آتا ہوں۔ میں قبر کےعذاب سے تیری پںاہ حاصل کرتا ہوں مسیح دجال کےفتنے سے تیری پناہ مانگتا ہوں اور زندگی وموت کےفتنے سے تیری پناہ چاہتا ہوں۔ ‘"}],[5515,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دعا میں کہتے ہوئے سنا: «اللہم إني أعوذ بك من فتنة القبر وفتنة الدجال وفتنة المحيا والممات» \"اے اللہ! میں قبر کے فتنے سے، دجال کے فتنے سے اور موت اور زندگی کے فتنے سے تیری پناہ مانگتا ہوں\"۔ ابوعبدالرحمٰن (نسائی)کہتے ہیں: حدیث میں (سلیمان بن یسار کے نام میں) غلطی ہے، صحیح \"سلیمان بن سنان ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ فرماتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کواپنی دعا میں فرماتے سنان:’’اے اللہ! میں قبر کی آزمائش دجال کےفتنے اورزندگی وموت کی آزمائشوں سے تیری پںاہ مانگتا ہوں۔ ‘‘ ابو عبدالرحمن (امام نسائی رحمتہ اللہ علیہ) نے کہا کہ یہ (سند میں مذکورسلیمان بن یسار) غلط ہے جبکہ سلیمان بن سنان درست ہے۔","f2":"عذاب قبر اورقبر کی آزمائش الگ الگ ہوں توقبر کی آزمائش سے مراد فرشتوں کےسوالات ہوں گے اورعذاب قبرسے مراد وہ سزا ہے جوکافر منافق اورنافرمان کوسوالات کےبعدقبر میں دی جاتی ہے۔ اعاذنا اللہ منہ . فرشتوں کےسوالات سے پںاہ کامطلب ہے کہ میں ان کےصحیح جواب دے سکوں اوراس آزمائش میں کامیاب ہو جاؤں۔"}],[5516,"ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اللہ کے عذاب سے اللہ کی پناہ مانگو، قبر کے عذاب سے اللہ کی پناہ مانگو، موت اور زندگی کے فتنے سے اللہ کی پناہ مانگو، اور مسیح دجال (کانا دجال) کے فتنے سے اللہ کی پناہ مانگو\"۔","الألباني: صحيح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبئ اکرم صلی اللہ علیہ وسلم نےفرمایا:’’اللہ تعالی کےعذاب سے اللہ تعالی کی پںاہ مانگو۔ قبر کےعذاب سے اللہ تعالی کی پںاہ مانگو۔ زندگی وموت کےفتنے سے اللہ تعالی کی پںاہ مانگو اورمسیج دجال کےفتنے سے اللہ تعالی کی پناہ مانگو۔‘"}],[5517,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جہنم کے عذاب سے، قبر کے عذاب سے اور مسیح دجال (کانا دجال) سے پناہ مانگتے تھے۔","الألباني: صحيح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نے فرمایا:رسول اللہ صلی اللہ علیہ وسلم عذاب جہنم،عذاب قبر اورمسیح دجال کےشرسے اللہ تعالی کی پںاہ طلب کیاکرتےتھے۔","f2":"مسیح دجال کےشر سے مراد اس کی پیروی سے انکار پرملنے والی سزا ہے یا اس کی پیروی کرنے پرملنے والی سزا۔ پہلی سزا دجال کی طرف سے ہوگی دوسری اللہ تعالی کی طرف سے۔"}],[5518,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"(جہنم کی) آگ کے عذاب، قبر کے عذاب، موت اور زندگی کے فتنے اور مسیح دجال (کانا دجال) کے شر سے اللہ کی پناہ مانگو\"۔","الألباني: صحيح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’آگ کےعذاب قبر کے عذاب زندگی اورموت کےفتنے اورمسیح دجال کے شرسے اللہ کی پںاہ حاصل کیاکرو۔‘","f2":"اصل تویہی ہے کہ آگ کےعذاب سے مراد جہنم کاعذاب ہے کیونکہ جہنم میں سب بڑاذریعہ عذاب آگ ہے لیکن ظاہر الفاظ کےلحاظ سے دنیا میں آگ سے جل مرنے کوبھی آگ کاعذاب کہا جاسکتا ہے۔ واللہ اعلم . آئندہ باب اورحدیث میں بھی یہ احتمال ہوسکتا ہے۔"}],[5519,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «اللہم رب جبرائيل وميكائيل ورب إسرافيل أعوذ بك من حر النار ومن عذاب القبر» \"اے اللہ، جبرائیل و میکائیل اور اسرافیل کے رب! میں جہنم کی آگ کی گرمی اور قبر کے عذاب سے تیری پناہ مانگتا ہوں\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے(دعا کرتےہوئے)فرمایا:’’اے اللہ!جبریل ومیکائل کےرب! اسرافیل کےرب! میں آگ کی تپش اورقبر کےعذاب سےتیری پںاہ چاہتا ہوں۔‘‘"}],[5520,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ میں نے ابوالقاسم صلی اللہ علیہ وسلم کو اپنی نماز میں کہتے سنا: «اللہم إني أعوذ بك من فتنة القبر ومن فتنة الدجال ومن فتنة المحيا والممات ومن حر جهنم» \"اے اللہ! میں قبر کے فتنے سے، دجال کے فتنے سے، موت اور زندگی کے فتنے سے اور جہنم کی گرمی سے تیری پناہ مانگتا ہوں\"۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: یہی درست اور صواب ہے ۱؎۔\n§وضاحت\n۱؎: یعنی ابوہریرہ سے روایت کرنے والے سلیمان بن سنان ہیں نہ کہ سلیمان بن یسار۔","الألباني: صحيح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نےفرمایا:میں نے الو القاسم صلی اللہ علیہ وسلم کودوران نماز فرماتے سنا:’’اے اللہ!میں قبر کی آزمائش اورعذاب دجال کےفتنے زندگی اورموت کےفتنے اورجہنم کی تپش سے تیری پںاہ میں آتا ہوں۔‘‘\nابو عبدلرحمن (امام نسائی رحمتہ اللہ علیہ) نے کہا:یہ درست ہے۔","f2":"1۔ حدیث:5517کےآخر میں امام نسائل رحمتہ اللہ علیہ نے فرمایا تھا کہ یہ خطا ہے یعنی سلیمان کے والد کانام یسار درست نہیں۔ یہاں سند میں سلیمان کےوالد کانام سنان ذکرہوا امام صاحب رحمتہ اللہ اسے درست قرار دیتے ہیں۔\n2۔ ابوالقاسم رسول اللہ صلی اللہ علیہ وسلم کی کنیت مبارکہ تھی۔یاتوآپ کےبڑے بڑے بیٹے کی نسبت سےیا آپ کےقاسم ہونے کی وجہ سے کہ آپ علم وحکمت تقسیم فرماتےتھے اوراللہ کےحکم سے غنیمت کامال بھی۔\n3۔ جبریل ومیکائیل اوراسرافیل اللہ تعالی کےعظیم المرتبت فرشتے ہیں۔ جواعلیٰ مرتبے کےساتھ ساتھ عظیم قوتوں کےمالک ہیں۔ فرشتوں کےسردار ہیں۔ دعا میں ان فرشتوں کےنام ذکر کرنے سےان کی عظمت کابیان مقصود ہے مگر یہ فرشتے اللہ تعالی کےحکم کےپابند ہیں۔ اوراس کے بندے ہیں ......علیہم السلام ......"}],[5521,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ نے فرمایا: \"جس نے تین بار اللہ تعالی سے جنت مانگی تو جنت کہے گی: اے اللہ! اسے جنت میں داخل کر دے اور جس نے تین بار جہنم سے پناہ مانگی تو جہنم کہے گی: اے اللہ! اسے جہنم سے بچا لے\"۔","الألباني: صحيح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نےفرمایا:جوشخص اللہ تعالی سے تین مرتبہ جنت کاسوال کرےتوجنت کہتی ہے:اے اللہ اسے جنت میں داخل فرما: اورجوشخص تین دفعہ آگ سے پناہ مانگے توآگ خود کہتی ہے:یا اللہ!اس کو آگ سے بچا۔‘","f2":"جنت جہنم اورآگ وغیرہ اللہ تعالی کی مخلوق ہیں۔ وہ اللہ تعالی سے باتیں کرتی ہیں۔ اللہ تعالی ان سے باتیں فرماتا ہے۔ اس پر کسی کوکوئی اعتراض نہیں ہونا چاہییے اورنہ کوئی تکلیف۔ ارشاد باری تعالی ہے(وان من شیء الا یسبح بحمدہ ولکن لا تفقھون تسبیحھم)بنی اسرائیل 17:44)یہاں حال و قال کی بحث کی ضرورت نہیں۔ یہ خالق ومخلوق کامعاملہ ہے۔"}],[5522,"شداد بن اوس رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"سیدالاستغفار یہ ہے کہ بندہ کہے: «اللہم أنت ربي لا إله إلا أنت خلقتني وأنا عبدك وأنا على عهدك ووعدك ما استطعت أعوذ بك من شر ما صنعت أبوء لك بذنبي وأبوء لك بنعمتك على فاغفر لي فإنه لا يغفر الذنوب إلا أنت» \"اے اللہ! تو میرا رب ہے، تیرے سوا کوئی حقیقی معبود نہیں۔ تو نے مجھے پیدا کیا ہے، میں تیرا بندہ ہوں اور جہاں تک ہو سکتا ہے میں تیرے اقرار اور وعدے پر ہوں، میں اپنے کیے ہوئے کاموں کی برائی سے تیری پناہ مانگتا ہوں، میں اپنے گناہ کا تجھ سے اقرار کرتا ہوں، مجھ پر جو تیری نعمتیں اور احسانات ہیں ان کا اقرار کرتا ہوں، تو مجھے بخش دے، اس لیے کہ تیرے علاوہ کوئی گناہوں کو نہیں بخش سکتا، اگر یہ دعا صبح پڑھے اور اس پر پکا یقین ہو، پھر مر جائے تو جنت میں داخل ہو گا، اور اگر شام کے وقت یقین کے ساتھ یہی دعا پڑھے تو جنت میں داخل ہو گا\"۔ (ابوعبدالرحمٰن نسائی کہتے ہیں:) ولید بن ثعلبہ نے حسین المعلم کے خلاف روایت کی ہے ۲؎۔\n§وضاحت\n۱؎: یہ اختلاف یوں ہے، عبداللہ بن بریدہ سے روایت کرنے والے کئی راوی ہیں، چنانچہ حسین المعلم کی روایت میں ابن بریدہ کے شیخ بشیر بن کعب ہیں جب کہ ثابت البنانی اور ابوالعوام نے بشیر بن کعب کا ذکر نہ کر کے «عن ابن بریدہ عن شداد» کے ساتھ روایت کی ہے۔ ۲؎: چنانچہ ولید کی روایت میں«عن ابن بریدہ عن أبیہ» ہے، جسے ابن ماجہ نے :(کتاب الدعا باب ۱۴ میں ) روایت کیا ہے۔","الألباني: صحيح",{"u2":"سیدنا شدادبن اوس رضی اللہ عنہ سے روایت ہے کہ نبئ اکرم صلی اللہ علیہ وسلم نےفرمایا:’’’سب سے اہم اورافضل استغفار یہ ہے کہ بندہ کہے:اے اللہ!تومیرا رب ہے۔تیرے سواکوئی معبودنہیں۔تومیرا خالق ہے۔میں تیرابندہ ہوں۔اورمیں اپنی طاقت واستطاعت کےمطابق تجھ سے کیے ہوئے عہدووعدے پرقائم ہوں۔میں اپنےگناہوں کےشرسےتیری پناہ چاہتاہوں۔میں اپںے ہرقسم کےگناہوں کااعتراف کرتاہوں اوراپنے آپ پرتیری نوازشات کااقرار کرتاہوں لہذامجھے معاف فرما کیونکہ تیرے سوا کوئی گناہ معاف نہیں کرسکتا۔‘‘اگرکوئی شخص یقین وایمان کےساتھ صبح کےوقت یہ کلمات پڑھے پھر مرجائےتو(لازماً)جنت میں داخل ہوگا اوراگر شام کےوقت یہی کلمات یقین وایمان رکھتے ہوئے کہے(ورمرجائے)تو(لازماً)جنت میں داخل ہوگا۔‘‘ولید ببن ثعلبہ نےاس (حسین المعلم) کی مخالفت کی ہے","f2":"1۔امام نسائی رحمتہ اللہ علیہ نے جوترجمۃ الباب قائم کیا ہے اس سے ان کامقصد یہ مسئلہ بیان کرنا ہے کہ انسان کوچاہیےکہ وہ اپنے کیے ہوئے کاموں کےشر اوران کےنقصان سے بچنے کےلیے اللہ تعالی کی پناہ حاصل کرے۔ شرعاً یہ مستحب اورپسندیدہ عمل ہے۔\n2۔ اس حدیث مبارکہ سے معلوم ہوا کہ مذکورہ دعا افضل استغفار ہے۔\n3۔ اہم وافضل یعنی اپنے الفاظ کی مناسبت سے اورجامع ہونے کے وجہ سے۔ عربی میں لفظ سید استعمال فرمایا گیا ہے جس کے لفظی معنی سردار کےہیں ترجمہ میں لازم معنی اختیار کیاگیا ہے تاکہ مقصود ظاہر ہوجائے۔\n4۔ استطاعت کےمطابق یہ دراصل اپنی کوتاہی اورعجز کااعتراف ہے نہ کہ دعوی۔\n5۔ عہدووعدے سے مرادفطری عہد بھی ہوسکتا ہے جسے عھدالست کہاجاتا ہے اورزبانی عہد بھی مثلاً کلمہ توحید ورسالت کی ادائیگی وغیرہ۔\n6۔ داخل ہوگا یعنی مرتےہی اولیں طور پر۔گویا اللہ تعالی اس عمل کی توفیق ہی اس شخص کودے گا جس کی مغفرت کافیصلہ ہوچکا ہو ورنہ ممکن ہے اس شخص ساری زندگی یہ دعاپڑھتا رہےمگر موت والے دن یا رات نصیب نہ ہو۔ العیاذ باللہ یا پڑھے توسہی مگر ایمان ویقین نہ ہو۔ اللہ تعالی ایسی قبیح حالت سے بچائے۔ آمین ."}],[5523,"ہلال بن یساف بیان کرتے ہیں کہ انہوں نے ام المؤمنین عائشہ رضی اللہ عنہا سے پوچھا کہ رسول اللہ صلی اللہ علیہ وسلم اپنی موت سے پہلے کون سی دعا مانگا کرتے تھے؟ وہ بولیں: آپ صلی اللہ علیہ وسلم اکثر یہ دعا مانگتے تھے «اللہم إني أعوذ بك من شر ما عملت ومن شر ما لم أعمل» \"اے اللہ! میں اپنے کیے ہوئے کاموں کے شر سے تیری پناہ مانگتا ہوں، اور جو کام نہیں کیے ہیں (اور آیندہ کروں گا) ان کے شر سے تیری پناہ مانگتا ہوں۔\n§وضاحت\n۱؎: چنانچہ عبدہ کی روایت میں «عن ہلال عن عائشہ» ہے جب کہ منصور اور حصین کی روایت میں «عن ہلال عن فروہ عن عائشہ»ہے۔","الألباني: صحيح",{"u2":"حضرت ہلال بن یساف سے منقول ہے کہ میں نےنبئ اکرم صلی اللہ علیہ وسلم کی زوجہ محترمہ ام المومنین سیدہ عائشہ رضی اللہ عنہا سے پوچھا رسول اللہ صلی اللہ علیہ وسلم اپںی وفات سے قبل کون سی دعا زیادہ پڑھتے تھے؟انھوں نے فرمایا:یہ دعا زیادہ پڑھتے تھے:’’اے اللہ!میں ان گناہوں کےشرسے تیری پناہ میں آتا ہوں جومیں کرچکا ہوں اوران گناہوں کےشر سےبھی جوابھی نہیں کیے۔‘","f2":"1۔ اس قسم کی دعائیں امت کی تعلیم کےلیےہیں یا اپنی عبودیت کے اظہارکےلیے ورنہ آپ سے گناہوں کاصدورممکن نہیں تھا۔ انبیاء علیہم السلام معصوم ہوتے ہیں۔ اللہ تعالی انھیں گناہ سے بچا کر رکھتا ہے۔\n2۔ گناہوں کے شرسے مراد وہ سزا ہے جوگناہوں کےلیے مقرر کی گئی ہے یعنی میرے گناہ معاف فرما۔ آئندہ گناہوں کےشر سے مراد ان کا صدور بھی ہوسکتا ہے کہ مجھ سے وہ گناہ ہی صادر نہ ہوں کیونکہ تقدیر سے توکوئی واقف نہیں۔ واللہ اعلم .\n3۔گناہ خواہ وہ فعل ہویا ترک۔"}],[5524,"ہلال بن یساف کہتے ہیں کہ میں نے ام المؤمنین عائشہ رضی اللہ عنہا سے پوچھا: نبی اکرم صلی اللہ علیہ وسلم کون سی دعا اکثر مانگا کرتے تھے؟ وہ بولیں: آپ اکثر یہی مانگتے تھے: «اللہم إني أعوذ بك من شر ما عملت ومن شر ما لم أعمل بعد» \"اے اللہ! میں اپنے عمل کی برائی سے پناہ مانگتا ہوں، جو میں کر چکا اور جو ابھی نہیں کیے ہیں\" (اور بعد میں کرنے والا ہوں)۔","الألباني: صحيح",{"u2":"حضرت ہلال بن یساف نے کہا کہ سیدہ عائشہ رضی اللہ عنہا سے پوچھا گیا:نبئ اکرم صلی اللہ علیہ وسلم اکثر کون سی دعا کیاکرتےتھے؟انھوں نے فرمایا:آپ اکثر یہ دعا فرمایا کرتے:’’اے اللہ!میں تیری پناہ میں آتا ہوں اپنے ان کاموں کےشرسے جومیں کر چکا ہوں اوران کاموں کے شر سے جومیں نے ابھی نہیں کیے۔‘‘"}],[5525,"فردہ بن نوفل کہتے ہیں کہ میں نے ام المؤمنین عائشہ رضی اللہ عنہا سے پوچھا: رسول اللہ صلی اللہ علیہ وسلم کون سی دعا مانگتے تھے؟ وہ بولیں: آپ صلی اللہ علیہ وسلم کہتے تھے: «أعوذ بك من شر ما عملت ومن شر ما لم أعمل» \"میں عمل کے شر سے تیری پناہ مانگتا ہوں جو میں نے کیا ہے اور جو نہیں کیا ہے\"۔","الألباني: صحيح",{"u2":"حضرت فروہ بن نوفل نے کہا کہ میں نے ام المومنین سیدہ عائشہ رضی اللہ عنہا سے پوچھا:رسول اللہ صلی اللہ علیہ وسلم کیادعا فرمایا کرتےتھے؟اںھوں نے کہا کہ آپ یوں دعا فرمایا کرتےتھے:’’(اے اللہ!) میں تیری پناہ میں آتا ہوں ان کاموں کےشر سے جومیں کر چکا ہوں اوران کاموں کےشر سے جومیں نے نہیں کیے۔‘‘"}],[5526,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کہتے تھے: «اللہم إني أعوذ بك من شر ما عملت ومن شر ما لم أعمل»\"اے اللہ! میں عمل کے شر سے تیری پناہ مانگتا ہوں جو میں نے کیا اور جو نہیں کیا\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ سے روایت ہے انھوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم فرمایا کرتے تھے:’’اے اللہ!میں اپنے کردہ وناکردہ گناہوں کےشرسےتیری پںاہ حاصل کرتاہوں۔‘‘","f2":"’’کردہ ناکردہ یہ مفہوم بھی ہوسکتاہے کہ میں حساب وکتاب کےبکھیڑے میں نہیں پڑتا۔ توسب گناہ معاف فرما۔ اس کے الفاظ کایہ ایک بلیغ مفہوم ہے جوعرف عام میں استعمال ہوتا ہے۔واللہ اعلم ."}],[5527,"فردہ بن نوفل کہتے ہیں کہ میں نے ام المؤمنین عائشہ رضی اللہ عنہا سے سوال کیا کہ مجھے کوئی ایسی چیز بتائیے جس کی رسول اللہ صلی اللہ علیہ وسلم دعا کرتے رہے ہوں؟ وہ بولیں: رسول اللہ صلی اللہ علیہ وسلم کہا کرتے تھے: \"اے اللہ! میں اس عمل کے شر سے تیری پناہ مانگتا ہوں جو میں نے کیا ہے اور جو نہیں کیا ہے\"۔","الألباني: صحيح",{"u2":"حضرت فروہ بن نوفل نے کہا کہ میں نے سیدہ عائشہ رضی اللہ عنہا سے عرض کی:مجھے وہ الفاظ بیان فرمائیے جن کے ساتھ رسول اللہ صلی اللہ علیہ وسلم دعا فرمایا کرتے تھے۔ انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم (یوں دعا)فرماتے تھے:’’اے اللہ!میں اپںے کردہ وناکردہ گناہوں کےشرسے تیری پناہ چاہتا ہوں۔"}],[5528,"فروہ بن نوفل کہتے ہیں کہ میں نے ام المؤمنین عائشہ رضی اللہ عنہا سے کہا: مجھے ایسی دعا بتائیے جو رسول اللہ صلی اللہ علیہ وسلم کرتے رہے ہوں۔ وہ بولیں: آپ صلی اللہ علیہ وسلم کہا کرتے تھے: «اللہم إني أعوذ بك من شر ما عملت ومن شر ما لم أعمل» \"اے اللہ! میں اس عمل کے شر سے تیری پناہ مانگتا ہوں جو میں نے کیا ہے اور جو نہیں کیا ہے\"۔","الألباني: صحيح",{"u2":"حضرت فروہ بن نوفل سے منقول ہے کہ میں نے سیدہ عائشہ رضی اللہ عنہا سے کہا کہ مجھے کوئی ایسی دعا بتلائیے جورسول اللہ صلی اللہ علیہ وسلم فرمایا کرتے تھے۔ انھوں نے کہا:آپ فرماتے تھے:اے اللہ! میں ان کاموں کے شرسے تیری پناہ میں آتا ہوں جو میں کر چکا ہوں اور ان کاموں کے شرسے بھی جو میں نے (ابھی تک) نہیں کیے۔‘‘","f2":"آئندہ گناہوں کےشرسے بھی پںاہ طلب کر جاسکتی ہے کیونکہ آخر ان کا صدور تومقدر ہے۔ اورقیامت کےدن سب گناہ ہی نامئہ اعمال میں موجود ہوں گے۔"}],[5529,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو کہتے ہوئے سنا: «اللہم إني أعوذ بعظمتك أن أغتال من تحتي» \"اے اللہ! میں تیری عظمت اور بڑائی کی پناہ مانگتا ہوں اس بات سے کہ میں نیچے کی طرف سے کسی آفت میں پھنس جاؤں\"۔ یہ حدیث مختصر ہے۔ جبیر کہتے ہیں: اس سے مراد زمین میں دھنس جانا ہے۔ عبادہ کہتے ہیں: مجھے نہیں معلوم کہ یہ رسول اللہ صلی اللہ علیہ وسلم کا قول ہے یا جبیر کا۔","الألباني: صحيح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ نےفرمایا:میں نے رسول اللہ صلی اللہ علیہ وسلم کوفرماتے سنا:اے اللہ میں اس بات سے تیری عظمت کی پناہ میں آتا ہوں کہ میں نیچے سے اچانک ہلاک کر دیا جاؤں۔‘‘یہ حدیث مختصر ہے۔ جبیر نے کہا کہ نیچے سے اچانک ہلاک کردیے جانے سے مراد ہے زمین میں دھنس جانا۔ عبادہ نےکہا:میں نہیں جانتا کہ یہ نبی صلی اللہ علیہ وسلم کافرمان ہے یا جبیر کا (اپنا) قول ہے۔","f2":"1۔تیر ی عظمت جس طرح اللہ تعالی کی ذات سے پناہ لی جاسکتی ہے اسی طرح اللہ تعالی کی صفات کی پناہ بھی لی جاسکتی ہے کیونکہ صفات ذات سے الگ نہیں ہوتیں۔ مقصود ایک ہی ہے۔\n2۔’’نیچےسے‘‘یعنی ایسے عذاب سے جوزمین سےآئے۔ اوردھنسایا جانا (خسف)بھی زمینی عذاب ہی سے ہوتاہے۔ زلزلہ بھی مراد ہوسکتاہے۔ واللہ اعلم ."}],[5530,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کہتے تھے: «اللہم» \"اے اللہ!\" پھر انہوں نے دعا کا ذکر کیا جس کے آخر میں یہ کہا: «أعوذ بك أن أغتال من تحتي» \"میں تیری پناہ مانگتا ہوں کہ میں نیچے کی طرف سے کسی مصیبت میں پھنس جاؤں\" اس سے آپ (زمین میں) دھنس جانا مراد لیتے۔","الألباني: صحيح",{"u2":"سیدہ ابن عمر رضی اللہ عنہا نے فرمایا کہ نبئ اکرم صلی اللہ علیہ وسلم نے فرمایا کرتےتھے:اےاللہ! پھر راوی نے دعا ذکر کی جس کے آخر میں یہ لفظ ہیں۔ میں اس بات سے تیری پناہ میں آتا ہوں کہ مجھے نیچے سے اچانک ہلاک کر دیاجائے۔ ان الفاظ سے آپ کامقصد دھنسائےجانے سے پناہ طلب کرنا تھا۔"}],[5531,"ابوالیسر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کہا کرتے تھے: «اللہم إني أعوذ بك من التردي والهدم والغرق والحريق وأعوذ بك أن يتخبطني الشيطان عند الموت وأعوذ بك أن أموت في سبيلك مدبرا وأعوذ بك أن أموت لديغا» \"اے اللہ! میں اونچائی سے گر پڑنے، دیوار کے نیچے دب جانے، ڈوب جانے، اور جل جانے سے تیری پناہ مانگتا ہوں، اور اس بات سے تیری پناہ چاہتا ہوں کہ موت کے وقت شیطان مجھے بہکا دے، اور اس بات سے تیری پناہ مانگتا ہوں کہ میں تیرے راستہ یعنی جہاد میں پیٹھ دکھا کر بھاگتے ہوئے مروں، اور اس بات سے بھی تیری پناہ مانگتا ہوں کہ (کسی موذی کے) ڈس لینے کی وجہ سے مروں\"۔","الألباني: صحيح",{"u2":"سیدہ ابوالیسر رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم فرمایا کرتےتھے:اے اللہ!میں تیری پناہ میں آتا ہوں اس بات سے کہ کسی اونچی جگہ سے گر جاؤں یا کوئی عمارت مجھ پر گر جائےیا غرق ہوجاؤں یا آگ میں جل مروں۔ اوراس بات سے بھی تیری پناہ میں آتا ہوں کہ مجھے مرتےوقت شیطان بد حواس کردے۔ اورمیں اس بات سے بھی تیری پناہ میں آتا ہوں کہ تیرے راستے میں (دوران جہاد میں) میدان جنگ سے پیٹھ پھیر کر بھاگتا ہوا مارا جاؤں۔ اوراس بات سے بھی تیر پناہ میں آٹا ہوں کہ کسی زہریلی چیز کے ڈسنے سے مرجاؤں۔‘‘","f2":"1۔ ان میں سے اکثرحادثاتی موتین ہیں جن میں انسان اچانک مرجاتا ہے۔ کلمہ اورتوبہ کا موقع نہیں ملتا لہذا یہ موتیں اچھی نہیں۔ ویسے بھی ان سے انسان کی شکل بگڑ جاتی ہے جوظاہر ہے اچھی بات نہیں اس لیے ان سے پناہ مانگنا حق ہے۔\n2۔ میدان جنگ سے بھاگتا جرم عظیم ہے۔اس حال میں موت گناہ والی موت ہے۔ قرآن مجید میں اس کی مذمت کی گئی ہے۔\n3۔ بدحواس کردے یعنی گمراہ کردے یاتوبہ وکلمہ کی طرف توجہ نہ کرنے دیے یااللہ تعالی سے بدگمان کردےوغیرہ۔\n4۔ گر جانے فضا سے یا پہاڑسے یامکان کی چھت وغیرہ سے کہ بچنے کاامکان نہ ہو۔"}],[5532,"ابوالیسر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم دعا فرماتے تو کہتے: «اللہم إني أعوذ بك من الهرم والتردي والهدم والغم والحريق والغرق وأعوذ بك أن يتخبطني الشيطان عند الموت وأن أقتل في سبيلك مدبرا وأعوذ بك أن أموت لديغا» \"اے اللہ! میں بڑھاپے سے، گر پڑنے، دب جانے، رنج و غم میں مبتلا ہونے سے، جل جانے اور ڈوب جانے سے تیری پناہ مانگتا ہوں، اور اس بات سے تیری پناہ مانگتا ہوں کہ شیطان مجھے موت کے وقت بہکا دے، اور اس بات سے کہ میں تیرے راستہ یعنی جہاد میں پیٹھ دکھا کر بھاگتے ہوئے مارا جاؤں، اور تیری پناہ مانگتا ہوں اس بات سے بھی کہ میری موت کسی موذی جانور کے ڈس لینے سے ہو\"۔","الألباني: صحيح",{"u2":"سیدنا ابوالیسر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم دعا میں یوں فرمایا کرتے تھے:اے اللہ! میں سخت بڑھاپے اونچی جگہ سے گر جانے دب جانے غم واندوہ آگ سے جل مرنےاورغرق ہو جانےسے تیر ی پناہ چاہتا ہوں کہ میری موت کے وقت شیطان مجھے بدحواس کرد اوریہ کہ میں دوران جہاد میں میدان جنگ سے پیٹھ پھیر کر بھاگتا ہوا ماراجاؤں۔ اوراس بات سےبھی تیری پناہ چاہتاہوں کہ میں کسی زہریلی چیزکےڈنک سے مرجاؤں۔‘‘"}],[5533,"ابوالاسود سلمی (ابوالیسر) رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کہا کرتے تھے: «اللہم إني أعوذ بك من الهدم وأعوذ بك من التردي وأعوذ بك من الغرق والحريق وأعوذ بك أن يتخبطني الشيطان عند الموت وأعوذ بك أن أموت في سبيلك مدبرا وأعوذ بك أن أموت لديغا» \"اے اللہ! میں (دیوار کے نیچے) دب جانے سے تیری پناہ مانگتا ہوں، اونچائی سے گر پڑنے سے تیری پناہ مانگتا ہوں، ڈوب جانے اور جل جانے سے تیری پناہ مانگتا ہوں، اور اس بات سے تیری پناہ مانگتا ہوں کہ شیطان موت کے وقت مجھے بہکا دے، اور اس بات سے بھی تیری پناہ مانگتا ہوں کہ میری موت تیرے راستہ یعنی جہاد میں پیٹھ دکھا کر بھاگتے ہوئے آئے، اور اس بات سے بھی تیری پناہ مانگتا ہوں کہ کسی موذی جانور کے ڈس لینے سے میری موت ہو\"۔","الألباني: صحيح",{"u2":"حضرت ابوالاسودسلمی رضی اللہہ عنہ س ایسی ہی روایت ہے انھوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم فرمایا کرتےتھے:اے اللہ! میں دب کر مرنے سے تیری پناہ میں آتا ہوں۔ میں نیچے گرکرمرنےسے تیری پناہ کاطالب ہوں۔ میں ڈوپ کر مرنے اورآگ میں جل مرنے سے تیر ی پناہ چاہتا ہوں اورمیں اس بات سے بھی تیری پنا ہ مانگتاہوں کہ موت کےوقت شیطان مجھے بدحواس کردے۔ اور اس بات سے بھی کہ میں تیرے راستے میں (میدان جنگ سے)پیٹھ پھیر کربھاگتا ہوا مرجاؤں۔ اوراس بات سے بھی تیری پناہ میں آتا ہوں کہ کسی زہریلے جانور کےڈسنے سےمارا جاؤں۔‘‘"}],[5534,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ ایک رات میں نے رسول اللہ صلی اللہ علیہ وسلم کو اپنے بستر پر ڈھونڈا تو آپ کو نہیں پایا، چنانچہ میں نے اپنا ہاتھ بستر کے سرہانے پر پھیرا تو وہ آپ کے قدموں کے تلوے سے جا لگا، دیکھا تو آپ سجدے میں تھے، اور فرما رہے تھے: «أعوذ بعفوك من عقابك وأعوذ برضاك من سخطك وأعوذ بك منك» \"میں تیری سزا سے تیری معافی کی پناہ مانگتا ہوں، تیرے غصے اور ناراضگی سے تیری رضا مندی کی پناہ مانگتا ہوں، اور تجھ سے تیری پناہ مانگتا ہوں\"۔","الألباني: صحيح",{"u2":"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے انھوں نے فرمایا کہ ایک رات میں نے رسول اللہ صلی اللہ علیہ وسلم کواپنے بستر پرتلاش کیالیکن آپ مجھے نہ ملے۔ میں نے اپنا ہاتھ بستر کےسرہانے کی جانب مارا تو میرا ہاتھ آپ کےمبارک پاؤں کےتلووں پرلگا۔ آپ سجدے کی حالت میں تھے اورفرما رہے تھے(اے اللہ!) میں تیری سزا سےے بچنے کےلیے تیر معافی کی پناہ میں آتا ہوں۔ تیری ناراضی سے بچنے کےلیے تیری رضامندی کی پناہ حاصل کرتاہوں۔ اورتجھ سے (تیرے عذاب سے بچنے کےلیے)تیری پناہ لیتا ہوں۔‘‘","f2":"سیدہ عائشہ رضی اللہ عنہا اچانک جاگیں تو آپ کوبستر پرنہ پاکر پریشان ہوگئیں۔ فرمارہےتھے گویا سیدہ عائشہ رضی اللہ عنہا اچانک جاگیں تو آپ کو بستر پرنہ پار کر پریشان ہوگئیں۔فرمارہے تھے گویا سیدہ عائشہ رضی اللہ عنہا کاہاتھ لگنے کےبعد آپ نے اونچا پڑھنا شروع کردیا تاکہ پتا چل جائے کہ آپ نماز پڑھ رہے ہیں۔ اللہ تعالی کی رضا مندی کی پناہ حاصل کرنے کا مطلب یہ ہےکہ اے اللہ تو مجھ پر راضی ہوجا ٭ ناراض نہ رہنا وغیرہ۔"}],[5535,"عاصم بن حمید کہتے ہیں کہ میں نے ام المؤمنین عائشہ رضی اللہ عنہا سے پوچھا کہ رسول اللہ صلی اللہ علیہ وسلم رات میں تہجد کس دعا سے شروع کرتے تھے؟ وہ بولیں: تم نے مجھ سے ایسی بات پوچھی ہے جو کسی نے نہیں پوچھی، آپ صلی اللہ علیہ وسلم دس بار «اللہ اکبر» کہتے، دس بار «سبحان اللہ» کہتے، دس بار«استغفراللہ» کہتے، اور کہتے: «اللہم اغفر لي واهدني وارزقني وعافني» \"اے اللہ! میری مغفرت فرما، مجھے ہدایت دے، مجھے روزی عطا کر، مجھے محفوظ رکھ\"، اور آپ قیامت کے روز کھڑے ہونے کی پریشانی (سوال کے لیے) سے اللہ کی پناہ مانگتے۔","الألباني: صحيح",{"u2":"حضرت عاصم بن حمید سےروایت ہے انھوں نے کہا کہ میں نے سیدہ عائشہ رضی اللہ عنہا سے پو چھا:رسول اللہ صلی اللہ علیہ وسلم رات کی نماز کس دعا سے شروع فرماتے تھے؟انھوں نے کہا:تونے مجھ سے ایسی چیز کےبارے میں سوال کیا ہے کہ کسی اورنے وہ چیز نہیں پوچھی۔ آپ دس دفعہ اللہ اکبر کہتے دس دفعہ سبحان اللہ کہتے دس دفعہ استغفر اللہ کہتے۔ پھر فرماتے:اے اللہ مجھے معاف فرما۔ مجھے ہدایت دے۔ مجھے رزق عطا فرما۔ مجھے عافیت عطا فرما۔پھر آپ قیامت کےدن مقام کی تنگی سے اللہ تعالی کی پناہ طلب فرماتے۔","f2":"1۔ قیامت کےدن ہر شخص کواللہ تعالی کے سامنےکھڑا ہوکر چند سوالات کےجوابات دینے ہوں گے۔تنگئی مقام یہ ہے کہ ان سوالات کاجواب نہ سوجھے۔ اورپریشانی کاسامنا کرنا پڑے۔ اعاذنااللہ منہ .\n2۔ یہ ذکر اوردعا ممکن ہے نماز شروع کرنے سے پہلے فرماتےہوں۔ اگردعائے استفتاح کی جگہ ہوتب بھی کوئی حرج نہیں۔"}],[5536,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «اللہم إني أعوذ بك من علم لا ينفع ومن قلب لا يخشع ومن نفس لا تشبع ومن دعا لا يسمع» \"اے اللہ! میں اس علم سے تیری پناہ مانگتا ہوں جو مفید اور نفع بخش نہ ہو، اس دل سے جس میں (اللہ کا) ڈر نہ ہو، اس نفس سے جو سیر نہ ہو اور اس دعا سے جو قبول نہ ہو\"۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: سعید نے یہ حدیث ابوہریرہ رضی اللہ عنہ سے نہیں سنی بلکہ اپنے بھائی سے سنی اور انہوں نے ابوہریرہ رضی اللہ عنہ سے روایت کی ہے۔","الألباني: حسن صحيح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:اے اللہ!میں تیری پناہ میں آتا ہوں اس علم سے جو فائدہ نہ دے اس دل سے جو اللہ تعالی کےسامنے عاجزی نہ کرے اس نفس سے جو سیرنہ ہو اوراس دعا سے جوقبول نہ ہو۔ ‘‘\nابو عبدالرحمن (امام نسائی رحمتہ اللہ) نے فرمایا:سعید (مقبری) نے یہ حدیث سیدنا ابو ہریرہ رضی اللہ عنہ سے نہین سنی بلکہ اس نے اپنے بھائی (عبادبن ابوسعید) سے سنی ہے اوراس (عباد) نے سیدنا ابوہریرہ رضی اللہ عنہ سے (جیسا کہ اگلی روایت میں اس کی صراحت ہے)۔\nسیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:اے اللہ!میں تیری پناہ میں آتا ہوں اس علم سے جو فائدہ نہ دے اس دل سے جو اللہ تعالی کےسامنے عاجزی نہ کرے اس نفس سے جو سیرنہ ہو اوراس دعا سے جوقبول نہ ہو۔ ‘‘\nابو عبدالرحمن (امام نسائی رحمتہ اللہ) نے فرمایا:سعید (مقبری) نے یہ حدیث سیدنا ابو ہریرہ رضی اللہ عنہ سے نہین سنی بلکہ اس نے اپنے بھائی (عبادبن ابوسعید) سے سنی ہے اوراس (عباد) نے سیدنا ابوہریرہ رضی اللہ عنہ سے (جیسا کہ اگلی روایت میں اس کی صراحت ہے)۔\nسیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:اے اللہ!میں تیری پناہ میں آتا ہوں اس علم سے جو فائدہ نہ دے اس دل سے جو اللہ تعالی کےسامنے عاجزی نہ کرے اس نفس سے جو سیرنہ ہو اوراس دعا سے جوقبول نہ ہو۔ ‘‘\nابو عبدالرحمن (امام نسائی رحمتہ اللہ) نے فرمایا:سعید (مقبری) نے یہ حدیث سیدنا ابو ہریرہ رضی اللہ عنہ سے نہین سنی بلکہ اس نے اپنے بھائی (عبادبن ابوسعید) سے سنی ہے اوراس (عباد) نے سیدنا ابوہریرہ رضی اللہ عنہ سے (جیسا کہ اگلی روایت میں اس کی صراحت ہے)۔","f2":"1۔ امام رحمہ اللہ کامقصد یہ بتانا ہے کہ یہ سند منقطع ہے تاہم روایت صحیح ہے کیونکہ اگلی روایت کی سند میں انقطاع ہے۔ واللہ اعلم .\n2۔ جو قبول نہ ہو مقصد یہ ہے کہ یا اللہ مجھے ان خرابیوں سے بچا جن کی بنا پر دعا قبول نہیں ہوتی مثلا رزق حرام عدم خلوص ناجائز دعا وغیرہ۔ (باقی تفصیلات دیکھیے حدیث:\nحدیث نمبر5444"}],[5537,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کہا کرتے تھے: «اللہم إني أعوذ بك من علم لا ينفع ومن قلب لا يخشع ومن نفس لا تشبع ومن دعا لا يسمع» \"اے اللہ! میں اس علم سے تیری پناہ مانگتا ہوں جو مفید اور نفع بخش نہ ہو، اس دل سے جس میں (اللہ کا) ڈر نہ ہو، اس نفس سے جو سیر نہ ہو اور اس دعا سے جو قبول نہ ہو\"۔","الألباني: صحيح",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم فرمایا کرتے تھے:اے اللہ!میں تیری پناہ چاہتا ہوں اس علم سے جونفع مند نہ ہو اس دل سے جس میں خشوع وخضوع نہ ہو اس نفس سے جوسیر نہ ہو اوراس دعا سے جو سنی نہ جائے۔ ‘‘"}],[5538,"عبداللہ بن حارث کہتے ہیں کہ جب زید بن ارقم رضی اللہ عنہ سے کہا جاتا: ہمیں رسول اللہ صلی اللہ علیہ وسلم کی کوئی حدیث سنایئے جو آپ نے خود سنی ہو تو وہ کہتے: میں تم سے وہی بیان کر رہا ہوں جو رسول اللہ صلی اللہ علیہ وسلم نے ہم سے بیان کیا، آپ ہمیں حکم دیتے کہ ہم کہیں: «اللہم إني أعوذ بك من العجز والكسل والبخل والجبن والهرم وعذاب القبر اللہم آت نفسي تقواها وزكها أنت خير من زكاها أنت وليها ومولاها اللہم إني أعوذ بك من نفس لا تشبع ومن قلب لا يخشع ومن علم لا ينفع ودعوة لا تستجاب» \"اے اللہ! عاجزی، سستی، بخیلی، بزدلی، بڑھاپے اور قبر کے عذاب سے تیری پناہ چاہتا ہوں، اے اللہ! تو میرے نفس کو تقوی عطا کر، اسے پاک کر دے، تو ہی سب سے بہتر پاک کرنے والا ہے، تو اس کا سر پرست اور مولا ہے، اے اللہ! میں ایسے نفس سے تیری پناہ مانگتا ہوں جو سیر نہ ہو، ایسے دل سے جس میں خوف الٰہی نہ ہو، ایسے علم سے جو مفید اور نفع بخش نہ ہو اور ایسی دعا ہے جو قبول نہ ہو\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن حارث سے منقول ہے کہ جب حضرت زید بن ارقم سے کہا جاتا کہ ہمیں کوئی ایسی چیز بیان کریں جو آپ نے رسول اللہ صلی اللہ علیہ وسلم کوفرماتے سنا ہوتووہ فرماتے:میں تمھیں وہی چیز بیان کروں گا جو ہمیں رسول اللہ صلی اللہ علیہ وسلم نے بیان فرمائی۔ آپ ہمیں یہ کلمات پڑھنے کاحکم دیتے تھے:اے اللہ!میں نکمے پن کاہلی کنجوسی بزدلی شدید پڑھاپے اورقبر کے عذاب سے تبری پناہ میں آتا ہوں۔ اے اللہ! میرے نفس کوتقوی عطا فرما اوراس کو پاکیزہ فرما کیونکہ تو بہترین پاکیزہ فرمانے والا ہے۔ تواس کا دوست اور مالک ہے۔اے اللہ!میں تیری پناہ مانگتا ہوں اس نفس سے جو سیرنہ ہو اس دل سے جو خشوع وخضوع والا نہ ہو اس علم سے جو مفید نہ ہو اوراس دعا سے حوقبول نہ ہو۔‘"}],[5539,"ام المؤمنین ام سلمہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم جب اپنے گھر سے نکلتے تو فرماتے: «بسم اللہ رب أعوذ بك من أن أزل أو أضل أو أظلم أو أظلم أو أجهل أو يجهل على» \"اللہ کے نام سے شروع کرتا ہوں، میرے رب! میں تیری پناہ مانگتا ہوں کہ مجھ سے غلطی ہو جائے، یا بھٹک جاؤں، یا ظلم کروں، یا مظلوم بنوں، یا جہالت کروں، یا کوئی مجھ سے جہالت سے پیش آئے\"۔","الألباني: صحيح",{"u2":"سیدہ ام سلمہ رضی اللہ عنہا سے مروی ہے کہ نبئ اکرم صلی اللہ علیہ وسلم جب گھر سے باہر تشریف لے جاتے توفرماتے:اللہ تعالی کے نام کی برکت سے اے میرے رب!میں تیری پناہ میں آتا ہوں اس بات سے کہ میں پھسل جاؤں (کوئی لغزش اورغلطی کروں)یا گمراہ ہوجاؤں یا میں کسی پرظلم کروں یا مجھ پرظلم کیا جائے یا میں کسی کے ساتھ نامناسب سلوک کروں یا مجھ سے نامناسب سلوک کیا جائے۔‘‘","f2":"دیکھیے‘روایت:5488۔"}],[5540,"ابومیسرہ کہتے ہیں کہ جب شراب کی حرمت نازل (ہونے کو) ہوئی تو عمر رضی اللہ عنہ نے (دعا میں) کہا: اے اللہ! شراب کے بارے میں صاف صاف آگاہ فرما دے، اس پر سورۃ البقرہ کی آیت نازل ہوئی ۱؎ عمر رضی اللہ عنہ کو بلایا گیا اور انہیں یہ آیت پڑھ کر سنائی گئی، (پھر بھی) انہوں نے کہا: اے اللہ! شراب کے بارے میں صاف صاف آگاہ فرما دے، اس پر سورۃ نساء کی یہ آیت نازل ہوئی «يا أيها الذين آمنوا لا تقربوا الصلاة وأنتم سكارى» \"اے ایمان والو! جب تم نشے کی حالت میں تو نماز کے قریب نہ جاؤ\" (النساء: ۴۳)، چنانچہ رسول اللہ صلی اللہ علیہ وسلم کا منادی جب اقامت کہتا تو زور سے پکارتا: نشے کی حالت میں نماز کے قریب نہ جاؤ، پھر عمر رضی اللہ عنہ کو بلایا گیا اور انہیں پڑھ کر یہ آیت سنائی گئی، (پھر بھی) انہوں نے کہا: اللہ! شراب کے بارے میں ہمیں صاف صاف آگاہ فرما دے، اس پر سورۃ المائدہ کی آیت نازل ہوئی ۲؎، پھر عمر رضی اللہ عنہ کو بلا کر یہ آیت انہیں سنائی گئی، جب «فهل أنتم منتهون» پر پہنچے تو عمر رضی اللہ عنہ نے کہا: ہم باز آئے، ہم باز آئے۔\n§وضاحت\n۱؎: یعنی ارشاد باری تعالی «قل فيهما إثم كبير ومنافع للناس وإثمهمآ أكبر من نفعهما» \" اے نبی ! کہہ دیجئیے کہ ان دونوں :(شراب اور جوا ) میں بہت بڑا گناہ ہے، اور لوگوں کے لیے کچھ فوائد بھی ہیں، لیکن ان کا گناہ ان کے فوائد سے بڑھ کر ہے \" :(البقرة: 219 ) ۲؎: یعنی: ارشاد باری تعالی «إنما يريد الشيطان أن يوقع بينكم العداوة والبغضائ في الخمر والميسر ويصدكم عن ذكر الله وعن الصلاة فهل أنتم منتهون» \" شیطان تو یہی چاہتا ہے کہ وہ شراب اور جوا کے ذریعہ تمہارے آپس میں بغض و عداوت پیدا کر دے، اور اللہ تعالی کی یاد اور نماز سے روک دے، تو کیا تم :(اب بھی ان دونوں سے ) باز آ جاؤ گے ؟ \" :(المائدہ: ۹۱ )۔","الألباني: صحيح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ نے شراب کی حرمت کی تفصیل بیان کرتے ہوئے فرمایا کہ عمر نے کہا اللہ ہمارے لیے شراب کے بارے میں واضح حکم بیان فرما تو وہ آیت اتری جو سورۃ بقرہ میں ہےپھر عمر بلائے گئے اورانھیں وہ آیت سنائی گئی توعمر نے کہا اے اللہ ہمارے لیے شراب کے بارے میں (مزید)واضح بیان فرما۔پھریہ آیت اتری جو سورۃ نساء میں ہے:اے ایمان والوں تم نشے کی حالت میں نماز کے قریب نہ جاؤ۔ رسول اللہ صلی اللہ علیہ وسلم کا مؤذن نماز کے قیام کے وقت یہ اعلان کرتا’’نشے کی حالت میں نماز کے قریب نہ جاؤ۔،، پھر عمر(رضی اللہ عنہ)کو بلا کر ان پر یہ آیت پڑھی گئی تو انھوں نے کہا: اے اللہ! شراب کے بارے میں مزید واضح حکم فرما۔پھر وہ مائدہ والی آیت اتری (جوباب میں درج ہے) تو عمر (رضی اللہ عنہ) کو بلا کر ان پر پڑھی گئی۔جب ان الفاظ تک پہنچے’’ تو کیا تم باز آؤگے؟،، سیدنا عمر رضی اللہ عنہ نے کہا: ہم رک گئے۔ ہم رک گئے۔","f2":"سیدنا عمر رضی اللہ عنہ کے دل میں شراب کی حرمت کا جذبہ اللہ تعالی کی طرف سے الہام تھا\nجو قطعی حکم اترنے پہلے القا کیا گیا تھا تا کہ لوگوں کے دلوں میں شراب سے نفرت پیدا ہو جائے۔"}],[5541,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ میں اپنے قبیلے میں چچا لوگوں کے پاس کھڑا ہوا تھا، میں عمر میں ان سب سے چھوٹا تھا، اتنے میں ایک شخص نے آ کر کہا: شراب حرام کر دی گئی، میں (اس وقت) کھڑے ہو کر لوگوں کو فضیخ شراب ۱؎ پلا رہا تھا، لوگوں نے کہا: اسے الٹ دو، میں نے اسے الٹ دیا۔ (سلیمان کہتے ہیں) میں نے انس رضی اللہ عنہ سے پوچھا: یہ شراب کس چیز کی تھی؟ کہا: «گدر» (ادھ کچی) اور سوکھی کھجور کی، ابوبکر بن انس نے کہا: اس وقت یہی ان کی شراب ہوتی تھی، اس پر انس رضی اللہ عنہ نے انکار نہیں کیا ۲؎۔\n§وضاحت\n۱؎: «گدر» :(ادھ کچی ) اور سوکھی کھجور کی بنی ہوئی شراب۔ ۲؎: گویا «خمر» کا اطلاق کھجور کی شراب پر بھی ہوتا ہے، اور چاہے جس چیز سے بھی بنی ہو اگر اس میں نشہ پیدا کرنے کی صلاحیت ہے تو وہ «خمر» ہے کیونکہ عمر رضی اللہ عنہ شراب کی تعریف یوں کرتے ہیں «الخمر ما خامر العقل» یعنی شراب ہر وہ مشروب ہے جو عقل کو ماؤوف کر دے، اور آپ صلی اللہ علیہ وسلم نے فرمایا ہے: «كل مسكر حرام» یعنی ہر نشہ پیدا کرنے والا مشروب حرام ہے \"، یہ سب نصوص آگے آ رہے ہیں۔","الألباني: صحيح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ نے بیان فرمایا کا ایک دفعہ میں اپنے قبیلے کے لوگوں کو جو میرے چچا لگتے تھے، کھڑا گدر کھجور کی شراب پلا رہا تھا۔ میں ان سب میں سے چھوٹا تھا۔ اتنے میں ایک آدمی نے آکر کہا: شراب حرام کر دی گئی ہے۔انھوں نے کہا: اسے بہا دے۔ میں نے وہ سب کی سب بہادی۔ میں (سلیمان تیمی) نے حضرت انس سے پوچھا: وہ شراب کس چیز کی تھی؟ انھوں نے فرمایا:وہ کچی کھجور وں (گدر) اور خشک کھجوروں کو ملا کربنائی گئی تھی۔ سیدنا انس رضی اللہ عنہ کے بیٹے حضرت ابوبکر نے کہا کہ ان دنوں لوگ کھجوروں کی شراب ہی پیتے تھے۔سیدنا انس رضی اللہ عنہ نے ان کی بات کی تردید نہیں فرمائی۔","f2":"یہ حدیث مبارکہ اس بات کی دلیل ہے کہ خمر صرف انگور سے کشید شدہ شراب کو نہیں کہتے بلکہ ہر نشہ آور مشروب کو خمر ہی کہا جاتا ہے، خواہ انگورو ں سے کشید کیا گیا ہو یا کھجور وں۔اسی طرح اس کشمش سے بنایا گیا ہو یا شہد سے تیار کر دہ ہو۔ خمر اسم جنس ہے اور ہر نشہ آور مشروب پر اس کا اطلاق ہوتاہے ہے۔اگرچہ وہ تھوڑی مقدار ہی میں پیا جائے تب بھی حرام ہے کیونکہ رسول اللہ صلی اللہ علیہ وسلم کا ارشاد گرامی ہے:(ما اسکر کثیرہ فقلیلہ حرام) ’’جس کی زیادہ مقدار نشہ چڑ ھا دے اس کی تھوڑی سی مقدار (لینا) بھی حرام ہے،،(سنن ابی داود الاشربۃ باب ماجاء فی السکر،حدیث 2481، وسنن ابن ماجہ،الاشربۃ،باب ما اسکر کثیرہ فقلیلہ حرام،حدیث 3393) رسول اللہ صلی اللہ علیہ وسلم نے بذات خود خمر کی وضاحت فرمادی ہے۔آپ نے فرمایا (کل مسکر خمر،وکل مسکر حرام)’’ ہر نشہ خمر ہے اور ہر نشہ آور چیز حرام ہے۔،،(صحیح مسلم،الاشربۃ بیان ان کل مسر خمر وان کل خمر حرام، حدیث:2003) ان صحیح احادیث کے باوجو د بعض الناس کا صرف انگوروں سے کشید کر دہ شراب کو خمر کہہ کر حرام قرار دینا اور دیگر شرابوں کو جائز ٹھرانا سینہ زوری کے سو کچھ نہیں۔ گویا جس شراب کو احناف خمر کہتے ہیں وہ تو تحریم کے وقت تھی ہی نہیں یا بہت کم تھی۔ پھر آخر حرام کس کو کیا گیا؟ نیز اگر وہ خمر تھی ہی نہیں تو اسے بہا یا کیوں گیا؟ جب کہ احناف کے بقول اسے نشے سے کم پیا جا سکتا تھا؟ وہ خالص عربی لوگ تھے۔ اگر وہ بھی خمر کا مفہوم نہ سمجھ سکے تو عجمیوں کواس کی سمجھ آگئی؟ ای چہ بوا لعجمی ست؟"}],[5542,"انس رضی اللہ عنہ کہتے ہیں کہ میں انصار کے ایک قبیلے میں ابوطلحہ، ابی بن کعب اور ابودجانہ رضی اللہ عنہم کو شراب پلا رہا تھا، اتنے میں ہمارے پاس ایک شخص نے آ کر کہا: خبر ہے! شراب کی حرمت نازل ہوئی ہے، یہ سن کر ہم لوگ باز آ گئے۔ اور اس وقت شراب فضیخ ہوتی تھی جو گدر (ادھ کچی) اور سوکھی کھجور کا کو ملا کر بنتی تھی۔ اور انس رضی اللہ عنہ نے کہا: جب شراب حرام ہوئی تو اس وقت وہ عام طور پر فضیخ کی ہوتی تھی۔","الألباني: صحيح",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ میں،ابوطلحہ ابی بن کعب،ابو دجانہ اور کچھ دوسرے انصاری لوگوں کو گدر کھجور کی شراب پلا رہا تھا کہ ہمارے پاس ایک آیا اور اس نے کہا: ایک نیا حکم جاری ہوا ہے کہ شراب کی حرمت کا حکم اتر آیا ہے۔ ہم نے شراب اندیل دی، حالانکہ وہ اس دن کچی کھجوروں اور خشک کھجوروں کوملا کر تیار کی گئی تھی۔ سیدنا انس رضی اللہ عنہ نے فرمایا: شراب حرام کی گئی تو لوگوں کی عام شراب کھجوروں سے تیار کر دہ تھی۔"}],[5543,"انس بن مالک رضی اللہ عنہ سے روایت ہے کہ جب شراب حرام کی گئی تو اس وقت لوگوں کی شراب گدر (ادھ کچی) اور سوکھی کھجور کی ہوتی تھی۔","الألباني: صحيح الإسناد",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ نے فرما: جب شراب حرام قرار دی گئی تو ان لوگوں کی شراب کچی کھجوروں اور خشک کھجوروں کو ملا کر تیار ہوتی تھی۔"}],[5544,"جابر رضی اللہ عنہما کہتے ہیں کہ گدر (ادھ کچی) اور سوکھی کھجور کا مشروب خمر (شراب) ہے ۱؎۔\n§وضاحت\n۱؎: یعنی: اگر اس میں نشہ ہو۔","الألباني: صحيح موقوف",{"u2":"سیدنا جابر بن عبد اللہ رضی اللہ عنہ نے فرمایا:گدر (ادھ پکی) اور خشک کھجوروں سے تیار کر دہ نشہ آور مشروب خمر ہے۔"}],[5545,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ گدر (ادھ کچی) اور سوکھی کھجور کا مشروب خمر (شراب) ہے۔ (ابوعبدالرحمٰن نسائی کہتے ہیں:) اعمش نے اسے مرفوعاً روایت کیا ہے۔","الألباني: صحيح موقوف",{"u2":"سیدنا جابر بن عبد اللہ رضی اللہ عنہ نے فرمایا: گدر اور خشک کھجوروں سے خمر تیار ہوتی ہے۔\nاعمش نے اس حدیث کو مرفوع بیان کیاہے۔","f2":"امام نسائی  یہ بتانا چاہتے ہیں کہ شعبہ،سفیان او راعمش تینوں نے یہ روایت محارب بن دثار سے بیان کی ہے۔ شعبہ اور سفیان نے تو اسے موقوف، یعنی سیدنا جابر رضی اللہ عنہ کا قول بیان کیا ہے جبکہ اعمش نے ان دونو ں کی مخالفت کرتے ہوئے اسکو مرفوع،یعنی رسول اللہ کا فرمان کہا ہے جیسا کہ اس سے اگلی روایت:5548 کی سند دیکھنے سے یہ واضح طور پر معلوم ہوتاہے۔ یہ روایت موقوفا اور مرفوعا دونوں طرح درست اور صحیح ہے۔واللہ اعلم،"}],[5546,"جابر رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: انگور اور کھجور کا مشروب خمر (شراب) ہے۔","الألباني: صحيح",{"u2":"سیدنا جابر رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرما یا: ’’ منقی اور کھجوروں سے تیار کردہ نشہ آور مشر وب خمر -(شراب)ہے۔،،","f2":"اس باب اور متعلقہ احادیث کا مقصد احناف کے موقف کی تردید ہے۔"}],[5547,"ایک صحابی رسول رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے «بلح» ادھ کچی اور سوکھی کھجور کی اور انگور اور سوکھی کھجور (کی نبیذ) سے منع فرمایا۔","الألباني: صحيح الإسناد",{"u2":"نبی اکرم صلی اللہ علیہ وسلم کے ایک صحابی سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے گدرہ اور خشک کھجور کی مشتر کہ نبیذ اور منقی او رکھجور کی مشتر کہ نبیذ سے منع فرمایاہے۔","f2":"(1)کسی پھل کو پانی میں ڈال دیا جاتا ہے،پھر جب و ہ نرم ہوجاتاہے تو پھل کو ہاتھوں سے پانی مسل دیا جاتاہے،اور پھر کسی کپڑے سے وہ پانی نچوڑ لیا جاتا ہے تا کہ پھل پھوک الگ ہو جائے او رپھر وہ پھل کے اثر والا پانی پی لیا جاتا ہے۔ اس نبیذ کہتے ہیں۔ یہ ذائقہ دار اور مقوی ہوتی ہے۔ اس پینے میں کوئی حرج نہیں مگر اسے زیادہ دیر نہ رکھا جائے ورنہ اس میں نشہ پیدا ہو جا تا ہے۔اگر وہ نشہ آور ہو جائے تو پھر شراب کی طرح حرام ہے۔اگر نبیذ دو قسم کے پھلوں سے بنائی جائے،یعنی دونوں پھلوں کے پانی میں ڈالاجائے تو اس میں جلدی نشہ پیدا ہونے کا امکان ہوتا ہے کیو نکہ اس میں کیمیائی عمل زیادہ تیزی سے شروع ہو جاتا ہے،اس لیے دو چیزوں کی نبیذ سے مطلقا روک دیا گیا ہے۔اگر چہ نشہ پیدا نہ ہونے کی صورت میں اس کا استعمال درست ہے مگر عام لوگ نشے کے معاملے میں زیادہ حساس نہیں ہوتے۔ ممکمن ہے انہیں نشے کا پتا نہ چلے، اس لیے مطلقا روک دیا گیا۔بعض علماء کے نزدیک دوپھلوں کی نبیذ سے نہی کی وجہ تعیش ہے، جیسے دو سالن پکانے سے منع کیا گیا ہے۔(2) گدر اور خشک کھجور آپس میں بہت مختلف ہوتی ہے،اس لیے ان کو دو پھلوں قائم مقام قرار دیا گیاہے۔"}],[5548,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کدو کی تو نبی، لاکھی، روغنی اور لکڑی کے برتن میں نبیذ بھگو کر پینے سے منع فرمایا ۱؎، اور اس بات سے کہ پکی اور کچی کھجور ملا کر نبیذ بنائی جائے۔\n§وضاحت\n۱؎: شراب کی حرمت سے پہلے ان برتنوں میں شراب بنائی جاتی تھی، جب اس کی حرمت نازل ہوئی تو ان کے اندر نبیذ بنانے سے منع کر دیا گیا کہ ایسا نہ ہو کہ سابقہ اثرات کی وجہ سے نبیذ میں نشہ آ جائے، اور جب یہ برتن خوب سوکھ گئے اور شراب کے اثرات زائل ہو گئے اور لوگوں کی شراب پینے کی عادت بھی جاتی رہی تب ان برتنوں کے اندر نبیذ بنانے کی اجازت دے دی گئی، :(دیکھئیے حدیث نمبر ۵۵۶۵، اور اس کے بعد کی حدیثیں )۔","الألباني: صحيح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کدو کے برتن،مٹکے،تارکول لگے ہوئے برتن اور کھجور کی جڑ سے بنائے گئے برتن (میں نبیذ بنانے)سے منع فرمایا ہے۔اسی طرح بلح اور زہو کھجور کو ملا کر نبیذ بنانے سے بھی منع فرمایا ہے۔","f2":"(1) مذکورہ برتنوں میں مسام نہ ہونے یا مسام بند ہونے کی وجہ سے جلدی نشہ پیدا ہو جاتا ہے، اس لیے ان برتنوں میں نبیذ بنانے سے منع فرمایا ہے۔ یا یہ برتن شراب بنانے کے لیے استعمال ہوتے تھے۔شراب کی حرمت کے وقت عارضی طور پر ان برتنوں کے جائز استعمال سے بھی روک دیا گیا تا کہ شراب کا خیال بھی نہ آئے۔بعد میں یہ برتن استعمال کرنے کی اجازت دے دی گئی،البتہ احتیاط کی جائے کہ نشہ پیدا نہ ہو ورنہ مشروب حرام ہوجائے گا۔نشہ پیدا نہ ہوتو کوئی حرج نہیں۔\n(2) بلح،زہو، بسر،رطب اور تمر کھجور ہی کی مختلف حالیتیں ہیں۔ بلح کچی کھجور کو کہتے ہیں جب تک اس کا رنگ سبز ہو۔ بسر گدر،یعنی نیم پختہ کھجور کو جب وہ کچھ نرم ہو جائے۔زہو جب وہ پکنے لگے اور رنگ بدل جائے۔رطب جب وہ مکمل پک جائے اور تازہ ہو۔ اور تمر جب وہ خشک ہو جائے اور تری جاتی رہے۔یہ تما م حالتیں ایک دوسری سے بہت مختلف ہیں، لہذا ان کو الگ الگ پھل کا حکم دیا جائے گا۔ اور ان میں کوئی سی بھی جوقسموں کی مشتر کہ نبیذ پینا منع ہے۔"}],[5549,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کدو کی تو نبی اور روغنی برتن دوسری بار اتنا زیادہ کیا، لکڑی کے برتن سے، اور کھجور کو انگور کے ساتھ اور کچی کھجور کو پکی کھجور کے ساتھ ملا کر نبیذ بنانے سے منع فرمایا۔","الألباني: صحيح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کدو کے برتن،تارکول لگے ہوئے برتن اور کھجور کی جڑ سے بنائے گئے برتن سے منع فرمایا،نیز کھجور کو منقی سے ملا کر پکنے کے قریب کھجور کو خشک کھجور سے ملا کر نبیذ بنانے سے بھی منع فرمایا"}],[5550,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کچی کھجور اور پکی کھجور، انگور اور کھجور (کی نبیذ) سے منع فرمایا۔","الألباني: صحيح",{"u2":"سیدنا ابو سعید خدری رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے پکنے کے قریب اور خشک کھجور،نیز منقی اور خشک کھجور کی مشترکہ نبیذ کے استعال سے منع فرمایا۔"}],[5551,"ابوقتادہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"سوکھی کھجور اور انگور کو ملا کر نبیذ نہ بناؤ، اور نہ ہی کچی اور تازہ کھجور کو ملا کر نبیذ بناؤ\" ۱؎۔\n§وضاحت\n۱؎: کیونکہ ملانے سے ان دونوں میں تیزی سے نشہ پیدا ہوتا ہے۔","الألباني: صحيح",{"u2":"سیدنا ابو قتادہ رضی اللہ عنہ سے روایت ہے کہ نبی اکر م صلی اللہ علیہ وسلم نے فرمایا:’’ کھجور اور منقی اسی طرح پکنے کے قریب اور تازہ کھجور کو (نبیذ بنانے کے لیے)اکٹھا نہ کرو۔،،"}],[5552,"ابوقتادہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کچی اور تازہ کھجور ایک ساتھ ملا کر نبیذ نہ بناؤ، اور نہ انگور اور تازہ کھجور ملا کر نبیذ بناؤ\"۔","الألباني: صحيح",{"u2":"سیدنا ابو قتادہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ کچی اور تازہ کھجور کی مشتر کہ نبیذ نہ بناؤ۔اسی طرح منقی اور تازہ کھجور کی مشترکہ نبیذ نہ بناؤ۔،،"}],[5553,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ سوکھی کھجور اور انگور کو ملانے، کچی اور سوکھی کھجور کو اور کچی اور ادھ کچی کھجوروں کو ملانے سے رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا ہے۔","الألباني: صحيح",{"u2":"سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کھجور اور منقی یا پکنے کے قریب اور خشک کھجور یا کچی اور گدر کھجور کو ملا کر نبیذ بنانے سے منع فرمایاہے۔"}],[5554,"جابر رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے سوکھی کھجور اور انگور، ادھ کچی اور تازہ کھجور سے بنے مشروب سے منع فرمایا ہے ۱؎۔\n§وضاحت\n۱؎: کیونکہ ان چیزوں سے بنائے گئے مشروب میں نشہ پیدا ہو جاتا ہے، اسی طرح ان ہر دو تین چیزوں کو ملا کر مشروب بنانے کا معاملہ ہے جن کے آمیزے سے اگلی حدیثوں میں منع کیا گیا ہے، دیکھئیے باب نمبر ۱۳ اور اس میں مذکور حدیثیں۔","الألباني: صحيح",{"u2":"سیدنا جابر رضی اللہ عنہ سےمنقول ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے کھجور اور منقی،نیز گدر اور تازہ کھجور کی مشترکہ نبیذ سے منع فرمایا ہے۔"}],[5555,"جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"انگور اور سوکھی کھجور کو نہ ملاؤ اور نہ ہی ادھ کچی اور خشک کھجور کو\" ۱؎۔\n§وضاحت\n۱؎: یہ بطور «حصر» کے نہیں ہے کہ \" شراب صرف وہی مشروب ہے جو صرف انہی دونوں درختوں کے پھلوں سے بنے \"، یہ صرف اس مشروب کا بیان ہے جو اہل مدینہ اس وقت بناتے تھے، کیونکہ ارشاد نبوی ہے «کل مسکر حرام» اور عمر رضی اللہ عنہ اور دیگر صحابہ و تابعین کی یہ تصریحات موجود ہیں کہ «الخمر ما خامر العقل» :(دیکھئیے ابواب رقم ۲۲و ۲۳ )","الألباني: صحيح",{"u2":"سیدنا جابر رضی اللہ عنہ سے روایت ہے کہ رسو ل اللہ صلی اللہ علیہ وسلم نے فرمایا:’’منقی اور کھجور اسی طرح گدر اور خشک کھجور کو ملا کر نبیذ نہ بناؤ۔،،"}],[5556,"جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے انگور اور سوکھی کھجور ایک ساتھ ملا کر نبیذ بنانے سے منع فرمایا نیز ادھ کچی اور سوکھی کھجور ایک ساتھ ملا کر نبیذ بنانے سے منع فرمایا ہے۔","الألباني: صحيح",{"u2":"سیدنا جابر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلمنے منقی اور کھجور کو ملا کر نبیذ بنانے سے منع فرمایا۔ اسی طرح گدر او رخشک کھجور کو ملا کر نبیذ بنانے سے بھی منع فرمایا"}],[5557,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کدو کی تو نبی، سبز رنگ کی ٹھلیا، روغنی برتن اور لکڑی کے برتن سے، ادھ کچی اور سوکھی کھجور کو ملانے سے اور انگور اور سوکھی کھجور کو ملانے سے منع فرمایا اور اہل ہجر (احساد) کو لکھا: انگور اور سوکھی کھجور کو ایک ساتھ نہ ملاؤ۔","الألباني: صحيح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ نے فرمایا:رسول اللہ صلی اللہ علیہ وسلم نے کدو کے برتن،مٹکے،تارکول ملے ہوئے برتن او رکھجور کی جڑ سے بنائے گئے برتن (میں نبیذ بنانے) سے منع فرمایا۔ اسی طرح گدر اور خشک کھجور کو ملا کر یا منقی اور کھجور کو ملا کر نبیذ بنانے سےمنع فرمایا۔ آپ نے علاقہ ہجر کے لوگوں کو لکھ بھیجا تھا کہ منقی اور کھجور کوملا کر نبیذ نہ بناؤ۔","f2":"تفصیل کے لیے دیکھیے حدیث نمبر5550"}],[5558,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ ادھ کچی کھجور تنہا بھی حرام اور سوکھی کھجور کے ساتھ ملا کر بھی حرام ہے ۱؎۔\n§وضاحت\n۱؎: یعنی اس کا نبیذ بنانا جائز اور صحیح نہیں ہے۔","الألباني: صحيح الإسناد",{"u2":"سیدنا ابن عباس رضی اللہ عنہ نے فرمایا:بسر،یعنی گدر کھجور اکیلی کی نبیذ بھی حرام ہے اور خشک کھجور کے ساتھ ملا کر بھی حرام ہے۔","f2":"ممکن ہے بسر کی نبیذ میں جلدی نشہ پیدا ہوتا ہو،اس لیے سیدنا ابن عباس رضی اللہ عنہ اسے حرام سمجھے ہوں۔\nبہر صورت یہ حرام تبھی ہے جب اس میں نشہ پید ا ہو جائے ورنہ نہیں مگر بسر وتمر کی مشترکہ نبیذ ہر حال میں حرام ہے نشہ پیدا ہو یا نہ ہو، کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے اس سے مطلقا منع فرمایا ہے۔اگر چہ احناف کے نزدیک مشترکہ نبیذ اگر نشہ آور نہ ہو تو جائز ہے مگر یہ صریح احادیث کے خلاف ہے۔رائے اور قیاس نص کے مقابلے میں مذموم ہے۔(مزید دیکھیے،حدیث:5549)"}],[5559,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سوکھی کھجور اور انگور سے اور سوکھی اور ادھ کچی کھجور سے بنے مشروب سے منع فرمایا ہے۔","الألباني: صحيح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کھجور ومنقی او رخشک وگدر کھجور کی مشترکہ نبیذ سے منع فرمایاہے۔"}],[5560,"عمرو بن دینار کہتے ہیں کہ میں نے جابر بن عبداللہ رضی اللہ عنہما کو کہتے ہوئے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے سوکھی کھجور اور انگور سے منع فرمایا ہے اور سوکھی اور ادھ کچی کھجور سے منع فرمایا کہ ان کی ایک ساتھ نبیذ بنائی جائے۔","الألباني: صحيح",{"u2":"سیدنا جابر بن عبد اللہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کھجور ومنقی کو ملا کر اور خشک اور گدر کھجور کو ملا کر نبیذ بنانے سے منع فرمایا ہے۔"}],[5561,"ابوقتادہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"کچی اور پکی کھجور ملا کر نبیذ نہ بناؤ، اور نہ ہی تازہ کھجور اور کشمش ملا کر نبیذ بناؤ\"۔","الألباني: صحيح",{"u2":"سیدنا ابوقتادہ رضی اللہ عنہ سے روایت ہے کہ نبی اکر م صلی اللہ علیہ وسلم نے فرمایا:’’پکنے کے قریب اور تازہ کھجور کی مشترکہ نبیذ نہ بناؤ۔ اور تازہ کھجور اور منقی کو ملا کر نبیذ نہ بناؤ۔،،"}],[5562,"جابر رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا کہ کشمش اور ادھ کچی کھجور ملا کر نبیذ بنائی جائے، نیز منع فرمایا کہ ادھ کچی اور تازہ کھجور ملا کر نبیذ بنائی جائے۔","الألباني: صحيح",{"u2":"سیدنا جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے منقی اور گدر کھجور کو ملا کر نبیذ بنانے سے منع فرمایا۔ اسی طرح گدر کھجور اور تازہ کھجور کو ملا کر نبیذ بنانے سے منع فرمایا۔"}],[5563,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے نبیذ کے لیے ایسی دو چیزوں کو ملانے سے منع فرمایا کہ ان میں سے کوئی ایک دوسری کو تیزی سے نشہ آور بناتی ہے۔ میں نے آپ صلی اللہ علیہ وسلم سے فضیخ کے بارے میں پوچھا تو آپ نے مجھے اس سے منع فرمایا۔ آپ اس ادھ کچی کھجور کو بھی ناپسند فرماتے تھے جو ایک طرف سے پکنا شروع ہو رہی ہو، اس ڈر سے کہ وہ بھی گویا دو چیزیں ہیں۔ چنانچہ ہم اسے کاٹ کر پھینک دیتے تھے ۱؎۔\n§وضاحت\n۱؎: یعنی جتنا حصہ پک جاتا اس کو نکال کر پھینک دیتے اور باقی حصے کی نبیذ بنا لیتے۔","الألباني: صحيح الإسناد",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں نبیذ میں دو چیزیں اکٹھی کرنے سے منع فرمایا ہے کیونکہ ایک دوسری کو تیز کرے گی۔ میں نے ان سے فضیخ کے بارے میں پوچھا تو انہوں نے مجھے اس سے منع کردیا۔وہ اس گدر کھجور کی نبیذ کو ناپسند کرتے تھے جو ایک طرف سے پک چکی ہو، اس خطرے سے کہ وہ دوقسم کا پھل ہے۔تو ہم اس کی ایک جانب کاٹ دیتے تھے۔","f2":"(1) ’’ تیز کرے گی، یعنی دوقسم کے پھل ملنے سے تیزر پیدا ہوگی اور نشہ جلدی پیدا ہوگا، لہذا دوقسم کے پھلوں کو ملا کر نبیذ بنانا منع ہے۔تفصیل پیچھے گزر چکی ہے۔\n(2) فضیخ،یہ ایک قسم کی شراب تھی جو گدر کھجور سے بغیر آگ پر پکائے تیار کی جاتی تھی۔ یہ نشہ آور ہوتی تھی لہذا ممنوع ہے۔\n(3) ایک طرف سے پک چکی ہو،، ایک طرف پکی اور ایک طرف سے کچی۔ گویا ایسی ایک کھجور بھی بظاہر دوقسم کا پھل ہے۔گدر بھی اور رطب (تازہ پکی ہوئی کھجور)بھی، اس لیے ایسی کھجور کی نبیذ سے بھی پرہیز بہتر ہے جیسا کہ سیدنا انس رضی اللہ عنہ نے کیا۔ اگر دونوں حصوں کو الگ الگ کر کے ایک حصے سے نبیذ بنائی جائے تو سرے سے کراہت والی بات ہی نہیں رہتی جیسا کہ حدیث میں ذکر ہے۔"}],[5564,"ابوادریس کہتے ہیں کہ میں انس بن مالک رضی اللہ عنہ کے پاس حاضر تھا ان کے پاس ایسی ادھ کچی کھجور لائی گئی جو ایک طرف سے پک رہی تھی، وہ اس میں سے اسے(پکے ہوئے حصے کو) کاٹ کر پھینکنے لگے۔","الألباني: صحيح لغيره",{"u2":"حضرت ابو ادریس سے روایت ہے کہ میں نے دیکھا،سیدنا انس بن مالک رضی اللہ عنہ کےپاس گدر کھجور لائی گئی جو ایک طرف سے پک چکی تھی۔آپ اس کے پکے ہوئے سرے کو کاٹنے لگے (تاکہ ایک حصے سے نبیذ بنائی جائے نہ دونوں سے)۔"}],[5565,"قتادہ کہتے ہیں کہ انس رضی اللہ عنہ ہمیں ایک طرف سے پکی ہوئی کھجور کے بارے میں کاٹ کر پھینکنے کا حکم دیتے۔\nحمید سے روایت ہے کہ انس رضی اللہ عنہ جس قدر کھجور کا حصہ پک چکا ہوتا اسے فضیخ سے نکال پھینکتے ۱؎۔\n§وضاحت\n۱؎: فضیخ ادھ کچی کھجور کے نبیذ کو بھی بولتے ہیں۔","الألباني: صحيح الإسناد",{"u2":"سیدنا انس رضی اللہ عنہ کھجور کے پکے ہوئے حصے کو نہیں رہنے دیتے تھے بلکہ (نبیذ بنانے کے لیے)گدر حصے سے الگ کردیتے تھے۔"}],[5566,"ابوقتادہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کچی کھجور اور پکی کھجور کی ایک ساتھ نبیذ نہ بناؤ اور نہ ہی ادھ کچی کھجور اور انگور کی ایک ساتھ، بلکہ ان میں سے ہر ایک کو الگ الگ بھگوؤ\"۔","الألباني: صحيح",{"u2":"سیدنا ابو قتادہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’پکنے کے قریب اور پکی کھجوروں کو ملا کر نبیذ نہ بناؤ۔ (اسی طرح)گدر کھجور اور منقی کو بھی نہ ملاؤ بلکہ ان میں سے ہر ایک الگ الگ نبیذ بناؤ۔"}],[5567,"ابوقتادہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے کچی اور سوکھی کھجور سے اور ادھ کچی اور سوکھی کھجور سے نبیذ بنانے سے منع فرمایا اور فرمایا:\"تم ان میں سے ہر ایک کو الگ الگ بھگویا کرو ان مشکوں میں جن کے منہ دھاگے سے بندھے ہوں\"۔","الألباني: صحيح الإسناد",{"u2":"سیدنا ابوقتادہ رضی اللہ عنہ سےمنقول ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے پکنے کے قریب اور خشک کھجور کی مشتر کہ نبیذ اور (اسی طرح)گدر اور خشک کھجور کی مشترکہ نبیذ سے منع کیا۔ اور آپ نے فرمایا:’’ ان میں سے ہر ایک کی الگ الگ نبیذ ان مشکیزوں میں بناؤ جن کا منہ باندھا جاتاہے۔،،","f2":"باب کا مقصود یہ ہے کہ نبیذ مٹکوں وغیرہ کی بجائے چمڑے کے مشکیزوں میں بنائی جائے (چمڑے کے مشکیزے کا ہی منہ باندھا جا سکتاہے) مٹکوں خصوصا تارکول لگے ہوئے مٹکوں میں جلدی نشہ پیدا ہو جاتا ہے۔"}],[5568,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ادھ کچی کھجور کو سوکھی کھجور میں ملانے، یا کشمش (خشک انگور) کو سوکھی کھجور میں، یا کشمش کو ادھ کچی کھجور میں ملانے سے منع فرمایا، اور فرمایا: \"جو شخص تم میں سے پینا چاہے تو ان میں سے ہر ایک کو الگ الگ پیے، سوکھی کھجور الگ یا ادھ کچی کھجور الگ یا کشمش(خشک انگور) الگ\"۔","الألباني: صحيح",{"u2":"سیدنا ابوسعید خدری رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے گدر (نیم پختہ)کھجور کو خشک کھجور کے ساتھ ملا کر یا منقی کو خشک کھجور کے ساتھ ملا کر یا منقی کو گدر کھجور سے ملا کر نبیذ بنانے سے منع فرمایا۔آپ نے فرمایا:’’ جو تم میں سے نبیذ پینا چاہے، وہ ان میں س ایک چیز کی نبیذ پیے: صرف خشک کھجور کی یا صرف گدر کھجورکی یا صرف منقی کی۔،،"}],[5569,"ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے ادھ کچی کو سوکھی کھجور میں ملانے یا کشمش (خشک انگور) کو سوکھی کھجور میں یا کشمش کو ادھ کچی کھجور میں ملانے سے منع فرمایا اور فرمایا: \"تم میں سے جو کوئی پینا چاہے تو ان میں سے ہر ایک کو الگ الگ کر کے پئے\"۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: ابوالمتوکل کا نام علی بن داود ہے۔","الألباني: صحيح",{"u2":"سیدنا ابوسعید خدری رضی اللہ عنہ نے بیان فرمایا کہ نبی اکرم صلی اللہ علیہ وسلم نے گدر کھجور کو خشک کھجور کے ساتھ یا منقی کو خشک کھجور کے ساتھ یا منقی کو گدر کھجور کے ساتھ ملانے سے منع فرمایا۔ آپ نے فرمایا:’’ تم میں سے جو شخص نبیذ پینا چاہے تو ان میں سے کسی ایک چیز کی نبیذ پیے۔،،\nابو عبد الرحمان (امام نسائی رحمہ اللہ) نے کہا کہ راوئ حدیث ابو المتوکل کا نام علی بن داودہے"}],[5570,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ادھ کچی کھجور اور کشمش، ادھ کچی کھجور اور سوکھی کھجور کو ملانے سے منع فرمایا، اور فرمایا: \"ان میں سے ہر ایک کی الگ الگ نبیذ بناؤ\"۔","الألباني: حسن صحيح",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ فرماتے ہیں کہ رسو ل اللہ صلی اللہ علیہ وسلم نے منع فرمایا کہ (نبیذ بنانے کے لیے)گدر کھجور او رمنقی کو یا گدر او رخشک کھجور کو ملا یا جائے۔ آپ نے فرمایا:’’ ان میں سے ہر ایک کی الگ الگ نبیذ بناؤ۔"}],[5571,"ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے سوکھی کھجور اور کشمش (سوکھے انگور) ملا کر اور سوکھی کھجور اور ادھ کچی کھجور ملا کر نبیذ بنانے سے منع فرمایا، اور فرمایا: \"کشمش کی الگ، سوکھی کھجور کی الگ اور ادھ کچی کھجور کی الگ نبیذ بناؤ\"۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: ابوکثیر کا نام یزید بن عبدالرحمٰن ہے۔","الألباني: صحيح",{"u2":"سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے منع فرمایا کہ کھجور وں او رمنقی کو ملا کر یا کھجوروں اور گدر کھجوروں کو ملا کر نبیذ بنائی جائے آپ نے فرمایا:’’ منقی کی الگ نبیذ بناؤ، کھجور کی الگ اور گدر کھجور کی الگ۔،،\nابو عبد الرحمان (امام نسائی رحمہ اللہ) نے کہا ک (راوئ حدیث)ابو کثیر کا نام یزید بن عبد الرحمان ہے۔","f2":"امام نسائی رحمہ اللہ جس ابو کثیر کے نام کی وضاحت فرمارہے ہیں وہ حدیث سابق: 5573 کا راوی ہے، اس لیے اس وضاحت اور تصریح کا اصل مقام سابقہ حدیث کے تحت ہی تھا۔ بہتر یہی تھا کہ یہ وضاحت اس حدیث سے اوپر والی حدیث کے تحت کی جاتی۔شاید یہ کاتب وغیرہ کا سہوہو -واللہ اعلم۔"}],[5572,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"خمر (شراب) ان دو درختوں سے (بنتی) ہے، (اور سوید کی روایت میں ہے کہ شراب ان دو درختوں: کھجور اور انگور سے بنتی ہے\"۔\n§وضاحت\n۱؎: اور کھجور اور انگور کے پھلوں میں :(تمہیں غور کرنا چاہیئے ) جن سے تم نشہ آور چیزیں اور بہترین روزی بناتے ہو :(النحل: ۶۷ )۔","الألباني: صحيح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سےمنقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ شراب ان دو درختوں (کے پھلوں)سے تیار ہوتی ہے: کھجور اور انگور۔،،","f2":"(1) کتاب الاشربہ کے شروع میں بیان ہو چکا ہے کہ ائمہ مالک،شافعی،احمد او ر جمہور اہل علم کے نزدیک شراب کسی بھی پھل یا غلے سے تیار کی جاسکتی ہے جب اس میں نشہ پایا جائے،جبکہ اہل رائے،یعنی احناف کے نزدیک شراب صرف انگور سے تیار ہوسکتی ہے اور وہ بھی مخصوص طریعے پر جس کی تفصیل شروع میں بیان ہوچکی ہے،لیکن یہ بات غلط ہے۔ لغت، عقل سلیم اور شرع کے خلاف ہے۔ خمر کے معنی ہیں ’’عقل کو ڈھانپنے والی،، یعنی نشہ آور مشروب،خوا وہ کسی چیز سے تیار کی گئی ہو۔ رسول اللہ صلی اللہ علیہ وسلم کا ارشاد ہے:(الخمر ما خامر العقل) یعنی خمر سے مراد ہروہ چیز ہے جو عقل کو پردے میں کردے کہ پینے سے عقل جاتب رہے، نیز یہ مسلک اس باب میں مذکورہ آیت اوراحادیث کے بھی خلاف ہے۔ آیت مذکورہ میں کھجور وانگور دونوں سے نشہ آور مشروب بنانے کا ذکر ہے اور دونوں کو اکٹھا ذکر کیا گیاہے۔ معلوم ہوا حکم بھی ایک ہے۔ احادیث میں تو انتہائی حد تک صراحت ہے کہ شراب کھجور سے بھی بن سکتی ہے۔\n(2) حدیث میں دو چیزوں (کھجور وانگور) کا ذکر یہ مطلب نہیں کہ ان کے علاوہ کسی اور پھل سے شراب نہیں بن سکتی بلکہ مقصد یہ ہے ہ عموما عر ب یا اہل مدینہ ان دو چیزون سے شراب تیار کرتے تھے ورنہ جس پھل یا غلے سے بھی نشہ آور مشروب تیار کیا جائے اسے شراب،یعنی خمر کا حکم حاصل ہوگا اور اس کا ایک گھونٹ بھی حرام ہوگا۔"}],[5573,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"شراب ان دو درختوں سے بنتی ہے: کھجور اور انگور\"۔","الألباني: صحيح",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’شراب (عموما) ان دو درختوں (یعنی)کھجور وانگور (کے پھلوں) سے تیار ہوتی ہے۔،،"}],[5574,"ابراہیم نخعی اور عامر شعبی کہتے ہیں کہ ہر نشہ لانے والی شے خمر (شراب) ہے۔","الألباني: ضعيف",{"u2":"حضرت ابراہیم او ر شعبی نے فرما یا: ہر نشہ آور شراب (کا حکم رکھتی)ہے۔ (یا آیت میں)’’ سکر،، سے مراد شراب ہے۔ (جو حرام ہے جبکہ رزق حسن،یعنی نبیذ وغیرہ جو نشہ آور نہ ہو،حلال ہے۔)"}],[5575,"سعید بن جبیر کہتے ہیں کہ عبدالرحمٰن بن ابی لیلی نے مجھے حکم دیا کہ میں ابن عباس سے ان دو آیتوں «ومن يقتل مؤمنا متعمدا فجزاؤه جهنم»،«والذين لا يدعون مع اللہ إلها آخر ولا يقتلون النفس التي حرم اللہ إلا بالحق» کے متعلق پوچھوں، اور میں نے اس کے بارے میں پوچھا تو انہوں نے کہا: اسے کسی چیز نے منسوخ نہیں کیا۔ اور دوسری آیت کے بارے میں انہوں نے کہا: یہ اہل مشرکین کے بارے میں نازل ہوئی۔\nسعید بن جبیر کہتے ہیں کہ ہر نشہ لانے والی چیز خمر ہے۔","الألباني: صحيح",{"u2":"حضرت سعید بن جبیر سے منقول ہے (آیت مذکورہ میں)’’سکر،،سے مراد شراب ہے۔"}],[5576,"سعید بن جبیر کہتے ہیں کہ ہر نشہ لانے والی چیز خمر ہے۔","الألباني: صحيح الإسناد",{"u2":"حضرت سعید بن جبیر سے منقول ہے کہ ’’سکر،،ہے مراد شراب ہے۔"}],[5577,"سعید بن جبیر کہتے ہیں کہ نشہ حرام ہے اور بہترین روزی حلال ہے۔","الألباني: صحيح الإسناد",{"u2":"حضرت سعید بن جبیر نے فرما یا: سکر (نشہ آور مشروب)حرام ہے۔ اور رزق حسن (نبیذ وغیرہ)حلال ہے۔","f2":"مختلف بابعین کے اقوال نقل کرنے سے مقصود یہ ہے کہ کوفی،بصری اور مکی تابعین کے نزدیک انگور کی طرح کھجور سے بھی شراب تیار ہوسکتی ہے۔اور یہی مسلک جمہور اہل علم اور محدثین وفقہاء کا ہے۔"}],[5578,"عبداللہ بن عمر رضی اللہ عنہ کہتے ہیں کہ میں نے عمر رضی اللہ عنہ کو مدینے کے منبر پر خطبہ دیتے ہوئے سنا، انہوں نے کہا: لوگو! دیکھو، جس وقت شراب کی حرمت نازل ہوئی، اس وقت وہ پانچ چیزوں سے بنتی تھی: انگور، کھجور، شہد، گیہوں اور جو سے، اور خمر (شراب) وہ ہے جو عقل کو ڈھانپ لے ۱؎۔\n§وضاحت\n۱؎: یعنی اسے خراب کر دے ہوش و حواس جاتے رہیں، اب یہ بات خواہ کسی بھی چیز سے بنے مشروب سے حاصل ہو۔","الألباني: صحيح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے کہ میں نے سیدنا عمر رضی اللہ عنہ ‎ رضی اللہ عنہ کو مدینہ منورہ کے منبر پر فرماتے سنا: اے لوگو! آگا ہ رہو! جس دن شراب کی حرمت کا حکم نازل ہوا، ان دنوں شراب پانچ چیزون سے تیار کی جاتی تھی: انگور سے، کھجور سے،شہد سے،گندم سے اور جو سے اور (یاد رکھو) ہر وہ چیزشراب ہے جو عقل کے ڈھانپے۔","f2":"(1) ’’عقل کو ڈھانپنے،، یعنی پینے والے کی عقل کام نہ کرے۔اسے اپنا اور اپنے قول وفعل کا شعور نہ رہے۔بکواس بکے، الٹے سیدھے کام کرے۔ در حقیقت عقل ہی انسان کا امتیاز ہے،عقل کو ختم کرنے والی چیز کیسے جائز ہو سکتی ہے؟\n(2)سیدنا عمر رضی اللہ عنہ کا تمام صحابہ کرام رضی اللہ عنہم کے سامنے یہ علانیہ فتوی اہل رائے کی آنکھیں کھولنے کے لیے کافی ہے کہ شراب انگور کےعلاوہ اور چیزون سے بھی تیار ہو سکتی ہےاور ان سب کو شراب(خمر)کا حکم حاصل ہو گا،یعنی ایک گھونٹ بھی حرام ہے۔ سیدنا عمر رضی اللہ عنہ سے بڑ افقیہ اور مجتہد صحابی کو ن ہو سکتاہے؟ اور اہل الرائے تو فقیہ صحابی کے قول کے سامنے حدیث بھی تر ک کردیتے ہیں۔کیا اپنی رائے کو ترک نہیں کریں گے؟ بلکہ یہ مسئلہ تو اجماعی بن جاتاہے کیونکہ کسی صحابی نے سیدنا عمر رضی اللہ عنہ کی بات کی تر دید نہیں کی اور کیا چائیے؟"}],[5579,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ میں نے عمر بن خطاب رضی اللہ عنہ کو رسول اللہ صلی اللہ علیہ وسلم کے منبر پر کہتے سنا: امابعد! جب شراب کی حرمت نازل ہوئی تو یہ اس وقت پانچ چیزوں سے بنتی تھی: انگور، گی ہوں، جو، کھجور اور شہد سے۔","الألباني: صحيح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے کہ میں نےسیدنا عمر بن خطاب رضی اللہ عنہ کو رسول اللہ صلی اللہ علیہ وسلم کے منبر مبار ک پرفاتے سنا: حمد وصلاۃ کے بعد (یاد رکھوکہ) شراب کی حرمت نازل ہوئی تو وہ پانچ چیزوں سے تیار کی جاتی تھی:انگور سے،گندم سے،جو سے، کھجور سے اور شہدسے۔","f2":"ان پانچ چیزوں کے ذکر سے مقصود باقی چیزوں کی نفی نہیں بلکہ اپنا رواج بتانا ہے ورنہ شراب جس چیز سے بھی تیار کی جائے،حرام ہے۔ایک قطرہ بھی حرام ہے۔"}],[5580,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ شراب پانچ چیزوں سے بنتی ہے: کھجور، گیہوں، جو، شہد، اور انگور سے ۱؎۔\n§وضاحت\n۱؎: اس کا یہ مطلب نہیں کہ شراب صرف نہیں پانچ چیزوں سے بنے مشروب کا نام ہے بلکہ اس کا اطلاق ہر اس چیز پر ہے جو عقل پر پردہ ڈال دے۔","الألباني: صحيح الإسناد",{"u2":"سیدنا ابن عمر رضی اللہ عنہ نے فرمایا کہ شراب پانچ چیزوں سے تیار ہوتی ہے: کھجور سے گندم سے،جو سے،شہد سےاور انگور سے۔"}],[5581,"عبداللہ بن سیرین کہتے ہیں کہ ایک شخص نے ابن عمر رضی اللہ عنہما کے پاس آ کر کہا: ہمارے گھر والے ہمارے لیے شام کو شراب بناتے ہیں، جب صبح ہوتی ہے تو ہم پیتے ہیں، وہ بولے: میں تمہیں ہر نشہ لانے والی چیز سے روکتا ہوں، کم ہو یا زیادہ، اور میں تم پر اللہ کو گواہ بناتا ہوں کہ میں تمہیں کم ہو یا زیادہ ہر نشہ لانے والی چیز سے روکتا ہوں، اور میں تم پر اللہ کو گواہ بناتا ہوں کہ خیبر والے فلاں فلاں چیز سے شراب بناتے ہیں اور اسے فلاں فلاں نام دیتے ہیں حالانکہ وہ خمر (شراب) ہے، اور اہل فدک فلاں فلاں چیز سے شر اب بناتے ہیں اور اسے فلاں فلاں نام دیتے ہیں، حالانکہ وہ خمر (شراب) ہے، یہاں تک کہ انہوں نے چار طرح کی شرابیں گنائیں ان میں سے ایک شہد تھا ۱؎۔\n§وضاحت\n۱؎: یعنی نشہ لانے والی چیزوں کے نام کی تبدیلی سے اس کی حرمت پر کچھ بھی اثر نہیں پڑتا، اسی طرح اس کی حرمت پر قلت و کثرت کا کوئی بھی اثر نہیں۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابن سیرین سے روایت ہے، انھوں نے کہا کہ ایک آدمی نے سیدنا ابن عمر رضی اللہ عنہ کے پاس آکر کہا: ہمارے گھر والے شام کے وقت نبیذ بناتے ہیں۔ہم صبح کے وقت وہ پی لیتے ہیں۔(کیا یہ جائز ہے؟) آپ نے فرمایا: میں تجھے نشہ آور سے روکتا ہوں۔ تھوڑا ہو یا زیادہ۔ اور میں اللہ تعالی کو تجھ پر گواہ بنا کر تجھے نشہ آور چیز سے روکتا ہوں قلیل ہو یا کثیر۔اور میں اللہ تعالی کو گواہ بنا کر تجھے بتاتا ہوں کہ خیبر والے فلاں فلاں چیز سے مشروب تیار کرتے ہیں اور اس کا نام یہ رکھتے ہیں مگر وہ در حقیقت شراب (خمر) ہے۔ اور فدک والے بھی فلاں فلاں چیز سے مشروب تیار کرتے ہیں اور اس کانام یہ اور یہ رکھتے ہیں،حالنکہ وہ بھی شراب ہی ہے حتی کہ انھوں نے چار (قسم کے) مشروب شمار کیے۔ان میں سے ایک شہد (سے تیار ہوتاہے)تھا۔","f2":"یہ وہی بات ہے جو احناف کے علاوہ جمیع اہل علم کا مسلک ہے کہ نشہ آور چیز کسی بھی پھل،غلے یا مشروب سے تیار ہو،وہ شراب،یعنی خمر کا حکم رکھتی ہے۔وہ قلیل بھی حرام ہے،خواہ ظاہرا اس کا نام کوئی رکھ لیا جائے۔"}],[5582,"عبداللہ بن عمر رضی اللہ عنہما روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"ہر نشہ لانے والی چیز حرام ہے اور ہر نشہ لانے والی چیز خمر (شراب)ہے\"۔","الألباني: صحيح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا:’’ہر نشہ آور چیز حرام اور ہر نشہ آور چیز خمر ہے۔،،","f2":"دیکھیے! اس صریح فرمان رسول کے سامنے اہل رائے کیا حجت کرتے ہیں؟العیاذ باللہ ."}],[5583,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہر نشہ لانے والی چیز حرام ہے اور ہر نشہ لانے والی چیز خمر (شراب) ہے\"۔ حسین کہتے ہیں: امام احمد نے کہا: یہ صحیح حدیث ہے۔","الألباني: صحيح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ ہر نشہ آور چیز حرام ہے اور ہر نشہ آور چیز خمر ہے۔،، حسین بن منصور نے کہا:امام احمد ن رحمہ اللہ نے فرمایا: یہ حدیث صحیح ہے۔","f2":"امام نسائی رحمہ اللہ نے امام احمد رحمہ اللہ کا قول اس لیے نقل فرمایا ہے کہ احناف کہتے ہیں کہ امام یحیی بن معین نے اس حدیث کو ضعیف کہا ہے، خالانکہ ابن معین سے یہ قول کہیں بھی ثابت نہیں۔بے پرکی اڑانے سے کیا فائدہ؟ پھر کوئی ایک حدیث ہے جسے ضعیف کہنے سے جان چھوٹ جائے گی؟آگے آگے دیکھیے ہوتا ہے کیا؟"}],[5584,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہر نشہ لانے والی چیز خمر (شراب) ہے\"۔","الألباني: صحيح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ہر نشہ آور چیز خمر (شراب) ہے۔،،"}],[5585,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہر نشہ لانے والی چیز خمر (شراب) ہے اور ہر نشہ لانے والی چیز حرام ہے\"۔","الألباني: صحيح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ ہر نشہ آور چیز شراب ہے اور ہر نشہ آور چیز حرام ہے۔،،"}],[5586,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"ہر نشہ لانے والی چیز حرام ہے اور ہر نشہ لانے والی چیز خمر (شراب) ہے\"۔","الألباني: حسن صحيح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ کا فرمان ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا:’’ ہر نشہ آور چیز حرام ہے اور ہر نشہ آور چیز خمر ہے۔،،"}],[5587,"حنظلہ بن قیس کہتے ہیں کہ میں نے رافع بن خدیج رضی اللہ عنہ سے سونے، چاندی کے بدلے صاف زمین کرائے پر اٹھانے کے بارے میں پوچھا تو انہوں نے کہا: حلال ہے، اس میں کوئی حرج نہیں، یہ زمین کا حق ہے۔ یحیی بن سعید نے بھی اسے حنظلہ بن قیس سے روایت کیا ہے اور اسے مرفوع کیا ہے جیسا کہ مالک نے ربیعہ سے اسے مرفوعاً روایت کیا ہے۔\nعبداللہ بن عمرو رضی اللہ عنہما روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی کے نزدیک دنیا کا زوال اور اس کی بربادی کسی مسلمان کو (ناحق)قتل کرنے سے زیادہ حقیر اور آسان ہے\"۔\nانس رضی اللہ عنہ سے روایت ہے کہ قبیلہ عکل کے کچھ لوگ نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے اور اسلام قبول کیا، انہیں مدینے کی آب و ہوا راس نہیں آئی، تو نبی اکرم صلی اللہ علیہ وسلم نے انہیں حکم دیا کہ صدقے و زکاۃ کے اونٹوں میں جا کر ان کا پیشاب اور دودھ پیئیں، انہوں نے ایسا ہی کیا، پھر چرواہے کو قتل کر دیا اونٹوں کو ہانک لے گئے، نبی اکرم صلی اللہ علیہ وسلم نے ان کی تلاش میں چند افراد بھیجے، جب پکڑ کر وہ لائے گئے تو آپ نے ان کے ہاتھ پیر کاٹ دئیے، ان کی آنکھیں گرم سلائی سے پھوڑ دیں، اور ان کے زخموں کو داغا نہیں بلکہ یوں ہی چھوڑ دیا، یہاں تک کہ وہ مر گئے۔ تو اللہ تعالی نے یہ آیت نازل فرمائی «إنما جزاء الذين يحاربون اللہ ورسوله» \"ان لوگوں کا بدلہ جو اللہ اور اس کے رسول سے لڑتے ہیں، الآیۃ\"۔\nعبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"ہر نشہ لانے والی چیز حرام ہے\"۔","الألباني: صحيح الإسناد",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا:’’ ہر نشہ آور چیز حرام ہے۔،،"}],[5588,"رافع بن خدیج رضی اللہ عنہ کہتے ہیں کہ ہمیں رسول اللہ صلی اللہ علیہ وسلم نے اپنی زمین کرائے پر دینے سے منع فرمایا، اس وقت سونا اور چاندی (زیادہ) نہیں تھا۔ تو آدمی اپنی زمین کیاریوں اور نالیوں پر ہونے والی پیداوار اور متعین چیزوں کے بدلے کرایہ پر دیتا تھا۔ اسے سالم بن عبداللہ بن عمر نے رافع بن خدیج رضی اللہ عنہ سے روایت کیا ہے، اور اس میں زہری پر اختلاف ہوا ہے۔\nعبداللہ بن عمرو بن عاص رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"قسم اس ذات کی جس کے ہاتھ میں میری جان ہے! کسی مومن کا(ناحق) قتل اللہ کے نزدیک پوری دنیا تباہ ہونے سے کہیں زیادہ بڑی چیز ہے\"\" ۱؎۔ ابوعبدالرحمٰن نسائی کہتے ہیں: ابراہیم بن مہاجر زیادہ قوی راوی نہیں ہیں۔\n§وضاحت\n۱؎: یعنی ایسا مومن کامل جو اللہ کی ذات اور اس کی صفات کا علم رکھنے کے ساتھ ساتھ اسلامی احکام کا پورے طور پر پابند بھی ہے ایسے مومن کا ناحق قتل ہونا اللہ رب العالمین کی نظر میں ایسے ہی ہے جیسے دنیا والوں کی نگاہ میں دنیا کی عظمت ہے۔\nاسامہ بن شریک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص میری امت میں پھوٹ ڈالنے کو نکلے اس کی گردن اڑا دو\"۔\nانس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس قبیلہ عکل کے آٹھ آدمی آئے، پھر انہوں نے اسی طرح «لم يحسمهم» \"ان کے زخموں کو داغا نہیں\" تک بیان کیا اور «فقتلوا راعيها» کے بجائے «قتلوا الراعي» کہا۔\nابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہر نشہ لانے والی چیز حرام ہے\"۔","الألباني: صحيح الإسناد",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسو ل اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ہر نشہ آور چیز حرام ہے -،،"}],[5589,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کدو کی تو نبی، روغنی برتن، لکڑی کے برتن اور ہرے رنگ کے برتن میں نبیذ بنانے سے منع فرمایا، اور فرمایا: \"ہر نشہ لانے والی چیز حرام ہے\"۔","الألباني: حسن صحيح الإسناد",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کدو کے برتن،تارکول لگے ہوئے برتن،کھجور کی جڑ سے بنائے ہو ئے برتن اور مٹکے میں نبیذ بنانے سے منع فرمایا ہے۔اور ہر نشہر آور چیز حرام ہے۔","f2":"دیکھیے حدیث:5550۔"}],[5590,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"کدو کی تو نبی، روغنی برتن اور لکڑی کے برتن میں نبیذ نہ بناؤ، اور (فرمایا:) \"ہر نشہ لانے والی شے حرام ہے\"۔","الألباني: صحيح",{"u2":"سیدنا عا ئشہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا:’’کدو کے برتن، تارکول لگے ہوئے برتن اور کھجور کی جڑ سےبنائے گئے برتن میں نبیذ نہ بناؤ۔اور ہر نشہ آور چیز حرام ہے۔،،"}],[5591,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہر مشروب جو نشہ لائے، حرام ہے\"۔","الألباني: صحيح",{"u2":"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ہر نشہ آور مشروب حرام ہے۔،، قتیبہ نے کہا: عن النبی صلی اللہ علیہ وسلم.","f2":"امام نسائی رحمہ اللہ نے یہ حدیث دو استادوں: اسحاق بن ابراہیم اور قتیبہ سے بیان کی ہے۔ استاد اسحاق بن ابراہیم نے حدیث بیان کرتے ہوئے کہا عن عائشۃ، قالت: قال رسول اللہ صلی اللہ علیہ وسلم جبکہ استاد قتبیہ کے الفاظ ہیں: عن عائشۃ صلی اللہ علیہ وسلم سبحان اللہ! محدثین کرام رحمہ اللہ نقل روایت میں کس درجہ محتاط تھے"}],[5592,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم سے شہد کی شراب کے بارے میں سوال کیا گیا، تو آپ نے فرمایا: \"ہر شراب جو نشہ لائے حرام ہے\"۔","الألباني: صحيح",{"u2":"سیدہ عائشہ رضی اللہ عنہا سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم سے شہد کی نبیذ کے بارے میں پوچھا گیا تو آپ نے فرمایا:’’ جس مشروب میں نشہ پیدا ہوجائے وہ حرام ہے۔،، یہ الفاظ سوید کے ہیں۔"}],[5593,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم سے «بتع» یعنی شہد کی شراب کے متعلق سوال کیا گیا تو آپ نے فرمایا: \"ہر شراب جو نشہ لائے وہ حرام ہے، اور «بتع» شہد سے ہے\"۔","الألباني: صحيح الإسناد لكن قوله والبتع من الغسل مدرج",{"u2":"سیدہ عائشہ رضی اللہ عنہا سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم سے بتع (شہد کی شراب)کے بارے میں پوچھا گیا تو آپ نے فرمایا:’’ جس مشروب میں بھی نشہ پیدا ہو جائے وہ حرام ہوجاتا ہے۔،، بتع (نبیذ ہے جو)شہد سے تیار کی جاتی تھی۔"}],[5594,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم سے «بتع» (یعنی شہد کی شراب) کے بارے میں پوچھا گیا، تو آپ نے فرمایا: \"ہر وہ شراب جو نشہ لائے حرام ہے، اور «بتع» شہد کی نبیذ ہوتا ہے\"۔","الألباني: صحيح الإسناد",{"u2":"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم سے بتع کے بارے میں پوچھا گیا تو آپ نے فرمایا: ’’ہرنشہ آور مشروب حرام ہے۔،، بتع شہد کی نبیذ کو کہتے ہیں۔","f2":"آپ کے جواب کا مقصود یہ ہے کہ اگر بتع نشہ آور ہے تو حرام ہے ورنہ نہیں۔"}],[5595,"ابوموسی اشعری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہر نشہ لانے والی چیز حرام ہے\"۔","الألباني: صحيح",{"u2":"سیدنا ابو موسی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ہر نشہ آور چیز حرام ہے۔،،"}],[5596,"ابوموسی اشعری رضی اللہ عنہ کہتے ہیں کہ مجھے اور معاذ رضی اللہ عنہ کو رسول اللہ صلی اللہ علیہ وسلم نے یمن بھیجا تو معاذ رضی اللہ عنہ نے کہا: آپ ہمیں ایسی سر زمین میں بھیج رہے رہیں جہاں کے لوگ کثرت سے مشروبات پیتے ہیں، تو میں کیا پیوں؟ آپ نے فرمایا: \"(جو چاہو) پیو لیکن کوئی نشہ لانے والی چیز مت پینا\"۔","الألباني: صحيح لغيره",{"u2":"حضرت ابو بردہ کے والد محترم (سیدنا ابو موسی اشعری رضی اللہ عنہ)نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے اور سیدنا معاذ رضی اللہ عنہ کو یمن کی طرف (مبلغ اور امیر بنا کر) بھیجا۔ حضرت معاذ نے کہا:آپ ہمیں ایسے علاقے کی طرف بھیج رہے ہیں جہاں کے لوگ بہت قسم کے مشروب پیتے ہیں۔ میں کو ن سا مشروب پیوں؟ آپ نے فرمایا:’’جو چاہے پی لو مگر نشہ آور مشروب نہ پینا۔،،"}],[5597,"ابوموسی اشعری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہر نشہ لانے والی چیز حرام ہے\"۔","الألباني: صحيح",{"u2":"سیدنا ابو موسی رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ہر نشے والی چیز حرام ہے۔،،"}],[5598,"اسود بن شیبان سدوسی بیان کرتے ہیں کہ میں نے عطا سے سنا ایک شخص نے ان سے پوچھا: ہم لوگ سفر پر نکلتے ہیں تو ہمیں بازاروں میں مشروب نظر آتے ہیں، ہمیں یہ نہیں معلوم ہوتا کہ وہ کن برتنوں میں تیار ہوئے ہیں؟ انہوں نے کہا: ہر نشہ لانے والی چیز حرام ہے، انہوں نے (اپنا سوال) دہرایا تو انہوں نے کہا: جو چیزیں نشہ لانے والی ہوں وہ سب حرام ہیں، انہوں نے پھر دہرایا تو انہوں نے کہا: جو میں تم سے کہہ رہا ہوں اصل وہی ہے۔","الألباني: صحيح الإسناد مقطوع",{"u2":"حضرت اسود بن شیبان سدوسی نے کہا کہ حضرت عطا سے ایک آدمی نے پوچھا: ہم لمبے لمبے سفر کرتے ہیں تو بازاروں میں ہمارے سامنے بہت سے مشروب آتے ہیں۔ ہمیں علم نہیں ہوتا کہ وہ کس برتن میں بنایا گیا؟ حضرت عطا نے فرمایا: ہر نشہ آور مشروب حرام ہے۔وہ دوبارہ وہی سوال کرنے لگا تو انھوں نے پھر فرمایا: ہر نشہ آور مشروب حرام ہے۔وہ پھر سوال دہرانے لگا تو انھوں نے کہا: جواب وہی ہے جو میں تجھے دےچکا۔","f2":"حضرت عطا کا مقصود یہ تھا کہ برتن کسی چیز کو حرام یا حلال نہیں کرتا۔ اگر مشروب نشہ آور ہو تو وہ جس برتن میں بھی بنایا گیا ہو،حرام ہے اور اگر اس میں نشہ نہیں تو حلال ہے،خواہ کسی برتن میں تیار کیا گیا ہو۔"}],[5599,"ابن سیرین کہتے ہیں کہ ہر نشہ لانے والی چیز حرام ہے۔","الألباني: سكت عنه الشيخ",{"u2":"حضرت ابن سرین نے فرمایا:ہر نشہ آور چیز حرام ہے (مشروب ہو یا مطعوم)۔"}],[5600,"عبدالملک بن طفیل جزری کہتے ہیں کہ عمر بن عبدالعزیز نے ہمیں لکھا: طلاء مت پیو، جب تک کہ اس کے دو حصے (جل کر) ختم نہ ہو جائیں اور ایک حصہ باقی رہ جائے اور ہر نشہ لانے والی چیز حرام ہے۔\n§وضاحت\n۱؎: طلاء: وہ شراب ہے، جسے آگ پر رکھ کر جوش دیا جائے یہاں تک کہ وہ گاڑھی ہو جائے۔","الألباني: ضعيف الإسناد مقطوع",{"u2":"حضرت عبد الملک بن طفیل جزری سے منقول ہے کہ حضرت عمر بن عبدا لعزیر رحمہ اللہ (خلیفہ راشد نے ہمیں لکھا کہ طلا ء نہ پیو حتی کہ دو تہائی خشک ہو کر ایک تہائی رہ جائے اور ہر نشہ آور چیز حرام ہے۔"}],[5601,"عمر بن عبدالعزیز نے عدی بن ارطاۃ کو لکھا: ہر نشہ لانے والی چیز حرام ہے۔","الألباني: حسن الإسناد مقطوع",{"u2":"حضرت صعق بن حزن سے منقول ہے کہ حضرت عمر بن عبد العزیز نے عدی بن ارطاۃ کو لکھا کہ ہر نشہ آور چیز حرام ہے۔"}],[5602,"ابوموسی اشعری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہر نشہ لانے والی چیز حرام ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابو موسی اشعری سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ ہرنشے والی چیز حرام ہے۔،،"}],[5603,"ابوموسی اشعری رضی اللہ عنہ کہتے ہیں کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے یمن بھیجا تو میں نے عرض کیا: اللہ کے رسول! وہاں مشروب بہت ہوتے ہیں، تو میں کیا پیوں اور کیا نہ پیوں؟ آپ نے فرمایا: \"وہ کیا کیا ہیں؟\" میں نے عرض کیا: «بتع» اور «مزر»، آپ نے فرمایا: «بتع» اور «مزر» کیا ہوتا ہے؟ میں نے عرض کیا: «بتع» تو شہد کا نبیذ ہے اور «مزر» مکئی کا نبیذ ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کوئی نشہ لانے والی چیز مت پیو، اس لیے کہ میں نے ہر نشہ لانے والی چیز حرام کر دی ہے\"۔","الألباني: حسن الإسناد",{"u2":"سیدنا ابو موسی رضی اللہ عنہ نےفرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے یمن کی طرف (مبلغ اور امیر بنا کر)بھیجا۔ میں نے کہا:اے اللہ کے رسول! وہاں کئی قسم کے مشروب استعمال ہوتے ہیں۔ میں ان میں سے کون سا پیون، کو ن سا تر ک کروں؟ آپ نے فرمایا: مثلا:’’وہ کو ن کون سے ہیں؟،، میں نےکہا: بتع اور مزر۔آپ نے فرمایا:’’ یہ کیا ہوتے ہیں؟ میں ن ےکہا:بتع تو شہد کی نبیذ ہوتی ہے اورمزر مکئی کی نبیذ ہوتی ہے۔رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کو ئی نشہ آورمشروب نہ پنیا کیونکہ میں ہر نشہ آور مشروب ک حرام قرار دے چکا ہوں -،،","f2":"(1) سیدنا ابوموسی اشعری رضی اللہ عنہ خود یمنی تھے، لہذا اس علاقے کے مشروب کو خوب جانتےتھے۔\n(2) ہر علاقے کے کھانے اور مشروب الگ الگ ہوت ہیں۔دوسرے علاقے کے لوگ ان سے واقف نہیں ہوتے،اس لیے رسول اللہ صلی اللہ علیہ وسلم کو ان سے بتع اور مزر کے بارے میں پوچھنا پڑا کیو نکہ ہر علاقے کی اصطاحات اپنی ہوتی ہیں۔ یہ کوئی قابل اعتراض بات نہیں۔\n(3) ’’ مزر،، کے معنی مکئی اور جو کی شراب کے کیے گئے ہیں۔شرح مسلم میں امام نوری رحمہ اللہ فرماتے ہیں کہ گندم سے بھی یہ شراب بنائی جاتی ہے۔\n(4) ’’حرام قرار دے چکا ہوں،، یعنی اللہ تعالی کے حکم سے کیو نکہ حلت وحرمت کا اختیار اللہ تعالی کوہے۔وحی کے ذریعے سے بتائے یا وحی خفی کے ذریعے سے۔"}],[5604,"ابوموسی اشعری رضی اللہ عنہ کہتے ہیں کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے یمن روانہ کیا تو میں نے عرض کیا: اللہ کے رسول! وہاں مشروبات بہت ہوتے ہیں جنہیں «بتع» اور «مزر» کہا جاتا ہے، آپ نے فرمایا: «بتع» کیا ہے؟ میں نے عرض کیا: وہ شہد کا مشروب ہوتا ہے اور «مزر» جَو کا مشروب ہوتا ہے، آپ نے فرمایا: \"ہر نشہ لانے والی چیز حرام ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابو بردہ کے والد محتر م (سیدنا ابو موسی اشعر ی رضی اللہ عنہ نےفرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نےمجھے یمن کی طرف بھیجا تو میں نےکہا: اے اللہ کے رسول!یمن میں کئی قسم کے مشروب ہیں جنھیں بتع اور مزر کہا جاتا ہے۔ آپ نے فرمایا: ’’بتع اور مزر کیاہیں؟،، میں نےعر ض کیا: بتع تو ایسا مشروب ہے جو شہد سے تیار کیا جاتاہے اور مزر جوسے۔آپ نے فرمایا:’’ ہر نشہ آور چیز حرام ہے۔","f2":"’’مزر،، جوار کے علاوہ جو حتی کہ گندم سے بھی تیار کیا جاتاتھا، لہذا یہ تناقص نہیں۔یہ ایک قسم کی نبیذ ہوتی تھی۔"}],[5605,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے خطبہ دیا تو خمر (شراب) والی آیت کا ذکر کیا، ایک شخص نے عرض کیا: اللہ کے رسول!«مزر» نامی مشروب کے بارے میں آپ کا کیا خیال ہے؟ آپ نے فرمایا: \" «مزر» کیا ہوتا ہے؟\" وہ بولا: جَو کی شراب جو یمن میں بنائی جاتی ہے\"، آپ نے فرمایا: \"کیا اس سے نشہ ہوتا ہے؟\" جی ہاں، آپ نے فرمایا: \"ہر نشہ لانے والی چیز حرام ہے\"۔","الألباني: صحيح الإسناد",{"u2":"سیدنا ابن عمر رضی اللہ عنہ نےکہا کہ رسول اللہ صلی اللہ علیہ وسلم نے خطبہ ارشاد فرمایا تو شراب (کی حرمت) والی آیت پڑھی۔ایک آدمی نے کہا: اے اللہ کے رسول! مزر کے بارے میں کیا خیال ہے؟ آپ نےفرمایا:’’مزر کیا ہوتاہے؟،، اس نے کہا یمن میں غلے کی کسی قسم سےتیار کیا جاتاہے۔ آپ نے فرمایا:’’ اس میں نشہ ہوتا ہے؟،، اسنے کہا: ہاں - آپ نے فرمایا:’’ ہر نشہ آور چیز حرام ہے۔،،"}],[5606,"ابوجویریہ کہتے ہیں کہ میں نے ابن عباس رضی اللہ عنہما کو سنا ان سے مسئلہ پوچھا گیا اور کہا گیا: ہمیں بادہ ۱؎ کے بارے میں فتوی دیجئیے۔ تو انہوں نے کہا: محمد (صلی اللہ علیہ وسلم) کے زمانے میں بادہ نہیں تھا، (یا آپ نے اس کا حکم پہلے ہی فرما دیا ہے کہ) جو بھی چیز نشہ لانے والی ہو وہ حرام ہے۔\n§وضاحت\n۱؎: «باذق» فارسی کے لفظ «بادہ» کی تعریب ہے۔ اس کے معنی خمر اور شراب کے ہیں، شاعر کہتا ہے: ہیں رنگ جدا، دور نئے، کیف نرالے شیشہ وہی، بادہ وہی، پیمانہ وہی ہے۔","الألباني: صحيح",{"u2":"حضرت ابو الجویریہ نے کہا: میں نےسنا کہ سیدنا ابن عباس رضی اللہ عنہ سے پوچھا گیا: باذق کے بارے میں فتوی دیجیے۔انھوں نےفرمایا:حضرت محمد باذق سے پہلے تشریف لےگئے اور (یادرکھو) جو چیز نشہ آور ہے، حرام ہے۔","f2":"(1) یہ حدیث صریح دلیل ہے کہ وہ شراب جسے باذق کا نام دیا جاتاہےاس کا پینا حرام ہے۔ باذق کہتے ہیں انگوروں کا نچوڑا اور شیرہ جسے معمولی سا جو ش دے کر ہلکا سا پکا لیا جائے۔اس طرح اس کا نشہ شدید ہو جاتا ہے۔\n(2) یہ حدیث مبارکہ سیدنا عبد اللہ بن عباس رضی اللہ عنہ کی عظیم فقاہت کی دلی ہے کہ انھوں نے مسائل کو انتہائی مختصر مگر نہایت بلیغ وجامع جوا ب دیا۔ بعد ازاں انھوں نے اس کے سامنے یہ اصول بیان فرمادیا کہ مااسکر فھو حرام یعنی جو چیز نشہ آور ہو وہ حرام ہے۔ یہ بعینہ اسی طرح کی بات ہے جیسی مختصر بات رسول اللہ صلی اللہ علیہ وسلم نے بیان فرمائی تھی۔\n(3) ’’تشریف لےگئے نبی اکر م صلی اللہ علیہ وسلم کے دور میں تو نہیں تھی،نہ آپ اسے جانتے تھے مگر آپ نے ضابطہ بیان فرمادیا ہے کہ ہر نشہ آور چیزرحرام ہے۔\n(4) یہ تقریبا پینتیس روایات ہیں جن سے یہ بات معلوم ہوتی ہے اور مصنف کا مقصود بھی یہی ہے کہ شراب کی حرمت کی وجہ نشہ ہے،لہذا جس چیز میں نشہ پایا جائے گا وہ شراب کیطرح قطعا حرام ہے۔قلیل بھی اور کثیر بھی۔اور یہ بات عرفا،عقلا اور شرعا بابکل واضح ہے۔اور یہی مسلک ہے جمہور اہل علم اور صحابہ وتابعین کا۔مگر احناف کو یہ سیدھی سادی بات سمجھ میں نہیں آتی اور وہ بھول بھلیوں میں پڑگئے،حالانکہ احناف قیاس کے سب سے بڑے داعی ہیں اور وہ یہ بھی مانتے ہیں کہ شراب کر حرمت کی قطعی وجہ نشہ ہے۔ تو پھر کیا وجہ ہے کہ کسی اور چیز میں نشہ پایا جائے تو وہ شراب کیطرح حرام نہ ہو؟ شراب تو قلیل بھی حرام اور کثیر بھی لیکن دوسری نشہ آور اشیاء نشے سے کم کم حلال؟ کیا اس کی کو ئی علی یا شرعی تو جیہ کی جاسکتی ہے؟ ہر گز نہیں، خصوصا قیاس کے داعی تو ایسا نہیں کر سکتے جب کہ بے شمار احادیث بھی صراحتا اس تفریق کے خلاف ہیں۔ یہی بات سمجھا نے کے لیے مصنف رحمہ اللہ نے آئندہ باب بھی قائم فرمایا جس میں یہ مسئلہ صراحتا ذکر فرمایا۔اللہ تعالی ہدایت دے۔ آمین."}],[5607,"عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس چیز کے زیادہ پینے سے نشہ آ جائے تو اسے تھوڑا سا پینا بھی حرام ہے\"۔","الألباني: حسن صحيح",{"u2":"حضرت عمر و بن شعیب کے پر دادا محترم (سیدنا عبد اللہ بن عمر و رضی اللہ عنہ) سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’جس مشروب کا زیادہ پینا نشہ آور ہو، اس کو تھوڑا پینا بھی حرام ہے۔،،","f2":"حناف کا خیالہ کہ خمر تو قلیل بھی حرام ہے اور کثیر بھی، مگر دوسرے نشہ آور مشروب نشے کی حدسے کم کم پیے جا سکتے ہیں۔ یہ حدیث ان کی تردید کرتی ہے۔احناف کے نزدیک خمر کسے کہتے ہیں؟ یہ بحث پیچھے گزر چکی ہے۔"}],[5608,"سعد بن ابی وقاص رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"میں تم لوگوں کو اس چیز کو تھوڑا سا پینے سے روکتا ہوں، جس کے زیادہ پی لینے سے نشہ آ جائے\"۔","الألباني: صحيح",{"u2":"سیدنا سعد رضی اللہ عنہ سے مروی ہےکہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’ من تمھیں وہ چیز معمولی سی پینے سے بھی روکتاہوں جسے زیادہ پینےسے نشہ آتا ہے (اور کم پینے سے نشہ نہیں ہوتا)۔،،"}],[5609,"سعد بن ابی وقاص رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے اس چیز کو تھوڑا سا پینے سے روکا جسے زیادہ پینے سے نشہ آ جائے۔","الألباني: صحيح",{"u2":"سیدنا سعد رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے اس چیز کو تھوڑا پینے سے منع کیاہے جسے زیادہ پینا نشہ آور ہو۔"}],[5610,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ مجھے معلوم تھا کہ رسول اللہ صلی اللہ علیہ وسلم روزہ رکھ رہے ہیں، تو ایک دن میں نے نبیذ لے کر آپ کے افطار کرنے کے وقت کا انتظار کیا جسے میں نے آپ کے لیے کدو کی تو نبی میں تیار کی تھی، میں اسے لے کر آپ کے پاس آیا تو آپ نے فرمایا: \"میرے پاس لاؤ\"، میں نے اسے آپ کے پاس بڑھا دی، وہ جوش مار رہی تھی، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اسے اس دیوار سے مار دو، اس لیے کہ یہ ان لوگوں کا مشروب ہے جو اللہ اور آخرت کے دن پر ایمان نہیں رکھتے\"۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: اس میں دلیل ہے کہ نشہ لانے والی چیز حرام ہے، خواہ وہ زیادہ ہو یا کم، اور معاملہ ایسا نہیں ہے جیسا کہ حیلہ کرنے والے اپنے لیے کہتے ہیں کہ ایسے مشروب کا آخری گھونٹ حرام ہوتا ہے اور وہ گھونٹ حلال ہوتے ہیں جو پہلے پیے جا چکے ہیں اور اس سے پہلے رگوں میں سرایت کر چکے ہیں، اس بات میں علماء کے درمیان اختلاف نہیں پایا جاتا کہ پورا نشہ ابتدائی گھونٹوں کے علاوہ صرف آخری گھونٹ سے پیدا نہیں ہوتا ۱؎۔\n§وضاحت\n۱؎: یعنی یہ کہنا کہ نشہ کا اثر صرف اخیر گھونٹ سے ہوتا ہے یہ صحیح نہیں ہے، کیونکہ اس اثر میں تو اس سے پہلے کے گھونٹ کا بھی دخل ہے۔","الألباني: صحيح",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ نے فرمایا:مجھے علم تھا کہ رسول اللہ صلی اللہ علیہ وسلم نے روزہ رکھا ہوا ہے تو میں نے آپ کی افطار ی کے لیے کدو کے برتن میں نبیذ تیار کر کے ایک طرف رکھ چھوڑی۔پھر افطاری کے وقت میں وہ نبیذ لے کر آپ کے پاس حاضر ہوا تو آپ نےفرمایا: ’’(میرے)قریب کرو۔،، میں نے وہ آپ کے قریب کی تو وہ جو ش مارہی تھی۔آپ نے فرمایا: ’’اسے اس دیوار پر دے مارو۔اس قسم کی نبیذ تو وہ لوگ پیتے ہیں جو اللہ تعالی اور آخرت کو نہیں مانتے۔،،\nابو عبد الرحمان (امام نسائی) رحمہ اللہ نے فرمایا: اس حدیث میں دلیل ہے کہ نشہ آور چیز قلیل بھی حرام ہے کثیر بھی، نہ کہ جیسے اپنے آپ کو دھوکا دینے والے لوگ کہتے ہیں کہ آخر ی گھونٹ جس سے نشہ آیا،حرام ہے۔پہلے گھونٹ حلال ہیں، خواہ وہ ایک فرق پی لے، حالانکہ اہل علم اس باب پر متفق ہیں کہ نشہ صرف آخری گھونٹ سے ہی پیدا نہیں ہو تا بلکہ پہلے گھونٹ بھی نشے ولے ہی ہیں اللہ تعالی ہی تو فیق دینے والا ہے۔","f2":"(1) اس حدیث سے معلوم ہو ا کہ نشہ آور طعام وشراب کو ضائع کرنا ضروری ہے حتی کہ اگر کوئی شخص کسی مسلمان کی ملکیت نشہ آور چیز کو اس طر خ ضائع کردے تو اس پر کوئی تاوان وغیرہ نہیں۔کسی مسلمان شخص کے ہاں منشیات کی کو ئی وقعت اور ان کو کوئی احترام نہیں ہونا چاہیے۔ ساری کی ساری نشہ آور اشیاء اور ہر قسم کی منشیات حرام ہیں۔\n(2)بعض اعمال ایمان کامل کے منافی ہیں، اس لیے ان سے بچنا چاہئے۔\n(3) امام صاحب رحمہ اللہ کا مقصد یہ ہے کہ اگر نشہ آور نبیذ تھوڑی مقدار میں پینی جائز ہوتی تو آپ ایک گھونٹ سے روزہ افطار کرلیتے اور باقی واپس کردیتے تا کہ کو ئی دوسرا شخص بھی تھوڑی سی پی سکے، جبکہ آپ نے تو ساری ضائع کرنے کا حکم دیا۔ثابت ہو نشہ آور مشروب کا ایک گھونٹ بھی جائز نہیں، خواہ کوئی سا بھی مشروب ہو۔ اوریہ بالکل صحیح استدالال ہے۔\n(4) ’’جوش مار رہی تھی،، یعنی اس میں نشے کی علامات تھیں۔\n(5) ’’نہیں مانتے،،یعنی یہ کافروں کا مشروب ہے مسلمانوں کا نہیں۔ یہ مطلب نہیں کہ جو پیے گا، کافر ہو جائے گا، جیسے ریشم کے بارے میں گزرا۔\n(6) ’’دھوکا دینے والے،، مراد احناف ہیں۔ اور دھوکا یہ ہے ہ شراب کو دوسرے ناموں سے پی لیتے ہیں اور سمجھتے ہیں کہ ہم نے شراب نہیں پی۔\n(7) ’’فرق،، تین صاع کو کہتے ہیں۔ یہ بطور مبالغہ فرمایا ورنہ بیک وقت اتنی پینی ممکن نہیں۔\n(8) ’’آخری گھونٹ سے،،امام صاحب کا مقصود یہ ہے کہ اپنے آپ کو دھوکا دینے والی ایک ہی ہے۔ جب اس کا آخری گھونٹ نشہ آور ہے تو پہلے کیو ں نہیں؟ نیز اگر وہ پہلے گھونٹ نہ پیتا تو کیا صرف اس گھونٹ سے نشہ آتا؟ ظاہر ہے وہ سارا مشروب نشہ آور ہے۔اتنی بات ہے ک نشے کااظہار آخری گھونٹ پر ہو ا، یعنی زیادہ پینے سےہوا اور شراب (جسے حنفی بھی خمر کہتے ہیں) بھی ایسے ہی ہے۔اس کا ایک گھونٹ پینے سے نشہ محسوس نہیں ہو تا۔ نشہ زیادہ پینے سے ہی ہوگا۔ تو آخر کس عقلی وشرعی علت کی بنا پر شراب اور دوسرے نشہ آور مشروب میں فرق کیا گیا ہے؟"}],[5611,"علی کرم اللہ وجہہ کہتے ہیں کہ مجھے نبی اکرم صلی اللہ علیہ وسلم نے سونے کے چھلے، ریشمی کپڑے، لال زین پوش اور جو کے مشروب سے منع فرمایا۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ سے روایت ہے کہ نبی اکر م صلی اللہ علیہ وسلم نے مجھے سونے کی انگوٹھی، قسی (ریشمی)کپڑے، سرخ ریشمی گدیلے اور جو کی نبیذ سے منع فرمایا۔","f2":"’’ منع فرمایا،، قلیل وکثیر کا فرق نہیں فرمایا جبکہ یہ مشروب جو سے تیار ہوتا ہے۔اور احناف کے نزدیک اس مشروب کو نشے سے کم کم پینا جائز ہے۔ کیا یہ صریح حدیث کی صریح مخالفت نہیں؟"}],[5612,"مالک بن عمیر بیان کرتے ہیں کہ صعصعہ نے علی بن ابی طالب کرم اللہ وجہہ سے کہا: امیر المؤمنین! آپ ہمیں ان باتوں سے منع کیجئیے، جن سے آپ کو رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے ہمیں کدو کی تو نبی اور سبز رنگ کے برتن کے استعمال سے روکا۔","الألباني: صحيح",{"u2":"حضرت صعصہ نے سیدنا علی بن ابی طالب رضی اللہ عنہ سے کہا: اے امیر المو منین! ہمیں اس چیز سے منع فرمائیے جس سے رسول اللہ صلی اللہ علیہ وسلم نے آپ کو روکا ہو۔ انھو ں نے کہا:رسو ل اللہ صلی اللہ علیہ وسلم نے مجھے کدو کے برتن اور مٹکے (میں نبیذ وغیرہ بنانے)سے منع فرمایا۔","f2":"یہ نہیں پہلے تھی بعد میں آپ نے اجازت فرمادی کہ برتن کسی چیز کو حلا ل یا حرام نہیں کرتا،البتہ نشے سے بچو۔ اس حدیث کی متعلقہ باب سے کوئی مناسبت نہیں الا یہ کہ سابقہ حدیث کا ٹکڑا ہو۔"}],[5613,"جابر رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم کے لیے پتھر کے کونڈے میں نبیذ تیار کی جاتی تھی۔","الألباني: صحيح"],[5614,"طاؤس کہتے ہیں کہ ایک شخص نے ابن عمر رضی اللہ عنہما سے کہا: کیا رسول اللہ صلی اللہ علیہ وسلم نے مٹی کے برتن کی نبیذ سے منع فرمایا ہے؟ کہا: ہاں، طاؤس کہتے ہیں: اللہ کی قسم! اسے میں نے ان سے (ابن عمر سے) سنا ہے ۱؎۔\n§وضاحت\n۱؎: کیونکہ مٹی کے برتن میں نبیذ بنانے سے خطرہ رہتا ہے کہ فوراً نشہ پیدا ہو جائے اور آدمی کو پتہ نہ چلے اور نشہ لانے والی نبیذ پی بیٹھے۔","الألباني: صحيح",{"u2":"حضرت طاؤس سے روایت ہے کہ ایک آدمی نے سیدنا ابن عمر رضی اللہ عنہ سے پوچھا: کہا رسول اللہ صلی اللہ علیہ وسلم نے مٹکے کی نبیذ سے منع فرمایا ہے؟ انھوں نے فرمایا:ہاں۔ حضرت طاؤس نے کہا: اللہ کی قسم! میں نے یہ (الفاظ)ان (سیدنا عبد اللہ بن عمر رضی اللہ عنہ) سے سنے ہیں۔","f2":"یہاں اگر چہ مطلق مٹکے کا ذکر کیا گیا ہے مگر دیگر روایات میں یہ قید بھی ہے کہ جس مٹکے پر تارکول یا روغن لگا کر اس کے مسام بند کر دیے گئے ہوں۔ تفصیل ملا حظہ فرمائیے (احادیث:5550،5615،5612)"}],[5615,"طاؤس کہتے ہیں کہ ایک شخص نے ابن عمر رضی اللہ عنہما کے پاس آ کر کہا: رسول اللہ صلی اللہ علیہ وسلم نے مٹی کے برتن کی نبیذ سے منع فرمایا؟ انہوں نے کہا: ہاں، ابراہیم بن میسرہ نے اپنی حدیث میں «والدباء» مزید کہا ۱؎۔\n§وضاحت\n۱؎: یعنی کدو کی تو نبی سے بھی منع فرمایا ہے۔","الألباني: صحيح",{"u2":"حضرت طاؤس کہتے ہیں کہ ایک آدمی نے سیدنا ابن عمر رضی اللہ عنہ کے پاس آکر کہا،کیا رسول اللہ صلی اللہ علیہ وسلم نے مٹکے کی نبیذ سے منع فرمایا ہے؟ انھوں نے کہا:ہاں۔(ایک روای) ابراہیم بن میسرہ نے اپنی حدیث میں کدو کے برتن کا بھی ذکر کیا ہے۔"}],[5616,"اوس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مجھے حکم دیا گیا ہے کہ میں لوگوں سے اس وقت تک جنگ کروں جب تک کہ وہ گواہی نہ دیں کہ اللہ کے سوا کوئی معبود برحق نہیں (جب وہ اس کی گواہی دے دیں گے تو) پھر ان کے خون اور ان کے مال حرام ہو جائیں گے مگر اس کے (جان و مال کے) حق کے بدلے\"۔\nبریدہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مومن کا (ناحق) قتل اللہ تعالی کے نزدیک دنیا کے ہلاک ہونے سے کہیں زیادہ بڑی بات ہے\"۔\nعبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مٹی کے برتن کی نبیذ سے منع فرمایا ہے۔","الألباني: صحيح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ نےکہا کہ رسول اللہ صلی اللہ علیہ وسلم نے مٹکے میں بنائی گئی نبیذ کے استعمال سے منع فرمایا ہے۔"}],[5617,"ابوادریس خولانی کہتے ہیں کہ میں نے معاویہ رضی اللہ عنہ کو خطبہ دیتے ہوئے سنا (انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے بہت کم حدیثیں روایت کی ہیں) کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"ممکن ہے کہ اللہ تعالی ہر گناہ معاف کر دے سوائے اس (گناہ) کے کہ آدمی مومن کو جان بوجھ کر قتل کرے، یا وہ شخص جو کافر ہو کر مرے\" ۱؎۔\n§وضاحت\n۱؎: یہ اس صورت میں ہے جب کہ یہ دونوں توبہ کئے بغیر مر جائیں، نیز آیت کریمہ: «ويغفر ما دون ذلك لمن يشاء» یعنی: \" اللہ تعالی شرک کے سوا دوسرے گناہ جس کے لیے چاہے معاف کر سکتا ہے \" :(سورة النساء: 48 ) کی روشنی میں مومن کے قصد و ارادہ سے عمداً قتل کو بھی بغیر توبہ کے معاف کر سکتا ہے :(جس کے لیے چاہے ) محققین سلف کا یہی قول ہے :(تفصیل کے لیے دیکھئیے حدیث رقم ۴۰۰۴ کا حاشیہ )۔\nعبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سب سے پہلی چیز جس کا بندے سے حساب ہو گا نماز ہے، اور سب سے پہلے لوگوں کے درمیان خون کا فیصلہ کیا جائے گا\" ۱؎۔\n§وضاحت\n۱؎: خالق کے حقوق سے متعلق پہلی چیز جس کا بندے سے حساب ہو گا نماز ہے، اور بندوں کے آپسی حقوق میں سے سب سے پہلے خون کی بابت فیصلہ کیا جائے گا۔\nعبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سبز رنگ کے برتن سے منع فرمایا ہے۔ راوی کہتے ہیں: میں نے عرض کیا: «حنتم» کیا ہوتا ہے؟ کہا: مٹی کا برتن۔","الألباني: صحيح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے حنتم (میں نبیذ بنانے) سے منع فرمایا ہے۔ (جبلہ بن سحیم نے کہا:) میں نے پوچھا کہ حنتم کیا ہوتا ہے؟ انھوں نے فرمایا:مٹی کا مٹکا۔","f2":"اس روایت کی سند میں ابن عمر رضی اللہ عنہ سے بیان کرنے والے روای کانام ’’ خالد بن سحیم،،ذکر کیا گیاہے جو کہ غلط ہے۔ صحیح ’’ جبلہ بن سحیم،،ہے۔ (ذخیرۃ العقبی شرح سنن النسائی: 40/207)"}],[5618,"عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سب سے پہلے لوگوں کے درمیان خون کا فیصلہ کیا جائے گا\"۔\nعبدالعزیز بن اسید طاحی بصری کہتے ہیں کہ عبداللہ بن زبیر رضی اللہ عنہما سے مٹی کے برتن کی نبیذ کے بارے میں پوچھا گیا، تو انہوں نے کہا: ہمیں رسول اللہ صلی اللہ علیہ وسلم نے اس سے منع فرمایا ہے۔","الألباني: صحيح",{"u2":"حضرت عبد العزیز بن اسید طاحی بصری نے فرمایا حضرت (عبدا للہ)ابن زبیر رضی اللہ عنہ سے مٹکے کی نبیذ کے بارےمں پوچھا گیا تو انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نےہمیں اس سے روکا تھا۔"}],[5619,"سعید بن جبیر کہتے ہیں کہ ہم نے ابن عمر رضی اللہ عنہما سے مٹی کے برتن کی نبیذ کے بارے میں سوال کیا، تو انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے اسے حرام کیا ہے، میں ابن عباس رضی اللہ عنہما کے پاس گیا۔ میں نے کہا: میں نے آج ایک ایسی بات سنی ہے، جس پر مجھے حیرت ہے۔ وہ بولے: وہ کیا ہے؟ میں نے کہا: میں نے ابن عمر رضی اللہ عنہما سے مٹی کے برتن کی نبیذ کے بارے میں سوال کیا تو انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے اسے حرام کیا ہے۔ ابن عباس رضی اللہ عنہما نے کہا: ابن عمر رضی اللہ عنہما نے سچ کہا، میں نے کہا: «جر» سے کیا مراد ہے؟ انہوں نے کہا ـ: مٹی سے بنی تمام چیزیں۔","الألباني: صحيح",{"u2":"حضرت سعید بن جبیر سے روایت ہے، انھوں نےکہا کہ ہم نے سیدنا ابن عمر رضی اللہ عنہ سے مٹکے کی نبیذ کے بارے میں پوچھا تو انھوں نے فرمایا:رسول اللہ صلی اللہ علیہ وسلم نےاسے حرام قرار دیا ہے۔پھڑ میں سیدنا ابن عباس رضی اللہ عنہ کے پاس حاضر ہوا اور کہا کہ میں نے آج ایک ایسی باب سنی ہے جس پر مجھے بہت تعجب ہو اہے۔ انھوں نے کہا:وہ کیا بات ہے؟ میں نے کہا: میں نے سیدنا ابن عمر رضی اللہ عنہ سے مٹکے کی نبیذ کے بارے میں پوچھا تو انھوں نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے اسے حرام قرار دیا ہے۔ سیدنا ابن عباس رضی اللہ عنہ نے کہا کہ سیدنا ابن عمر رضی اللہ عنہ نے سچ فرمایا۔ میں نے کہا: جی! مٹکے سے کیا مراد ہے؟ انھوں نے فرمایا،مٹی سے بنا ہو ا ہر برتن۔"}],[5620,"سعید بن جبیر کہتے ہیں کہ میں ابن عمر رضی اللہ عنہما کے پاس تھا، ان سے «جر» کی نبیذ کے بابت پوچھا گیا تو بولے: اسے رسول اللہ صلی اللہ علیہ وسلم نے حرام کیا ہے، جو کچھ میں نے سنا وہ مجھ پر گراں گزرا۔ چنانچہ میں ابن عباس رضی اللہ عنہما کے پاس آیا اور کہا کہ ابن عمر رضی اللہ عنہما سے ایک چیز کے بارے میں پوچھا گیا، وہ(ان کا جواب) مجھے بہت برا لگا۔ وہ بولے: وہ کیا ہے؟ میں نے کہا: ان سے «جر» کی نبیذ کے بارے میں پوچھا گیا تھا، تو ابن عباس نے کہا: انہوں نے سچ کہا، اسے رسول اللہ صلی اللہ علیہ وسلم نے حرام کیا، میں نے کہا: «جر» کیا ہوتا ہے؟ وہ بولے: ہر وہ چیز جو مٹی سے بنائی جائے۔","الألباني: صحيح لغيره",{"u2":"حضرت سعید جبیر نے کہا کہ میں سیدنا ابن عمر رضی اللہ عنہ کے پاس بیٹھا تھا کہ ان سے مٹکے کی نبیذ کے بارےمیں پوچھا گیا۔ انھو ں نے فرمایا:رسول اللہ صلی اللہ علیہ وسلم نے اسے حرام قرار دیا ہے۔ میں نے یہ بات سنی تو یہ مجھے بہت شاق گزری۔ میں سیدنا ابن عباس رضی اللہ عنہ کی خدمت میں حاضر ہوا اور کہا کہ سیدنا ابن عمر رضی اللہ عنہ سے ایک مسئلہ پوچھا گیا تو میں ان کے جو اب پر بہت حیران ہوا ہوں۔ فرمانے لگے: وہ کیا مسئلہ تھا؟ میں نے کہا:ان سے مٹکے کی نبیذ کے بارے میں پوچھا گیا تھا۔سیدنا ابن عباس رضی اللہ عنہ نے فرمایا:انھوں نےسچ فرمایا۔رسول اللہ صلی اللہ علیہ وسلم نے اسے حرام قرار دیا ہے۔میں کہا مٹکے سے کیا مراد ہے؟ انھوں نےفرمایا: مٹی سے بنا ہوا ہر برتن۔"}],[5621,"ابن ابی اوفی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سبز لاکھی برتن کی نبیذ سے منع فرمایا۔ (شیبانی کہتے ہیں) میں نے کہا: اور سفید؟ (برتن سے)انہوں نے کہا: مجھے نہیں معلوم ۱؎۔\n§وضاحت\n۱؎: اس باب اور اگلے ابواب میں مذکور تمام برتنوں میں شروع میں :(جب شراب حرام کی گئی تھی ) حلال نبیذ بنانا بھی ممنوع قرار دیا تھا گیا کیونکہ ان برتنوں میں نشہ لانے والے شراب کے اثرات باقی تھے تو نبیذ بناتے وقت اس میں فوراً نشہ پیدا ہو جانے کا خطرہ تھا، اور جب بہت دن گزر گئے اور وہ سارے برتن خوب خوب سوکھ گئے تب ان میں نبیذ بنانے کی اجازت دے دی گئی، لیکن بعض علما ہمیشہ کے لیے ممانعت کے قائل ہیں، دیکھئیے باب نمبر ۳۶ اور اس کے بعد کے ابواب کی احادیث و آثار۔","الألباني: صحيح خ بلفظ لا لم يذكر أدري وهو شاذ",{"u2":"سیدنا ابن ابی اوفی رضی اللہ عنہ سے روایت ہے کہ رسو ل اللہ صلی اللہ علیہ وسلم نے سبز مٹکے کی نبیذ سے منع فرمایا ہے۔میں نے کہا:سفید مٹکا (جائز ہے؟)انھوں نے فرمایا:میں نہیں جانتا۔","f2":"سبز مٹکے سے مراد وہ مٹکا ہے جسے روغن لگا کر مسام بند کر دیے گئے ہوں۔ایسے مٹکے میں نبیذ بنائی جائے تو جلدی نشہ پیدا ہو نے کا خطرہ ہو تاہے،اس لیے اس سے منع فرمایا گیا۔صحیح بخاری میں (حدیث 5596) میں لفظ ’’لا،، کے ساتھ روایت منقول ہے،یعنی جوابا انھوں نے فرمایا کہ سفید مٹکےے میں بھی جائز نہیں،جبکہ مذکورہ روایت میں ’’لا،، کے ساتھ ’’ادری،، کا بھی اضاف ہے جو شیخ البانی رحمہ اللہ کے نزدیک شاذہے۔"}],[5622,"ابواسحاق شیبانی بیان کرتے ہیں کہ میں نے ابن ابی اوفی رضی اللہ عنہ کو کہتے ہوئے سنا: رسول اللہ صلی اللہ علیہ وسلم نے ہرے اور سفید لاکھی برتن کی نبیذ سے منع فرمایا ہے۔","الألباني: صحيح دون قوله والأبيض فإنه مدرج",{"u2":"سیدنا ابن ابی اوفی رضی اللہ عنہ سے روایت ہے کہ رسو ل اللہ صلی اللہ علیہ وسلم نے سبز اور سفید مٹکے کی نبیذ سے منع فرمایا ہے۔","f2":"’’سفید مٹکے،، کے الفاظ مدرج ہیں۔"}],[5623,"ابورجاء کہتے ہیں کہ میں نے حسن بصری سے لاکھی برتن کی نبیذ کے بارے میں پوچھا: کیا وہ حرام ہے؟ انہوں نے کہا: حرام ہے، ہم سے اس شخص نے بیان کیا جو جھوٹ نہیں بولتا (یعنی بعض صحابہ) کہ رسول اللہ صلی اللہ علیہ وسلم نے سبز روغنی گھڑا، کدو کی تو نبی، روغنی برتن اور لکڑی کے برتن سے منع فرمایا ہے۔","الألباني: صحيح لغيره",{"u2":"حضرت ابو رجاء سے منقول ہے کہ میں نے حضرت حسن بصری سے مٹکے کی نبیذ کےبارےمیں پوچھا:کیا وہ حرام ہے؟ انھوں نے کہا کہ حرام ہے۔ مجھے اس شخص نے بیان کیا جس نے جھوٹ نہیں بو لا کہ رسول اللہ صلی اللہ علیہ وسلم نے (روغنی)مٹکے،کدو کے برتن،تارکول لگے ہوئے مٹکے اور کھجور کی جڑ سے بنائے گئے برتن (میں نبیذ بنانے)سے منع فرمایاہے۔"}],[5624,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کدو کی تو نبی سے منع فرمایا ہے۔","الألباني: صحيح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کدو کے برتن (میں نبیذ بنانے)سےمنع فرمایا ہے۔","f2":"بڑا کدو سوکھ جائے تواس کو اندر سے صاف کر لیا جاتاہے۔اس کاچھلکا بڑ ا سخت ہوجاتا ہے اور وہ برتن جیسا بن جا تا ہے۔اہل جاہلیت اس میں شراب بناتے تھے کیو نکہ مسام نہ ہو نے کی وجہ سے اس میں خوب نشہ پید ہوتا تھا۔شراب حرام ہوئی تو آپ نے شراب کے برتنوں سے بھی منع فر مادیا مگر بعد میں برتنوں کے استعمال کی اجازب دے دی،البتہ نشہ پیدا نہیں ہوا چاہیے۔احتیاط یہی ہے کہ ایسے برتن نبیذ کےلیے استعمال نہ کیے جائیں۔"}],[5625,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کدو کی تو نبی سے منع فرمایا۔","الألباني: صحيح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سےمنقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نےکدو کے برتن سے منع فرمایا ہے۔"}],[5626,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کدو کی تو نبی اور روغنی برتن سے منع فرمایا ہے۔","الألباني: صحيح",{"u2":"سیدنا عا ئشہ رضی اللہ عنہ سے روایت ہے، انھوں نےفرمایا: رسول اللہ صلی اللہ علیہ وسلم نے کدو کے برتن اور تارکول لگے ہوئے برتن (میں نبیذ بنانے) سے منع فرمایا ہے"}],[5627,"علی رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کدو کی تو نبی اور روغنی برتن سے منع فرمایا ہے۔","الألباني: صحيح",{"u2":"سیدنا علی رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے کدو کے برتن اور تارکول لگے ہوئے برتن (کے نبیذ)سےمنع فرمایا ہے۔"}],[5628,"عبدالرحمٰن بن یعمر رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے کدو کی تو نبی اور روغنی برتن سے منع فرمایا ہے۔","الألباني: صحيح الإسناد",{"u2":"سیدنا عبد الرحمان بن یعمر رضی اللہ عنہ سے منقول ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے کدو کے برتن اور تارکو ل ملے ہوئے برتن سےمنع فرمایا ہے۔"}],[5629,"انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کدو کی تو نبی اور روغنی برتن میں نبیذ بنانے سے روکا ہے۔","الألباني: صحيح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ نے بتایا کہ رسول اللہ صلی اللہ علیہ وسلم نے کدو کے برتن اور تارکول لگے ہوئے برتن میں نبیذ بنانےسے منع فرمایا ہے۔"}],[5630,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کدو کی تو نبی اور روغنی برتن میں نبیذ بنانے سے روکا ہے۔","الألباني: صحيح",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کدو کے برتن اور تارکول لگے ہوئے برتن میں نبیذ بنانے سے منع فرمایا ہے۔"}],[5631,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے روغنی برتن اور کدو کی تو نبی سے روکا ہے۔","الألباني: صحيح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سےمروی ہے کہ سول اللہ صلی اللہ علیہ وسلم نے تارکول لگے ہوئے اور برتن اور کدو کے برتن (میں نبیذ بنانے) سے منع فرمایا۔"}],[5632,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کدو کی تو نبی، لاکھ کے برتن اور لکڑی کے برتن سے منع فرمایا ہے۔","الألباني: صحيح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نےکدو کےبرتن،روغنی مٹکے اور کھجور کی جڑ سے بنائے گئے برتن میں نبیذ بنانے سےمنع فرمایا۔","f2":"کھجور کی جڑ کو اندر سے کرید کربرتن کی صورت دی جاتی ہے۔ اسے نقیر کہا جاتا تھا۔ یہ برتن بھی شراب بنانے کے لیے استعمال کیا جاتا تھا۔ اس میں مسام نہیں ہوتے تھے،لہذا نشہ جلدی پیدا ہوتا تھا۔ شراب کی حرمت کے ساتھ ان برتنوں سے بھی روک دیا گیا مگر بعد میں اس برتن کی اجازت دے دی گئی۔(دیکھیے،روایت:5550.)"}],[5633,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے لاکھ کے برتن، کدو کی تو نبی اور لکڑی کے برتن سے منع فرمایا ہے۔","الألباني: صحيح",{"u2":"سیدنا ابو سعید خدری رضی اللہ عنہ سےروایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے روغنی مٹکے،کدو کےبرتن اور کھجور کی جڑ سے بنائے گئے برتن میں بنائی گئی نبیذ پینے سے منع فرمایا۔","f2":"مباد ا اس میں نشہ ہو مگر ہلکا ہونے کی وجہ سے محسوس نہ ہو۔ یہ حکم ابتدا میں تھا جب لوگ شراب کے رسیا تھے اور انھیں شراب سے روک دیا گیا تھا۔ معمولی نشہ ان کو محسوس نہیں ہوتا تھا۔ بعد میں جب نشے والی بات پرانی ہوگئی تو ان برتنوں میں نبیذ میں کی اجازت دے دی گئی، بشرطیکہ اس میں نشہ نہ ہو۔ یہ جمہور اہل علم کا مسلک ہے۔"}],[5634,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے لاکھی برتن اور روغنی برتن سے منع فرمایا ہے۔","الألباني: صحيح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہےکہ رسو ل اللہ صلی اللہ علیہ وسلم نےکدو کے برتن،روغنی مٹکے اور تارکول لگے ہو ئے برتن (میں نبیذ بنانے) سے منع فرمایا۔"}],[5635,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے لاکھی کے برتنوں، کدو کی تو نبی اور روغنی برتنوں سے منع فرمایا ہے۔","الألباني: صحيح",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ نےبیان فرمایا کہ رسو ل اللہ صلی اللہ علیہ وسلم نے مٹکوں، کدو کے برتن اور تارکول ملے ہوئے برتنو ں سے منع فرمایا۔"}],[5636,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو ایسے مشروب سے منع فرماتے ہوئے سنا جو کدو کی تو نبی، یا لاکھی برتن، یا روغنی برتن میں تیار کیا گیا ہو، سوائے زیتون کے تیل اور سر کے کے ۱؎۔\n§وضاحت\n۱؎: کیونکہ یہ نشہ لانے والی چیزیں نہیں ہوتیں۔","الألباني: حسن",{"u2":"سیدہ عائشہ رضی اللہ عنہا نے فرمایا کہ میں نےرسول اللہ صلی اللہ علیہ وسلم کو ایسا مشروب پینےسے منع فرماتے سناجو کدو کے برتن یا روغنی مٹکے یا تارکول لگے ہوئے برتن میں تیار کیا گیا ہے، علاوہ زیتون کے تیل اور سرکے۔","f2":"علاوہ زیتوں کے تیل کے،، یہ بات یادر ہے کہ تیل،خواہ زیتون کا ہو یا کسی اور چیز کا کسی بھی برتن میں ہو استعمال ہو سکتا ہے کیو نکہ تیل میں نشہ پید ا ہونے کا امکان نہیں۔ اسی طرح سرکہ وغیرہ کیونکہ نہی کی وجہ تو نشہ ہے جواس میں پیدا نہیں ہوتا۔"}],[5637,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کدو کی تو نبی، لاکھی برتن، لکڑی کے برتن اور روغنی برتن سے منع فرمایا ہے۔","الألباني: صحيح",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نےکدو کے برتن،روغنی مٹکے،کھجور کی جڑ کےبرتن اور تارکول لگ برتن (میں نبیذ بنانے)سے منع فرمایا۔","f2":"تفصیل د یکھیے، حدیث:5550."}],[5638,"ثمامہ بن حزن قشیری بیان کرتے ہیں کہ میں نے عائشہ رضی اللہ عنہا سے ملاقات کی اور ان سے نبیذ کے بارے میں سوال کیا، تو انہوں نے کہا: عبدالقیس کا وفد رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور آپ صلی اللہ علیہ وسلم سے ان چیزوں کے بارے میں سوال کیا جن میں وہ نبیذ بناتے ہیں تو نبی اکرم صلی اللہ علیہ وسلم نے کدو کی تو نبی، لکڑی کے برتن، روغنی برتن اور لاکھی برتن میں نبیذ بنانے سے منع فرمایا۔","الألباني: صحيح",{"u2":"حضرت ثمامہ بن حزن قشیری سے روایت ہے کہ میں سیدہ عائشہ رضی اللہ عنہا کوملا تو میں نے ان سے نبیذ کےبارے میں پوچھا۔ انھوں نے فرمایا: قلبیلہ عبد القیس کا وفد رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا تو انھوں نےآپ سے پوچھا کہ وہ کس برتن میں نبیذ بنائیں؟ نبی اکرم صلی اللہ علیہ وسلم نے انھیں کدو کے برتن، کھجور کی جڑکے برتن،تارکول لگے ہوئے برتن اورروغنی مٹکے میں نبیذ بنانے سےمنع فرمایا۔","f2":"وفد عبد القیس کی یہ پہلی آمد ہے جو 3ہجری کے آخر یا 4 ہجر ی کے شروع میں ہوئی کیونکہ اس میں قریش کی رکاوٹ کا ذکر ہے۔دوسری آمد تو 9 ہجری میں ہوئی تھی۔ اس وقت تک مکہ فتح ہو چکا تھا اور قریش کی اس رکاوٹ ختم ہو چکی تھی۔ پہلی آمد جنگ احد کے بعد قریبی دور میں ہوئی اور یہ دور شراب کی حرمت کا تازہ دور تھا۔ اس دور میں شراب کے ساتھ ساتھ شراب والے برتن بھی ممنوع فر ما دئے گئے تھے تا کہ شراب کی طر ف ذہن نہ جائے۔بعد میں شراب اسلامی معاشرے میں بھولی بسری ہوگئی توان برتنو ں کے استعمال کی اجازت بھی دے دی گئی البتہ چونکہ یہ برتن مسام بند ہونے کی وجہ سے نشہ پیدا ہونےمیں ممد ہیں،لہذا نبیذ بنانےکے لیے ان سے احتراز بہتر ہے۔ تاہم جب تک نشہ پیدا نہ ہو، ان برتنوں کی نبیذ حرام نہیں ہوگی، کیو نکہ برتن کسی چیز کو حلال یا حرام نہیں کر سکتا۔"}],[5639,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ اصل کدو کی تو نبی سے روکا گیا ہے ۱؎۔\n§وضاحت\n۱؎: خواہ اس میں نشہ ہو یا نہ ہو۔","الألباني: صحيح الإسناد",{"u2":"سیدہ عائشہ رضی اللہ عنہا نے فرمایا: کدو کے برتن میں ذاتی طور پر نبیذ بنانے سے روکا گیا ہے۔","f2":"’’ذاتی طور پر،، یعنی خصوصا اس میں نشے کا امکان زیادہ ہے۔یا معنی یہ بھی ہو سکتا ہے کہ کدو کے برتن میں نبیذ بنانےکی ممانعت نشے کی بناپر نہیں بلکہ کدو کا برتن ہونے کی وجہ سے ہے، یعنی ہر حال میں منع عے -لیکن یہ معنی دیگر احادیث کی بنا پر مرجوح ہیں۔ واللہ اعلم."}],[5640,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے لکڑی کے برتن، روغنی برتن، کدو کی تو نبی اور لاکھی برتن سے منع فرمایا۔ ابراہیم بن علیہ کی روایت میں ہے کہ اسحاق کہتے ہیں: ہنیدہ نے عائشہ رضی اللہ عنہا سے روایت کرتے ہوئے معاذہ کی حدیث کی طرح بیان کیا اور گھڑوں کا ذکر کیا، میں نے ہنیدہ سے کہا: تم نے عائشہ رضی اللہ عنہا کو گھڑوں کا نام لیتے سنا، وہ بولیں: ہاں۔","الألباني: صحيح",{"u2":"حضر ت عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کھجور کی جڑ کے برتن،تارکول لگے برتن،کدوبرتن اورروغنی مٹکے میں نبیذ بنانے سے منع فرمایا۔ یہ ابن علیہ کی روایت میں ہے۔\nاسحاق نے کہا کہ ہنیدہ نےسیدہ عائشہ رضی اللہ عنہا سے معاذہ کی حدیث کے مثل بیان کیا ہے اور (مطلقا) مٹکوں کا ذکرکیا۔میں نے ہنیدہ سے کہا:تونے ان (سیدہ عائشہ رضی اللہ عنہا)سے سنا، انھوں نے مٹکوں (مٹی کے گھڑوں) کا نام لیا تھا؟ اس (ہنیدہ)نے کہا: ہاں۔"}],[5641,"ہنیدہ بنت شریک بن ابان کہتی ہیں کہ میں نے عائشہ رضی اللہ عنہا سے (مقام) خریبہ میں ملاقات کی اور ان سے شراب کی تلچھٹ کے بارے میں سوال کیا۔ تو انہوں نے مجھے اس سے منع فرمایا، یعنی انہوں نے کہا: شام کو بھگو کر صبح پی لو اور برتن کے منہ کو بند کر کے رکھو۔ اور انہوں نے مجھے کدو کی تو نبی، لکڑی کے برتن، روغنی برتن اور لاکھی برتن سے منع فرمایا۔","الألباني: ضعيف",{"u2":"حضرت ھنیدہ بنت شریک بن ابان سے منقول ہے کہ میں سیدہ عائشہ رضی اللہ عنہا کو خریبہ میں ملی۔ میں نے ان سے شراب کی باقی ماندہ میل کچیل (تل چھٹ) کے بارے میں پوچھا تو انھون نے مجھے اس سے بھی منع کیا، نیز فرمایا:شام کو نبیذ بناؤ تو صبح کو پی لیا کرو۔ اور رات کو اس کا منہ باند ھ کر رکھا کرو۔ اور انھوں نے مجھے کدو کے برتن،کھجور کی جڑکے برتن تارکو ل لگے برتن اور روغنی مٹکے سے بھی منع فرمایا۔","f2":"خریبہ بصرہ شہر کا ایک محل ہے جسے بصر ہ صغری (چھو ٹا بصر ی) بھی کہا جاتا تھا۔"}],[5642,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے روغنی برتنوں سے منع فرمایا ہے۔","الألباني: صحيح",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے تارکول لگے ہوئے برتنوں (میں نبیذ بنانے) سےمنع فرمایا ہے۔"}],[5643,"عبداللہ بن عمر اور عبداللہ بن عباس رضی اللہ عنہم کہتے ہیں کہ وہ دونوں رسول اللہ صلی اللہ علیہ وسلم کے پاس موجود تھے، آپ نے کدو کی تو نبی، لاکھی برتن، روغنی برتن اور لکڑی کے برتن سے منع فرمایا، پھر آپ نے یہ آیت تلاوت فرمائی: «وما آتاكم الرسول فخذوه وما نهاكم عنه فانتهوا» \"رسول جو کچھ تمہیں دیں اسے لے لو، اور جس سے تمہیں روکیں، اس سے رک جاؤ\" (الحشر: ۷)۔","الألباني: صحيح دون تلاوة الآية وكأنها مدرجة",{"u2":"حضرت سعید بن جیرسے روایت ہے کہ انھوں نے حضرت ابن عمر اور سیدنا ابن عباس رضی اللہ عنہ سےسنا، ان دونوں نے رسو ل اللہ صلی اللہ علیہ وسلم پر گواہی دی کہ آپ نےکدو کےبرتن، روغنی مٹکے، کھجور کی جڑ کے بر تن اور تارکول لگے ہوئے برتن سے منع فرمایا۔پھر رسول اللہ صلی اللہ علیہ وسلم نے یہ آیت پڑ ھی:’’ رسو ل اللہ جو کچھ تمھیں دیں، وہ لے اور جس چیز سےتمھیں روکین، اس سے رک جاؤ۔،،","f2":"امام نسائی رحمہ اللہ کا مقصود یہ ثابت کرنا ہے کہ ان برتنو ں سے نہی حرمت پر محمول ہے، کراہب پر نہیں۔اور یہ بات مذکورہ آیت سے صاف ثابت ہو رہی ہے مگر اس کا مطلب یہ نہیں کہ خود آپ صلی اللہ علیہ وسلم بھی بعد میں ان برتنوں کے استعمال کی اجازت نہیں دے سکتے جو ہ صحیح ثابت ہے، لہذا محقق بات یہ ہے کہ آپ نےشراب کی تحریم کے ساتھ ان برتنوں کا استعمال حکما رو ک دیا تھا۔بعد میں جب شراب ختم ہوگئی توآپ نے ان برتنوں کے بنانا بہتر نہیں۔ مجبوری ہو تو بنائی جا سکتی ہے مگر نشے سے بچانا ضرور ی ہے۔نبیذ کے علاوہ ان برتنوں کا دیگر استعمال قطعا صحیح ہے اور اس میں کوئی کراہت نہیں۔ اس طریقے سےتمام متعلقہ روایات میں تطبیق ہو جائے گی اور ہر روایت پر عمل ہوجائے گا۔ واللہ اعلم ."}],[5644,"انس (قیسی بصری) کہتے ہیں کہ ابن عباس رضی اللہ عنہما نے کہا: کیا اللہ تعالی نے نہیں فرمایا: «ما آتاكم الرسول فخذوه وما نهاكم عنه فانتهوا»\"جو کچھ تمہیں رسول دے، اسے لے لو اور جس سے تمہیں روکے، اس سے رک جاؤ\" (الحشر: ۷) میں نے کہا: کیوں نہیں۔ انہوں نے کہا: کیا یہ اللہ تعالی نے نہیں فرمایا: «وما كان لمؤمن ولا مؤمنة إذا قضى اللہ ورسوله أمرا أن يكون لهم الخيرة من أمرهم» \"کسی مومن مرد اور کسی مومن عورت کو جب اللہ اور اس کے رسول کسی معاملے میں فیصلہ کر دیں اپنے معاملات میں کوئی حق نہیں رہتا\" (الاحزاب: ۳۶) میں نے کہا: کیوں نہیں، انہوں نے کہا: تو میں گواہی دیتا ہوں کہ اللہ کے نبی اکرم صلی اللہ علیہ وسلم نے لکڑی کے برتن، روغنی برتن، کدو کی تو نبی اور لاکھ برتن سے منع فرمایا ہے۔","الألباني: ضعيف",{"u2":"حضرت اسماء بنت بزید سے روایت ہے کہ ان کے چچا زاد بھائی حضرت انس سے منقول ہے کہ سیدنا ابن عباس رضی اللہ عنہ نے کہا: کیا اللہ تعالی نے (قرآن مجید میں) یہ نہیں فرمایا: ’’او جو کچھ تمھیں اللہ کا رسول دے، وہ لے لو اور جس چیز سےروک دے، اس سے رک جاؤ۔،، میں نےکہا: کیو ں نہیں (بلکہ فرمایاہے۔) پھر انھوں کہا:کیا اللہ تعالی نےیہ نہیں فرمایا: ’’کسی مومن مرد یا مومنہ عورت کو لائق نہیں کہ جب اللہ تعالی اور اس کا رسول فیصلہ فرما دیں تو وہ اپنا اختیار استعمال کرے؟،، میں نے گواہی دیتا ہوں کہ اللہ کے نبی صلی اللہ علیہ وسلم نےکھجور کی جڑ کے برتن، تارکول لگے برتن، کدو کے برتن اور روغنی مٹکے سےمنع فرمایاہے۔"}],[5645,"زاذان کہتے ہیں کہ میں نے عبداللہ بن عمر رضی اللہ عنہما سے درخواست کی کہ مجھ سے کوئی ایسی بات بیان کیجئیے جو آپ نے رسول اللہ صلی اللہ علیہ وسلم سے برتنوں کے سلسلے میں سنی ہو اور اس کی شرح و تفسیر بھی بیان کیجئے تو انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے لاکھی برتن سے روکا اور یہ وہی ہے جسے تم «جرہ»(گھڑا) کہتے ہو۔ «دباء» سے روکا، جسے تم «قرع» (کدو کی تُو نبی) کہتے ہو، «نقیر» سے روکا اور یہ کھجور کے درخت کی جڑ ہے جسے تم کھودتے ہو (اور برتن بنا لیتے ہو) اور «مزفت» جو «مقیر» ۱؎ ہے اس سے بھی روکا۔\n§وضاحت\n۱؎: پینٹ کیا ہوا روغن چڑھایا ہوا برتن۔","الألباني: صحيح",{"u2":"حضرت زادان سےروایت ہے کہ میں نےسیدنا عبد اللہ بن عمر رضی اللہ عنہ سے گذارش کی کہ مجھے کوئی ایسی چیز بیان فرمائے جو آپ نے رسول اللہ صلی اللہ علیہ وسلم سے ان برتنو ں کے بارے میں سنی ہو۔ اس کی وضاحت بھی فرمائے۔ انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے حنتم سے منع فرمایا اور اسے تم مٹکا کہتے ہو۔ اوردباء سے منع فرمایا،جسے تم کدو کا برتن کہتے ہو۔اور نقیر سے منع فرمایا۔ یہ کھجور کی جڑ ہوتی ہے جسے لوگ اندر سے کرید کرید کر برتن بنالیتے ہیں،نیز آپ نے مزفت سے منع فرمایا اور یہ وہ برتن ہوتا ہے جسے تارکول یا لاکھ مل دی گئی ہو۔","f2":"مذکورہ برتنوں کی حثییت کےمتعلق محقق بات تو حدیث:5646 کے تحت ذکر ہو چکی ہےمگر بعض ائمہ مجتہدین،مثلا: امام احمد اور امام اسحاق اس بات کے قائل ہیں جو حضرت ابن عمر اور ابن عباس رضی اللہ عنہ کےمذکورہ بالا فرامین سے ظاہر ہوتی ہے کہ ان برتنوں میں اب بھی نبیذ بنانا حرام ہے اور ان برتنوں میں بنائی ہوئی نبیذ پینی منع ہے۔حضرت ابن عباس اور سیدنا ابن عمر رضی اللہ عنہ کا مسلک بھی یہی معلوم ہوتا ہے مگر اس سے بعض دوسری روایات متروک ہو جائیں گی جو نسخ پر دلالت کرتی ہیں۔ واللہ اعلم ."}],[5646,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے عبدالقیس کے وفد کو جب وہ آپ کے پاس آئے کدو کی تو نبی اور لکڑی کے برتن، روغنی برتن اور منہ کھلے گہرے برتن سے روکا، اور فرمایا: \"مشک میں نبیذ تیار کرو اور اس کا منہ بند کر دو اور اسے میٹھا میٹھا پیو، ان میں سے کسی شخص نے کہا: اللہ کے رسول! مجھے اس جیسے برتن کی اجازت دیجئیے۔ آپ نے فرمایا: تو تمہیں اس جیسا چاہیئے اور آپ اپنے ہاتھ سے اشارہ کرتے ہوئے اس کی شدت اور تیزی بیان کرنے لگے۔","الألباني: صحيح",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ جب قبیلہ عبد القیس کا وفد رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا تو آپ نےان کو کدو کےبرتن،کھجور کی جڑ کےبرتن، تارکول لگے برتن اور کٹے ہوئے منہ والے مشکیزے میں نبیذ بنانے سے روک دیا اور فرمایا:’’ اپنے (معروف) مشکیزے میں نبیذ بناؤ اور اس کا منہ باندھ کر رکھور اور اسے میٹھی میٹھی پیو۔ایک شخص نے کہا: ا ے اللہ کے رسول! مجھے اس جیسی (متغیر) نبیذ پنیے کی بھی اجازت دے دیجیے۔ آپ نےفرمایا: ’’پھر توتو اسے ایسی (نشے والی) بنا لے گا۔،، آپ نے اسے بیان کرنے کے لیے ہاتھ سے اشارہ بھی فرمایا۔","f2":"(1) قبیلہ عبد القیس، بحرین کے رہنے والے تھے جو اس دور میں یمن میں شمار ہوتا تھا۔یمن کے علاقے میں اس وقت نشہ آور مشروب بہت زیادہ استعمال ہوتے تھے، اس لیے آپ نے ان کوخصوصی ہدایات ارشاد فرمائیں۔\n(2) ’’ کٹے ہوئے منہ والے،، کیو نکہ منہ کٹا ہونے کی صورت میں وہ مٹکے جیسا بن جائے گا اور اس کا منہ باند ھا نہیں جا سکے گا، لہذا اس میں نشے کا پنا نہیں چل سکے گا۔ منہ والے مشکیزےکا منہ باندھا جائے تو نبیذ میں نشہ پیدا ہونے کی صورت میں وہ مشکیزہ پھٹ جاتا ہے،لہذا نشے کاپتا چل جاتا ہے، اس لیے آپ نے نبیذ والے مشکیزے کا منہ باند ھنے کاحکم دیا۔\n(3) ’’میٹھا میٹھا پیو،، یعنی اس کے ذائقے میں تبدیلی نہ آئی ہو کیو نکہ تبدیلی کی صورت میں نشے کا امکان ہے۔\n(4) ’’ اجازت دیجیے،، اس شخص نےبھی اشارے میں بات کی اور رسول اللہ صلی اللہ علیہ وسلم نے بھی اشارے سے جواب دیا۔ اس اشارے کا صحیح تعین تو نا ممکن ہےمگر مفہوم وہی ہے جو ترجمے میں بیان کیا گیا کہ اس نے ممنوع یا کم ازکم مشکوک نبیذ پینے کی اجازت مانگی آپ نے نشہ یانشے کے خطرے کی وجہ سے اجازت نہ دی۔واللہ اعلم."}],[5647,"جابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے روغنی گھڑے، کدو کی تو نبی اور لکڑی کے برتن سے منع فرمایا، اور جب نبی اکرم صلی اللہ علیہ وسلم کے پاس مشکیزہ نہ ہوتا جس میں آپ کے لیے نبیذ تیار کی جاتی تو آپ کے لیے پتھر کے برتن میں نبیذ بنائی جاتی۔","الألباني: صحيح",{"u2":"سیدنا جابر رضی اللہ عنہ نےفرمایا کہ رسو ل اللہ صلی اللہ علیہ وسلم نے تارکول لگے ہوئے مٹکے،کدو کےبرتن اور کھجور کی جڑ کےبرتن (میں نبیذ بنانے) سے منع فرمایاہے۔اور جب رسول اللہ صلی اللہ علیہ وسلم کو نبیذ بنانے کے لیے مشکزہ نہ ملتا تو پتھر کے کو نڈے میں آپ کے لیے نبیذ بنائی جاتی تھی۔"}],[5648,"جابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے لیے مشکیزہ میں نبیذ تیار کی جاتی تھی، جب مشکیزہ نہ ہوتا تو پتھر کے برتن میں تیار کی جاتی، اور آپ نے کدو کی تو نبی، لکڑی کے برتن اور روغنی برتن سے روکا۔","الألباني: صحيح",{"u2":"سیدنا جابر رضی اللہ عنہ سے روایت ہے، انھو ں نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم کے لیے چمڑے کے مشکیز ے میں نبیذ بنائی جاتی تھی اور جب مشکیز ہ میسر نہ ہوتا تو پتھر کے کو نڈے میں آپ کے لیے نبیذ بنائی جاتی۔ اور رسول اللہ صلی اللہ علیہ وسلم نے کدو کےبرتن،کھجور کی جڑ کے برتن اور تاکولگے ہوئے مٹکے سے منع فرمایا ہے۔"}],[5649,"جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کدو کی تو نبی، لکڑی کے برتن، گھڑے اور روغنی برتن سے منع فرمایا ہے۔","الألباني: صحيح",{"u2":"سیدنا جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کدو کے برتن،کھجور کی جڑ کے برتن (روغنی)مٹکے اور تارکول لگے ہوئے برتن (میں نبیذ بنانے سے منع فرمایا۔"}],[5650,"عبدااللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے ایسے مٹی کے برتن (گھڑے) کی اجازت دی جس پر روغن نہ لگایا گیا ہو۔","الألباني: صحيح",{"u2":"سیدنا عبد اللہ رضی اللہ عنہ سے منقول ہےکہ نبی اکرم صلی اللہ علیہ وسلم نے ایسے مٹکے میں نبیذ بنانے کی اجازت دی ہے جس کو تارکول (یا روغن)نہ لگا یا گیا ہو۔"}],[5651,"بریدہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میں نے تمہیں قربانی کے گوشت (ذخیرہ کرنے) سے روکا تھا، لیکن اب تم اسے رکھ چھوڑو اور ذخیرہ کرو، اور جو قبروں کی زیارت کرنا چاہے کرے، اس لیے کہ اس سے آخرت کی یاد تازہ ہوتی ہے اور پیو (ہر چیز) البتہ نشہ لانے والی چیز سے بچو۔","الألباني: صحيح",{"u2":"سیدنا بریدۃ رضی اللہ عنہ سے مروی ہےکہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ میں نے تمھیں (تین دن سے زائد) قربانیوں کے گوشت (کھانے)سے منع فرمایا تھا۔اب (تمھیں اجازت ہے) سفر میں ساتھ لے کرجاؤ یا محفوظ کر کے رکھو۔ اسی طرح جو شخص قبروں کی زیارت کو جانا چاہے،وہ جا سکتا ہے کیو نکہ وہ آخرت کی یاد دلاتی ہیں۔ اسی طرح (جس برتن کی نبیذ چاہو)پیو لیکن ہر نشہ آور مشروب سے بچو۔،،"}],[5652,"بریدہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میں نے تمہیں قبروں کی زیارت سے منع کیا تھا، اب تم زیارت کرو، میں نے تین دن سے زیادہ تک قربانی کے گوشت (جمع کرنے) سے منع کیا تھا، لیکن اب جب تک تمہارا جی چاہے رکھ چھوڑو، میں نے تمہیں مشکیزے کے علاوہ (برتنوں) کی نبیذ سے منع کیا تھا، لیکن اب تم تمام قسم کے برتنوں میں پیو البتہ نشہ لانے والی چیز مت پیو\"۔","الألباني: صحيح",{"u2":"سیدنا بریدہ رضی اللہ عنہ سے روایت ہے کہ سول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’میں نے تمھیں قبروں کی زیارت سے روکا تھا۔ اب تم زیارت کو جاسکتے ہو۔ میں نے تمھیں مشکیزوں کے علاوہ جوسرے برتنوں میں نییذ بنا نے سے روکا تھا، اب تم سب برتنوں میں (نبیذ بناکر)پی سکتے ہو لیکن نشہ آور مشروب نہ پنیا۔،،","f2":"یہ حدیث سابقہ حدیث سےزیادہ واضح ہے اور یہ حدیث اس بات میں صریح ہے کہ مذکورہ برتنوں میں نبیذ بنانےسے روکنے کا حکم ابتدا میں دیا گیا تھا، بعد میں یہ حکم منسوخ کر دیا گیا۔ جس طرح زیارت قبور اور قربانی کے گوشت کی پابندی منسوخ ہو چکی ہے اورا س پر سب اہل علم کا اتفاق ہے، اسی طر ح برتنوں کی پابندی بھی منسوخ ہے۔ جمہور اہل علم کا یہی مسلک ہے اور یہی درست ہے۔تفصیل پیچھے گزر چکی ہے۔ دیکھیے، حدیث: 5646، نیز یہ نسخ کی سب سے بہترین صورت ہے کہ خود رسول اللہ صلی اللہ علیہ وسلم نے اپنا سابقہ حکم منسوخ ہونے کی صراحت فرمادی اور نیا حکم جاری کر دیا۔ ایسے نسخ میں کوئی شک نہیں رہتا۔ یہ حدیث سندا بھی اعلی درجے کی صحیح ہے کیو نکہ صحیح مسلم میں مذکور ہے۔"}],[5653,"بریدہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میں نے تمہیں تین چیزوں سے روکا تھا: قبروں کی زیارت سے تو اب تم (قبروں کی زیارت) کرو، اس کی زیارت سے تمہاری بہتری ہو گی، میں نے تمہیں تین دن سے زائد قربانی کے گوشت (ذخیرہ کرنے) سے روکا تھا، لیکن اب تم جب تک چاہو اس میں سے کھاؤ، میں نے تمہیں کچھ برتنوں کے مشروب سے روکا تھا، لیکن اب تم جس برتن میں چاہو پیو اور کوئی نشہ لانے والی چیز نہ پیو\"۔","الألباني: صحيح",{"u2":"سیدنا بریدہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلمنے فرمایا:’’ میں نے تمھیں تین چیزوں سے روکا تھا: قبروں کی زیارت سے۔ اب تم زیارت کیا کرو کیو نکہ امید ہےقبروں کی زیارت تمھاری نیکی میں اضافے کاباعث ہوگی۔ (یا لیکن قبروں کی زیارت سے تمھاری نیکی میں اضافہ ہونا چاہیے -) میں نے تمھیں تین دن سے زائد قربانی کے گوشت (کھانے) سے روکا تھا۔ اب جب تک چاہو کھاؤ۔اور میں نے تمھیں چند برتنوں میں نبیذ وغیرہ بنانے سے روکا تھا، اب تم جس برتن میں چاہو، بناؤ اور پیو لیکن نشہ آور مشروب نہ پیو۔،،","f2":"’’لیکن قبروں کی زیارت، یعنی قبروں کی زیارت کا مقصد صرف تبرک نہیں جیسا کہ عموما ہوتا ہے کہ صالحین کی قبور کی زیارت صرف تبرک کے لیے کی جاتی ہے بلکہ قبروں کی زیارت آخرت کو یاد کرنے، مو ت اور قبر کی طرف متوجہ ہو نے اور اصلاح اعمال کے لیے ہو نی چاہیے۔"}],[5654,"بریدہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میں نے تمہیں (مخصوص) برتنوں کے استعمال سے منع کیا تھا، لیکن اب تمہیں جو بہتر لگے اس میں نبیذ تیار کرو، البتہ ہر نشہ لانے والی چیز سے بچو\"۔","الألباني: صحيح",{"u2":"سیدنا بریدہ رضی اللہ عنہ سےروایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ میں نے تمھیں بعض برتنوں (میں نبیذ بنانے)سے روکا تھا۔ اب جس برتن میں چاہو، نبیذ بناؤ لیکن ہر نشہ آور چیز سے بچو۔،،"}]]);
